body:
[Thm 7 of arXiv:2608.11695, 'Generalised stochastic curvature flow in $d \geq 2$, and sharp interface limit for the sto'] Fix $\alpha\in\left(\frac{1}{3},\frac{1}{2}\right)$. Let $\widehat{\oO} \subset \RR^d$ be an open, connected, bounded domain with smooth boundary, and fix a domain $\widetilde{\oO} \Subset \widehat{\oO}$ with $\partial\widetilde{\oO}\in\cC^{2+2\alpha}$. Let $\dD_2 \subset \RR \times \RR^d$ and $\dD_3 \subset \RR \times \RR^d \times \RR^{d \times d}$ be open sets such that
\begin{equation*}
    \begin{split}
    \dD_2 &\supset \big\{ (\rho^0(x), \nabla \rho^0(x))\;, \; x \in \overline{\widetilde{\oO}} \big\}\;,\\
    \dD_3 &= \dD_2 \times \text{a neighbourhood of} \; \big\{ \nabla^2 \rho^0(x)\;, \; x \in \overline{\widetilde{\oO}} \big\}\;.
    \end{split}
\end{equation*}
Consider the RPDE \eqref{e:RPDE} induced by $\widetilde{\oO}$, where $F_\eps$, $G_\eps$, $H$, $\W^\eps$ and $\rho^0$ satisfy the following conditions.
\begin{enumerate}
\item  $F_\eps$ is uniformly elliptic on $[0,T] \times \widehat{\oO} \times \dD_3$ in the sense that
\begin{equation}
\sum_{i,j=1}^d \partial_{q_{ij}}F_\eps(t,x,u,p,q)\,\eta_i\eta_j \geq \lambda |\eta|^2
\end{equation}
for some $\lambda > 0$ independent of $\eps$, $(t,x,u,p,q)$ in the above region and $\eta \in \RR^d$. 

\item $F_\eps$ is four times differentiable in $(x,u,p,q)$ with norm 
\begin{equation}
    \triplenorm{F_\eps}_{\mathcal F,\mathrm{RPDE}}:=
    \sup_{\substack{x\in\overline{\widehat{\oO}}, (u,p,q)\in \dD_3\\ |\beta|\leq 4}}
\bigl\|D_{(x,u,p,q)}^\beta F_\eps(\cdot\,,x,u,p,q)\bigr\|_{\cC^{\alpha}([0,T])}<+\infty\;.
\end{equation}

\item $G_\eps$ is three times differentiable in $(u,p)$. Furthermore, each derivative $D_{(u,p)}^\beta G_\eps$ with $|\beta|\leq3$ is $\cC^{1+2\alpha}$ in $x$ with norm
\begin{equation}
\triplenorm{G_\eps}_{\mathcal G}:=
\sup_{\substack{(u,p)\in \dD_2\\ |\beta|\leq 3}}
\bigl\|D_{(u,p)}^\beta G_\eps(\cdot\,,u,p)\bigr\|_{\cC^{1+2\alpha}(\overline{\widehat{\oO}})} <+\infty\;.
\end{equation}
\item 
    \(H\in\cC^7_b(\overline{\widehat{\oO}}\times\RR\times\RR^d)\). Moreover, there exists $L_\eps\in\cC_b^3 \bigl(\overline{\widehat{\oO}}\times\dD_2;\RR^{1\times m}\bigr)$ such that 
    \begin{equation} 
        -(D_x G_\eps)(D_p H)^\sft+(D_u G_\eps)\big(H-(D_p H)p\big)^\sft
        +(D_p G_\eps)\big((D_x H)^\sft+p(D_u H)^\sft\big)
        =G_\eps L_\eps
    \end{equation}
    holds for all
    \((x,u,p)\in\overline{\widehat{\oO}}\times\dD_2\).
\item $\rho^0\in \cC^{4+2\alpha}(\overline{\widetilde\oO})$ satisfies the compatibility condition
\begin{equation*}
G_\eps\bigl(x,\rho^0(x),\nabla \rho^0(x)\bigr)=0\;,\quad x\in\partial\widetilde\oO\;,
\end{equation*}
and the uniform non–tangentiality condition: there exists $c>0$ such that
\begin{equation} 
\inf_{x \in \d \widetilde{\oO},\eps\in[0,1]} \Big| \sum_{i=1}^d \d_{p_i} G_\eps \big( x,\rho^0(x),\nabla \rho^0(x) \big) \nu_i(x) \Big| \geq c\;,
\end{equation}
where $\nu(x)$ denotes the unit outward normal on $\partial\widetilde\oO$. 
\end{enumerate}
Then for every $\eps$, there exists $\tau_\eps > 0$ such that there is a unique solution to \eqref{e:RPDE} induced by $\widetilde{\oO}$. 

If furthermore $|\!|\!| F_\eps |\!|\!|$ and $|\!|\!| G_\eps |\!|\!|$  are all uniformly bounded in $\eps$, then one can choose the above existence time $\tau_\eps$ independent of $\eps$. Moreover, for every open set $\oO \Subset \widetilde{\oO}$, there exists $\tau>0$ independent of $\eps$ such that 
\begin{equation*}
    \|\rho_\eps-\rho_0\|_{\cC^{0,2} ([0,\tau]\times\overline{\oO})} \lesssim \triplenorm{F_\eps-F_0}_{\mathcal F,\mathrm{RPDE}} +\triplenorm{G_\eps-G_0}_{\mathcal G} +d_\alpha(\W^\eps,\W)\;.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

