body:
[Lemma sigma-moments of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] Let $k=1,\dots,n$.
	\begin{enumerate}
		\item We have
		\begin{equation*}
			\mathrm{Cov}(\bm{\sigma}^n(k)\,|\,{\mathcal G}^n(k-1)) = \frac{1}{n} I_n - \bm{b}^n(k-1)\bm{b}^n(k-1)^\top.
		\end{equation*}
		In particular, $\mathrm{Cov}(\bm{\sigma}^n(k)\,|\,{\mathcal G}^n(k-1))\leq n^{-1} I_n$ in semidefinite order.
		\item For every $i=1,\dots,n$,
		\begin{equation}
			{\mathbb E}[\sigma_i^n(k)^4\,|\,{\mathcal G}^n(k-1)] \leq \frac{16}{n^2}\int x^4\,\nu(dx).
		\end{equation}
	\end{enumerate}

