[Theorem thm:HW-Qy of arXiv:2603.07132, 'Quadratic form of heavy-tailed self-normalized random vector with applications in $\alpha$'] If $\xi$ is centered and sub-Gaussian, then there exist universal constants $C,c>0$ such that for any $n\in \mathbb{N}$ and $t>0$,
	\begin{equation}
		\mathbb{P}\left(\Big|Q_n(\mathbf{y},\mathbf{A})-\mathbb{E}[Q_n(\mathbf{y},\mathbf{A})]\Big|\geqslant t\right)\leqslant C\exp\left(-c\min\left(\frac{nt^2}{K^4\|\mathbf{A}\|^2},\ \frac{n t}{K^2\|\mathbf{A}\|}\right)\right),
	\end{equation}
	where $K=\|\xi\|_{\psi_2}/\sqrt{\operatorname{Var}(\xi)}$.

[Proposition prop:potential under tens and Ar of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] Let $A\subset \mathbb{R}^m$ and $B\subset \mathbb{R}^n$ be finite subsets and let $\alpha\in\mathbb{R}_{>0}^A$ and $\beta\in \mathbb{R}_{>0}^B$. For all $(x,y)\in \mathbb{R}^m\oplus\mathbb{R}^n$ we have 
  \begin{equation}
    \Phi_{\alpha\otimes \beta}(x,y)=\Phi_\alpha(x)+\Phi_\beta(y).
  \end{equation}
  Moreover, if $n=m$, then for all $x\in\mathbb{R}^m$ we have
  \begin{equation}
    \Phi_{\alpha\odot \beta}(x)=\Phi_\alpha(x)+\Phi_\beta(x).
  \end{equation}

