[Lemma 2 of arXiv:2506.17045, '\LARGE{On bivariate Archimax copulas: Level sets, mass distributions and related results}'] Let $\psi \in \mathbf{\Psi}$, $A \in \mathcal{A}$, $C_{\psi,A} \in \mathcal{C}_{am}$, $t \in (0,1)$, $\fg^t$ be defined as in eq. \eqref{eq:fct_g_t}, $R$ be defined according to eq. \eqref{eq:definition_L_R} and $g^R$ be defined as in eq. \eqref{eq:fct_f}. Then the following assertions hold:
\begin{itemize}
    \item[$(i)$] $L_{\psi,A}^t = \Gamma(\fg^t) \cup (\{t\} \times [\ff^R(t),1])$;
    \item[$(ii)$] $L_{\psi,A}^t =  \Gamma(\fg^t)$ if, and only if $R = 1$.
    \end{itemize}

[Lemma prod-rule of arXiv:2512.10625, 'Bessel and Dunkl processes with drift'] For all functions $f,g\in C^{(2)}(\mathbb R^N)$,
  \begin{align}
    \Delta_k (fg)(x)= f(x) \Delta_kg(x)+ & g(x) \Delta_kf(x)+ 2\langle \nabla f(x), \nabla g(x)\rangle \notag\\&+
    \sum_{\alpha\in R_+}k(\alpha)\|\alpha\|^2 \frac{(f(x)-f(\sigma_\alpha x))(g(x)-g(\sigma_\alpha x))}{\langle\alpha , x\rangle^2}.\notag\end{align}
  Moreover, if $f$ or  $g$ is $W$-invariant, then the reflection parts on the right hand side disappear. (Proof in the paper; no proof environment follows the statement in the TeX.)

