[Lemma 13 of arXiv:2608.11031, 'A Bayesian Proof of the Bernoulli Theorem'] For every finite $T\subset\R^n$,
\[
  \inf_{a:T\to\R^n}
  \left\{
    \max_{x\in T}\norm{a(x)}_1
    +W\bigl(\{x-a(x):x\in T\}\bigr)
  \right\}
  \le
  2\sup_{\mu\in\cP(T)}\delta_T(\mu).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition d:MartP of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Fix a Borel probability measure~$\mu$ on~$M$, with~$\mu\ll\mssm$.
A (time-homogeneous) $\mssm$-special standard process~$\mssW$ as in~(equation eq:MarkovP of the paper) is called a \emph{sub-stationary solution to the martingale problem for~$(\mssL,\msA,\mu)$} if and only if, for every~$f\in\msA$ and every~$t\geq 0$,
\begin{enumerate}[$(a)$]
\item the associated semigroup of transition kernel measures is $2$-sub-stationary w.r.t.~$\mssm$, see~(equation eq:d:MartP:1 of the paper);
\item (\emph{martingale property}) the family
\begin{equation}
M^{\class{f}}_t\eqdef \tilde f(X_t)-\tilde f(X_0)-\int_0^t (\mssL f)(X_s)\mathop{}\!\mathrm{d} s\,\mathrm{,}\;\, \qquad t\geq 0\,\mathrm{,}\;\,
\end{equation}
is an $\msF_\bullet$-martingale under~$P_\mu$ for any $\mssW$-quasi-continuous version~$\tilde{f}$ of~$f$, where~$P_\mu$ is defined as in~(equation eq:MarkovProbab of the paper).
\end{enumerate}

[Prop 8 of arXiv:2606.10074, ''] For $j\ge1$,
  \begin{align} 
    C_{\theta_j}(a) - C_{\theta_j}(b) = \omega_j
    &= Y_{\tau_{j-1}+1}
    =
    \begin{cases}
      1 & \text{if~} (X)^L_{\theta_j}=a \\
      -1 & \text{if~} (X)^L_{\theta_j} = b
    \end{cases}
    \\
    &=-Y_{\tau_j}
    =
    \begin{cases}
      -1 & \text{if~} (X)^L_{\sigma_j}=a \\
      1 & \text{if~} (X)^L_{\sigma_j} = b.
    \end{cases}
  \end{align}
  Furthermore,
  \begin{gather} 
    \theta_j =
    \min\{t>\sigma_{j-1}: C_t(a) \ne C_t(b)\},
    \quad
    \sigma_j = \min\{t>\theta_j: C_t(a) = C_t(b)\},
  \end{gather}
  i.e., $\{\sigma_{j-1}, \ldots, \theta_j-1\}$ is a neutral period and
  $\{\theta_j, \ldots, \sigma_j-1\}$ is a $\kappa(\omega_j)$-period.

[Theorem 103 (Supercritical) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Let $p= \frac{\lambda}{n}$ with $\lambda > 1$. Then for any $\delta > 0$
    \begin{equation*}
        \P \Bigg( \Big| \frac{|\cC_1(p)|}{(1-\eta_\lambda) n } -1 \Big| \geq \delta \Bigg) \rightarrow 0,
    \end{equation*}
    where $\eta_\lambda > 0 $ satisfies $\eta_\lambda = \exp(\lambda(\eta_\lambda - 1))$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 20 of arXiv:2608.27569, 'Laplace and Dolbeault operators on Sasakian manifolds'] The operator $\Delta _{\overline{\partial }}$ maps primitive forms to
primitive forms, so that $\mathcal{H}_{\overline{\partial },P}^{\bullet}=\ker
\left( \Delta _{\overline{\partial }}:\Omega _{P}^{\bullet}\rightarrow \Omega
_{P}^{\bullet}\right) $ and $\mathcal{H}_{\overline{\partial }
,P}^{\bullet}\left( q\right) =\ker \left( \Delta _{\overline{\partial }
}:\Omega _{P}^{\bullet}\left( q\right) \rightarrow \Omega _{P}^{\bullet}\left(
q\right) \right) $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 6 of arXiv:2607.29534, 'Expected signatures via partial integration, coordinate change and symmetrization'] Let $\ell: T((\mathbb{R}^d))\rightarrow T((\mathbb{R}^d))$ be a graded linear map. We define the pairing \begin{equation}

    \langle \alpha,\mathbf{a}\rangle_{\ell}:= \langle \alpha, \ell(\mathbf{a})\rangle = \langle \ell^\ast(\alpha),\mathbf{a}\rangle, \qquad \alpha \in \mathbb{R}\langle \mathcal{A}\rangle, \quad \mathbf{a}\in T((\mathbb{R}^d)). 
\end{equation} If $\ell$ is a graded automorphism, we call the family $(\langle w,\mathbf{a}\rangle_{\ell})_{w\in \mathcal{W}}$ the $\ell$-coordinates of $\mathbf{a}$.

[Lemma lmm:tail-contribution of arXiv:2607.02013, 'Resolution of the Detection Threshold Conjecture for Random Geometric Graphs in the $d>n$ '] Fix $r\ge2$ and $M\ge1$.  With $c_0$ as in
\prettyref{lmm:taylor-derivative}, there exist constants $c,C>0$,
depending only on $r$ and $M$, such that if
$a\geq 1$ and $a^2\delta\le c$,

then
\begin{equation}

\int_{\{U(t)>c_0/\delta\}}
\bigg\{\prod_{i=1}^r |K(t_i)|\bigg\}
\Big\{
L(t)+|L_M(t)|
\Big\}
\nu^{\otimes r}(\mathrm d t)
\le
C\mathop{\rm exp}\{-c/\delta\}.
\end{equation}

[Lemma 4 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Entropy Tensorization (Lemma 4.1, \cite{caputo2022})}


    Let $\nu :=\nu_1 \otimes \dotsm \otimes \nu_n$ be a product probability measure on the product space $\mathcal X^n := (\mathcal X_1 \times \dotsm \times \mathcal X_n)$. Suppose that $X \sim \mathcal \nu$. Then, for all $f : \mathcal X^n \to [0,\infty)$,
    \begin{align*}
        \ent[\nu]{f}
        \leq \sum_{i=1}^n \E[\ent[\nu_i]{f}]
        = \sum_{i=1}^n \E[\ent[\nu(\cdot | X_{-i})]{f}].
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] For $a,b,d\in\R$ and $y\geq 0$ it holds that
\begin{equation*}
\max_{x\in[0,y]} a + bx + d(y-x)^{\frac{3}{2}} =
\begin{cases}
a + by - \frac{4}{27}\frac{b^{3}}{d^{2}}  & \text{if $d<0$, $b<0$ and $y > \frac{4}{9}\frac{b^{2}}{d^{2}}$}\\
a + \max\{b,dy^{\frac{1}{2}}\}y & \text{otherwise}
\end{cases}
.
\end{equation*}

