body:
[Prop SSMestimateFixedk of arXiv:2603.17858, 'Decay of correlations and zeros for the hard-core model'] Let $\lambda^\star>0$. For each $k\in\mathbb{N}$, there exists
    a constant $M_{k}>0$ such that for all $\lambda\in[0,\lambda^\star]$, all induced subgraphs $H$ of $T_{k}$, and
    all $\ell>2k$ we have
    \begin{equation}
        |R_{(H,v),\tau_{1}}(\lambda)-R_{(H,v),\tau_{2}}(\lambda)|<M_{k}c^{\ell}
    \end{equation}
    for all $v\in V(H)$ and all boundary conditions $\tau_{1},\tau_{2}:S_H(v,\ell)\to\{0,1\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 4 of arXiv:2605.23461, 'An almost sure invariance principle for the Takagi--van der Waerden class functions'] Suppose that \eqref{Assump2:A_n_to_infinite} and \eqref{Assump2:last_term} hold. Then, for any $p\in (0, 1)$, we have the following:
  \begin{enumerate}[label={(\roman*)}, ref={\roman*}, align=left, leftmargin=*]










    \descitem{(CLT)} \begin{equation}
    \lim_{n\to\infty} P\biggl(\frac{S_n}{s_n}\le y\biggr) = \int_{-\infty}^{y} \frac{1}{\sqrt{2\pi}} e^{-t^2/2} dt.
  \end{equation}
    \descitem{(the compact LIL)} With probability one, the set of limit points of
  \begin{equation}
    \frac{S_n}{\sqrt{2 s_n^2 \log\log s_n^2}}
  \end{equation}
  coincides with the closed interval $[-1,1]$.
    \descitem{(the other LIL)}
    \begin{equation}
    \liminf_{n\to\infty} \sqrt{\frac{\log\log s_n^2}{s_n^2}}\max_{1\le k\le n} |S_k| = \frac{\pi}{\sqrt{8}} \quad \text{$P$-a.s.}
  \end{equation}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 (Kac, Pleijel) of arXiv:2507.06186, '2507.06186'] If $\partial D$ is sufficiently regular (e.g., smooth), then
\begin{align}

\msf T_0(t)=\tfrac{\msf{A}(D)}{2\pi}t^{-1}
-\tfrac{\msf{L}(\partial D)}{4\sqrt{2\pi}}t^{-1/2}+O(1)\qquad\text{as }t\to0,
\end{align}
where $\msf L(\partial D)$ is the length of the curve
$\partial D$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 30 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] $\{\xi_t\}_{t\ge0}$ is said to be unifromly integrable, if 
      \begin{equation*}
          \lim_{K\to\infty}\sup_{t\ge0}\E(|\xi_t|\chi_{\{|\xi_t|\ge K\}})=0.
      \end{equation*}

[Lemma 111 (Stochastic Fubini and covariance density) of arXiv:2607.10813, '2607.10813'] At finite cutoff, $\partial_t^\nu V_{a,\Lambda}$ is a homogeneous colored second chaos.  Its covariance spectral density is
\begin{equation}
\begin{aligned}
  q_{a,\nu,\Lambda}(t,\xi)
  =c_{\mathrm F}
  \int_{\R^3}\int_0^t\int_0^t
  &|m_\Lambda(\eta)\mathfrak h_{\W}(\eta)|^2
   |m_\Lambda(\xi-\eta)\mathfrak h_{\K}(\xi-\eta)|^2\\
  &\times
  |\mathcal K_{a,\nu}
  (\xi,\eta;t,r_1,r_2)|^2
  \dd r_1\dd r_2\dd\eta,
\end{aligned}
\end{equation}
where $c_{\mathrm F}>0$ depends only on the Fourier normalization.  The formula remains valid with an extra factor $|m_\Lambda(\xi)|^2$ for the auxiliary output projection.

[Thm cor:boundtype2constant_TCS of arXiv:2411.10633, 'A Geometric Perspective on the Injective Norm of Sums of Random Tensors'] Let $r\geq 2$ an integer, $2 \leq p < \infty$, and $\mathcal{C}_{r,p}(d)$ the type-2 constant of the $\ell_p$ injective norm of order $r$ tensors as in (def:type2constant_TCS of the paper). Then\footnote{The notation $f \lesssim_{r,p} g$ means that the inequality $ f \leq C_{r,p} g$ holds for some constant $C_{r,p}$ that only depends on $r$ and $p$ (see (subsec:notation_TCS of the paper)).}
\begin{equation}
d^{\frac12 - \frac1p}\underset{r,p}{\lesssim}  \mathcal{C}_{r,p}(d) 
\underset{r,p}{\lesssim} d^{\frac12- \frac1{\max\{p,2r\}}}\log d.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

