    \begin{equation*}
    \begin{aligned}
        \tau P_t\left[e^{\lambda g}\cdotp\Gamma^{\psi}\left(e^{\lambda g}\right)\right]-\left(\tau+t\right)e^{\lambda\varphi_{\lambda} }\cdotp\Gamma^{\psi}\left(e^{\lambda\varphi_{\lambda} }\right)
        \geq -\psi^{\prime}\left(1\right)t\left[1+K(2\tau+t)\right]\Delta P_t e^{\lambda g}\\
        -\frac{n}{8}\left[\log\left(1+\frac{t}{\tau}\right)+4Kt+4K^{2}\tau t+2K^{2}t^{2}\right] ...","release_manifest_digest":"sha256:9f10dcd67cfe45420d9121471cff8b93a19597a2f7ce0234d1a78931efce29b4","revision_digest":"sha256:5f6dfa94af514cd3625e222679d69103616f0c73a6b4926070cab310f1467451","source_id":"arxiv:2608.30409","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

