[Proposition 24 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. Then
        \begin{align}
                \avg{\Pi_{*,21}\Sg\Pi_{*,12}}_N + & \sqrt{\avg{\Pi_{*,22}^2}_N \avg{\Sg\Pi_{*,11}\Sg\Pi_{*,11}}_N} =1,                  \\
                \avg{\Pi_{*,22}^2}_N                                                                            \sim1, \qquad &\avg{\Sg\Pi_{*,11}\Sg\Pi_{*,11}}_N                                                              \sim1. 
        \end{align}
        Consequently, $1$ and $\la_*$ are the two simple eigenvalues of $\calJ_*$ and
        \begin{align}
                1-\la_* =2\sqrt{\avg{\Pi_{*,22}^2}_N\avg{\Sg\Pi_{*,11}\Sg\Pi_{*,11}}_N} \sim1. 
        \end{align}
        Moreover, the dual basis relations imply the spectral decomposition
        \begin{align}
                I_2 & =\f{r}_*\f{\ell}_*^*+\wh{\f{r}}_*\wh{\f{\ell}}_*^*, \qquad
                \calJ_*  =\f{r}_*\f{\ell}_*^*+\la_*\wh{\f{r}}_*\wh{\f{\ell}}_*^*. 
        \end{align}
        In particular,
        \begin{align}
                \|\f{r}_*\|+\|\wh{\f{r}}_*\|+\|\f{\ell}_*\|+\|\wh{\f{\ell}}_*\|\lesssim1. 
        \end{align}

