[Lemma lm:fibrationsbetweenfibrantobjectscartesian of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Suppose that $\varphi\colon V\to W$ is an equivariant linear isometric embedding of faithful $G$-representations. 
    \begin{enumerate}
    \item If $X\in\cat{$\bm{G}$-$\textbf{\textup{L}}$-Top}_{*}$ is fibrant in the $G$-global model structure, the square 
\[
\begin{tikzcd}
\bm\Omega(X)(V)^G\arrow[d,"\bm\Omega(X)(\varphi)^G"']\arrow[r,"\textbf{\textup{q}}(X)"]& \textbf{\textup{Gr}}(V)^G\arrow[d,"\textbf{\textup{Gr}}(\varphi)^G"] \\ 
\bm\Omega(X)(W)^G\arrow[r,"\textbf{\textup{q}}(X)"']& \textbf{\textup{Gr}}(W)^G
\end{tikzcd}
\] is a homotopy pullback. 
\item Suppose that $X\in \cat{$\bm{G}$-OrthSp}$ is fibrant in the $G$-global model structure. Then the square 
\[
\begin{tikzcd}
\bm\Omega(X)(V)^G\arrow[d,"\bm\Omega(X)(\varphi)^G"']\arrow[r,"\textbf{\textup{Q}}(X)"]& \textbf{\textup{BOP}}(V)^G\arrow[d,"\textbf{\textup{BOP}}(\varphi)^G"] \\ 
\bm\Omega(X)(W)^G\arrow[r,"\textbf{\textup{Q}}(X)"']& \textbf{\textup{BOP}}(W)^G
\end{tikzcd}
\]
 is a homotopy pullback.
\end{enumerate}

[Definition sum_condition of arXiv:2606.17425, 'Order statistics for edge eigenvectors of Wigner matrices'] We call an $N \times N$ symmetric random matrix generalized Wigner if it satisfies \begin{enumerate}
		\item The elements $(h_{ij})_{i \geq j}$ are independent random variables with $\EX[h_{ij}] = 0$. 
		\item The variances of $h_{ij}$ are given by the variance profile matrix $V = (V_{ij})_{1 \leq i, j \leq N}$, where $V_{ij} = \EX[h_{ij}^2]$. We require $V$ to satisfy the normalization condition \begin{equation}
			\sum_{i = 1}^N V_{ij} = 1, \quad 1 \leq j \leq N. 

		\end{equation} Further, we assume there exist two constants $C_{\mathrm{inf}}, C_{\mathrm{sup}} > 0$ independent of $N$ such that \begin{equation}
			C_{\mathrm{inf}} \leq \inf_{i,j} \{N V_{ij}\} \leq \sup_{i,j} \{N V_{ij}\} \leq C_{\mathrm{sup}}.

		\end{equation} 
		\item All moments of $\sqrt{N} h_{ij}$ are uniformly bounded, \emph{i.e., } for any $k \geq 3$ there exists $C_k$ independent of $N$ such that for all $1 \leq i, j \leq N$, \begin{equation}
			\EX[(\sqrt{N} h_{ij})^k] \leq C_k.

		\end{equation}
	\end{enumerate}

