[Lemma 2 of arXiv:2608.29501, 'Disorder Thresholds and Free Energy of Brownian Directed Polymers with\\ Product and Radia'] If
\begin{equation}
  \rho_{T,g}<1,

\end{equation}
then, for every \(m\ge1\),
\begin{equation}
  \E\left[W_{mT}(\beta)^{1/2}\right]
  \le \rho_{T,g}^{\,m}.

\end{equation}
Consequently,
\begin{equation}
  p(\beta)
  \le
  \frac{2\log\rho_{T,g}}{T}
  <0.

\end{equation}

