body:
[Lem polyencodingGOEGSE of arXiv:2412.00593, 'A new approach to strong convergence II.\\The classical ensembles'] For any $h\in \mathcal{P}_q$, there is $\Phi_h\in\mathcal{P}_{qq_0}$
so that
\begin{alignat*}{2}
	&\mathbf{E}[\mathop{\textnormal{tr}} h(X^N)] &&= \Phi_h(\tfrac{1}{N}),\\
	&\mathbf{E}[\mathop{\textnormal{tr}} h(Y^N)] &&= \Phi_h(-\tfrac{1}{2N}).
\end{alignat*}

[Definition 1 of arXiv:2605.15781, 'Mean-Field Backward Stochastic Differential Equations with Nonlinear Resistance and Double'] Let $s\in C[0,T]$,  and $l,r:[0,T] \times \mathbb{R}\rightarrow \mathbb{R}$ be two functions with $l\leq r$.  A pair of functions $(x,K)\in C[0,T]\times BV[0,T]$ is called a solution to the  Skorokhod problem for $s$ with nonlinear constraints $l,r$ ($(x,K)=\mathbb{SP}_l^r(s)$ for short) if 
\begin{itemize}
\item[(i)] $x_t=s_t+K_t$;
\item[(ii)] $l(t,x_t)\leq 0\leq r(t,x_t)$;
\item[(iii)]  $K_{0-}=0$ and $K$ has the decomposition $K=K^r-K^l$, where $K^r,K^l$ are nondecreasing functions satisfying  
\begin{align}
\int_0^{T} I_{\{l(s,x_s)<0\}}dK^l_s=0, \  \int_0^{T} I_{\{r(s,x_s)>0\}}dK^r_s=0.
\end{align}
\end{itemize}

[Conj strip GW formula of arXiv:2609.03152, 'Experiments with membranes, maps and sheaves'] Suppose $X$ is a strip geometry and $(X\times\mathbb{C}^{2},\mathsf{T})$ is equivariantly Calabi--Yau. Then if we denote the tangent $\mathsf{T}$-weights of the affine plane by $\epsilon_4,\epsilon_5$ we have
    \begin{equation*}

    \GWarg{X\times\mathbb{C}^{2}}{\mathsf{T}}{} = \Exp \left(-\sum_{1 \leq m < n \leq N+1} \frac{[\kappa q_{v_m}]}{[q_{v_n}] \, [q_4] \, [q_5]} \prod_{i=m}^{n-1} Q_i \right)
	\end{equation*}
    under the change of variables $q_i = \mathrm{e}^{u \epsilon_i}$. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma 41 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] For any $\delta>0$, $n\ge 1$ and $h_*+\frac{n}{(\log n)^{1+\frac{\varepsilon}{8}}}\le s \le h^*$, we have on the event $(\Xi_n)^{\rm c}\cap \Big\{T^{(r)}_{\lfloor (\log n)^{1+\frac{\varepsilon}{2}} \rfloor}(s) < s^{\downarrow} \Big\}$,
\begin{align}
    X^{(r)}_s - X^{(r)}_{s^{\downarrow}} \ge \frac{2}{(\log n)^{\frac\varepsilon{12}}}\sum_{j=s^{\downarrow}+1}^{s} \widetilde N_j.
\end{align}

