[Proposition thm:AuxApprox of arXiv:2606.01866, 'Phase Transition of a Semiflexible Membrane in Two Dimensions'] Fix $\lambda<0$, $d=2$, and let $G_N$ and $\bar{G}_N$ be as in (equation eq:cl of the paper) and (equation eq:ss of the paper), respectively. For a fixed $\delta\in(0,1)$ and $x,y\in V_N^\delta$, we have
    \begin{equation}
        |\bar{G}_N(x,y)-G^0_N(x,y)|=O(N^\lambda)
    \end{equation}
    and
    \begin{equation}
        |G_N(x,y)-\bar{G}_N(x,y)|=O(N^{\lambda-1})
    \end{equation}
    uniformly. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2607.07309, 'Quantitative limit theorems for generalized P\'olya urns with applications to random tree '] Let $(x_n)$ be a sequence of nonnegative real numbers.
    \begin{itemize}
        \item If $\sum_{i=0}^\infty x_n = \infty$, we say a function $\theta: \mathbb{N} \times \mathbb{R}^+ \to \mathbb{N}$ is a rate of divergence for $\sum_{i=0}^\infty x_n$ if $\sum_{n=k}^{\theta(k,b)}x_n\geq b$ for any $b>0$ and $k \in \mathbb{N}$.

        \item If $\sum_{i=0}^\infty x_n <  \infty$, we say a function $\chi: \mathbb{R}^+ \to \mathbb{N} $ is a rate of convergence for $\sum_{i=0}^\infty x_n$ if $\sum_{n=\chi(\varepsilon)}^{\infty}x_n < \varepsilon$ for any $\varepsilon>0$.
    \end{itemize}

[Lemma 22 of arXiv:2604.26898, '\bf Stochastic Scaling Limits and Synchronization \\by Noise in Deep Transformer Models'] Under the assumptions of Proposition~\ref{prop:euler_maruyama}, for any $0 \leq u \leq t \leq T$ and any particle $i \in \{1, \dots, N\}$,
    \begin{equ}
        \E\left[|X^i_t - X^i_u|^2\right] \leq 2 K_3 (t-u)(1 + t-u).
    \end{equ}

