body:
[Proposition P3.6 of arXiv:2412.09850, 'Averaging principles for time-inhomogeneous multi-scale SDEs via nonautonomous Poisson equ'] Suppose that Assumption {\rm(A1 of the paper)} holds. For any $H:\mathbb{R}\times\mathbb{R}^n\times\mathbb{R}^m\rightarrow \mathbb{R}^n$ satisfying (equation CenCon of the paper) and (equation CenPol of the paper), define
\begin{equation}
\Phi(s,x,y):=\int^{+\infty}_{s}\mathbb{E} H(r,x,Y^{s,x,y}_r)\,dr.
\end{equation}
Then, $\Phi(s,x,y)$ is a solution to the nonautonomous Poisson equation (equation TimePE of the paper). Moreover, there exists a constant $C>0$ such that for $s\in\mathbb{R}$, $x\in \mathbb{R}^n$ and $y\in \mathbb{R}^m$,
\begin{equation}
\begin{split}
&|\Phi(s,x,y)|\leqslant C(1+|x|+|y|)\Lambda(s),\\
& \|\partial_x \Phi(s,x,y)\|+ \|\partial^2_x \Phi(s,x,y)\|\leqslant C(1+|x|+|y|)\Lambda_{\gamma}(s),\\
& \|\partial_y \Phi(s,x,y)\|\leqslant C\Lambda(s),\quad  \|\partial^2_y \Phi(s,x,y)\|\leqslant C\Lambda_{\gamma}(s),
\end{split}
\end{equation}
where $\Lambda_{\gamma}(s)$ is defined in (equation A12 of the paper) and $\Lambda(s)=\Lambda_1(s)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:ucp of arXiv:2411.08846, 'On the Number of Crossings and Bouncings\\ of a Diffusion at a Sticky Threshold'] We say that $(A^{n})_{n\ge1} $
	\emph{converges locally uniformly in time, in probability} 

	to $A^{0}$ if 
	\begin{equation}
		\forall t\ge 0:\;
		\sup_{s\le t} \bigabsbraces{A^{n}_s - A^{0}_s}  \xlongrightarrow[n \rightarrow  \infty]{\Prob}  0.
	\end{equation}
	We denote this convergence with 
	\begin{equation}
		A^{n} \convergence{ {\Prob}\text{-}\mathrm{ucp}} A^{0} .
	\end{equation}

[Lemma lm:PPP.clusters of arXiv:2411.02046, 'Speed of Convergence and Moderate Deviations of FPP on Random Geometric Graphs'] Let $d \geq 2$ and $r>r_c$. Then, there exist $C,c>0$ such that, for each $t>0$,
    \begin{equation*}
    \mu_v\big(v \not\in \Hh , ~\mathlcal{C}(v) \not\subseteq B(v,t)\big) \leq C e^{-c t}.
    \end{equation*}
    Furthermore, there exist $C',c,>0$ and $\beta' >1$ such that, for all $u,v \in \R^d$ and every $t> \beta' \|u-v\|$,
    \begin{equation*}
        \mu_{u,v}\big(\accentset{\rule{.4em}{.5pt}}{D}(u,v) \mathbbm{1}_{u \in\mathlcal{C}(v)}> t\big)  \leq C'e^{-c' t}.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_reg_wasserstein of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Let $1\le p<p^{\prime }$. Suppose that $
		\mu(\omega,dx)$ and $\nu(\omega,dx)$ are random probability measures on~${\ 
			\mathbb{R}}^d$ such that $\left\Vert \mu \right\Vert _{p^{\prime
		}}^{p^{\prime }}+\left\Vert \nu \right\Vert _{p^{\prime }}^{p^{\prime
		}}<\infty$. We assume that there exists an exponent $\mathbf{e}_d>0$ such that 
		\begin{equation} \exists C \in {\mathbb R}_+,\ \forall x \in {\mathbb R}^d, \forall r \in (0,1], \ S_{\mu ,\nu ,1}(\phi_r(x-\cdot)) \le C r^{-\mathbf{e}_d}\overline{W}_{1}^{\mathcal{A}}(\mu ,\nu ).
		\end{equation}		
		Let $\hat{p}=\frac{p(p^{\prime }-p)}{
			(\mathbf{e}_d+p)(p^{\prime }-p)+(d+p)p}$. Then, there exists a constant $C\in {\mathbb{R}}_+$ depending on 
		$p$, $p^{\prime }$ and $d$ such that  
		\begin{equation}
			\mathbb{E}[W_{p}^{p}(\mu ,\nu )]\leq C (1+ \left\Vert \mu \right\Vert
			_{p^{\prime }}^{p^{\prime }}+\left\Vert \nu \right\Vert _{p^{\prime
			}}^{p^{\prime }})^{1-\hat{p}} \overline{W}^{\mathcal{A}}_{1}(\mu ,\nu )^{\hat{p}}.

		\end{equation}
		In particular, for  $ \mathcal{A}=\{\varphi \in  C_{b}^{1}({\mathbb{R}}^{d})\text{ s.t. }\left\Vert \varphi \right\Vert
		_{\infty }\times \left\Vert \nabla \varphi \right\Vert _{\infty }\leq 1 \}$, (equation assump_calA of the paper) holds with $\mathbf{e}_d=d+1/2$.

