[Prop e:accessible of arXiv:2411.03482, 'Ergodicity of 2D singular stochastic Navier--Stokes equations'] For every $u_0, u_1\in \mathcal{C}^{-\kappa}_{\div}$ and $\delta > 0$, we have 
	\begin{equ}

		\mathbb{P}\left(\|\Psi\big(u_0, X, \mathbf{P} \div(\Wick{X^{\otimes 2}})\big)[1]-u_1\| < 2\delta \right) > 0\;.
	\end{equ}

[Lem rigorous-w123 of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] For $W_1, W_2$ from (equation w123 of the paper) we have $W_1,W_2 \in \tilde{\mathcal{D}}^{ext}_+(\mathcal{M})$ and with $x = (rv, z)$:
    \begin{equation}
    \begin{aligned}
        \mathcal{L} W_1(r,v,z) &= -\|x\|_{\beta+1/2,2}^2 +\ip{x}{F(x)}_\beta + \frac{1}{2}\|G(x)\|_{\beta,2}^2 \\
        \Gamma W_1(r,v,z) &= \|G(x)^*x\|_\mathcal{U}^2 \,,
    \end{aligned}
\end{equation}
where the adjoint of $G(x)$ is taken in $\mathcal{L}(\mathcal{U},\mathcal{B}_{\beta,2})$. Moreover, 
\begin{equation}
    \begin{aligned}
        \mathcal{L} W_2(r,v,z) &= \ip{x}{\tilde e} + \ip{F(x)}{1} \\
        \Gamma W_2(r,v,z) &= \|G(x)^*1\|_\mathcal{U}^2 \,,
    \end{aligned}
\end{equation}
where the adjoint of $G(x)$ is taken in $\mathcal{L}(\mathcal{U},L^2)$ and $\tilde{e}$ is as in (def:tilde-e of the paper).

[Lemma lem:tikhonov_contraction of arXiv:2609.01697, 'Unique ergodicity of projective cocycles over the 2D stochastic Navier--Stokes equations'] For any $\delta \in (0,1]$, $K,R, T > 0$, $p \geqslant 1$, and $N \in \mathbf{N}$, there exists $\beta = \beta(\delta, p, N, K, R, T) > 0$ such that for all $z_0 \in \mathcal{C}_R$ and $\eta \in T_{z_0} \mathcal{X}$ with $\|\eta\| \leqslant 1$ we have:
  \begin{equation}
    \mathbb{E}\left[ \| P_N \beta(\beta I + M_T )^{-1}  J_{0,T} \eta\|^p \cdot \mathbf{1}_{E_K} \right] \leqslant \delta^p .
  \end{equation}

