[Corollary cor:lbm-finite-energy-simple-response of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let $x\in\Omega_{\rm LBM}$, let $\Lambda_n^x$ be a simple eigenvalue
of $A_x$, and choose a real $L^2(M_x)$-normalized eigenfunction $\phi_n^x$.
The response measure $\eta_n^x$ in
(equation eq:lbm-spectral-response-measure of the paper) belongs to $\mathcal M_{\rm fe}(D)$ and satisfies
\begin{equation}
 I_D(\eta_n^x)
 \le \gamma^2(\Lambda_n^x)^4M_x(D)^{1/2}
       K_G(x)^{3/2}<\infty.

\end{equation}
The simple-eigenvalue response functional extends continuously to $H$ as
\begin{equation}
 f\longmapsto
 -\gamma\Lambda_n^x\int_D\widetilde f(\phi_n^x)^2\,dM_x
 =\inner{U_D\eta_n^x}{f}_{H},
 \qquad f\inH.

\end{equation}

[Lemma fchangemetric of arXiv:2608.09856, '\bf Mass erasure on measured $\bbR$-trees,\\ applications to L\'evy forests'] Let $a,b\! \in \!  (0, \infty]$ and let $g\colon[0, a) \! \to \! [0, b)$ be an increasing homeomorphism. We fix a rooted $\mathbb{R}$-tree $(T,d,\rho)$ such that $\mathtt{Ht}_{d, \rho} (T) \! \leq \!  a$.  We set $T^o\! \! :=\! B^o_{T,d} (\rho, a)\! = \!  \{ \sigma \! \in \!  T: d(\rho, \sigma) \! < \!  a \}$ and  
\begin{equation}

\forall \sigma, \sigma' \! \in \!  T^o, \quad d_g(\sigma, \sigma')\! = \!  g \big( d(\rho, \sigma) \big)+ g \big( d(\rho, \sigma') \big) \! - \! 2g \big(d(\rho, \sigma \! \wedge \! \sigma') \big).
\end{equation}
Then $(T^o\! , d_g)$ is an $\mathbb{R}$-tree and the identity function on $T^o$ is a $(d,d_g)$-homeomorphism. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 2 (Theorem 4.1, \cite{LP17}) of arXiv:2605.31568, 'Lipschitz continuity of the time constant for continuum percolation'] \emph{[Palm theory for Poisson processes.]}
For all non-negative bounded and measurable functions $f$ we have \begin{align*}
\E\left[\sum_{x_1,x_2,...,x_k \in X_\lam} f(x_1,x_2,...,x_k,X_\lam) \right] &= \lam^k \int_{\R^d} \E\left[f(x_1,...,x_k,X_\lam \cup \{x_1,...,x_k\}) \right]\,dx \ \\
&= \lam^k \int_{\R^d} \E^{\lam}_{x_1,...,x_k}\left[f(x_1,...,x_k,X_\lam) \right]\,dx. 
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2609.02426, 'Deformations of the $\osp(n|2)$-action on the superspace\\ of symbols of differential oper'] Let $1\leq k\leq m$ and put $a^k_1=\Delta_1A_k$, $a^k_2=\Delta_2A_k$. Then, as cochains on
$\osp(n|2)$,
\begin{equation}

a^k_2=h_k,\qquad a^k_1=-\bigl(h_k+\widetilde{h}_k\bigr),
\end{equation}
i.e.\ for every $F$ such that $X_F\in\osp(n|2)$,
\begin{equation}

h_k(X_F)=(-1)^{n|F|}F'A_k,\qquad
h_k(X_F)+\widetilde{h}_k(X_F)=A_k\circ(F'\cdot).
\end{equation}
In particular $a^k_1$ and $a^k_2$ are $1$-cocycles whose classes form a basis of
$\Hd^1(\osp(n|2),\Dc^n_{\lambda_k,\mu_k})\simeq\R^2$, and
\begin{equation}

\delta^{\sigma,\tau}A_k=\sigma a^k_1+\tau a^k_2 .
\end{equation}

[Definition def:fn of arXiv:2510.13572, 'Coalescence in Markov chains'] \mbox{\hfill}
Let $f \in \mathcal F_S$ where $S=\{1,2,\dots,n\}$. We write $f=(j_1j_2\ldots j_n)$ if
$f(r)=j_r$ for $r=1,2,\dots,n$.\hfill $\blacktriangleleft$

[Proposition lem:approx-exact of arXiv:2608.23554, 'Provably adaptive sampling with uniform and remasking \\ discrete diffusion models'] Fix \(k \in \{0, \ldots, N - 1\}\) in the time discretization \(0 = t_0 < t_1 < \ldots < t_N < T\). Consider the uniform or remasking process and recall~\(\cF(t, b)\) from~(eq:def-ftb of the paper). Letting \(u = T - t_{k+1}\) and \(\ell = T - t_k\), we have

    \begin{equation*}
    \begin{aligned}
        &\cL_{\mathrm{approx}}^{(k)} = \sum_{i\in[d]} \sum_{b\in\cV}\int_u^{\ell} \bE_{x_{\ell}^{-i}} \Biggl[ \Pr(X_t^i = b \mid x_{\ell}^{-i}) \log \frac{\Pr(X_t^i = b \mid x_{\ell}^{-i})}{\widehat \Pr(X_t^i = b \mid x_{\ell}^{-i})} \\
        &\qquad \qquad \qquad \qquad \qquad \qquad + \cF(t, b)\left(\frac{\Pr(X_t^i = b \mid x_{\ell}^{-i})}{\widehat \Pr(X_t^i = b \mid x_{\ell}^{-i})} - 1 - \log \frac{\Pr(X_t^i = b \mid x_{\ell}^{-i})}{\widehat \Pr(X_t^i = b \mid x_{\ell}^{-i})} \right) \Biggr]\mathrm{d} t.
    \end{aligned}
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:stat.dist.alpha>0.beta=lambda0 of arXiv:2607.10708, 'A class of Markov processes with resetting and applications to cybersecurity'] \addcontentsline{toc}{subsection}{Theorem \thetheorem\ {case \texorpdfstring{$\beta=\lambda_o$}{Theorem β=λₒ}} and \texorpdfstring{$\alpha>0$}{α>0}}
    Let $X=(N,\Lambda,C)$  be a self-exciting PDMP with resetting and $Y=(N,\Lambda)$.  Under Assumption (a:finitereset of the paper) and with $\alpha>0\ \&\ \beta={\lambda^o}$,


    the invariant measure $\Pi$ for $Y$ is given by the following:


\begin{equation} 
    \begin{split}
      \Pi(0,\{{\lambda^o}\}) &= K_0/{\lambda^o}\\
      \Pi(n, d\lambda)&=\pi(n,\lambda)d\lambda, \quad n\geq 1, \lambda \in ({\lambda^o}, A),
                \end{split}

\end{equation}
    where the density is given by 

\begin{equation} 
    \begin{split}
      \pi(1,\lambda)&= {\frac{K_0}{\alpha}\int\mathds{1}_{\{\lambda<y+{\lambda^o}<A\}} \frac{F({\lambda^o} + y)}{yF(\lambda)} \,dG_{\ell}(1, y)}, \mbox{ and} \\
      \pi(n,\lambda)&=
      \frac{1}{\alpha}\int_{\lambda-{\lambda^o}}^{A-{\lambda^o}} \frac{F({\lambda^o} + y)}{yF(\lambda)} p(n-1,{\lambda^o} + y) \, dy, \; \mbox{ for } n\geq 2
          \end{split}

\end{equation}
    with $F(\lambda)$ defined in~(equation e:F.lambda of the paper), and for $n\ge2$,

\begin{equation} 
      p(n-1,\lambda) = \int\mathds{1}_{\{u + {\lambda^o}< \lambda\}} (\lambda-u) \pi(n-1,\lambda-u) \,dG_{\ell}(n, u).

\end{equation}
    The constant $K_0$ is equal to 

\begin{equation} 
    K_0=\sum_{n=1}^\infty \int_{[{\lambda^o},A)} \lambda \bar{G}_{\ell}(n, (A-\lambda) \textrm{-}) \Pi(n-1, d \lambda) \ .

\end{equation}

[Prop 4 of arXiv:2608.27022, 'On LCK Geometry of Gauduchon Connections'] Let $(M,J,\omega)$ be a compact lcK manifold. If for two distinct parameters $t,s\in\mathbb R$,
    \begin{equation*}
        \Ric^{t,2}=\Ric^{s,2},
    \end{equation*}
    then $\omega$ is K\"ahler.

