body:
[Lemma 10 of arXiv:2604.15191, 'Quantitative Stability of Many-Marginal Schr\"odinger Bridge'] By choosing $\phi_{\rm lb}(x) \coloneqq \varepsilon\log U_K(x)$ and $\psi_{\rm lb}(x) \coloneqq\varepsilon\log V_K(x)$ defined in~\eqref{eqn: proxy_Schro_sys}, we have
\begin{subequations}
\begin{align}
\int_{\mb T^d}\phi_{\rm lb}\,\dd\rho_0 + \int_{\mb T^d}\m T_{\rho_0}^\varepsilon[\phi_{\rm lb}]\,\dd\rho_\varepsilon &\geq \varepsilon\int_{\mb T^d}\log U_K\,\dd\rho_0 + \varepsilon\int_{\mb T^d}\log V_K\,\dd\rho_\varepsilon + C\varepsilon^{K+2},\\
\int_{\mb T^d}\m T_{\rho_\varepsilon}^\varepsilon[\psi_{\rm lb}]\,\dd\rho_0 + \int_{\mb T^d}\psi_{\rm lb}\,\dd\rho_\varepsilon &\geq \varepsilon\int_{\mb T^d}\log U_K\,\dd\rho_0 + \varepsilon\int_{\mb T^d}\log V_K\,\dd\rho_\varepsilon + C\varepsilon^{K+2}
\end{align}
\end{subequations}
for some constant $C>0$ depending only on the elements in the set $\m RS_{\rm lb}^{(K)}(0, \varepsilon)$. Here, given $t\in[0, 1-\varepsilon]$, we define $\m RS_{\rm lb}^{(K)}(t, t+\varepsilon)$ as the set containing the elements
\begin{align}
\begin{cases}
\|u_{t,0}\|_{\m C^0}, \cdots \|u_{t,K}\|_{\m C^0}, \|u_{t,0}\|_{H^{2K+2}}, \cdots, \|u_{t,K}\|_{H^{2K+2}},\\
\|v_{t,0}\|_{\m C^0}, \cdots \|v_{t,K}\|_{\m C^0}, \|v_{t,0}\|_{H^{2K+2}}, \cdots, \|v_{t,K}\|_{H^{2K+2}},\\
L_\rho,\,\, \sup\big\{\|\rho_s^{(k)}\|_{\m C^{2k'}}: t\leq s\leq t+\varepsilon, \,\, k,k'\in\mb N,\,\,k+k'\leq K+1\big\},
\end{cases}
\end{align}
where $u_{t, k}$ and $v_{t,k}$ are defined by Equation~\eqref{eqn: uvtk}.

