[Lemma lem: grid lemma for circulant of arXiv:2509.04349, 'Precise asymptotics for the norm of large random rectangular Toeplitz matrices'] For any $\tau \in (0, 3/4)$, there exist positive integers $T = T(\tau)$, $k = k(\tau)$, and vectors $\mathbf{u}^{(1)}, \dots, \mathbf{u}^{(T)}$ from the interior of the unit ball in $\mathbb{C}^k$ such that, for any $t \in \{1, \dots, T\}$ and all $p/n \in (\tau_{t-1}, \tau_t]$,
\begin{equation}
    \frac{\|\Pi_{p/n}^{[k]}\operatorname{diag}\{\mathbf{u}^{(t)}\}\|}{\sqrt{p/n}} > 1 - \tau/2.
\end{equation}
Moreover, for all $p/n \in [\log^{-\alpha} n, \tau]$ and all sufficiently large $n$, we have
\begin{equation}
    \frac{\|\Pi_{p/n}^{[2L_n+1]}\operatorname{diag}\{\mathbf{u}^{(0)}\}\|}{\sqrt{p/n}} > 1 - 3\tau/4,
\end{equation}
where $L_n := \lceil \log n \rceil$ and $\mathbf{u}^{(0)} = (0, \dots, 0,\, 1 - \tau/15,\, 0, \dots, 0)^\top$ with $L_n$ zeros on each side of the entry $1 - \tau/15$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 (Quotient asymptotics) of arXiv:2608.30551, 'Critical Discrete Hardy Inequalities in $L^p$'] Let \(\sigma\in(0,1/2)\), \(\alpha\in(\sigma,1/2)\), and
\(a\in(0,1]\). Define \(\gamma\) by
\[
    1-2\gamma=a(1-2\alpha).
\]
Then \(\gamma\in(\sigma,1/2)\), and, as \(|x|\to\infty\),
\[
    \frac{\Delta^\sigma k_{-\alpha}^{a}(x)}
         {k_{-\alpha}^{a}(x)}
    =
    \frac{\mathcal A_{\gamma-\sigma}}{\mathcal A_\gamma}
    \frac{1}{|x|^{2\sigma}}
    +
    O\left(
        \frac{1}
        {|x|^{2\sigma+1-\max\{2\sigma,1-2\gamma\}}}
    \right).
\]

[Lemma 13 of arXiv:2608.01081, 'The Optimal Rate in the Averaged Random-Marginal Central Limit Theorem for Log-Concave Mea'] For all $n\ge6$,
\begin{equation}
 W_1(\Law(\eta_n),\gamma_1)\le\frac Cn.
\end{equation}

[Theorem 1 (CLT of cavity field) of arXiv:2608.10515, 'Limiting Law of Local Fields for the Mean Field Ghatak-Sherrington Model'] Let $\beta_0$ be as above and $k\in\N$. Suppose that $U$ is an infinitely differentiable function on $\R$ whose derivatives of all orders are of moderate growth. Then for $\beta\le \beta_0$ and $D,h\in\R$, we have
\begin{equation}
  \E\left(\langle U(\ell)\rangle-\int_{\R}U(x)\varphi_{r,p-q}(x)d x\right)^{2k}\le \frac{C}{N^k},
\end{equation}
where $C$ is a constant depending on $k,U,S,D,h$, and the high-temperature bound only. The second subscript in $\varphi_{u,v}$ is the variance, as in the convention above. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 (Finite-cascade endpoint expansion) of arXiv:2607.18032, 'FRSB in the SK spin glass: convergence to full-interval support at zero temperature'] Every function obtained from $\log\cosh$ by finitely many operations in Proposition~\ref{prop:zt-finite-KJ} is even, smooth, strictly convex, and satisfies $-1<f'<1$. All its positive-order derivatives are bounded. Moreover, as $x\to+\infty$,
\begin{equation}
 f(x)=x+d_0+d_1e^{-2x}+d_2e^{-4x}+d_3e^{-6x}
 +O(e^{-8x})\quad\text{and}\quad d_1>0,

\end{equation}
with the corresponding differentiated remainder bounds.

Fix such a function $f$, a parameter $a>0$, and $R<\infty$. Define
\begin{equation*}
 u(r,x):=\mathcal T_{a,r}f(x),\qquad \mathsf B(r,x):=u_x(r,x)
 \quad\text{and}\quad \mathsf C(r,x):=u_{xx}(r,x),
 \qquad \forall (r,x)\in[0,R]\times\R.
\end{equation*}
For every $(r,B)\in[0,R]\times(-1,1)$, define $x(r,B)$ and $\mathsf c(r,B)$ by
\begin{equation*}
 \mathsf B(r,x(r,B)):=B\quad\text{and}\quad \mathsf c(r,B):=\mathsf C(r,x(r,B)).
\end{equation*}
With $\delta:=1-B$, there are smooth functions $c_2,c_3$ such that
\begin{equation}
 \mathsf c(r,B)=2\delta+c_2(r)\delta^2+c_3(r)\delta^3
 +O_R(\delta^4).

\end{equation}
The remainder in \eqref{eq:app-slope-endpoint-expansion} may be differentiated once in $r$ and three times in $B$, with
\begin{equation}
 \partial_r^i\partial_B^jO_R(\delta^4)
 =O_R(\delta^{4-j}),
 \qquad i\in\{0,1\},\quad 0\leq j\leq3.

\end{equation}
The expansion at $B=-1$ follows by evenness.

