[Corollary 12 of arXiv:2512.02322, 'Ursell functions in lattice gauge theory'] Under the same assumptions as in Lemma \ref{lem:factorizationUn}, it holds that
    \begin{equation*}
    V_n^-(W_\gamma)= \sum_{\substack{\mathfrak{P} \in \mathfrak{F}_n  \\ |\mathfrak{P}| ~ \text{even}}} b_\mathfrak{P} = - \sum_{\substack{\mathfrak{P} \in \mathfrak{F}_n  \\ |\mathfrak{P}| ~ \text{even}}} (\mathfrak{P}-1)! \myexp\Big(-2 \sum_{I \subset [n]} (c_{I,\mathfrak{P}} - \mathbbm{1}\{|I| ~ \text{odd}\}) \Psi_\beta[I] \Big).
    \end{equation*}

[Lemma 27 of arXiv:2608.26619, 'Uniqueness of Positively Curved Ancient Ricci Flows on Surfaces with Boundary'] If $v:\old\times(-\infty,0)\rightarrow\bR$ satisfies \eqref{eq_symmetry_v} with $v(\cdot,t)\xrightarrow{C^\infty(\mathbb{D})} 0$ as $t\rightarrow -\infty$, then there exists $S<0$ and $a,b>0$ such that for all $t\leq S$ we have
\begin{equation}
\|v(\cdot,t)\|_{C^2(\old)}\leq a e^{bt}.
\end{equation}

[Lemma lemma2.1 of arXiv:2609.02607, 'Spatial inhomogeneity for a three-dimensional doubly degenerate nutrient system with indir'] Let $\Omega \subset \mathbb R^3$ be a bounded domain with smooth boundary, $\ell\geq 0$, and assume that (equation 1.2 of the paper) holds.  Then for each $\varepsilon\in(0,1)$, there exists
$T_{max,\varepsilon}\in(0,\infty]$ and functions
\begin{equation*}
\left\{
\begin{aligned}
&u_{\varepsilon }\in C^0(\overline{\Omega}\times [0,T_{max,\varepsilon}))\cap C^{2,1}(\overline{\Omega}\times(0,T_{max,\varepsilon})), \\
&v_{\varepsilon }\in  \textstyle\bigcap_{q>3} C^0([0,T_{max,\varepsilon});W^{1,q}(\Omega))\cap C^{2,1}(\overline{\Omega}\times(0,T_{max,\varepsilon})),\\
&w_{\varepsilon }\in  C^0(\overline{\Omega}\times[0,T_{max,\varepsilon}))\cap C^{2,1}(\overline{\Omega}\times(0,T_{max,\varepsilon})) \\
\end{aligned}
\right.
\end{equation*}
such that $u_ \varepsilon >0$, $v_ \varepsilon >0$ and $w_{\varepsilon}>0$ in $\overline{\Omega} \times [0,T_{max,\varepsilon})$, that $(u_{\varepsilon
},v_{\varepsilon },w_{\varepsilon })$ solves (equation 2.5 of the paper) classically in $\Omega\times(0,T_{max,\varepsilon})$, and that
  \begin{equation} 
   \hbox{if}~~  T_{max,\varepsilon}<\infty, ~~ \mbox{then}~~
   \limsup_{t\nearrow T_{max,\varepsilon}}\|u_\varepsilon(\cdot , t)\|_{L^{\infty}(\Omega)}=\infty.
\end{equation}
Furthermore, this solution satisfies
\begin{align}
    \|v_{\varepsilon}(\cdot , t)\|_{L^{\infty}(\Omega)}\leq \|v_{0 }\|_{L^{\infty}(\Omega)}\qquad \mbox{for all}~~ t\in(0,T_{max,\varepsilon}),
\end{align}
\begin{align}
    \int_{\Omega}u_{0}\leq \int_{\Omega}u_{\varepsilon}(\cdot,t)\leq m:=\int_\Omega u_0+\ell\int_\Omega v_0\qquad \mbox{for
    all}~~ t\in(0,T_{max,\varepsilon})
\end{align}
and
\begin{align}
    \int_{\Omega}w_{\varepsilon}(\cdot,t)\leq\max\bigg\{m,\int_\Omega w_0\bigg\}\qquad \mbox{for
    all}~~ t\in(0,T_{max,\varepsilon})
\end{align}
as well as
\begin{align}
    \int_{0}^{T_{max,\varepsilon}}\int_{\Omega}w_{\varepsilon }v_{\varepsilon }\leq \int_{\Omega}v_{0}.
\end{align}

[Definition of arXiv:2608.29147, 'The crossing matrix and the Burau matrix of pure braids'] Let $A=[a_{ij}]$ be an $m \times m$ symmetric matrix with zero diagonal. 
\begin{itemize}
\item[(1)] The following diagonal matrix $D_A \in M_m(\mathbb{Z})$ is called the {\it degree matrix of $A$}. 
\begin{align*}
D_A= 
\begin{bmatrix}
\sum_{j\neq 1}a_{1 j}  \\
 & \sum_{j\neq 2}a_{2 j}          &        & \text{\Huge{0}}   \\
 &                 & \ddots                     \\
  & \text{\Huge{0}} &        & \ddots            \\
&                 &        &           & \sum_{j\neq m}a_{m j}
\end{bmatrix}
\end{align*}
\item[(2)] The matrix $L_A=D_A-A \in M_m(\mathbb{Z})$ is called the {\it Laplacian of $A$}. 
\end{itemize}

