[Deff 2 of arXiv:2511.22156, ''] Let $F_0=[0,1]^2$ be the unit square. For $i=1,2,\cdots,8$, define similarities $\Phi_i:\mathbb{R}^2\to \mathbb{R}^2$ as
\begin{align*}
&\Phi_1(x)=\frac{1}{3}x,\ \Phi_2(x)=\frac{1}{3}x+(\frac{1}{3},0),\ \Phi_3(x)=\frac{1}{3}x+(\frac{2}{3},0),\ \Phi_4(x)=\frac{1}{3}x+(\frac{2}{3},\frac{1}{3}),\\ &\Phi_5(x)=\frac{1}{3}x+(\frac{2}{3},\frac{2}{3}),\ \Phi_6(x)=\frac{1}{3}x+(\frac{1}{3},\frac{2}{3}),\ \Phi_7(x)=\frac{1}{3}x+(0,\frac{2}{3}),\ \Phi_8(x)=\frac{1}{3}x+(0,\frac{1}{3}).
\end{align*}

Let $F_n=\bigcup_{i=1}^8\Phi_i(F_{n-1})$ for $n\geq 1$, and let $F=\bigcap_n F_n$. We call $F$ the \textit{Sierpi\'nski carpet} (SC for abbreviation),  and call $\tilde{F}:=\bigcup_{n=0}^{\infty}3^n F$ the \textit{unbounded Sierpi\'nski carpet} (unbounded SC for abbreviation). Let $\tilde{F}_0=\bigcup_{m=0}^{\infty}3^mF_m$ be the \textit{pre-carpet}. For $n\geq 1$, denote $\tilde{F}_n=3^{-n}\tilde{F}_0$.

[Conjecture conj:quenched formula of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Define
		\begin{equation}
			\tilde{\Lambda}(\theta)=\theta\inf_{\zeta:\zeta([0,\sup(\mathrm{supp} \zeta)))=\theta}\mathcal{P}\mathrm{arisi}(\zeta).
		\end{equation}
		Then there exists an open subset $D\subset\mathbb{R}$ such that for every $f\in D$,
		\begin{equation}
			\lim_{\varepsilon\to 0}\lim_{N\to\infty}
			\frac{1}{N}\mathbb{E}\bigl[\log\mathcal{N}_\varepsilon(f)\bigr]=-\tilde{\Lambda}^*(f)=\inf_\theta \bigl(\tilde{\Lambda}(\theta)-\theta f\bigr).
		\end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Theorem 4 (Nonlinear parametric regression) of arXiv:2608.24426, 'Sequential operator learning under dependent data'] For each $\iteridx\in\N$, assume that (i) $\loss_\iteridx(\cdot,\observation_\iteridx)$ is twice Fr\'echet differentiable and $\alpha$-strongly convex, (ii) $R_\iteridx$ is Fr\'echet differentiable and $\regfactor_\iteridx$-strongly convex, with $\regfactor_\iteridx\geq\regfactor_0>0$, and (iii) $\vnoise_\iteridx:=\nabla_1\loss_\iteridx(\obsop_\iteridx^\adj(\mdlop_\star),\observation_\iteridx)$ is conditionally $\vncov_\iteridx$-sub-Gaussian, with $\norm{\vncov_\iteridx}_\opnorm\leq\sigma_\vnoise^2$. Suppose that $\mdlop_\star=\mdlop(\cdot,\parameter_\star)$, for some $\parameter_\star\in\paramspace$, and that $\widehat{\parameter}_\iteridx$ is a global solution of \eqref{eq:nonlinear-parametric-estimator}. Then, for every $\delta\in(0,1]$, with probability at least $1-\delta$, simultaneously for every $\iteridx\in\N$,
\begin{equation}
    \begin{split}
        \norm{\mdlop(\pch,\widehat{\parameter}_\iteridx)-\mdlop_\star}_{\operator{H}_\iteridx}
        \leq
        2\norm{
            \nabla R_\iteridx(\mdlop_\star)
        }_{\operator{H}_\iteridx^{-1}}
        +
        \frac{2\sigma_\vnoise}{\sqrt{\alpha}}
        \sqrt{
            2\log\paren*{
                \frac{
                    \det\paren{
                        \idop+\regfactor_0^{-1}\alpha\obsops\obsops^\adj
                    }^\half
                }{\delta}
            }
        }
    \end{split}

\end{equation}
where $\operator{H}_\iteridx:=\regfactor_\iteridx\idop+\alpha\sum_{i=1}^\iteridx\obsop_i\obsop_i^\adj$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2607.28992, 'Minimal inversion of a permuton sample'] Let $\mu$ be a corner-balanced permuton.
    Using the notations from Section~\ref{sec:notation}, for any $0<\epsilon\leq1/2$, there exists $0<\rho<1$ and $\delta>0$ such that
    \begin{align*}
        \P*{\frac{1}{n}\minv_n\Big(\big([0,\epsilon]\times[0,\rho]\cup[1-\epsilon,1]\times[\rho,1]\big)^c\Big)\geq\delta}
        \longrightarrow1\,.
    \end{align*}

