[Theorem thm:main of arXiv:2606.28575, 'Global smooth solutions by high mode Lie-Transport noise for Logarithmically Hyperdissipat'] Let $p\in ( 4, \infty)$, $\varepsilon\in(0,1)$, $M\ge 1$ and $T>0$. Then there exists $\nu >0$, $n\ge 1$ and $(\theta_k)_{k\in I}$ satisfying (hyp_noise of the paper) and independent of time such that for all initial data 
\begin{align*}
    \omega_0 \in B^{{-\frac{2}{p}}}_{g,2,p}, \qquad \|\omega_0\|_{B^{{-\frac{2}{p}}}_{g,2,p}} \le M
\end{align*}
there exists a unique maximal $L^p$ solution $(\omega, \tau)$ of equation (equation main_ito of the paper) such that 
\begin{align*}
    \mathbb{P}(\tau \ge T) \ge 1-\varepsilon.
\end{align*}
Moreover for all $\theta, \theta_1\in [0,\frac{1}{2})$ and $ \theta_2\in \mathbb{N}$,
\begin{align*}
\omega &\in H^{\theta, p}_{{\rm loc}}([0, \tau); H^{-2\theta}_g)
\quad a.s. \\ 
\omega &\in C([0, \tau); B^{{-\frac{2}{p}}}_{g,2,p}) \quad a.s.\\
\omega &\in C^{\theta_1, \theta_2}_{{\rm loc}} ((0, \tau)\times \mathbb{T}^3) \quad a.s.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 40 of arXiv:2608.17509, '2608.17509'] For every \(a>1\), \(\Phi_a(0)=0\), \(\Phi_a'(0)=0\), and
\begin{equation}

\Phi_a''(0)
=
\frac{1}{\pi^2}\log\frac{(a+1)^2}{4a}
-
\frac{a-1}{2\pi^2(a+1)}\log a.
\end{equation}

[Propo 13 of arXiv:2605.11264, 'Uniform sampling of multitype continuous-time Bienaym\'e-Galton-Watson trees'] Fix $k\geq 2$. 
Then we have 
\begin{equation}
    \begin{split}
    \Q^{(k),\bm \theta}_{T,r}&\left(\tau_1\in {\rm d}t,\mathcal{P}_{\tau_1}=\bo{P},\bo{L}_{\tau_1}=\bm{\ell} , c(\varsigma^{(1)}_{t-})=i\right)\\
        & =\alpha_{i}\E_i\left[\bo L^{\floor{\bo g}}\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{L^{(m)}-g_m}\right] \frac{p_{i}(\bm \ell)\bm \ell^{\floor{\bo g}}\prod_{m=1}^d \E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{\ell_m-g_m}}{\E_i\left[\bo L^{\floor{\bo g}}\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{L^{(m)}-g_m}\right]}\\
&\hspace{1.2cm} \times \E_r\left[ Z^{(i)}_{t}\prod_{m=1}^d\E_m\left[e^{-\bm \theta \cdot \bo Z_{T-t}}\right]^{Z^{(m)}_{t}-\delta_{i,m}}\right]\frac{\prod_{m=1}^d\prod_{q=1}^{g_m} \E_m\left[N^{\floor{a_{m,q}}}_{T-t}e^{-\bm \theta \cdot \bo Z_{T-t}}\right]}{\E_r\left[N^{\floor{k}}_{T}e^{-\bm \theta\cdot \bo Z_{T}}\right]}{\rm d} t.
    \end{split}
\end{equation}

