[Lemma finitepoments of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Consider a subset $\mathcal V$ such that
    \begin{align}
        \{p|_S\text{  for some polynomial }p:\mathbb R^d\to \mathbb R\}\subseteq \mathcal V\subseteq \mathcal O(S)
    \end{align}
    and let $X=(X_t)_{t\in [0,T]}$ be an $S$-valued $\mathcal{V}$-holomorphic process. Then $\int_{\mathbb R^d}\|\xi\|^k \ K(x,d\xi)<\infty$ for all  for all $k\geq 2$ and $x\in S$, and the characteristics $(b,a,K)$ of $X$ satisfy
 \begin{align}
        &b_i(\cdot)\in \mathcal{O}(S), \quad \text{for all }i\in\{1,\dots,d\},\\
        &a_{ij}(\cdot)+\int_{\mathbb R^d}\xi_i\xi_j K(\cdot,d\xi)\in\mathcal{O}(S), \quad \text{for all }i,j\in\{1,\dots,d\}^2,\nonumber \\
        &\int_{\mathbb R^d}\xi^\beta  K(\cdot,d\xi)\in\mathcal{O}(S), \quad  \text{for all }\beta\in \mathbb{N}^d_0,\ |\beta|\geq3. \nonumber 
    \end{align}

[Theorem 92 (Critical trace-clock weak-Schatten estimate) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Under \eqref{eq:clock-assumption}, for every finite $p\ge1$,
\begin{equation}
  \bigl\|\|A^M_{s,t}\|_{\Sch_{1,\infty}}\bigr\|_{L^p}
  \le C_pR(s,t).
\end{equation}
The constant is dimension free.

[Lem 18 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d \geq 2$.  
	There exists $C>0$ such that the following holds. For every $G$ subgraph of $\mathbb Z^d$, every $\beta\geq \beta_c/2$, every $x\in V(G)$ and $zw\in E(G)$, 
\begin{equation}
	\frac{1}{C}\langle \sigma_x \sigma_w \rangle_{G, \beta} \leq \langle \sigma_x \sigma_z \rangle_{G, \beta} \leq  C \langle \sigma_x \sigma_w \rangle_{G, \beta}.
\end{equation}
Similarly, for any $\mathsf{h}\in (\mathbb{R}^+)^V$ and $zw \in E(G)$,
	\begin{equation}
		\langle \sigma_z \rangle_{G, \beta, \mathsf{h}} \leq C \langle \sigma_w \rangle_{G, \beta, \mathsf{h}}
	\end{equation}

