[Theorem analogue of theorem 3.10 of arXiv:2411.09614, 'Moment estimates for the stochastic heat equation on Cartan-Hadamard manifolds'] Let $M$ be a Cartan-Hadamard Manifold satisfying $\sec_M\leq -K_1<0$. A mild solution to the Cauchy problem of PAM driven by noise $W_\alpha$ exists and is unique if the initial condition $u_0\in L^\infty(M)\cap L^r(M)$, $1\leq r\leq +\infty$ and $\alpha>\frac{n-2}{4}$. Moreover, with the convention $\frac{1}{+\infty}=0$, its second moment satisfies 
    \begin{equation}
        \limsup_{t\to+\infty}\frac{\ln\mathbb{E}[u(t,x)^2]}{t}\leq \Theta_{\alpha}(\beta)-\frac{(n-1)^2}{\max(2,r)}K_1,
    \end{equation}

where $\Theta_{\alpha}(\beta)$ is a non-negative and (not strictly) increasing function satisfying the following properties.
\begin{enumerate}
    \item Define $$i=i(\alpha):=\begin{cases}
        1& \frac{n-2}{4}<\alpha<\frac{n}{4},\\
        2& \alpha=\frac{n}{4},\\
        3& \alpha>\frac{n}{4}.
    \end{cases}$$ Let $F_i:\mathbb{R}_+\to \mathbb{R}_+$ for $i\in\set{1,2,3}$ be the functions defined in Lemma (Analogue of lemma 3.9 of the paper). Then, for $\beta<\frac{1}{\sqrt{CF_i(0)}}$,  $\Theta_{\alpha}\equiv0$. Here $C>0$ is the constant taken from Lemma (Analogue of lemma 3.9 of the paper).
    \item The following asymptotic relations hold: \begin{enumerate}[label=(\roman*)]
        \item if $\alpha\in \left(\frac{n-2}{4},\frac{n}{4}\right)$, $\Theta_{\alpha}(\beta)\sim_{\beta\to\infty}(C\beta^2)^{1-2\alpha+\frac{n}{2}}$,
        \item if $\alpha=\frac{n}{4}$, then $\Theta_{\alpha}(\beta)\sim_{\beta\to+\infty}\frac{C\beta^2}{\ln([C\beta]^2)^2}$,\\
        \item if $\alpha>\frac{n}{4}$, then $\Theta_{\alpha}(\beta)\sim_{\beta\to+\infty}C\beta^2$.
    \end{enumerate}
\end{enumerate}

[Lemma lem:It_asymp-3 of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d \ge 1$, $\varepsilon \in (0,1] $, and denote
$\zeta_0 = \zeta \wedge \frac {d \wedge 2}2$.
For any $t \ge \varepsilon^{-1} \vee \varepsilon^{-(2+\zeta_0)/\zeta_0}$ and any $x\in {\mathbb Z^d}$, we have
\begin{equation}  
\bigabs{ I_{t}(x) - \hat g(0) \rho_t(x; \eta, \Lambda) }
\le C_1 \biggl[ e^{-c/\varepsilon}
	+ \frac{1}{  (\sqrt \varepsilon )^{d+4} (\sqrt{ \varepsilon t})^{\zeta_0}} \biggr]
	\frac 1 {(\sqrt t)^d}
	\biggl( \frac{ \sqrt t } { \abs{ x - \integer{t \eta} } } \biggr)^n
	\qquad (n = 0,1,2)
\end{equation}
(here $n=0$ means the factor is absent),
with $c = \frac 1 4 K_{\mathrm{IR}} $ and $C_1$ depending only on $n, d, \zeta, M, K_{\mathrm{IR}}$.

