[Definition def:bracket of arXiv:2601.10359, 'An Operator It\^o Formula for Volterra Gaussian Processes:\\ The Intrinsic Bracket via Cau'] Let $Y = (Y_t)_{t\in[0,T]}$ be such that $Y_t\in\Dom(D)$ for a.e.\ $t$ and $t\mapsto \Pi DY_t$ lies in $L^2([0,T]\times\Omega;\mathcal{H})$. Define the \emph{energy function}
\begin{equation}
\Gamma^Y(t) := \left\|\Pi DY_t\right\|_\mathcal{H}^2
\end{equation}
and the \emph{intrinsic bracket}
\begin{equation}
\langle Y\rangle^{(D,\Pi)}_t := \Gamma^Y(t) = \left\|\Pi DY_t\right\|_\mathcal{H}^2.
\end{equation}
For centered Gaussian processes, $\Gamma^Y(t) = \mathbb{E}[Y_t^2]$.

[Lemma 4 of arXiv:2608.06011, 'Strong averaging principle for multiscale time-inhomogeneous SDEs with multiplicative $\al'] For any $y,z\in\br^d$ and $p\in(1,\alpha)$, let $D$ be a $d\times d$ matrix. Define
    \begin{align*}
        H(y,z,D)=(\theta+|y+Dz|^2)^\frac{p}{2}-(\theta+|y|^2)^\frac{p}{2}-\langle p(\theta+|y|^2)^{\frac{p}{2}-1}y, Dz\rangle,
    \end{align*}
    where $\theta$ is a fixed positive constant. Then the following estimate holds:
    \begin{equation}
        H(y,z,D)\leq \int_0^1\int_0^1\frac{pu_1\langle Dz,Dz\rangle}{(\theta+|y+u_2u_1Dz|^2)^{1-\frac{p}{2}}}\d u_2\d u_1.
    \end{equation}

