body:
[Theorem 3 of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] Let $X = (X_t)_{t\in T}$ be a centered stationary Gaussian process, $\Delta = 1$.
	For a fixed $r \ge 4$ and any $\beta > 0$,
	\begin{align*}
	\sup_{\mu \in \eP(T)}\eF_\beta(P_X;\mu) \asymp \sup_{\mu \in \eP(T)}\eG_\beta(P_X;\mu) 
	\asymp \sum_{k \ge 1} r^{-k } \sqrt{\eta(n_k, \beta  r^{-k})} 
	\end{align*}
	where $n_k=\sN(B(r^{-k+1}),{r^{-k}})$ and $B(r^{-k})$ is a $r^{-k}$-ball at any center. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2606.21394, 'McKean-Vlasov Equations for Large Networks of Neurons with Adaptive Asymmetric Edges'] The means and variances constitute the following family of Ordinary Differential Equations (with mean-field coupling): for every $\theta,\eta\in\mathcal{E}$
\begin{align}
\frac{d}{dt} m_s(t,\theta,\eta)  =& Q_{\theta \eta} m_s(\theta,\eta,t)  +  M_{\theta \eta}m_u(\theta,t)  \\ 
\frac{d}{dt}m_u(\theta,t) =&   Lm_u(\theta,t)  + R_{\theta}(t)  \\
\frac{d}{dt} V_{ss}(t,\theta,\eta) =& Q_{\theta \eta} V_{\theta\eta}(t) + V_{\theta\eta}(t) Q_{\theta \eta}^T + \tilde{\gamma}_{\theta\eta} \tilde{\gamma}^T_{\theta\eta} \\
\frac{d}{dt} V_{us}(t,\theta,\eta)  =& L V_{us}(t,\theta,\eta) + V_{us}(t,\theta,\eta) Q_{\theta \eta}^T +  V_{uu}(t,\theta) Q_{\theta \eta}^T \\
\frac{d}{dt}  V_{uu}(t,\theta)=& L V_{uu}(t,\theta)+ V_{uu}(t,\theta) L^T +  \tilde{\sigma}_{\theta} \tilde{\sigma}_{\theta}^T
\end{align}
Here
\begin{multline}
R_{\theta}\big(m_s, m_u , V_{ss} , V_{us} , V_{uu} \big) = \\ \int_{\mathcal{E}} \int_{\mathbb{R}^{c+d}}  \mathcal{K}(\theta,y)  F(s,y) \rho \big( m_s , m_u , V_{ss}, V_{us} , V_{uu} , s,y \big) ds dy d\mu_{\mathcal{E}}(\eta) 
\end{multline}
and $\rho_{\theta\eta,t}(J,y)$ is the Gaussian density for an $\mathbb{R}^{c+d}$-valued Gaussian variable, with mean vector 
\[
\left(\begin{array}{c}
 m_s(t,\theta,\eta)\\
m_u(t,\theta) 
\end{array}\right) \in \mathbb{R}^{c+d}
\]
and covariance matrix
\begin{equation}
\left(\begin{array}{c c}
V_{ss}(t,\theta,\eta)  &V_{su}(t,\theta,\eta ) \\
V_{us}(t,\theta,\eta ) &V_{uu}(t,\theta)
\end{array}\right) \in \mathbb{R}^{(c+d) \times (c+d)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma3.200 of arXiv:2507.05417, 'Invertibility for non-Hermitian and symmetric random band matrices with sublinear bandwidt'] For a vector $v\in\mathbb{F}_p^m$ and $J\subset[m]$, we denote by $v_J\in\mathbb{F}_p^{|J|}$ the restriction of $v$ onto the coordinates of $J$, and denote by $v_J^*$ the vector in $\mathbb{F}_p^m$ whose $i$-th coordinate is $v_i\cdot\mathbf{1}(i\in J)$. Consider a random vector $w\in\{-2,0,2\}^{n-1}$ with independent coordinates $(w_i)_{1\leq i\leq n-1}$ satisfying 
\begin{equation}
\begin{cases}   
\mathbb{P}(w_i=2)=\mathbb{P}(w_i=-2)=\frac{1}{4},\quad \mathbb{P}(w_i=0)=\frac{1}{2},\quad \forall i\leq d_n\text{ or } i\geq n-d_n,\\
w_i=0\quad\forall d_n+1\leq i\leq n-d_n-1.
\end{cases}\end{equation} 
     Then, for any non-trivial partition $I,J$ with $I\cup J=[n-1]$, we have
     $$
\mathbb{P}(\operatorname{rk}(S_n)=\operatorname{rk}(S_n^{(i)})=n-1)\leq 2\cdot\mathbb{E}[\max_{a\in\mathbb{F}_p}\mathbb{P}(z_I\cdot w_I=a\mid S_n^{(i)})^{1/4}
\mathbf{1}[\operatorname{rk}(S_n^{(i)})=n-1]
],$$
where the expectation is over $S_n^{(i)}$ and $z:=(S_n^{(i)})^{-1}\cdot w_J^*$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:explicit.value of arXiv:2604.22453, 'Adapted Wasserstein Barycenters of Gaussian Processes'] For every $t\in[T]$,
\begin{equation}

\min_{\mathbf P_t\in\mathscr{P}_+(K,d)}\Phi_t(\mathbf P_t)
=
\min_{\Sigma\in\mathscr S_+(Td)}
\sum_{k=1}^K\lambda_k\,\mathrm{dist}_{\mathrm{BW}}^2(A_t^k,\Sigma),
\end{equation}
and the map $\mathbf P_t\mapsto\mathbf L_{\cdot,t}\Lambda \mathbf P_t\Lambda\mathbf L_{\cdot,t}^\intercal$ sends the minimizers of the left-hand side onto the minimizers of the right-hand side; in particular, the right-hand minimum is attained.  Every minimizer $\overline\Sigma_t$ satisfies the trace identity
\begin{equation}

\tr(\overline\Sigma_t)
=
\sum_{k=1}^K\lambda_k
\tr\Bigl(\bigl(\overline\Sigma_t^{1/2}A_t^k\overline\Sigma_t^{1/2}\bigr)^{1/2}\Bigr),
\end{equation}
so that
\begin{equation}

\min_{\mathbf P_t\in\mathscr{P}_+(K,d)}\Phi_t(\mathbf P_t)
=
\sum_{k=1}^K\lambda_k\|L_{\cdot,t}^k\|_F^2-\tr(\overline\Sigma_t).
\end{equation}
Consequently, with general means $a^1, \ldots, a^K$ the unrestricted value (equation eq:unrestricted.value of the paper) takes the explicit form
\begin{equation}

\inf_{\mathbb{Y}\in\mathrm{FP}_2}\sum_{k=1}^K\lambda_k\mathcal{AW}_2^2(\mathbb{X}^k,\mathbb{Y})
=
\sum_{k=1}^K\lambda_k\|a^k-\overline a\|_2^2
+
\sum_{k=1}^K\lambda_k\|L^k\|_F^2
-
\sum_{t=1}^T\tr(\overline\Sigma_t).
\end{equation}

