[Proposition 12 (Long-time bounds for the propagated test functionals) of arXiv:2605.03057, 'Uniform-in-time quantitative fluctuations of large scale interacting particle systems'] Assume Assumption~\ref{ass:coeff-level-new}, and let $ \varphi \in C_b^7\left( \R^d \right) $.
Then, there exists a constant $C > 0$ such that the following hold.
\begin{enumerate}
\item[(i)] For $\ell \in \left\{ 1,2 \right\}$, $ \sup_{t \ge 0}
\norm{P_t\Phi_{\ell}}_{M^5\big( \Ptwo \big)}
\le C$.

\item[(ii)] For $\ell \in \left\{ 1,2 \right\}$ and every $t \ge 0$,
  $\sup_{x,y \in \R^d,\, \mu \in \Ptwo}
\abs{\partial_{\mu\mu}^2 P_t\Phi_{\ell}\left( \mu \right)\left( x,y \right)}
\le C e^{-\omega t}$.

\item[(iii)] For $\ell \in \left\{ 1,2 \right\}$ and every $t \ge 0$,
  $ \norm{\Gamma P_t \Phi_\ell}_{M^5\big( \Ptwo \big)}
\le C e^{-\omega t}$.
\end{enumerate}

[Lemma lem:second-bound of arXiv:2511.01058, 'Limit profiles and cutoff for the Burnside process on Sylow double cosets'] For \(p \ge 11\) and \(k \le a < 2k\),
        \begin{equation}
            f(a;k) \le \frac{1}{p^{2k-2}}((k-1)p)!k^2(p-1).
        \end{equation}

[Proposition 1 of arXiv:2609.01850, 'A comparison theorem for relative regular holonomic $\shd$-modules'] Let $F$ be an object of $\rD^\rb_{\Rc}(\pOS)$. Then, the support of $F$ satisfies: 
\begin{equation}
\supp F=\bigcup\limits_{i\in I}X_i\times S_i
\end{equation}
for some compact subanalytic contractible subsets $X_i$ of $X$ and some closed analytic subsets $S_i$ of $S$, and, locally on $X$, the set $I$ is finite.
Moreover, the sets $S_i$ are independent of the family $(X_i)_{i\in I}$.

[Lem 7 (Local entropy bounds for $(\mathbb{RP}^{d-1},\delta)$) of arXiv:2608.13374, 'Nearly Sharp Comparison Results for sliced and max-sliced Wasserstein distances'] For $0 < \epsilon < 1$, there exists an $\epsilon$-packing of $\R\prob^{d-1}$ of size $m$ with respect to the metric $\delta$
\begin{equation}
    \cU_\epsilon = \sbrac{[u_1],\dots, [u_m]} \subseteq \R\prob^{d-1}
\end{equation}
such that for two universal constants $c, C > 0$,
\begin{equation}
    \brac{\frac{c}{\epsilon}}^{(d-1)} \leq m \leq \brac{\frac{C}{\epsilon}}^{(d-1)}.
\end{equation}
Additionally, for some universal $\tilde{c} > 0$, for each $v\in \R\prob^{d-1}$ and $R \geq \epsilon$,
\begin{equation}
    |\sbrac{j \in [m]: \delta([u_j], [v])\leq R}| \leq \brac{\frac{\tilde{c} R}{\epsilon}}^{(d-1)}.
\end{equation}

[Prop 12 of arXiv:2605.27713, 'Lower path regularity in all dimensions'] Suppose that $X=(X_t)_{t\in[0,T]}$ satisfies Assumption \ref{a1} (i). Let $0\leq \alpha < d$ and $0\leq \beta \leq 1$ be such that 
		\eqref{eq:key-restriction} holds and let $n$ be an even integer. Then for every $0 \leq u < v\leq T$ and $x,h \in \rd$ we have
		\begin{equation}
			\E \lvert L^{\alpha,X}(x,[u,v])\rvert^n \leq c_9^n n^{H\left(\theta+d-\alpha\right)n}(v-u)^{\left(1-H\left(d-\alpha\right)\right)n}[\log(e+(v-u))]^{2nd\zeta}
		\end{equation}
		and
		\begin{multline}
			\E [L^{\alpha,X}(x+h,[u,v])-L^{\alpha,X}(x,[u,v])]^{n}\\
			\leq \|h\|^{\beta n}   c_9^n n^{H\left(\theta+d-\alpha+\beta\right)n}(v-u)^{\left(1-H\left(d-\alpha+\beta\right)\right)n}[\log(e+(v-u))]^{2nd\zeta}
		\end{multline}
		with a constant $c_9>0$ depending only on $T$, $d$, $H$, $\alpha$ and $\beta$ and where $\zeta=1$ if $\beta<\alpha$ while $\zeta=0$ if $\beta\geq \alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm indepentryapplication of arXiv:2411.10633, 'A Geometric Perspective on the Injective Norm of Sums of Random Tensors'] Let $T \in (\mathbb R^d)^{\otimes r}$ be a symmetric Gaussian tensor with $\mathbb E[T] =0$, such that the entries $T_{i_1, \ldots, i_r}$ are independent for $i_1 \leq i_2 \leq \ldots \leq i_r$. Define the variance tensor $A\in (\mathbb R^d)^{\otimes r}$ as $A_{i_1, \ldots,i_r} \coloneqq \mathbb E[T_{i_1, \ldots,i_r}^2]$ and let $\mathbf{1} \in \mathbb R^d$ denotes the vector with all-$1$ coordinates. Then we have
    $$ d^{ rac1p - rac12} \mathbb E \left\lVertTightVert_{\mathcal{I}_p} \underset{r,p}{\lesssim} (\log d) \,  
orminx{A \mathbf{1}}{p/2}^{ rac12}   +  \max_{2 \leq q \leq r} 
orminx{A \mathbf{1}^{\otimes q}}{p/2} ^{ rac{1}{2q}} 
orminx{A }{p/2} ^{ rac{q-1}{2q}}. $$ (Proof in the paper; no proof environment follows the statement in the TeX.)

