[Proposition 4 (Total-variation estimate on the fixed domain) of arXiv:2609.00501, 'Uniqueness of Finite-Time Varifold Limits for the M\"obius-Invariant Willmore Flow'] Assume \eqref{eq:un}.  For every $0<s<t<T$,
\begin{equation}

 \lVert\mu_t-\mu_s\rVert_{\TV}
 \leq
 \frac{2\sqrt{W_0}}{c_0}
 \sqrt{(t-s)\bigl(W(s)-W(t)\bigr)}.
\end{equation}
In particular, for every Borel set $B\subset\Sigma$,
\begin{equation}

 \lvert\mu_t(B)-\mu_s(B)\rvert
 \leq
 \frac{2\sqrt{W_0}}{c_0}
 \sqrt{(t-s)\bigl(W(s)-W(t)\bigr)}.
\end{equation}
If $W_0\leq8\pi$, the constant $2\sqrt{W_0}/c_0$ in
\eqref{eq:fixed-tv}--\eqref{eq:borel-tv} may be replaced by
$\sqrt{32\pi}/c_0$.

[Theorem 6 (\cite{fEhRjS2019}*{Theorem 3.45 and Remark 3.55}) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $d= 1$, $N = 0$, and 
	consider the quasilinear wave equation \eqref{E:JANQNLW} with the following metric:
		\begin{align}
			\hfour & := \begin{pmatrix}
				-(1+(\p_{x^1}\Phi)^2) & \p_t\Phi \p_{x^1} \Phi \\ 
				\p_t\Phi \p_{x^1} \Phi & 1 - (\p_t \Phi)^2
				\end{pmatrix}. 
		\end{align}
	There exists smooth initial data on $\{t=0\}$ and two MGHDs $(\mathcal{M}_1,\Phi_1)$ and $(\mathcal{M}_2,\Phi_2)$ of the same data such that there exists a $p \in \mathcal{M}_1\cap \mathcal{M}_2$ with $\Phi_1(p) \neq \Phi_2(p)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 27 of arXiv:2606.31455, 'Discrete time-multidimensional renewal theory and applications'] For $a,b:I_N\to\mathbb{C}$, their circular convolution $a*_N b:I_N\to\mathbb{C}$ is

\begin{equation*}
(a*_N b)(k)
:= \sum_{\ell\in I_N} a(\ell)\, b\big((k-\ell)\bmod N\big),
\qquad k\in I_N.
\end{equation*}

[Lem 21 of arXiv:2604.25725, 'What is The Probability That A Random Graph With A Given Degree Sequence is Connected?'] For any $m$ large enough, $0<\gamma<1$, $0<\epsilon<10^{-6}$, $n_1<\eps m$, $n_2 \le 10^{-6}m$, $0<C \le m^{\gamma /20}$,  $i \ge 1$, and $0\leq r\le C(\log m)^2$, the following holds: if $2|E(H_{i-1})|+X_{i-1} \le \epsilon m$ then, conditioned on $H_{i-1}$,
\begin{multline*}
    \p{\left|\left\{i \le t \le  i+ r-1:K_t=d_t(v_t)>0\right\}\right|>\frac{ r}{2} \text{ and }\forall i \le t\le i+ r-1:X_{t-1}  \le 2C}\\
    \le 14^{- r}.
\end{multline*}

