[Lemma I of arXiv:2504.14457, 'Abstract'] If $m=0$, we have
	$$I_{\mathbf{0}}(t;\mathbf{t},\mathbf{x}) = \prod_{k=1}^{n} w(t_k,x_k).$$
	If $m > 0$, we have
	\begin{align*}
	I_{\mathbf{m}}(t;\mathbf{t},\mathbf{x}) 
	& = \sum_{\underset{m_a m_b > 0}{(a,b) \in \mathcal{P}_n}} \int_{0}^{t} ds \int_{\mathbb{R}^d} dy_1 \int_{\mathbb{R}^d} dy_2 \, s^{2H-1} p_{t_a-s}(x_a-y_1) f(y_1-y_2) p_{t_b-s}(x_b - y_2) \\
	& \qquad \qquad \times I_{\mathbf{m}'(a,b)}(s;\phi_{a,b}(\mathbf{t},s),\psi_{a,b}(\mathbf{x},y_1,y_2)),
	\end{align*}
	where
	\begin{itemize}
		\item $m'(a,b)_a = m_a -1$, $m'(a,b)_b = m_b - 1$, and $m'(a,b)_k = m_k$ for $k \neq a,b$;
		\item $\phi_{a,b}(\mathbf{t},s)_a = \phi_{a,b}(\mathbf{t},s)_b = s$, and $\phi_{a,b}(\mathbf{t},s)_k = t_k$ for $k \neq a,b$;
		\item $\psi_{a,b}(\mathbf{x},y_1,y_2)_a = y_1$, $\psi_{a,b}(\mathbf{x},y_1,y_2)_b = y_2$, and $\psi_{a,b}(\mathbf{x},y_1,y_2)_k = x_k$ for $k \neq a,b$.
	\end{itemize}

[Lem thinning of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] For each $n \geq 1$, let ${\rm Y}_n$ be a random subset of ${\rm D}_n$ which is $L_{t^A_n}({\rm D}_n)$-measurable. Given $u \geq 0$, define the sets ${\rm Z}_n(u):={\rm W}_n(u) \cap {\rm Y}_n$, ${\rm X}_n(u+1):={\rm S}_n(u+1) \cap {\rm Y}_n$ and 
	\begin{equation}
		\mathbb{Z}_n(u):=\{ z \in \mathbb{X}_{n-r_n} : {\rm Z}_n(u) \cap {\rm Q}(z;n-r_n) \neq \emptyset\}.
	\end{equation} Then, there exist constants $C,c > 0$ (which depend only on $u$) such that, if $n$ is sufficiently large, for each $s > 0$ we have
	\begin{equation}
		\mathbb{P}\left(|\mathbb{Z}_n(u)|>s \sqrt{n}\right) \leq C(1+s^{-1})\mathbb{P}(|{\rm X}_n(u+1)|>cs). 
	\end{equation}

