body:
[Thm th1.1 of arXiv:2510.10898, 'A central limit theorem for unbalanced step-reinforced random walks'] ([A2025]) Let $\xi_1, \xi_2, \cdots$ are i.i.d. random variables with finite second moment. Define
\begin{eqnarray*}
a:=(2r-1)p, \qquad \mu:=\frac{1-r}{1-a}\mathbb{E}(\xi_1), \qquad \sigma^2:=\mathbb{E}(\xi_1^2)-\mu^2.
\end{eqnarray*}
Then the following limit theorems hold:
\begin{enumerate}
\item[(i)] Subcritical regime ($a<1/2$):  
\begin{eqnarray} 
\frac{T_n-n\mu}{\sqrt{n}} \stackrel{d}{\longrightarrow} N(0, \sigma^2/(1-2a)); 
\end{eqnarray} 

\item[(ii)] Critical regime ($a=1/2$):
\begin{eqnarray*}
\frac{T_n-n\mu}{\sqrt{n \log n}} \stackrel{d}{\longrightarrow} N(0, \sigma^2);
\end{eqnarray*}

\item[(iii)]Supercritical regime ($a>1/2$):
\begin{eqnarray*}
\frac{T_n-n\mu}{n^{a}}  \longrightarrow  L~~\mbox{a.s.},
\end{eqnarray*}
where $L$ is non-gaussian square-integrable random variable.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

