[Theorem thm:unbounded-state-rate of arXiv:2606.25135, 'Convergence Rates for Semistochastic Processes'] Let $\{X_t\}$ be a semistochastic process with generator (equation eq:gen of the paper) 
on the state space $\mathcal{X} = [0,\infty)$, satisfying 
\begin{itemize}
\item[(i)] 
$0  <   \lambda_* \leq  \Lambda(x)  \leq  \lambda^{*}  <  \infty$ for all $ x  \in  \mathcal{X} $, 
for some constants $ \lambda_*$ and~$\lambda^{*}$, 
\item[(ii)] 
$\rho(x,\alpha)  \geq  \rho_{*} $ for all $x \in \mathcal{X}$ and $ \alpha  \in  [0, 1]$, 
for some constant $\rho_* > 0$, 
\item[(iii)]
$\zeta(x) \geq \zeta_*$ for all $x \in \mathcal{X}$, for some constant $\zeta_* > 0$, 
\item[(iv)]
the function $v$ is Lipschitz, satisfies 
\begin{equation}  
0 \leq v(x) \leq v^* = \mathrm{const} \ , \qquad v(0) \neq 0 \ , 
\end{equation}
and vanishes for at most finitely many~$x$.  
\end{itemize}
Then $\{X_t\}$ has a unique stationary distribution $\pi$ to which it converges at an exponential rate.  Namely, for any initial distribution $\mu_0$ and any $\Delta t>0$, the estimate 
\begin{equation}  
d_{\mathrm{TV}}\left( \mu_t  ,  \pi \right) 
\leq 
\left(2+ \frac{b}{1-\beta} + {\mathbb{E}}_{\mu_0}[X_0] \right) 
\, (1-\epsilon_{\Delta t,\kappa})^{r \lfloor t / \Delta t \rfloor}\ 
\end{equation}
holds with $\Phi$ given by~(equation eq:Phi of the paper), 
\[
\epsilon_{\Delta t, \kappa} :=    \frac{ \rho_{*}  \Phi  \zeta_* \lambda_* \exp (-\lambda^{*}  \Delta t)} {\kappa}   \ ,
\]
\[
\beta := e^{-\lambda_* \zeta_* \Delta t} \ , 
\qquad 
b := \frac{v^{*}}{\lambda_* \zeta_*} 
\left( 1 \ - \ e^{-\lambda_* \zeta_* \Delta t} \right) \ , 
\]
\begin{equation}
\theta := \frac{1  +  2b  +  \kappa  \beta}{1  +  \kappa} \ , 
\qquad 
\Theta := 1 + 2(\beta  \kappa +  b) \ , 
\end{equation}
\begin{equation}  
r := \frac{\ln\theta}{\ln\frac{\theta(1-\epsilon_{\Delta t,\kappa})}{\Theta}}  
= \frac{\ln\frac{1}{\theta}}{\ln\frac{1}{\theta}+\ln\Theta+\ln\frac{1}{1-\epsilon_{\Delta t,\kappa}} }
\in (0,1) \ , 
\end{equation}
where $\kappa$ can be chosen to be any number satisfying 
\begin{equation}  
\kappa > \frac{2b}{1-\beta} \ .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:moment-boud:H^2xM^2:d=3 of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] {Let} $d\le 3$ {and assume the hypothesis} of Theorem (thm:well-posed of the paper). {Additionally assume} that \nameref{cond:phi:d=3}, \nameref{cond:Q:higher_regularity} hold for $m\ge 2$. Given $U_0=(u_0,\eta_0)\in \mathcal{H}^2_\mu$, there exist positive constants $c_{3,n},\,C_{3,n}$ and positive integer $q_{3,n}$ independent of $U_0$, $t$ and $\mu\in\mathcal{M}_\delta$ such that
\begin{equation}  
\emph{d} \Psi_2(U(t))^n\le -c_{2,n} \Psi_2(U(t))^n\emph{d} t+C_{2,n}\emph{d} t+C_{2,n}\Psi_{1}(U(t))^{q_{2,n}}\emph{d} t+\emph{d} M_{2,n}(t),
\end{equation}
where $\Psi_{\ell}$ {is given as in} (equation form:Psi_m of the paper) and $M_{2,n}(t)$ is the semi-martingale given by
\begin{equation} 
M_{2,n}(t)=\int_0^t n\Psi_2(U(r))^{n-1}\langle Au(t),A Q\emph{d} w(r)\rangle_H.
\end{equation}
Furthermore,
\begin{equation} 
\mathbb{E}\Psi_2(U(t))^n \le C_{2,n}e^{-c_{2,n}t}\Psi_2(U_0)^{q_{2,n}}+C_{2,n}.
\end{equation}

