[Theorem 27 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Let $\lambda^0\in\Delta_d$ and put $I=\mathcal I(\lambda^0)$ and $\kappa_0=\kappa(\lambda^0)$. Let $\mathcal H$ be a compact subset of $\R^d$ and let $k_t:\mathcal H\to\N^d$ be Borel and satisfy

\begin{equation*}
\sup_{h\in\mathcal H}|k_t(h)-t\lambda^0-\sqrt t\,h|_1=o(\sqrt t).
\end{equation*}

Let $g$ be a transition reward and assume

\begin{equation*}
\Ee_{\mathfrak a}\left[L_1^2+|Y_1|_1^2+(R_1^*(g))^2\right]<\infty.
\end{equation*}

Define

\begin{equation*}
\zeta_{\lambda^0}(h)=
\min_{r\in I}\left\{\frac{h_r-W_{Y,r}(\kappa_0)}{m_r}\right\},
\qquad h\in\mathcal H.
\end{equation*}

Then, in $\ell^\infty(\mathcal H)$,

\begin{equation*}
\left(
\frac{\mathfrak N(k_t(h))-t\kappa_0}{\sqrt t}
\right)_{h\in\mathcal H}
\xrightarrow[t\to\infty]{d}
\left(\zeta_{\lambda^0}(h)\right)_{h\in\mathcal H},
\end{equation*}

\begin{equation*}
\left(
\frac{N(k_t(h))-t\ell\kappa_0}{\sqrt t}
\right)_{h\in\mathcal H}
\xrightarrow[t\to\infty]{d}
\left(W_L(\kappa_0)+\ell\zeta_{\lambda^0}(h)\right)_{h\in\mathcal H},
\end{equation*}

and, if $a_g=\Ee_{\mathfrak a}[R_1(g)]$ and $\bar g=a_g/\ell$,

\begin{equation*}
\left(
\frac{\mathcal R_g(k_t(h))-t a_g\kappa_0}{\sqrt t}
\right)_{h\in\mathcal H}
\xrightarrow[t\to\infty]{d}
\left(W_R(\kappa_0)+a_g\zeta_{\lambda^0}(h)\right)_{h\in\mathcal H}.
\end{equation*}

Moreover,

\begin{equation*}
\left(
\frac{\mathcal R_g(k_t(h))-\bar g N(k_t(h))}{\sqrt t}
\right)_{h\in\mathcal H}
\xrightarrow[t\to\infty]{d}
\left(W_R(\kappa_0)-\bar g W_L(\kappa_0)\right)_{h\in\mathcal H}.
\end{equation*}

