[Defi app_def_IOP of arXiv:2411.16464, 'Generating social networks with static and dynamic utility-maximization approaches'] For a given individuals graph $\mathcal{G}_N(\mathscr{I} , \alpha, C)$, we define for all individual $i \in \Iintv*{1, N }$ the Individual Optimization Problem (IOP) as:
\begin{equation}
\begin{cases}
\argmax_{\alpha^i} U_i(\alpha^i, C^i) \\
\text{s.t.} \quad \alpha^i \in [0 ,1)^{I-1}
\end{cases}
\end{equation}

[Lemma lem: 393 of arXiv:2607.05848, 'Mesoscopic eigenvalue statistics for correlated random matrices'] Let $\mathcal{B}_{z}$ and $\mathfrak{g}$ be as in (equation eq: 535 of the paper) and (equation eq: 678 of the paper).
Then,
\begin{equation}
	\mathfrak{g} = -\mathcal{B}_{z}^{-1}\Big[\Big(R + \sum_{k=1}^{L-1} Q^{(k)} + \mathcal{E}^{(L)}\Big)M\Big],
\end{equation}
where $R=(R_{ij})$ and $Q^{(k)}=(Q^{(k)}_{ij})$ are defined by
\begin{equation}
	R_{ij} \coloneqq \sum_{a,b,k} \frac{\kappa(aj,bk)}{N} \mathbb{E}[(\partial_{bk}\tilde{e})G_{ia}],
\end{equation}
\begin{equation}
	Q^{(1)}_{ij} \coloneqq Q^{(1,1)}_{ij} + Q^{(1,2)}_{ij} + Q^{(1,3)}_{ij}, \quad
	Q^{(1,1)}_{ij} \coloneqq -\sum_{a,b,k}\frac{\kappa_{d}(aj,bk)}{N}\mathbb{E}[\tilde{e}(G_{ib}G_{ka}-\mathbb{E}[G_{ib}G_{ka}])],
\end{equation}
\begin{multline}
	Q^{(1,2)}_{ij} \coloneqq - \sum_{a,b,k}\frac{\kappa_{c}(aj,bk)}{N} \mathbb{E}[\tilde{e}(G_{ib}-\mathbb{E}[G_{ib}])]\mathbb{E}[G_{ka}-M_{ka}]
	- \sum_{a,b,k}\frac{\kappa_{c}(aj,bk)}{N} \mathbb{E}[\tilde{e}(G_{ka}-\mathbb{E}[G_{ka}])]\mathbb{E}[G_{ib}-M_{ib}] \\
	-\sum_{a,b,k}\frac{\kappa_{c}(aj,bk)}{N} \mathbb{E}[(\tilde{e}-\mathbb{E}[\tilde{e}])(G_{ib}-\mathbb{E}[G_{ib}])(G_{ka}-\mathbb{E}[G_{ka}])],
\end{multline}
\begin{equation}
	Q^{(1,3)}_{ij}
	\coloneqq \sum_{a,b,k}\frac{\kappa_{d}(aj,bk)}{N} \mathbb{E}[\tilde{e}(G_{ib}-\mathbb{E}[G_{ib}])]M_{ka}
	+ \sum_{a,b,k}\frac{\kappa_{d}(aj,bk)}{N} \mathbb{E}[\tilde{e}(G_{ka}-\mathbb{E}[G_{ka}])]M_{ib},
\end{equation}
\begin{equation}
	Q^{(k)}_{ij} \coloneqq \sum_{a} \sum_{\boldsymbol{\alpha}\in\mathcal{N}^{k}(\alpha_{0})}
	\frac{\kappa(\alpha_{0},\boldsymbol{\alpha})}{N^{(k+1)/2}k!}\mathbb{E}[\partial_{\boldsymbol{\alpha}}(\tilde{e}G_{ia}) - \tilde{e}\mathbb{E}[\partial_{\boldsymbol{\alpha}}G_{ia}]], \quad k\in\{2,\dots,L-1\}.
\end{equation}
Finally, each entry of $\mathcal{E}^{(L)}=(\mathcal{E}^{(L)}_{ij})$ corresponds to a linear combination of error terms satisfying (equation eq: 391 of the paper) where $f$ is replaced with
\begin{equation*}
	\sum_{a,b,k}\frac{\kappa(aj,bk)}{N}G_{ia} \quad\text{or}\quad \sum_{a,b,k}\frac{\kappa(aj,bk)}{N}\tilde{e}G_{ia}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Mainthm t:1.4i of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Assume $(r_N)_{N \geq 1}$ is as in~(equation e:1.11i of the paper). Then,
with the underlying space is as in~(equation e:1.10i of the paper),
\begin{equation}

\widehat{\eta}_{N,r_N}
\underset{N \to \infty} \Longrightarrow \ \widehat{\eta}_{\rm D} \,,
\quad ; \qquad
	\widehat{\eta}_{\rm D} \,\big|\, \widehat{\mathcal Z}_{\rm D} \sim\  \text{\rm PPP}\bigl(\widehat{\mathcal Z}_{\rm D}(\text{\rm d}\mkern0.5mu x)\otimes\text{\rm e}\mkern0.7mu^{-\alpha s}\text{\rm d}\mkern0.5mu s\otimes\nu({\rm d} \omega)\bigr) \,,
\end{equation}
where $\alpha$ and $\nu$ as in~(equation e:1.10i of the paper), and $\widehat{\mathcal Z}_{\rm D}$ is a random Radon measure on ${\rm D}$.
The law of $\widehat{\mathcal Z}_{\rm D}$ is uniquely defined via the relation:
\begin{equation}

	\widehat{\mathcal Z}_{\rm D} {\rm e}^{\alpha \psi_{\rm D} \overline{h}_{\rm D}} \overset{{\rm d}} = \mathcal Z_{\rm D} \,,
\end{equation}
where $\overline{h}_{\rm D}$ is as in~(equation e:1.7p of the paper) and independent of $\widehat{\mathcal Z}_{\rm D}$, $\psi_{\rm D}: {\rm D} \to \mathbb{R}$ is the deterministic field:
\begin{equation}

	\psi_{\rm D}(\cdot) : =  {\rm Leb}({\rm D}) \frac{\int_{\rm D} G_{\rm D}(\cdot,z)\, {\rm d} x}{\int_{{\rm D} \times {\rm D}} G_{\rm D}(x,y)\, {\rm d} x {\rm d} y} \,,
\end{equation}
and $\mathcal Z_{\rm D}$ is as in~(equation eq:deflqgm of the paper). The joint law of $\overline{h}_{\rm D}$ and $\mathcal Z_{\rm D}$ as determined by~(equation e:1104.14n of the paper) is the same as that in the coupling of Theorem~(t:1.2i of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:scalingreduction of arXiv:2606.11248, 'Persistent Homology of the Planar Wiener Sausage: Brownian Scaling and a Logarithmic Expec'] Suppose that there exist a normalization $a(T)$ and a nonnegative function $f$ on $(0,\infty)$ such that, for every fixed $r>0$,
\begin{equation}
\frac{\mathbb{E}[\beta_{1}^{T}(r)]}{a(T)}\to f(r)\qquad\text{as }T\to\infty,
\end{equation}
and suppose that
\[
a(T)=T\ell(T),
\]
where $\ell$ is slowly varying at infinity. Then there exists an absolute constant $\kappa\ge0$ such that
\begin{equation}
f(r)=\frac{\kappa}{r^{2}}.
\end{equation}

[Lemma l1 of arXiv:2603.05467, 'Thresholds for colouring the random Borsuk graph'] For all $ \lambda>\lambda_c $ and $ \varepsilon>0 $ there is a $ k=k(\lambda,\varepsilon) $ such that the following holds. For all $ N\in \mathbb{N} $ we have for all $\ell\geq \ell_0(\lambda,\varepsilon,N,k) $
	\begin{equation*}
		\mathbb{P}(Y_{\ell,k}\geq N)>1-\varepsilon.
	\end{equation*}

