body:
[Definition1 of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] Let $T$ be a random infinite planar triangulation. We say that $T$ is weakly Markovian if there exist numbers $a_v^{p_1,\dots,p_k}$ for $k \ge 1$ and $p_1,\dots,p_k \ge 1$, $v \ge 0$, such that for any triangulation $t$ with $k$ holes of perimeters $p_1,\dots,p_k$ and $v$ internal vertices,
\begin{align*}
\mathbb{P}(t \subset T) = a_v^{p_1,\dots,p_k}.
\end{align*}

[Lemma 10 of arXiv:2512.10199, 'Explicit correlation functions for the six-vertex model in the free-fermion regime'] Let $\rho \in \pure_n$ have disjoint cycle decomposition $\rho = c_1 c_2\dots c_r$. For a cycle $c$ on $\midedge_n$, define its \textit{horizontal} and \textit{vertical winding numbers} by, respectively,
        \begin{equation*}
            q_1(c) = \frac{A(c) + \tfrac{1}{2}C(c)}{n}, \qquad q_2(c) = \frac{B(c) + \tfrac{1}{2}C(c)}{n}.
        \end{equation*}
        Then there exist coprime non-negative integers $q_1,q_2$ such that $q_i(c_j) = q_i$ for all $i = 1,2$ and $1 \leq j \leq r$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lm:bdry of arXiv:2604.12963, 'Shocks, instability, and the twenty networks\\ of infinite geodesics in the Directed Lands'] Let $\omega\in\Omega_0$, $\theta\in\Theta^\omega$, and  $(x,s)\in\mathbb{R}^2$. For $t\in\mathbb{R}$, let $\gamma(t)=(I^{\theta-}_{(x,s)}(t),t)$ and $\tau(t)=(I^{\theta+}_{(x,s)}(t),t)$. 
    \begin{enumerate}[label={\rm(\alph*)}, ref={\rm\alph*}] \itemsep=1pt
    \item $\gamma\preceq\tau$ and $(x,s)$ is weakly between the two paths. If $\gamma\ne\tau$, then the connected components of $\{(z,r):\gamma(r)<(z,r)<\tau(r)\}$ are all stability islands.
    \item Suppose $(x,s)$ is in the closure of some stability island. Let $t_1=\sup\{r\le s:\gamma(r)=\tau(r)\}$ and $t_2=\inf\{r\ge s:\gamma(r)=\tau(r)\}$. Then $-\infty<t_1<t_2<\infty$, $s\in[t_1,t_2]$, $\gamma(t_1) = \tau(t_1)$, $\gamma(t_2) = \tau(t_2)$, for any $r\in(t_1,t_2)$, $\gamma(r) < \tau(r)$, and the island is given by
    \begin{align}
    \{(z,r):\gamma(r)<(z,r)<\tau(r),\,t_1<r<t_2\}.
    \end{align}
    \end{enumerate}

