body:
[Definition 1 of arXiv:2607.21931, 'Lorenz and convex ordering of parasite burden distributions with density-dependent deaths'] The {\em Lorenz curve} $L: [0,1] \to [0,1] $ for the distribution $F$ on $[0,\infty)$ with finite mean $ \mu$ is given by
    \begin{equation*}
        L(u) = \frac{\int_{0}^{u} F^{-1}(y)\, dy}{\mu}, 
    \end{equation*}
    where $ F^{-1}$ is the quantile function
    \begin{equation*}
        F^{-1}(y) = \inf \{ x : F(x) \geq y \} \quad \text{for } y \in (0,1).
    \end{equation*}

[Lemma Lemma_phi_martingale_on_stochastic_interval of arXiv:2608.08299, 'Non-linear optimal stopping with Bermudan strategies: the infinite horizon case'] Let $\rho$ satisfy the consistency property (v).
    Let $\phi=(\phi(\nu))$ be a given non-negative admissible family.
    Let $S$ $\in$ $\Theta$ and $\tau$ $\in$ $\Theta$ be such that $S \leq \tau$ a.s. 
    We assume that for any  $\sigma$ $\in$ $\Theta$ such that $S \leq \sigma \leq \tau$ a.s., it holds 
    \begin{equation}
        \rho_{\sigma,\tau}[\phi(\tau)] = \phi(\sigma) \,\,\,\, a.s.
    \end{equation}
    Then, $\phi$ is a \emph{$(\Theta, \rho)$}-martingale on the stochastic interval $[S,\tau]$, that is, for any  $\nu_1$ $\in$ $\Theta$, and $\nu_2$ $\in$ $\Theta$, such that $S \leq \nu_1 \leq \nu_2 \leq \tau$ a.s.,
    \begin{equation}
          \rho_{\nu_1,\nu_2}[\phi(\nu_2)] = \phi(\nu_1) \,\,\,\, a.s.
    \end{equation}

[Theorem 6 of arXiv:2609.00687, 'A unification of Euler-Maclaurin and Euler-Boole summation formulas'] Let $n,q\in\mathbb{N}$ and $x,a\in\mathbb{R}$ with $a>0$. Let $\chi$ be a Dirichlet character modulo $q$. If $q=1$, then
\begin{equation}
L(1-n,x,a,\chi)=-\frac{\beta_{n}(a,e^{\frac{2\pi \mathrm{i}x}{q}})}{n},
\end{equation}
and if $q\geqslant2$, then
\begin{equation}
L(1-n,x,a,\chi)=-\frac{\beta_{n,\chi}(a,e^{\frac{2\pi \mathrm{i}x}{q}})}{n},
\end{equation}
where $\beta_{n,\chi}(x,\lambda)$ are the generalized Apostol-Bernoulli polynomials, defined for $\lambda\in\mathbb{C}\setminus\{0\}$ and for a Dirichlet character $\chi$ modulo $q\in\mathbb{N}$, by the generating function (see, e.g., \cite[Definition 2.1]{he})
\begin{equation}
\sum_{r=1}^{q}\frac{\chi(r)\lambda^{r}te^{(r+x)t}}{\lambda^{q}e^{qt}-1}=\sum_{n=0}^{\infty}\beta_{n,\chi}(x,\lambda)\frac{t^{n}}{n!}\quad(|t+\log\lambda|<2\pi/q).
\end{equation}

[Lem Lem2.2 of arXiv:2411.15724, 'Wasserstein Convergence Rates for Empirical Measures of Random Subsequence of $\{nα\}$'] Given $\theta > 1$ and $\tau > 0$, then for any irrational number $\alpha$ associated with convergents $( p_k/q_k )_{k \in \mathbb N}$ and every $k \geq 3$,
\begin{align*}
\sum_{q_k \leq m < q_{k + 1}} \frac{1}{m^{\theta} \| m \alpha \|^\tau} \, = \,  O \bigg( \frac{1}{q_k^\theta \| q_k \alpha \|^\tau} \bigg) \, + \,
\begin{cases}
O\big( q_k^{-(\theta - 1)} \big), & \textrm{if }0 < \tau < 1;\\
O\big( q_k^{-(\theta - 1)} \log q_k \big), & \textrm{if } \tau = 1;\\
O\big( q_k^{-\theta + \tau} \big), & \textrm{if }\tau > 1,
\end{cases}
\end{align*}
where the implied constants only depend on $\theta$ and $\tau$.

