body:
[Thm 1 of arXiv:2609.00598, 'Supercritical mean--field limit for magnetized Hamiltonian dynamics'] Suppose that 
\begin{itemize}
\item[{\rm(i)}] $B\in W^{1,\infty}(\mathbb{R}_{+};W^{2,\infty}(\mathbb{T}^{2}))${\rm;}
\item[{\rm(ii)}]
$f_{\varepsilon}\in W^{1,\infty}([0,T]\times \mathbb{T}
    ^{2}\times \mathbb{R}^{2})$ is a solution to \eqref{magnetized vp with quasineutral scaling} with $f^{\mathrm{in}}_{\varepsilon}\in \mathcal{P}(\mathbb{T}^{2}\times \mathbb
    {R}
    ^{2}),$ finite second velocity moment and sufficient velocity decay{\rm;}
\item[{\rm(iii)}]
    $\omega^{\mathrm{in}}\in W^{1,\infty}( \mathbb{T}^{2})$, 
    $\int_{\mathbb T^2}\omega^{\mathrm{in}}\,\dd x=0$,  
    and $(\omega,v)$ is the solution to \eqref{vorticity formulation intro}  on $[0,T]$ with initial data $\omega^{\mathrm{in}}$. 
\end{itemize}
 Let $\mathcal{E}_{\varepsilon}(t)$ be given by \eqref{modulated energy def}.
Then
\begin{align*}
\underset{t\in [0,T]}{\sup} \mathcal{E}_{\varepsilon}(t)\underset{\varepsilon \rightarrow 0}{\longrightarrow}0,
\end{align*}
provided $\mathcal{E}_{\varepsilon}(0)\underset{\varepsilon \rightarrow 0}{\longrightarrow}0$.    
This implies that
\begin{align*}
\rho_{\varepsilon}(t,\cdot)\xrightharpoonup[\varepsilon \rightarrow 0]{}1\quad\, 
\mbox{and} \quad\, J_{\varepsilon}(t,\cdot)
\xrightharpoonup[\varepsilon \rightarrow 0]{}v
\end{align*}
weakly in the sense of measures. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 15 (Degree evolution in continuous time) of arXiv:2605.21459, 'Network evolution with self-reinforcement'] Let $(Y(t))_{t \ge 0}$ be a standard rate-$1$ Yule process started with $Y(0) = 2$ individuals. Suppose that new individuals are marked according to the following rule. Let $D(t)$ be the number of marked individuals at time $t$, with $D(0) = 1$. Let $T_1, T_2, \dots, T_{D(t)}$ be the times when these marks occurred. Define $W(t) = \sum_{j=1}^{D(t)} Y(T_j)$. When a new individual is born at time $t$ (which occurs at rate $Y(t)$), then it is marked with probability
	\begin{equation*}
	    p_\delta(t) = \gamma \left( \frac{D(t) + \delta}{Y(t)+1} - \frac{W(t)}{Y(t)(Y(t)+1)} \right),
	\end{equation*}
where $\delta>-1$ is a constant, and $\gamma = \frac{1}{1 + \delta/2} = \frac{2}{2+\delta}$.

[Proposition prop:Z of arXiv:2412.02160, 'A functional central limit theorem for weighted occupancy processes of the Karlin model'] Assume 
\begin{equation}
|a_j|\le Cj^\beta \quad\mbox{ with }\quad \beta\in\Big[0,\frac\alpha 2\Big),
\end{equation} Then,  $(\mathcal{Z}_\alpha(t))_{t\ge 0}$ is a family of centered Gaussian random variables with
\begin{equation}
{\rm{Cov}}(\mathcal{Z}_\alpha(s),\mathcal{Z}_\alpha(t)) =\alpha t^\alpha \sif k1 \frac{F_{\vec a,s,t}\topp 1(k)\Gamma(k-\alpha)}{k!} -  \alpha(s+t)^\alpha \sif k2 \frac{F_{\vec a,s,t}\topp 2(k)\Gamma(k-\alpha)}{k!},
\end{equation}
where $0<s<t$, 
and 
\begin{align*}
F_{\vec a,s,t}\topp1(k) &:= \summ j1k\binom kj \pp{\frac st}^j\pp{1-\frac st}^{k-j}a_ja_k,\\
F_{\vec a,s,t}\topp2(k) &:= \summ j1{k-1}\binom kj \pp{\frac s{s+t}}^j\pp{\frac t{s+t}}^{k-j}a_ja_{k-j}.
\end{align*}
If furthermore 
\begin{equation}
|a_{i+j}-a_i|\le Cj^\beta \mbox{ for all } i,j\in{\mathbb N}  \quad\mbox{ with }\quad \beta\in\Big[0,\frac\alpha 2\Big),
\end{equation} 
 then $(\mathcal{Z}_\alpha(t))_{t\ge0}$ forms a stochastic process with a version that is $\gamma$-H\"older-continuous for 

  every $\gamma\in(0,\alpha/2)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Propo 23 of arXiv:2604.22114, 'Free compressions of R-diagonal random variables and the semigroup of Brown measures'] If $x \in \AA^\Delta$ is an $R$-diagonal random variable with a stable Brown measure $\mu \ne \delta_0$, then
\begin{equation}

S_{|x|^2}(z) = c \frac{(-z)^\beta}{1 + z},
\end{equation}
for some $c > 0$ and $\beta \ge 0$.

[Theorem thm:nualart-sub of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] Let $m \in \mathbb{N}$ and let
\[
  w = \{w_r(z) : r \in [0, T],\ z \in \mathbb{R}^m\}
\]
satisfy the hypotheses of Nualart's substitution theorem, namely Skorokhod integrability and continuity in $z$, $C^1$-regularity in $z$, and the corresponding local integrability bounds. If
\[
  G \in \mathbb{D}^{1,4}_{\mathrm{loc}}(\mathbb{R}^m),
\]
then
\[
  w(G) \in (\operatorname{Dom}\delta_U)_{\mathrm{loc}}
\]
and
\begin{equation}
  \delta_U(w(G))
  \;=\;
  \bigl[\delta_U(w(\cdot)(z))\bigr]_{z = G}
  \;-\;
  \int_0^T \operatorname{Tr}_U\bigl[\nabla_z w_r(G) \circ \mathcal{D}_r G\bigr]\,\mathrm{d}r.
\end{equation}

\medskip\noindent No general infinite-dimensional extension of this theorem is invoked below. The only $H$-valued substitution required in the present paper is the linear case
\[
  w_r(z) = \Phi_r^{*}z,
\]
for which Theorem~(thm:linear-sub-D12 of the paper) gives a direct basis-wise proof under the weaker requirement $G \in \mathbb{D}^{1,2}(H)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 14 (Decoupled Gaussian chaos operator) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $I_1,\ldots,I_m$ be finite index sets, and let
$K=(K_{i_1\cdots i_m})$ be an operator-valued coefficient array with
$K_{i_1\cdots i_m}\in\cL(\cC,\cE)$.  Let
\[
  \{g_i^{(\nu)}:\nu\in[m],\ i\in I_\nu\}
\]
be a jointly independent collection of standard real Gaussian variables, or
a jointly independent collection of standard circular complex Gaussian
variables.  The associated \emph{decoupled homogeneous Gaussian chaos
operator of order $m$} is
\begin{equation}

  \cT_K^{(m)}
  :=\sum_{i_1\in I_1,\ldots,i_m\in I_m}
  g^{(1)}_{i_1}\cdots g^{(m)}_{i_m}K_{i_1\cdots i_m}.
\end{equation}

[Proposition 4 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] Let $p\geq 2$ and~\eqref{co:1}, \eqref{co:3} and \eqref{co:5} be satisfied. Then there is a unique strong solution $I$ to~\eqref{eq:SIS epidemic model} such that $I_{0} = \xi_{0}$ a.s.~and
\begin{equation}
\E\big[I_{t}^{p}\big] \leq e^{\int_{0}^{t}\overline{l}_{p}(s,N(s))\,\mathrm{d}s}\E\big[\xi_{0}^{p}\big] + \int_{0}^{t}e^{\int_{s}^{t}\overline{l}_{p}(\tilde{s},N(\tilde{s}))\,\mathrm{d}\tilde{s}}\hat{b}_{0}(s,N(s))\,\mathrm{d}s
\end{equation}
for all $t\geq 0$ with $\overline{l}_{p} := (p-1)\hat{b}_{0} + p(\hat{b}_{k+2} + c_{p}l^{2})$. Furthermore, the following two assertions hold:
\begin{enumerate}[(i)]
\item The integrability of $\overline{l}_{p}^{+}(\cdot,N)$ and $\hat{b}_{0}(\cdot,N)$ implies that $\sup_{t\geq 0}\E[I_{t}^{p}]$ is finite. If in addition $\int_{0}^{\infty}\overline{l}_{p}^{-}(s,N(s))\,\mathrm{d}s = \infty$, then $\lim_{t\uparrow\infty} \E[I_{t}^{p}] = 0$.

\item If $\xi_{0}  = i_{0}$ a.s.~and~\eqref{co:4} is valid, then $0 < I < N$ a.s.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

