body:
[Lem 22 of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] Let $F \in \bW^{k+1, p}$, $\Delta_F^{-1} \in L^q(\Omega)$, and $G \in \bW^{k, r_0}$ for some $k \in \N_0$ and $p, q, r_0 \in (1, \infty)$. 
Define $r_j, \ j \in \{1, \ldots, k+1\}$ by 
\begin{equation}
    \frac{1}{r_j} = \frac{1}{r_0} + \sum_{i=0}^{j-1} \left( \frac{2k+1-2i}{p} + \frac{k+1-i}{q} \right) = \frac{1}{r_0} + \frac{j(2k+2-j)}{p} + \frac{j(2k+3-j)}{2q}. 
\end{equation}
If $r_j > 1$ for some $j \in \{1, \ldots, k+1\}$, then for every $i \in \{1, \ldots, j\}$, we have
\begin{equation}
    \Theta_F^{\circ (i-1)}(G) \Delta_F^{-1} DF \in \bW^{k-i+1, r_i}(\fH), \qquad  \Theta_F^{\circ i}(G) \in \bW^{k-i, r_i},
\end{equation}
and 
\begin{equation}
    \norm{\Theta_F^{\circ i}(G)}_{\bW^{k-i, r_i}} \lesssim_{i,k,p,q,r_0} \norm{G}_{\bW^{k,r_0}} \norm{F}_{\bW^{k+1, p}}^{i(2k+2-i)} \norm{\Delta_F^{-1}}_{L^q(\Omega)}^{\frac{i(2k+3-i)}{2}}.
\end{equation}

