[Definition 13 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] A localic relation~$R$ is called:
	\begin{itemize}
		\item \emph{reflexive} if $\Delta\subseteq R$;
		\item \emph{transitive} if $R\circ R\subseteq R$;
		\item \emph{anti-symmetric} if $R\cap R^\op \subseteq \Delta$.
	\end{itemize}
	Combined, we say~$R$ is a:
	\begin{itemize}
		\item \emph{preorder} if it is reflexive and transitive;
		\item \emph{partial order} if it is an anti-symmetric preorder.
	\end{itemize}

[Theorem ThmMaster of arXiv:2608.28949, 'The information geometry of product-reference discrete diffusion: Interaction growth compl'] For any grid~(equation EqnGrid of the paper) of the interval $[r_0, R]$, the
\textsf{PRD}\xspace sampler returns output $\ensuremath{\widehat{Z}}$ such that
\begin{align}

  \ensuremath{D_{\scaleto{\operatorname{KL}}{4pt}}}( \ensuremath{\mathbb{P}}_Z \| \ensuremath{\mathbb{P}}_{\ensuremath{\widehat{Z}}}) & \leq 2 \; \sum_{j = 0}^{N - 1} \big \{
  \frac{\ensuremath{\psi}(r_{j + 1})}{\ensuremath{\psi}(r_j)} - 1 \big \}
  \mathsf{G}(r_j, r_{j + 1}) +  \ensuremath{\mathsf{TC}}(\ensuremath{X}_{r_0}) + \ensuremath{\mathsf{TC}}(Z \mid
  X_R),
\end{align}
where $\ensuremath{\psi}(t) \coloneqq \frac{t}{1 - t}$ is the odds of the squared
reliability $t$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop starting-point of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] There exists $C>0$ such that for all $\beta$, for any $\ell \times h$ rectangle $R$ with $h \ge \log \ell$, with any boundary conditions $\tau$, has mixing time at most $e^{ 8 \beta h}$. As a consequence, for all $n \in [N_0,N]$, we have 
    \begin{align*}
        \mathcal A (L_n, t, e^{ - t e^{ - 8\beta \kappa_N \sqrt{L_n}}})  \qquad \text{and} \qquad \mathcal B(L_n, t, e^{-t e^{- 16\beta \kappa_N \sqrt{L_n}}}) \quad \text{hold}\,.
    \end{align*}

[Definition 1 (Compressible predictable process) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] For $S>0$, let $X \in \mathcal{H}^2_T(\mathbb{R}^{d})$ be a process with chaoslet expansion
    \begin{equation}

        X= \sum_{k=0}^{\infty}\,\sum_{\mathfrak{m}\in \mathfrak{C}_k}\,\beta_{k,\mathfrak{m}}\,\mathfrak{m},
    \end{equation}
    where $(\beta_{k,\mathfrak{m}})_{{k,\mathfrak{m}}} \subseteq \mathbb{R}^d$. Then, $X$ is called \emph{$S$-compressible} if the non-increasing rearrangement of the norms of $(\beta_{k,\mathfrak{m}})_{{k,\mathfrak{m}}}$ decays polynomially with exponent $S$. More precisely, if $|\beta_{k_1,\mathfrak{m}_1}|_{\mathbb{R}^{d}}\ge |\beta_{k_2,\mathfrak{m}_2}|_{\mathbb{R}^{d}} \ge \dots \ge |\beta_{k_r,\mathfrak{m}_r}|_{\mathbb{R}^{d}}
    \ge |\beta_{k_{r+1},\mathfrak{m}_{r+1}}|_{\mathbb{R}^{d}}\ge \dots$ for some enumerations $(k_r)_{r \in \mathbb{N}_+}$ and $(\mathfrak{m}_r)_{r \in \mathbb{N}_+}$ of $\mathbb{N}_+$ and $\mathfrak{C}_k$, respectively, there exists some constant $C_{X}>0$ such that for every $r \in \mathbb{N}_{+}$ it holds that
\begin{equation} 

|\beta_{k_r,\mathfrak{m}_r}|_{\mathbb{R}^{d}} \le C_{X}\,r^{-S}.
\end{equation}

[Proposition 6 of arXiv:2604.20631, 'The Ising Model on a Two-Community Stochastic Block Model'] Let $\beta>0$ and $\alpha \in (0,1]$. Define
\begin{align}
    \beta^* (\alpha)= \frac{2}{1-\alpha} \frac{\operatorname{arctanh}(t_*)}{t_*},
\end{align}
where $t_* \in (0,1)$ is such that
\begin{align} 
   (1-t_*^2)\frac{\operatorname{arctanh}(t_*)}{t_*}=\frac{1-\alpha}{1+\alpha}.
\end{align}
Then the functional $G_{\alpha,\beta}(\bm)$ defined in \eqref{def:free_energy_functional_CW} admits one, two, or four local maximizers. In particular:
    \begin{itemize}
        \item[(i)] for $\beta\le \frac{2}{1+\alpha}$, $\bm^0$ is the unique maximizer;
        \item[(ii)] for $\beta \in \left (\frac{2}{1+\alpha}, \beta^*(\alpha)\right ]$, there are two (symmetric) global maximizers, $\bm^1$ and $\bm^2$;
        \item[(iii)] for $\beta > \beta^*(\alpha)$, there are two (symmetric) global maximizers, $\bm^1$ and $\bm^2$, and two (anti-symmetric) local maximizers, $\bm^3$ and $\bm^4$.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm diffusiveMeanFieldConvergence of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Fix $T_\ast\in(0,\infty]$ and $\beta>0$.  Let $(\mu^t)_{0\le t<T_\ast}$ solve (equation eq:diffusiveMeanFieldEquation of the paper), and assume that this solution admits a globally\footnote{For sufficiently regular solutions, this velocity is
\(
u^t=-\nabla h_{\mu^t}-\beta^{-1}\nabla\log\mu^t\).} Lipschitz velocity field $u^t$ satisfying
\begin{align}
\partial_t\mu^t+\div(\mu^t u^t)=0.
\end{align}
Let $(f_N^t)_{0\le t<T_\ast}$ be a curve of $N$-particle probability laws and write
\begin{align}
\mathsf{E}_N^t\coloneqq \mathsf{E}_N(f_N^t,\mu^t).
\end{align}
Assume that $t\mapsto\mathsf{E}_N^t$ is absolutely continuous and that the pair $(f_N^t,\mu^t)$ satisfies the modulated-free-energy dissipation inequality
\begin{align}
\frac{\mathop{}\!\mathrm d}{\mathop{}\!\mathrm d t}\mathsf{E}_N^t
\le \frac1N\Big|{\mathbb{E}}_{X_N\sim f_N^t}\Big[N\mathsf{A}_1(u^t,X_N,\mu^t)\Big]\Big|, \qquad \text{a.e. } t\in(0,T_\ast).
\end{align}
Assume also that, for a.e. $t\in(0,T_\ast)$, the hypotheses of (thm:entropicCommutator of the paper) are satisfied with $n=1$, $\mu=\mu^t$, and $v=u^t$, at the fixed inverse temperature $\beta$.

Set
\begin{align}
\mathcal A^t
&\coloneqq \exp\pa*{\int_0^t C_{\beta,1,u^\tau}(\mu^\tau)\,\mathop{}\!\mathrm d\tau},\\
\mathcal B^t
&\coloneqq \int_0^t \exp\pa*{\int_\tau^t C_{\beta,1,u^r}(\mu^r)\,\mathop{}\!\mathrm d r}
C_{\beta,\mu^\tau,u^\tau,1}\,\mathop{}\!\mathrm d\tau,
\end{align}
where the constants are those of (thm:entropicCommutator of the paper).  If these quantities are finite for every $t<T_\ast$, then
\begin{align}
\mathsf{E}_N(f_N^t,\mu^t)
\le \mathcal A^t\mathsf{E}_N(f_N^0,\mu^0)+\frac{\mathcal B^t}{N},
\qquad 0\le t<T_\ast.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

