body:
[Proposition 21 (Laplace asymptotics in the right-edge regime) of arXiv:2605.11995, 'Intrinsic volumes of \(\ell_p\)-balls and a continuum of Maxwell--Poincar\'e--Borel laws f'] Fix $1<p<\infty$, an integer $r\ge 1$, and complex parameters
\begin{equation}
\lambda_1,\dots,\lambda_r\in\mathbb C,
\qquad
\Re \lambda_j>\max\{-1,1-p\},\quad j=1,\dots,r.
\end{equation}
Put $\Lambda:=\lambda_1+\cdots+\lambda_r$. Fix an integer $m\geq 1$ and recall that for sufficiently large  integer $n$ we defined
\[
I_{n, n-m}(\lambda_1,\dots,\lambda_r)
:=
\int_{\partial \mathbb B_p^n}
\prod_{j=1}^r |x_j|^{\lambda_j}\,
d\Phi_{n-m}\bigl(\mathbb B_p^n,x\bigr).
\]
Then the following assertions hold:

\vspace{2mm}
\noindent
(i) Absolute asymptotic: As $n\to\infty$, one has
\[
I_{n, n-m}(\lambda_1,\dots,\lambda_r)
\sim
\frac{\Gamma\!\left(\frac m2\right)}{2(m-1)!}
\left(
\frac{p(p-1)\Gamma\!\left(1-\frac1p\right)}
{\pi\,\Gamma\!\left(\frac1p\right)}
\right)^{m/2}
\left(\prod_{\ell=1}^r
\frac{\Gamma\!\left(\frac{\lambda_\ell+1}{p}\right)}
{\Gamma\!\left(\frac1p\right)}
\right)
\frac{\left(\frac{2}{p}\Gamma\!\left(\frac1p\right)\right)^n\,n^{m/2}}
{\Gamma\!\left(\frac{n+\Lambda+p-m}{p}\right)}.
\]
In particular, setting $\lambda_1=\ldots= \lambda_r = 0$ gives
\[
I_{n, n-m}(0,\dots,0)
\sim
\frac{\Gamma\!\left(\frac m2\right)}{2(m-1)!}
\left(
\frac{p(p-1)\Gamma\!\left(1-\frac1p\right)}
{\pi\,\Gamma\!\left(\frac1p\right)}
\right)^{m/2}
\frac{\left(\frac{2}{p}\Gamma\!\left(\frac1p\right)\right)^n\,n^{m/2}}
{\Gamma\!\left(\frac{n+p-m}{p}\right)}.
\]

\vspace{2mm}
\noindent
(ii) Relative asymptotic: As $n\to\infty$, one has
\[
\frac{I_{n, n-m}(\lambda_1,\dots,\lambda_r)}{I_{n, n-m}(0,\dots,0)}
\sim
\frac{\Gamma\!\left(\frac{n+p-m}{p}\right)}
{\Gamma\!\left(\frac{n+\Lambda+p-m}{p}\right)}
\cdot
\prod_{\ell=1}^r
\frac{\Gamma\!\left(\frac{\lambda_\ell+1}{p}\right)}
{\Gamma\!\left(\frac1p\right)}
\sim
\left(\frac{p}{n}\right)^{\Lambda/p}
\cdot
\prod_{\ell=1}^r
\frac{\Gamma\!\left(\frac{\lambda_\ell+1}{p}\right)}
{\Gamma\!\left(\frac1p\right)}.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem T:SLND of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Assume Hypothesis (H:para of the paper) and the Dalang condition~(equation E:main of the paper). Let $0<S<T<\infty$.
  \begin{enumerate}[\rm (i)]

    \item \emph{(SLND in time)}\index{strong local nondeterminism (SLND)!temporal}
          \begin{enumerate}[\rm (a)]

            \item If $\beta = 1$, $\gamma \ge 0$; or $\beta = 2$, $\gamma \in [0,
                      1]$, then there exist constants $C > 0$ and $\delta>0$ such that for
                  all $x \in \mathbb{R}^d$, for all $n \ge 1$, and for all $t, t_1, \dots, t_n
                    \in [S, T]$ with $\max_{1\le j \le n}|t-t_j| \le \delta$,
                  \begin{align}
                    \ensuremath{\mathrm{Var} }\big( u(t, x) \big| u(t_1, x), \dots, u(t_n, x) \big) \ge C \min_{1 \le j \le n} |t-t_j|^{2\rho}.
                  \end{align}

            \item If $\beta \in (0, 2)$, $\gamma \ge 0$, then there exists a constant $C>0$ such
                  that for all $x \in \mathbb{R}^d$, for all $n \ge 1$, and for all $t, t_1,
                    \dots, t_n \in [S, T]$ with $\max\{t_1, \dots, t_n \} \le t$,
                  \begin{align}
                    \ensuremath{\mathrm{Var} }\big( u(t, x) \big| u(t_1, x), \dots, u(t_n, x) \big) \ge C \min_{1 \le j \le n} (t-t_j)^{2\rho}.
                  \end{align}

          \end{enumerate}

    \item \emph{(SLND in space)}\index{strong local nondeterminism (SLND)!spatial} If $\beta \in (0, 2]$, $\gamma \ge 0$, then
          for any $M>0$, there exists a constant $C>0$ such that for all $t \in [S,
              T]$, for all $n \ge 1$, and for all $x, x_1, \dots, x_n \in B(0, M)$,
          \begin{align}
            \ensuremath{\mathrm{Var} }\big( u(t, x) \big| u(t, x_1), \dots, u(t, x_n) \big) \ge C \min_{1 \le j \le n} |x-x_j|^{2\tilde\rho}.
          \end{align}

  \end{enumerate}

