[Proposition thm|BayesFormula of arXiv:2504.08935, 'Higher-Order Derivatives of First-Passage Percolation with Respect to the Environment'] For every random variable $\varphi$ on $\Omega$, its expected value $\mathbb E[\varphi]$ can be evaluated using 
the equation
 \begin{align}
\mathbb E\left[\varphi\right]&= p\mathbb E[\varphi\circ \sigma_i^a]+(1-p)\mathbb E[\varphi\circ \sigma_i^b]. 

\end{align}

[Proposition prop:linearization-well-behaved-vert of arXiv:2608.12415, 'Sharp Phase Transition for Ellipsoid Fitting'] Let $\tau_I$ be a well-behaved intersection in the sense of (def:well-behaved-intersection-vertical of the paper); we define its linearized shapes as follows:
	\begin{enumerate}
		\item $R(\tau_I)$ has the same vertex boundary as $\tau_I$;
		\item $R(\tau_I)$ is obtained from $\tau_I$ via the following operation: for any square vertex $s \in \{s_{bp}, s_{\eta}\}$ incident to well-behaved intersection (i.e., its incident edges match up), remove the square vertex and its incident edges.
	\end{enumerate}
	Then we have \[
	\mathsf{M} _{\tau_I} = \frac{m}{d^2}\cdot  \mathsf{M} _{R(\tau_I)} + \tilde{O}(1/d)\,.
	 \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop prop_boundary_regular_odes of arXiv:2606.23648, '\textsc{Optimal Stopping for a Diffusion with Unobserved Bernoulli Drift}'] Let \(x_0\in\mathcal I\).

    \noindent \textbf{(i)} \quad Suppose first that \(a(x_0)>-x_0\) and
    \(
        H(x_0,a(x_0))H(x_0,b(x_0))\neq0.
    \)
    Then there exists a neighborhood \(J\) of \(x_0\) in \(\mathcal I\) such that \(a(\cdot)\) and \(b(\cdot)\) are \(C^1\) on \(J\). Moreover, with
    \begin{equation}
        M(x; a, b)
        \coloneqq
        \frac{k'(x+b)-k'(x+a)}
             {G(b)-G(a)},
    \end{equation}
    we have, for \(x\in J\), the system of coupled ordinary differential equations
    \begin{equation}
    \begin{split}
        a'(x)
        &=
        \frac{G'(a(x))}{2H(x,a(x))}
        \left(
            M\big(x; a(x), b(x)\big)-\frac{k''(x+a(x))}{G'(a(x))}
        \right),
        \\
        b'(x)
        &=
        \frac{G'(b(x))}{2H(x,b(x))}
        \left(
            M\big(x; a(x), b(x)\big)-\frac{k''(x+b(x))}{G'(b(x))}
        \right).       
    \end{split}
    \end{equation}

    \noindent \textbf{(ii)} \quad Suppose next that \(J\subset\mathcal I\) is an open interval on which \(a(x)=-x\), and that
    \(
        H(x,b(x))\neq0,\, x\in J.
    \)
    Then \(b(\cdot)\) is \(C^1\) on \(J\). Moreover, with
    \begin{equation}
        M_0(x; b)
        \coloneqq
        \frac{
            k'(x+b)-k'(0+)
            +
            \big(\Phi(x,-x)-\Phi(x,b)\big)G'(-x)
        }
        {G(b)-G(-x)},
    \end{equation}
    we have, for \(x\in J\), the differential equation
    \begin{equation}
        b'(x)
        =
        \frac{G'(b(x))}{2H(x,b(x))}
        \left(
            M_0(x; b(x))-\frac{k''(x+b(x))}{G'(b(x))}
        \right), \qquad x \in J
    \end{equation}

[Corol 21 of arXiv:2604.27205, 'An Analysis of the Diaconis-Holmes-Neal Markov Chain Sampler Under Generalized Unimodal Un'] Both
        \begin{equation}
            \dbinom{cn}{f_1} \lesssim (cn)^{f_1} 
        \end{equation}
        \noindent and
        \begin{equation}
            \dbinom{\lfloor cn/\tilde{f}\rfloor}{f_2} \lesssim \left(\frac{cn}{\tilde{f}}\right)^{f_2}. 
        \end{equation}
        \noindent are true. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop u_R_L_x^2_priori_esti of arXiv:2606.31155, 'The well-posedness of stochastic Korteweg--de Vries equations revisited'] Assume $u_0\in L_x^2$ and $ k\in L_x^\infty L_y^2$. For any fixed $ R,T>0$, let $u_R$ be the solution constructed in Proposition (localwellres of the paper). Then for any stopping time $0\leq \sigma\leq \sigma_R^T(u_R)$ almost surely, we have
		\begin{equation*}
			\left\|u_R\right\|_{L_\omega^pL^\infty_{\sigma}L_x^2}\leq C(p,T,\|k\|_{L_x^\infty L_y^2})\|u_0\|_{L_x^2}, \quad \forall~2\leq p<\infty.
		\end{equation*}

