[Theorem 25 of arXiv:2608.30752, '2608.30752'] Let \(q\in\mathcal Q^1(X_0)\) be Jenkins--Strebel, let
\(X_t=\gamma_q(t)\), \(t\geq0\), be the associated unit-speed
Teichm\"uller ray, and let \(\delta_1,\ldots,\delta_r\) be the core curves
of the cylinders in the contracting foliation. Set
\(\Delta_q=\delta_1+\cdots+\delta_r\). Under the filling hypothesis,
\begin{equation}
  \lim_{t\to\infty}\frac{\mathcal E_{u_0}(X_t)}{t^2}
  =16\,\mathscr E_{\Delta_q}(u_0)>0.

\end{equation}

[Lemma lem.aux1 of arXiv:2607.10105, 'The four-dimensional Anderson model: a case study for critical SPDEs'] For the binomial coefficient, we have
\begin{equation}
\binom{m+n}{m}\leq \alpha^m\beta^n,
\end{equation} where $\alpha>1$ is arbitrary and $\beta=\beta(\alpha)>1$ depends only on $\alpha$. Similarly, for the multinomial coefficient, we have (where $n=n_1+\cdots +n_r$)
\begin{equation}
\binom{n}{n_1,\cdots,n_r}=\frac{n!}{n_1!\cdots n_r!}\leq\alpha^{n_1+2n_2+\cdots +rn_r}\cdot\beta^{n_1+\cdots +n_r},
\end{equation} where again $\alpha>1$ is arbitrary and $\beta=\beta(\alpha)>1$ depends only on $\alpha$.

In particular, if the $(n_j)$ are \emph{lacunary} as in Definition (def.lac of the paper), then we have 
\begin{equation}
\binom{n}{n_1,\cdots,n_r}\leq C^{n_1+\cdots +n_r}.
\end{equation}

[Lemma lem:conditional_boundedness_L2 of arXiv:2412.01645, 'Regularisation by Gaussian rough path lifts of fractional Brownian motions'] For $u \in \mathbb{D}^{1,2}(V \otimes \mathcal{H})$ we have with probability one
    \begin{equs}
        \mathbb{E}^B_s \|\delta_{\mathcal{H}_s^\perp}(u)\|^2_V \leq \mathbb{E}^B_s \left( \|\Pi_{\mathcal{H}_s^\perp} u\|^2_{V \otimes \mathcal{H}}+ \|\Pi_{\mathcal{H}_s^\perp \otimes \mathcal{H}_s^\perp} Du\|^2_{V \otimes \mathcal{H}\otimes \mathcal{H}} \right). 
    \end{equs}

