[Definition 2 of arXiv:2605.10609, '\Large \bf Stochastic curve shortening flow driven by a transport-type pure jump L\'evy no'] Let $u_0\in V$. An $H$-valued c$\grave{a}$dl$\grave{a}$g $\mathcal{F}_t$-adapted process $u:=\{u_t\}_{t\geq0}$ is called a strong solution to \eqref{c2eq6}, if \\
{\rm(i)} there exists a $dt\otimes\mathbb{P}$-equivalent class $\hat{u}$ of $u$ such that $\hat{u}\in L^2_{loc}([0,\infty);V)$, $\mathbb{P}$-a.s.;\\
{\rm (ii)} for all $t\in[0,\infty)$, the following equality
\begin{equation}
\begin{aligned} u(t)=&u_0+\int_0^tA\bar{u}(s)ds+\int_0^t\int_{\{|z|\leq1\}}\Big( \Phi(1,z,\bar{u}(s))-\bar{u}(s)\Big)\tilde{N}(dzds)\\
&+\int_0^t\int_{\{|z|>1\}} \Big(\Phi(1,z,\bar{u}(s))-\bar{u}(s)\Big) N(dsdt)\\
&+\int_0^t\int_{\{|z|\leq1\}} \Big(\Phi(1,z,\bar{u}(s))-\bar{u}(s)-\epsilon z\partial_x \bar{u}(s)\Big)\nu(dz)ds,\ \text{holds\ in}\ V^*,\ \mathbb{P}\text{-}a.s.,
\end{aligned}
\end{equation}
where $\bar{u}$ is a $V$-valued progressively measurable $dt\otimes\mathbb{P}$ version of $\hat{u}$.

[Theorem thm:key-area-p of arXiv:2606.06612, 'The limit shape and emergence of the \\ Discrete Gaussian level lines'] Fix $g\geq 0$, $n \geq 0$, and set $h = H+1-n$. The following hold for every subsets $F\subseteq V \subset\mathbb Z^2$ where $F$ is connected with $g$ holes. There exists constants $\delta_p, c > 0$ such that
        \begin{enumerate}
            \item[\emph{Mesoscopic range}] If $1 < p < 2$ and $|\partial F|\vee |\partial V| \leq O(L^{\frac23+\frac{\delta_p}5})$, or if $p > 2$ and $|\partial F|\vee |\partial V| \leq O(L^{2/3}e^{c\sqrt{\beta\log L}})$, then 
    \begin{align}{\widehat\pi}^{(p), 0}_V(\phi_x \geq -h,\, \forall x \in F) = (1+o(1))\exp\left(-\upxi^{(p)}_n|F|\right)\,.
    \end{align}
    \item[\emph{Macroscopic range}] If $1 < p < 2$ and $|\partial F| \vee |\partial V| \leq O( Le^{\sqrt{\log L}})$, then 
    \begin{align}\quad\;{\widehat\pi}^{(p), 0}_V(\phi_x \geq -h,\, \forall x \in F) \geq \exp\left(-\upxi^{(p)}_n|F| + O\big(\sqrt{L}e^{3\sqrt{\log L}}\big)\right)\,,
    \end{align}
    and if $\mathfrak{S}$ is the event that there are no disagreement polymers $\gamma$ in $\phi$ with $|\gamma| \geq \log L$, then        
\begin{align}{\widehat\pi}^{(p), 0}_V(\phi_x \geq -h,\, \forall x \in F \mid \mathfrak{S}) \leq \exp\left(-\upxi^{(p)}_n|F| + O\big(\sqrt{L}e^{3\sqrt{\log L}}\big)\right)\,.
    \end{align}
If $|F| \leq  \big(\frac{3\beta}{{\widehat\pi}^{(p)}_\infty(\phi_o > h)}\big)^2 $, then the last upper bound also applies to ${\widehat\pi}_V^0(\phi_x\geq -h,\,\forall x\in F)$. The same holds if $p > 2$ and $|\partial F| \vee |\partial V| \leq O(Le^{c\sqrt{\beta\log L}}))$, replacing the error of $O\big(\sqrt{L}e^{3\sqrt{\log L}}\big)$ by $O\big(\sqrt{L}e^{5c\sqrt{\beta\log L}}\big)$.
\end{enumerate}
The above statements also hold when replacing ${\widehat\pi}^{(p),0}_V$ by ${\widehat\pi}^{(p)}_\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{prop:transience_renorm_base}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel satisfying $J(x,y) = \Omega (d_G(x,y)^{-d \alpha})$ with $\alpha \in (1,2)$. 

    Let $\beta > \beta_{c}$. 

    We can choose $r_0$ sufficiently large such that for all tiles $\Tile{0}{j}$.

    \begin{equation}
        \mathbf{P}_{\beta}
        \left(
            \Tile{0}{j} 
            \text{ is good}
        \right)
        \geq
        1
        -
        \xi_0.
    \end{equation}

[Lemma 30 (Uniformly bounded predictive variance) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] \label[lemma]{lem:gp-pointvar}
Assume \eqref{eq:gp-basis}. Then  for every $t\ge0$ and every $J\ge1$,
    \begin{equation}
    \sup_{x\in\mathcal X}v_{\Pi_t}(x)
    +\sup_{x\in\mathcal X}v_{Q_t^{(J)}}(x)
    \lesssim 1.
    \end{equation}

