[Lemma L:int_D:LB of arXiv:2604.08129, 'Polarity of points for Gaussian random fields in critical dimension'] There exist constants $\delta_2\in(0,1)$ and  $C_2\in(0,\infty)$ such that for
any $\varepsilon \in (0,\delta_2)$ and any $n$ of the form $n=2^p$ for some 
$p\in{\mathbb N}^+$ with $n \le \log\log\log(1/\varepsilon)$, there is a subset $D$ of 
$B_{\varepsilon^{\beta}}^n$ with the following properties:
\begin{enumerate}
\item[\rm (i)] Every $(t_1, \dots, t_n) \in D$ satisfies 

\begin{align}
\sigma(|t_1|) \ge 2^{-p}\varepsilon,
\end{align}
and 
\begin{align}
\sigma(d(t_i, F_k)) \ge 2^{k-p} 
\varepsilon
\end{align}
 for all $k$ and $i$ 
with $0 \le k < p$ and $2^k < i \le 2^{k+1}$;
\item[\rm (ii)] Let $\mathcal{J}_n(D)$ denote the integral
    \[
    \mathcal{J}_n(D) := \int_D \frac{1}{\sigma^d(|t_1|)} \prod_{0 \le k < p} \prod_{2^k < i \le 2^{k+1}} \frac{1}{\sigma^d(d(t_i, F_k))} \, dt_1 \cdots dt_n.
    \]
Then, the following estimate holds:
    \begin{align}
    \mathcal{J}_n(D) \ge C_2^n 2^{-p} \prod_{0 \le k < p} \left[ (2^k)! \cdot \left( 2^{k-p} \, \Psi(\varepsilon) \right)^{2^k} \right],
    \end{align}
    where $\Psi$ is defined in (equation E:psi of the paper).
\end{enumerate}

