body:
[Lemma lem:new-L(Bt|H) of arXiv:2606.10257, 'Downward conditional monotonicity gives survival and extinction for contact processes in r'] For the MMPP with initial distribution $B_0\sim x$ on $S$, the conditional distribution of $B_t$ before the first arrival is given by
	\begin{equation}
		\mathcal L(B_t\mid\tau_1>t)=x_t=\frac{xe^{t(T-D_\alpha)}}{xe^{t(T-D_\alpha)}\boldsymbol1}.
	\end{equation}
	Conditioned on the first arrival time being precisely $\tau_1=t_1$, the conditional distribution of $B_{t_1}$ is given by 
	\begin{equation}
		\mathcal L(B_{t_1}\mid\tau_1=t_1)=\frac{x_{t_1}D_\alpha}{x_{t_1}D_\alpha\boldsymbol1}=\frac{xe^{{t_1}(T-D_\alpha)}D_\alpha}{xe^{{t_1}(T-D_\alpha)}D_\alpha\boldsymbol1}.
	\end{equation}
	Consider arrival history $\mathcal{H}_{t}=\{\tau_1=t_1,\ldots,\tau_n=t_n\}$, which implicitly assumes that $t\geq t_n$ and that $\tau_{n+1}>t$. Then, 
	\begin{equation}
		\mathcal L(B_t\mid \mathcal{H}_{t})=
		\frac{x\prod_{j=1}^{n}\left[e^{(t_j-t_{j-1})(T-D_\alpha)}D_\alpha\right] e^{(t-t_{n})(T-D_\alpha)}}{x\prod_{j=1}^n\left[e^{(t_j-t_{j-1})(T-D_\alpha)}D_\alpha\right] e^{(t-t_{n})(T-D_\alpha)}\boldsymbol1}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 (Master inequalities) of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Assume the set-up and conditions of Proposition~\ref{prop:global}. For any fixed $p\ge 2$, $n,S\in\N$ and $\xi> 0$ it holds that
\begin{equation}
\begin{split}
\Psi^{(p)}(n,S)\lesssim &\Psi^{(p)}(n,S-1) + \Psi^{(p)}(n-1,S+2L)+\frac{1}{N^{1/2}}\Psi^{(p)}(n,S+2L)+ \frac{1}{N}\Psi^{(p)}(n+1,S+1)\\
+&\sum_{r=1}^{p-2}\left(\frac{1}{N^{r-1/2}}+\frac{1}{N^{(r+1)/2}}\right)\Psi^{(p-r)}(n-r,S+2L)\\
+&\sum_{r=1}^{p-2} \frac{1}{N^{(r-1)/2}} \Psi^{(p-r)}(n-r-1,S+2L) + N^{-(p-2)/2+\xi} \left( N^{-1} + \bm{1}_{n\ge p}\right),
\end{split}

\end{equation}
where $L=L^{(p)}(S):=p+S+4$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 5 (Definition 3.1 of \cite{Chen2024}) of arXiv:2608.26598, 'Pinching cones for positive isotropic curvature in dimensions seven and eight'] For $0<b\le b_{max,2}$, let $\mathcal{E}(b)$ denote the set of all algebraic curvature tensors $S$
        for which there exists a tensor $T\in S^2(\mathfrak{so}(n))$ satisfying:
        \begin{enumerate}
            \item $T\geq 0$;
            \item $S-T\in\CPIC$ in the relaxed sense of Remark \ref{rem:relaxed} below;
            \item $\Ric(S)_{11}+\Ric(S)_{22}+\frac{2\gamma}{n}\Scal(S)\geq 0$ for every orthonormal pair
            $\{e_1,e_2\}$;
            \item for every orthonormal frame $\{e_1,\dots,e_n\}$,
            \begin{equation}
                \Ric(S)_{22}-\Ric(S)_{11}\leq\omega^{\frac12}\Scal(S)^{\frac12}
                \Bigl(\sum_{p=3}^n(T_{1p1p}+T_{2p2p})\Bigr)^{\frac12}.
            \end{equation}
        \end{enumerate}
        We then define $C(b)=l_{a,b}(\mathcal{E}(b))$.

[Theorem of arXiv:2608.10415, 'Continuous random variables'] When flipping a usual coin $n$ times in a row:
\begin{enumerate}
\item $E({\rm heads})=n/2$.

\item $E({\rm tails})=n/2$.

\item $E(a\times{\rm heads}+b\times{\rm tails})=n(a+b)/2$.
\end{enumerate}

[Thmx 5 (Hard-to-soft edge transition, \cite{DLV}) of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] \begin{align}
a^{-4/3}(\Bessel_{\beta,2a}-a^2)\Rightarrow \Airyb, \qquad \text{as $a\to \infty$}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

