[Lemma 4 of arXiv:2606.22044, 'Degenerate Stochastic Delay Modified Equation: Approximation of Stochastic Variance Reduce'] Let $Y_{t}$ be defined by (\ref{sfde-0-0}) and $\eta\in(0,1)$. Then it follows for any $y\in\mathbb{R}^{d}$ and $t\in[0,m\eta]$,
\begin{align}
\mathbb{E}|Y_{t}^{y}|^{2}\leq C_{1}(1+|y|^{2}+\mathbb{E}|z_{0}|^{2})e^{C_{2}m\eta}
\end{align}
and
\begin{eqnarray}
\mathbb{E}|Y_{t}^{y}-y|^{2}
&\le&C_{1}(1+|y|^{2}+\mathbb{E}|z_{0}|^{2})e^{C_{2}m\eta}t(t+\eta),
\end{eqnarray}
where $C_{1}$ and $C_{2}$ are some positive constants not depending on $m$ or $\eta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem_Omega of arXiv:2609.01250, 'Global regularity for 2D gravity water waves with two retreating point vortices'] Under the bootstrap assumptions, we have
    \begin{equation}
        \norm{\Omega_0\tilde{\theta}_\alpha}_{H^{s-1}}+\norm{\Omega_0\tilde{\theta}_\alpha}_{W^{s-2,\infty}}\lesssim\epsilon t^{\delta_0},
    \end{equation}
    \begin{equation}
        \left\lVert\Omega_0(\zeta_\alpha-1)\right\rVert_{H^{s-1}}\lesssim\epsilon^2t^{\frac{1}{2}}+\epsilon t^{\delta_0}
    \end{equation}
    and
    \begin{equation}
        \left\lVert\Omega_0(\zeta_\alpha-1)\right\rVert_{W^{s-2,\infty}}\lesssim\epsilon^2t^{\frac{1}{4}}\ln (2+t)+\epsilon t^{\delta_0}.
    \end{equation}

