[Lemma 12 (Persistence of cutoff moments and the condensate) of arXiv:2609.01436, '2609.01436'] Assume \cref{ass:CL}.  Let $F_t$ be a conservative isotropic measure
solution with mass $N>0$, energy $E>0$, and $c_0=\sqrt{NE}$.  For every
bounded, nonnegative, convex
$\varphi\in C_b^{1,1}([0,\infty))$,
\begin{equation}
 \int_{[0,\infty)}\varphi(x)\,dF_t(x)
 \geq e^{-c_0(t-s)}
 \int_{[0,\infty)}\varphi(x)\,dF_s(x),
 \qquad 0\leq s\leq t.
\end{equation}
In particular,
\begin{equation}
 N_{0,2}(F_t,\varepsilon)
 \geq e^{-c_0(t-s)}N_{0,2}(F_s,\varepsilon),
 \qquad \varepsilon>0,
\end{equation}
and
\begin{equation}
 F_t(\{0\})
 \geq e^{-c_0(t-s)}F_s(\{0\}).
\end{equation}

