body:
[Lemma 18 of arXiv:2605.11877, 'Fluctuation analysis for a randomly perturbed dynamical system with state-dependent impuls'] Let $B_t$ be a standard one-dimensional Brownian motion. Then, for any fixed $\sfT>0$, $\alpha \in (0,\tfrac{1}{2})$, we have
 	\begin{equation}
 		C_\alpha \triangleq \BE[\|B\|_\alpha] < \infty, \quad \text{and further} \quad 
 		\BE\left[\sup_{\substack{0 \le s < t \le \sfT\\|t-s| \le \delta}} |B_t - B_s| \right] \le C_\alpha \delta^\alpha \quad \text{for all $\delta \in (0,1)$.}
 	\end{equation}

[Definition 18 of arXiv:2608.26803, 'On bubbling of Fueter maps'] Let $(M, g_M)$ be a closed oriented Riemannian $3$--manifold and suppose that $(X, g_X, I_1, I_2, I_3)$ is a hyperk\"ahler manifold. Choose a fiberwise isometric identification
    \begin{align*}
        \cI: STM \to S(X).
    \end{align*} 
    Now, for $m \geq 2$ consider the space of \textbf{Hamiltonian perturbations}
    \begin{align*}
        \cP^m \coloneq C^m(M \times X, \bR).
    \end{align*}
    For any $H \in \cP^m$, denote by $\nabla^{g_X} H \in C^{m-1}\Gamma(M \times X, \pr_2^* TX)$ the gradient of $H$ in the direction of $X$. Now, this data yields the \textbf{perturbed Fueter operator} acting on maps $f: M \to X$ by
    \begin{align*}
        \cF_H f \coloneq \sum_{a=1}^3 \cI(e_a) Tf(e_a) - \nabla^{g_X} H (f),
    \end{align*}
    where $\{e_a \}$ is an orthonormal frame of $M$ at a point.

    For any positive integer $n$, define the \textbf{ordered configuration space of $n$ points on $M$} by
    \begin{equation*}
        \Conf_n (M) = \{(x_1, \dots, x_n) \in M^n \; | \; x_i \neq x_j \; \textnormal{for } i \neq j\}.
    \end{equation*}

[Definition def.LambdaG of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] A cube ${\scaleobj{1}{\square}}$ is an element in $\Lambda(\mathcal{G}, t, C)$ if it satisfies the following three conditions:
		\begin{itemize}
			\item ${\scaleobj{1}{\square}}$ is good: ${\scaleobj{1}{\square}} \in \mathcal{G}$;
			\item Control of the averaged $\ell^t$ moment:
			\begin{align}
				\frac{1}{|{\scaleobj{1}{\square}}|} \sum_{x\in {\scaleobj{1}{\square}}}\vert {\scaleobj{1}{\square}}_{\mathcal{S}^{loc}_{\mathcal{G}}}(x)\vert^t \leqslant C
			\end{align}
			\item Control of the maximum partition cube:
			\begin{align}
				\sup_{x \in {\scaleobj{1}{\square}}} \size( {\scaleobj{1}{\square}}_{\mathcal{S}^{loc}_{\mathcal{G}}} (x)) \leqslant \size({\scaleobj{1}{\square}})^{\frac{d}{d+t}}.
			\end{align}
		\end{itemize}

[Defn 18 (Pfaffian $L$-ensemble) of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $\mathcal{Z}$ be a set of points, and let $L:\mathcal{Z}\times\mathcal{Z}\to \mathbb{C}^{2\times2}$ be a skew-symmetric $2\times2$-matrix valued function. A measure $\mu$ on $2^\mathcal{Z}$ is a \emph{Pfaffian $L$-ensemble} on $\mathbb{Z}$ if its correlation function $\rho$ is given by
	\begin{equation}

		\rho(X) = \frac{\Pf L_X}{\Pf(J + L)},\quad X \subset \mathcal{Z}.
	\end{equation}
	Here $L_X$ denotes the $(2|X|)\times(2|X|)$ matrix $[L(x,x')]_{x,x'\in X}$, while $\Pf(J + L)$ denotes the Fredholm Pfaffian of $L$ on $\ell^2(\mathcal{Z})$ (which coincides with the Pfaffian of the matrix $J + L$ when $\mathcal{Z}$ is finite).

[Thm cov_presc of arXiv:2505.19622, 'Discrete harmonic polynomials in multidimensional orthants'] Let $a,b,c \geqslant 0$ and $\delta$ be defined as in (equation eq:cov_dim3 of the paper). Then the following assertions are equivalent: 
\begin{itemize}
    \item There exists a small step model $\mathcal S$ such that $\delta= {\cov}(\chi_{\mathcal S})$;
    \item The parameters satisfy $a^2 +b^2 +c^2 +2abc < 1$;
    \item The matrix $\delta$ is positive definite.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2609.03736, '2609.03736'] For every $\varepsilon>0$,
\begin{equation}
 \Tr\bigl(\mathcal A_n(I-z_{n,\varepsilon})\bigr)\longrightarrow0,
 \qquad
 \tr\bigl(G^{\otimes n}(I-q_{n,\varepsilon})\bigr)\longrightarrow0.

\end{equation}

