[Definition 25 of arXiv:2607.29495, 'Fast Mixing for Low-Temperature Potts Models via Poisson Trees'] Let $\ell$ be a positive integer and
let $T\sim \cT$.  For every vertex $v\in V(T)$, 
let $T_{v,\ell}$ be the maximal subtree of~$T_v$ in which each root-to-leaf path contains at most $\ell$ good vertices, excluding the root~$v$.

[Lemma lem:f'=f^2 of arXiv:2508.18807, '{\bf Critical long-range percolation I: High effective dimension}'] Let $f:(0,\infty)\to (0,\infty)$ be differentiable and let $A$, $\alpha$, and $r_0$ be positive constants.
\begin{enumerate}
  \item If $f'(r) \geq A r^{-\alpha-1} f(r)^2$ for every $r\geq r_0$ then $f(r) \leq A^{-1}\alpha r^\alpha$ for every $r\geq r_0$.
  \item If $f(r)\to\infty$ as $r\to \infty$ and $f'(r) \leq A r^{-\alpha-1} f(r)^2$ for every $r\geq r_0$  then $f(r) \geq A^{-1}\alpha r^\alpha$ for every $r\geq r_0$.
  \item If $f(r)\to\infty$ as $r\to\infty$ and $f'(r)=A(1-h(r))r^{-\alpha-1}f(r)^2$ for some bounded measurable function $h:(0,\infty)\to \mathbb R$ then 
  \[
f(r) = \frac{\alpha}{A}r^\alpha\left(1- \alpha r^\alpha \int_r^\infty h(s)s^{-\alpha-1}\dif s\right)^{-1}
  \]
  for every $r>0$.
\end{enumerate}

