[Lemma 10 of arXiv:2608.28245, 'I-FLOP: Fast Learning of Order and Parents from Interventional Data'] Fix $v\in V$ and $Z\subseteq V\setminus\{v\}$.
	Under Assumptions~\ref{assump:data-generating process}--\ref{assump:env-proportions}, the following statements hold simultaneously over the finitely many candidate parent sets contained in $Z$ with probability tending to one.
	\begin{enumerate}
		\item If $P,Q\subseteq Z$ satisfy $\sigma^{2}_{v\mid Q,\mathrm{pool}} < \sigma^{2}_{v\mid P,\mathrm{pool}}$, then $s_{v}^{\mathrm{tf\text{-}pool}}(Q) < s_{v}^{\mathrm{tf\text{-}pool}}(P)$.

		\item If $u\in P\subseteq Z$ and $\sigma^{2}_{v\mid P\setminus\{u\},\mathrm{pool}} = \sigma^{2}_{v\mid P,\mathrm{pool}}$, then $s_{v}^{\mathrm{tf\text{-}pool}}(P\setminus\{u\}) < s_{v}^{\mathrm{tf\text{-}pool}}(P)$.
	\end{enumerate}

