[Lemma 17 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Supermartingality of Entropy (Lemma 39, \cite{anari:koehler:vuong2024})}


    Assume $\nu_t$ is a stochastic localization process as in Definition \ref{def:stoclocproc}. Let $K$ be any Markov kernel. Then, the stochastic process $t \mapsto \E_{y\sim \nu_t K}[\ent[\nu_t | K \triangleright y]{f}]$ is a supermartingale. Let $(\mathcal F_t)_{t\geq 0}$ be the filtration generated by the Brownian motion $B_t$ of the process. Equivalently, for all $0 \leq s < t$
    \begin{align*}
        \E[\E_{y\sim \nu_t K}[\ent[\nu_t | K \triangleright y]{f}] | \mathcal F_s] 
        \leq \E_{y\sim \nu_s K}[\ent[\nu_s | K \triangleright y]{f}].
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 11 of arXiv:2506.17109, 'Limit theorems under nonlinear expectations dominated by sublinear expectations'] Let a nonlinear expectation $\mathbb{\tilde{E}}[\cdot]$ be
dominated by a sublinear expectation $\mathbb{\hat{E}}[\cdot]$ on
$(\Omega,\mathcal{H})$, and let $\{(X_{n},Y_{n})\}_{n=1}^{\infty}$ be a
sequence of $2d$-dimensional random vectors such that $(X_{n+1},Y_{n+1}
)\overset{d}{=}(X_{1},Y_{1})$ and $(X_{n+1},Y_{n+1})$ is independent of
$(X_{1}$,$\ldots$,$X_{n}$,$Y_{1}$,$\ldots$,$Y_{n})$ for $n\geq1$ under
$\mathbb{\tilde{E}}[\cdot]$ and $\mathbb{\hat{E}}[\cdot]$ respectively.
Suppose that
\[
\mathbb{\hat{E}}[X_{1}]=\mathbb{\hat{E}}[-X_{1}]=0\text{ and }\lim
_{N\rightarrow \infty}\mathbb{\hat{E}}\left[  (|X_{1}|^{2}-N)^{+}
+(|Y_{1}|-N)^{+}\right]  =0.
\]
Then, for each $\phi \in C_{b.Lip}(\mathbb{R}^{2d})$, we have
\begin{equation}
\lim_{n\rightarrow \infty}\frac{1}{n}\mathbb{\tilde{E}}\left[  n\phi \left(
\frac{1}{\sqrt{n}}\sum_{i=1}^{n}X_{i},\frac{1}{n}\sum_{i=1}^{n}Y_{i}\right)
\right]  =u^{\phi}(1,0,0),
\end{equation}
where $u^{\phi}$ is the unique viscosity solution of the following PDE:
\begin{equation}
\partial_{t}u-\tilde{G}(D_{x}^{2}u,D_{y}u)=0\text{, }u(0,x,y)=\phi
(x,y),
\end{equation}
and
\begin{equation}
\tilde{G}(A,p):=\mathbb{\tilde{E}}\left[  \frac{1}{2}\langle AX_{1}
,X_{1}\rangle+\langle p,Y_{1}\rangle \right]  \text{ for }(A,p)\in
\mathbb{S}_{d}\times \mathbb{R}^{d}.
\end{equation}

