[Theo integralsqW of arXiv:2510.23430, 'On the Martin boundary for discrete TASEP'] {BW17},[BK21]}] Let $\lambda$ be a partition and $k$ be an integer such that $\lambda_1\leq k$. Assume that there exists a complex positively-oriented simple contour $\mathcal C$  such that
\begin{itemize}
\item $0$ and $s/\xi$ are inside the contour $\mathcal C$;
\item all points $(s\xi)^{-1}$ is outside of the contour $\mathcal C$;
\item the image $q\mathcal C$ of the contour $\mathcal C$ under the multiplication by $q$ is inside $\mathcal C$.
\end{itemize}
\begin{equation*}
\mathbb{F}_{\lambda}(x_1,\dots, x_n\mid\xi,s)\\
=\xi^{-|\lambda|}\oint_{\mathcal C}\frac{du_1}{2\pi\mathbf i u_1}\dots\oint_{\mathcal C}\frac{du_k}{2\pi\mathbf i u_k}\prod_{i<j}\frac{u_i-u_j}{u_i-qu_j}\prod_{i=1}^k\(\frac{(1-s\xi u_i)^{\lambda_i'-1}}{(u_i-\xi^{-1}s)^{\lambda'_i}}\prod_{j=1}^n\frac{1-u_ix_j}{1-u_i\xi s}\).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:parisi-maximal-estimate of arXiv:2607.29330, 'Large deviations for the maximum of\\ the generalized TAP free energy'] For the fixed finite-step order parameter $\zeta$, as
		$N\to\infty$,
		\begin{equation}
			\mathbb{E}
			\sup_{\substack{q\in[0,1]\\ \alpha\in\mathbb{N}^L}}
			\left\{
			u_\alpha
			+
			\sum_{i=1}^N
			\Phi_\zeta(q,B_q^i(\alpha))
			-
			N\Phi_\zeta(0,0)
			\right\}
			\le
			\mathbb{E}\max_{\alpha\in\mathbb{N}^L}u_\alpha
			+
			o(N).
		\end{equation}

[Lem exs thT of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] There exists a constant $a_3 \in (0,1)$ such that, for any $x \in M$ and $t>0$,
  \begin{equation}
    \lim_{\delta \downarrow 0}
    \hat{P}_{\diag(x)}
    \left(
      \sigma^{\mathrm{G}}(\delta;a_3) \leq t
    \right)
    =
    1.
  \end{equation}

[Lemma 7 of arXiv:2609.00867, '2609.00867'] For every finite signed measure \(\nu\) and every \(\tau\in(0,1]\),
\begin{equation}
 \iint g_\tau(x-y)\,\nu(\dd x)\nu(\dd y)
 =\frac1{\Gamma((d-s)/2)}\int_\tau^\infty
 t^{(d-s)/2-1}e^{-m^2t}\norm{p_{t/2}*\nu}_2^2\dd t
 \ge0.
\end{equation}
Consequently, \((g_\tau)_\rho^\circ\) is positive semidefinite, and its
diagonal \(d_\tau(x):=(g_\tau)_\rho^\circ(x,x)\) satisfies
\begin{equation}
 0\le d_\tau(x)\le2g_\tau(0)\le C_{d,s}\tau^{-s/2},
 \qquad x\in\mathbb R^d.
\end{equation}

[Proposition 3 (Hoeffding inequality) of arXiv:2604.21143, 'Quantitative homogenization for the critical long-range random conductance model'] Let $(X_n)_{n \in \mathbb{N}}$ be independent random variables satisfying $\E[X_n] = 0$ and $|X_n| \le 1$ almost surely, and let $(a_n)_{n \in \mathbb{N}}$ be a sequence of real numbers such that $\sum_{n=1}^\infty a_n^2 < \infty$.
		Then the series $\sum_{n=1}^\infty a_n X_n$ converges almost surely and in $L^2$.
		Moreover, there exists a universal constant $C < \infty$ such that
		\begin{equation} 
			\left| \sum_{n=1}^\infty a_n X_n \right| \leq \mathcal{O}_2\left( C\Bigl(\sum_{n=1}^\infty a_n^2\Bigr)^{1/2} \right).
		\end{equation}

[Lem lower-bound-prob of arXiv:2410.24170, 'Persistent hubs in CMJ branching processes with independent increments and preferential at'] Suppose that $(X_{i})_{i \in \mathbb{N}_{0}}$ and $(X'_{i})_{i \in \mathbb{N}_{0}}$ are independent sequences of exponential random variables, with $X_{i} \sim X'_{i} \sim \exponentialrv\left( f(i) \right)$. Suppose, moreover, that $n, \phi_{n} \in \mathbb{N}_{0}$ are given such that
    $n < \phi_{n} - 1$, and  
    \begin{equation} 
    \frac{3\left(\sum_{i=1}^{n-1} \frac{1}{f(i)}\right)^2}{\sum_{i=n}^{\phi_{n} - 1} \frac{1}{f(j)^2}} \leq \frac{1}{2}.
    \end{equation}
    Then, 
    \begin{equation} 
        \Prob{\sum_{i=1}^{\phi_{n} - 1} X_{i} < \sum_{i=n}^{\phi_{n}-1} X'_{i}} > \frac{1}{176}. 
    \end{equation}

