[Lemma 67 of arXiv:2607.18104, '2607.18104'] Fix some $M\in \N$ and $n\in \N$. 

Assume that for all $i\in \lbr M\rbr$, we have  $\hfix^{\per,(i),\varepsilon}_0$ in $\UCp$ converging to some $\hfix^{\per,(i)}_0 \colon \mathbb{T}\rightarrow \R$ as $\varepsilon \rightarrow 0$ with respect to the UC topology, and initial data $\hfix^{(i),1,\varepsilon,j}_0$ and $\hfix^{(i),2,\varepsilon,j}_0$ in $\UC$ with
\begin{equation}
    \begin{split}
        \hfix^{(i),1,\varepsilon,j}_0(x) &= \hfix^{\textup{patch},n^{-1},\varepsilon}\big(\hfix^{\per,(i),\varepsilon}_0;x,(j-1)n^{-1}\big) \ \forall x\in \Big[ -\frac{1}{8}, \frac{5}{8}\Big] \\
        \hfix^{(i),2,\varepsilon,j}_0(x) &= \hfix^{\textup{patch},n^{-1},\varepsilon}\big(\hfix^{\per,(i),\varepsilon}_0;x,(j-1)n^{-1}\big) \ \forall x\in \Big[ \frac{3}{8}, \frac{9}{8}\Big] , 
    \end{split}
\end{equation}
 such that $\hfix^{(i),1,\varepsilon,j}_0$ and $\hfix^{(i),2,\varepsilon,j}_0$ converge to some $\hfix^{(i),1,j}_0$ and $\hfix^{(i),2,j}_0$ in $\UC$. Then for all $j\in \N$, there exist full-space KPZ fixed points $\hfix^{1,j}$ and $\hfix^{2,j}$ such that as $\varepsilon \rightarrow 0$
\begin{equation}
\begin{split}
    \hAeps_{1,j}\big( \hfix^{(i),1,\varepsilon,j}_0;\cdot,t\big) &\rightarrow \hfix^{1,j}\big(\hfix^{(i),1,j}_0;\cdot,t\big) ,  \\
    \hAeps_{2,j}\big( \hfix^{(i),2,\varepsilon,j}_0;\cdot,t\big) &\rightarrow \hfix^{2,j}\big(\hfix^{(i),2,j}_0;\cdot,t\big) , 
\end{split}
\end{equation} jointly in $i\in \lbr M \rbr$, and $t \in [0,n^{-1}] \cap \mathcal{T}$ with respect to the topology of uniform convergence on compact subsets. On the left sides of \eqref{eq:ASEPconvPatchtwice}, 
the functions $\hAeps_{1,j}\big(\hfix_0^{(i),1,\varepsilon,j};\cdot,t\big)$ and $\hAeps_{2,j}\big(\hfix_0^{(i),2,\varepsilon,j};\cdot,t\big)$ are coupled according to $\Ppatch$. On the right sides of \eqref{eq:ASEPconvPatchtwice}, the functions $\hfix^{1,j}(\hfix^{(i),1,j}_0;\cdot,t)$ are coupled through \eqref{eq:VariationFixedPeriodic} for all $i\in \lbr M \rbr$  under the same directed landscape $\mathcal{L}^{1,j}$; the functions $\hfix^{2,j}(\hfix^{(i),2,j}_0;\cdot,t)$ are coupled through \eqref{eq:VariationFixedPeriodic} for all $i\in \lbr M \rbr$  under the same directed landscape $\mathcal{L}^{2,j}$, and $\mathcal{L}^{1,j}$ and  $\mathcal{L}^{2,j}$  are coupled under some probability measure $\mathbf{P}$, so that
\begin{equation}
  \mathbf{P}\big(  \mathcal{A}^{j}_{n} \big) \geq 1 - C_0\exp(-c_0 n ) 
\end{equation}
holds for some $c_0,C_0>0$, which do not depend on $j$ and $n$, and all $n\in \N$.

[Theorem thm2ch5 of arXiv:2512.09308, 'On asymptotic behavior of solutions to random fractional Riesz-Bessel equations with cycli'] Let $u(t,x)$, $t > 0$, $x \in \mathbb{R}$, denote the random field defined by equations~{\rm ((modch5 of the paper))} and~{\rm((modCch5 of the paper))} with the random initial condition $\xi(x),$ which covariance function satisfies Assumption~~{\rm (Asumptionmain of the paper)} with $A_0\neq0$. Then, for $\alpha>\kappa_0/2$, if $\varepsilon \to 0$, the finite-dimentional distributions of the random fields
\[
U_\varepsilon(t,x) = \varepsilon^{-\frac{\kappa_0\beta}{2\alpha}}u\left( \frac{t}{\varepsilon}, \frac{x}{\varepsilon^{\beta/\alpha}} \right), \, t>0, x\in \mathbb{R},
\]
converge weakly to the finite-dimensional distributions of the zero-mean Gaussian field
\begin{equation}
    U_0(t,x) = \sqrt{c_{2}(\kappa_0)A_{0}}\int_{\mathbb{R}} \frac{e^{i \lambda x} E_\beta(-\mu|\lambda|^\alpha t^\beta)}{|\lambda|^{(1-\kappa_0)/2}}W(d\lambda), \,
\end{equation}
which has the covariance function
\begin{align}
     {\rm Cov}(U_0(t,x), U_0(t', x')) =& 2A_{0}c_{2}(\kappa_0) \int_{0}^{+\infty} \frac{\cos\left( \lambda(x - x') \right)}{|\lambda|^{1 - \kappa_0}} E_\beta(-\mu|\lambda|^{\alpha} t^\beta)\nonumber\\&\times E_\beta(-\mu|\lambda|^{\alpha} (t')^\beta) \,d\lambda.
\end{align}

