body:
[Proposition thm:ST1.1 of arXiv:2411.00748, '\bfseries Central limit theorems for the nearest neighbour embracing graph in Euclidean an'] Let $F$ be an integrable Poisson functional such that $\mathbb{E} \int (D_x F)^2 \lambda (dx) < \infty$ and
    \begin{equation}
        \mathbb{E} \Big[\int (D_{x,y} F)^2 \lambda^2(d(x,y))\Big] \le c \mathbb{E} \Big[\int (D_x F)^2 \lambda(dx)\Big]
    \end{equation}
    for some constant $c \ge 0$. Then,
    \[
    \operatorname{Var} F \ge \frac{4}{(c+2)^2} \mathbb{E} \Big[\int (D_x F)^2 \lambda(dx)\Big].
    \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 10 (Upper bound on balls) of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] For any $\mu \in \mathcal{M}_1(\mathbb{R})$, we have

\begin{align}

\limsup_{\delta \searrow 0} \limsup_{N \to +\infty} \frac{1}{N} \ln \overline{\Pi}_{N}[B(\mu,\delta)] \leq - I[\mu] \, .

\end{align}

Similarly, for any $\mu \in \mathcal{M}_{1,\mathsf{c}}(\mathbb{R})$, we have

\begin{align}

\limsup_{\delta \searrow 0} \limsup_{N \to +\infty} \frac{1}{N}\ln \overline{\Pi}_{N,\mathsf{c}}[B_{\mathsf{c}}(\mu,\delta)] \leq - I[\mu] \, .

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2607.14718, 'Anchored Nash inequalities and heat kernel bounds for a class of random conductance models'] Let $d \geq 3$. Suppose that Assumptions~\ref{a1-4} and \ref{a1-5} hold, and there exist $m_{0} > d$ and $p \in \bigl(\max\{1, d/(m_{0}-2)\}, \infty\bigr]$, $q \in (1, \infty]$ satisfying \eqref{a1-1-2} such that, for $\prob_{0}$-a.e.\ $\omega$, \eqref{t1-4-3}, \eqref{t1-4-2} and

  \begin{align}
    \sup_{R \geq 1} \Norm{1 \vee \mu_{m_{0}}^{\omega}}{p, B^{\omega}(0, R)}
    \;<\;
    \infty
  \end{align}

  hold. Then, for $\prob_{0}$-a.e.\ $\omega$, there exists a random constant $C_{11}(\omega) \in (0, \infty)$ such that for all $t > 0$,

  \begin{align}
    p^{\omega}(t, 0, 0) \;\leq\; C_{11}(\omega)\, t^{-d/2}.
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 16 (Limit of $D(t)$) of arXiv:2605.21459, 'Network evolution with self-reinforcement'] For any $\delta >-1$, there exists a non-negative random variable $X_\delta$ with $\E[X_\delta] >0$ such that, almost surely and in $L^1$, as $t \to \infty$,
\begin{equation}
    \eee^{-t/\phi(\delta)} D(t) \longrightarrow X_\delta,
\end{equation}
with $\phi(\delta)$ as in \eqref{phidef}, so that
\begin{equation}
    \frac{1}{\phi(\delta)} = \frac{1}{2} \left( \sqrt{1 + 4\gamma} - 1 \right). 
\end{equation}

