[Lemma 11 of arXiv:2605.02713, '2605.02713'] \begin{itemize}
		\item[(i)] If $\sigma_n^2 \gg  (1 - \alpha_n^2) $ consider $f=\sum_{q=m}^p c_q H_q$. Then 
		\begin{align*}
			\hat{S}_{n,t}(f) &= c_p \hat{S}_{n,t}(H_p)  + R_{n,t}(f), 
		\end{align*}
		where $R_{n,t}(f) \longrightarrow_{L^2} 0$ for $n \to \infty$. Moreover,  with $C_{p,l}=\frac{p!}{l! (p-2l)! 2^l}$,  \begin{align*}
			\hat{S}_{n,t}(H_p) &= \frac{  \big( \mathrm{Var} X_{1,n} \big)^{p/2} \sum_{i=1}^{\lfloor nt \rfloor}   \sum_{l=0}^{\lfloor (p-1)/2 \rfloor} C_{p,l} H_{p-2l}  \big( Z_{i,n} \big)}{\sqrt{\mathrm{Var}S_{n,1}(H_p)}} \big(1 + o_{n,\mathrm{unif}}(1) \big) \quad\text{and}\\
			\mathrm{Var} S_{n,t}(H_p) &=  \left( \mathrm{Var} X_{1,n} \right)^{p}  \sum_{l=0}^{\lfloor p/2 \rfloor}  C_{p,l}^2 (p-2l)! \Lambda_{p-2l}(n,t)\big(1 + o_{n,\mathrm{unif}}(1) \big) . 
		\end{align*}
		\item[(ii)] If $\sigma_n^2 = \sigma^2 (1 - \alpha_n^2) $ consider $f = \sum_{q=m}^\infty c_q H_q ( \cdot; \sigma^2) \in L^2 \left(\mathcal{N} \left(0, \sigma^2 \right) \right)$. Then 
		\begin{align*}
			\mathrm{Var} S_{n,t}(f) = \sum_{q=m}^\infty  c_q^2 q!  \left(   \sigma^2  \right)^q \Lambda_{q}(n,t) 
		\end{align*}  
		for any $t\in [0,1]$.
		\item[(iii)] If $\sigma_n^2 \ll  (1 - \alpha_n^2) $ consider  $f=\sum_{q=m}^p c_q H_q$. Then 
		\begin{align*}
			\hat{S}_{n,t}(f)  = \frac{ \left( \mathrm{Var} X^{(n)} \right)^{m_*/2}  \sum_{i=1}^{ {\lfloor nt \rfloor} } \sum_{r=1}^{m_*} D_r^{(m_*,m,p)}     H_{r}(Z_{i,n})  }{\sqrt{\mathrm{Var} S_{n,1}(f)}} + R_{n,t}(f),
		\end{align*}
		where $R_{n,t}(f) \longrightarrow_{L^2} 0$ for $n \to \infty$, 
		\begin{align*}
			D_r^{(m_*,m,p)}  =   \sum_{s=0}^{\lfloor p/2 \rfloor}  \mathds{1}_{A_{s,r}} (m_*) \sum_{u=0}^{\lfloor p/2 \rfloor}  \mathds{1}_{B_{m,p}}(m_*+2u) \,  c_{m_*+2u} \,  C_{m_*+2u,s+u} \,  \binom{s+u}{s} (-1)^{u} ,
		\end{align*}
		where the sets are $A_{s,r}= \{ x : x=2s+r \}$ and $B_{m,p} = \{ y : m \leq y \leq p \}$, and  $m_* := \min \{w \geq 1:  \sum_{r=1}^p D_r^{(w,m,p)}  \neq 0 \}$.  Moreover, for any $t\in [0,1]$,
		\begin{align*}
			\mathrm{Var} S_{n,t}(f) = \left( \mathrm{Var} X_{1,n} \right)^{m_*} \sum_{r=1}^{m_*} \left( D_r^{(m_*,m,p)}  \right)^2 r! \; \Lambda_{r}(n,t) \big(1 + o_{n,\mathrm{unif}}(1) \big)  .
		\end{align*}
	\end{itemize}

