[Theorem thm:kirchhoffweighted of arXiv:2609.01672, '\textbf{All-Minors Matrix-Tree Theory for Superport Networks:\\ Completed Quotient-Inciden'] For a connected conductance-weighted graph on \(n\) vertices,
\begin{align}
K_c(G;x)
={}&\frac1{\tau_c(G)}\Bigg\{
 m\bigl(S_{c/x}(G),n-2\bigr)
 \prod_{v\in V}x_v\notag\\
&+\sum_{C\in\mathcal C(G)}(-2)^{p(C)}c(C)\notag\\
&\qquad\times m\bigl(S_{c/x}^{C}(G),n-2-|C|\bigr)\notag\\
&\qquad\times\prod_{v\notin V(C)}x_v\Bigg\}.

\end{align}

[Proposition prop:local_hajek of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] As in (equation eq:hatngrhovdef of the paper), let us write
\begin{equation}
    \widehat{\mathsf{N}}_G^{\rho \to v}(x) = \mathsf{N}_G^{\rho \to v}(x) - \mathsf{d}_\rho p^{\mathsf{e}-1} n^{\mathsf{v}-2} \mathsf{deg}_v(x).
\end{equation}
Then for all $\zeta \in (0,\frac{3}{4})$, there is some $c > 0$ such that
\begin{equation}
    \mathbb{P} \mleft[ \mleft| \widehat{\mathsf{N}}_G^{\rho \to v}(X) - \mathbb{E} \mleft[ \widehat{\mathsf{N}}_G^{\rho \to v}(X) \mright]\mright| > n^{\mathsf{v}-1.75+\zeta} \mright]
    \leq \Exp{-c n^{\frac{4}{3} \zeta}}.
\end{equation}
In particular, for all $\xi > 0$ we have
\begin{equation}
    \operatorname{Var} \mleft[
        \widehat{\mathsf{N}}_G^{\rho \to v}(x)
    \mright] \lesssim n^{2\mathsf{v} - 3.5 + \xi}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfn 36 (Laplace benchmark) of arXiv:2609.02398, '\textbf{Convex Order Comparisons for Sub-Gamma Random Variables}'] The standard Laplace variable $\Lap$ has density
\begin{align*}
    \frac{1}{2}e^{-|x|}, \qquad x \in \R,
\end{align*}
and satisfies
\begin{align*}
&&
    \E[\Lap] &= 0, &
    \E[|\Lap|] &= 1, &
    \E\left[e^{\lambda \Lap}\right] &= \frac{1}{1 - \lambda^2}
    \quad (|\lambda| < 1). &
&\end{align*}

[Lemma 11 of arXiv:2609.03243, 'Weighted Ces\`aro type operators on the weighted Bergman spaces in the unit ball'] Let $\alpha>-1$, $\beta>0$ and $\delta\geq 0$. If $f\in H(\mathbb B_n)$, then the following formula holds:
\begin{equation}
    \big(\mathcal{C}_{\mu,\beta}^{\xi}f\big)(z)=\frac{c_{\alpha+\delta}}{c_{\alpha}}\int_{\mathbb{B}_n}f(w)K_{\mu,\beta,\delta}^{\xi}(z,w){\rm d}v_{\alpha}(w),
\end{equation}
where 
\begin{equation}
K_{\mu,\beta,\delta}^{\xi}(z,w)=\int_{[0,1)}\frac{(1-|w|^2)^{\delta}}{(1-t\langle z,\xi\rangle)^{\beta}(1-t\langle z,w\rangle)^{n+1+\alpha+\delta}}{\rm d}\mu(t).
\end{equation}

