[Lemma 13 (Lemma 3.6 of \cite{Chen2024} at $n=8$) of arXiv:2608.26598, 'Pinching cones for positive isotropic curvature in dimensions seven and eight'] Let $n=8$ and $0<b\le b_{max}$. Then, with $a,\gamma,\omega,A,P,Q$ as in \eqref{data},
    \begin{equation}
        (1+b\sqrt{n-2})^2<1+\frac{A}{2}\sqrt{n(n-2)},
    \end{equation}
    \begin{equation}
        \left(1+\frac{A}{2}\sqrt{n(n-2)}\right)^2\frac{1}{P+nQ}<\frac{\omega}{4},
    \end{equation}
    and
    \begin{equation}
        \left(1+\frac{A}{2}\sqrt{n(n-2)}\right)\frac{1}{P}<\frac{\omega}{4}.
    \end{equation}

