body:
[Lemma EHI:l:LeaveBallExponential of arXiv:2511.08956, '\textbf{Towards a characterization of elliptic Harnack inequality for jump processes}'] There exists a universal constant $c_{(EHI:l:LeaveBallExponential of the paper)}=c_{(EHI:l:LeaveBallExponential of the paper)}(d)>0$ such that if $X \in \mathcal{I}(d, r_0)$, then for all $r>0$, $x \in \mathbb{R}^d$, and $t>0$,
    \begin{equation*}
        \mathbb{P}_0(\tau_{B(x, r)}>t) \leq \exp(-\floor{c_{(EHI:l:LeaveBallExponential of the paper)} \frac{m_2(X)}{(r \vee r_0)^2} t}).
    \end{equation*}

[Prop Kac-Rice Formula of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] For the random polynomials $P_n$, we have almost surely 
    \begin{equation}
        \mathscr{C}(\Lambda_n) \hspace{1mm}(\textrm{resp.} \hspace{1mm} \tildea{\mathscr{C}}(\Lambda_n) ) = 1 + \lim_{\varepsilon \to 0} \frac{1}{\pi \varepsilon^2} \int_{\mathbb{D} \hspace{1mm}(\textrm{resp.} \hspace{1mm} \mathbb{A}_n )} |P_n''(z)|^2 \mathbbm{1}_{\{|P_n'(z)|<\varepsilon, |P_n(z)| >1\}} A(dz). 
    \end{equation} 
   Moreover, 
   \begin{equation}
       \mathbb{E}[\tildea{\mathscr{C}}(\Lambda_n)] = 1 + \lim_{\varepsilon \to 0} \frac{1}{\pi \varepsilon^2} \int_{\mathbb{A}_n} \mathbb{E}\bigl[|P_n''(z)|^2 \mathbbm{1}_{\{|P_n'(z)|<\varepsilon, |P_n(z)| >1\}}\bigr] A(dz).
   \end{equation}

[Proposition 28 (Exploration of the right part) of arXiv:2512.05466, 'Stochastic Flows and Marked Stable Processes'] Almost surely: for every  $t\ge 0$ and every spindle $\cT$,  setting $(a,r)$ and $(c,z)$ for its bottom and top points,  if $t> t_{\cT}$ and $\varrho_t\in \cT$, then there exist $t_0<t<t_1$ and $r_0\in (X_t,z)$ such that:

    (i)  $\varrho_{t_0}=\varrho_{t_1}=(\cB_{r,{r_0}}(a),r_0)$;

    (ii) by time $t$, $\varrho$ has visited all points $((\mathcal{B}_{r,x}(a), x)$ for $x \in [r_0, z]$, but has not visited any points $(\mathcal{B}_{r,x}(a), x)$ for $x \in (r, r_0)$; 

    (iii) for any $s\in (t_0,t_1)$, we have $\varrho_s \in \cT$  and $X_s\in (r,r_0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 of arXiv:2604.04840, 'Bounding the Gap Between Zeros of the Variable-\\Parameter Confluent Hypergeometric Functi'] Consider real parameters $a<0$, $b>0$ and $z>0$ such that $\Phi(a,b,z) = 0$ and $z<-1-a+b$. Then an upper bound on the integral $I=\int_0^z t^{b-1} e^{-t} \Phi^2(a,b,t)dt$ is

\begin{equation}

	I\leq \frac{a^2 e^{-z} z^{b-1} \Phi^2(a+1,b,z)}{-1 - a + b - \sqrt{z(-1-a+b)}}
\end{equation}

