[Proposition StoFubiniThm of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] Let $T\geq 0$, $m(dt)$ be a $\sigma$-finite measure on $\mathbb{R}_+$ and $h$ be a measurable function on $\mathbb{R}_+$ such that
 \begin{eqnarray*}
  \int_0^T \big|h(T-t)\big|  \cdot \bigg( \int_0^t |f(s)|^2\, ds +\int_0^t  \int_0^\infty \big| g(s,y) \big|^2\, \mu(dy)\,ds \bigg)\,m(dt)  <\infty .
 \end{eqnarray*}
 If $\sup_{t\in[0,T]}  X(t)  <\infty$ a.s., we have
 \begin{eqnarray}
  \int_0^T h(T-t)  B(f,t)\, m(dt) 
  \!\!\!&=\!\!\!&  \int_0^T \int_0^{X(s)} \bigg( \int_s^{T} h(T-t)f(t-s)\, m(dt) \bigg)B(ds,dz) 
 \end{eqnarray}
 and 
 \begin{eqnarray}
  \int_0^T h(T-t)   \widetilde{N}(g,t)\, m(dt)  
  \!\!\!&=\!\!\!& \int_0^T  \int_0^{X(s)}\int_0^\infty \bigg(\int_s^{T}h(T-t) g(t-s,y)\, m(dt) \bigg) \widetilde{N}(ds,dz,dy).
 \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 (Fixed-slope evolution) of arXiv:2607.18032, 'FRSB in the SK spin glass: convergence to full-interval support at zero temperature'] Let $u:=u^{|\cdot|,\gamma}$ solve \eqref{eq:zt-general-PDE}, and define the functions of $(t,B)$ by \eqref{eq:zt-slope-curvature}--\eqref{eq:zt-slope-variables}. On an interval where $\gamma=m$, derivatives at fixed $B$ satisfy
\begin{equation}
 x_t=-\mathsf K B,\qquad \mathsf c_t=\mathsf c^2\mathsf J
 \quad\text{and}\quad \mathsf z_t=2\mathsf c\mathsf z\mathsf J-\frac12\mathsf c^2\mathsf J_B.

\end{equation}
If
\begin{equation}
 \Phi:=2\mathsf z^2-m\mathsf c\quad\text{and}\quad
 \cG:=2\mathsf c\mathsf z(3\mathsf z\mathsf J-\mathsf c\mathsf J_B),

\end{equation}
then
\begin{align}
 \Phi_B&=2\mathsf z(2\mathsf J+3m),                                             \\
 \Phi_t&=\mathsf c\mathsf J\Phi+\cG\quad\text{and}\quad \cG\geq0.           
\end{align}
In particular, if $m>0$, then $\Phi$ is strictly increasing on $0<B<1$.

