[Proposition 132 (Dyadic summation in the gap lattice) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $1\le q<\infty$, and identify a dyadic array
$(x_{L,M})_{L,M\in\Dya}$ with
$(x_{2^j,2^k})_{j,k\ge0}$ in $\mathsf{Gap}_q$.

If \eqref{eq:strict-power-region} holds, then
$\mathcal M\in\mathsf{Gap}_q$.  Moreover, with $\rho$ as in
Proposition~\ref{prop:dyadic-summation}, for every
$0<\sigma<\rho$,
\begin{equation}

 \norm{\bigl(
 \mathcal M_{L,M}\mathbf1_{\{L\vee M>R\}}
 \bigr)_{L,M}}_{\mathsf{Gap}_q}
 \lesssim_\sigma R^{-\sigma},
 \qquad R\ge2.
\end{equation}

If \eqref{eq:diagonal-critical-plane} holds, then
\begin{equation}

 \mathcal M\in\mathsf{Gap}_q
 \quad\Longleftrightarrow\quad
 \alpha+\zeta>\kappa+\frac1q.
\end{equation}
When this condition holds, put
\[
 \rho_{\log,q}:=\alpha+\zeta-\kappa-\frac1q>0.
\]
Then
\begin{equation}

 \norm{\bigl(
 \mathcal M_{L,M}\mathbf1_{\{L\vee M>R\}}
 \bigr)_{L,M}}_{\mathsf{Gap}_q}
 \asymp
 \ell_R^{-\rho_{\log,q}},
 \qquad R\ge2.
\end{equation}

