[Lemma 9 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] We denote $F_1:=[\widetilde{B}(10d^2N)]^c$ and $F_{-1}:=\widetilde{B}(\frac{N}{10d^2} )$. For any $d\ge 3$ with $d\neq 6$, $D\subset \widetilde{\mathbb{Z}}^d$, $N\ge 1$, $i \in \{1,-1\}$, and $v\in (\widetilde{\mathbb{Z}}^d\setminus D)\cap  F_i$,
 	\begin{equation}
 	 \begin{split}
 	 	\mathbb{P}^D\big( v\xleftrightarrow{\ge 0} \partial B(N) \big) \lesssim & N^{-(\frac{d}{2}\boxdot 3)}\sum\nolimits_{x\in \partial \mathcal{B}(d^{i}N)} \mathbb{P}^D\big( v\xleftrightarrow{\ge 0}x  \big). 	 \end{split}
 	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2505.16701, 'Open interacting particle systems and Ising measures'] (1) Let the interaction parameter $\epsilon$ be in the range $0<|\epsilon|<1$.
For the open generalized KLS model 
the Ising measure \eqref{Isingfreedef} is invariant for any $z\in\R^+$ 
if and only if all of the following conditions (A) - (C) hold:\\
\emph{(A)} The boundary rates
\eqref{rm} - \eqref{d12} are on the parameter manifold defined by
\begin{eqnarray}
d^{\pm}_{1} & = & \frac{(f \epsilon + c) (1+\epsilon) + q_{\pm}^{-1} (f \epsilon - c) (1-\epsilon)}{2 \epsilon} 
 \\
d^{\pm}_{2} & = & \frac{(f \epsilon + c)  + q_{\pm}^{-1} (f \epsilon - c) }{2 \epsilon}.
 \\
a_1^{\pm} & = &  \frac{d^{\pm}_{1}}{1+z_{\pm}} 
\\
a_2^{\pm}  & = & a_1^{\pm}
+ (q_{\pm} - 1) \frac{(f \epsilon + c) (1+\epsilon)}{2 \epsilon z_{\pm}} 

\end{eqnarray}
where $q_{\pm} := z_{\pm} z^{-1}$.\\
\emph{(B)} The boundary fugacities $z_{\pm}$
satisfy the relations
\begin{eqnarray}
0 & = & 2 \epsilon a_2^{-} (z_{-} + y^{-1}) 
- (q_{-}  (f \epsilon + c)  + (f \epsilon - c)) (1+\epsilon)   \\[2mm]

0 & = & 2 \epsilon a_2^{+} (z_{+} + y^{-1}) 
- (q_{+}  (f \epsilon + c)  + (f \epsilon - c)) (1+\epsilon).

\end{eqnarray}  
\emph{(C)} The compatibility condition
\begin{equation}
a_1^{+} z_{+}  = a_1^{-} z_{-}

\end{equation}
between the boundaries holds.\\
(2) For the open generalized KLS model with
$\epsilon=0$ and $c\neq 0$
the Bernoulli product measure 
\begin{equation}
\pi^\ast_{L}(\bfeta) = 
\frac{z_{-}^{\eta_1}}{1+z_{-}} \left(\prod_{k=2}^{L-1} \frac{z^{ \eta_k}}{1+z}\right) \frac{z_{+}^{\eta_L}}{1+z_{+}}

\end{equation}
 is invariant for any $z\in\R^+$ 
if and only if all of the following conditions hold:\\
\emph{(A0)} The boundary rates
\eqref{rm} - \eqref{d12} of the open generalized KLS model 
with $\epsilon=0$ are on the parameter manifold
defined by
\begin{eqnarray}
d^{\pm}_{1} & = & f + \frac{c}{1+z} 
 \\
d^{\pm}_{2} & = & f - \frac{c}{1+z^{-1}} 
 \\
a^{\pm}_1 & = & \frac{d^{\pm}_{1}}{1+z}
 \\
a^{\pm}_2 & = & a^{\pm}_1 - \frac{c}{1+z} 

\end{eqnarray}
where $f=r-\ell$, $c=r\kappa - \ell \lambda$.\\
\emph{(B0)}
The boundary fugacities
\begin{eqnarray}
z_{-}=z_{+}=z

\end{eqnarray}  
are equal to the bulk fugacity.\\
\emph{(C0)} The compatibility condition
\begin{equation}
a_1^{+}  = a_1^{-}

\end{equation}
between the boundaries holds.\\
(3) For the open generalized KLS model with
$\epsilon=0$ and $c= 0$
the Bernoulli product measure \eqref{Isingfreedef2}
 is invariant for any $z,z_{-},z_{+}\in\R^+$ 
if and only if the boundary rates are on the manifold defined by
\begin{eqnarray}
 d^{\pm}_{1} & = &  f 
\frac{1+ z_{\pm}^{-1}}{1 + z^{-1}} 
  \\
 d^{\pm}_{2} & = &  f 
\frac{1+ z_{\pm}^{-1}}{1 + z^{-1}}   \\
a_1^{\pm}  & = &  f \frac{z_{\pm}^{-1}}{1 + z^{-1}}   \\
a_2^{\pm} & = &  f \frac{z^{-1}}{1 + z^{-1}} .

\end{eqnarray}
and the compatibity condition \eqref{cH1} holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 (Uniform limiting Malliavin bounds) of arXiv:2608.08177, 'Uniform-in-Time Smoluchowski--Kramers Approximation\\ in Total Variation for Fractional SD'] For every $p\ge1$,
\begin{align}
 \sup_{t\ge0}\norm{\D Z_t}_{L^p(\Omega;\cH)}
 &<\infty,
 \\
 \sup_{t\ge0}\norm{\D^2Z_t}_{L^p(\Omega;\cH^{\otimes2})}
 &<\infty.

\end{align}
Moreover, for every $t_0>0$ and $q\ge1$,
\begin{equation}
 \sup_{t\ge t_0}
 \E\left[\norm{\D Z_t}_{\cH}^{-q}\right]
 <\infty.
\end{equation}
In fact, the inverse bound is deterministic.

[Corollary 4 (Ridge-product identity) of arXiv:2608.26693, '2608.26693'] Under \eqref{eq:equal-tau}, the covariance action admits the ridge-product representation
\begin{equation}
\Acal_{\rm cov,\tau}(\Sigma_0,\Sigma_1)
=-\frac{\tau}{2}\log\det(I-R_0)
-\frac{\tau}{2}\log\det(I-R_1)
+\tau\log\det(I-\mathcal R^{1/2}).
\end{equation}
In particular, the associated determinants satisfy
\begin{equation}
\det(I-\mathcal R^{1/2})^2
\ge \det(I-R_0)\det(I-R_1),
\end{equation}
with equality if and only if $\Sigma_0=\Sigma_1$.

[Lemma of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] For every $k \in \mathbb{N}$ the map
	\begin{equation*}
		\mathbb{R}^k \times \overline{\mathbb{R}}_+^k \times (0,\infty)^k \ni (\pmb{u}, \pmb{z}, \pmb{t})  \mapsto 	\mathfrak{V}^k(\pmb{u},\pmb{z},\pmb{t}) 
	\end{equation*}
	is continuous with respect to the topology induced by uniform convergence on compacts.

[Lemma lem:shortcut-to-LRP of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] Recall that $b=b_X$ is the constant in (equation Eq2 of the paper). 
Let $F$ be bounded and uniformly continuous.  For each fixed $\varepsilon\in(0,1)$,
\begin{equation*}

\lim_{\delta\downarrow0}\limsup_{n\to\infty}
\left|
\mathbb{E}\left[F\left(\frac{\sum_{i=1}^{N_\varepsilon}\hat{X}_i-X_n}{n(\log n)^{-3/2}}\right)\right]
-
\mathbb{E}\left[F\left(b\varepsilon\delta L_{\mathrm{LRP}}\right)\right]
\right|=0.
\end{equation*}

