[Corollary cor:dynamic-fisher-eos of arXiv:2608.21561, '\textbf{Loss-Parameterized Fisher Width Along Learning Trajectories}'] Let $\theta(t)$ follow population gradient flow. Then, for $d\geq2$,
\begin{equation}
    \frac{
        w_F(B_2^d;\theta(t))
    }{
        \sqrt{L(\theta(t))}
    }
    \longrightarrow
    \frac{\sqrt6}{\pi}
    \mathbb E[\chi_{d-1}].

\end{equation}
Moreover,
\begin{equation}
    L(\theta(t))
    \asymp
    t^{-1/3},
    \qquad
    w_F(B_2^d;\theta(t))
    \asymp
    t^{-1/6}.

\end{equation}

[Lemma lem:Cconveuqiv of arXiv:2606.11677, 'Feynman--Kac formula for the heat equation with a one-center point interaction in $d=3$.'] [Mat75]
$C_n\to C$ in $\mathcal{C}$ if and only if the following conditions hold:
\begin{enumerate}
\item if $x_n \in C_n$ is a sequence with $x_n\to x\in [0,\infty)$, then $x\in C$;
\item if $n_k\to C_{n_k}$ is a subsequence, every convergent sequence $n_k\to x_{n_k}\in F_{n_k}$ satisfies $\lim_{k\to\infty}x_{n_k}\in F$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem Black-Scholes_vs_BM of arXiv:2411.11408, 'Multidimensional specific relative entropy between continuous martingales'] {The specific relative entropy between a $\mathbb{R}^l$-valued martingale Black-Scholes models with parameter $\Gamma\in \mathbb{R}^{l \times l}$ and Brownian motion, both starting wlog.\ at $\mathbf{1}$, is given by:
\begin{equation} \begin{split}  \textstyle 
h_l(\mathcal L(M^{\Gamma})|\mathbb B^l)=\frac{1}{2}\Big(\sum_{i=1}^l \big(e^{\sum_{k=1}^l \Gamma_{ik}^2}-1\big)-l+\frac{1}{2} \sum_{i=1}^l \sum _{k=1}^l \Gamma_{ik}^2 - \log \big(\det (\Gamma \Gamma^T) \big)\Big).
\end{split}
\end{equation}}

[Theorem 11 of arXiv:2605.29608, '2605.29608'] Consider the 1D Ising model with coupling constant $\hat{J}\in[0,+\infty)$. Let $(Y_{k})_{k\in\mathbb{Z}^{+}}$ and $\mu_{N}$ be defined as in Theorem \ref{thm: transitionmatrix}, the sample covariance matrix $\mathbb{K}$ satisfies
\begin{align*}	\mathbb{P}(\lim\limits_{N\rightarrow +\infty}\lim\limits_{M\rightarrow +\infty}	\rho(\mathbb{K})=0)=\mathbb{P}(\lim\limits_{N\rightarrow +\infty}\lim\limits_{M\rightarrow +\infty}\Vert\mathbb{K}\Vert_{1}=0)=1. 	
\end{align*}
Furthermore, we know that for $\hat{J}\in[0,+\infty)$
\begin{align*}
	\lim\limits_{N\rightarrow +\infty}\lim\limits_{M\rightarrow +\infty}	\lambda_{1}(\mathbb{K})=0,\qquad  \mathbb{P}\text{-a.s.}.
\end{align*}

