body:
[Lemma lem: Linden bd ERW of arXiv:2505.05921, 'Limit Theorems for step reinforced random walks\\ with regularly varying memory'] Let $\{S_n\}_{n\geq 0}$ be the SRRW-RVM with zero mean unit variance innovation sequence $\{\xi_n\}$. Then, for every $t>0$, there is a positive constant $C_t$ such that for all $n\ge 1$ and $1\le k\le \lfloor nt\rfloor$, the following hold:
\begin{enumerate}
\item  When $p\in[0,\widehat{p})$, we have $\| \Delta \overline T_{n,k} \| \le C_t |\Delta L_k| / \sqrt{n}$.
\item  When $p\in(\widehat{p}, p_c)$, we have $\| \Delta T_{n,k} \| \le C_t |\Delta L_k| / n^\rho$, for some $\rho>0$.
\item  When $p=\widehat{p}$, we have $\| \Delta \widetilde T_{n,k} \| \le C_t |\Delta L_k| / n^{1/4}$.
\end{enumerate}

[Dfn indices of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] Let $H=(V,E)$ be a graph with node set $V$ and edge set $E$.\\
    The Zagreb index is defined as
    \begin{align}
        Z_H:=\sum_{v \in V} (d(v))^2.
    \end{align}
For $\alpha \in \mathbb{R}$, the  $\alpha$-Randić index of $H$ is given by
    \begin{align}
        R_H^{[\alpha]}:=\sum_{\{u,v\} \in E} (d(u)d(v))^\alpha.
    \end{align}
If $H$ is connected, the Wiener index is defined as  
    \begin{align}
        W_H:=\frac{1}{2}\sum_{u,v\in V} \dist(u,v).
    \end{align}
If $H$ is connected and rooted, the level index is defined as 
    \begin{align}
        L_{H}:=\frac{1}{2}\sum_{u,v \in V} \vert D(u)-D(v)\vert.
    \end{align}
For a random graph $H$ of a class of rooted, connected graphs $\mathcal{H}$, the Gini index is given by
\begin{align}
G_H:=\frac{L_{H}}{\,{\mathbb{E}}[V]^2\,{\mathbb{E}}[D_\mathcal{H}^\star]},
\end{align}
where $D_\mathcal{H}^\star$ is the depth of a randomly chosen node in a random tree of class $\mathcal{H}$ (see [ma17] for more information).

[Prop 21 (Triangular array marginal for empty initial conditions) of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $N$ be an even integer and let $x=(x_1,\dots,x_N)$ be the ordered coordinates of TASEP particles. Then the half-line open TASEP transition probability from an empty state to $x$ can be written as a sum over Pfaffian kernels indexed by Gelfand--Tsetlin patterns with endpoints fixed by $x=(x_1,\dots,x_N)$:
	\begin{equation}

		\mathbb{P}_t(\emptyset\to x) = (-1)^{\binom{N}{2}}\mathrm{e}^{-\alpha t} \sum_{z\in\mathsf{GT}_N(x)} \Pf\left[\Psi(z_i^N,z_j^N)\right]_{1\leq i,j\leq N},
	\end{equation}
	where we have defined
	\begin{equation}
		\Psi(x,y) := Q_{1,1}(x,y)
		= \alpha^2\oint_\contour \frac{\dd u}{2\pi\ii} \oint_\contour \frac{\dd w}{2\pi\ii} \frac{u-w}{1-u-w} \frac{w^{1-x}\mathrm{e}^{t(w-1)}}{(w-\alpha)(w-1)} \frac{u^{1-y}\mathrm{e}^{t(u-1)}}{(u-\alpha)(u-1)},
	\end{equation}
    where contour $\beta$, as in Definition \ref{defn:TASEP countours}, surrounds poles at $u,w=1,0,\alpha,1-\alpha$ and omits all other singularities of the integrand. The kernel $\Psi(x,y)$ is skew-symmetric under the interchange of $x$ and $y$ when $x,y\geq1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition p:fin_bubble of arXiv:2505.09604, 'Exceptional force, uncountably many solutions in the KPZ fixed point'] The following holds on the event $\Omega_1$. Let $\xi \in \Xi$ and $(x_0,s) \in \mathbb{R}^2$ be such that 
       \begin{equation}

      \tau^{\xi,-}_{(x_0,s)}(r) < \tau^{\xi,+}_{(x_0,s)}(r)\quad \text{ for all } r \in (s,t), \text{ and }\quad \tau^{\xi,-}_{(x_0,s)}(t)=\tau^{\xi,+}_{(x_0,s)}(t).
       \end{equation}

      Then there exists $\delta>0$ such that 
       \begin{equation}

       \tau^{\xi,-}_{(x_0,s)}(r)=\tau^{\xi,-}_{(x_0,s)}(r) \text{ for all } r \in [t,t+\delta].
       \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 12 of arXiv:2608.20552, 'One-point fluctuations for exponential last passage percolation under upper-tail condition'] Define
\beqq
	\dc_k^{m,n}:=k!\binom{m}{k}\binom{n}{k}.
\eeqq
For a list containing the indicated consecutive blocks, define
\beqq
	\mathrm{R}_k^{12}(\cdots1^m2^n\cdots):=\cdots2^{n-k}(12)^k1^{m-k}\cdots,
	\qquad
	\mathrm{R}_k^{21}(\cdots2^n1^m\cdots):=\cdots1^{m-k}(12)^k2^{n-k}\cdots.
\eeqq

\begin{enumerate}[(a)]
\item
If $\bsigma'$ is obtained from $\bsigma$ by interchanging consecutive blocks $\alpha^m\beta^n$ with $\beta^n\alpha^m$, where $\alpha,\beta\in\mc A_2$ and $\{\alpha,\beta\}\ne\{1,2\}$, then $\J^{\bsigma}_{\btau}=\J^{\bsigma'}_{\btau}$. The analogous statement also holds when two such blocks occur in $\btau$.

\item
Suppose $\type(\btau)=(b_{12},b_1,b_2)$. Then,
\begin{eqnarray}
	&&\J^{\bsigma}_{\btau}
	=\sum_{k=0}^{m\wedge n}(-1)^{k(b_1+1)}\dc_k^{m,n}\J^{\mathrm{R}_k^{12}(\bsigma)}_{\btau},
	\qquad \text{if $\bsigma=\cdots1^m2^n\cdots$,}
	\\
	&&\J^{\bsigma}_{\btau}
	=\sum_{k=0}^{m\wedge n}(-1)^{kb_1}\dc_k^{m,n}\J^{\mathrm{R}_k^{21}(\bsigma)}_{\btau},
	\qquad \text{if $\bsigma=\cdots2^n1^m\cdots$.}

\end{eqnarray}

\item
Suppose $\type(\bsigma)=(a_{12},a_1,a_2)$. Then,
\begin{eqnarray}
	&&\J^{\bsigma}_{\btau}
	=\sum_{k=0}^{m\wedge n}(-1)^{ka_1}\dc_k^{m,n}\J^{\bsigma}_{\mathrm{R}_k^{12}(\btau)},
	\qquad \text{if $\btau=\cdots1^m2^n\cdots$,}
	\\
	&&\J^{\bsigma}_{\btau}
	=\sum_{k=0}^{m\wedge n}(-1)^{k(a_1+1)}\dc_k^{m,n}\J^{\bsigma}_{\mathrm{R}_k^{21}(\btau)},
	\qquad \text{if $\btau=\cdots2^n1^m\cdots$.}

\end{eqnarray}
\end{enumerate}

[Corollary jo1 of arXiv:2411.18374, 'Drawdowns of diffusions'] For $\delta>\rho\geq 0$,  and if   $M_{\theta_\rho}> v$ then
\begin{align}

&
{\bf P}_0\left(M_{\theta_\delta}>v\,|\, M_{\hbox {\rm tanh\,}_\rho}\right)=1,
\end{align}
and if $M_{\theta_\rho}\leq v$ then for $y\leq v$
\begin{align}

&
\nonumber
{\bf P}_0\left(M_{\theta_\delta}>v\,|\, M_{\hbox {\rm tanh\,}_\rho}=y\right)\\
&\hskip2cm
=\frac{S(y-\rho)-S(y-\delta)}{S(y)-S(y-\delta)}\exp\left(-\int_y^v\frac{dS(z)}{S(z)-S(z-\delta)}\right).
\end{align}

