\lim_{n\rightarrow{+\infty}}  \limsup_{N\rightarrow{+\infty}}\mathbb{E}_{N}\Big[\sup_{0\leq{t}\leq{T}}\sum_{|z|\geq{n}}(\langle \pi_{t}^N,h_{z}\rangle)^{2}\gamma_{z}^{-m}\Big]=0.
\end{equation*}

