[Theorem thm:area-law-main of arXiv:2505.16585, 'Expanded regimes of area law for lattice Yang--Mills theories'] Consider lattice Yang--Mills theory with gauge group $G = \unitary(N)$. For all $d \geq 2$, there exists $\beta_0(d) > 0$ such that for all $\beta \leq \beta_0(d)$ and all $N \geq 1$, for any rectangular loop $\ell$ belonging to a finite lattice $\Lambda$, we have that 
\begin{equs}
|\langle W_\ell \rangle_{\Lambda, \beta, N}| \leq C_{1, d} C_N^{|\ell|} \exp(-C_{2, d} \mrm{area}(\ell)),
\end{equs}
where $|\ell|$ denotes the perimeter of $\ell$, and $C_{1, d}, C_{2, d}$ are constants depending on $d$, and $C_N$ is a constant depending on $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 5 of arXiv:2608.30658, 'Higher Regularity of Time-Periodic Solutions to Nonautonomous Hyperbolic Problems: Away fr'] Let $V$ be a vector space, $U\subseteq V$ be a subspace of $V$, and $\CC,\E: V\to V$ be linear operators. 
Assume that integers $m\ge 1$ and $k\ge 2$ are such that:
	\begin{enumerate}
		\item 
	If $(I-\CC^m)v\in U$  for $v\in V$, 
		then  $v\in U$;
\item 
$\CC u\in U$ and $\E u\in U$ for all $u\in U$;
		\item 
		$\sgn(m-1)\,\CC\E u$, $\E\CC u$, and $\E^ku$ belong to $U$ for all $u\in V$.
	\end{enumerate}
Then for any $u\in V$  satisfying $u-\CC u-\E u\in U$, it follows that  $u\in U$.

[Lemma Th+i of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] Let $\theta\in [0,\pi]$ and $\gamma\geq 0$. Define $\rho_{i}(\theta)^2:=v_i^2\cot^2\theta+1$, for $i=1,2$. For each $i\in \{1,2\}$, $\Theta^+_{0, i}$ and $\hat{H}_{0,i}^2$ we have 

\begin{enumerate}
\item for $\theta\leq \pi/2$,
\begin{align}
\mathbb{E}^0_i\left[{\mathds{1}}_{\{\Theta^+_{0, i}\leq \theta\}}e^{-\gamma \hat{H}_{0,i}^2}\right]&= \pi \lambda^{3/2}\int_{0}^{\infty}\int_{0}^{h_1\rho_1(\theta)}\int_{t_+}^{\infty}  e^{-(\lambda\pi+\gamma) \hat{h}^2} {\rm d}t \,{\rm d}h_2 \, {\rm d}h_1  {\nonumber}\\
&\quad + \pi \lambda^{3/2} \int_{0}^{\infty}\int_{h_1}^{h_1\rho_1(\theta)}\int_{0}^{t_-} \, e^{-(\lambda\pi+\gamma)\hat{h}^2} {\rm d}t \,{\rm d}h_2 \, {\rm d}h_1 {\nonumber}\\

&\quad + \pi \lambda^{3/2}\int_{0}^{\infty}\int_{h_1\rho_1(\theta)}^{\infty}\int_{0}^{\infty}\, e^{-(\lambda\pi+\gamma) \hat{h}^2} {\rm d}t \,{\rm d}h_2 \, {\rm d}h_1 ,
\end{align}

where $t_{\pm}:= h_1v_i\cot\theta\pm \sqrt{h_1^2 \rho_i^2(\theta) -h_2^2}$.

\item For $\theta>\pi/2$ 

\begin{align}
\mathbb{E}_0\left[{\mathds{1}}_{\{\Theta_{0, i}^+\geq \theta\}} e^{-\gamma \hat{H}_{0,1}^2} \right]&= \pi \lambda^{3/2}
\int_{0}^{\infty}\int_{0}^{h_1}\int_{\tilde{t}_+\wedge \sqrt{h_1^2-h_2^2}}^{\sqrt{h_1^2-h_2^2}}\, e^{-(\lambda\pi+\gamma) \hat{h}^2} {\rm d}t \,{\rm d}h_2 \, {\rm d}h_1 ,
\end{align}
where $\tilde{t}_+:= h_1v_i\cot\theta+ \sqrt{h_1^2 \rho_i(\theta)^2 -h_2^2}$, for $i=1,2$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 2 of arXiv:2606.00648, 'Asymptotic estimates for multiple point ranges of transient random walks on graphs'] If $(U_1)$ holds, then, for every $j \ge 1$ and every $x \in \mathcal{X}$, 
the following statements hold $P^x$-a.s.: 
\begin{equation}
\limsup_{n \to \infty} \frac{R_n^j}{n}  \le (F_{\sup})^{j-1} (1-F_{\inf}). \ 
\end{equation}
\begin{equation}
\limsup_{n \to \infty} \frac{R_n^{(j)}}{n}  \le (F_{\sup})^{j-1} (1-F_{\inf})^2. 
\end{equation} 
\begin{equation}
\liminf_{n \to \infty} \frac{R_n^j}{n}  \ge (F_{\inf})^{j-1} (1-F_{\sup}). \ 
\end{equation}
\begin{equation}
\liminf_{n \to \infty} \frac{R_n^{(j)}}{n}  \ge (F_{\inf})^{j-1} (1-F_{\sup})^2. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

