body:
[Definition def:ALE of arXiv:2411.10586, 'A convergence framework for Airy$_\beta$ line ensemble\\ via pole evolution'] ALE$_\beta$ is an ordered families of continuous random processes
\begin{align}
    {\mathcal A}^\beta_1(t)\geq {\mathcal A}^\beta_2(t)\geq {\mathcal A}^\beta_3(t)\geq \cdots, \text{ for } -\infty<t<\infty,
\end{align}
which is the edge limit of the stationary DBM (equation eq:DBM of the paper), i.e., the limit of $\{n^{1/6}\lambda_i(tn^{-1/3})-2n^{2/3}\}_{i\in \mathbb{N}, t\in {\mathbb R}}$ as $n\to\infty$, in the uniform in compact topology. Namely for every compact $K\subset{\mathbb R}$ and every finite $I\subset\{1,2,3,\cdots\}$,
\begin{align}
\lim_{n\to\infty}\ \max_{i\in I}\ \sup_{t\in K}\, \bigl|n^{1/6}\lambda_i(tn^{-1/3})-2n^{2/3}-{\mathcal A}^\beta_i(t)\bigr| \;=\; 0.
\end{align}

[Corollary 41 of arXiv:2609.01460, 'On cost-induced Santal\'o-type inequalities \\ in Polish measure spaces'] Let $\mu$ be an even, log-concave probability measure on $\R$ with density. 

For any pair of measurable functions $f, g:\R \to [0,\infty)$ and any non-decreasing measurable function $W: \R_+ \to (0, \infty)$ satisfying the pointwise relation
\begin{equation}

f(x)^{\frac{1}{2}} g(y)^{\frac{1}{2}} \leq W\left(\frac{|x-y|}{2}\right) \quad \text{for all } x, y \in \R,
\end{equation}
one has the functional inequality
\begin{equation}

\left( \int_{\R} f(x) \, d\mu(x) \right)^{\frac{1}{2}} \left( \int_{\R} g(y) \, d\mu(y) \right)^{\frac{1}{2}} \leq  \int_{\R} W(|r|) \,d\mu(r).
\end{equation}

[Lem 21 (Relation between $q$, $Q$ and the stopping times $\sttm_k$) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] We have
	\begin{equation}
	Q(k) = \left( 1+o\left( \frac{1}{k} \right) \right) \, \frac{1}{\sqrt{\pi}} \, \Ec{\sttm_{k}^{-1/2}} \qquad\text{as } k \to \infty,
	\end{equation}
    and
    \begin{equation}
	(1+o(1))\, \frac{1}{2\sqrt{\pi}} \, \frac{1}{k} \Ec{\sttm_{k+1}^{-1/2}} \leq q(k) \leq (1+o(1)) \,\frac{1}{2p \sqrt{\pi}} \, \frac{1}{k} \Ec{\sttm_k^{-1/2}} \qquad\text{as } k \to \infty.
	\end{equation}
    Moreover, there exists a constant $C>0$ such that for all $k\geq 1$, 
    \begin{equation}
        \frac{1}{C} \, \frac{Q(k)}{k} \leq q(k) \leq C \, \frac{Q(k)}{k}.
    \end{equation}

