[Lemma lem:fourthcumu2 of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] In the setting of (lemma_G_large_2 of the paper), let $B$ be an arbitrary deterministic matrix with $\|B\|\le 1$. Then, we have that
    \begin{equation}
    \begin{aligned}
    \mathbb{E} \langle(G_1 - M_1)B\rangle 
    =&~\frac{\kappa^{(2,2)}  \langle \mathrm{diag}(M_1)^2 \rangle }{N}\left[ \langle M_1BM_1\mathrm{diag}(M_1)\rangle   +   \frac{ \langle M_1^2 \mathrm{diag}(M_1)\rangle}{1-\langle M_1^2\rangle } \langle M_1^2B\rangle\right]\\
    &~ + \mathrm{O}_\prec\qa{\pa{\frac{1}{\im m (z) }\wedge N^{\varepsilon_g}}\cdot{\pa{ N^{-3/2}\eta^{-1}+N^{-2}\eta^{-2}}}}.
    \end{aligned}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma le:space-integral of arXiv:2411.12192, 'Sample path properties and small ball probabilities for stochastic fractional diffusion eq'] Let $H_j\in(0,1)$ with $j=1,\dots,d$ and $H=\sum_{j=1}^{d}H_j$.
\begin{enumerate}[(i)]
  \item The integral
  \begin{equation*}
    \int_{\mathbb{R}^d} \frac{\prod_{j=1}^{d}c_{H_j} |\xi_j|^{1-2H_j}}{1+|\xi|^{2\alpha}} \ensuremath{ \mathrm{d}} \xi
  \end{equation*}
  is convergent if and only if $\alpha>d-H$.
  \item   The integral
  \begin{equation*}
    \int_{\mathbb{R}^d} \frac{\prod_{j=1}^{d}c_{H_j} |\xi_j|^{1-2H_j}}{1+|\xi|^{2\alpha}}|\xi|^2 \ensuremath{ \mathrm{d}} \xi
  \end{equation*}
  is convergent if and only if $\alpha>d-H+1$.
  \item The following inequalities
  \begin{equation*}
    \int_{\mathbb{S}^{d-1}} \prod_{j=1}^{d}c_{H_j}|w_j|^{1-2H_j} \sigma(\ensuremath{ \mathrm{d}}  w)<\infty,
  \end{equation*}
  and
  \begin{equation*}
    \int_{\mathbb{S}^{d-1}} |w_i|^2\prod_{j=1}^{d}c_{H_j}|w_j|^{1-2H_j} \sigma(\ensuremath{ \mathrm{d}}  w)<\infty, \quad \text{for } i=1,\dots,d,
  \end{equation*}
  hold, where $\sigma(\ensuremath{ \mathrm{d}}  w)$ is the uniform measure on the $(d-1)$-dimensional unit sphere $\mathbb{S}^{d-1}$.
\end{enumerate}

