[Theorem 5 of arXiv:2609.04095, '2609.04095'] Let \(q,g\ge0\) be integers.  The following conditions are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \(g\le\binom{q+1}{2}\);
\item for every \(W\ge0\) and \(m\ge1\),
      \begin{equation}
       T_m(W)^2\ge T_{m-1}(W)T_{m+1}(W).
      \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2604.22567, 'Sign-balance of random Laplace eigenfunctions'] Let $\phi_{0},\psi:\Gamma\rightarrow \R$ be two smooth functions defined on an open domain $\Gamma\subseteq\R^{2}$, and $\Pi\subseteq \Gamma$ a compact domain of area $|\Pi|=\area(\Pi)\in (0,\infty)$, 
so that $\phi_{0}$ has no critical zeros on $\Pi$. For $t\in \R$ define 
 \[ \phi_{t}(x):=\phi_{0}(x)+t\cdot \psi(x) \qquad \text{and} \qquad D(t):= \frac{1}{|\Pi|} \int\limits_{\Pi} H(\phi_{t}(x)) dx. \]
 Then
\[  D'(0) = \frac{2}{|\Pi|}\int\limits_{\phi_{0}^{-1}(0)\cap \Pi} \frac{\psi(x)}{\|\nabla  \phi_{0}(x)\|} dx \]
and
\begin{equation}

\begin{split}
D''(0) &= \frac{2}{|\Pi|}\int\limits_{\phi_{0}^{-1}(0)\cap \Pi} 
\bigg(-2\frac{\psi(x)\cdot\left\langle \nabla\phi_{0}(x),\nabla\psi(x)\right\rangle}{\|\nabla\phi_{0}(x)\|^{3}}dx + \frac{\psi(x)^{2}}{\|\nabla\phi_{0}(x)\|^{4}}\cdot \partial_{\nabla\phi_{0}(x)}\left[\left\|\nabla\phi_{0}(x)\right\|\right] 
\\& \qquad \qquad \qquad \qquad \qquad \qquad + \frac{\psi(x)^{2}}{\|\nabla  \phi_{0}(x)\|^{2}} \cdot \kappa(x)\bigg)dx,
\end{split}
\end{equation}
where $\partial_v$ denotes the directional derivative and $\kappa(x)$ is the curvature of a point $x \in \phi^{-1}(0)$, signed in accordance to the orientation defined by the unit normal $\vec{N}(x) = \frac{\nabla \phi_{0}(x)}{\|\nabla \phi_{0}(x)\|}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2609.02065, '\textbf{From Bowditch's question to Goldman's conjecture for type-preserving representatio'] \cite[Lemma 3.4.5]{goldman_torus} 
        Let $A, B\in \SL$. The following conditions are equivalent:
        \begin{enumerate}[(1)]
       \item $\tr[A,B]<2$;
       \item $A, B$ are hyperbolic elements and their invariant axes cross.
       \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 6 (Martingale solution) of arXiv:2606.31500, 'Non-Uniqueness for Nonlinear Fokker--Planck Equations and Their Associated Distribution-De'] Let $C([0,T];\mathbb{T}^d)$ be the space of continuous paths on the torus,
equipped with its Borel $\sigma$-algebra. Denote by
\begin{align*}
\Pi_t(\omega):=\omega(t),
\qquad
\omega\in C([0,T];\mathbb{T}^d),
\end{align*}
the canonical process, and let $(\mathcal F_t)_{t\in[0,T]}$ be the natural
filtration generated by $(\Pi_t)_{t\in[0,T]}$.

The corresponding (linear)  diffusion operator is defined by
\begin{align*}
L_{\rho_t}:=  \sigma\sigma^{T}(t,x,\rho_t):\nabla^2+(v(t,x)+V*\rho_t)\cdot \nabla.    
\end{align*} 

We say that a probability measure $\mathbf Q$ on
$C([0,T];\mathbb{T}^d)$ is a martingale solution associated with
$L_{\rho_t}$ if
\begin{align*}
\dif\mathbf Q\circ \Pi_t^{-1} =\rho_t \,\dif x,
\qquad
t\in[0,T],
\end{align*}
and, for every $f\in C^2(\mathbb{T}^d)$, the process
\begin{align*}
     f( \Pi_t) -f(\Pi_0)-\int^t_0 L_{\rho_s}f( \Pi_s)\dif s
\end{align*}
is a $\mathbf Q$-martingale with respect to $(\mathcal F_t)_{t\in[0,T]}$.

[Lemma 13 of arXiv:2506.18132, 'Throughput in inhomogeneous planar drainage networks'] There exists a constant $\tilde{C} \in (0, \infty)$ such that, for all sufficiently large $\eta$ and all $j \geq 0$, 
    \begin{align*}
        \P\big(\tau_{(\eta, j,\ell)} \neq \tau'_{(\eta, j,\ell)} \big)
        \leq 1- \tilde C(\log\eta)^{-2}.
    \end{align*}

