body:
[Lemma 18 (Uniform \(\ell^1\) bound for \(\IK\)) of arXiv:2608.26259, 'Cutoff with an $O(1)$ window for Potts Glauber Dynamics\\on lattice at High Temperature'] There exists \(C_{\IK,1}<\infty\) such that for all integers \(t\ge0\),
\begin{equation*}
\sum_{z\in\mathbb Z^d}|\IK(z,t)|\le C_{\IK,1}e^{-(1+\kappa)t}.
\end{equation*}

[Lemma Palm-Lcal-iin of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For $l\in [n]$ and for all non-negative measurable functions $f$ on $(\Omega,{\mathcal F })$,

\begin{align}
\mathbb{E}^0_{{\mathcal V }_l} [f ({\mathcal H })]
& = 
\frac {4\lambda_l^2v_l^2} {\Lambda_{l}}
\int_{(\mathbb{R}^+)^3}
\mathbb{E}_{\mathcal H }\left[ f\big(\theta_{\hat{s}(0,h,-t',h')}({\mathcal H }^l+\delta_{(0,h)}+\delta_{(-t',h')}+\sum_{m\neq l}{\mathcal H }^m)\big)\right.{\nonumber}\\

&\hspace{3in}\times \left.\prod_{i}{\mathds{1}}_{{\mathcal H }^i\left(E^{ \hat{s}(0,h,-t',h'),v_i}_{\hat{h}(0,h,-t',h')}\right)=0}  \right] {\rm d}t' {\rm d}h' {\rm d}h ,
{\nonumber}
\end{align}

where $(\hat{s}(t,h,t',h'),\hat{h}(t,h,t',h'))$
is the coordinates of the intersection of the two radial birds with heads $(t,h)$ and $(t',h')$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2607.02477, 'Mixing times of spin systems on dynamical percolation'] Fix $n\geq 2$ and and let $k\in\{1,\ldots,\ell_n\}$ be such that
$$\sigma_\frac{nC}{\lambda}(x) ~=~ \sigma_\frac{nC}{\lambda}'(x), \quad \forall x\in\bigcup_{j\in A_k^{(n)}\cup J_k^{(n)}}\overline{\Lambda_j^\core}.$$
Then, for all $t\in\II_n^{(2)}$ and $x\in\bigcup_{j\in A_k^{(n)}}\Lambda_j^\core$,
\begin{equation}
    \sigma_t(x) ~=~ \sigma_t'(x).
    \end{equation}

[Theorem 2 of arXiv:2604.00756, '\textbf{Stochastic ordering tools for continuous-time Markov chains and applications to re'] Consider a reaction network $\rn$ with two associated mass-action kinetics $K^X$ and $K^Y$. Choose $M \in \Z^{m,d}$ and define the matrix
    \begin{equation*}
        D = \brb{M^\intercal | C^\intercal} \in \R^{d,m+d-s}.
    \end{equation*}

    Let $A,B \in \R^{m+1,d}$ be filled in as follows, for $i = 1,\dots,m+1$ and $j=1,\dots,d$:
    \begin{equation*}
        A_{i,j} = 
        \begin{cases}
            1 & \text{if} \ \exists \alpha \in \R^{m+d-s} \ \text{such that} \ D\alpha = e_j \ \text{and} \ \alpha_k \geq 0 \ \forall k \in \{1,\dots,m\} \setminus \{i\}, \\
            0 & \text{otherwise};
        \end{cases}
    \end{equation*}
    \begin{equation*}
        B_{i,j} = 
        \begin{cases}
            1 & \text{if} \ \exists \beta \in \R^{m+d-s} \ \text{such that} \ D\beta = e_j \ \text{and} \ \beta_k \leq 0 \ \forall k \in \{1,\dots,m\} \setminus \{i\}, \\
            0 & \text{otherwise}.
        \end{cases}
    \end{equation*}

    Now, suppose that each reaction $r \in \rct$ satisfies one of

    \begin{tabular}{r l c r c l c l}
        \refstepcounter{hypa} \thehypa & $(M\xi_r)^+ = 0$, & & & & & & \\
        \refstepcounter{hypa} \thehypa & & & $A_{m+1,*} \odot \nu_r = \nu_r$, & & $\kappa_r^X \leq \kappa_r^Y$, & & \\
        \refstepcounter{hypa} \thehypa & $(M\xi_r)^+ = e_i$, & & $A_{i,*} \odot \nu_r = \nu_r$, & & $\kappa_r^X \leq \kappa_r^Y$ & & for some $i \in \cb{1,\dots,m}$,
    \end{tabular}

    and one of

    \begin{tabular}{r l c r c l c l}
        \refstepcounter{hypb} \thehypb & $(M\xi_r)^- = 0$, & & & & & & \\
        \refstepcounter{hypb} \thehypb & & & $B_{m+1,*} \odot \nu_r = \nu_r$, & & $\kappa_r^X \geq \kappa_r^Y$, & & \\
        \refstepcounter{hypb} \thehypb & $(M\xi_r)^- = e_i$, & & $B_{i,*} \odot \nu_r = \nu_r$, & & $\kappa_r^X \geq \kappa_r^Y$ & & for some $i \in \cb{1,\dots,m}$.
    \end{tabular}

    Then, for each choice of $x^0, y^0 \in \nat^d$ such that $x^0-y^0 \in \ss$ and $x^0 \preord{M} y^0$, there exist two CTMCs $X$ and $Y$ modeling $\rn$ with kinetics $K^X$ and $K^Y$, defined on a common probability space, and such that $X(0) = x^0$, $Y(0) = y^0$ and
    \begin{equation*}
        \P\brb{X(t) \preord{M} Y(t) \ \ \forall t \in [0, \tau^X \wedge \tau^Y)} = 1.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2607.22362, 'A Small-Noise Analysis of Controlled Functional Differential Equations with Gaussian Noise'] There are Borel maps $P_n \colon \Omega \to \M$, $n\in\mathbb{N}$, with the following properties:
	\begin{enumerate}[label=\textup{(\roman*)}]
		\item For every $n\in \mathbb N$, $P_n$ is adapted in the sense that \(\pi_t P_n\) is \(\cF_t\)-measurable for every \(t \in [0, 1]\).
		\item For every \(n \in \mathbb{N}\), there exists a \(\P\)-null set \(N\in \cF\) such that, for all \(\eta \in \M\), \(P_n (\omega + \eta) = P_n (\omega) + Q_n(\eta)\) for all \(\omega \not \in N\), where \(Q_n \colon \M \to \M\) is a linear contraction such that, for every $R >0$,
		\begin{equation}
			\sup_{\substack{u\in \M\\ \|u\|_{\M}\le R}}\|Q_n u -u\|_\infty\to0 \quad \text{as } n \to \infty.
		\end{equation}
		\item For every \(n \in \mathbb{N}\), \(\E [ \| P_n \|_{\mathcal{H}}^2 ] < \infty\). 
	\end{enumerate}

