body:
[Theorem thm:rigid-simple-nsc of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] Let   $ k\in \mathbb{N}$.
    Assume that one of the following holds:\begin{itemize}
\item (i) $ k = 0$
\item (ii) $    \mathsf s$ is invariant under rotations
\item (iii) $    \mathsf s$  is  {\it separable}, i.e. $    \mathsf s(u)=   \mathsf s_{1}(u_{1})\dots    \mathsf s_{d}(u_{d}),u\in \mathbb{R}^{d}$, for some measurable symmetric $    \mathsf s_{i}\geqslant 0.$

\end{itemize}
Then for $ R>0,$ $ \mathsf{M}$ is linearly $ k$-rigid on $ B_{ R}$ if for all $ \varepsilon >0$
\begin{align}

 \int_{B(0,\varepsilon )}\frac{ \|u\|^{ 2k}}{   \mathsf s(u)}du=\infty .
\end{align}
 {As noted in  [LotzKlatt],  (equation eq:simple-condition-k-rigidity of the paper) is also implied by the $ (2k + d)$-hyperuniformity of $ \mathsf{M}$.} In particular, a $ d$-hyperuniform process is always number rigid. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:growth of arXiv:2604.14851, 'Pool model: a mass preserving multi particle aggregation process'] \

\begin{enumerate}

\item { For $\lambda<1$, we have asymptotically a.s. $\sqrt{t}\log^{-\frac{1+\epsilon}{2}}(t)\le {\mathcal{E}}_t\le \sqrt{t}\log(t)$ for all $\epsilon>0$. }
\item For $\lambda=1$, $\forall\zeta<1$, {$\limsup_{t\to\infty}\frac{{\mathcal{E}}_t}{t^\zeta}=\infty$ a.s.}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 11 (Log-concave bilinear forms) of arXiv:2608.27657, '\bfseries Stein Kernels and Normal Approximation\\ for Log-Concave Bilinear Forms'] Assume the estimates in \cref{thm:letwin}.  Let
\(X\in\R^m\) and \(Y\in\R^n\) be independent isotropic log-concave random
vectors, let \(0\neq B\in\R^{m\times n}\), and set
\[
  S=X^{\mathsf T}BY,
  \qquad
  \sigma^2=\|B\|_{\HS}^2.
\]
Then \(Z=S/\sigma\) admits a nonnegative scalar Stein kernel
\(\kappa_Z\) such that
\begin{equation}
  \E(\kappa_Z(Z)-1)^2
  \leq\frac{20}{r_4(B)}.
  \tag{5.2}
\end{equation}
Consequently, for \(G\sim N(0,1)\),
\begin{equation}
  \boxed{
  W_2^2\!\left(\Law(Z),\Law(G)\right)
  \leq\frac{20}{r_4(B)}.}
  \tag{5.3}
\end{equation}
Equivalently, if \(G_\sigma\sim N(0,\sigma^2)\), then
\begin{equation}
  W_2^2\!\left(\Law(S),\Law(G_\sigma)\right)
  \leq
  20\frac{\Tr((B^{\mathsf T}B)^2)}{\Tr(B^{\mathsf T}B)}.
  \tag{5.4}
\end{equation}

