[Definition 26 of arXiv:2609.03831, 'On flows generated by square-integrable vector fields'] A family $\{X_t\}_{t\in \R}$ of maps $X_t\colon \R^d \to \R^d$
	is called a \emph{group of measure-preserving transformations}, if
	\begin{enumerate}
		\item[1.] the map $t\mapsto (X_t - \operatorname{id})$ belongs to $C(\R;L^p(\R^d; \R^d))$;
		\item[2.] for all $t,s\in \R$ we have $X_s \circ X_t = X_{s+t}$ a.e.;
		\item[3.] for all $t\in \R$ we have $(X_t)_\# \L^d = \L^d$.










	\end{enumerate}

[Thm 22 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\mu_0,\mu_1\in\mathcal{P}(\mathbb{R}^d)$ have finite second moments. Then 
\begin{equation*}
BB_2(\mu_0,\mu_1)=\sup_{\phi\in C_b(\mathbb{R}^d)}\Bigl\{\int_{\mathbb{R}^d}\phi^c(x)\,\mu_0(\mathrm{d}x)-\int_{\mathbb{R}^d}\phi(y)\,\mu_1(\mathrm{d}y)\Bigr\},
\end{equation*}
where $\phi^c(x):=\inf_{y\in\mathbb{R}^d}\{|x-y|^2+\phi(y)\}$,
and the infimum is achieved for the problem $BB_2(\mu_0,\mu_1)$ in~\eqref{BB} whenever it is finite.

