body:
[Corollary 26 (Several frequencies) of arXiv:2608.22342, 'Completely Positive Entropy and Fourier Central Limit Theorems for Stationary Random Measu'] For every $q\geq1$ there is a $\lambda_{dq}$-conull set
$E_\eta^{(q)}\subset(\bR^d)^q$ such that the following holds. If
$(\xi_1,\ldots,\xi_q)\in E_\eta^{(q)}$ and, for each $a$,
$h_{a,1},\ldots,h_{a,m_a}\in C_c^\infty(\bR^d;\bC)$, then
\begin{equation}

    \bigl(Z_R(\xi_a;h_{a,j})\bigr)_{a,j}
    \dto
    \bigl(G_{\xi_a}(h_{a,j})\bigr)_{a,j}
\end{equation}
in $\bC^{m_1+\cdots+m_q}$. For $a\neq b$, the two Gaussian vectors
$(G_{\xi_a}(h_{a,j}))_j$ and $(G_{\xi_b}(h_{b,j}))_j$ are independent.

[Lemma lem:marginal-density of arXiv:2608.07410, 'Extreme least singular values of random row submatrices\\ with bounded-density subgaussian'] Let $\xi$ be as in \hyperref[thm:main]{Theorem~\ref*{thm:main}}, and let $X=(\xi_1,\dots,\xi_m)$ have independent
coordinates distributed as $\xi$. Then, for every deterministic unit vector $u\in\mathbb R^m$,
\begin{equation}
\|\operatorname{dens}(\langle X,u\rangle)\|_\infty\le\sqrt2K.
\end{equation}
Furthermore, for unit vectors $u,v\in\mathbb R^m$ with $\rho=\langle u,v\rangle$ and $|\rho|<1$,
\begin{equation}
\|\operatorname{dens}(\langle X,u\rangle,\langle X,v\rangle)\|_\infty
\le \frac{C_{\mathrm{RV}}^2K^2}{\sqrt{1-\rho^2}}.
\end{equation}

