body:
[Proposition prop: bulk enhancement of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] For every $p \in [1,\infty)$, there exists $C>0$ such that for every $T>0$,
\begin{equation}
	\mathbb E[\|W_T\|_{\mathcal C^{-1/2-\kappa}_x}^p + \|\llbracket W_T^2\rrbracket \|_{\mathcal C^{-1-\kappa}_x}^p + \| \mathbb W_T^{[3]}\|_{\mathcal C^{1/2-\kappa}_x}^p] \leq C
\end{equation}
and
\begin{equation}
\mathbb E[\|\mathbb W_T^{1 \diamond [3]}\|_{\mathcal C^{-\kappa}_x}^p]+\mathbb E[\| \mathbb W_T^{2\diamond 2}  \|_{L^1_t \mathcal C^{-\kappa}_x}^p] + \mathbb E[\| \mathbb W_T^{2\diamond[3]}\|_{\mathcal C^{-1/2-\kappa}_x}^p] \leq C.	
\end{equation}
Furthermore, there exist random variables 
\begin{equation}
W_\infty, \, \llbracket W_\infty^2\rrbracket, \, \mathbb W_\infty^{[3]}, \, \mathbb W_\infty^{1 \diamond [3]}, \, \mathbb W_\infty^{2\diamond 2}, \, \mathbb W_\infty^{2\diamond[3]}	
\end{equation}
and limiting bulk enhancement
\begin{equation}
	\Xi_\infty(W):= \left( (W_t)_{t \leq \infty}, (\llbracket W_t^2 \rrbracket)_{t \leq \infty}, (\mathbb W_t^{[3]})_{t\leq \infty}, (\mathbb W_t^{1 \diamond [3]})_{t \leq \infty}, (\mathbb W_t^{2\diamond 2})_{t \leq \infty}, (\mathbb W_t^{2\diamond[3]})_{t \leq \infty} \right)
\end{equation}
 such that, for every $p \in [1,\infty)$,
 \begin{equation}
 	\lim_{T \rightarrow \infty} \mathbb E[\|\Xi_T(W)-\Xi_\infty(W)\|_{\mathfrak S}^p] = 0. 
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2608.15616, '\textbf{Compact Support Property of Super-Brownian Motion with Irregular Drift}'] Let $r >0$, $m >0$, and 
		\begin{equation}
			\psi^{m,r}(x) =
			\begin{cases}
				0, & |x| \leq r, \\
				m(|x|/r - 1), & r \leq |x| \leq 2r, \\
				m, & 2r \leq |x|.
			\end{cases}
		\end{equation}
		Then there exists a unique mild solution $V(0,\psi^{m,r})=V^{m,r}$ to 
		\begin{equation}
			\begin{cases}
				&\partial_t V^{m,r}_t(x) = \frac{1}{2}\Delta V^{m,r}_t(x) - \frac{1}{2}(V^{m,r}_t(x))^2 + \psi^{m,r}(x), \quad t >0, x\in \R,\\
				&V_0^{m,r}\equiv 0\\
				& V_t^{m,r}(x) \geq 0,  \quad t >0, x\in \R.
			\end{cases}
		\end{equation}
		Furthermore, for $(t,x) \in \R_+\times \R$, the sequence $(V_t^{m,r}(x))_{m> 0}$ is monotonically increasing in $m$.  We get the bounds
		\begin{equation}
			\lim_{m \rightarrow \infty}V_t^{m,r}(x) \leq \constFromEq{c}{eq:est_v_infty_1} (r-|x|)^{-2}, \quad t > 0,  -r<x<r,
		\end{equation}
		and
		\begin{equation}
			\lim_{m \rightarrow \infty}V_t^{m,r}(x) \leq \constFromEq{c}{eq:ext_v_infty_2} (r-|x|) t^{-\frac{3}{2}} \exp\Big(-\frac{(r-|x|)^2}{2t}\Big), \quad t>0, r-|x|>2\sqrt{t},
		\end{equation} 
		for some constants $\constFromEq{c}{eq:est_v_infty_1}, \constFromEq{c}{eq:ext_v_infty_2}>0$.

