[Definition 3 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] {\em (Spectral density)}
    Let $(\mathbf{x}_t)_{t\geq 0}$ be a (weakly) stationary $n$-dimensional stochastic process with
    $$\int_\R V(\tau)~\txtd\tau<\infty.$$ Then the spectral density is defined as 
    \begin{align}
        S_\mathbf{x}(\omega):= \mathcal{F}(V(\tau))(\omega)=\frac{1}{2\pi}\int_\R e^{-i\omega \tau} V(\tau)~\txtd \tau,
    \end{align}
    where the Fourier transform $\cF$ is interpreted componentwise.

[Prop size-to-length_estimate of arXiv:2601.00119, 'The largest common subtree of two random trees'] For all $\varepsilon\in (0,1/4)$, $\delta>0$, and $m\geq 1$, there exists an integer $N\geq 3$ such that for all $n$ large enough, it holds that
\begin{multline*}
\mathbf{P}\big(\#\tau\vee\#\tau'\leq n\, ;\, \mathrm{Ht}(\tau)\leq n^{1/2+\varepsilon} \, ;\, \Delta(\tau)\leq n^{1/2-2\varepsilon}\, ;\, \Delta(\tau')\leq n^{1/2+\varepsilon}\, ;\,\\
\big|\operatorname{LCS}(\tau,\tau')-c_{\mu,\mu'}\operatorname{LCS}_N(\tau,\tau')\big|>\delta\sqrt{n}\big)\leq n^{-m}.
\end{multline*}

[Lemma Monotonicity of arXiv:2607.21862, '\bf Uniform Large Deviations of Mckean-Vlasov Stochastic Fractional $(\alpha,p)$-Laplacian'] (\texttt{Strong monotonicity})

Let condition \textbf{A} be satisfied. Then we have:

(i)The operator $\mathbf{A}_1(t,\cdot,\cdot): \mathbb{V}_1\times\mathcal{P}_2
(\mathbb{H})\rightarrow
\mathbb{V}^*_1$ is strongly monotone, that is, for all $t\in\mathbb{R}^+$, $\psi_1,\psi_2\in \mathbb{V}_1$ and $\mu_1,\mu_2\in\mathcal{P}_2
(\mathbb{H})$,
\begin{align*}
& _{\mathbb{V}^*_1}
\big\langle \mathbf{A}_1(t,\psi_1,\mu_1)-
\mathbf{A}_1(t,\psi_2,\mu_2),
\psi_1-\psi_2\big\rangle_{\mathbb{V}_1}
\leqslant -\frac{1}{2^{p+1}K}\|\psi_1-\psi_2
\|^p_{\dot{\mathbb{V}}_1}
 -2^{-p}\beta\|\psi_1-\psi_2\|^p_p
\nonumber\\& -\frac{1}{8K} \int_{\mathbb{R}^d}\int_{\mathbb{R}^d}
\big( |\psi_1(x)-\psi_1(y)|^{p-2}
+|\psi_2(x)-\psi_2(y)|^{p-2}  \big)
|\psi_1(x)-\psi_1(y)
-(\psi_2(x)-\psi_2(y))|^{2}|x-y|^{-(d+\alpha p)}dxdy
\\&\ \ -\frac{\beta}{4} \int_{\mathbb{R}^d}  \big(|\psi_1(x)|^{p-2}+|\psi_2(x)|^{p-2}\big)
|\psi_1(x)-\psi_2(x)|^2dx
+\|\phi_6(t)\|_{\infty}
\|\psi_1-\psi_2\|^2+
\|\phi_7(t)
\|_{1}
d_{\mathcal{P}_2}^2
(\mu_1,\mu_2).
\end{align*}

(ii)The operator $\mathbf{A}_2(t,\cdot,\cdot): \mathbb{V}_2\times\mathcal{P}_2
(\mathbb{H})\rightarrow
\mathbb{V}^*_2$
is strongly monotone, that is, for all   $t\in\mathbb{R}^+$, $\psi_1,\psi_2\in \mathbb{V}_2$ and $\mu_1,\mu_2\in\mathcal{P}_2
(\mathbb{H})$,
\begin{align*}&
_{\mathbb{V}^*_2}\langle \mathbf{A}_2(t,\psi_1,\mu_1)
-\mathbf{A}_2(t,\psi_2,\mu_2) ,\psi_1-\psi_2\rangle_{\mathbb{V}_2}
 \leqslant-2^{-q}\widehat{\beta}
\|\psi_1-\psi_2\|_{\mathbb{V}_2}^{q} \\& -\frac{\widehat{\beta}}{4}\int_{\mathbb{R}^d}  \big(|\psi_1(x)|^{q-2}+|\psi_2(x)|^{q-2}\big)
|\psi_1(x)-\psi_2(x)|^2dx
  +\|\widehat{\phi}_6(t)\|_{\infty}
\|\psi_1-\psi_2\|^2+
\|\widehat{\phi}_7(t)
\|_{1}
d_{\mathcal{P}_2}^2
(\mu_1,\mu_2).
\end{align*}

