[Definition 3 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{Shade.}

Let $\landsc$ be a landscape, $(x_1, y_1)$ a point of $\Half$, and $(a, b)\in \landsc$ a building. We call the \textit{shade} of $(a, b)$ from $(x_1, y_1)$ the set of points right to $a$ that form a lower angle with $(x_1, y_1)$ than $(a, b)$ does:
\[S^{(x_1, y_1)}_{(a, b)} = \left\{ (x, y)\in \Half:x \geq a,\  \frac{y-y_1}{x-x_1}\leq \frac{b-y_1}{a-x_1}\right\}.\]

[Definition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] We call an $ H $-valued, $ \mathbf{F} $-adapted, continuous stochastic process $ X(\cdot) $ a mild solution to (eqSEE of the paper) if   $F(\cdot, X(\cdot)) \in L^1(0, T ; H)$ a.s., $\widetilde{F}(\cdot, X(\cdot)) \in L_{\mathbb{F}}^{2}(0, T; H)$, and for any $t \in[0, T]$,
    \begin{align*}
    X(t)\!=\!S(t) X_0\!+\!\int_0^t\! S(t\!-\!s) F(s, X(s)) d s\!+\!\int_0^t\! S(t\!-\!s) \widetilde{F}(s, X(s)) d W(s),  \;\,  \text { a.s. }
    \end{align*}

[Thm LSimplex of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] For ${\boldsymbol{\gamma}} \in {\mathbb R}^{d_1}$ with ${\gamma}_i  > -1$, $1\le i \le d_1$ and ${\boldsymbol{\kappa}} \in {\mathbb R}^{d_2+1}$ with ${\kappa}_i > -1$, $1 \le i \le d_2+1$, 
define
\begin{align} 
{\mathfrak D}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{L \rtimes \triangle}  : =\,& -(1-|{\bm y}|) \left({\mathfrak L}_{\boldsymbol{\gamma}}^{d_1, ({\bm x})}\right)^2 + {\mathfrak L}_{\boldsymbol{\gamma}}^{d_1, ({\bm x})} {\langle} {\bm x}, \nabla_{\bm x}{\rangle}+{\langle} {\bm x}, \nabla_{\bm x}{\rangle} {\mathfrak L}_{\boldsymbol{\gamma}}^{d_1, ({\bm x})} \\
 & +({\kappa}_{b_2+1} + |{\boldsymbol{\gamma}}| +d_1) {\mathfrak L}_{\boldsymbol{\gamma}}^{d_1, ({\bm x})} +  {\mathfrak L}_{\boldsymbol{\kappa}}^{d_2, ({\bm y})} - ({\langle} {\bm x}, \nabla_{{\bm x}} +{\langle} \bm y, \nabla_{\bm y}{\rangle})^2 
 \notag \\
 &     - (|{\boldsymbol{\kappa}}|+{\beta}+ d_2) ( {\langle} \bm x, \nabla_{\bm x} {\rangle} +{\langle} \bm y, \nabla_{\bm y} {\rangle})  \notag 
 \end{align}
Then ${\mathcal V}_n(\triangle^{d_1}  \rtimes {\mathbb R}_\Sigma^{d_2}, \bm W_{{\boldsymbol{\gamma}}, {\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma})$ is an eigenspace 
of $ {\mathfrak D}_{{\boldsymbol{\gamma}},{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma}$ for each $n \in {\mathbb N}_0$. More precisely, 
\begin{align} 
  {\mathfrak D}_{\mu,{\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma} u =  - n (n + |{\boldsymbol{\kappa}}|+ |{\boldsymbol{\gamma}}|+d_1+d_2) u, \qquad \forall u \in {\mathcal V}_n\big(\triangle^{d_1}  \rtimes {\mathbb R}_\Sigma^{d_2}, \bm W_{{\boldsymbol{\gamma}}, {\boldsymbol{\kappa}}}^{\triangle \rtimes \Sigma}\big).
\end{align}

[Corollary cor:sample_Gn of arXiv:2607.16911, 'Multipartite random graphs with given degrees: local limit, revisiting the giant, distance'] Consider graphs $G_{i,j}$ defined as follows. If $(i,j)$ is $\rm BAD$, we simply let $G_{i,j}$ be a uniform random simple graph with degree sequence $\mathbf d_i(n)$ if $i=j$ and with degree sequence $\mathbf d_{(i,j)}(n)$ if $i \neq j$. If $(i,j)$ is $\rm GOOD$, we let $G_{i,j}$ be $CM_n^{i,j}$. Recall $G_n$ is a uniform multipartite random graph with given degree sequences, satisfying Assumptions (assump:part_i_size of the paper), (assump:degree_regularity of the paper), (assump:one_good_deg_greater_2 of the paper) and (assump:offspring_degree_reg of the paper). The following statements are true:
    \begin{itemize}
        \item The random graph $\mathbb G_n:=\mathcal G(G_{i,j}:i,j\in [k])$ conditionally on the event $\{\mathbb G_n \textrm{ is simple}\}$ has the same law as $G_n$.
        \item Moreover,
        \begin{align*}
            \liminf_{n \to \infty}\Prob{\mathbb G_n \textrm{ is simple}}=\left(\prod_{\substack{i\in [k]:\\(i,i)\textrm{ is GOOD}}}e^{-\phi_i/2-(\phi_i)^2/4}\right)\left(\prod_{\substack{i\neq j \in [k]:\\(i,j)\textrm{ is GOOD }}}e^{-\phi_{i,j}} \right)>0.
        \end{align*}
        Thus, for any subset $A_n$ of simple graphs, $\mathbb{P}\left(G_n\in A_n\right)=o(1)$ if and only if $\mathbb{P}\left(\mathbb G_n \in A_n\right)=o(1)$.  
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2605.09372, 'Sharp weighted norm estimates for martingale square functions'] Let $1<r<p<\infty$. Given a scalar weight $w\in A_p$, we have
	\begin{equation*}
		\left\|\mathcal T_{w,r}f\right\|_{L_p(\Omega)} \lesssim_{p,d}[w]_{A_p}^{\max\{\frac1r ,\frac1{p-1}\}} \|f\|_{L_p(\Omega)},\quad\forall f\in L_p(\Omega).
	\end{equation*}

[Corollary 9 of arXiv:2604.10051, 'Ergodicity of the voter model with dynamic anti-voter bonds'] Fix~$k \in \N$. Then, for any configuration~$(\eta,\zeta,\mathbf x, \mathbf i,A,B ) \in \Omega \times \mathcal S_k$, with~$\mathbf x = (x_1,\dots,x_k)$ and~$\mathbf i = (\mathsf i_1,\dots, \mathsf i_k)$, and any time~$t \ge 0$,
\begin{equation}
    \begin{aligned}
    P_{\eta,\zeta}( \eta_t(x_1)  =\mathsf i_1,\dots \eta_t(x_k) &=  \mathsf i_k, \zeta_t \equiv 1 \text{ on } A, \zeta_t \equiv -1 \text{ on } B ) \\[0.2cm]
    & = p^{|A|}(1-p)^{|B|} \cdot E_{\mathbf{x},\mathbf{i},A,B}[D(\eta,\zeta,\mathbf Y_t,\mathbf i_t,A_t,B_t) ].        
    \end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 11 (Moment bounds) of arXiv:2605.21459, 'Network evolution with self-reinforcement'] $\E([\hat\mvzeta_{\ve}(\gl)]^l) < \infty$ for every $l \geq 1$. This implies that for every $l\geq 1$, there exist constants $H_l^{\circ}, H_l^\prime < \infty$, such that
\begin{equation}

	\sup_{t\geq 0} \E\left[\big[\ee^{-\lambda t} |\BP^\circ_{\ve}(t)|\big]^l\right] \leq H_l^{\circ}, 
	\qquad  \Rightarrow \sup_{t\geq 0} \E\left[\big[\ee^{-\lambda t} |\BP_{\Sr,\ve}(t)|\big]^l\right] \leq H_l^\prime. 
\end{equation}

