[Lemma of arXiv:2609.03959, 'The combinatorial Hopf algebra of signed graphs'] Given a graph $G = (V,E)$

\begin{equation}
    w_G(x,t) = \sum_{\kappa: V \rightarrow [t]}x^{rk(I(\kappa))}.
\end{equation}

[Define 8 of arXiv:2506.10522, 'On the Law of the Iterated Logarithm for $m$-dependent stationary random variables under s'] Another countably sub-additive capacity generated by $\mbE$ can be defined as follows:
 \begin{equation} \tildeCapc(A)=\inf\Big\{\lim_{n\to\infty}\mbE[\sum_{i=1}^n g_i]: I_A\le \sum_{n=1}^{\infty}g_n, 0\le g_n\in\mathcal{H}\Big\},\;\;\; A\in\mathcal F.
\end{equation}

[Proposition lem:A of arXiv:2609.01776, 'On the Cuspidal Cohomology of Iwahori Congruence Subgroups of $\mathrm{SL}(3, \mathbb{Z})$'] Let $p$ be a rational prime and let $e_1, e_2, e_3$ be the standard basis of column vectors in $\mathbb{Q}^3$.  A set of representatives of $\mathcal{I}(3, p)$-orbits of maximal proper parabolic $\mathbb{Q}$-subgroups of $\mathrm{SL}(3)$ is given by
    \begin{align*}
        P_1 = \mathrm{Stab}\langle e_1 \rangle, && P_1^T  = \mathrm{Stab}\langle e_2, e_3 \rangle, \\
        P_2 = \mathrm{Stab}\langle e_2 \rangle, && P_2^T = \mathrm{Stab}\langle e_1, e_3 \rangle, \\
        P_3 = \mathrm{Stab}\langle e_3 \rangle, && P_3^T = \mathrm{Stab}\langle e_1, e_2 \rangle. 
    \end{align*}
    Moreover, a set of representatives of $\mathcal{I}(3, p)$-orbits of minimal parabolic $\mathbb{Q}$-subgroups of $\mathrm{SL}(3)$ is given by
    \begin{align*}
        P_1 \cap P_2^T, && P_1 \cap P_3^T, \\ 
        P_2 \cap P_3^T, && P_2 \cap P_1^T, \\
        P_3 \cap P_1^T, && P_3 \cap P_2^T.
    \end{align*}

[Theorem 5 (Averaging principle via weak convergence of projected processes) of arXiv:2607.17943, 'Coadjoint averaging and cross-scale fluxes in a fast-slow stochastic Euler-Arnold system o'] As $\varepsilon \rightarrow 0$, the family of (non-Markov) processes $\zeta_t^{\varepsilon,\delta}=\pi(\Omega^{\varepsilon,\delta}_{t\wedge \tau^{\varepsilon,\delta}})$ converges weakly to $Z_{t\wedge \tau^\delta}^\delta$ in $\mathbf{C}_{[0,T]}(\mathcal{A})$. In other words, for any bounded continuous functional $F$ on $\mathbf{C}_{[0,T]}(\mathcal{A})$ we have, as $\varepsilon \rightarrow 0$, \begin{equation}
\mathbf{E}_{\Omega^{\varepsilon,\delta}_0=\Omega_0} F(\pi(\Omega^{\varepsilon,\delta}_{t\wedge \tau^{\varepsilon,\delta}}))\rightarrow \mathbf{E}_{Z_0^\delta=\pi(\Omega_0)} F(Z_{t\wedge \tau^\delta}^\delta) \ .
\end{equation}

[Definition 3 (Weakly geometric $p$-rough paths) of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $p\geq 1$. We define $C^{\textup{$p$-var}}_o([0,T],G^{\lfloor p\rfloor}(\mathbb{R}^k))$ as the set of continuous paths $\mathbf{x}:[0,T]\rightarrow G^{\lfloor p\rfloor}(\mathbb{R}^k)$ such that $\mathbf{x}_0=(1,0,\dots,0)$ and
    \begin{equation*}
        \lVert \mathbf{x} \rVert_{\textup{hom $p$-var};[0,T]} < \infty \qquad (\textit{equiv.}\; \lVert \mathbf{x} \rVert_{\textup{inhom $p$-var};[0,T]} < \infty).
    \end{equation*}

[Definition 7 (Definition 4.1 of \cite{Chen2024}, with the omitted $\lambda^2S_{2424}$ term restored; cf.\ Definition 4.1 of \cite{Brendle2019}) of arXiv:2608.26598, 'Pinching cones for positive isotropic curvature in dimensions seven and eight'] Assume $0<b\le\tilde b_{max,2}$ and let $a=b+\frac{n-2}{2}b^2$. We denote by
        $\tilde{\mathcal{E}}(b)$ the set of all $S\in\CB(\mathbb{R}^n)$ such that
        $l_{a,b}(S)\in C(b_{max,2})$ and
        \begin{equation}
            Z:=S_{1313}+\lambda^2S_{1414}+S_{2323}+\lambda^2S_{2424}-2\lambda S_{1234}
            +\sqrt{2a}(1-\lambda^2)\bigl(\Ric(S)_{11}+\Ric(S)_{22}\bigr)\geq 0
        \end{equation}
        for every orthonormal four-frame $\{e_1,e_2,e_3,e_4\}$ and every $\lambda\in[0,1]$. We then
        define $\tilde C(b)=l_{a,b}(\tilde{\mathcal{E}}(b))$.

[Lemma of arXiv:2607.14993, 'Sharp phase transition for percolation with short-range dependencies'] With the assumptions of Lemma~(lem:ineq-pivot-site-bond of the paper),
  \begin{equation}
    \mathbb P(x \text{ pivotal for } A_n) \leqslant \frac p {q (1-p)^{2d-2} (p \wedge (1-p))} \sum\limits_{e \in \mathcal N(x)} \mathbb P(e \text{ pivotal for } A_n).
  \end{equation}

[Prop rieszLaplaceLogFallback of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Assume $0\le\mathsf{s}<\mathsf{d}/2$, $\mu\in L^\infty\cap\mathcal{P}({\mathbb{R}}^\mathsf{d})$, and $\beta>0$ is fixed.  If $\mathsf{s}=0$, assume in addition (equation eq:logEnergyAssumption of the paper) and (equation eq:logRateExtraAssumptions of the paper).  Then there are constants $C_{\beta,\mu}<\infty$ and, in the case $\mathsf{s}=0$, $c_{\beta,\mu}>0$ such that, for all $N\ge1$,
\begin{align}
\Big|{\mathbb{E}}_{\mu^{\otimes N}}\Big[e^{-\frac{\beta}{2}W_N}\Big]
-\mathrm{det}_2(\mathrm{Id}+\beta T_\mu)^{-1/2}\Big|
\le C_{\beta,\mu}
\begin{cases}
(\log(e+N))^{-\frac{\mathsf{d}-2\mathsf{s}}{2\mathsf{s}}}, & 0<\mathsf{s}<\mathsf{d}/2,\\[0.4em]
(e+N)^{-c_{\beta,\mu}}, & \mathsf{s}=0.
\end{cases}
\end{align}

