[Lemma single of arXiv:2412.04396, 'Superdiffusive Scaling Limits for the Symmetric\\ Exclusion Process with Slow Bonds'] Fix a measure $v$ on $\Omega_{nk}$. Fix $x\in{\mathbb T}_{kn}$ and  let $h:\Omega_{kn}\to{\mathbb R}$ be such that $h(\eta)=h(\eta^{x,x+1})$ for every $\eta\in\Omega_{nk}$. Then, for any $A>0$ and any density $f$ with respect to $\nu$,
	\begin{equation*}
		\begin{split}
			\int h(w(x+1)-w(x)) f d\nu\;\leq\; &A\, {\mathfrak D}_{x,x+1}(\sqrt{f},\nu)\,+\,\frac{4}{A\varepsilon_0}\int h^2 fd\nu\\
			\,& - \Big[\rho(m_n(x+1))-\rho(m_n(x))\Big]\int hw(x)w(x+1)fd\nu\,,
		\end{split}
	\end{equation*}
	where we recall that
	${\mathfrak D}_{x,x+1}(\sqrt{f};\nu):= \int \big[\sqrt{f(\eta^{x,x+1})}-\sqrt{f(\eta)}\big]^2 d\nu.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem3 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Let $p\ge 2$ and $q\in [p,\frac{(n+2)p}{n}]$. Then there exists $C(p,q)>0$ such that
  \begin{equation} \label{3.1}
	\int_\Omega |\nabla\varphi|^q
	\le C(p,q) \cdot \bigg\{ \int_\Omega |\nabla\varphi|^p \bigg\}^\frac{q-p}{p} \cdot \int_\Omega |\nabla\varphi|^{p-2} |D^2 \varphi|^2
	\qquad \mbox{for all $\varphi\in C^2(\overline{\Omega})$ fulfilling $\varphi=0$ on $\partial\Omega$.}
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition diag:pb-regular-card of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] A regular cardinal $\kappa$ is \emph{$(S,T)$-regular} if for every pullback
    \begin{equation}
        \begin{tikzcd}
            X\arrow[r, "f'"]\arrow[dr,pullback]\arrow[d, "s'"'] & A\arrow[d,"s"]\\
            C\arrow[r,"f"'] & B
        \end{tikzcd}
    \end{equation}
    in $\PSh(T)$ such that $A,B,C$ are representable and $s$ is a map in $S$ (so that $X\in\PSh(S)$ by the definition of a cleft), $X$ can be written as a $\kappa$-small colimit in $\PSh(S)$ of representables.

[Lemma 21 (Six-move elimination) of arXiv:2608.08242, 'Bang--bang representation of $3\times 3$ embeddable stochastic matrices'] Suppose that $U\notin\V$.  Then $U\in R_6$ in each of the following
regions:
\begin{enumerate}[(1)]
\item $1<r\leq2$ and $\min(x,y)\leq r$;
\item $r\geq3$ and $\max(x,y)\geq r$;
\item $2\leq r\leq3$ and $\min(x,y)\geq r$.
\end{enumerate}

