body:
[Lemma paris of arXiv:2411.07609, 'Activated Random Walks on $\bZ$ with Critical Particle Density'] Let $\omega_{\text{initial}},\ \omega_{\text{final}} \in \{0,1,2,\dots\}^{\{-k^{n+1},\dots , k^{n+1}\}}$ be the initial and final configurations of the stabilization in $I_{n+1}$. If

    \begin{enumerate}
         \item there exist $z \leq  {k^n}$ such that $z \notin \text{\bf\texttt{Positive Odometer}},$
        \item $\omega_{\text{initial}}$ is {\bf\texttt{plentiful}}  \ and
        \item$\omega_{\text{final}}$ is {\bf\texttt{sparse}}\ in $[z,k^{n+1}),$ 

    \end{enumerate}
    then 





       \begin{equation} 
           \sum_{i=z}^{k^{n+1}}i\ (\omega_{\text{final}}(i)-\omega_{\text{initial}}(i))>(\delta/10)(k^{n+1})^2.  \end{equation}

