body:
[Corollary 49 (Full Newton congruence filtration) of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$, every $n\ge2$, and $r>s\ge0$,
\begin{equation}
 J_r^{SU(n)}(K;q)-J_s^{SU(n)}(K;q)
 \in\{r-s\}\{r+s+n\}\Z[q^{\pm1}].
\end{equation}
More generally, for $0\le m<r$,
\begin{equation}
 J_r^{SU(n)}(K;q)\equiv
 \sum_{k=0}^{m}C_{r+1,k}^{(n)}H_k^{(n)}(K;q)
 \pmod{C_{r+1,m+1}^{(n)}\Z[q^{\pm1}]}.
\end{equation}

[Lemma lem:hit_close_to_tree of arXiv:2607.25428, 'The local weak limit of the minimum spanning arborescence in the complete graph'] For all $n \ge 1$,
 \begin{align*}
  \mathbb{P}^{{\sf t}}(\text{a vertex in  $\mathcal{N}_{ A_n^2}$ is hit in steps  $(n\varepsilon_n,2n\varepsilon_n)$})  \ge 1-O(|{\sf f}|\varepsilon_n).
 \end{align*}

[Lemma lem:formula u and h of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Fix $q\in(0,1)$ and $c\in[0,1)$.  For each $n,k,\ell\in\mathbb{Z}_{\geq0}$, we have
\begin{align}
    u_n^k(\ell)
&=
\frac1\pi\int_0^{2\pi}
\sin((\ell+1)\theta)\sin((k+1)\theta)
\left(1+\frac{4q}{(1-q)^2}\sin^2\frac{\theta}{2}\right)^{-n}
\mathsf{d}\theta ,\\
\sum_{j\geq0}c^j u_n^{k}(j)
&=\frac1\pi\int_0^{2\pi}
\frac{\sin\theta}{1-2c\cos\theta+c^2}
\sin((k+1)\theta)
\left(1+\frac{4q}{(1-q)^2}\sin^2\frac{\theta}{2}\right)^{-n}
\mathsf{d}\theta.
\end{align}

