body:
[Definition def:rwre of arXiv:2603.22652, 'A cohesive account on the ergodic behaviours and scaling limits of Random Walks in Cooling'] Let $\omega$ be sampled from $\mu$. The \emph{random walk in random environment}
(RWRE) is the Markov chain $Z=(Z_n)_{n\in{\mathbb {N}}_0}$ on ${\mathbb {Z}}$ with transition
kernel
\begin{equation}
P^{\omega}(Z_{n+1}=x+e\mid Z_n=x)=
\begin{cases}
\omega(x), & e=+1,\\
1-\omega(x), & e=-1,
\end{cases}
\qquad x\in{\mathbb {Z}},\ n\in{\mathbb {N}}_0.
\end{equation}
We write $P_x^{\omega}$ for the \emph{quenched} law of $Z$ started at $x$ and
\begin{equation}
P_x^{\mu}(\,\cdot\,):=\int_{(0,1)^{{\mathbb {Z}}}} P_x^{\omega}(\,\cdot\,)\,\mu(d\omega)
\end{equation}
for the corresponding \emph{annealed} law (with expectations $E_x^{\omega}$ and
$E_x^{\mu}$).

[Corollary 8 (The Poincar\'e inequality) of arXiv:2605.29608, '2605.29608'] Let $(Y_{k})_{k\in\mathbb{Z}^{+}}$ and $\mu_{N}$ be defined as in Theorem \ref{thm: transitionmatrix}. For the coupling constant $\hat{J}\in [0,+\infty)$, the following Poincar\'e inequality holds 
	\begin{align*} 
		E_{\mu_{N}}[f^{2}]-(E_{\mu_{N}}[f])^{2}\leq&\frac{e^{2\hat{J}}(e^{4\hat{J}}+1)}{2}\big(\frac{1}{2}+\hat{J}e^{\frac{e^{2\hat{J}}-1}{2}}\big)N	\mathcal{E}^{\text{W}}_{\mu_{N}}(f),
	\end{align*}
	where $f$ is any real-valued function defined on $\Omega$. (Proof in the paper; no proof environment follows the statement in the TeX.)

