[Defi def_condNegSemiDef of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] Let $A$ be a set and let $f:A\times A\to \mathbb{R}_{\geq 0}$ be a symmetric function. Then it is called conditionally negative definite, if for any $n\in\mathbb{N}$, any $\lambda_1, \ldots, \lambda_n \in\mathbb{R}$ with $\lambda_1 + \ldots + \lambda_n=0$ and any $x_1, \ldots, x_n \in A$ it holds that
    \begin{align*}
        \sum_{i,j=1}^n \lambda_i \lambda_j f(x_i, x_j) \leq 0.
    \end{align*}

[Lem prop:s(n)-properties of arXiv:2608.26876, 'Local Bousfield classes via homological support'] The following hold:
	\begin{enumerate}
		\item For each $0\le n \le \infty$, $\mathinner{\langle T(n)/p \rangle}^{\mkern-2mu *} = \mathinner{\left\langle I(T(n)/p) \right\rangle}_{\mkern-2mu *}$.
		\item For each $0\le n < \infty$, $\ihom{T(n+1)/p,T(n)/p} = 0$.
		\item For each $0\le n < \infty$, $\ihom{BP/p,T(n)/p} = 0$.
	\end{enumerate}

[Lemma lm:cNhaplrandomall of arXiv:2601.09537, 'Gene genealogies in haploid populations evolving according to sweepstakes reproduction'] Suppose the conditions of Theorem~(thm:haplrandomalpha of the paper) hold with
$1 \le \alpha < 2$, $\ensuremath{{\kappa}} \ge 2$, and $c > 0$ all fixed, and that
${\ensuremath{\zeta(N)}}/N \gneqq 0$.  Let $L \equiv L(N)$ be a function of $N$ such that
$L/N \to 0$, and
\begin{equation}

\begin{split}
\varepsilon_{N}  =  cN^{\alpha - 2} \left( \ensuremath{\mathds{1}_{\left\{ \kappa > 2 \right\}}} + \ensuremath{\mathds{1}_{\left\{ \kappa = 2 \right\}}}\log N \right)   
\end{split}
\end{equation}
Then, with $\kappa + 2 < c_{\kappa} < \kappa^{2}$ when $\kappa > 2$
and with $C_{\kappa}^{N} $ as in (equation eq:CNmap of the paper), $\gamma$ as in
(equation eq:27 of the paper), $B(\gamma,2-\alpha,\alpha)$ as in
Definition~(def:betacoal of the paper), $f_{\alpha}^{(\infty)} = g_{\alpha}^{(\infty)}$ and
$\underline {g_{\kappa}}(2) = \overline {f_{\kappa}}(2)$, we have
$ \lim_{N\to \infty} C_{\kappa}^{N} c_{N} = C_{\kappa,\alpha,\gamma}$ where
$C_{\kappa,\alpha,\gamma}$ as in (equation eq:23 of the paper) and $m_{\infty}$ as in
(equation eq:49 of the paper), i.e.\
\begin{equation}

\begin{split}
&  C_{\kappa,\alpha,\gamma}  =   \frac{  2 \overline {f_{\kappa}}(2) }{m_{\infty}^{2}}\left( \ensuremath{\mathds{1}_{\left\{ \kappa = 2 \right\}}}  + \ensuremath{\mathds{1}_{\left\{ \kappa > 2 \right\}}}  \frac{ c_{\kappa} }{2^{\kappa}(\kappa -2)(\kappa - 1) } \right)  +       \frac{ c\alpha f_{\alpha}^{(\infty)} }{m_{\infty}^{\alpha}}  B(\gamma, 2-\alpha,\alpha) 
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

