body:
[Theorem th:non-conservative of arXiv:2412.01489, 'One- and two-particle spectral gap identities for the symmetric inclusion process and rela'] For all graphs $G=(V,(c_{xy})_{x,y\in V})$, and site weights $\alpha=(\alpha_x)_{x\in V}$, $\omega=(\omega_x)_{x\in V}$ with $\omega\neq 0$, we have
	\begin{equation}
		{\rm gap}_{\rm SIP}(G,\alpha,\omega)= {\rm gap}_{\rm RW}(G,\alpha,\omega)\; \text{.}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop: 1wr fixed n of arXiv:2507.04505, 'Heights of butterfly trees'] Let $\pi \sim \operatorname{Unif}(S_n \wr S_m)$ or $\pi \sim \operatorname{Unif}(S_m \otimes S_n)$, and $h_{n,m} = h(\mathcal T(\pi))$. Then for any $\varepsilon>0$,
    \begin{equation*}
        \lim_{m \to \infty} \mathbb{P}\left({h_{n,m}} \ge (c^* H_n^{(1)}-\varepsilon)\log m\right) = 1.
    \end{equation*}

[Lemma 44 of arXiv:2508.04938, 'Perfect t-embeddings of doubly periodic Aztec diamonds'] Let~$0\leq \ell x'+i'\leq \ell N-1$,~$0\leq 2y'+j'\leq 2\ell N-2$,~$1\leq \ell x+i\leq 2\ell N-1$ and~$0\leq 2y+j\leq 2\ell N-1$, with~$i,i'=0,\dots,\ell-1$ and~$j,j'=0,1$, and set~$w=w_{\ell x'+i',2y'+j}$ and~$b=b_{\ell x+i,2y+j}$. Then 	
\begin{align}
& K^{-1}(w_{0,2y'+j'},b)
  =
  -d^{-N}\left(
\begin{pmatrix}
1 \\
-\alpha_1
\end{pmatrix}
\begin{pmatrix}
1 & -\alpha_1^{-1}
\end{pmatrix}
\frac{1}{2\pi\i}\int_{\tilde \Gamma_l}Q(z_2,w_2)
  \prod_{m=1}^{2i}\phi_m(z_2)\right)_{j'+1,j+1}\\
  &\times\frac{(z_2-1)^{\ell N}w_2^{x-N}\d z_2}{z_2^{y+1}(z_2-1)},  \\
&
  K^{-1}(w_{2\ell N-1,2y'+j'},b)=
  d^{-N}\left(\begin{pmatrix}
1 \\
\beta_\ell
\end{pmatrix}
\begin{pmatrix}
1 & \beta_\ell^{-1}
\end{pmatrix}
\frac{1}{2\pi\i}\int_{\tilde \Gamma_l}Q(z_2,w_2)
  \prod_{m=1}^{2i}\phi_m(z_2)\right)_{j'+1,j+1} \\
  &\times\frac{(z_2-1)^{\ell N}w_2^{x-N}\d z_2}{z_2^{y+1}(z_2-1)}, \\
&
  K^{-1}(w,b_{\ell x+i,0})=
  (-1)^{\ell x+i}\prod_{m=1}^i\alpha_m^{-1}\beta_m\\
 &\times\frac{1}{2\pi\i}\int_{\tilde \Gamma_s}\left(\left(\prod_{m=1}^{2i'+1}\phi_m(z_1)\right)^{-1}Q(z_1,w_1)\right)_{j'+1,1}
  \frac{1}{(z_1-1)^{\ell N}}\frac{z_1^{y'}}{w_1^{x'-N}}\frac{\d z_1}{(-z_1)}, \\
&
  K^{-1}(w,b_{\ell x+i,2\ell N-1})
  = \frac{1}{2\pi\i}\int_{\tilde \Gamma_s}\left(\left(\prod_{m=1}^{2i'+1}\phi_m(z_1)\right)^{-1}Q(z_1,w_1)\right)_{j'+1,2}
  \frac{z_1^{y'}\d z_1}{(z_1-1)^{\ell N}w_1^{x'-N}}. 
\end{align}
where~$\tilde \Gamma_s$ and~$\tilde \Gamma_l$ are given in~\eqref{eq:inv_kast_2xell}.

[Corollary corollaryatthebeginning of arXiv:2411.16103, 'Non-commutative Stein's Method: Applications to Free Probability and Sums of Non-commutati'] Let $ \mu_{k,n}$, with $k,n\geq 1$ be centered probability measures with uniformly bounded supports, such that 
\begin{align*}
\sum_{k=1}^{n}\int_{\mathbb{R}}x^2\mu_{k,n}(dx)=1,
\end{align*}
for all $n\geq 1$. Then, we can find a  constant $C>0$, independent of $n$, such that for large enough $n$, 
\begin{equation}
d_{TV}(\mu_{1,n}\boxplus\cdots\boxplus \mu_{n,n},\mathbf{s}) \leq C\sum_{k=1}^nm_{3}[\mu_{k,n}],
\end{equation}
where $d_{TV}$ denotes distance in total variation. In particular, if the $\mu_{k,n}$ are constant over $k$, 
\begin{equation}
d_{TV}(\mu_{1,n}\boxplus\cdots\boxplus \mu_{n,n},\mathbf{s}) \leq Cn^{-1/2}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 29 of arXiv:2605.30616, 'Brownian motion: the hyperbolic number setting'] The sum 
\begin{equation}
N_{p}(\w)=\sum_{n=0}^{\infty}U\begin{pmatrix}\zeta_{n}(\lambda_{1})Z_{n}(\w) & 0\\
0 & \zeta_{n}(\lambda_{2})W_{n}(\w)
\end{pmatrix}U.
\end{equation}
belongs to $\mathcal{K}^{\prime}$. It is the derivative of $B_{p}$
in the topology of $\mathcal{K}^{\prime}$, in the sense that 
\begin{equation}
\lim_{\substack{h\rightarrow0\\
h^{-1}\,\,{exists}
}
}\frac{B_{p+h}-B_{p}}{h}=N_{p}.
\end{equation}

[Proposition 1 of arXiv:2604.10266, 'A singular SDE driven by additive fractional Brownian motion with Hurst parameter $H<\frac'] Let $b(t)$ be a continuous function on $[0,\infty)$. Assume that continuous functions $x^i=\{x^i_t,\, t\geq 0\}$, $i=1, 2$, satisfy the following equations
\begin{equation*}
x^i_t=x_0+\int_0^tg_i(s)f_i(x^i_s)ds+\int_0^t h_i(x^i_s)ds+b(t), \ t\geq 0,
\end{equation*}
where $x_0\in\mathbb{R}$ is a constant, and $g_i, f_i, h_i$, $i=1, 2$, are continuous functions such that 
\begin{itemize}
\item[(a)] $0<g_1(t)<g_2(t)$, $\forall t\geq 0$;
\item[(b)] $0< f_1(x)<f_2(x)$, $\forall x\in\RR$;
\item[(c)] $h_1(x)\leq h_2(x)$, $\forall x\in\RR$.
\end{itemize}
Then, for all $t> 0$, we have $x^1_t<x^2_t$.

[Prop cor:decomposition of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] For every $\mathsf{q} \in \mathsf{R}_1\cup \cdots \cup \mathsf{R}_7$, there exist constants $C, c, L_0>0$ such that for every $\mathbf{n} \in {\mathbb N}^3$ with $\mathbf{n}\neq (1,1,1)$, and for ${\boldsymbol \sigma}, {\boldsymbol \tau} \in \mathcal S_{\mb{n}}$ of the forms 
\begin{equation} 
    {\boldsymbol \sigma} = 3^{n_{31}}2^{n_{21}}1^{n_{1}}2^{n_{22}}3^{n_{32}}, \qquad {\boldsymbol \tau} = 3^{n'_{31}}2^{n'_{21}}1^{n_{1}}2^{n'_{22}}3^{n'_{32}}
\end{equation} 
satisfying 
\begin{itemize}
\item $\mathbf{n}\neq (1,2,1)$ when $\mathsf{q}\in \mathsf{R}_6\cup \mathsf{R}_7$, 
\item $n_1\ge n_{21}+1$ when $\mathsf{q}\in \mathsf{R}_5\cup \mathsf{R}_6\cup \mathsf{R}_7$, 
\end{itemize}
we have, for every $L\ge L_0$, 
\begin{equation} 
    |\mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}} |  
    \le  C^{|\mathbf{n}|} 
    \frac{ (n_1!)^{3/2} (n_2!)^2 (n_3!)^{3/2}}{\sqrt{(n_1\vee n_2- n_1\wedge n_2)! (n_2\vee n_3- n_2\wedge n_3)!}}  e^{-cL} \mathsf{Z}_L .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

