body:
[Theorem thm:G-moments of arXiv:2412.01015, 'Classical beta ensembles and related eigenvalues processes at high temperature and the Mar'] Assume that each moment of the initial empirical measure $\mu_0^{(N)}$ converges to a limiting moment, that is, for each $n$,
\begin{equation}
	S_n^{(N)}(0) = \frac{1}{N} \sum_{i=1}^N x_i(0)^n \to a_n \quad \text{as} \quad N \to \infty.
\end{equation}
Then it holds that 
\[
	S_n^{(N)}(t) \to m_n(t) \quad \text{as} \quad N \to \infty,
\]
in probability as random elements in $C([0, T])$. Here the limiting moment processes are recursively defined by $m_0(t) = 1, m_1(t) = a_1,$
\begin{align}
	m_n(t) &= a_n + \sigma^2 \frac{cn}2 \sum_{j=0}^{n-2}\int_0^t m_j(u) m_{n-2-j}(u) du\notag\\
	&\quad +\sigma^2 \frac12 n(n-1) \int_0^t m_{n-2}(u) du, \quad (n \ge 2).
\end{align}

[Lemma phasperotrai of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Suppose (equation eq: Parameters of the paper) holds. Then\\\\
\underline{Relative positions}.
$$
\sigma(P_3)<\sigma(P_2)<\sigma(P_5),
$$
\underline{Convergence}.  For $r=r_+(d,\ell)$, $P_2=P_3$ and
\begin{equation}

\mathop{\rm lim}_{r\uparrow r_+} |P_2-P_3|=0
\end{equation}
\underline{Positions of $P_2,P_3$ on $\Delta_2=0$ curve}.  For $0<r_+(d,\ell)-r\ll1$ sufficiently small, $P_2$ and $P_3$ lie on the lower root curve $(\sigma,w_2^-(\sigma))$ of $\Delta_2$. Also, we have
\begin{equation}

w_2^+(\sigma_3)>1.
\end{equation}

[Lemma 36 of arXiv:2604.04823, '2604.04823'] Suppose the potential~$U$ satisfies Assumptions~\ref{a:criticalpts} and~\ref{a:massRatioBound}. If all the temperatures~$(\epsilon_k)_{k=0}^N$ are in~$[\underline \theta, \bar \theta]$, then there exists a finite constant
\begin{equation}
    \hat C_\mathrm{BV} \defeq \max_{i\in \set{1,2}}\int_{\underline\theta}^{\bar \theta} \abs*{\partial_{\epsilon'} \pi_{\epsilon'}\paren*{\Omega_i}}d\epsilon' < \infty\,,
\end{equation}
such that
    \begin{equation}
        \gamma_\pt  \geq \exp\paren*{-C_m^2 \hat C_\mathrm{BV}}\,,
    \end{equation}

