[Prop finite-energy of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Let $\beta > 0$. There exists $\varepsilon > 0$ such that the following holds. Let $\Lambda \subset \mathbb Z^d$ and $e=xy \in E(\Lambda)$. For every $\omega' \in \{0,1\}^{\overline E(\Lambda)\setminus \{e\}}$,
\begin{equation} 
\varepsilon \leq \Phi^0_{\Lambda,\beta}[\omega_{xy}=1 \mid \omega|_{\overline E(\Lambda)\setminus \{xy\}} = \omega']\leq 1-\varepsilon.
\end{equation}

[Lemma lem:growing-wedge-barrier of arXiv:2609.00698, 'Kinetic Wedge Layers and Diffusive Limit of Neutron Transport in Polygonal Domains'] Let $0<\omega<\pi$. Every $u\in L^\infty(K_\omega)$ satisfying
\begin{align}
 u&=\mathsf T_\omega u
 \quad\hbox{almost everywhere in }K_\omega

\end{align}
is identically zero.

[Theorem 37 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] Given $f_k \in \mathcal{B}_R$ and $G^k$,
\begin{equation}
   \mathscr{S}_R(f_k,G^k) (s) = \sup (G^k \cup (-\infty, G^k])_{\leq \widetilde{X}_k(s)}, \ \forall s \in (0,1)
\end{equation} 
is right continuous.

[Lemma 25 of arXiv:2605.02430, '\textbf{Scaling limit of the range of tree-valued branching random walks in random environ'] We assume that $\mu$ satisfies (\ref{hypostaintro}). Recall from (\ref{bnBiGoTe}) the definition of the slowly varying function $L\! : \! (0, \infty) \! \to \! (0, \infty)$.  
For all $s\ino [0, 1]$, we set $\varphi_\mu (s) \eqo \bE [s^{\# \tau} ]$. Then, there is a constant 
$c_\alpha\ino (0, \infty)$ that only depends on $\alpha$, such that 
\begin{equation}

n^{\frac{1}{\alpha}}L(n) \bP \big(\# \tau \geqo n  \big) \to  c_\alpha \quad \textrm{and} \quad 1\! -\! \varphi_\mu (e^{-\lambda}) \sim_{0^+} c_\alpha \Gamma_{\!\! \texttt e} \big( 1\! -\! \tfrac{1}{\alpha}\big) \lambda^{\frac{1}{\alpha}} L\big( \tfrac{1}{\lambda}\big)^{-1} 
\end{equation}
(here $\Gamma_{\!\! \texttt e} $ is Euler's gamma function). Furthermore, $n^{1+\frac{1}{\alpha}}L(n) \bP \big(\# \tau \eqo n  \big) \to  \alpha^{-1} c_\alpha $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm main of arXiv:2607.28167, 'Temporal properties of the stochastic fractional heat equation with rough dependence in sp'] Assume that Condition (cond A of the paper) holds. Then for every $p\geq 1$ and $\eta\in \mathcal{I}$, there exists a finite constant  $c_{3,1}>0$
   such that  for all $\varepsilon\in(0,1)$,  $t\in [0,T]$ and $x\in \mathbb R$,
     \begin{align}
    &\Big\| (\mathcal{D}_{\varepsilon}u)(t,x)-\big[ G_{\alpha}(t+\varepsilon,\cdot)-G_{\alpha}(t,\cdot)\big]*u_0(x)-\sigma(u(t, x))(\mathcal{D}_{\varepsilon}v)(t,x) \Big\|_{L^p(\Omega)}
    \le  c_{3,1}\,   \varepsilon^{\frac{\alpha+2H-2}{2\alpha}+\eta}.
     \end{align}

    In addition,     if the initial condition $u_0$ is H\"older continuous with order $ \beta_0>\frac{\alpha+2H-2}{\alpha}$, then there exists a finite constant  $c_{3,2}>0$
   such that  for all $\varepsilon\in(0,1)$,
     \begin{align}
   \sup_{t\in[0,T]}\sup_{x\in \mathbb{R}} \Big\|(\mathcal{D}_{\varepsilon}u)(t,x)-\sigma(u(t, x))(\mathcal{D}_{\varepsilon}v)(t,x) \Big\|_{L^p(\Omega)}\le c_{3,2}\varepsilon^{\frac{\alpha+2H-2}{2\alpha}+\eta}.
     \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:var conv of arXiv:2412.06615, 'A family of log-correlated Gaussian processes'] For all $r>0,\delta>0$ and $f\in{\mathcal F}_\delta$, 
\begin{align*}
\lim_{n\to\infty} {\mathbb E}\psi_{n,r/n}(f)^2 &= 4{\mathbb E}\pp{\int_0^\infty f(s)\pp{\inddd{N(rs){\rm~is~odd}} - \wt p_r(s)}{\rm d} s}^2\\
& = \int_0^\infty\int_0^\infty f(s)f(t)\log\frac{s+t}{|t-s|}{\rm d} s{\rm d} t.\nonumber
\end{align*}

