[Lemma lem: CokMp_Trivial of arXiv:2603.26932, 'On the satisfaction frequency of spectral characterization conditions'] Let $q = p^{\operatorname{deg}(\beta)}$. Then, for every $n\geq 1$, 
    \begin{align}
        \biggl\lvert \, \bbP\biggl(\frac{\coker(\bM_{p,\beta})}{p\coker(\bM_{p,\beta})}  \cong 0   \biggr) - \prod_{i\geq 0}\Bigl(1 - \frac{1}{q^{2i+1}} \Bigr)     \, \biggr\rvert \leq \frac{3}{q^n}.
    \end{align}

[Theorem thm:bismut-formula of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] Let $X(t)$ be the variational solution of (equation eq:SPDE of the paper) under Assumptions (ass:LR of the paper), (ass:diff2 of the paper), and~(ass:SC of the paper), and let $h \in H$ satisfy clauses~\textup{(i)} and~\textup{(ii)} of Assumption (ass:nondeg of the paper). Assume further that the covering vector field $v_h$ defined in (equation eq:covering-field of the paper) belongs to $\operatorname{Dom}(\delta_U)$. Then:
\begin{enumerate}[label=\textup{(\roman*)}]
  \item The law $\mu_t$ of $X(t)$ is Fomin-differentiable along $h$ in the sense of [bogachev2010differentiable], equivalently of Definition (def:log-deriv of the paper);
  \item The logarithmic derivative $\beta_h$ exists and is unique in $L^2(\mu_t)$, with the Bismut representation
  \begin{equation}
    \beta_h(X(t)) = -\mathbb{E}\bigl[\delta_U(v_h) \mid X(t)\bigr] \qquad \mu_t\text{-a.e.};
  \end{equation}
  \item $\lVert \beta_h \rVert_{L^2(\mu_t)} \leq \lVert \delta_U(v_h) \rVert_{L^2(\Omega)} < \infty$.
\end{enumerate}

