body:
[Corollary 48 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\Phi_0$, $\Phi_1$ be continuous bounded functions $\mathbb{R}^d \rightarrow [0,\infty)$. Let $\Phi: \mathbb{R}^d \times \{0,1\} \rightarrow [0,\infty)$ be given by $\Phi((b,0)) = \Phi_0(b)$ and $\Phi((b,1)) = \Phi_1(b)$. Similarly, let $\mu_{\rm d}$, $\mu_{\rm a} \in \mathcal{M}_F(\mathbb{R}^d)$ and then let $\mu$ be the finite measure on $\mathbb{R}^d \times \{0, 1\}$ given by $\mu = \mu_{\rm d} \otimes \delta_0 + \mu_{\rm a} \otimes \delta_1$. Let $\gamma>0$ and let $\mathbb{E}_\mu$ be the expectation operator for an $\text{ooSBM}(\gamma, c, \Tilde{c})$, which we denote by $(\mathcal{Y}''_s)_{s \geq 0}$, on $\mathcal{M}_F(\mathbb{R}^d \times \{0,1\})$ with initial state $\mu$. Finally, let $(K^{\%}_s)_{s \geq 0}$ be the transition semigroup for $\text{ooBM}(c, \Tilde{c})$. Then we have
    \begin{equation*}
        \mathbb{E}_\mu(\langle \mathcal{Y}''_s, \Phi \rangle) = \langle \mu, K^{\%}_s \Phi \rangle.
    \end{equation*}
    \begin{proof}
        This result simply pulls together the different parts of the expectations given in Proposition \ref{proposition expectation oosbm}. Specifically, we have
        \begin{equation*}
            \mathbb{E}_\mu(\langle \mathcal{Y}''_s, \Phi \rangle) = \mathbb{E}_{(\mu_{\rm d}, \mu_{\rm a})} (\langle \mathcal{Y}^{(\rm d)}_s, \Phi_0 \rangle) + \mathbb{E}_{(\mu_{\rm d}, \mu_{\rm a})} (\langle \mathcal{Y}^{(\rm a)}_s, \Phi_1 \rangle).
        \end{equation*}
        The integrals in the equations correspond to the parts of the expectation, i.e. we have
        \begin{equation*}
            \langle \mu_{\rm d} \otimes \delta_0, K^{\%}_s \Phi \rangle = \int_{b \in \mathbb{R}^d} E^{\%}_{(b,0)}[\Phi_0(U_s)\mathbbm{1}_{I_s=0}] \mu_{\rm d}(db) + \int_{b \in \mathbb{R}^d} E^{\%}_{(b,0)}[\Phi_1(U_s)\mathbbm{1}_{I_s = 1}] \mu_{\rm d}(db)
        \end{equation*}
        and we also have
        \begin{equation*}
            \langle \mu_{\rm a} \otimes \delta_1, K^{\%}_s \Phi \rangle = \int_{b \in \mathbb{R}^d} E^{\%}_{(b,1)}[\Phi_0(U_s)\mathbbm{1}_{I_s=0}] \mu_{\rm a}(db) + \int_{b \in \mathbb{R}^d} E^{\%}_{(b,1)}[\Phi_1(U_s)\mathbbm{1}_{I_s=1}] \mu_{\rm a}(db).
        \end{equation*}
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem TCL of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $n,N\in\mathbb{N}$, and define
    \begin{equation}
		Z_{N}(n):=\frac{1}{\sqrt{N}}\left[\mathrm{Tr}(X_{N}^{n})-\mathbb{E}(\mathrm{Tr}(X_{N}^{n}))\right].
	\end{equation}
The family $(Z_{N}(n))_{n\in\mathbb{N}}$ converges to a Gaussian process as $N$ goes to infinity. (Proof in the paper; no proof environment follows the statement in the TeX.)

