[Lemma lem:5.17 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] Let $a<b$. Let $A$ be a closed set in $\mathbb R^3$ such that $\partial\mathcal B_a\not\subseteq A$ and $\partial\mathcal B_b\not\subseteq A $. Let $\mathcal U$ be the class of all bounded positive harmonic functions $u$ on $\mathcal B_b^\circ\setminus A$ such that  $u$ vanish continuously on the regular points of $ A\cap\mathcal B_b^\circ$ and can be extended continuously to $\partial\mathcal B_b\setminus A$. We have
    \begin{equation}
    \sup_{u,v\in\mathcal U,x_1,x_2\in\partial\mathcal B_a\setminus A}\dfrac{u(x_1)v(x_2)}{u(x_2)v(x_1)}
    =K(p_{a,b}^ A).    
    \end{equation}

[Lem repLin of arXiv:2509.26254, '$K$-Branching Random Walk with Noisy Selection: \\ \Large Large Population Limits and Phas'] For $g \in \mathcal{D}$, define $\omega(g):= \sup_{z \in \mathbb{R}}(g(z) + z)$. The following hold:
\begin{itemize}
\item[(i)] For all $x \in \mathbb{R}$, 
\[ r(g)(x) \leq \pi\left(1 -\gamma + \omega(g) - x\right),\]
with equality for all $x \geq U(g)$, that is, $r(g)$ is a line with slope $-1$ on $[U(g), U(r(g))]$.
\item[(ii)] For $\bm{x} \in \mathbb{R}^{K+1}$ non-increasing, let $L' := L(f_{\bm{x}})\vee x_{K-1}$ when $K\in \mathbb{N}$ and $L' = L(f_{\bm{x}})$ when $K = \infty$. Then $\omega(f_{\bm{x}}) = U(f_{\bm{x}}) = x_0$ and \begin{equation} 
r(f_{\bm{x}})(x) = \begin{cases}
\pi(1-\gamma - (x-x_0)) & x > x_0,\\
1-\gamma + f_{\bm{x}}(x) & x \in [L', x_0],\\
\pi\left(1 - \gamma + f_{\bm{x}}(L') - c_-(L' - x)\right) & x < L'.
\end{cases}
\end{equation}
\end{itemize}

