[Tm Ito of arXiv:2411.05441, 'Sticky diffusions on star graphs : characterization and It\^o formula'] Let $X(t) = (i(t), x(t))$ be the process generated by (equation generator2 of the paper) and (equation eq:domain of the paper) with $\eta > 0$, started at $X(0) = \mathsf{x} \in \Gamma$, and let $f \in C_{b}^{1,2}(\mathbb{R}_+ \times \Gamma)$. Then,
	\begin{equation}
	\begin{split}
	& f(t,X(t)) = f(0,\mathsf{x}) + \int_0^t \left ( \partial_s f(s,X(s)) +  Lf(s,X(s)) \right ) \mathbf 1_{\{ X(s) \neq \mathsf{v} \}}  ds \\
	& \, + \int_0^t \sigma(X(s)) \partial_x f(s,X(s)) \mathbf{1}_{\{X(s) \neq \mathsf{v} \}} d \widetilde W(s)
	 + \int_0^t \left ( \eta\, \partial_s f(s,\mathsf{v}) +  \sum_{i=1}^N \rho_i \partial_x f_i(s,0) \right ) d \ell_X(s),
	\end{split}
	\end{equation}
	where $\widetilde W$ is the Brownian motion obtained in Theorem (tm:SDE of the paper). In particular, if $Lf(t,\cdot) \in C(\Gamma)$ for all $t \geq 0$, we have
	\begin{equation}
	\begin{split}
	& f(t,X(t)) = f(0,\mathsf{x}) + \int_0^t \left ( \partial_s f(s,X(s)) +  Lf(s,X(s)) \right )  ds \\
	& \, + \int_0^t \sigma(X(s)) \partial_x f(s,X(s)) \mathbf{1}_{\{X(s) \neq \mathsf{v} \}} d \widetilde W(s) + \int_0^t \left (\sum_{i=1}^N \rho_i \partial_x f_i(s,0) - \eta\, L f(s,\mathsf{v}) \right ) d \ell_X(s).
	\end{split}
	\end{equation}

