[Lemma 52 (Determinant and conditional profile decoder) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] The following statements hold.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.8em]
\item If \(0<p<1\) and \(Q\succeq0\) is trace class, then
\begin{equation}
 \sup_{x>0}x^{-p}\Psi_Q(x)
 \asymp_p\|Q\|_{\mathcal S_{p,\infty}}^p,
 \qquad
 Q\in\mathcal S^0_{p,\infty}
 \Longleftrightarrow \Psi_Q(x)=o(x^p).

\end{equation}
Moreover \(Q\in\mathcal S_1\) implies \(\Psi_Q(x)=o(x)\).

\item Let \(0<p<2\), let \((A_\theta)\) be a measurable family of skew
Hilbert--Schmidt operators, and put
\[
 \Phi(z):=\sup_\theta\mathfrak P_{A_\theta}(z),
 \qquad
 W_p:=\sup_{\theta,j}j^{1/p}a_j(A_\theta).
\]
Let \(\mathcal H\) be a sigma-field.  Suppose that, for an
\(\mathcal H\)-measurable \(B\geq0\), some \(q>0\), and deterministic
\(C_0,C_1<\infty\),
\begin{equation}
 \mathbb E[e^{q\Phi(z)}\mid\mathcal H]
 \leq C_0\exp(C_1(zB)^p),\qquad z\geq0.

\end{equation}
Then, for every \(0<r<2q\),
\begin{equation}
 \left(\mathbb E[W_p^r\mid\mathcal H]\right)^{1/r}
 \leq C_{p,q,r,C_0,C_1}B.

\end{equation}

\item Under the notation of part~\textup{(ii)}, suppose instead that
\begin{equation}
 \mathbb E[e^{\Phi(z)}\mid\mathcal H]
 \leq C_0e^{b(z)},
 \qquad b(z)=o(z^p)\quad\text{almost surely},

\end{equation}
where \(b(z)\) is \(\mathcal H\)-measurable.  Then
\begin{equation}
 \sup_\theta n^{1/p}s_n(A_\theta)\longrightarrow0
 \quad\text{almost surely}.

\end{equation}
\end{enumerate}

[Lemma lem-A7 of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] There exists   $\mathbb{P}$-full set  $\Omega^{(viii)} \subset \Omega^{(vii)}$ and  an infinite set $\Upsilon_{5} \subset \Upsilon_{4}$
 such that for all $T\geq 0$ and every $\omega \in \Omega^{(viii)}$,
\begin{equation}
\begin{aligned}
&
\lim_{\ensuremath{\varepsilon}\in \Upsilon_{5} }\sup_{t\in[0,T]}\Big| \int_0^t\Xint\times_{B}\int_{\mathbb R^d}u_0(y)\big[  \theta(\phi_{s}^{\ensuremath{\varepsilon}}(y)+z)-\theta(\phi_{s}^{\ensuremath{\varepsilon}}(y)) -\sum_{i=1}^d z_iD_i\theta(\phi_{s}^{\ensuremath{\varepsilon}}(y))\big] J_s^{\ensuremath{\varepsilon}}(y)dy\, \nu(dz)\, ds
\\
& \hspace{1.9truecm} - \int_0^t\Xint\times_{B}\int_{\mathbb R^d}u_0(y)\big[  \theta(\phi_{s}(y)+z)-\theta(\phi_{s}(y)) -\sum_{i=1}^d z_iD_i\theta(\phi_{s}(y))\big] J_s(y)dy\, \nu(dz)\, ds\Big|=0.
\end{aligned}
\end{equation}

[Definition 3 of arXiv:2609.00680, 'Sharp embeddings between quasi-Banach Besov spaces and shallow ReLU Variation spaces'] Let $X$ be a Banach space and let $\mathcal D\subset X$ be compact. The
closed absolutely convex hull of $\mathcal D$ is
\[
\mathcal K(\mathcal D):=
\overline{\left\{\sum_{i=1}^N a_i v_i:
v_i\in\mathcal D,\ \sum_{i=1}^N|a_i|\leq1\right\}}^{\,X}.
\]
The variation space if defined as
\begin{align*}
\mathcal{L}_1(\mathcal D)
&:=\{f\in X:\|f\|_{\mathcal{L}_1(\mathcal D)}<\infty\}
\end{align*}
with the corresponding norm
\begin{align*}
    \|f\|_{\mathcal{L}_1(\mathcal D)}
&:=\inf\{t>0:f\in t\mathcal K(\mathcal D)\}.
\end{align*}

[Definition def:tau Psi of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] We define the one form $\tau$ on $M$ given for all $x\in M$ by 
  \begin{equation}
    \tau(x):=\frac{1}{\sqrt{\mathrm{K}_0(x)}}\left(f_0(x)\mu(x)-D_xf_0\right).
  \end{equation}
  Moreover, we define $\Psi\in C^\infty(M)$ given for all $x\in M$ by: 
  \begin{equation}
    \Psi(x):=\left(\frac{\mathrm{K}(x)}{\mathrm{K}_0(x)}\right)^{\frac{m}{2}}\sqrt{1+ g^x(\tau(x))}.
  \end{equation}

[Thm of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] Under the same assumption of Theorem (windingangletheorem of the paper). If $\theta$ is piecewise $C^1$ on $[0,T]$ and $\theta_T-\theta_0\in(4k\pi+\pi,4k\pi+3\pi)$ for some integer $k$, then $\gamma$ has finite radius of convergence for its logarithmic signature.
\begin{proof}
It is implied by Corollary (ODEequivalence of the paper), Remark (piecewiseC2path of the paper) and the calculation in (equation signcalculation of the paper). Actually, we have 
\begin{equation*}
\begin{aligned}
&\int_l^{l+\pi}\rho_T^\lambda\cos(\varphi_T^\lambda-\zeta)d\zeta\\
\to&~e^{\lambda T}\prod_{k=1}^{n-1}\cos\left(\frac{\theta_{T_k+}-\theta_{T_k-}}{2}\right)\int_l^{l+\pi}\cos\left(\zeta-\frac{\theta_0}{2}\right)\cos\left(\zeta-\frac{\theta_T}{2}\right)d\zeta\\
=&\frac{e^{\lambda T}\pi}{2}\prod_{k=1}^{n-1}\cos\left(\frac{\theta_{T_k+}-\theta_{T_k-}}{2}\right)\cos\left(\frac{\theta_T-\theta_0}{2}\right).
\end{aligned}
\end{equation*}
W.L.O.G. we can assume the all the intersection angles $|\theta_{T_k+}-\theta_{T_k-}|<\pi$ for any $k$. Actually, we have to assume this to make the ODE system consistent on each piece $\gamma|_{[T_k,T_{k+1}]}$, otherwise the condition has to change. Because $\prod_{k=1}^{n-1}\cos\left(\frac{\theta_{T_k+}-\theta_{T_k-}}{2}\right)>0$, it follows that
$$
\int_l^{l+\pi}\rho_T^\lambda\cos(\varphi_T^\lambda-\zeta)d\zeta\to-\infty~~~\Longleftrightarrow~~~\cos\left(\frac{\theta_T-\theta_0}{2}\right)<0,
$$
which finishes the proof.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem L1 of arXiv:2609.01350, 'New classes of trace-form permutation polynomials and their compositional inverses'] Let $a, b \in \mathbb F_{2^n}$ , $b \neq 0$ and $f(x) = x^3 + ax + b, g(y) = y^2 + by + a^3$. Let $y_1$, $y_2$ be two roots of $g(y)$. The factorizations of $f(x)$ are characterized as follows:
\begin{enumerate}
\item $f = (1, 1, 1)$ if and only if ${\rm Tr}_2^{2^n} \left( \frac{a^3}{b^2} \right) = {\rm Tr}_{2}^{2^n}(1)$, and $y_1, y_2$ are cubes in $\mathbb F_{2^n}$ (resp. $\mathbb F_{2^{2n}}$) if $n$ is even (resp. odd);
\item $f = (1, 2)$ if and only if ${\rm Tr}_2^{2^n} \left( \frac{a^3}{b^2} \right) \neq {\rm Tr}_2^{2^n}(1)$;
\item $f = (3)$ if and only if ${\rm Tr}_2^{2^n} \left( \frac{a^3}{b^2} \right) = {\rm Tr}_2^{2^n}(1)$, and $y_1, y_2$ are not cubes in $\mathbb F_{2^n}$ (resp. $\mathbb F_{2^{2n}}$) if $n$ is even (resp. odd).
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

