[Definition def:sol_gen_SDE of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $s\in [0,T)$. A (general) solution to SDE$(b,\sigma;s)$ is a 
triple $( (\mathcal{F}_t)_{t},W, X)$, where: 
\begin{itemize}
\item[(i)] $(\mathcal{F}_t)_{t\in [s,T)}$ is a filtration on a probability space $(\Omega , \mathcal{F}, \mathbb{P})$, satisfying the usual assumptions of completeness and continuity from the right;
\item[(ii)] $W=(W_t)_{t\in [s,T)}$ is a $q$-dimensional (uncorrelated) Brownian motion (starting at $s$) with respect to $(\mathcal{F}_t)_{t\in [s,T)}$;
\item[(iii)] $X=(X_t)_{t\in [s,T)}$ is an $\mathbb{R}^d$-valued process, adapted to  $(\mathcal{F}_t)_{t\in [s,T)}$, such that: 
\begin{itemize}

\item the processes $(b(t,X_t))_{t\in [s,T)}$ and  $(\sigma(t,X_t))_{t\in [s,T)}$ are progressively measurable and such that 
\begin{equation}
\int_s^t |b(r,X_r)| dr + \int_s^t \big|\sigma\sigma^\top(r,X_r)\big| dr  <\infty, \qquad \mathbb{P}\text{-almost surely.}
\end{equation}

\item 
the following representation holds $\mathbb{P}$-almost surely:
\begin{equation}
X_t = X_s + \int_s^t b(r,X_r) dr + \int_s^t \sigma(r,X_r) dW_r ,\qquad t\in [s,T).
\end{equation}
\end{itemize} 
\end{itemize}

[Satz thm:mgf of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d,k\in\mathds{N}$, $s,\alpha,\beta,\gamma,\theta\in\mathds{R}$, $p,q\in (0,\infty]$, and $r\in (0,\infty)$.
Assume that $f$ follows a Besov prior with parameters $(\alpha,\beta,\gamma,\theta,k)$ and template random variable $X$ with
\begin{equation*}
\begin{cases}\:\exists\: C>0:\,\mathds{E}[\exp(C\left\lvertX\right\rvert^{\max\left\{r,p\right\}})]<\infty&\text{if }p\in (0,\infty),\\
\:\exists\: R>0:\,\left\lvertX\right\rvert\stackrel{a.s.}{\leq}R&\text{if }p=\infty.\end{cases}
\end{equation*}
If Properties A and B are satisfied, then there exists $c>0$ with $\mathds{E}[\exp(c\left\lVertf\right\rVert_{B^s_{p,q}}^r)]<\infty$.

