[Proposition prop:asymp_escape_crossing_probabilities of arXiv:2509.23496, 'Crossing probabilities in geometric inhomogeneous random graphs'] Let $2<\delta\leq\infty$ and $0\leq\gamma<\frac12$, excluding the case $(\gamma,\delta)=(0,\infty)$, and adopt the convention $\frac{1}{\gamma}=\infty$ when $\gamma=0$. Then, for arbitrary $\lambda>0$,
    the one-edge escape and crossing probabilities satisfy 
    \begin{align} 
        \pi_{(u), R} \asymp 
        \begin{cases}
            u^{-1}g(R) \wedge 1 & \mbox{ if } \delta\ge\frac1\gamma, \\
            u^{-\gamma\delta}g(R) \wedge 1 & \mbox{ if } \delta<\frac1\gamma,
        \end{cases}
    \end{align}
    and
    \begin{align} 
        \pi_{r, R} \asymp 
        \begin{cases}
            r^d (\log R) g(R)  & \mbox{ if } \delta\ge\frac1\gamma, \\
            r^d g(R)  & \mbox{ if } \delta<\frac1\gamma,
        \end{cases}
    \end{align}
    and the two-edge escape and crossing probabilities satisfy



    \begin{align} 
        \pi_{(u), R}^{(2)} \asymp 
        \begin{cases}
        \pi_{(u),R} + u^{-\gamma}h(R)\wedge 1 & \mbox{ if } \delta\ge \frac1\gamma-1,\\ \pi_{(u),R} & \mbox{ if } 
        \delta< \frac1\gamma-1,
        \end{cases}
    \end{align}
    and
 \begin{align} 
        \pi^{(2)}_{r, R} \asymp 
        \begin{cases}
            \pi_{r,R} + 
            r^{d\gamma} h(R)   & \mbox{ if } \delta>\frac1\gamma,\vspace{0.5mm} \\
             \pi_{r,R} + r^{d\gamma} (\log r)^\gamma h(R)   & \mbox{ if } \delta=\frac1\gamma,\vspace{0.5mm} \\
            \pi_{r,R} + r^{\frac{d}{\delta}} h(R)  & \mbox{ if } \frac{1}{\gamma}-1\leq\delta<\frac1\gamma, \vspace{0.5mm}\\
             \pi_{r,R}    & \mbox{ if } \delta<{\frac1\gamma-1},
        \end{cases}
    \end{align}    
    where the {asymptotic order of} $g(R):=\pi_{(1),R}$ and $h(R):=\pi^{(2)}_{(1),R}$ are stated in Table~(tab:gandh of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma E[multi_edges]_asymp of arXiv:2604.05921, 'Simplicity of random hypergraphs'] If $\forall e \in E: \delta_e = \delta\in O(1)$ and 
\begin{enumerate}
    \item $\mathds{E}[d_U^{2\delta}] \in o(n)$
    \item $\exists c > 0: \lim_{n \rightarrow \infty} \mathds{P}(d_U \geq 2 \delta) \geq c$ 
\end{enumerate}
then
\begin{align*}
    \mathds{E}[M_n] = \frac{(\delta-1)!}{2\delta}  (n \mathds{E}[d_U])^2 \Bigg(\frac{\mathds{E}[d_U^2] - \mathds{E}[d_U]}{n\mathds{E}[d_U]^2}\Bigg)^{\delta} (1+o(1)).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

