[Corollary 13 of arXiv:2605.31344, 'Subcritical sharpness for real-valued spin models'] Let $\Lambda \subset V$ finite, $\beta \geq 0$, and $\sfb \in (\mathbb{R}^{+})^{\partial^{\mathrm{ext}} \Lambda}$. For every $x,y \in \Lambda,$ we have
    \begin{align*}
        \nu_{\Lambda, \beta}^{\mathsf{b}} [\varphi_x] = \Psi_{\Lambda, \beta}^{(w, \mathsf{b})}[\sfa_x \mathbbm{1}_{x \longleftrightarrow \partial^{\mathrm{ext}}\Lambda}]
    \end{align*}
    and
    \begin{align*}
    \nu_{\Lambda, \beta}^{\mathsf{b}} [\varphi_x \varphi_y] = \Psi_{\Lambda, \beta}^{(w, \mathsf{b})}[\sfa_x \sfa_y \mathbbm{1}_{x \longleftrightarrow y}].
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo 22 of arXiv:2609.02261, 'Quantization and process'] Let  $L$ be a homogeneous differential operator of order 2 with constant coefficients. Then, there exists $C>0$ satisfying if 
 $0 < \mu < \lambda $ and  $\lambda - \mu >C$, for all
    $h>0$ and  $F\in D_{\lambda h }( \R^{2n})$, 

  \be \frac {h^m}  {m!} \Vert L^m F \Vert_{ D_{\mu  h }( \R^{2n})} 
  \leq  \frac {C^{m+1}}  {(\lambda - \mu) ^m}
  \Vert  F \Vert_{ D_{\lambda  h }( \R^{2n})} .\ee (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem theorem4.3 of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] ([erdHos2011universality], Theorem 1.11.) Let $H\in\operatorname{Sym}_n(\zeta)$ where $\zeta\in\Gamma_B$ for some $B>0$. Let $\kappa>0$ and consider $E\in[-2+\kappa,2-\kappa]$. Denote by $\mathcal{N}_{\eta^*}(E)=\mathcal{N}_{I^*}$ the number of eigenvalues of $n^{-\frac{1}{2}}H$ in $I^*:=[E-\eta^*/2,E+\eta^*/2]$. Then we can find a universal constant $c_1>0$ and two constants $C$, $c>0$ depending only on $\kappa$ such that for any $\delta\leq c_1\kappa$ we can find a constant $K_\delta$ depending only on $\delta$ such that 
\begin{equation}
    \mathbb{P}\left\{\left|\frac{\mathcal{N}_{\eta^*}(E)}{n\eta^*}-\rho_{sc}(E)\right|\geq\delta\right\}\leq Ce^{-c\delta^2\sqrt{n\eta^*}},
\end{equation}
for all $\eta^*$ satisfying $K_\delta/n\leq\eta^*\leq 1$ and all $n\geq 2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition J_def_eq of arXiv:2606.17425, 'Order statistics for edge eigenvectors of Wigner matrices'] Let $\epsilon > 0$, and $J = J(N, \epsilon)$ be a sequence of index sets,
\begin{equation}
    J \subset \{(\alpha, i, j) : 1 \leq i, j \leq N,  1 \le \alpha \le \floor{N^{\epsilon/10}} \},

\end{equation} corresponding to products of entries of the edge eigenvectors. We assume $\#_{J} \to \infty$ as $N \to \infty$. Further, let $E_J = E_J(N)$ be the set, 
\begin{equation}
  E_J := \{N \inner{u_{\alpha}, q_i} \inner{u_{\alpha}, q_j} : (\alpha, i,j) \in J\}.
\end{equation}
 Let $(N \inner{u_{\alpha}, q_i} \inner{u_{\alpha}, q_j})_{(k)}$ denote the $k$-th largest entry of $E_J$, \emph{i.e., } $(N \inner{u_{\alpha}, q_i} \inner{u_{\alpha}, q_j})_{(1)}$ denotes the largest entry of $E_J$, and $(N \inner{u_{\alpha}, q_i} \inner{u_{\alpha}, q_j})_{(\#_J)}$ the smallest.

[Lemma lemma38 of arXiv:2510.10898, 'A central limit theorem for unbalanced step-reinforced random walks'] Define
$
Z_{l}(n)=\sum_{k=1}^n k^l \nu_k(n).
$
For any $0<p<1$ and $l\ge 0$, we have
\begin{eqnarray}
\mathbb{E}(Z_{l}(n))  \asymp b_{l}(n),   
\end{eqnarray}
where
\begin{eqnarray}
b_{l}(n):=\left\{
\begin{array}{ll}
n^{lp}, & lp>1;\\
 n\log n,  & lp=1;\\
 n, & lp<1.
\end{array}
\right.   
\end{eqnarray}
Furthermore,  if $lp<1$, then
\begin{eqnarray}
\limsup_{m\rightarrow \infty}\limsup_{n\rightarrow \infty} \Big(\frac{1}{n}\sum_{k=m}^n k^l \mathbb{E}(\nu_k(n))\Big) =0.  
\end{eqnarray}

[Prop ;pp of arXiv:2604.12462, 'Stochastic analysis of Beckner's and related functional inequalities'] For every $4/3<p<2$, it holds that 
\begin{align}
 \int _{0}^{t}ds\,\ex \!\left[ 
 M_{s}^{-p}|\dv _{s}|^{2}\int _{0}^{s}du\,M_{u}^{2p-4}|\dv _{u}|^{2}
 \right] 
 =\ex \!\left[ 
 \fp \!\left( 
 \int _{0}^{t}ds\,M_{s}^{2p-4}|\dv _{s}|^{2},M_{t}
 \right) 
 \right] 
\end{align}
for all $0\le t\le 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:gammas of arXiv:2512.12902, 'Non-equilibrium fluctuations for the \\stirring process with births and deaths'] Let  $i,j\subset \{1,\dots,n\}$, $\zeta>0$,  $\epsilon<1$ and $\underline x=(x_1,\dots,x_n)$. Under {\bf Assumption 1} given in (equation Ass1 of the paper), for any {$0\leq \lambda\leq t$}, the following estimates hold:

\begin{equation}
\mathbf{E}_{\epsilon,\underline x} [\gamma^{{\epsilon}}_{0}(i,j,\lambda, t-\lambda)]\lesssim {\phi_0(\lambda)}:=\frac{1}{\lambda^{1/2}}+\frac{1}{\lambda^{1/2+\zeta}},
\end{equation} 
\begin{equation}
\mathbf{E}_{\epsilon,\underline x} [\gamma_{2}^{{\epsilon}}(i,j,\lambda, t-\lambda)]\lesssim \,{\phi^\epsilon_2(\lambda):=} \epsilon\left( \frac{1}{\lambda^{1/2}}+\frac{1}{\lambda^{3/4}}\right).
\end{equation}

 Moreover, for $n\geq 3$,
\begin{equation}
\mathbf{E}_{\epsilon,\underline x} [\gamma^{{\epsilon},n-1}_1(i,j,\lambda, t-\lambda)]\lesssim {\phi^{\epsilon,n-1}_1(\lambda)}:=\epsilon
\phi_0(\lambda) \mathbf 1_{n= 3}+\frac{1}{[\epsilon^{-2}\lambda]+1}\epsilon^{-4\zeta}\mathbf 1_{n\geq 4},
\end{equation}
where $\gamma^\epsilon_0$, $\gamma_{1}^{\epsilon,n-1}$ and $\gamma^\epsilon_{2}$ are defined in (equation 19.1 of the paper)--(equation 19.2 of the paper).

