[Corollary 8 of arXiv:2608.27307, '2608.27307'] Under Assumptions~\ref{ass:basic} and~\ref{ass:rand_ent}, suppose that $E_+$ is a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. Then, for every $x\in\R$,
        \begin{align}
                \lim_{N\to\infty} \bb P( \gamma_+N^{2/3}(\la_1-E_+)\leq x ) =F_1(x). \nonumber
        \end{align}
        Here $F_1$ denotes the distribution function of the Tracy--Widom law of type~1. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 22 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, let $E_*$ be a regular right edge in the sense of Definition~\ref{def:reg_r_edge}. Then there exists a constant $\eps_*>0$ such that, for every $z=E+\ii\eta\in\C^+$ with $|E-E_*|\leq\eps_*$ and $0<\eta\leq\eps_*$,
        \begin{align}
                \|(\calI-\calJ(z))^{-1}\|+\|\calB(z)^{-1}\|\lesssim(|E-E_*|+\eta)^{-1/2}. 
        \end{align}
        Moreover, with $\kappa:=|E-E_*|$,
        \begin{align}
                \Im m(E+\ii\eta)\sim \begin{cases} (\kappa+\eta)^{1/2},               & E\leq E_*, \\[1mm]
              \dfrac{\eta}{(\kappa+\eta)^{1/2}}, & E\geq E_*,\end{cases} 
        \end{align}
        and consequently
        \begin{align}
                \Im m(z)+\frac{\eta}{\Im m(z)}              & \sim (|E-E_*|+\eta)^{1/2}, \nonumber                                       \\
                \|(\calI-\calJ(z))^{-1}\|+\|\calB(z)^{-1}\| & \lesssim \frac{1}{\Im m(z)+\eta/\Im m(z)}. 
        \end{align}
        The same $\eps_*$ may be chosen so that, uniformly for $|E-E_*|\leq\eps_*$ and $\eps_*\leq\eta\leq\eta_0$,
        \begin{align}
                \|\Pi(z)\|+\|(\calI-\calJ(z))^{-1}\|+\|\calB(z)^{-1}\|\lesssim1. 
        \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma6.111 of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Let $\zeta\in\Gamma_B$ for some $B>0$ and have a finite Log-Sobolev constant, and let $A_n\sim\operatorname{Sym}_n(\zeta)$.  Fix any $\kappa>0$, $\Delta>0,$ and any two $\lambda_1,\lambda_2\in[(-(2-\kappa)\sqrt{n},(2-\kappa)\sqrt{n}]$ with $|\lambda_1-\lambda_2|\geq \Delta\sqrt{n}$. Then for any $\delta_1,\delta_2\geq e^{-cn}$, any unit vector $u\in\mathbb{S}^{n-1}$, and any $p>0$, we have the following estimate: 
\begin{equation}\begin{aligned}
&\mathbb{E}_{A_n}\sup_{r_1,r_2\in\mathbb{R}}\mathbb{P}_X\left(\begin{cases}
    \frac{|\langle (A_n-\lambda_i I_n)^{-1}X,X\rangle-r_i|}{\|(A_n-\lambda_i I_n)^{-1}\|_*}\leq\delta_i,\text{  for each }i=1,2;\\
    \langle X,u\rangle\geq s,\\\frac{\mu_1(\lambda_1)\mu_1(\lambda_2)}{n}\leq(\delta_1\delta_2)^{-p}\end{cases}
    \right)\\&\lesssim e^{-s}\delta_1\delta_2+e^{-s}\delta_1\delta_2\mathbb{E}\left[\left(\frac{\mu_1(\lambda_1)\mu_1(\lambda_2)}{n}\right)^{9/10}
    \mathbf{1}\{ \frac{\mu_1(\lambda_1)\mu_1(\lambda_2)}{n}\leq (\delta_1\delta_2)^{-p}\}\right]^{80/81}\\&+e^{-\Omega(n)},\end{aligned} 
\end{equation} where the constant $c>0$ appearing in the condition $\delta_1,\delta_2\geq e^{-cn}$ only depends on $B,\kappa,\Delta$ and the Log-Sobolev constant of $\zeta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2608.26816, '\textbf{On the existence of maximal foliations in general relativity}'] Let $(M_{0},{g},{h})$ be an asymptotically flat initial data set (\ref{AC})  which satisfies the vacuum constraint equations (\ref{ECE}). For any $1<p_0<\frac{3}{2}$,     there exist  constants     $\epsilon_{0}>0$, $C>0$,  depending only on $p_0$ and $\alpha_0, \alpha_1$ in (\ref{II}) and (\ref{III})  satisfying the following properties.  If  
 \begin{equation}
\|{H}\|_{L^{p_0}(M_{0})} (E_1E_2)^{\frac{3-p_0}{2p_0}}<\epsilon_0,
   \end{equation}        
\begin{equation}
  \begin{split}
 \|{H}\|_{L^{p_0}(M_{0})}  E_1^{\frac{6}{p_0}-2}<\epsilon_0,\end{split}
      \end{equation}
       \begin{equation}
   (||\nabla H||^2_{L^2(M_0)}+ ||H||_{L^{\infty}(M_0)})( ||\nabla^2 H||^2_{L^2(M_0)}+E_1E_2||H||_{L^{\infty}(M_0)})<\epsilon^4_0 E_1^8,
      \end{equation}
           then  there exist a vacuum spacetime $(\bar{M},\bar{g})$ in the maximal development $\mathcal{M}$ of $M_0$, and  a time function ${\tau}: \bar{M}\rightarrow (-\tau_0,\tau_0)$,   the level sets $\{\Sigma_\tau: \tau\in (-\tau_0,\tau_0)\}$ form  a foliation of maximal and asymptotic flat surfaces.  Moreover, the maximal foliation covers $M_0$, i.e.,  $M_0\subset \bar{M}$, and  we have 
  \begin{equation} 
\begin{split}
    &  \int_{\Sigma_{\tau}}|\bar{R}m|^2+|\nabla h|^2+|h|^4 \leq CE^2_1\\
& \int_{\Sigma_{\tau}}|\nabla \bar{R}m|^2+|\nabla^2 h|^2+|h|^6+|\bar{R}m|^3+|\nabla h|^3 \leq CE^2_2.
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 25 of arXiv:2609.03556, 'An Effective SPDE Model for a Schr\"odinger Equation with a Fluctuating Magnetic Potential'] \label[lemma]{lem:stochastic_conv}
  Assume \cref{hp:noise}. For each $\tau\in (0,1)$ and $T\geq 0$, the process
  $(A^{\tau}_t)_{t\in [0,T]}$ has paths in
  $C([0,T];H^{5+\frac{d+\theta}{2}})$ $\mathbb{P}-a.s.$
  Moreover, it is stationary and
\begin{align}
      A^{\tau}_t\sim \mu \quad \text{for each }t\in [0,T],\ \tau\in (0,1),
  \end{align}
  where $\mu$ is the Gaussian measure with covariance kernel given by $Q(x,y).$
  In particular, there exists $\lambda>0$ such that, for every
  $t\in[0,T]$ and $\tau\in(0,1)$,
  \begin{align*}
\expt{e^{\lambda\|A^{\tau}_t\|_{H^{5+\frac{d+\theta}{2}}}^2}}<+\infty.
  \end{align*}
Analogous statements hold replacing $H^{5+\frac{d+\theta}{2}}(\R^d)$ with $W^{5,\infty}(\R^d)$.

