[Theorem 18 (Doob's optional stopping version III) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] Let $\{f_j\}_{j \geq 0}$ be a given non-negative,  real-valued supermartingale on $\mathcal{S}$ we also set $f_{T+1} \equiv \liminf_{n \rightarrow T+1} f_n$. Consider two stopping times satisfying
$\rho\le \tau$ a.e. Under the assumption that both,  $(L)-a.e$ and property $(P)$ (see Definition \ref{def:Positivity}), then:
\begin{enumerate}
\item 
\begin{equation} 
\overline{\sigma}_{\rho}(f_{\tau}) \leq f_{\rho}~~\mbox{a.e. on}~~\mathcal{S},
\end{equation}
\item 
\begin{equation} 
\overline{\sigma}_{\rho}({\bf 1}_{\{\tau < T+1\}}~f_{\tau}) \leq {\bf 1}_{\{\rho < T+1\}} f_{\rho}~\mbox{~a.e. on}~~\mathcal{S}.
\end{equation}
\end{enumerate}

[Lemma Special case of Lemma~2.3, the least-action principle of arXiv:2411.02541, 'The hockey-stick conjecture for\\ activated random walk'] \thlabel{lem:lap}
  Let $u$ be the true odometer stabilizing finite $V\subseteq\mathbb{Z}$ with given instructions and initial configuration
  with no sleeping particles.
  Let $u'$ be an odometer on $\mathbb{Z}$ that is stable on $V$ for the same instructions and 
  initial configuration.
  Then
  \begin{align*}
    u(v)\leq u'(v)
  \end{align*}
  for all $v\in V$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 34 of arXiv:2601.16377, '2601.16377'] Suppose that Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic} and \ref{Assumptions_offcrit}
 hold. If $[\mathfrak{a},\mathfrak{b}]$ is included in a void of the equilibrium measure, then for any $\eps>0$ there exists a real $C > 0$ independent of $\N$ such that the probability to have at least one particle $\ell_i$ inside $[\N(\mathfrak{a}+\eps),
 \N(\mathfrak{b}-\eps)]$ is at most $C^{-1}e^{-C\N}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:noninvariant of arXiv:2411.02030, 'Finite ergodic components for upper probabilities'] Let $(\Omega,\mathcal{F},P)$ be a probability space and $T:\Omega\to \Omega$ be a measurable invertible transformation. If the limit (equation eq:20.19 of the paper) exits, then the following statements are equivalent:
	\begin{enumerate}
		\item [(i)] $\#(P(\mathcal{I}))<\infty$;
		\medskip
		\item [(ii)] $(\Omega,\mathcal{F},P,T)$ satisfies the finite irreducible invariant set partition assumption; 
		\medskip
		\item [(iii)]there exist $Q_1,\ldots,Q_n\in\mathcal{M}^e(T)$ and  a finite measurable partition $\alpha=\{A_1,\ldots,A_n\}$ with $P(A_i)>0$, $i=1,2,\ldots,n$, such that for any $f\in B(\Omega,\mathcal{F})$, 
		\begin{equation}
			\lim_{N\to\infty}\frac{1}{N}\sum_{i=0}^{N-1}f\circ T^i=\sum_{j=1}^{n}\left(\int fdQ_j\right)\cdot1_{A_j},  ~~P\text{-a.s.}
		\end{equation}
		\item [(iv)]there exist  $Q_1,\ldots,Q_n\in\mathcal{ M}^e(T)$  and  a finite  measurable partition $\alpha=\{A_1,\ldots,A_n\}
		$ with $P(A_i)>0$, $i=1,2,\ldots,n$ such that 
		\begin{equation}
			\lim_{N\to\infty}\frac{1}{N}\sum_{i=0}^{N-1}P(B\cap T^{-i}C)=\sum_{j=1}^nQ_j(C)P(A_j\cap B)\text{ for any }B,C\in\mathcal{F}.
		\end{equation}
	\end{enumerate}

