[Theorem 6 (L\'evy space-time white noise) of arXiv:2506.12834, 'Space-time fractional stochastic partial differential equations driven by L\'evy white noi'] Let the parameters $(\alpha,\beta,\gamma,d)$ satisfy the inequality
\begin{equation}
  2\alpha+\min\left\{\frac{\alpha}{\beta}(2\gamma-1),-2 \right\}>d.
\end{equation}
Assume that there exist positive functions $g_1,g_2,g_3\in L^1(\R^d)$ such that the following growth conditions:
\begin{equation*}
  |f(t,x,z)|^2 +\sum_{j=1}^{d} |q_j(t,x,z)|^2 \le g_1(x)+ C|z|^2,
\end{equation*}
\begin{equation}
  |\sigma(t,x,z)|^2+\int_{\E}|h(t,x,z;\xi)|^2\mu(\ud\xi)  \le g_2(x)+ C|z|^2,
\end{equation}
and Lipschitz conditions
\begin{align}
   &|f(t,x,z_1)-f(t,x,z_2)|^2+\sum_{j=1}^{d} |q_j(t,x,z_1)-q_j(t,x,z_2)|^2 \le \left[g_3(x)+C(|z_1|^2+|z_2|^2)\right]|z_1-z_2|^2,
\end{align}
\begin{equation*}
  |\sigma(t,x,z_1)-\sigma(t,x,z_2)|^2+\int_{\E}|h(t,x,z_1;\xi)-h(t,x,z_2;\xi)|^2\mu(\ud\xi)  \le C|z_1-z_2|^2
\end{equation*}
hold for all $(t,x)\in[0,\infty)\times\R^d$ and $z_1,z_2,z_3\in\R$. Then for every $\cF_0$-measurable $u_0,u_1:\R^d\times\Omega\to\R$ with
\begin{equation*}
\begin{cases}
 \displaystyle \E\left[\int_{\R^d}|u_0(x,\cdot)|^2\ud x\right]<\infty, & \mbox{if } \beta\in(0,1], \vspace{0.2cm}\\
  \displaystyle \E\left[\int_{\R^d}|u_0(x,\cdot)|^2\ud x\right]+ \E\left[\int_{\R^d}|u_1(x,\cdot)|^2\ud x\right]<\infty , & \mbox{if } \beta\in(0,2).
\end{cases}
\end{equation*}
there exist a unique local solution to \eqref{e:de-solution} with the following property
\begin{equation*}
  \E \left[\Vert u(t\wedge\tau,\cdot)\Vert_2^2\right]<\infty,
\end{equation*}
for all $t\in[0,T]$.  Furthermore, there exists a predictable modification for the solution $u(t)$ of \eqref{e:de-solution}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm:hole_pr of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] \phantom{a}
 For every $t>0$ in the limit $\varepsilon\to 0^{+}$
  \begin{align}
 \log P_0(t;e^{-\varepsilon})
\!=\!
-\frac{1}{\varepsilon} \left[ \frac{ w^2}{2}+w +\frac{\pi^2}{3} \right]  -\frac{1}{2} \log (\varepsilon t) + t  -\frac{t}{w}  +O(\varepsilon), \quad w=W_{-1}(-\varepsilon t)
\end{align}
where $W_{-1}$ is the lower branch of the Lambert-$W$ function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 9 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $N$ be a fixed integer and let $x=(x_1,\dots,x_N)$ be the ordered coordinates of half-space TASEP particles. Then the half-line open TASEP has transition probability from an empty state to $x$ given by the following: when $N$ is even
	\begin{equation}

		\mathbb{P}_t(\emptyset\to x) = (-1)^{\binom{N}{2}} \mathrm{e}^{-\alpha t} \Pf \left[\mathsf{Q}\right],
	\end{equation}
	and when $N$ is odd the underlying matrix is augmented with an addition row and column
	\begin{equation}
		\mathbb{P}_t(\emptyset\to x) = (-1)^{\binom{N}{2}} \mathrm{e}^{-\alpha t} \pf\left[\begin{array}{cc}
			\mathsf{Q} & \mathsf{p} \\[5pt]
			-\mathsf{p}^T & 0
		\end{array}\right].
	\end{equation}
    Here, $\mathsf{Q}$ is a skew-symmetric $N\times N$-dimensional matrix and $\mathsf{p}$ is a column vector of length $N$ whose entries are given by
    \begin{align*}
        [\mathsf{Q}]_{i,j} := & Q_{i,j}(x_{N-i+1},x_{N-j+1}), \\ 
        [\mathsf{p}]_i := & p_{i}(x_{N-i+1}),
    \end{align*}
    for all $1\leq i,j\leq N$. We define the integral kernels
	\begin{equation}

		Q_{i,j}(x,y) = \alpha^2 \oint_\contour \frac{\dd u}{2\pi\ii} \oint_\contour \frac{\dd w}{2\pi\ii} \frac{u-w}{1-u-w} \frac{w^{i-x}\mathrm{e}^{t(w-1)}}{(w-\alpha)(w-1)^i} \frac{u^{j-y}\mathrm{e}^{t(u-1)}}{(u-\alpha)(u-1)^j},
	\end{equation}
	and 
	\begin{equation}

		p_i(x) = \oint_\contour \frac{\dd w}{2\pi\ii} \frac{w^{i-x}\mathrm{e}^{t(w-1)}}{(w-\alpha)(w-1)^i},
	\end{equation}
	whose contours surround poles at $w,v=1,0,\alpha,1-\alpha$ whilst omitting all other singularities of the integrand. (Proof in the paper; no proof environment follows the statement in the TeX.)

