body:
[Prop 10 of arXiv:2608.26259, 'Cutoff with an $O(1)$ window for Potts Glauber Dynamics\\on lattice at High Temperature'] Assume \(0<\alpha\le(2C_{\mathrm{bp}})^{-1}\) and recall
\(\vartheta=C_{\mathrm{bp}}\alpha\). There are constants
\(c_{\mathrm{len}},C_{\mathrm{len}},C_{\mathrm{jnt}}<\infty\) such that for all integers $\ell\ge1$ and $b\ge1$,
\begin{equation}
\mu\big(\ell(x_1)=\ell,\ b(x_1)\ge b\big)\le C_{\mathrm{jnt}}\,\vartheta^{\,b}\,e^{-\eta\ell}.
\end{equation}
Moreover, for every integer $\ell\ge1$,
\begin{equation}
c_{\mathrm{len}}\,e^{-\eta \ell}
\ \le\ \mu(\ell(x_1)=\ell)
\ \le\ c_{\mathrm{len}}\,e^{-\eta \ell}\,\bigl(1+C_{\mathrm{len}}\,\alpha\bigr),
\end{equation}
and hence
\begin{equation}
\mu(\ell(x_1)>t)\ \le\ 
c_{\mathrm{tail}}\,e^{-\eta t},
\qquad
c_{\mathrm{tail}}:=\frac{c_{\mathrm{len}}\,e^{-\eta}(1+C_{\mathrm{len}}\alpha)}{1-e^{-\eta}}.
\end{equation}

[Definition 6 of arXiv:2609.00448, 'Equivariant formality and representation theory'] (\cite[\S I.4]{Ho}, \cite[\S 3]{BZ}, \cite[Definitions 2.2 and 2.5]{F})
	Let $\delta: R(G)\to K^{-1}(G)$ be the $\mathbb{Z}$-linear map which sends a complex representation $\rho$ with underlying vector space $V$ to the $K$-theory class represented by the complex of vector bundles
	\begin{align*}
		0\longrightarrow G\times\mathbb{R}\times V&\longrightarrow G\times\mathbb{R}\times V\longrightarrow 0\\
		(g, t, v)&\mapsto\begin{cases}(g, t, -t\rho(g)v),&\ \text{if }t>0\\ (g, t, tv),&\ \text{if }t\leq 0.\end{cases}
	\end{align*}
	More generally, for an element $\rho\in\text{ker}(i^*: R(G)\to R(K))$ which is the formal difference $\rho_1-\rho_2\in R(G)$ of two complex $G$-representations restricting to the same $K$-representations, we define the $\mathbb{Z}$-linear map $\delta^{G/K}:\text{ker}(i^*)\to K^{-1}(G/K)$ which sends $\rho$ to the complex of vector bundles
	\begin{align*}
		0\longrightarrow G/K\times\mathbb{R}\times V&\longrightarrow G/K\times\mathbb{R}\times V\longrightarrow 0\\
		(gK, t, v)&\mapsto\begin{cases}(gK, t, t\rho_1(g)\rho_2(g)^{-1}v),&\ \text{if }t>0\\ (gK, t, tv),&\ \text{if }t\leq 0.\end{cases}
	\end{align*}
	The map $\delta_K^{G/K}: \text{ker}(i^*)\to K_K^{-1}(G/K)$ is defined using the same complex of vector bundles and equipping it with the $K$-action on $G/K\times \mathbb{R}\times V$ given by $k\cdot(gK, t, v)=(kgK, t, \rho_1(k)v)$. The map $\delta_K^G: R(G)\to K_K^{-1}(G)$ can be defined similarly (here $K$ acts on $G$ by conjugation). We will also use the same notation to denote the rationalized maps from the rational representation ring to the rational $K$-theory $K^{-1}(G; \mathbb{Q})$, $K^{-1}(G/K; \mathbb{Q})$ etc.

[Theorem 35 of arXiv:2607.02777, 'Hypocoercivity for Hamiltonian Diffusions \\ with Singular Drift'] Let $h \in L^2(\mu)$ be a probability density with respect to $\mu$ and set $\mathbb{P}_{h\mu}\defeq \int_{\Omega} \mathbb{P}_{(x,y)}(\cdot) \, h(x,y) \,\textup{d}\mu(x,y)$.
        Then $\mathbb{P}_{h\mu}$ solves the martingale problem for $(\cL,D(\cL))$, i.e., for all $f\in D(\cL)$, the process $(M_t^{[f]})_{t\geq 0}$ on $(C([0,\infty);\Omega), \mathcal{B}, \mathbb{P}_{h\mu})$ defined by
		\begin{equation}

			M_t^{[f]} \defeq f(X_t, Y_t) - f(X_0, Y_0) - \int_{0}^{t} \cL f(X_s, Y_s) \,\textup{d}s, \quad t \ge 0,
		\end{equation}
		is an $(\mathcal{G}_t)_{t\geq 0}$-martingale. 
        Furthermore, if $f\in D(\cL)$ with $f^2\in D(\cL)$ and $\cL f \in L^4(\mu)$, then also the process $(N_t^{[f]})_{t\geq 0}$ given by
		\begin{equation}

			N_t^{[f]} \defeq (M_t^{[f]})^2 - \int_{0}^{t} \bigl(\cL(f^2)-2f \cL f\bigr)(X_s, Y_s) \,\textup{d}s, \quad t \ge 0,
		\end{equation}
		is a martingale with respect to $(\mathcal{G}_t)_{t\geq 0}$, identifying the quadratic variation of $(M_t^{[f]})_{t\geq 0}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

