[Proposition prop:feature-side-localization of arXiv:2608.22910, 'A Commutator Framework for Selective Spectral Alignment in Deep Neural Networks'] For \(1\leq i,j\leq r_\ell\),
\begin{equation}
v_{\ell,i}^\top\mathcal S_\ell v_{\ell,j}
=
\sqrt{\lambda_{\ell,i}\lambda_{\ell,j}}
\,u_{\ell,i}^\top Q_\ell u_{\ell,j}.
\end{equation}
Consequently, for the preceding range of \((k,\beta)\),
\begin{align}
\mathcal G_{\mathcal S,\ell}^{(k,\beta)}
&=
\sum_{\substack{1\leq i\leq k\\k+\beta<j\leq r_\ell}}
\lambda_{\ell,i}\lambda_{\ell,j}
|u_{\ell,i}^\top Q_\ell u_{\ell,j}|^2,
\\
\|[\mathcal S_\ell,\mathrm{NFM}_\ell]\|_F^2
&=
\sum_{i,j=1}^{r_\ell}
(\lambda_{\ell,i}-\lambda_{\ell,j})^2
\lambda_{\ell,i}\lambda_{\ell,j}
|u_{\ell,i}^\top Q_\ell u_{\ell,j}|^2.

\end{align}
Moreover,
\begin{align}
&\|[\Pi_{\ell,N}^{(k)}\mathcal S_\ell
\Pi_{\ell,N}^{(k+\beta),\perp},\mathrm{NFM}_\ell]\|_F^2=
\sum_{\substack{1\leq i\leq k\\k+\beta<j\leq r_\ell}}
(\lambda_{\ell,i}-\lambda_{\ell,j})^2
\lambda_{\ell,i}\lambda_{\ell,j}
|u_{\ell,i}^\top Q_\ell u_{\ell,j}|^2.

\end{align}

[Lemma lem: Delta_1 Roots of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Assume (equation eq: Parameters of the paper). For all $\sigma\ge 0$, the equation $\Delta_1(w,\sigma)=0$ has exactly three distinct root branches $w_1(\sigma)<w_2(\sigma)<w_3(\sigma)$ which satisfy the following:\\\\
\underline{relative positions}: $\forall \sigma \ge 0$, 
\begin{equation}

 -w_1(\sigma)\leq 0<w_e<w_2(\sigma)\leq 1<r\leq w_3(\sigma).
\end{equation}
\underline{monotonicity}: $\forall \sigma>0$, \ \ 
\begin{equation}

w_1'(\sigma)<0, \ \ w'_2(\sigma)<0, \ \ w_3'(\sigma)>0\ \ \mbox{for}\ \ \sigma>0.
\end{equation}
\underline{asymptotics}:
\begin{equation}

\left|\begin{array}{lll}
\displaystyle w_1(\sigma)=-\frac{dw_e}{r}\sigma^2+\mathcal O(\sigma^3),\\
\displaystyle w_2(\sigma)=1-\frac{d(1-w_e)\sigma^2}{r-1}+\mathcal O(\sigma^3),\\
\displaystyle w_3(\sigma)=r+\frac{d(r-w_e)}{r(r-1)}\sigma^2+\mathcal O(\sigma^3),
\end{array}\right. \ \ \mbox{as}\ \ \sigma \to 0
\end{equation}
and 
\begin{equation}

\left|\begin{array}{lll}
\displaystyle w_1(\sigma)=-\sqrt{d}\sigma +\mathcal O(1),\\[1mm]
\displaystyle w_2(\sigma)=w_e+\mathcal O(\sigma^{-2}),\\[1mm]
\displaystyle w_3(\sigma)=\sqrt{d}\sigma +\mathcal O(1)
\end{array}\right.\ \ \mbox{as}\ \ \sigma\to +\infty.
\end{equation}

[Prop CT UB UT of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] For any $t \in (0, \infty)$ and $\lambda \in (0, \infty)$,
  \begin{equation}
    \sup_{\bm{x} \in M^k} \hat{P}_{\bm{x}}\bigl( C_t > \lambda t^{d_{\mathrm{ct}}} \bigr) 
    \leq \tilde{c}_1(t) \exp\! \left(-\tilde{c}_2(t) \lambda^{2/\hat{d}_{\mathrm{s}}^*}\right).
  \end{equation}

[Lemma 31 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $b > 0$,  $\vec{y} \in \weyl_2$, and $f,g \in C([0,b])$, such that $f(b) \ge y_1 > y_2 \ge g(b)$, and $f(t) > g(t)$ for $t\in[0,b]$. For any $\varepsilon > 0$, there exists $\delta > 0$, depending on $\varepsilon, b, y_1, y_2 ,f,g$, such that
\begin{align}
\mathbb{P}_{\mathrm{pin}}^{b,\vec{y}}\left(g(t) - \varepsilon \leq \mathcal{Q}_2(t) \leq \mathcal{Q}_1(t) \leq f(t) + \varepsilon \mbox{ for all }t \in [0,b] \right) &\geq \delta.
\end{align}
Now fix $M>0$ and assume in addition that $f(t) = y_1+m(b-t)$ and $g(t) = y_2+m(b-t)$ for some $m\in\mathbb{R}$ with $|m|\le M$. Then the lower bound $\delta$ in \eqref{Eq.StayInCorridor} may be taken to depend only on $\varepsilon,b,M$.

[Prop 8 of arXiv:2607.27535, 'Universal topological statistics on \\ triangulated singular spaces'] Let $\phi: K \to M \subset \RR^D$ be a $C^2$-triangulation, where $K$ is purely $d$-dimensional and $M$ is compact. Let $\subdiv_\l: K \to K_\l$ be the $\l$-th FK-subdivision with respect to some vertex order, and let $\psi_\l: \wtilde{K}_\l \to M$ be the rectification of $\phi \circ \subdiv_\l^{-1}$. Then for all sufficiently large $\ell$, the following assertions hold:
    \begin{enumerate}
        \item For every $x \neq y \in \wtilde{K}_\l$,
        \begin{align*}
            \bigg( 1 + \frac{\gamma}{\ell} \bigg)^{-1} \le \frac{\dist_M (\psi_\l(x), \psi_\l (y))}{\dist_{\mathsf{PL}} (x, y)}  \le \bigg( 1 + \frac{\gamma}{\ell} \bigg),
        \end{align*}
        where $\dist_{\mathsf{PL}}$ is the piecewise-linear metric on $\wtilde{K}_\l$. The constant $\gamma$ is given by:
            \[ \gamma = 3\sqrt{d} \cdot  \frac{\sup_{x \in K} \| \on{Hess}_x\phi \| }{\inf_{x \in K} \sing_{\min}(\Diff_x \phi)} \cdot \frac{\max_{\sigma \in K} \diam(\sigma)^2}{\min_{\sigma \in K} \sthick(\sigma)}. \]
        \item For every $d$-simplex $\sigma \in \wtilde{K}_\ell$, the diameter of $\sigma$ is at most $c_1 / \l$ and its thickness is at least $c_2$ regardless of $\l$. The constants $c_1,c_2$ are given in \eqref{eqn:scr_dt}, \eqref{eqn:constc012}.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

