[Definition 5 of arXiv:2607.10725, 'From the Airy line ensemble to the Gaussian free field'] For $x_1, x_2, t_1, t_2 \in \mathbb{R}$, we define the {\em extended Airy kernel} by 
\begin{equation}
\begin{split}
K^{\mathrm{Ext.Airy}}(t_1,x_1; t_2,x_2) = \frac{1}{(2\pi \im)^2} \int_{\Im z=\eta} d z \int_{\Im w=\eta'} dw \frac{e^{\im \left(z^3/3 +x_1z + w^3/3 + x_2w\right)}}{\im (z+w) + t_2 - t_1}.
\end{split}
\end{equation}
In (\ref{Eq.S1AiryKer}), $\eta,\eta'>0$ are arbitrary, subject to the condition that $\eta+\eta'+t_1-t_2<0$ whenever $t_2>t_1$.

[Lemma 24 of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] If $\beta$ is populated and $|\beta|=2$, then
\begin{enumerate}
	\item either $\beta$ is purely polynomial, 
i.e.~$\beta=\delta_\n$ for some $|\n|=2$,
	\item or $\beta=\delta_k+\kk\delta_{\0}$ for some $k\geq\kk$.		
\end{enumerate}

[Corollary 8 of arXiv:2608.26509, '2608.26509'] Under the hypotheses of Theorem~\ref{thm:main}, the \(\alpha\)-process is
recurrent if either of the following bounds holds for all sufficiently large
\(r\):
\begin{enumerate}
 \item \(V(o,r)\leq Cr^d\) for constants \(C>0\) and \(d\leq\alpha\);
 \item \(V(o,r)\leq Cr^\alpha(\log r)^p\) for constants \(C>0\) and
 \(p\leq1\).
\end{enumerate}

[Theorem thm:lip_samples of arXiv:2512.04371, 'Constructive Approximation under Carleman's Condition, \\ with Applications to Smoothed An'] Fix $\varepsilon>0$ and $\delta\in(0,1)$. 
Let $\sigma \in \mathsf{Lip}^{k,M}(\RR)$. 
Suppose that the $y$-marginal of $\mu$ has a finite fourth moment, i.e., $\EE[|y|^4] <\infty$. 
Let $\ell(y,y') = (y-y')^2$ be the quadratic loss function.
Then there exists an algorithm that agnostically learns $\cH_\sigma$ with accuracy $\varepsilon$ and confidence $1-\delta$ using i.i.d. samples of size 
\begin{enumerate}
    \item $O\Big(\varepsilon^{-3} d^{ O\left((M/\varepsilon)^{r/k} \cdot \left(k\log k \right)^{r-1}\right)} \log(1/\delta)\Big)$ under \(r\)-strictly sub-exponential input $\mu_x$;
    \item $O\Big(\varepsilon^{-3} d^{O\big(\exp \big\{O\big( (M/\varepsilon)^{1/k}\big)\big\}\big)} \log(1/\delta)\Big)$ under sub-exponential input $\mu_x$.
\end{enumerate}

[Corollary 28 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Let $X$ have density $f$ with respect to $\pi_{T}.$ If $H(T_{a}(X) |\pi_{aT}) < \infty$ for some $a \in (0,1],$ then
    \begin{displaymath}
        a\E X = \E T_{a}(X) < \infty
    \end{displaymath}
    and
    \begin{displaymath}
         \E T_{a}(X) \log T_{a}(X) < \infty .
    \end{displaymath}

