[Lemma pp of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] Suppose $z_0 \neq (0,0).$ Let $K$ be a compact neighbourhood of $z_0$ in the quadrant satisfying $d((0,0), K) > 0$. Let $\alpha_0 \in [0, \pi/2]$. Then, for sufficiently small $\eta>0$, there exist constants $r_0>0$ and $D_{\alpha_0}>0$ such that for any $z \in K$ and any pair $(a,b)$ satisfying $\sqrt{a^2+b^2}>r_0$ and $|\alpha(a,b) - \alpha_0|<\eta$, the following inequalities hold
\begin{equation}
\Big|\int\limits_{S^{\pm}_{x, \alpha}}
\frac{\phi_2^z(x) \gamma_2(x, Y^+(x))}{\partial_y\gamma(x, Y^+(x))} \exp\big(-ax -b Y^+(x)\big)dx \Big| \leq D_{\alpha_0} \exp\Big(-a x(\alpha) -b y(\alpha) - \epsilon \sqrt{a^2+b^2}  \Big),
\end{equation}
\begin{equation}

\Big|\int\limits_{S^{\pm}_{y, \alpha}}
\frac{\phi_1^z(y) \gamma_1(X^+(y), y)}{\partial_x\gamma(X^+(y), y)} \exp\big(-aX^+(y) -b y \big)dy \Big| \leq D_{\alpha_0} \exp\Big(-a x(\alpha) -b y(\alpha) - \epsilon^2\sqrt{a^2+b^2}\Big).
\end{equation}

 If $b>b_0$,
\begin{equation}

\Big| \int\limits_{S^{\pm} _{x, \alpha}}  
\exp((a_0-a) x + (b_0-b) Y^{+}(x))
  \frac{dx}{\partial_y\gamma(x, Y^{+}(x)) } \Big| \leq  
  \frac{D_{\alpha_0}}{b-b_0} \exp\Big(-a x(\alpha) -b y(\alpha) -\epsilon^2\sqrt{a^2+(b-b_0)^2}\Big).
\end{equation}  

 If $a>a_0$,
\begin{equation}

\Big| \int\limits_{S^{\pm} _{y, \alpha}}  
\exp((a_0-a) X^+(y) + (b_0-b) y )
  \frac{dy}{\partial_x\gamma(X^+(y), y) } \Big| \leq  
 \frac{D_{\alpha_0}}{a-a_0}\exp\Big(-a x(\alpha) -b y(\alpha) -\epsilon^2\sqrt{(a-a_0)^2+b^2}\Big).
\end{equation}

