[Coro 26 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $X^K$ be the right process provided by \Cref{prop:X^K}.
Further, for every $A\in \mathcal{B}(\mathbb{R}^d), s,t\geq 0, (s,x)\in E$, set
\begin{equation*}
    \Gamma_{\mu}^K:=\left(\Gamma_{\mu,t}^{K,s,x}\right)_{t\geq 0, (s,x)\in E},\quad \Gamma_{\mu,t}^{K,s,x}(A)
    :=\mathbb{P}^{K}_{s,x}\left(X_2^K(t)\in A\cap E(t+s)\right).
\end{equation*}
Then the following assertions hold
\begin{enumerate}
    \item[(i)] $(E,\Gamma_{\mu})$ is a $\mu$-restricted fundamental solution flow to the linear Fokker-Planck equation \eqref{eq:LFPshortKcal}.
    Moreover, if $b$ is locally bounded then $(E,\Gamma_{\mu})$ is a $\mu$-restricted fundamental solution flow to the linear Fokker-Planck equation \eqref{eq:LFPshortKbar}.
    \item[(ii)] If $\bf H_u(K)$ is fulfilled and $E^K$ is given by \Cref{prop: HuK}, then $\left(E^K, \left(\Gamma_{\mu,t}^{K,s,x}\right)_{t\geq 0, (s,x)\in E^K}\right)$ is a $\mu$-restricted fundamental solution flow to the linear Fokker-Planck equation \eqref{eq:LFPshortKbar}.
\end{enumerate}

[Definition def:not:symProb of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] The space $\mathcal{M}_{\kappa, d}$  is the set of probability measures $\nu \in \mathcal{P}((\ensuremath{\mathbb{R}}^d)^{1 + \kappa})$ that satisfy the following two properties:
    \begin{enumerate}
        \item (Leaf Exchangeability) For any permutation $\tau$ on $\{1, \ldots, \kappa\}$, we have
        \begin{equation}

            \nu(dx_0, dx_{\{1, \ldots, \kappa\}}) = \nu(dx_0, dx_{\{\tau(1), \ldots, \tau(\kappa)\}}).
        \end{equation}
        \item (Edge Symmetry) $\bar{\nu}$ satisfies
        \begin{equation}

            \bar{\nu}(dx_0, dx_1) = \bar{\nu}(dx_1, dx_0).
        \end{equation}
    \end{enumerate}
    In addition, given $T \in (0, \infty)$, we define the space $\mathcal{M}_{k,d}^T$ to be the set of measures $\mu \in \mathcal{P}((\mathcal{C}_T^d)^{1 + \kappa})$ such that $\mu_t \in \mathcal{M}_{\kappa, d}$ for all $t\in [0, T]$.

[Theorem 5 (Marginals) of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] The $\lambda$-marginal is
\begin{equation}
        \Prob_q^{X,Y}(\lambda)
        =\frac{Q_\lambda[X+qX]P_\lambda(Y)}{\Ht(X+qX;Y)}.
\end{equation}
The $\mu$-marginal is
\begin{equation}
        \Prob_q^{X,Y}(\mu)
        =\frac{Q_\mu(qX)P_\mu(Y)}{\Ht(qX;Y)}.
\end{equation}

