body:
[Lemma lem:continuity of arXiv:2607.05671, 'Bi-infinite systems of singularly interacting Brownian particles and the KPZ equation'] Fix $r \in [1,\infty)$, $\theta \in (0,1)$, and $T \in (0,\infty)$.
\begin{enumerate}[label = (\roman*)]
\item There exist constants $C_1 = C_1(\theta,r,T)$ and $C_2 = C_2(\theta,r,T)$ in $(0,\infty)$ such that for all $\varepsilon \in (0,1]$, $t \in [0,T]$ and $x,x' \in \mathbb{R}$, 
\begin{equation} 
\|\tilde{\mathcal{E}}_\theta^\varepsilon(t,x') - \tilde{\mathcal{E}}_\theta^\varepsilon(t,x)\|_r \leq C_1e^{C_2(|x|+|x'|)}|x' - x|^{\theta/2}.
\end{equation}
\item 

There exist constants $C_3 = C_3(\theta,r,T)$ and $C_4 = C_4(\theta,r,T)$ in $(0,\infty)$ such that for all $\varepsilon \in (0,1]$, $x \in \mathbb{R}$ and $t,t' \in [0,T]$,
\begin{equation} 
\| \tilde{\mathcal{E}}_\theta^\varepsilon(t',x) - \tilde{\mathcal{E}}_\theta^\varepsilon(t,x) \|_r \leq C_3 e^{C_4|x|}|t' - t|^{\theta/4}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

