\noindent \thetag{ii} 
All Dirichlet forms in (equation :9Aa of the paper) and (equation :9Ab of the paper)  are strongly local and quasi-regular on $ \Lmuam $ and $ \Lmm $, respectively.

[Definition 19 of arXiv:2608.20552, 'One-point fluctuations for exponential last passage percolation under upper-tail condition'] For $z_0\in(-1,0)$ and $L>0$, define
\beqq
\begin{split}
    \cont_-^L(z_0)
    &:=\{z_0+re^{2\pi\ii/3}:r\in[0,L^{-1/12}]\}
    \cup\{z_0+re^{-2\pi\ii/3}:r\in[0,L^{-1/12}]\}
    \cup\gamma_-,
\end{split}
\eeqq
where $\gamma_-$ is the circular arc centered at $-1$ joining the points $z_0+L^{-1/12}e^{\pm2\pi\ii/3}$ and passing to the left of $-1$. Similarly, define
\beqq
\begin{split}
    \cont_+^L(z_0)
    &:=\{z_0+re^{\pi\ii/3}:r\in[0,L^{-1/12}]\}
    \cup\{z_0+re^{-\pi\ii/3}:r\in[0,L^{-1/12}]\}
    \cup\gamma_+,
\end{split}
\eeqq
where $\gamma_+$ is the circular arc centered at $0$ joining the points $z_0+L^{-1/12}e^{\pm\pi\ii/3}$ and passing to the right of $0$.

[Lemma l.ulbd of arXiv:2606.07353, 'The Gaussian structure of a perturbed KPZ'] For any $p\in[1,+\infty)$, there exists $C>0$ only depending on $p,V$ such that 
\begin{equation}
\mathbf{E}\Big[\big(\inf_{x,y\in\mathbb{T}}
\mathcal{Z}_{t,t-1}^V(x,y)\big)^{-p}\Big]+\mathbf{E}\Big[\big(\sup_{x,y\in\mathbb{T}^d}\mathcal{Z}_{t,t-1}^V(x,y)\big)^p\Big]\leq
C.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:martingale_convergence of arXiv:2607.13748, 'Load Balancing with Individually Heterogeneous Servers'] Suppose $W_1(t)$ and $W_2(t)$ are independent $\mathcal{F}_t$-Brownian motions. Then, as $n\to \infty$, we have
    \begin{enumerate}
        \item $(M_A^n(t), M_{D,1}^n(t))\Rightarrow (W_1(t), W_2(t))$,
        \item $M_{D,i}^{f,n}\stackrel{p}{\rightarrow} 0$ for all $i\geq 2$ uniformly for all $f\in \Lipbar{\mathbb{R},L}(\mathbb{S})$. 
    \end{enumerate}

