body:
[Proposition 15 (Small-aspect-ratio expansion) of arXiv:2608.26693, '2608.26693'] For fixed $\tau>0$, the two-sample limit admits the expansion, as $c_0,c_1\downarrow0$,
\begin{equation}
b_\tau^{(2)}(c_0,c_1)
=\frac{c_0+c_1}{4(1+2/\tau)}
+O\!\left((\sqrt{c_0}+\sqrt{c_1})(c_0+c_1)\right).
\end{equation}

[Lemma 17 of arXiv:2608.30602, '2608.30602'] Let $r=|x-y|$, and let $\rho=|x-z|-|z-y|$, $\tau=\frac{2(|x-z|\,|z-y|)^{1/2}}{\sqrt{r^2-\rho^2}}$ and $u(\rho,\theta)$ be as in the proof of Lemma~\ref{lem:boundedness of W^V_0-2}. Then the kernel
	\begin{equation*}
		\mathfrak{L}(x,y)=\int_{-\frac{\pi }{2}}^{\frac{\pi }{2}}\int_{|\rho|\le \min\{1, r/2 \}} \left(\frac{\big(|V_0|+|\nabla V_0|\big) \tau^{3/2} \sec\theta}{\sqrt{|\rho|}}
		+\frac{|V_0|\sqrt{\tau}\,\sec\theta}{ r \sqrt{|\rho|}}
		+\frac{|V_0|\sqrt{\tau} \,\sec\theta }{\sqrt{|\rho|}}\right) d\rho \, d\theta,
	\end{equation*}
	where $V_0$ and $\nabla V_0$ are evaluated at $z=u(\rho,\theta)+\frac{x+y}{2}$, is admissible.

[Corollary cor:on-dim_conv_SI_setting of arXiv:2605.15783, 'Set-indexed and multiple sums in high dimensions'] In the {\bf (SI)} setting suppose that (a)--(d) hold. Then, for every
  $A,B\in\mathsf{F}$,
  \begin{displaymath}
    n^{-1/2}\|S_n^{(d)}(A)-S_n^{(d)}(B)\|_2 \overset{\mathbb{P}}{\to} \mu(A\triangle B)^{1/2}
    \quad\text{as}\  d\to\infty.
  \end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

