body:
[Thm 3 (Bounding Wasserstein distance by the uniform discrepancy) of arXiv:2605.03528, '\bf Kolmogorov-Smirnov distance and discrepancies {\em versus} Wasserstein distances'] Let $\mu$ and $\nu$ two probability measures on $([0,1]^d, {\cal B}or([0,1]^d),\lambda_d)$.  Then,
\begin{itemize}
\item If $p>d$ then
\begin{align*}
{\cal W}_p^p(\mu, \nu)& \le   \frac{\diamd^p(2^p+1)}{2(2^{p-d}-1)}    D^{\infty}(\mu,\nu) .


\end{align*}
If furthermore, $1+2^{-p}-2^{p-d}>0$, i.e. $p< d+\frac{\log(1+\sqrt{1+2^{-(d-2)}})}{\log 2}-1$, then
\begin{align*}
{\cal W}_p^p(\mu, \nu)& \le   \frac{\diamd^p}{2^{p-d}-1}\left[\frac{2^p+1}{2}    D^{\infty}(\mu,\nu) -  2^{p(1-\frac{1}{d})}\left(1+2^{-p}-2^{p-d}\right) D^{\infty}(\mu,\nu)^{\frac{p}{d}}\right].


\end{align*}

\item If $p=d$  then
\[
{\cal W}_p^p(\mu, \nu) \le  \diamd^d   \bigg( \bigg(   \frac{(d+1)2^{d-1}}{d}+\frac 1{2d}\bigg) D^{\infty}(\mu,\nu)+\frac{2^d+1}{2d\log 2} D^{\infty}(\mu,\nu)\log\Big(\frac{1}{ D^{\infty}(\mu,\nu)}\Big)\bigg).
\]
\item If $p<d$ then
\[
{\cal W}_p^p(\mu, \nu) \le \diamd^p    {2^{-\frac pd}}   \bigg( \frac{2^p+1}{1-{2^{p-d}}} + 2^{p}\bigg) D^{\infty}(\mu,\nu)^{\frac pd}.
\]
\end{itemize}

