[Lemma lem-UpperLDPbound of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Assume the situation and the notation described in Section~(sec-Purpose of the paper). That is, $\Lambda_N$ is a centred box with volume $|\Lambda_N|\sim N/\rho$ for some $\rho\in(0,\infty)$, and is decomposed into the subboxes $z+W_R=z+[-R,R]^d$ for some $R\in(0,\infty)$ with $z\in 2R\mathbb{Z}^d\cap\Lambda_N$. We consider particle boundary condition and indicate it by \lq par\rq. Fix a large parameter $M\in(0,R/2)$ and fix  $\xi\in {\mathcal M }_1({\mathcal L }_W^{{{\scriptscriptstyle{({M}})}}}\times{\mathcal S }_W^{{{\scriptscriptstyle{({M}})}}})$ such that $ \langle  {\mathfrak N}^{\ssup{\ell,{\mathcal S }}}_{\partial W},\psi\rangle<\infty$, where $\psi=\partial\Pi_W^{{{\scriptscriptstyle{({\mathcal S }})}}}(\xi)\in  {\mathcal M }_1({\mathcal T }_W)$, and assume that $\psi$ is $W$-admissible.  Then, for any sufficiently large $R$, there is $\psi_N\in {\mathcal M }_1({\mathcal T }_W)$ that converges to $\psi$ as $N\to\infty$ such that
\begin{equation}
\begin{aligned}
\liminf_{N\to\infty}\frac 1{|\Lambda_N|}&\log{\tt Q}^{\ssup{\Lambda_N,{\rm par}}}_{M}\Big(\partial\Xi^{{{\scriptscriptstyle{({\mathcal S }})}}}_{N,R} =\psi_N\Big)\geq -\frac{C_M}{R^{d/2}}+\frac 1{|W|}\langle\psi,\mathfrak p_{W,M}\rangle,
\end{aligned}
\end{equation} 
where we recall (equation pMdef of the paper) and introduce 
\begin{equation}
\mathfrak p_{W,M}(\mu)=\sum_{i\in I}\log p_{x_i}^{{{\scriptscriptstyle{({W,M}})}}}(l_i,y_i),\qquad \mu=\sum_{i\in I}\delta_{(x_i,l_i,y_i)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop opti_problem_231 of arXiv:2604.23751, 'Large deviation principles for pattern-avoiding permutations, and limit shapes for constra'] The action $A_{\beta}$ has a unique minimizer $\varphi_\beta$ in $\mathcal{E}$. 
    Moreover, for $\beta \leq 0$, we have $\varphi_{\beta}(t)=0$ for all $t \in [0,1]$. 
    For $\beta>0$, it is given by the formula
	\begin{equation}
		\varphi_\beta(t)= \frac{1}{\beta} \log\left( \frac{ 1 + \textup{e}^{\beta} }{ 1 + \textup{e}^{\beta(1-2t)}} \right) - t.
	\end{equation}

[Lemma 7 of arXiv:2605.26439, '2605.26439'] Let $T>0$. Assume that $B\in\mathcal L(U;\mathcal H_{-\eta})$ for some $\eta\in[0,1)$ and that there exists $\beta\in(0,1/2)$ such that
    \begin{equation}
        \int_0^T t^{-2\beta}\|S_{-\eta}(t)B\|_{\mathcal L_2(U;\mathcal H)}^2dt<\infty.
    \end{equation}
    Then the stochastic convolution
    \begin{equation*}
        W_A(t):=\int_0^tS_{-\eta}(t-s)BdW_s,\quad t\in[0,T],
    \end{equation*}
    is well defined and admits an $\mathcal H$-valued continuous modification. Moreover,
    \begin{equation*}
        W_A\in L^2(\Omega;C([0,T];\mathcal H)).
    \end{equation*}

