[Definition 30 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Let $\kappa$ be a linear order with a designated member $\ttOmega\in \kappa$. We define the terms in $\calL^u_{\kappa,\ttOmega}$ as members of $\bfL(u)_{\{\alpha\in \kappa\mid\alpha<\ttOmega\}} \cup \{\ttL(u)_\ttOmega\}$.
    We define $\calL^u_{\kappa,\ttOmega}$-formulas as follows:
    \begin{enumerate}
        \item For two terms $s$ and $t$, $s\in t$ and $s\notin t$ are formulas.
        \item We can form new formulas by $\land$, $\lor$, and bounded quantifications $\forall x\in s A(x)$ and $\exists x\in s A(x)$.
    \end{enumerate}
    We also define $|s| = \max (\supp^{\bfL(u)}_\kappa(s))$ computed in $\kappa$. Note that
    \begin{equation*}
        \lvert \ttL(u)_\xi\rvert = \lvert \{x\in \ttL(u)_\xi \mid \phi(x,a_0,\cdots,a_{n-1})\}\rvert = \xi.
    \end{equation*}

[Theorem 12 (Solution of Problem~\ref{fractional-problem}) of arXiv:2608.25164, 'A time-fractional Kalman filter'] Problem~\ref{fractional-problem} has a unique solution. First, $H$ is the
unique bounded deterministic solution of the following equation on the
triangular domain $0\leq s\leq t\leq T$:
\begin{align}
H(t,s)
=K_X(t,s)-\int_0^s\frac{G^2(r)}{D^2(r)}
H(t,r)H(s,r)dr.                                               
\end{align}
Define
\begin{align}
A(t,s)&=\frac{G^2(s)}{D^2(s)}H(t,s),
&
B(t,s)&=\frac{G(s)}{D^2(s)}H(t,s),                            
\end{align}
and the resolvent kernels
\begin{align}
Q_1(t,s)&=-A(t,s),\nonumber\\
Q_{n+1}(t,s)&=-\int_s^tA(t,r)Q_n(r,s)dr,\qquad n\geq1,         \\
Q_H(t,s)&=\sum_{n=1}^{\infty}Q_n(t,s).                        
\end{align}
Set
\begin{align}
m_H(t)
 &=m(t)+\int_0^tQ_H(t,s)m(s)ds,                               \\
L_H(t,u)
 &=B(t,u)+\int_u^tQ_H(t,s)B(s,u)ds.                           
\end{align}
Then the unique best estimate is
\begin{align}
\widehat X(t)=\E[X(t)\mid\mathcal Y_t]
=m_H(t)+\int_0^tL_H(t,u)dY(u).                             
\end{align}
Equivalently, it is the unique adapted solution of
\begin{align}
\widehat X(t)
=m(t)+\int_0^t\frac{G(s)}{D^2(s)}H(t,s)
\big[dY(s)-G(s)\widehat X(s)ds\big].                          
\end{align}
The minimum mean-square error is
\begin{align}
S(t)
=H(t,t)
=K_X(t,t)-\int_0^t\frac{G^2(r)}{D^2(r)}H^2(t,r)dr.             
\end{align}
Moreover,
\begin{align}
\widehat X(0)=m(0),\qquad
H(t,0)=K_X(t,0),\qquad
S(0)=K_X(0,0).                                                
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2609.02193, 'State-law dynamics of McKean-Vlasov stochastic reaction-diffusion equations on $\mathbb R^'] Let $X=L^2(\mathbb R^n)$ and $q>2$. For $R>0$, set
	$B_R=\{x\in\mathbb R^n:|x|<R\}$, and interpret
	$\|w\|_{H^1(B_R)}$ as the extended Borel functional on $X$
	obtained by assigning the value $+\infty$ whenever
	$w|_{B_R}\notin H^1(B_R)$. Suppose that
	$\mathcal B\subset X\times\mathcal P_2(X)$ satisfies the following conditions:
	\begin{itemize}
		\item[(i)] for every $R>0$,
		\begin{align*}
			\sup_{(u,\mu)\in\mathcal B}
			\Big[
			\|u\|_{H^1(B_R)}^2
			+
			\int_X\|v\|_{H^1(B_R)}^2\,\mu(dv)
			\Big]<\infty;
		\end{align*}

		\item[(ii)]
		\begin{align*}
			\lim_{R\to\infty}
			\sup_{(u,\mu)\in\mathcal B}
			\int_{|x|>R}|u(x)|^2\,dx=0;
		\end{align*}

		\item[(iii)]
		\begin{align*}
			\lim_{R\to\infty}
			\sup_{(u,\mu)\in\mathcal B}
			\int_X\int_{|x|>R}|v(x)|^2\,dx\,\mu(dv)=0;
		\end{align*}

		\item[(iv)]
		\begin{align*}
			\sup_{(u,\mu)\in\mathcal B}
			\int_X\|v\|_X^q\,\mu(dv)<\infty.
		\end{align*}
	\end{itemize}
	Then $\mathcal B$ is relatively compact in $X\times\mathcal P_2(X)$.

