body:
[Proposition 7 (Haagerup--Schlichtkrull) of arXiv:2608.30304, '2608.30304'] For $n\in\Nzero$, $\alpha,\beta\ge0$ and $x\in[-1,1]$ put
\begin{equation}
g_n^{(\alpha,\beta)}(x)
=\Bigl(\frac{\Gamma(n+1)\Gamma(n+\alpha+\beta+1)}
{\Gamma(n+\alpha+1)\Gamma(n+\beta+1)}\Bigr)^{1/2}
\Bigl(\frac{1-x}2\Bigr)^{\alpha/2}\Bigl(\frac{1+x}2\Bigr)^{\beta/2}
P_n^{(\alpha,\beta)}(x).
\end{equation}
Then
\[
(1-x^2)^{1/4}\bigl|g_n^{(\alpha,\beta)}(x)\bigr|
\le C_{\mathrm{HS}}\,(2n+\alpha+\beta+1)^{-1/4},
\qquad C_{\mathrm{HS}}<12 .
\]
Moreover
\begin{equation}
F_{n,\alpha,\beta}(x)
=\Bigl(\frac{2n+\alpha+\beta+1}2\Bigr)^{1/2}(1-x^2)^{1/4}
\bigl|g_n^{(\alpha,\beta)}(x)\bigr|
\qquad(n\in\Nzero),
\end{equation}
so that
\begin{equation}
F_{n,\alpha,\beta}(x)\le 2^{-1/2}C_{\mathrm{HS}}\,(2n+\alpha+\beta+1)^{1/4}.
\end{equation}

[Lem 14 of arXiv:2607.24561, 'Range convergence and sharp one-arm asymptotics\\for the critical percolation cluster in h'] Let $\Lambda>3$. There exists a constant $c_1>0$ such that, for every $z \in Q_{0,\Lambda r}\setminus Q_{0,3r}$, $\varepsilon>0$, $i\in\{1,\ldots,\varepsilon^{-1}\}$, every $K$ satisfying $L\ge 10K$, where $L=\varepsilon r/4$, and every $C\in\mathcal S_i$,
\begin{align*}
\E\left[Z_{L}^i\ind{ \mathcal C_e(0; \mathcal Q_{z, i}^c)=C}\right]\ge c_1L^2X_{r,i}^{K-\mathrm{line-good}}(C)\bP\left[C_e(0; \mathcal Q_{z, i}^c)=C\right].
\end{align*}

