body:
[Lemma 24 of arXiv:2608.29361, 'Convergence of the subcritical $\gamma$-LQG metric to the critical $2$-LQG metric as $\gam'] Let $U \subseteq \CC$ be a bounded open set and fix $\varepsilon \in (0,1), \delta \in (0,\xi_c / 2)$. Suppose that we choose the continuous functions $b,M$ such that $b(\xi) \sqrt{M(\xi)} > 40 (1+\xi_c) / \delta$ for all $\xi \in (\xi_c / 2 , \xi_c]$. Then, the following holds for all $\xi \in (\xi_c/2 , \xi_c]$. There exists deterministic constant $C>1$ depending only on $\varepsilon,\delta$, and $U$, such that the following is true with probability at least $1-\varepsilon$. Fix $z \in U$. Then, we have the following.
\begin{enumerate}
    \item 
    For all $m,n \in \NN$ with $m<n$,
    \begin{align*}
        \widetilde{D}_h^{\xi}(\partial B_{e^{-n-50}}(z) , \partial B_{e^{-m}}(z)) \leq C \sum_{k=m}^{n-1} \min_{t \in [k,k+1]} \left(\exp\left((\xi-\delta) (h_{e^{-t}}(z)-2t)\right)\right).
    \end{align*}
    \item 
    For all $n \in \NN$,
    \begin{equation*}
        \widetilde{D}_h^{\xi}(\text{around}\,\,\mathbb{A}_{e^{-n-1},e^{-n}}(z)) \leq C \min_{t \in [n+1,n+2]} \left(\exp\left((\xi-\delta) (h_{e^{-t}}(z) - 2t)\right)\right).
    \end{equation*}
\end{enumerate}

