[Prop 15 of arXiv:2608.29148, '2608.29148'] The curvature tensor $R'_{abcd}$ is given by 
\begin{equation}
\begin{aligned}
R'_{ijkl}&=R_{ijkl}+\frac{1}{2}F_{ij}F_{kl}+\frac{1}{4}F_{ik}F_{jl}-\frac{1}{4}F_{jk}F_{il}, \\
R'_{n+1\,jkl}&=-\frac{1}{2}\nabla_j F_{kl}, \\
R'_{n+1\,j\, n+1\, l}&=\frac{1}{4}F_{jm}F_l{}^m.
\end{aligned}
\end{equation}
The Ricci and scalar curvatures of $g'$ are given by
\begin{equation}
R'_{ij}=R_{ij}+\frac{1}{2}F_{im}F_j{}^m,  \quad
R'_{n+1\, j}=\frac{1}{2}\nabla^i F_{ij}, \quad
R'_{n+1\,n+1}=\frac{1}{4}|F|^2
\end{equation}
and 
\begin{equation}
R'=R+\frac{1}{4}|F|^2.
\end{equation}

[Theorem thm:ode of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] For $\kappa\in(4,8)$ and $p\in\mathscr{P}$, $U^p(\lambda)$ is smooth and solves the following third-order ODE
\begin{equation}
\begin{aligned}
\frac12 \kappa^3\lambda^2 (1 - \lambda)^2U''' &+ \kappa^2\lambda(3\kappa - 16)(1 - \lambda)(1 - 2\lambda)U'' \\
&+ \kappa\left[ 3(\kappa - 4)(\kappa - 8) + \lambda(\lambda - 1)(18\kappa^2 - 212\kappa + 608) \right]U' \\&+ 6(2\lambda - 1)(\kappa - 4)(\kappa - 8)^2 U = 0.
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 9 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Let $D$ be a dilator. We define a linear order $\psi^+(D)$ inductively as follows: For each $\sigma\in D(\psi^+(D))$, we have $\psi(\sigma)\in \psi^+(D)$. 
    For two $\psi(\sigma),\psi(\tau)\in \psi^+(D)$, we define 
    \begin{equation*}
        \psi^+(D)\vDash \psi(\sigma)<\psi(\tau) \iff D(\psi^+(D))\vDash \sigma<\tau.
    \end{equation*}

