[Proposition 20 of arXiv:2608.05679, 'Small ball probabilities and Chung's law of the iterated logarithm for Gaussian Volterra p'] Assume that Condition \eqref{eq constant cond} holds, and set 
$$\tau = \min \left\{ \frac{H}{6},\; \frac{1}{4}\bigl(\alpha+\frac12 \bigr) \right\}.$$
Then there exist positive constants $c_{5,6}, c_{5,7}$, and $c_{5,8}$ such that, for every  $u>t>0$, $\theta>0$, and  $\eta\in (0, c_{5,6}^{-1})$,
\begin{equation}
\begin{split}
&\mathbb{P} \Bigl\{ \left\{ M(t) \leq \theta t^H \right\} \cap \left\{ M(u) \leq \eta u^H \right\} \Bigr\}\\
&\le c_{5,6}\exp \left[ -c_{5,7}\left( \frac{u}{t} \right)^{\tau} \right]
+ \varphi(\theta) \varphi(\eta) \exp\left (c_{5,8} \left( \frac{u}{t} \right)^{-\tau}  \eta^{-\frac{2}{2\gamma+3}-1}\right). 
\end{split}
\end{equation}

