[Lemma lm:recursionforCk of arXiv:2505.00198, '\ttl'] If $\theta>0$, then the sequence $C_k$ defined in (equation eqn-Ck-MMr of the paper), satisfies
\begin{equation}
C_0 =1, C_1 = 1 + \frac{\gamma}{\theta}  
\end{equation}
and, for $k \ge 1$, 
\begin{equation} 
\theta  C_{k+1}- (k + \theta + \gamma)   C_k +  k  C_{k-1} =0.  
\end{equation}
Furthermore, we have
\begin{equation}
\theta C_{r} - r\alpha C_{r-1} >0.  
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:uplowAron of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] Let $A_1,\ldots,A_n\subset \mathbb{R}^m$ be finite sets, let $\alpha_j\in\mathbb{R}_{>0}^{A_j}$ for $j=1,\ldots,n$, let $d_1,\ldots,d_n$ be positive integers and write $d:=\sum_{j=1}^n d_j$. Then for every admissible random field $\mathcal{X}\randin C^\infty(\mathbb{R}^m,\mathbb{R}^{m-1})$ independents of all the exponential sums, and every open set $U\subset \mathbb{R}^m$ we have 
  \begin{equation}
    \sum_{j=1}^n \frac{d_j}{\sqrt{d}}\, \mathbb{E}\#\sol{\mathcal{E}_{\alpha_j},\mathcal{X};U} \leq \mathbb{E}\# \sol{\mathcal{E}_{\alpha_1}^{\odot d_1}\odot \cdots \odot \mathcal{E}_{\alpha_n}^{\odot d_n}, \mathcal{X}; U}\leq \sum_{j=1}^n \sqrt{d_j}\, \mathbb{E}\#\sol{\mathcal{E}_{\alpha_j},\mathcal{X};U} 
  \end{equation}

[Proposition 12 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumption~\ref{assump-particles}\ref{hyp:ICu0} holds and let $(\Omega,\mathcal{F},(\mathcal{F}_{t})_{t\geq 0},\PP)$ be a filtered probability space satisfying the usual conditions. Let $(B^i)_{i\in \N}$ be a family of independent $(\mathcal{F}_{t})_{t\geq 0}$-Brownian motions and let $(X^i_{0},V^i_{0})_{i\in \N}$ be $\mathcal{F}_{0}$-measurable random variables in $\T^d\times \R^d$. Then for each fixed $N\in \N^*$, there exists $\Omega_{N}\in \mathcal{F}$ and a unique process $(u^N,X^{1,N},V^{1,N},\dots,X^{N,N},V^{N,N})$ such that $\PP(\Omega_{N})=1$ and 
\begin{itemize}
\item for all $\omega\in \Omega_{N}$, $u^N$ is the unique solution of the mild equation~\eqref{eq:mildeq};

\item for all $\omega\in \Omega_{N}$, for each $i\in \{1,\dots, N\}$, $(X^{i,N},V^{i,N})$ solves the ODE from~\eqref{Part};

\item $(u^N,X^{1,N},V^{1,N},\dots,X^{N,N},V^{N,N})$ is measurable and adapted to the filtration $(\mathcal{F}_{t})_{t\geq 0}$.

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 6 (Algorithmic guarantee) of arXiv:2608.21466, 'Spectral partitioning for $k$-block averaging kernels of finite Markov chains'] Let $k\in\llbracket 2,n-1\rrbracket$.
The output of Algorithm~\ref{alg:multiway-sweep} satisfies
\begin{equation}
    0\leq F(\widehat{\mathcal O}_F)-F_k^*
    \leq W\overline\delta_\ell-g\delta_k^*.

\end{equation}
If at least one candidate is a $\rho$-approximation for weighted
$k$-means, so that
$\overline\delta_\ell\leq\rho\delta_k^*$, then
\begin{equation*}
    F(\widehat{\mathcal O}_F)-F_k^*
    \leq(\rho W-g)\delta_k^*.

\end{equation*}
In particular, every exact minimizer $\mathcal O$ of $\delta$
satisfies
\begin{equation*}
    F(\mathcal O)-F_k^*
    \leq(W-g)\delta_k^*.

\end{equation*}

[Defn propchaos of arXiv:2606.24385, 'Gradient Mean-Field Dynamics with Measure-Valued States: Well-Posedness, Chaos, and Long-T'] A sequence of random vectors ${\boldsymbol Y}^N=(Y^1,\dots,Y^N)$ in ${\mathscr Y}^N$ is said to be \emph{chaotic with law $\mu\in{\mathscr{P}}({\mathscr Y})$} if for every $k\in\mathbb N$ fixed, the $k$-marginals converge in law:
\begin{align}
\mathcal L(Y^{1},\dots,Y^{k}) \xrightarrow[N\to\infty]{\text{law}} \mu^{\otimes k}.    
\end{align}

[Dfn Definition:StaticSBP of arXiv:2411.13765, 'Schr\"odinger Bridge Problem for Jump Diffusions'] Given a reference measure $R\in \mathcal P(\mathbb{R}^n\times \mathbb{R}^n)$ and target marginals $\rho_0,\rho_T \in \mathcal P(\mathbb{R}^n)$, determine
\begin{equation}
    \hat{\pi}=\arg\min_{\pi \in \mathcal P(\mathbb{R}^n\times \mathbb{R}^n)}\set{\KL{\pi}{R} \text{ such that }  \pi_0=\rho_0,\pi_T=\rho_T }
\end{equation}
where $\pi_0,\pi_T$ are respectively the marginal distributions of $\pi$ in the first and second variable.

We say that the static SBP does not have a solution if the ``\textup{min}'' in (equation Definition:StaticSBP of the paper) is $\infty$.

