body:
[Theorem 4 of arXiv:2607.22892, 'Mirror Langevin diffusions: Convergence rates and Markov chain approximations'] Suppose that a weak solution of the MLD exists and
    \begin{enumerate}
    	\item[(a)] $V, F$ are in $C^1$. $u, u^*$ are strictly convex and in $C^2$. 
        \item[(b)] $g=\nabla^2 u$ is locally bounded and locally uniformly elliptic on $R^d$. That is, for any closed ball $B(0,r)$ of radius $r>0$, there exist positive constants $c_r, C_r$ such that $c_r I \leq g(x) \le C_r I$, for all $x\in B(0,r)$.  
        \item[(c)] For some $\alpha \in (0,1]$, 
    \begin{equation}
    \lim_{x\rightarrow \infty}\left[  x \cdot \frac{\partial V}{\partial x} - \alpha x^T \nabla^2u(x) x\right]=\infty.
    \end{equation}
    \end{enumerate}
    Then the MLD Dirichlet energy $\cdc$ satisfies a Poincar\'e inequality for some constant $\lambda >0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] Let $\eps_i\to0$ and suppose
\begin{equation}
  \norm{\phi_i}_{C^0_\delta}=1,
  \qquad
  \eps_i^\delta
  \norm{\widetilde{\mathcal P}_{\eps_i}\phi_i}_{C^{0,\alpha}_{\delta-4}}
  \longrightarrow0.
\end{equation}
If $\phi_i\to u$ locally on $X\setminus S$, then $u=0$.

