body:
[Theorem main subspace dependent theorem of arXiv:2606.01683, 'Singular-value gap of nonreversible Markov processes'] In the above setting, assume $\gamma_V > 0$. Then 
    \begin{align*}


        &\text{(i)} \qquad \Delta_t^U \leq \frac{2}{\sqrt{t \mkern1mu \gamma_V }} \\
        &\text{(ii)}\sup_{s \in [t, 2t]}  \Delta_s^{U+V} \geq \frac{1}{\frac{3}{2}t \mkern1mu \gamma_V + 3}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:one-scale-second-moment of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] There exists $C<\infty$ such that
\begin{equation*}

        \mathbb E[(\mathcal E_n)^2]\le Cn^2(\log n)^{-2}.
\end{equation*}

[Corollary of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{prop:o_in_kinfty}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$ and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel satisfying $J(x,y) = \Omega(d_G(x,y)^{-d \alpha})$ with $\alpha \in (0,2)$.

    Let $\beta > \beta_c$.

    Then there exists $c = c(G,J) > 0$ such that 

    \begin{equation}
        \mathbf{P}_{\beta}
        \left(
            o 
            \not\in 
            K_{r}^{\scriptscriptstyle (1)},
            o 
            \in 
            K_{\infty}
        \right)
        \leq 
        \frac{1}{(\#B(r))^{c}}
    \end{equation}

    and in particular, for all $r \in \mathbf{N}$

    \begin{equation}
        \mathbf{P}_{\beta}
        \left(
            o 
            \in 
            K_{r}^{\scriptscriptstyle (1)}
        \right)
        \geq 
        \theta(\beta) 
        -
        \frac{1}{(\#B(r))^{c}}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 4 (Change of measure) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] Fix $T>0$, $n\geq 1$, $i\in \{1,\ldots,n\}$, and consider $Z^{i,n}$ from \eqref{eq:Z_i_n}. There exist a probability measure $\Q^{i,n}$ on $\hat{\mathcal{F}}_T^{i,n}$, equivalent to the restriction of $\Prob$ to $\hat{\mathcal{F}}_T^{i,n}$, so that $Z^{i,n}$
    becomes a reflected Brownian motion on $[0,T]$ under $\Q^{i,n}$ for the filtration $\hat{\mathcal{F}}^{i,n}$. Furthermore, $Z^{i,n}$ becomes independent of $\mathcal{G}^{i,n}_T$ under $\Q^{i,n}$, and the Radon--Nikodym derivative $\di \Prob/\di \Q^{i,n}$ (still dependent on $\mathcal{G}^{i,n}_T$) satisfies
	\begin{equation}
	\E^{\Q^{i,n}}\Bigl[ \frac{\di  \Prob }{\di  \Q^{i,n}} \; \big| \;  \mathcal{G}^{i,n}_T\Bigr] = 1
	\end{equation}
	as well as
	\begin{equation}
	\E^{\Q^{i,n}}\Bigl[ \Bigl( \frac{\di \Prob}{ \di \Q^{i,n}}\Bigr)^p \; \big| \; \mathcal{G}_T^{i,n}\Bigr] \leq 	C,
	\end{equation}
	for some $p>1$ close enough to $1$, for a fixed constant $C>0$ which only depends on $p$ and $T$.

[Definition defn:linear_weak_solution of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] We say that $f$ is a weak solution to (equation eq:linear_kolmogorov of the paper) with initial data $f_{\rm in}\in L^2_{x,v}$ provided $f \in L^\infty([0,T];L^2_{\rm loc}(\mathbb T^3\times\mathbb R^3))$, $\nabla_v f \in L^2_{\rm loc}([0,T]\times\mathbb T^3\times\mathbb R^3)$, and 
    \begin{equation}
        \iiint f\;(\partial_t + v\cdot\nabla_x)\psi \, {\rm d} v\, {\rm d} x\, {\rm d} t  + \iint f_{\rm in}\psi(0) \, {\rm d} v \, {\rm d} x = \iiint \nabla_v \psi \cdot \left[\mathcal A\nabla_v f + \mathcal B\right] \, {\rm d} v \, {\rm d} x \, {\rm d} t 
    \end{equation}
    for each $\psi \in C^\infty_c([0,T)\times \mathbb T^3\times \mathbb R^3)$.

[Corollary 9 of arXiv:2604.10820, 'A Strict Gap Between Relaxed and Partition-Constrained\\ Spectral Compression in a Six-Sta'] For the explicit parameter choice \eqref{eq:example-params1}--\eqref{eq:example-params2}, one has
\begin{equation*}
\sup_{\mathcal A\,\mathrm{3\text{--}partition}}\det Q_{\mathcal A}(T)
<\mathfrak D^{\mathrm{rel}}_3(T).
\end{equation*}

[Definition def:parameters-restriction-to-a-subset of arXiv:2411.06195, 'Restrictions of some reinforced processes to subgraphs'] We define new transition probabilities, rates, and weights as follows
  \begin{align}
    & p^{\neq}=\left(p^{\neq}_{ij}:=\frac{p_{ij}}{1-p_{ii}}1_{\{i\neq j\}}\right)_{i,j\in\Lambda}, \quad
      q^{\neq}=(q^{\neq}_{ij}:=q_{ij}1_{\{i\neq j\}})_{i,j\in\Lambda}, \\
    & C^{\neq}=(C^{\neq}_{ij}:=C_{ij}1_{\{i\neq j\}})_{i,j\in\Lambda}, \quad
      C^{\neq}_i:=\sum_{k\in\Lambda}C^{\neq}_{ik}, i\in\Lambda. 
  \end{align}
  For any subset $J\subseteq\Lambda$ with $\rho\in J$, $|J|\ge 2$, we set
  $I=\Lambda\setminus J$ and define 
  \begin{align}

    p^J=(p^J_{ij})_{i,j\in J}:=p_{JJ}+\sum_{l=0}^\infty p_{JI}p_{II}^lp_{IJ},
  \end{align}
  which is a convergent series with $p_{ij}^J=Q^{C,\Lambda}_i(X^J_1=j)$.
  Furthermore, we define
  \begin{align}
    C^J=(C^J_{ij}:=C_ip^J_{ij})_{i,j\in J}, \quad
    q^J=\left(q^J_{ij}:=\frac{C_i}{\pi_i}p^J_{ij}\right)_{i,j\in J}.
  \end{align}
  The notation $p^{J\neq}$, $q^{J\neq}$, and $C^{J\neq}$ means that the two
  operations $\mbox{}^J$ and $\mbox{}^{\neq}$ have been applied successively.

[Lemma 43 (Explicit balanced models) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Assume that $\xi$ has the expansion
\begin{equation}

    \xi(a)=\sum_{p\geq1}\sum_{s_1,\ldots,s_p\in\sS}\Delta^2_{s_1,\ldots,s_p}a_{s_1}\cdots a_{s_p},\qquad a\in\R^\sS,
\end{equation}
where the coefficients are nonnegative and satisfy the standing summability assumptions. For each $p\geq1$, define the symmetrized coefficients
\begin{equation}

    \widehat\Delta^2_{s_1,\ldots,s_p}:=\frac1{p!}\sum_{\pi\in\mathfrak S_p}\Delta^2_{s_{\pi(1)},\ldots,s_{\pi(p)}}.
\end{equation}
Suppose that
\begin{align}
    \begin{cases}
        \widehat\Delta_t^2\quad\text{does not depend on }t\in\sS,
        \\
        \sum_{s_2,\ldots,s_p\in\sS}\widehat\Delta^2_{t,s_2,\ldots,s_p}\lambda_{s_2}\cdots\lambda_{s_p}\quad\text{does not depend on $t\in\sS$ for every $p\geq2$.}
    \end{cases}
\end{align}
Define
\begin{equation}

    \beta_p^2:=\sum_{s_1,\ldots,s_p\in\sS}\Delta^2_{s_1,\ldots,s_p}\lambda_{s_1}\cdots\lambda_{s_p}\quad\text{for $p\geq1$},\quad\text{and}\quad \xi_\star(r):=\sum_{p\geq1}\beta_p^2r^p=\xi(r\lambda)\quad \text{for $r\in\R_+$}.
\end{equation}
Then $\xi$ is balanced with respect to $\lambda$ in the sense of Definition~\ref{d.balanced_comparison_structure}.

