[Lemma 16 of arXiv:2608.15616, '\textbf{Compact Support Property of Super-Brownian Motion with Irregular Drift}'] Let $n\geq 1$ and let $(X^0, \ldots X^n)$ be a solution to \eqref{eq:SPDE_n} such that conditionally on $\mathcal{F}_\infty^{k-1}$,  $X^k$ is a solution to \eqref{eq:SPDE_k_gen} for $1\leq k \leq n$. Then, for any $1\leq k \leq n$ and any  $\psi^k, \phi^k\in \mcC_c^+(\R)$, it holds that 
		\begin{equation}
		\begin{split}
		&	\E\Big[\exp\Big(- \langle X^k_t, \phi^k \rangle - \int_0^t \langle X^k_s, \psi^k\rangle ds\Big)\Big| \mathcal{F}^{k-1}_\infty\Big] \\
		& \quad = \exp\Big(- \langle X_0^k, V_t(\phi^k, \psi^k)\rangle -\int_0^t\langle g_s^k, V_{t-s}(\phi^k, \psi^k) \rangle ds\Big), 
		\end{split}
		\end{equation} 
		where $V(\phi^k, \psi^k)$ is the solution to 
		\begin{equation*}
			\begin{split}
				&\partial_t V_t(x) = \frac{1}{2}\Delta V_t(x) - \frac{1}{2}(V_t(x))^2 + \psi^k(x), \quad t >0, x\in \R\\
				&V_0 \equiv \phi^k.
			\end{split}
		\end{equation*}

