[Prop lem-rewrite of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Fix $\beta\in(0,\infty)$. Let $ v\colon[0,\infty)\to (-\infty,\infty] $ be measurable and bounded from below, and let $ \Lambda\subset\mathbb{R}^d$ be measurable with finite volume (assumed to be a torus for periodic boundary condition). Then, for any $N\in\mathbb{N}$, and $ {\rm bc}\in\{{\rm per},0\} $,
\begin{equation}
	Z_N^{{{\scriptscriptstyle{({\rm bc}})}}}(\Lambda)
	={\operatorname e }^{\nu_{\Lambda}^{{{\scriptscriptstyle{({\rm bc}})}}}(\Lambda\times {\mathcal C }^{\ssup\circlearrowleft})}
	{{\tt Q}}^{{{\scriptscriptstyle{({\Lambda,\rm bc}})}}}\big[{\rm e}^{-\Phi_ {\Lambda,\Lambda}}\1\{{\mathfrak N}^{\ssup\ell}_\Lambda=N\}\big].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:RGP-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = \ell^2(\mathbb{Z})$.  The seed functions
$\psi_{t,r,n}$ and $\phi_{t,r,n}$ satisfy the linear
problem (equation eq:Linear-Psi-3 of the paper) and the adjoint
linear problem (equation eq:Linear-Phi-Prob of the paper) on
$\mathcal{V}$ with edge weights
$(c_k, \lambda_k)$.  Explicitly, for each fixed
$r \in \mathbb{Z}$:
\begin{align}
\psi_{t,r,n+1}
&= (1{-}\theta)^{-1}\psi_{t,r+1,n}
   - (1{-}\theta)^{-1}\theta\psi_{t,r,n},
 \\
\psi_{t-1,r+1,n}
&= p^{-1}\psi_{t,r+1,n}
   - q\theta p^{-1}\psi_{t,r,n},

\end{align}
and
\begin{align}
\phi_{t,r+1,n}
&= (1{-}\theta)^{-1}\phi_{t,r,n+1}
   - (1{-}\theta)^{-1}\theta\phi_{t,r+1,n+1},
 \\
\phi_{t,r+1,n}
&= p^{-1}\phi_{t-1,r+1,n}
   - q\theta p^{-1}\phi_{t-1,r+2,n}.

\end{align}

[Cor sig:gam of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] If Assumptions \mbox{\normalfont  (asum:ic of the paper)}, \mbox{\normalfont  (asum:lip of the paper)} and \mbox{\normalfont  (asump:super of the paper)} to \mbox{\normalfont  (asum:liningam of the paper)}  hold,
		 then for  $ 0\leq p_0\leq {\bar p}/{(\eta+1)}$
		\begin{align*}
E|(\widehat b)_{tam}^{\displaystyle{n}}\big(x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)}\big)|^{p_0}+E|(\widehat\sigma)_{tam}^{\displaystyle{n}}\big(x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)}\big)|^{p_0}+\int_Z E|(\widehat\gamma)_{tam}^{\displaystyle{n}}\big(x_{\kappa_n(s)}^{i,N,n},\mu^{x,N,n}_{\kappa_n(s)}, \bar z\big)|^{p_0} \nu(d\bar z) \leq& K
		\end{align*}
		 for any   $s\in[0,T]$ and $i\in\{1,\ldots,N\}$   where $K>0$ is independent of $N$ and $n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:local-dissipation-at-a of arXiv:2411.01364, 'Global Dynamics of Granular Media Equations via Stochastic Order'] Assume that $W(x)=\frac{\theta}{2}x^2$ and the confining potential function $V\in C^2(\mathbb R;\mathbb R)$ satisfy the following conditions:
    \begin{enumerate}
        \item [(i)] There exists $a\in \mathbb{R}$ such that $V'(a)=0$ and $V''(a)>0$;
        \item [(ii)] $\liminf_{|x|\to\infty}\frac{V'(x)}{x|x|^{\delta}}>0$ for some $\delta>0$.
    \end{enumerate}
    Then, there exists $r_a > 0$ such that for any $0 < r \leq r_a$, there are $\theta_r > 0$ and $\sigma_r > 0$ such that for all $\theta \geq \theta_r$ and $\sigma^2(x) \leq \sigma_r$ for all $x \in \mathbb R$, the equation (equation eq:mvsystem of the paper) is locally dissipative at $a$ with radius $r$.

