body:
[Theorem thm:poisson of arXiv:2608.28169, 'characteristic polynomial of self-normalized random matrices'] Let $\big(N_{-,\ell}\big)_{\ell\geqslant 1}$ and $\big(N_{+,\ell}\big)_{\ell\geqslant 1}$ be two i.i.d.\ sequences of independent random variables  with $N_{-,\ell}$ following a Poisson $\mathcal{P}\big(\frac{1}{2\ell}\big)$ distribution. Define 
    \begin{equation*}
        Z_k^{(0)} = \sum_{\ell | k} \ell  (N_{+,\ell } + (-1)^{k/\ell } N_{-,\ell }) \,, \qquad k\geqslant 1\,.
    \end{equation*}
    For integers $k_1,\ldots, k_\ell\geqslant 1$, we then have the convergence of traces
        \begin{equation}
        \left(\operatorname{Tr} \left[ {\mathbf Y}^{k_1}_n \right], \dots, \operatorname{Tr} \left[ {\mathbf Y}^{k_\ell}_n \right] \right) \stackrel{\rm d}{\rightarrow} \left(Z_{k_1}^{(0)}, \dots, Z_{k_\ell}^{(0)} \right) \,,\qquad n\to\infty\,,
    \end{equation}
    and the following convergence in distribution  of characteristic polynomial $p_n$ for the topology of local uniform convergence in $\mathbb{D}$:
    \begin{equation*}
        p_n \stackrel{\rm d}{\rightarrow} F_0 \,, \qquad n\to\infty\,,
    \end{equation*}
    where $F_0$ is the random holomorphic function 
    \begin{equation}

        F_0(z) = \exp \left( - \sum_{k \geqslant 1} \frac{z^k}{k} Z_k^{(0)} \right) .
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem load-balancing-gap of arXiv:2505.04942, '\textbf{Randomized Routing to Remote Queues}'] Assume the conditions of Theorem~(theorem:load-balancing of the paper) hold. If conditions~(equation eq:fourth-moments of the paper) and (equation eq:log-log-n-bound of the paper) also hold, then there exist two positive numbers $ C $ and $ C' $ such that with probability 1,
	\begin{equation}
		\sup_{0 \leq t \leq T} \max_{k,\ell = 1, \ldots, s} | \tilde{L}_{n,k}(t) - \tilde{L}_{n,\ell}(t) | < \max \Big\{ C \chi_{n}, C' \frac{\log \log n + \log (n \chi_{n}^{2})}{\sqrt{n} \chi_{n}} \Big\}
	\end{equation}
	for $ T > 0 $ and $ n $ sufficiently large. If condition~(equation eq:fourth-moments of the paper) holds and $ \lim_{n \to \infty} \sqrt{n} \chi_{n}/\log \log n = \infty$, then with probability 1,
	\begin{equation}
		\lim_{n \to \infty} \sup_{0 \leq t \leq T} \max_{k,\ell = 1, \ldots, s} | \tilde{L}_{n,k}(t) - \tilde{L}_{n,\ell}(t) | = 0.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 31 of arXiv:2608.13976, 'Boundary Harnack principle for diffusion with jumps on metric measure spaces'] For each $R>0,$
 there is a constant  $C=C(d, R)>0$  such that for any $r\in (0, R)$ and $t>0,$
\begin{equation}
\P_x(\tau^b_{B(x,r)}\leq t)\leq  C   t/r^2  \quad \mbox{for every} \quad x\in \R^d.
\end{equation}
Consequently,  ${\bf (EP)} _{\leq, R, \gamma}$   holds  with  $\gamma=2.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

