body:
[Theorem 56 (Defect-energy transfer for the Hilbert--Schmidt primitive) of arXiv:2608.04993, '2608.04993'] Let $Y:\Omega_H\to C([0,T];H)$ be a total Borel raw-causal map whose
sample paths have finite variation, put $D:=X-Y$, and define
\begin{align}
 J_t^Y&:=Y_t\otimes X_t-\int_0^t\dd Y_r\otimes X_r,
 \\
 Q_t^Y&:=X_t^{\otimes2}-J_t^Y-(J_t^Y)^*.

\end{align}
For $q\ge2$ set
\begin{align}
 \mathfrak d_q(Y)
 &:=\sup_{P\in\Smax}
 \left\|\left(\int_0^T\|X_r-Y_r\|_H^2\,\dd r\right)^{1/2}\right\|_{L^q(P)},
 \\
 \mathfrak d_q(Y,\widetilde Y)
 &:=\sup_{P\in\Smax}
 \left\|\left(\int_0^T\|Y_r-\widetilde Y_r\|_H^2\,\dd r\right)^{1/2}\right\|_{L^q(P)}.

\end{align}
Then $J^Y$ and $Q^Y$ are total Borel continuous-path fields satisfying the
exact stopping identities
\begin{equation}
 J_t^Y(r_sx)=J_{t\wedge s}^Y(x),
 \qquad
 Q_t^Y(r_sx)=Q_{t\wedge s}^Y(x)
 \qquad(s,t\in[0,T]).
\end{equation}
In particular, they are raw causal as path-valued maps.
Under every $P\in\Smax$, let $\mathcal E^P$ be the transform in
\eqref{eq:defect-error-transform}.  Then, up to indistinguishability,
\begin{align}
 J^Y-J^P&=-\mathcal E^P(D),
 \\
 Q^Y-\qv{M^P}
 &=\mathcal E^P(D)+\mathcal E^P(D)^*.

\end{align}
Moreover,
\begin{equation}
 \sup_{P\in\Smax}\left(
 \|J^Y-J^P\|_{\mathbb S^q(P;\mathcal S_2)}
 +\|Q^Y-\qv{M^P}\|_{\mathbb S^q(P;\mathcal S_2)}\right)
 \le C\bigl(\sqrt{q\Lambda}+B\sqrt T\bigr)\mathfrak d_q(Y),
\end{equation}
and for any two such regularizations,
\begin{equation}
 \sup_{P\in\Smax}\left(
 \|J^Y-J^{\widetilde Y}\|_{\mathbb S^q(P;\mathcal S_2)}
 +\|Q^Y-Q^{\widetilde Y}\|_{\mathbb S^q(P;\mathcal S_2)}\right)
 \le C\bigl(\sqrt{q\Lambda}+B\sqrt T\bigr)
       \mathfrak d_q(Y,\widetilde Y).
\end{equation}
Here $C$ is numerical and independent of $H,P,q$ and the regularizations.
Thus $\mathfrak d_q(\cdot,\cdot)$ is an upper-energy pseudometric on
regularizations modulo zero $\mathfrak d_q$-distance, and the
$C([0,T];\mathcal S_2)^2$ primitive reconstruction is Lipschitz for this
pseudometric in the upper-$L^q$ seminorm
\[
 \sup_{P\in\Smax}
 \|\,\cdot\,\|_{L^q(P;C([0,T];\mathcal S_2)^2)}
\]
before any limiting scheme is chosen.

