[Proposition 6 of arXiv:2604.07275, 'Some probabilistic properties and time-changed versions of a renewal process based on Mitt'] For a fixed $t > 0$, we have 
		\begin{equation*}
			\frac{\big(\hat{N}_{\alpha}(t)\big)^r}{\mathbb{E}\big( \hat{N}_{\alpha}(t) \big)^r} 
			\xrightarrow[\lambda \to \infty]{\ \ \mathrm{\Pr}\ \ } 1, \ \ r \ge 1, \ \text{$0<\alpha\le 1$}.
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:CLE4-thin of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $\alpha\in(0, 1)$. Consider $\mathds A_{-2\lambda, 2\lambda}$ in a valid domain $D$ and index its loops by decreasing size of diameter. For any continuous, bounded  function $f:\mathbb C\to\mathbb R$,
    \begin{equation}
        (:\! \sin(\alpha\phi) \!: , f) = \lim_{N\to\infty}\sum_{k=1}^N\xi_k(:\! \cos(\alpha(\phi_k^\mathds A+\xi_k(\pi-a_c))) \!: , f),
    \end{equation}
    where the limit is in $L^2(\mathbb P)$,  $(\xi_k)_{k\geq1}$ are the i.i.d. labels of the loops, and $(\phi^\mathds A_k)_{k\geq1}$ are independent GFFs inside each loop.

