[Lemma lem:W=landscape of arXiv:2605.26048, 'Classification of the eternal solutions and multiple coalescing shocks in the KPZ fixed po'] [Busa-Sepp-Sore-22a]
    For all $\xi \in \mathfrak{X}$ and $s_1 < s_2 \le t$, we have that 
    \begin{equation} 
\mathcal{L}(y_1,s_1;y_2;s_2) = W^\xi(y_1,s_1;y_2,s_2), \quad\text{ where }  y_i = g_{(x,t)}^{\xi,L/R}(s_i).
\end{equation}
In general, for $\xi \in \mathfrak{X}$, $s_1 < s_2$, and $y_1,y_2 \in \mathbb{R}$,
\begin{equation} 
\mathcal{L}(y_1,s_1;y_2;s_2) \le  W^\xi(y_1,s_1;y_2,s_2)
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop proba ineq coupling map of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $W$ be a measurable subset of $\mathcal W_T$, and let
\begin{equation*}
	U=\{\underline u\in \widetilde{\mathcal{W}}_n^N\ |\ \Psi_{N,n,T}(\underline u)\subseteq W\}.
\end{equation*}
Then,\footnote{Note that the factor in~(equation eq: proba ineq coupling map of the paper) is simpler than the corresponding one in [daures2025]. This is because our stitching map allows empty words as input.}
\begin{equation}

	 \mathbb P^{\otimes N}(U)\leqslant\big(c_K^r(\tau_K+1)^r(n+1)^{2r+1}\big)^{N}\mathbb P (W).
\end{equation}

