body:
[Prop periodicAttractiveLowerBounds of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Assume $\mathsf{d}\ge11$. Then:
\begin{enumerate}[(i)]
\item At the stability threshold,
\begin{align}
\liminf_{N\to\infty}
N^{-\mathsf{d}/2}{\mathsf{K}}_{N,\beta_{\mathrm{s}}(\mathsf{d})}(\mu_{\mathrm{unif}})
\ge
\left(\frac{\sqrt\pi}{e}\right)^\mathsf{d}.
\end{align}
\item For every $\beta_{\mathrm{s}}(\mathsf{d})<\beta<2\mathsf{d}$,
\begin{align}
\liminf_{N\to\infty}
\frac1N\log{\mathsf{K}}_{N,\beta}(\mu_{\mathrm{unif}})>0.
\end{align}
\item For every $\beta\ge2\mathsf{d}$ and every $N\ge2$,
\begin{align}
{\mathsf{K}}_{N,\beta}(\mu_{\mathrm{unif}})=+\infty.
\end{align}
\end{enumerate}

