[Corollary 12 of arXiv:2608.30859, 'Conservation Laws with Discontinuous Flux:\\ A First Application to Traffic Flow'] Let $y(t)$ be the solution to the Cauchy problem \eqref{eq:Yode}. Then
    \begin{align}
        \dot y(0+) = \lim_{\substack{t \to 0+ \\ y \ge g^\prime(u^+)t}} H(t, y(t))= \frac{f(u^-)-g(u^+)}{u^--u^+}=:\lambda> g^\prime(u^+).
    \end{align}

[Corollary of arXiv:2412.04334, 'Fractional counting process at L\'{e}vy times and its applications'] Let the random variables $\{Y_i, i\in \mathbb{N}\}$  are absolutely continuous with  pdf $f_y(\cdot)$, then the probability law of $Z(t),\;t\geq 0$  has the following absolutely continuous and discrete component\\
    (i) the absolutely continuous component is given by
   \begin{equation*}
    h_{Z}(y,t) =  \mathit{\Gamma } ( \vartheta )\sum_{m=1}^{\infty}\frac{\lambda_{\theta}^m(\zeta )_m}{m!}\sum_{l=0}^{\infty}\frac{(\zeta  + m)_{l}(-\lambda_{\theta})^l}{l! \mathit{\Gamma } (\mu (l+m)+ \vartheta )}\mathbb{E}\left[(H(t))^{\theta(l+m) }\right]f_{Y}^{(m)}(y),
\end{equation*}
where $f_{Y}^{(m)}(\cdot)$ is the m-fold convolution of $f_{Y}(\cdot)$.\\
(ii) the discrete component of the probability law is
\begin{align*}
    \mathbb{P}\left[Z(t)=0\right] &= \sum_{n=0}^{\infty}\mathbb{P}\left[ \mathcal{X}_{\mu, \vartheta }^{\zeta ,\theta}(n)= 0\right]\mathbb{P}\left[ H(t) = n\right]\\
    &=  \sum_{n=0}^{\infty}\mathit{\Gamma } ( \vartheta )E_{\mu, \vartheta }^{\zeta }(-\lambda_{\theta}n^{\theta})\mathbb{P}\left[H(t) = n\right],
\end{align*}
where 
\begin{align*}
    \mathbb{P}\left[ \mathcal{X}_{\mu, \vartheta }^{\zeta ,\theta}(t)= 0\right] &=  W_{X}(0,t) -  W_{X}(y,t),\;\;\; y<0\\
    &= \mathit{\Gamma } ( \vartheta )E_{\mu, \vartheta }^{\zeta }(-\lambda_{\theta}t^{\theta}).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2608.10415, 'Continuous random variables'] Let $A$ be a $C^*$-algebra, given with a positive trace $tr:A\to\mathbb C$.
\begin{enumerate}
\item The elements $a\in A$ are called random variables.

\item The moments of such a variable are the numbers $M_k(a)=tr(a^k)$.

\item The law of such a variable is the functional $\mu_a:P\to tr(P(a))$.
\end{enumerate}

[Theorem thm:matrix_azuma-gtp of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $(\mathcal{Y},\hat\mathcal{Z},T)$ be a sequential gamble space, $T\in\mathbb{N}$, satisfying Condition~(cond:usa-minimax of the paper).
  Consider sequences $\{X_k:\mathcal{Y}^k\to \mathrm{SA}_d\}$ and $\{A_k\in\mathrm{SA}_d\}$ satisfying
  \begin{align*}
    \textsf{\textbf{E}}[ X_k \mid s ] = 0 \text{ for all } s\in\mathcal{Y}^{k-1}, \quad \text{and} \quad X_k^2 \preceq A_k^2 \quad \text{g.t.a.s.}
  \end{align*}
  Let \(\sigma^2 := \left\| \sum_k A_k^2 \right\|\).
  Then, for all $t \geq 0$,
  \begin{align*}
    \overline{\textsf{\textbf{P}}}\left[ \lambda_{\max} \left( \sum_k X_k \right) \geq t \right] \leq d \cdot e^{-t^2 / 8\sigma^2}~.
  \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 7 (The burglar Drivers) of arXiv:2609.03968, 'A one-parameter family of local-time conditioned processes : the generalized Brownian burg'] Let $\nu\in\R$, and let $z,z_0\in\overline\R=\R\cup\{\pm\infty\}$. The \emph{burglar Driver} of parameter $\nu$, starting from $z$ and targeting $z_0$, is the continuous diffusion on $\overline \R$ which satisfies $D_0 = z$, evolves according to the SDE
\begin{equation}

\dd D_t = \exp\left(\cosh(D_t)\right)\dd B_t+ \exp\left(2\cosh(D_t)\right)(1-\nu)\sign(D_t-z_0)\dd t.
\end{equation}
for $B$ a usual Brownian motion, and is instantly reflected at the boundaries $\pm\infty$. In the case of a boundary target $z_0=\pm\infty$, we stop it at the time $T(D):=\inf\{t\geq 0, D_t = z_0\}$, and otherwise let it run until $T(D)=+\infty$, which corresponds to the final time of the driver $D$ for the target $z_0$ as defined in Lemma \ref{lemmatech}.

