[Proposition 13 of arXiv:2608.29143, 'Least Variability in a Polynomial-Square Class\\ of Rational Kernels'] Let $a_*$ be an optimizer of the closed problem.
\begin{enumerate}[label=\textup{(\roman*)}]
\item If $\deg a_*=m-1$, then there exists $j\in\{1,\ldots,m\}$ such that
\begin{align*}
 R_*(t)=(t-x_{j,m+1})(t-x_{j+1,m+1})
\end{align*}
and
\begin{align*}
 a_*(t)=C\frac{\Lag_{m+1}(t)}
 {(t-x_{j,m+1})(t-x_{j+1,m+1})}.
\end{align*}
\item If $\deg a_*=m$, then there exists $j\in\{1,\ldots,m+1\}$ such that
\begin{align*}
 R_*(t)=(t-x_{j,m+2})(t-x_{j+1,m+2})
\end{align*}
and
\begin{align*}
 a_*(t)=C\frac{\Lag_{m+2}(t)}
 {(t-x_{j,m+2})(t-x_{j+1,m+2})}.
\end{align*}
\end{enumerate}

[Definition eq:ingdef of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] For ${\boldsymbol \sigma}, {\boldsymbol \tau}\in \mathcal S_{\mb{n}}$ and $L>0$, define the integral 
\begin{equation} 
    \mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}}
    =  \frac{1}{(2\pi \mathrm{i})^{|{\boldsymbol \sigma}|+|{\boldsymbol \tau}|}} \int \mathrm{d} \boldsymbol{\xi}^{{\boldsymbol \sigma}} \int \mathrm{d} \boldsymbol{\eta}^{{\boldsymbol \tau}} \, 
    \Pi^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}}(\boldsymbol{\xi}, \boldsymbol{\eta}) {\mathsf{F}}_{L}^{{\boldsymbol \sigma}|{\boldsymbol \tau}} (\boldsymbol{\xi}, \boldsymbol{\eta}) 
\end{equation}
where the contour for $\boldsymbol{\xi}^{{\boldsymbol \sigma}}$ is a product of $|{\boldsymbol \sigma}|$ small circles centered at $-1$, nested from inside to outside, 
and the contour for $\boldsymbol{\eta}^{{\boldsymbol \tau}}$ is a product of $|{\boldsymbol \tau}|$ small circles centered at $0$, also nested from inside to outside. All circles are mutually disjoint.

[Prop FunL-presentable of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] If ${\mathcal{D}},{\mathcal{E}}$ are $T$-presentable, then so is $\ul{\textup{Fun}}_T^\textup{L}({\mathcal{D}},{\mathcal{E}})$.
    \begin{proof}
        If ${\mathcal{D}}\simeq\ul\PSh_T({\mathcal{D}}_0)$, then $\ul{\textup{Fun}}_T^\textup{L}({\mathcal{D}},{\mathcal{E}})\simeq\ul{\textup{Fun}}_T({\mathcal{D}}_0,{\mathcal{E}})$ by Theorem~(thm:univ-prop-PSh of the paper), and so the claim is an instance of [martiniwolf2022presentable]*{Corollary 2.4.2.7}.

        In the general case, we use [martiniwolf2022presentable]*{Remark 2.4.4.12} to find a pushout
        \[
            \begin{tikzcd}
                {\mathcal{A}}\arrow[r, "f"]\arrow[dr,"\ulcorner"{very near end},phantom]\arrow[d,"p"'] & {\mathcal{B}}\arrow[d,"q"]\\
                {\mathcal{C}}\arrow[r,"g"'] & {\mathcal{D}}
            \end{tikzcd}
        \]
        in $\textup{Pr}^{\textup{L}}_{T}$ such that ${\mathcal{A}},{\mathcal{B}},{\mathcal{C}}$ are presheaf categories. Taking ${\textup{Hom}}\big(-,\ul{\textup{Fun}}({\mathpalette\ulhelper{A}}\hbox{\rule[-2pt]{0pt}{0pt}}\times[n],{\mathcal{E}})\big)$ for varying $A\in T$ and $n\ge 0$ we then arrive at a pullback
        \[
            \begin{tikzcd}
                \ul{\textup{Fun}}_T^\text{L}({\mathcal{D}},{\mathcal{E}})\arrow[r,"g^*"]\arrow[d,"q^*"'] & \ul{\textup{Fun}}^\text{L}({\mathcal{C}},{\mathcal{E}})\arrow[d,"p^*"]\\
                \ul{\textup{Fun}}_T^\text{L}({\mathcal{B}},{\mathcal{E}})\arrow[r,"f^*"'] & \ul{\textup{Fun}}_T^\text{L}({\mathcal{A}},{\mathcal{E}})
            \end{tikzcd}
        \]
        in $\CAT_T$. By the above special case, all objects except possibly the top left one are presentable; moreover, $f^*$ and $p^*$ are cocontinuous since ${\textup{Fun}}^\text{$T$-cc}({\mathcal X},{\mathcal Y})\subset{\textup{Fun}}({\mathcal X},{\mathcal Y})$ is closed under $T$-colimits for any $T$-cocomplete ${\mathcal X},{\mathcal Y}$ by [martiniwolf2022presentable]*{Lemma 2.6.1.3}. The claim now follows since $\textup{Pr}^{\textup{L}}_{T}\hookrightarrow\CAT_T$ preserves small limits by [martiniwolf2022presentable]*{Proposition 2.4.4.10}.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 (Differentiability of $\bar F_N$) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $N \in \N$ and let $\bar F_N$ be given as in~\eqref{e.F_N(t,q)=}. We have for every $t,t' \in \R_+$ and $q,q' \in \mcl Q_\infty^\sS$ that 
\begin{equation*}
\Ll|\bar F_N(t,{q}) - \bar F_N(t',{q'})\Rr|\leq \Ll|{q}-{q'}\Rr|_{L^1} + |t-t'| \, \sup_{|a| \le 1} |\xi(a)|.
\end{equation*}
In particular, the free energy in~\eqref{e.F_N(t,q)=} can be extended by continuity to $\R_+\times\mcl Q_1^\sS$.
Moreover, the restriction of the function $\bar F_N$ to $\R_+ \times \mcl Q_2^\sS$ is Gateaux differentiable everywhere, jointly in its two variables. We denote its Gateaux derivative in $q$ by $\dr_q \bar F_N(t,q) = \dr_q \bar F_N(t,q, \cdot) \in L^2([0,1]; \R^\sS)$. For every $t \ge 0$ and  $q \in \mcl Q_2^\sS$, we have
\begin{equation}

\partial_q \bar F_N(t,q) \in \mcl Q^\sS_{\infty,\leq \lambda_N}, \end{equation}
and, for every $q \in \mcl Q_\infty^\sS$  and $\pi \in L^2([0,1]; \R^\sS)$,
\begin{equation}

\begin{split}
    \la \pi,\dr_q \bar F_N(t,{q})\ra_{L^2} &= \E \la \pi \Ll(\alpha\wedge\alpha'\Rr)\cdot R_N(\sigma,\sigma')\ra_N.
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 14 of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] There exist absolute constants $\delta_0, \nu >0$ such that the following holds for every $\delta \leq \delta_0$.
	Consider $x_0,y \in D$ with $\dgeo(x_0, y) \geq (4/5) r_\delta$.
	Then, there exists $z\in \cD(\delta)$ with $\Vert z - x_0 \Vert \leq (4/5) r_\delta$ satisfying that $\sB(z,\nu r_\delta)\subseteq \cD(\delta)$ and
	\begin{align}
		\dgeo(\zeta, y) \leq \dgeo(x_0, y) -  r_\delta/10 \ \text{ for every } \ \zeta \in \sB(z,  \mu r_\delta).  
	\end{align}

