[Theorem 10 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] Let $(M(t), \covm (t))_{t \geq 0}$  be   an extended  Kalman filter for problem \eqref{FiltPb} such  that  $M$  and $ \qcovm= \frac{1}{\eps }\covm$
			satisfy  \eqref{EKF1}  and \eqref{EKF2}  respectively,  and  in  addition 

				\begin{enumerate}[ wide, labelwidth=!, labelindent=0pt]
					\renewcommand{\labelenumi}{(A\theenumi)} 				
					\item   The  variable $\qcovm^{-1/2}(0) (\sig(0)-M(0))$  is  of  order $\sqrt{\eps}$.
					\item  The functions  $\sigma$, $\coDifS$  and $\coDifO$  are  bounded.
					\item  The  function $f$ and $h$  are  $\mathcal{C}^1$  and   almost  linear with  respect  to  the  signal.
					\item  
					\hspace*{-3mm}
					\begin{tabular}[t]{l}The    function $h$   is   strongly injective with  respect  to  the  signal,\\ $\af= \sigma \sigma^\top - \coDifS(I-\coDifO^\top(\coDifO\coDifO^\top)^{-1} \coDifO)\coDifS^\top$   and $(\coDifO\coDifO^\top)^{-1}$ are uniformly  elliptic, and \\   the quotient   between  the largest   and  the  smallest eigenvalues  of  $\qcovm (0)$   is  bounded.
					\end{tabular}	
				\end{enumerate}

				\noindent	Then   $\qcovm^{-1/2}(t) (\sig(t)-M(t))$  is  of  order $\sqrt{\eps}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 41 of arXiv:2607.19873, 'Local limit theorem for the operator norm of products of random matrices'] Assume that $\Gamma_{\mu}$ is strongly irreducible and that $\mu$ admits a finite exponential moment \eqref{Exponential-moment}. 
Then, for any $\ee >0$, there exist constants $a, c  >0$ such that for any $n \geq 1$ and any $g \in G $, 
\begin{align*}
& \bb P \Big( \|g g_n \cdots g_1\| \leq  e^{-\ee n} \|g\| \|g_n \cdots g_1\| \Big) \leq  c e^{- a n},  \notag\\
& \bb P \Big( \|g \pi_{g_n \cdots g_1} \| \leq  e^{-\ee n} \|g\| \|\pi_{g_n \cdots g_1}\| \Big) \leq c e^{- a n}. 
\end{align*}

[Theorem DefStatewiseCondExpect0 of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] For  $Y \in \mathbb{Y}$, let  $Y^i$, $i \in \mathcal{Z}$, be defined by (equation DefOfYi of the paper). 
		For given stochastic processes $E^i$, $i \in \mathcal{Z}$, the two following statements are equivalent:
		\begin{itemize}
			\item[(i)]  The multivariate process  $(E^i)_{i \in \mathcal{Z}}$ satisfies $E^i(t)= \mathbb{E}_{t}^i[Y(T)-Y(t)]$ for $t \in [0,T]${.}
			\item[(ii)]  The multivariate process  $(E^i)_{i \in \mathcal{Z}}$ is a solution of  $\mathcal{Y}(\Lambda)$ for the backward equation
			\begin{align} \begin{split}
					0=\mathds{1}_{\{  \Lambda^{i\raisebox{-0.25ex}{\scalebox{1.4}{$\cdot$}}}(t-)< \infty\}} I^i(t-)  \bigg( E^i(\mathrm{d} t)   +  Y^i(\mathrm{d} t) + \sum_{j : j\neq i}(Y^{j}(t)-Y^i(t)+ E^j(t)-E^i(t)) \Lambda^{ij}(\mathrm{d} t)\bigg)
			\end{split}\end{align}
		 with terminal value $E^i(T)=0$. 
		\end{itemize}
		If for a  subset $\mathcal{Z}_0 \subset \mathcal{Z}$ we have $\Lambda^{ij}=0$ for all $i \in \mathcal{Z}_0$ and $j \not\in \mathcal{Z}_0$, then the equivalence is also true for the sub-process $(E^i)_{i  \in \mathcal{Z}_0}$ only. (Proof in the paper; no proof environment follows the statement in the TeX.)

