   \begin{align}
   \E[|f(X^h_{\tau^h_t})(g(X^h_t)-g(X^h_{\tau^h_t}))|]\le C h^{\frac 1\alpha}(\tau^h_t)^{-\frac d{\alpha p}}\|f\|_{L^p}\|\nabla g\|_{L^\infty}.
\end{align}
\begin{align}
   |\E[f(X^h_{\tau^h_t})(g(X^h_t)-g(X^h_{\tau^h_t}))]|\le C\|f\|_{L^p}\left(h^{1-\frac 1\vartheta}(\tau^h_t)^{-\frac{2d}{\alpha p}}\|b\|_{L^\vartheta-L^p}\|\nabla g\|_{L^\infty}+h(\tau^h_t)^{-\frac d\alpha(\frac 1{\vrho}+\frac 1 p)}\|\Delta^{\frac \alpha 2} g\|_{L^{\vrho}}\right)
 ,
