[Proposition prop:Doeblin of arXiv:2411.03984, 'Diffusion of the Random Lorentz Process in a Magnetic Field'] \begin{enumerate}[label = (\roman*)]
   \item The distribution
     \begin{align}
       (\zeta_{n},\theta_n) \sim (\wh{\zeta},\wh{\theta}),
     \end{align}
     where $\wh{\zeta}$ and $\wh{\theta}$ are independent random variables distributed as $\wh{\zeta} \sim {\tt TRUNCEXP}(1,\-2\pi)$ and $\wh{\theta} \sim {\tt UNI}[0,2\pi]$, is stationary for the Markov chain $(\zeta_n,\theta_n)$.
   \item Moreover, D\"oblin's condition holds: There exists a $\delta>0$ such that for any measurable subset $A\subset [0,2\pi) \times[0,2\pi)$
\begin{align}

\condprobab
{(\zeta_{n+1}, \theta_{n+1}) \in A}
{(\zeta_n, \theta_n)} 
\geq 
\delta 
\probab{(\wh \zeta, \wh \theta)\in A}, 
\end{align}
uniformly in the condition $(\zeta_n , \theta_n) \in [0,2\pi)\times [0,2\pi)$. In particular, the distribution (equation statimeasure of the paper) is the unique stationary measure of the Markov chain $(\zeta_n,\theta_n)$.
\end{enumerate}

[Lem lemlwp1 of arXiv:2608.30777, 'Inhomogeneous nonlinear Schr\"odinger equation \\ in Fourier-Lebesgue and modulation space'] Let $\alpha \in (1,5-2b),\, 0<b\leq 1/4$ and $p_{0}$  be as follows 
     \begin{gather*}
2>p_{0}>\begin{cases}
\vspace{0.2cm}
\max \left( \frac{\alpha+1}{\alpha}, \frac{4\alpha}{9-4b} \right) &\text{if} \quad \alpha \in  (1,3) \\ 
\vspace{0.2cm}
\max \left( \frac{2(\alpha-1)}{\alpha}, \frac{2\alpha}{5-2b} \right) \quad  & \text{if} \quad \alpha\in [3,5-2b).
\end{cases}
    \end{gather*}
    Then
    \begin{align*}
   \inf_{(\gamma,\rho)\in \mathcal{A}}\| ~|x|^{-b}|u|^{\alpha-1}v\|_{L^{\gamma'}_{T}L^{\rho '}}
   &\lesssim \|u\|_{X(T)}^{\alpha-1}\|v\|_{X(T)}
   \left(
     T^{1-\frac{\alpha-1}{2p_{0}}-\frac{1}{2}\left(\frac{1}{p_{0}}-\frac{1}{2}\right)} 
     + T^{1-\frac{\alpha-1}{2p_{0}}-\frac{1}{2}\left(\frac{1}{p_{0}}-\frac{1}{2}\right)-\frac{1}{\nu}}
\right).
\end{align*}

