body:
[Definition def:F-FPE of arXiv:2607.00800, 'Brownian motion in Minkowski normed spaces'] Let $z\in \mathbb{R}^d$.
    We say that $u: (0,\infty)\times \mathbb{R}^d \to [0,\infty)$ is a \emph{probability solution} to (equation eq:NL-FPE of the paper) with initial datum $z$ if $u(t):=u(t,\cdot) \in \mathfrak{C}$ for all $t >0$ and
    \begin{enumerate}[(i)]
        \item $u(t,x) \,\mathrm d x \in \mathcal P$ for all $t>0$, $t\mapsto u(t,x) \,\mathrm d x$ is weakly continuous on $(0,\infty)$, and $u(t,x) \,\mathrm d x \to \delta_z$ weakly as $t \to 0$;
        \item For each $T>0$, the maps $(t,x) \mapsto a_{ij}(x,u(t))$ and $(t,x) \mapsto b_i(x,u(t))$ belong to $L^1([0,T]\times \mathbb{R}^d; u(t,x) \,\mathrm d x \mathrm d t)$;
        \item For all $\varphi \in C^2_c(\mathbb{R}^d)$ and $t>0$,
        \begin{align*}
            &\int_{\mathbb{R}^d} \varphi(x) u(t,x) \,\mathrm d x - \varphi(z) 
            \\&= \int_0^t \int_{\mathbb{R}^d} \Bigl(a_{ij}\bigl(x,u(r)\bigr) \partial_{ij}\varphi(x) + b_i\bigl(x,u(r)\bigr) \partial_i \varphi(x) \Bigr) u(r,x) \,\mathrm d x \mathrm d r.
        \end{align*}
    \end{enumerate}

[Proposition 38 of arXiv:2608.27630, 'Oriented planar maps and \\ annular mating of trees'] Let $a,b>0$, and $Z=(L,R)$ be a sample from 
     $a B^{\gamma, \bH}_{0, -a+ib}$ of (random) duration $T$ such that $L_T=-a$. Let $L_{\mathrm{inf}}=\inf_{0\leq u\leq T}L_u$, and $c$ be sampled from the uniform probability measure on $(-L_{\mathrm{inf}}-a,-L_{\mathrm{inf}})$. Let $\tau = \inf\{u\in[0,T]:L_u=-c\}$. Let $Z^1 = Z|_{[0,\tau]}+c$ and $Z^2(t) = Z(t+\tau)-Z(\tau)$ for $t\in[0,T-\tau]$. Then for some constant $C_\gamma>0$ depending only on $\gamma$, $(Z^1,Z^2) = ((L^1,R^1),(L^2,R^2))$ has the joint law 
    \begin{equation}
          C\int_0^\infty \int_0^\infty \mathds{1}_E\big(B_{c,id}^{\gamma,\bbR_+^2}\times B^{\gamma,\bC}_{0,(c-a)+(b-d)i}\big)\,\d d\,\d c,
    \end{equation}
    where   $$E=\{L_{T_2}^2- \inf_{t\in [0,T_2]} L_t^2< c \}\cap \{-\inf_{t\in[0,T_2]}R_t^2\leq d \}; \ \ T_2 \text{ is the duration of }Z^2.  $$

