body:
[Definition 2 (Fake stationary regime of type I and II (see. \cite{Pages2024})) of arXiv:2608.31099, '\bf On (fake) Stationarity in Stochastic Volterra Equations with Affine Drift and Regular '] .
	\begin{enumerate}
		\item The process $(X_t)_{t\ge 0}$ starting from $X_0\!\in L^2(\P)$,  exhibit a fake stationary regime of type I if:
		\begin{equation}
			\forall\, t\ge 0, \quad	\mathbb{E}[X_t] = m_0, \quad \text{Var}(X_t) = v_0 \geq 0, \quad \text{and} \quad \bar{\sigma}^2(t) = \mathbb{E}[\sigma^2(X_{t})]=\bar \sigma^2_0 \geq 0.
			\vspace{-.1cm}
		\end{equation}
		\item The process $(X_t)_{t\ge 0}$ starting from $X_0$ 
		has a fake stationary regime of type II if \( (X_t)_{t \geq 0} \) has the same marginal distribution, i.e., \( X_t \overset{d}{=}X_0 \) for every \( t \geq 0 \).
	\end{enumerate}
	\vspace{-.1cm}

[Lemma 6 (see {\cite[Lemma~2.1) of arXiv:2608.03922, 'Absolute continuity of two-dimensional polynomial random vectors'] {KosZh}}]
Let $\alpha\in(0,1]$ and let $\nu$ be a probability Borel measure on $\mathbb R^k$.
Then the estimate
\begin{equation}
\nu(A)\le C\bigl(\lambda_k(A)\bigr)^\alpha
\end{equation}
for every Borel set $A\subset \mathbb R^k$ is equivalent to the estimate
\begin{equation}
\int_{\mathbb R^k}\psi\,d\nu\le C\|\psi\|_{L^1(\mathbb R^k)}^\alpha
\end{equation}
for every $\psi\in C_0^\infty(\mathbb R^k)$ with $0\le\psi\le 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t:suboptimal_Lq_finite_time of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Fix $r\in (1,\infty)$ and an interval $I=(0,T)$ for some $T<\infty$. Let $p,q\in (2,\infty)$ be such that the Sobolev index $\mathtt{Sob}\stackrel{{\rm def}}{=}1-\frac{2}{p}-\frac{d}{q}$ satisfies
\begin{equation}

-\frac{d}{2}\leq \mathtt{Sob} <0, \qquad \text{ and }\qquad p<\frac{d}{-\mathtt{Sob}},
\end{equation}
Moreover, set $q_{{\rm max}}\stackrel{{\rm def}}{=}-\frac{d^2}{d-2}\frac{1}{\mathtt{Sob}}$, 
with the convention $q_{{\rm max}}=\infty$ if $d=2$.
Then for all $p_0\in (2,\infty)$ and $q_0\in (2,q_{{\rm max}})$ satisfying 
\begin{equation}

-\frac{2}{p_0}-\frac{d}{q_0}<\mathtt{Sob},
\end{equation}
there exists a constant $C_0$ such that, for all $N\geq 1$, 
\begin{equation}

w_0\in L^r_{{\mathscr F}_0}(\Omega;\mathbb{B}^{1-2/p}_{q,p}(\mathbb{T}^d))\qquad \text{ and }\qquad F\in L^r_{\mathscr{P}}(\Omega;L^p(I ;L^q(\mathbb{T}^d;{\mathbb R}^{d\times d}))),
\end{equation}
the unique energy solution $w^N$ to the oscillating stochastic Stokes system (equation eq:turbulent_Stokes_scaling_uniform_estimates of the paper) provided by Lemma (l:global_energy_estimate of the paper) satisfies
\begin{align}

\big({\mathbf E}\|w^N\|_{L^{p_0}(I;L^{q_0} (\mathbb{T}^d))}^{r} \big)^{1/r}
&\leq C_0 \big({\mathbf E}\|w_0\|_{B^{1-2/p}_{q,p}(\mathbb{T}^d)}^r\big)^{1/r}\\
\nonumber
& + C_0  \big({\mathbf E}\|F\|_{L^p(I;L^q(\mathbb{T}^d))}^r\big)^{1/r}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

