[Proposition eq:lookdown-sip of arXiv:2412.01489, 'One- and two-particle spectral gap identities for the symmetric inclusion process and rela'] For all $k\ge 2$, we have
	\begin{equation}
		\ensuremath{\mathcal S}_k  {\mathscr L}_{G,\alpha,\omega,k}(f\circ \Phi_k)= (L_{G,\alpha,\omega,k}f)\circ \Phi_k\; \text{,}\;\;\qquad f \in \mathbb{R}^{\Xi_k}\; \text{,}\;\;
	\end{equation}
	where ${\mathscr L}_{G,\alpha,\omega,k}$ denotes the generator of the lookdown ${\rm SIP}_k(G,\alpha,\omega)$ given, for all $\varphi \in \mathbb{R}^{V^k}$ and $\mathbf x\in V^k$, by 
	\begin{equation}
		{\mathscr L}_{G,\alpha,\omega,k}\varphi(\mathbf x)= {\mathscr L}_{G,\alpha,k}\varphi(\mathbf x)
			 - \varphi(\mathbf x)\sum_{i=1}^k \omega_{x_i}\; \text{.}
	\end{equation}	
	Here, ${\mathscr L}_{G,\alpha,k}\varphi(\mathbf x)$ reads as
	\begin{equation}
	{\mathscr L}_{G,\alpha,k}\varphi(\mathbf x) = \sum_{i=1}^k \sum_{x,y\in V}c_{xy}\,\delta_{x,x_i}\tonde{\alpha_y+2\sum_{j=1}^{i-1}\delta_{y,x_j}}\left(\varphi(\mathbf x_i^y)-\varphi(\mathbf x)\right)\; \text{,}\;\;
	\end{equation}and stands for the conservative part of the lookdown dynamics, with $\mathbf x_i^y\in V^k$ denoting the configuration obtained from $\mathbf x\in V^k$ by setting the $i$-th coordinate equal to $y\in V$.

