[Defs 36 (Smooth local function {\cite[(1.2)) of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] {Osa96}}] \ 
\begin{itemize}
\item A function $u: \U \to \R$ is {\it  smooth} if $\mathbf u_r^{k, \eta}$ is smooth in $ B_r^{\times k}$ for every $r>0$, $k \in \N_0$ and $\eta \in \U$. 
We denote by $\mcD_{loc}^\infty$ the space of all smooth local functions. 

\item Under~\ref{ass:CE} and~\ref{ass:ConditionalClos}, we define  
$$\mcD_{loc, \QP}^\infty:=\{u\in \mcD_{loc}^\infty: \underline{\E}^{\U, \QP}(u)+\|u\|_{L^2(\QP)}<\infty\} \fstop$$

{According to~Dfn.~\ref{d:core}, $\mcD_{loc, \QP}^\infty \subset \cup_{r>0} \mcC_r \subset \dom{\underline{\E}^{\U, \QP}}$}, thus $\underline{\E}^{\U, \QP}(u)$ is well-defined for $u \in \mcD_{loc, \QP}^\infty$ and $(\underline{\E}^{\U, \QP}, \mcD_{loc, \QP}^\infty)$ is closable since  $(\underline{\E}^{\U, \QP}, \dom{\underline{\E}^{\U, \QP}})$ is a closed extension of it. The closure is denoted by $(\overline{\E}^{\U, \QP}, \dom{\overline{\E}^{\U, \QP}})$. 
Due to the locality of $u$, there exists $R>0$ such that $\cdc^{\U}_r(u)=\cdc^{\U}(u)$ for every $r \ge R$ and 
\begin{align}
 \overline{\E}^{\U, \QP}(u)=\frac{1}{2}\int_\U \cdc^{\U}(u) \diff \QP = \frac{1}{2}\int_\U \cdc_r^{\U}(u) \diff \QP \quad r \ge R\fstop
 \end{align}

\end{itemize}

[Proposition prop:semigroup of arXiv:2511.22162, 'Landau Hamiltonian with Gaussian white noise potential and the asymptotics of its bottom o'] For $q = (h, \zeta) \in \ccM$, $\bA \in \ccA$ and $g \in L^2(B; \C)$, the initial value problem (equation eq:Landau_PDE of the paper) admits a unique, global-in-time mild solution $v$. Define, for $t \in (0, \infty)$,
	\begin{equ}
		P^B_t(\bA, q): g \mapsto e^{-h} v(t, \cdot),
	\end{equ}
	and $P_0^B(\bA, q) = \mathrm{Id}$ for $t = 0$. Then, the following assertions hold for the map $(t, \bA, q, g) \mapsto P^B_t(\bA, q) g$ defined on $[0, \infty) \times \ccA \times \ccM \times L^2(B)$.
	\begin{enumerate}
		\item For fixed $(\bA, q) \in \ccA \times \ccM$ and $t \ge 0$, the map $g \mapsto P^B_t(\bA, q) g$ defines a bounded, symmetric (hence self-adjoint), compact and positive operator on $L^2(B)$.
		\item For fixed $t \ge 0$, the map $(\bA, q) \mapsto P^B_t(\bA, q)$ is locally Lipschitz-continuous from $\ccA \times \ccM$ to $\cL(L^2(B))$.
		\item For fixed $(\bA, q) \in \ccA \times \ccM$, the map $t \mapsto P^B_t(\bA, q)$ is continuous from $[0, \infty)$ to $\cL(L^2(B))$.
		\item For fixed $(\bA, q) \in \ccA \times \ccM$ and $0 \leq s < t < \infty$, one has the semigroup property $P^B_{t}(\bA, q) = P^B_{t-s}(\bA, q) \circ P^B_{s}(\bA, q)$.
	\end{enumerate}

