body:
[Lemma 19 of arXiv:2608.06392, '2608.06392'] Let $g:\mathbb R_+\to\mathbb R_+$ be locally integrable, ultimately monotone, and $\int_0^\infty g(t)\,dt<\infty$.
    Assume that for some constant $K>0$,
\[
    g(t)\sim{K}\,\frac{L(t)}{t}  \qquad \text{as} \quad t\to\infty,
\]
    where $L\in\mathcal{SV}_\infty$. Then
\begin{equation}
    {\mathcal{L}g(0)-\mathcal{L}g(s)}\sim{K}\int_{1/s}^\infty\frac{L(u)}{u}\,du
    \qquad \text{as} \quad s\downarrow{0}.
\end{equation}

    Conversely, if
\begin{equation}
    {\mathcal{L}g(0)-\mathcal{L}g(s)}\sim{C}\int_{1/s}^\infty\frac{L(u)}{u}\,du
    \qquad \text{as} \quad s\downarrow{0}
\end{equation}
    for some $C>0$, then
\begin{equation}
    g(t)\sim{C}\,\frac{L(t)}{t} \qquad \text{as} \quad t\to\infty.
\end{equation}

