[Definition of arXiv:2608.12415, 'Sharp Phase Transition for Ellipsoid Fitting'] For the base iteration, we define $
	\mathsf{Proper} \mathcal{L}^*(M^{-1}\eta )$ to be the weighted linear combination of the following terms in the $3$-way concatenation in $\frac{r+s}{s^2-ru} \cdot A^{-1}\eta$ :
	\begin{enumerate}
		\item Proper concatenations such that each non-trivial gadget in $A^{-1}$-path is an $\alpha$-gadget;
		\item Linearization of well-behaved intersections such that each non-trivial gadget in $A^{-1}$-path is an $\alpha$-gadget without interior $\beta$-gadget.
	\end{enumerate}
	Let $\mathsf{ProperShape} \mathcal{L}^*(M^{-1}\eta )$ denote the collection of underlying proper shapes.

[Theorem alpha=0 of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] Suppose $\gamma_2(x_{max}, Y^\pm(x_{max})) \neq 0$. 
Then,
\begin{equation}
    h_\alpha(z_0) \underset{\alpha\to 0}{\sim} \alpha \partial_\alpha[h_{\alpha}(z_0)]_{\alpha = 0}
\end{equation}  
{and thus $c^{z_0}_0(\alpha) \underset{\alpha\to 0}{\sim} \frac{1}{\sqrt{2\pi}}\alpha \partial_\alpha[h_{\alpha}(z_0)]_{\alpha = 0} $}. Furthermore, if $\alpha^* = 0$, 
\begin{equation}
    c_1^{z_0}(\alpha)\underset{\alpha\to 0}{\longrightarrow} 2\kappa \partial_\alpha[h_{\alpha}(z_0)]_{\alpha = 0}.
\end{equation}

Moreover,
\begin{itemize}
\item  If $\alpha^* = 0$ (i.e. $\phi_2$ has no pole), then
$$ g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to\infty \atop \alpha \to 0}{\sim} \partial_\alpha[h_{\alpha}(z_0)]_{\alpha = 0} \frac{e^{-r(\cos(\alpha)x(\alpha) + \sin(\alpha)y(\alpha))}}{\sqrt{r}}\left({\frac{\alpha}{\sqrt{2\pi}}}+ \frac{2\kappa}{r}\right) .$$

\item If $\alpha^* > 0$  (i.e. $\phi_2$ has a pole), then
$$
g^{z_0}(r\cos(\alpha), r\sin(\alpha)) \underset{r\to\infty \atop \alpha \to 0}{\sim} c^*h_{\alpha^*}(z_0)e^{-r(\cos(\alpha)x^* + \sin(\alpha)y^*)}
$$
where $h_{\alpha^*}(z_0)$ and $c^*$ are given by (equation harm2 of the paper) and (equation eq:c* of the paper), respectively.
\end{itemize}

Moreover, the constants $\partial_\alpha[h_{\alpha}(z_0)]_{\alpha = 0}$ and $h_{\alpha^{*}}(z_0)$ are nonzero in the corresponding asymptotics.

[Lemma l:regularity_v_u of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Let $Q$ be a parabolic cylinder with side length $\varrho\in (0,1/2]$ and center $(t_0,x_0)\in {\mathbb R}_+\times {\mathbb R}^d$. Fix $r\in (1,\infty)$, $N\geq 1$ and $\delta\in (0,1]$. 
Let $(v^{N,\delta},\pi^{N,\delta},(\widetilde{\pi}_{k,\alpha}^{N,\delta})_{k,\alpha})$ be a local solution to (equation eq:turbulent_Stokes_scaling_quantitative of the paper). Let $\mathrm{Err}^{{\rm det}}$ and $\mathrm{Err}^{{\rm sto}}$ be as in (equation eq:def_error_det of the paper) and (equation eq:def_error_sto of the paper), respectively. Then, the process $z^{N,\delta}$ is well-defined with paths
$$
z^{N,\delta} \in L^2(I;H^{1}_0(B;{\mathbb R}^d))\cap L^\infty(I;\mathbb{L}^2(B)) \ \text{a.s.,}
$$
and moreover,
\begin{align*}
\big({\mathbf E}\|z^{N,\delta}\|_{L^\infty(I;L^2(B))}^r \big)^{1/r}
+
\big({\mathbf E}\|z^{N,\delta}\|_{L^2(I;H^1(B))}^r\big)^{1/r}
\lesssim\big( {\mathbf E}\|G\|_{L^2(Q)}^r\big)^{1/r}\qquad \qquad\qquad&\\
+\big({\mathbf E}\|\nabla v^{N,\delta}\|_{L^2(Q)}^r\big)^{1/r}
 +\big({\mathbf E} \|(\nabla \widetilde{\pi}^{N,\delta}_{k,\alpha})_{k,\alpha}\|_{L^2(Q;\ell^2)}^r\big)^{1/r},&
\end{align*}
where the implicit constant depends only on $\mu,r,\varrho$ and $d$.

