body:
[Definition def.algorithm of arXiv:2505.15283, 'Quantization of Probability Distributions via Divide-and-Conquer: Convergence and Error Pr'] Let $T^f(\mu,0) = \delta_{f(\mu)}$ and for $n\geq 1$ let 
\begin{equation}
    \mu^{(n),f} :=T^f(\mu,n) = \mu(\Omega_-)T^f(\mu_-,n-1)+\mu(\Omega_+)T^f(\mu_+,n-1)
\end{equation}
and we let $F^{(n),f}(x) := \mu^{(n),f}(-\infty,x]$ denote the corresponding CDF.  If $\mu(\Omega_\pm) = 0$ the procedure terminates prematurely and sets $\mu^{(n),f}=\delta_{f(\mu_\mp)},\ \forall n\geq 0$.

[Lemma l:ordrIn of arXiv:2505.09604, 'Exceptional force, uncountably many solutions in the KPZ fixed point'] The following holds on the event $\Omega_1$ for all $\xi\in\mathbb{R}$, $s\in\mathbb{R}$, and $x_0 <  y_0 \in\mathbb{R}$. For these choices, define
           \begin{equation}
           \begin{aligned}
                 \mathfrak t_{RL}&=\inf\{r>s:\tau^{\xi,+}_{(x_0,s)}(r)=\tau^{\xi,-}_{(y_0,s)}(r)\}\\
               \mathfrak t_{LL}&=\inf\{r>s:\tau^{\xi,-}_{(x_0,s)}(r)=\tau^{\xi,-}_{(y_0,s)}(r)\}\\
               \mathfrak t_{RR}&=\inf\{r>s:\tau^{\xi,+}_{(x_0,s)}(r)=\tau^{\xi,+}_{(y_0,s)}(r)\}.
           \end{aligned}
           \end{equation}
           Then, 
       \begin{align}

           \tau^{\xi,+}_{(x_0,s)}(r)&\geq \tau^{\xi,-}_{(y_0,s)}(r) \quad\text{for}\quad r\in [\mathfrak t_{RL},\infty), \quad\text{and, moreover,} \\

           \tau^{\xi,+}_{(x_0,s)}(r) &=  \tau^{\xi,-}_{(y_0,s)}(r) \quad\text{for}\quad r\in [\mathfrak t_{RL},\mathfrak t_{LL}\wedge \mathfrak t_{RR}] 
       \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:2 of arXiv:2602.00988, 'Wealth exchange under ceiling and flooring constraints: a modified Bennati–Dragulescu–Yako'] Let ${\bf p}(t) = \{p_n(t)\}_{n\geq 0}$ be a classical solution to the system of nonlinear ODEs (equation eq:law_limit of the paper)-(equation eq:two-classes of the paper) with ${\bf p}(0) \in V_\mu$, we have
\begin{equation}
\sup\limits_{t\geq 0} \sum\limits_{n\geq 0} K^n\,p_n(t) \leq \max\left\{\frac{K^{b+1}+K^a}{1-\mu/b},\sum_{n\geq 0} K^n\,p_n(0)\right\}
\end{equation}
for all $K > 1$, provided that $\sum_{n\geq 0} K^n\,p_n(0) < \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conjecture 1 of arXiv:2609.02610, 'The frame set of the first Hermite function'] The frame set of the first Hermite function is given by
  \begin{equation}
    \cF(h_1)
    =\left\{a,b\in(0, \infty):
      ab<1
      \text{ and }
      ab\neq\frac{q-1}{q}
      \text{ for every }q\in\Z_{\geq2}
    \right\}.
  \end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma lem:localNumeratorComm of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] There exists $\beta_{\mathrm{loc}}=\beta_{\mathrm{loc}}(\mu,v,n)>0$ such that for every $0<\gamma\le\beta_{\mathrm{loc}}$ and every $\sigma\in\{\pm1\}$,
\begin{align}
\sup_{N\ge1}
{\mathbb{E}}_{\mu^{\otimes N}}
\Bigg[\exp\pa*{
\sigma\frac{\gamma}{4C_{\mathrm{sr},n}\|\nabla v\|_{L^\infty}^n}
N\mathsf A_n(v,X_N,\mu)
-\gamma N\mathsf{F}_N(X_N,\mu)}\Bigg]
\le e+L.
\end{align}

