&=\mathrm{Pr}\{Z(t_1)\le x_1, Z(t_2)\le x_2,\dots, Z(t_n)\le x_n\}\\ &=\sum_{\substack{m_l\ge0\{\langle}=1,2,\dots,n}}\mathrm{Pr}\Big\{\sum_{i=1}^{m_1}X_i\le x_1, \sum_{i=1}^{m_1+m_2}X_i\le ...","release_manifest_digest":"sha256:781423f04d7ff2ec217774f6183227bfa3e533d20f615720255eec93d691e9dc","revision_digest":"sha256:723f221d15d9035ffb8cc10d671af00953c660340f0c8d001093b265d45e37f9","source_id":"arxiv:2411.09257","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

