[Definition eq:detailed_balance of arXiv:2510.20461, 'Long time behaviour of one facilitated kinetically constrained models: results and open pr'] We say that  $\mu$ satisfies detailed balance if   for any finite set $\Lambda\subset {\ensuremath{\mathbb Z}} ^d$ and any $ x$ such that $x+[-\operatorname{r},\operatorname{r}]^{d}\in\Lambda$
\begin{equation}
c_{x}(\eta_{\Lambda})\pi(\eta_{\Lambda}^{x})\mu(\eta_{\Lambda})=c_{x}(\eta^x_{\Lambda})\pi(\eta_{\Lambda})\mu(\eta_{\Lambda}^{x})=c_{x}(\eta_{\Lambda})\pi(\eta_{\Lambda})\mu(\eta_{\Lambda}^{x}).
\end{equation}

[Definition 1 of arXiv:2606.17859, 'Full $\Gamma-$expansion for the level-two large deviation rate functionals of non-reversib'] Consider a non empty Polish space $\mc X$ and a sequence of
functionals $U_n: \mc X \to [0,+\infty]$. A full $\Gamma-$expansion of
$U_n$ is given by the speeds $(\alpha^{(p)}_n, n\geq 1)$,
$-\mf r \leq p \leq \mf q$, and the functionals
$U^{(p)}: \mc X \to [0,+\infty]$, $-\mf r \leq p \leq \mf q$, if:

\begin{enumerate}

\item The speeds $\alpha^{(-\mf r)}_n, \dots, \alpha^{(\mf q)}_n$ are
positive sequences such that $\alpha^{(p)}_n\prec \alpha^{(p+1)}_n $,
for every $-\mf r \leq p < \mf q$;

\item $\alpha_{\epsilon}^{(p)} U_n$ $\Gamma-$converges to $U^{(p)}$,
$-\mf r \leq p \leq \mf q$;

\item $U^{(p+1)}(x)$ is finite if, and only if, $x$ belongs to the
$0-$level set of $U^{(p)}$, for every $-\mf r \leq p < \mf q$;

\item $\beta_n U_n$ $\Gamma-$converges to $0$, for every sequence
$\beta_n \prec \alpha_n^{(-\mf r)}$; and

\item the $0-$level set of $U^{(\mf q)}$ is a singleton.
\end{enumerate}

In this case, we express the expansion as 
\begin{equation*}
U_n = \sum_{p\in -\mf r}^{\mf q}\frac{1}{\alpha_{n}^{(p)}} \, U^{(p)}.
\end{equation*}

[Corollary 113 (Finite-grade reconstruction with deterministic branches) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Fix $2\le r<\infty$ and an integer $Q\ge0$.  For every
$0\le q\le Q$, let $E_q(I)$ be an order-continuous
$r$-reconstruction lattice for the fixed two-sided block support system,
with constant $C_{E_q,r}$.  Let
\[
 H_{\nu;i}^{(0)}\in
 \Sch_r(Q_{\mu(i)}\cC,P_{\lambda(i)}\cE)
\]
and, for $q\ge1$, let
\[
 H_{\nu;i}^{(q)}\in
 \mathfrak W_{q,r}
 (\cH_{\R};Q_{\mu(i)}\cC,P_{\lambda(i)}\cE)
\]
be symmetric block kernels, all realized over one isonormal Gaussian
process.  Assume, for every $q$:
\begin{enumerate}
\item $H_{\nu;i}^{(q)}$ is Cauchy blockwise in $\Prof_{q,r}$ for every
      $i\in I$;
\item there is $M^{(q)}\in E_q(I)$ such that
\begin{equation}

 \Prof_{q,r}(H_{\nu;i}^{(q)})\le M_i^{(q)}
 \qquad(\nu\in\N,\ i\in I).
\end{equation}
\end{enumerate}
Then every branch
\[
 H_\nu^{(q)}:=\sum_{i\in I}H_{\nu;i}^{(q)}
\]
is well defined in its coefficient completion and is Cauchy there.  The
finite Gaussian polynomials
\begin{equation}

 T_\nu:=\sum_{q=0}^{Q}I_q(H_\nu^{(q)})
\end{equation}
are Cauchy in $L^p(\Omega;\Sch_r)$ for every $1\le p<\infty$.

More quantitatively, if
\[
 d_{\nu,\mu;i}^{(q)}
 :=\Prof_{q,r}(H_{\nu;i}^{(q)}-H_{\mu;i}^{(q)})
 \quad(0\le q\le Q),
\]
then
\begin{align}

 \norm{T_\nu-T_\mu}_{L^p(\Omega;\Sch_r)}
 &\le C_{E_0,r}\norm{d_{\nu,\mu}^{(0)}}_{E_0}
 \notag\\
 &\quad+
 \sum_{q=1}^{Q}A_q(p+r)^{q/2}C_{E_q,r}
 \norm{d_{\nu,\mu}^{(q)}}_{E_q}.
\end{align}
The same conclusion holds for two cutoff schemes with common majorants and
the same blockwise limits.

[Theorem 56 (Habiro diagonal lift) of arXiv:2608.29585, '2608.29585'] Let $K$ be a zero-framed knot, let $n\ge2$, and let
$1\le s\le n-1$.  Then
\begin{equation}
 \mathscr J_K^{(n,s)}(q)=\sum_{k=0}^{\infty}
 \left(\prod_{i=0}^{k-1}\{-s-i\}\{n-s+i\}\right)
 H_k^{(n)}(K;q)
\end{equation}
defines an element of $\Hab$.  If $\zeta$ has order $L>s$, then
\begin{equation}
 \mathscr J_K^{(n,s)}(\zeta)=J_{L-s}^{SU(n)}(K;\zeta).
\end{equation}
Moreover, \eqref{eq:ordinary-Habiro-series} is the image of
\eqref{eq:colored-lift} under the continuous specialization $x=q^{-s}$.

[Definition 1 of arXiv:2607.22441, 'The martingale representation theorem for cylindrical martingale valued measures'] We consider the space $L = L(M,T,X,Y)$ whose elements are families of operators $\Phi(\omega,t,u)$ that satisfy:
\begin{enumerate}
    \item For each $(\omega,t,u)$, $\Phi(\omega,t,u) \in \mathcal{L}(X,Y)$.
    \item The process $\quadraVari{Q_M \Phi^* y_1^*,\Phi^* y_2^*}_{X,X^*}$ is predictable for each $(y_1^*,y_2^*) \in Y^*\times Y^*$.

    \item  For each $A\in \mathcal{A}$ the expression
    \begin{equation}

    \rho_{M,A}(\Phi) := \sup_{\norm{y^*}_{Y^*}\leq 1} \left[ \int_{\Omega\times [0,T]\times A} \quadraVari{Q_M \Phi^* y^*,\Phi^* y^*}_{X,X^*} d\mu_M \right]^{1/2}
    \end{equation}
    represents a (finite) real number, that is $\rho_{M,A}(\Phi)<\infty$.
\end{enumerate}

[Theorem 3 (A representation congruence modulo $32$) of arXiv:2609.03238, 'Representation Defects and Cassels Pairings for Congruent Number Curves'] Assume \eqref{eq:layer}.  Then
\begin{equation}
\frac{r_f(pq)-r_g(pq)}{32}
 =\frac{r_a(pq)-h(-pq)}{16}
 \equiv\Pi(p,q)\pmod2.
\end{equation}
Equivalently,
\[
r_a(pq)\equiv h(-pq)+16\Pi(p,q)\pmod{32}.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:regularity of arXiv:2411.02459, 'Existence and higher regularity of statistically steady states for the stochastic Coleman-'] {Let $d\leq 3$ and assume the same conditions from  (thm:well-posed of the paper). Additionally assume that \nameref{cond:Q:higher_regularity}, \nameref{cond:phi:d=3} hold} for $m\ge 2$. Then, any invariant probability $\nu^\mu$ of (equation eqn:react-diff:mu of the paper) satisfies 
\begin{equation}
\sup_{\mu\in \mathcal{M}_\delta}\int_{\mathcal{H}^m_\mu} \exp\Big\{\beta_m\|(u,\eta)\|^{q_m}_{\mathcal{H}^m_\mu} \Big\}\nu^\mu(\emph{d}u,\emph{d}\eta)<\infty,
\end{equation}
for some positive constants $\beta_m$, $q_m\in(0,1)$. Here, $\mathcal{M}_\delta$ is as in~(equation form:M_delta of the paper). Furthermore, for all $p\ge 1$,
\begin{equation} 
\sup_{\mu\in \mathcal{M}_\delta}\int_{\mathcal{H}^m_\mu} \|u\|^p_{H^m}\|u\|^2_{H^{m+1}}\nu^\mu(\emph{d} u,\emph{d}\eta)<\infty,
\end{equation}
In particular, $\nu^\mu(H^{m+1}\times M^m_\mu)=1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 9 (Mean-field convergence with converging coefficients) of arXiv:2605.23529, 'Generalized Bessel-Dunkl diffusions'] Let the finite systems be given by \eqref{eq:mf:root-sde}, with the same $1/N$ mean-field scaling, but with $\sigma,b,k$ replaced by coefficients $\sigma_N,b_N,k_N$. Assume \ref{ass:mf:exist} and \ref{ass:mf:initial}. Assume also that $k_N$ is symmetric, that all coefficients satisfy the growth bounds \eqref{eq:mf:growth-sigma}-\eqref{eq:mf:growth-k} uniformly in $N$, and that, for every $T,R>0$,
    \begin{align}
        \lim_{N\to\infty}
        \sup_{\substack{0\le t\le T\\ |x|\le R}}
        \left|\sigma_N^2(t,x)-\sigma^2(t,x)\right|
            &=
            0,
        \\
        \lim_{N\to\infty}
        \sup_{\substack{0\le t\le T\\ |x|\le R}}
        |b_N(t,x)-b(t,x)|
            &=
            0,
        \\
        \lim_{N\to\infty}
        \sup_{\substack{0\le t\le T\\ |x|\le R,\ |y|\le R}}
        |k_N(t,x,y)-k(t,x,y)|
            &=
            0,
        \\
        \lim_{N\to\infty}
        \sup_{\substack{0\le t\le T\\ 0\le x\le R}}
        |k_N(t,x)-k(t,x)|
            &=
            0.

    \end{align}
    Then the conclusions of Theorem~\ref{thm:mf:classical} remain valid, with the same limiting equation \eqref{eq:mf:limit-equation}. (Proof in the paper; no proof environment follows the statement in the TeX.)

