body:
[Lemma lem:contraction of arXiv:2606.04859, 'Stein's method for the Wishart distribution'] Let $\alpha > 3d-3$ and $\Sigma\in \mathcal{S}_{++}^d$ be given. Let $(\mathfrak{W}_t)_{t\geq 0}$ be the Wishart process defined in (equation eq:Wishart.process of the paper), with transition semigroup $(\mathcal{P}^{\mathcal{W}}_t)_{t\geq 0}$ and stationary limiting distribution $\xi = \mathcal{W}_d(\alpha, \Sigma)$. For any given $t > 0$, let $\Sigma_t = (1 - e^{-2t})\Sigma$ and define
\[
h_t(X) \vcentcolon= h(\Sigma_t^{1/2}X\Sigma_t^{1/2}), \qquad X\in \mathcal{S}_{++}^d,
\]
with $h:\mathcal{S}_{++}^d\to\mathbb{R}$ being bounded and Lipschitz. Assume that $h\in C^d(\mathcal{S}_{++}^d)$ and that for every differential monomial $\overline{\nabla}$ of order at most $d$ in the entries of $\nabla_{\!X}$, there exist constants $C_{\overline{\nabla}}, N_{\overline{\nabla}}\geq 0$ such that
\begin{equation}
|\overline{\nabla}h(X)| \leq C_{\overline{\nabla}} (1 + \|X\|_F^{N_{\overline{\nabla}}}), \qquad X\in \mathcal{S}_{++}^d,
\end{equation}
and assume that
\begin{equation}
M_t^{\mathcal{D}}(h) \vcentcolon= \sup_{X\in \mathcal{S}_{++}^d} \sup_{\substack{U\in \mathcal{S}^d\\ \|U\|_F = 1}}\big|\langle U, \mathcal{D}\rangle_F \, h_t(X)\big| < \infty.
\end{equation}
Then, for every $W\in \mathcal{S}_{++}^d$, we have
\begin{equation}
\begin{aligned}
\big|(\mathcal{P}^{\mathcal{W}}_t h)(W)-\mathsf{E}[h(\mathfrak{W}_{\infty})]\big|
&\leq \frac{e^{-2t}}{1 - e^{-2t}} \, M_t^{\mathcal{D}}(h) \, \|\Sigma^{-1/2}W\Sigma^{-1/2}\|_F \\
&\qquad + e^{-2t} [h]_1 \, \|\Sigma\|_2 \, \mathsf{E}[\|\mathfrak{V}\|_F],
\end{aligned}
\end{equation}
where $\mathfrak{V}\sim \mathcal{W}_d(\alpha, I_d)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop tv-general of arXiv:2604.20629, 'Rates of forgetting for the sequentially Markov coalescent'] Let $K$ be a Markov kernel on $(0,\infty)$
with transition density $q( \cdot |s)$ with respect to Lebesgue
measure, and let $\pi$ be an invariant probability measure for $K$.
Suppose that:
\begin{enumerate}
\item There exists $L<\infty$ such that 
\begin{equation}
\int^{\infty}_{0}\bigl|q(t|a)-q(t|b)\bigr| dt\le L |a-b|,\qquad a,b>0;
\end{equation}
\item There exists a coupling $(X_{n},Y_{n})_{n\ge0}$ of two copies of
the chain, with 
\[
X_{0}=x,\qquad Y_{0}\sim\pi,
\]
such that for some $r\in(0,1)$, 
\begin{equation}
\mathbb{E}\!\left[ |X_{n+1}-Y_{n+1}| \, \mid  \, X_{n},Y_{n}\right]\le r |X_{n}-Y_{n}|\qquad\text{a.s. for all }n\ge0.
\end{equation}
Then for every $n\ge1$, 
\begin{equation}
d_{\mathrm{TV}}\!\bigl(K^{n}(x,\cdot),\pi\bigr)\le\frac{L}{2} r^{ n-1} \mathbb{E}|x-Y_{0}|.
\end{equation}
In particular, the chain is geometrically ergodic in total variation.
\end{enumerate}

[Lemma lem:dgt4-origin-frozen of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Assume that $d\geq5$ and that the scenery is i.i.d., atomless, centered,
	and of finite positive variance. For every $n\geq0$:
	\begin{equation}
	\begin{aligned}
		\{u_{n+1}(0)=0\}
		&=\{-\zeta(0)>Pw_n(0)\},\\
		(-\zeta(0)-Pu_n(0))_+
		&=(-\zeta(0)-Pw_n(0))_+,\\
		\mathbb{E} u_{n+1}(0)-\mathbb{E} u_n(0)
		&=\mathbb{E}(-\zeta(0)-Pw_n(0))_+\, .
	\end{aligned}
	\end{equation}
	If $\mathbb{E}|\zeta(0)|^p<\infty$ for some $p\geq2$, then
	\begin{equation}
	\begin{aligned}
		\frac{G(0,0)\mathbb{E} Pw_n(0)}{\mathbb{E} u_n(0)}
		&\longrightarrow1,\\
		\sup_{n\geq0}\mathbb{E}|Pw_n(0)-\mathbb{E} Pw_n(0)|^p
		&<\infty\, .
	\end{aligned}
	\end{equation}
	If, in addition, $\mathbb{E} e^{\theta_0|\zeta(0)|}<\infty$ for some
	$\theta_0>0$, then, for every
	\[
		0<\lambda<
		\frac{\theta_0}{
		\displaystyle\sup_{z\ne0}G(0,z)/G(0,0)},
	\]
	there is $C(\lambda)<\infty$ such that for every $n,r\geq0$,
	\begin{equation}
		\mathbb{P}\left(
		Pw_n(0)-\mathbb{E} Pw_n(0)\leq-r
		\right)
		\leq C(\lambda)e^{-\lambda r}\, .
	\end{equation}

