[Theorem 2 of arXiv:2511.04938, 'Uniform dimension theorems for parabolic SPDEs'] Suppose that the underlying probability space $(\Omega\,,\mathscr{F},\P)$ is complete.
	If $\{v\in\R^p:\, \inf_{x\in\R^:\|x\|=1}
	\|\sigma(v)x\|=0\}$ is polar for the random field $u$ 
	(Assumption \ref{ass:polar}) and $p \ge 4$,  then 
	\begin{equation}
		\P\{\dimh  u(\{t\}\times F) = 2\dimh  F \
		\text{$\forall$compact  $F\subset\T$, $t>0$}\}=1.
	\end{equation}
	If in addition the matrix $\sigma(v)$ does not depend on $v\in\R^p$, and is nonsingular, then 
	\eqref{eq:HEAT:torus} holds for all $p\ge2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th: a priori branched of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Under Assumption (As: regularity assumption of the paper), for any solution $Z$ of (equation eq: sol Davie branched of the paper) we have
		\begin{equation*}
			\|Z^{[N+1]}\|_{(N+\beta)\alpha,\mu} \lesssim_{\mathbb X,\sigma,T} 
			(1\vee\| Z^{[1]}\|_{\alpha,\mu})+\sum_{\ell=2}^{m+1}\|Z^{[\ell]}\|_{\ell\alpha,\mu}\, ,
		\end{equation*}
		and, if either $T$ or $\mu$ are sufficiently small, 
		\begin{align}\nonumber
			&(1\vee \| Z^{[1]} \|_{\alpha, \mu})+\sum_{i=2}^N \| Z^{[i]} \|_{i \alpha, \mu}  \le
			\\ & \le 2\left[ (1\vee (|\Upsilon_{\bullet}(Z_0)| \, \|\mathbb{X}(\bullet)\|_{\alpha}))+ \sum_{\tau\in{\mathcal T}^{\le N}\setminus\{\bullet\}} |\tau| \,|\Upsilon_{\tau}(Z_0)| \, \|\mathbb{X}(\tau)\|_{|\tau|\alpha}\right].
		\end{align}
		If moreover $\beta=1$, namely if $\Upsilon_\tau$ is globally Lipschitz continuous for all $\tau\in{\mathcal T}^{\le N}$, 
		then for any solution $Z$ of (equation eq: sol Davie branched of the paper),
		if either $T$ or $\mu$ are small enough, we have
		\begin{equation}
			\sum_{i=1}^N \| Z^{[i]} \|_{i \alpha, \mu} \le 2\sum_{\tau\in{\mathcal T}^{\le N}} |\tau| \,|\Upsilon_{\tau}(Z_0)| \, \|\mathbb{X}(\tau)\|_{|\tau|\alpha}\,.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 of arXiv:2604.00474, 'Trap behaviors for Brownian motions'] For $\alpha < 1/2$, as $t\to 0$, we have that 
\begin{align}
\mathbf{E}_{\mathsf{m}} \left[ \frac{1}{t} \int_0^t f(\mathsf{Y}_s) d\gamma_s(\mathsf{v}) \right] \to \int_{\mathsf{S}} f(\mathsf{x}) \mu(d\mathsf{x})

\end{align}
where
\begin{align*}
\mu(d\mathsf{x}) = \sum_{\varepsilon \in \mathcal{E}}  \rho_\varepsilon\, \mu_\varepsilon(dx)
\end{align*}
is the Revuz measure of the local time $\gamma(\mathsf{v}) = \gamma(\cdot, 0)$ at the star vertex $\mathsf{v}$ of the process $\mathsf{Y}$ on $\mathsf{S}$ whereas $\mu_\varepsilon(dx) = \mu(\varepsilon, dx)$ can be associated with the local time $\gamma(\mathsf{v}) = \gamma(\varepsilon, 0)$ at $\mathsf{v}$ of $\mathsf{Y}$ on the edge $\varepsilon$.

