&0, && \text{otherwise},
\end{aligned}
\right.

\\
\frac{\partial \bm{q}(u,K)}{\partial u}
&=
\bm{Q}(T-u)\bm{q}(u,K).

\end{align}

[Lemma lem:guquasteltsailemma of arXiv:2608.11603, 'Continuous-time directed polymers to the Critical SHF via moments'] {}
		Fix $f_{2}, g_{2} \in \mathcal{L}^{2}(\mathbb{R}^{2[\![n]\!]\setminus\operatorname{r}}_{\alpha})$. Then for $ \alpha = ij, \alpha' =kl \in \mathsf{Pair}[\![n]\!]$ such that $\alpha \neq \alpha'$, we have
		\begin{equation*}
			\sup_{\lambda > 0} \int_{\widehat{\mathbb{R}}^{2[\![n]\!]}}\frac{|\F{f_{2}}(\xi_i + \xi_j, \xi_{[\![n]\!]\setminus\alpha})| \, |\F{g_{2}}(\xi_k + \xi_l, \xi_{[\![n]\!]\setminus\alpha'})|}{\lambda + \frac{1}{2}\Vert \xi\Vert^2} \, \mathrm{d} \xi \lesssim \norm{f_{2}}_{2} \norm{g_{2}}_{2} \, \, .
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

