[Defi 37 of arXiv:2606.24887, '2606.24887'] For $\varphi >0$, $T \subset [N]$ and $x \in [N]$, we define
		\begin{equation*}
			\Phi^{1,\bset{T}}_x:= \sum_{y}^{(Tx)}\bigg(|X_{xy}|^2 - \frac{1}{N}\bigg), \qquad \Psi^{1,\bset{T}}_x:=  \sum_{y}^{(Tx)}\bigg(|X_{xy}|^2 - \frac{1}{N}\bigg) G^{\bset{Tx}}_{\ubarr{y}\ubarr{y}},
		\end{equation*}
		\begin{equation*}
			\Phi^{2,\bset{T}}_x:= \sum_{y}^{(Tx)}\bigg(|X_{yx}|^2 - \frac{1}{N}\bigg),\qquad \Psi^{2,\bset{T}}_x:=  \sum_{y}^{(Tx)}\bigg(|X_{yx}|^2 - \frac{1}{N}\bigg) G^{\bset{Tx}}_{yy}.
		\end{equation*}
		Similarly as in \cref{def:typicalvertices}, we define the set
		\begin{equation*}
			\mathcal{T}^{\bset{T}}_{\varphi} := \Bigl\{ x \in [N]\setminus T :~\max_{i \in \{1,2\}}\absn{\Phi^{i,\bset{T}}_x}\vee \absn{\Psi^{i,\bset{T}}_x }\le \varphi\Bigr\}.
		\end{equation*}

[Corollary Ergodic:AsymptoticDriftDiffusion of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] Fix $\epsilon>0$. There exists positive constants $C_1,C_2$ depending on $d$, $\|b\|_{0,\alpha}$ and $\|\sigma\|_{0,\alpha}$ such that, for all $t$ sufficiently large (depending on $d$, $\|b\|_{0,\alpha}$, $\|\sigma\|_{0,\alpha}$ and $\epsilon$),
    \begin{equation}
        \sup_{x\in \mathbb{R}^d} \mathbb{P}_{x}\bigg[\sup_{\ell \in [0,t]}\bigg| Z_\ell - Z_0 - \ell\nu(b)   \bigg|>t\epsilon\bigg]\leq C_1 t^{-1/2}e^{-C_2t\epsilon^2}.
    \end{equation}

