[Lemma lem:projective-trace-polynomial of arXiv:2608.30779, 'Some uniform estimates for K\"ahler--Ricci Shrinkers'] Assume that \(R_\omega\) is bounded above.  Then there are
\(C,A<\infty\) such that
\begin{equation}
\operatorname{tr}_\omega\Psi^*\omega_{\rm FS}
 \le C(1+\rho^2)^A.
\end{equation}

[Theorem thm:main:PCA:ergodicity of arXiv:2605.16904, 'Positive-rate PCA and IPS with stationary Bernoulli measures are rapidly forgetful \footno'] Let $\Phi$ be a $d$-dimensional PCA with a strictly positive local transition rule $\varphi\colon\Sigma^N\times\Sigma\to(0,1)$, and suppose that $\Phi$ admits a stationary Bernoulli measure $\lambda$.
	Then, there exist constants $\alpha,\beta>0$ 
	such that
	\begin{equation}
		\norm[\big]{(\mu\Phi^t)_J - \lambda_J}_\mathsf{TV} \leq \alpha\mathrm{e}^{-\beta t} n^{d/2}
	\end{equation}
	for every initial measure $\mu$, every finite region $J\subseteq\mathbb{Z}^d$ with diameter~$n$, 
	and every $t\geq 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 of arXiv:2506.13634, 'Absolutely Continuous Curves of Stochastic Processes'] Let $p \in [1,\infty),$ $(\Omega,\cF,(\cF_t)_{t=1}^T,\P)$ be a filtered probability space, and $Y^u = (Y^u_t)_{t=1}^T : \Omega \rightarrow \cX$, $u \in [0,1],$ a family of  $(\cF_t)_{t=1}^T$-adapted processes. Suppose that $\eta\coloneqq \law_{\P}((Y^u)_{u \in [0,1]}) \in \cP(C(\Xc))$ 
    is concentrated on $AC^p(\Xc)$ for some $p \in [1,\infty)$, that
\begin{align} 
    \Y^0 \coloneqq (\Omega,\cF,(\cF_t)_{t=1}^T,\P,(Y^0_t)_{t = 1}^T) &\in \FP_p, \quad \text{and}\nonumber \\ \int_{C([0,T],\Xc)}\int_0^1 |f^\prime|^p(s)\mathrm{d}s\,\eta(\mathrm{d}f)&<\infty.  
\end{align} 
Then, the curve $u \mapsto \Y^u \coloneqq (\Omega,\cF,(\cF_t)_{t=1}^T,\P,(Y^u_t)_{t= 1}^T)$ is in $AC^p(\FP_p)$ and its metric derivative satisfies
\begin{equation}
    |\Y^\prime|^p(u) 
    \leq \int_{C(\Xc)} |f^\prime |^p(u)\eta(\mathrm{d}f), \; \text{for {\rm a.e.}~$u \in [0,1]$.}
\end{equation}

[Definition 2 (Coercivity and continuity assumptions) of arXiv:2604.02312, 'A weak transport approach to the Schrödinger--Bass bridge'] Let $C_V:\mathcal X\times\cP_p(\mathcal Y)\to\R\cup\{+\infty\}$ be a standard weak transport cost and let $W:\cP_p(\mathcal Y)\times\cP_p(\mathcal Z)\to\R\cup\{+\infty\}$ be a standard weak transport problem.

    \begin{enumerate}
        \asptitem{Crc}{Crc}  \textbf{Coercivity assumption.}
        We say that $(C_V,W)$ satisfies the coercivity assumption for $r \in [1,p]$ if for each compact $K \subseteq \mathcal X \times \cP_p(\mathcal Z)$, the map
        \[
            \rho \longmapsto \inf_{(x,\eta)\in K}\bigl\{C_V(x,\rho)+W(\rho,\eta)\bigr\}
        \]
        has compact sublevel sets in $(\cP_p(\mathcal Y),\Wcal_r)$. 

        \asptitem{Cnt}{Cnt}  \textbf{Continuity assumption.}
        We say that $(C_V,W)$ satisfies the continuity assumption if, for every $\rho$ with $(x,\rho) \in {\rm dom}(C_V)$ for some $x \in \mathcal X$, the maps $x \mapsto C_V(x,\rho)$ and $\eta \mapsto W(\rho,\eta)$ are continuous on $\mathcal X$ and on $\cP_p(\mathcal Z)$, respectively.
    \end{enumerate}

[Lemma lem:sum-mdp of arXiv:2608.26745, 'Moderate Deviations for the Largest Eigenvalue of a Randomly Deformed Gaussian Unitary Ens'] Let $b_N\to\infty$, $b_N=o(\sqrt N)$, and $b_N=N^{o(1)}$.  Define
\[
 T_N=\frac1{\sqrt N}
 \sum_{j=1}^N(\xi_j-m_{1,N}).
\]
Then $T_N/b_N$ satisfies an MDP on $\mathbb R$ with speed $b_N^2$ and good rate
function
\begin{equation}
 I_G(x)=\frac{x^2}{2\sigma^2}.
\end{equation}

[Definition eqn : Intro/framework/LDP_general case of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Let $\mathbb{X}$ be a Hausdorff topological space. We call \emph{rate function} a lower semicontinuous map $I:\mathbb{X}\rightarrow \intervalleff0\infty$, i.e. a map whose sublevels $\set{x \in \mathbb{X}}{I(x)\le t}$, for $t\ge 0$, are closed. We further say that $I$ is a \emph{good rate function} if its sublevels are compact.

    We say that a random process $(X_n)_{n\ge 1}$ with values in $\mathbb{X}$ follows the \emph{large deviation principle} (LDP), at speed $a_n$, with the rate function $I$ if for every Borel set $A\subseteq \mathbb{X}$,
\begin{equation}

    \inf_{x\in \overline{A}} I(x)
    \le \liminf_{n\to\infty}-\frac{1}{a_n} \log \Pb{ X_n \in A } 
    \le \limsup_{n\to\infty}-\frac{1}{a_n} \log \Pb{ X_n \in A } 
    \le \inf_{x\in \mathring{A}} I(x).
\end{equation}

[Theorem 9 of arXiv:2608.19179, 'A random walk on $p$-groups with a symmetric perfect pairing'] The Markov chain generated by $\Delta_S$  on the state space $X_S$ is reversible with respect to the probability measure:
\begin{equation}

\frac{
\prod_{i=1}^{\infty}(1-p^{1-2i})
}{
\# G
\# Aut(G,<\cdot,\cdot>)
