[Corollary sec2-col.1 of arXiv:2602.04303, '\Large\textbf{Strong solutions to SDEs with singular drifts driven by fractional Brownian '] Assume that $b_j\in L^p(\mathbb{R}^d),p\geq1,\alpha_j\in\mathbb{N}^d,j=1,\cdots,m$. Then, for $0\leq s_0<s_1<\cdots<s_m$, we have
		\begin{equation}
			\left|\mathbb{E}_{s_0}\left[\prod_{j=1}^m\partial_{\alpha_j}b_j(B_{s_j}^H)\right]\right|\leq C_{H,d,p} \prod_{j=1}^m\Vert b_j\Vert_{L^p}(s_j-s_{j-1})^{-H|\alpha_j|-\frac{Hd}{p}}
		\end{equation}
		Here, we adopt the convention that $\mathbb{E}_0[\cdot]=\mathbb{E}[\cdot]$.

