[Definition def-commutaror of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] Suppose that $u:\mathbb{R}^d \to  \mathbb{R}$ is locally Lebesgue essentially bounded and $b:\mathbb{R}^d \to  \mathbb{R}^d$ is locally Lebesgue integrable  such that $\operatorname{div} b :\mathbb{R}^d \to  \mathbb{R}$ is locally Lebesgue integrable. We define  an expression $\mathcal{R}_\ensuremath{\varepsilon}[b,u]$  by the following formula
\begin{equation}
 \mathcal{R}_\ensuremath{\varepsilon}[b,u]:= \vartheta_\ensuremath{\varepsilon} \ast ( b\cdot  D u) -  b \cdot   D ( \vartheta_\ensuremath{\varepsilon} \ast u),
\end{equation}
where $b\cdot  D u$ is defined in Definition (def-weak derivative of the paper) and $\vartheta_\ensuremath{\varepsilon}$ is defined by (equation def-vartheta-eps of the paper),  and we call $ \mathcal{R}_\ensuremath{\varepsilon}[b,u]$ the  $\ensuremath{\varepsilon}$-commutator.

[Prop p:CDRP-scaling of arXiv:2607.18194, 'Temperature chaos in directed polymers'] There exists an event $\Xi_0\subset \Xi$ with $\mathbb{P}(\Xi_0)=1$ such that
    \begin{enumerate}[label={\rm(\roman*)}]
        \item\textup{(Translation).} For each $(u,z) \in \mathbb{R}^2$, on the event $\Xi_0\cap\mathsf{T}(u,z)$, it holds for all $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$, all $\beta\geqslant 0$, and all Borel sets $S\in\mathcal{B}(C([s,t]))$ that
        \begin{align*}
            \mathbb{P}_{\beta,(s+u, x+z),(t+u, y+z)}\left(
                X(\cdot + u) - z
                \in S\right)
            \circ \mathcal{T}_{-u, -z}
            =
            \mathbb{P}_{\beta,(s,x),(t,y)}(X\in S).
        \end{align*}
        \item\textup{(Shearing).} For each $(r,\nu)\in\mathbb{R}^2$, on the event $\Xi_0\cap\mathsf{S}(r,\nu)$, it holds for all $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$, all $\beta\geqslant 0$, and all Borel sets $S\in\mathcal{B}(C([s,t]))$ that
        \begin{align*}
            \mathbb{P}_{\beta,(s, x+\nu(s-r)),(t, y+\nu(t-r))}\left(
                X(\cdot) - \nu(\cdot - r)
                \in S
            \right)
            \circ \mathcal{S}_{r, -\nu}
            =
            \mathbb{P}_{\beta,(s,x),(t,y)}(X\in S).
        \end{align*}
        \item\textup{(Diffusive scaling).}
        For each $\lambda>0$, on the event $\Xi_0\cap \mathsf{D}(\lambda)$, it holds for all $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$, all $\beta\geqslant 0$, and all Borel sets $S\in\mathcal{B}(C([s,t]))$ that
        \begin{align*}
            \mathbb{P}_{\beta\lambda^{-1/2}, (\lambda^2 s, \lambda x),(\lambda^2 t,\lambda y)}\left(
                \lambda^{-1}X(\lambda^2\cdot)
                \in S
            \right)
            \circ \mathcal{D}_{\lambda^{-2},\lambda^{-1}}
            =
            \mathbb{P}_{\beta,(s,x),(t,y)}\left(X\in S\right).
        \end{align*}
    \end{enumerate}
    The events $\mathsf{T}(u,z), \mathsf{S}(r,\nu), \mathsf{D}(\lambda)$ are defined in (t:AJRS-Z-scaling of the paper).
    Like in (t:AJRS-Z-scaling of the paper), the composition notation $\circ$ reflects that the above polymer probabilities are regarded as real-valued functions of the white noise.

[Definition def:triple of arXiv:2601.10359, 'An Operator It\^o Formula for Volterra Gaussian Processes:\\ The Intrinsic Bracket via Cau'] A \emph{causal derivation--divergence triple} is $(D,\delta,\Pi)$ where:
\begin{enumerate}[label=(\arabic*)]
\item $D: \Dom(D) \subset L^2(\Omega) \to L^2(\Omega;\mathcal{H})$ is a densely-defined closed linear operator (the \emph{derivation}) with $\mathbf{1}\in\Dom(D)$ and $D\mathbf{1}=0$.
\item $\delta: \Dom(\delta) \subset L^2(\Omega;\mathcal{H}) \to L^2(\Omega)$ is the Hilbert space adjoint of $D$ (the \emph{divergence}):
\begin{equation}
\mathbb{E}[F\delta(u)] = \mathbb{E}[\inner{DF}{u}_\mathcal{H}], \qquad F \in \Dom(D),\; u \in \Dom(\delta).
\end{equation}
\item $\Pi: L^2(\Omega;\mathcal{H}) \to L^2(\Omega;\mathcal{H})$ is a bounded projection (``causal'' or ``predictable'') with $\Pi^2 = \Pi$.
\end{enumerate}

[Proposition 9 of arXiv:2605.15781, 'Mean-Field Backward Stochastic Differential Equations with Nonlinear Resistance and Double'] Let  Assumption \ref{ass1ipterminalp} and \ref{assLR} hold. Given $C\in \mathcal{H}^p$, the BSDE with double mean reflections 
   \begin{equation}
   \begin{cases}
Y_t=\xi+\int_t^T C_s ds-\int_t^T Z_s dB_s+K_T-K_t, \\
\E[L(t,Y_t)]\leq 0\leq \E[R(t,Y_t)], \\
K_t=K^{R}_t-K^{L}_t, \int_0^T \E[R(t,Y_t)]dK_t^{R}=\int_0^T \E[L(t,Y_t)]dK^{L}_t=0,
\end{cases}
\end{equation}
has a unique solution $\left(Y,Z,K\right)\in \mathcal{S}^p\times\mathcal{H}^{p}\times BV[0,T]$.

[Theorem l:6A of arXiv:2508.21658, 'Infinite-dimensional stochastic differential equations for Coulomb random point fields'] There exists an $ \uLX $ satisfying the following: 

\noindent \thetag{i} 
For each $ m \in \zN $, $ \uLXm $ is the $ \mum $-symmetric, conservative, continuous Markov process associated with $(\Emum , \uLdm ) $ on $ \Lmm $. 

\noindent \thetag{ii} 
For each $ m \in \zN $, $ \uLXm $ satisfies 
\begin{align}		&
 \uLXm = \limiR \uLXRm \quad \text{ in law in $ W^{[m]}$} 
.\end{align}

\noindent \thetag{iii} 
 $ \uLX $ satisfies 
\begin{align} &
 \uLX = \limiR \uLXR \quad \text{ in law in $ \CRdN $}
.\end{align}
In particular, each tagged particle $ \uLxX ^{i } $ of $ \uLX = (\uLxX ^i )_{i\in \N }$ does not explode.

[Proposition max2 of arXiv:2507.10294, 'Guessing Strategies for Shelf-Shuffling Machines'] Let $n\geq 5$. Then, $I_2^*=I_{n-1}^*=\{2,3\}$, i.e. the player should guess card $2$ or card $3$ in positions $2$ and $n-1$.
    \begin{proof}
        Note that the $n=2$ case was covered in the proof of Proposition $(first card of the paper)$. One verifies that when $n=3$, $p_{2,2}=p_{3,2}=1/2$. When $n=4$, we have $p_{3,2}=p_{4,2}=p_{3,3}=p_{4,3}=3/8$, and Proposition $(doubly stochastic of the paper)$ implies that the player should guess card $3$ or $4$ in position $2$ and card $3$ or $4$ in position $3$.
        We will show that $p_{2,2}$ and $p_{3,2}$ are the unique maxima of column $2$. The column $n-1$ case will follow by Proposition $(guessing strategy symmetry of the paper)$. We have, for any $i\leq n$, $p_{i,2}=\frac{i-1+\binom{i-1}{n-2}}{2^i}$. The binomial coefficient vanishes when $i-1<n-2$, i.e. when $i\leq n-2$. For the other two cases, we have $p_{n-1,2}=\frac{n-1}{2^{n-1}}=p_{n,2}$ using Lemma $(last two rows are equal of the paper)$. So the problem has been reduced to finding
        \begin{equation}
        \max_{1\leq i\leq n-2}\frac{i-1}{2^i}
        \end{equation}
        and comparing this value with $p_{n,2}=\frac{n}{2^{n}}$. Some calculus shows that the maximum in equation $(max2 of the paper)$ is $1/4$ and is achieved only at $i=2$ and $i=3$. To compare this with $p_{n,2}$, we note that by the same calculus used above, for $n\geq 2$, the sequence $p_{n,2}=\frac{n}{2^n}$ is strictly decreasing with $p_{4,2}=1/4$. Hence, $p_{n,2}<1/4$ for all $n\geq 5$ and thus the maxima are unique.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:biskup_xi of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{def:renorm_scheme_2}
    For $\alpha \in(0,2)$ and $\delta \in (\max(0, 1-\alpha),2-\alpha)$, let

    \begin{equation}   

        \xi
        =
        \xi(\delta, \alpha)
        = 
        \frac{
            \delta/2
        }{
            1 - \delta /2
        }.
    \end{equation}

    Let $r_0 > 1$ be a large constant, $\bar r_0:=r_0$, and for $i \geq 1$ we iteratively define

    \begin{equation}

        m_i = r_{i-1}^{\xi}
        \quad
        \text{and}
        \quad
        r_i = m_i r_{i-1}.
    \end{equation}

    Let $((\Tile{i}{j})_{j \geq 0})_{i \geq 0}$ be the renormalisation scheme associated to the renormalisation scales $(r_i)_{i \geq 0}$ in \thref{def:recursive_tiles}.

[Lemma lemma_bound_length_xi_chi_b of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] For all $\sigma \in \{-,+\}$ and $\big(v^{\textup{c}},v^{\textup{exc}},v^{\textup{mea}}\big) \in \Omega_{\textup{c}} \times \Omega_{\textup{exc}}^{-\sigma} \times \Omega_{\textup{mea}}^{\sigma}$, 
\begin{equation}
|\xi^{-\sigma}(v^{\textup{c}}_{-1})|+|\chi^{\sigma}|+|b| \leq 9 \varepsilon n.
\end{equation}

[Lemma 9 (Local identity of the auxiliary forcing) of arXiv:2607.10813, '2607.10813'] If $U\subset\R^3$ is open and $\chi=\rho=1$ on a neighborhood of $U$, then
\begin{equation}
  \zeta_a^{\chi,\rho}=\xi_a
  \quad\text{in }\mathcal D'((0,T_0)\times U).
\end{equation}
The same identity holds at every finite spectral cutoff.

[Definition 120 (Complex slope) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] For any $u \in \mathbb{C}$, define 
		\begin{flalign}

                  	f_0 (u) = \displaystyle\frac{(\mathfrak{q}^{u-b - c} - 1) (\mathfrak{q}^{u} - 1)}{(\mathfrak{q}^{u+a} - 1) (\mathfrak{q}^{u - b} - 1)}; \qquad U(u) = \mathfrak{q}^{u} \cdot \displaystyle\frac{f_0 (u)}{1 - f_0 (u)}; \qquad V(u) = \displaystyle\frac{\mathfrak{q}^{u}}{1 - f_0 (u)}. 
		\end{flalign} 

		\noindent For any $(x, y) \in \mathbb{R}^2$, define $u = u(x,y) = u_q (x, y)$ to be the unique solution in $\overline{\mathbb{H}}$ to the equation
		\begin{flalign}

                  	\mathfrak{q}^y =  V(u) - \mathfrak{q}^x \cdot U(u),
		\end{flalign}
		whenever \eqref{equationu}, which is quickly verified to be a quadratic equation in $\mathfrak q^u$, has at most one real root. In this case, define the \emph{complex slope} $f_x(y):=f (x, y) $ by
		\begin{flalign}

			f (x,y) = \displaystyle\frac{\mathfrak{q}^{u} - \mathfrak{q}^{y}}{\mathfrak{q}^{u} - \mathfrak{q}^{y-x}}.
		\end{flalign}

[Theorem SSK with CW interaction at phase transitions \cite{BL17,BLW18,JKOP2} of arXiv:2510.26960, 'Free energy fluctuations in SK and related spin glass models: \\ A literature survey'] At the boundaries between each pair of phases and at the triple point, $F_N$ exhibits the following convergence in distribution as $N\to\infty$.
\begin{enumerate}[(i)]
\item Spin glass $\leftrightarrow$ Ferromagnetic [BL17]: If $\beta>1$ and $J=1-wN^{-1/3}$ for fixed $w\in\mathbb{R}$, then
 \begin{equation} 
\frac{2N^{2/3}}{\beta-1}(F_N(\beta)-F(\beta))\to \TW_{1,w}
 \end{equation} 
where $F(\beta)$ is defined as in (equation eq:F(beta)SSK+CW of the paper) for the spin glass regime and  $\TW_{1,w}$ is a parametrized family characterized in Theorems 1.5 and 1.7 of [Bloemendal_2012], interpolating between Tracy-Widom and Gaussian.
\item Ferromagnetic $\leftrightarrow$ Paramagnetic [BLW18]: If $J>1$ and $\beta=J^{-1}+BN^{-1/2}$ for fixed $B\in\mathbb{R}$, then
 \begin{equation} 
N\left(F_N(\beta)-F(\beta)-\frac{\log N}{4N}\right)\to \mathcal{G}_1+Q(\mathcal{G}_2)
 \end{equation} 
where $F(\beta)$ is defined as in (equation eq:F(beta)SSK+CW of the paper) for the ferromagnetic regime, $(\mathcal{G}_1,\mathcal{G}_2)$ has bivariate Gaussian distribution with explicit mean and variance depending on $J$, and $Q$ is an explicit function depending on both $J$ and $B$ (in the GOE case that we consider $\mathcal{G}_1,\mathcal{G}_2$ are independent, but the theorem is more general).
\item Spin glass $\leftrightarrow$ Paramagnetic [JKOP2]: If $J<1$ and $\beta=1+bN^{-1/3}\sqrt{\log N}$ for fixed $b\in\mathbb{R}$, then
 \begin{equation} 
\frac{N}{\sqrt{\frac16\log N}}\left(F_N(\beta)-F(\beta)+\frac{\log N}{12N}\right)\to\mathcal{N}(0,1)+\sqrt{\frac32}b_+\TW_1
 \end{equation} 
where $F(\beta)$ is defined as in (equation eq:F(beta)SSK+CW of the paper) for the spin glass ($b\geq0$) and paramagnetic ($b\leq0$) regimes, $b_+=\max\{b,0\}$, and $\TW_1$ is independent of $\mathcal{N}(0,1)$.
\item Triple point [JKOP2]: If $\beta=1+bN^{-1/3}\sqrt{\log N}$ and $J=1-wN^{-1/3}$ for fixed $b,w\in\mathbb{R}$, then
 \begin{equation} 
\frac{N}{\sqrt{\frac16\log N}}\left(F_N(\beta)-F(\beta)+\frac{\log N}{12N}\right)\to\mathcal{N}(0,1)+\sqrt{\frac32}b_+\TW_{1,w}.
 \end{equation} 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma gap_convergence of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] For any fixed $\delta >0$ and $f$ of the form (Form of f of the paper) with $supp (f) \subset [-K_f, \infty), $ for some $K_f>0$, uniformly in $x\in[-(\mu -\lambda)t-\delta\sqrt{t},-(\mu -\lambda)t+\delta\sqrt{t}]$, we have
\begin{equation}
  \begin{aligned}
    &\lim_{t\to\infty}\mathbb{E}[1-e^{-\sum_{i = 1}^{n(t)} f(x_{i}+\chi_{k}^{i}(t) - \lambda t)}|x+M_{t} -\lambda t\ge -K_{f}]\\
    & = \int_{-\infty}^{\infty}\mu \mathbb{E}[1-e^{-\int f(y+z)\mathcal{D}^{\mu}(dz) }]e^{-\mu y}e^{-\mu K_{f}}dy. 
 \end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 (Boundedness and continuity of $ \Pi^{-}$, Step 2.a)) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Let $ [\beta]\geq0 $ and assume that 
	\begin{enumerate}
\item for all $ \beta'$ and $m$ such that $ \beta' + m\delta_{\0}\prec \beta$
\begin{equation}
\begin{aligned}
| c^{(m)}_{\beta'}| \lesssim \ve^{| \beta'+ m\delta_{\0}|- 2}=
\ve^{| \beta' | - m\alpha - 2}\,,
\end{aligned}
\end{equation}

\item for all populated $ \beta' \prec \beta$ and $\n$
\begin{equation}
\begin{aligned}
\EE^{\frac{1}{p}} \left|
\partial^\n \Pi_{x \beta'}(y)
\right|^{ p} \lesssim 
\ve^{\alpha-|\n|}
( \ve + |x-y|)^{| \beta' |- \alpha}\,.
\end{aligned}
\end{equation}
\end{enumerate}
Then for every $k$ and $\n$ 

\begin{equation}
\begin{aligned}
	\ve^{(\kk-k)\alpha}
\EE^{\frac{1}{p}} \left| \partial^\n \big(z_k W_{k, \varepsilon}(\Pi_x)\big)_\beta(y) 
\right|^{ p} 
\lesssim 
\ve^{\alpha-2-|\n|}
( \ve+ | x-y|)^{| \beta| - \alpha} \, ,
\end{aligned}
\end{equation}

\begin{equation}
\begin{aligned}
\EE^{\frac{1}{p}} \left| 
\partial^\n \Pi^-_{x\beta}(y) 
\right|^{ p} 
\lesssim 
\ve^{\alpha-2-|\n|}
( \ve+ | x-y|)^{| \beta| - \alpha} \, .
\end{aligned}
\end{equation}

As well as, for every $l\geq 0$
\begin{equation}
\begin{aligned}
\EE^{\frac{1}{p}} \! \left| \ve^{(\kk-k)\alpha}
(\mathrm{id}-T_z^{\leq l}) \partial^\n \big(z_k W_{k, \varepsilon}(\Pi_x)\big)_\beta(y) 
\right|^{ p} 
\! \lesssim 
\ve^{\alpha-2-|\n|-1-l}
|y-z|^{1+l} 
( \ve+ | x-y| + |x-z|)^{| \beta| - \alpha} \, ,
\end{aligned}
\end{equation}
and
\begin{equation}
\begin{aligned}
\EE^{\frac{1}{p}} \left|
(\mathrm{id}-T_z^{\leq l}) \partial^\n \Pi_{x \beta}^{-}(y) 
\right|^{ p} 
\lesssim 
\ve^{\alpha-2-|\n|-1-l}
|y-z|^{1+l}
( \ve+ | x-y| + |x-z|)^{| \beta| - \alpha} \,.
\end{aligned}
\end{equation}

