[Lemma Lem: 1226-1 of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] For $\phi\in C_{lip}(\mathbb{R}^d)$ with Lipschitz constant $l_{\phi}$, let $v_n^Z$ be defined by (equation 1225-2 of the paper)-(equation 1225-3 of the paper). Then for $\epsilon>0$, there exists a function $f_n^{(\epsilon)}:\mathbb{R}^d\times \mathbb{R}\to\mathbb{R}$ such that for $ t>\epsilon+\frac{1}{n},$ $ x\in \mathbb{R}^d$, $f_n^{(\epsilon)}(t,x)\geq -\frac{C_{\zeta}l_{\phi}}{n\epsilon}\big(\hat{\mathbb{E}}[|Z|]+\hat{\mathbb{E}}[|Z|^2]\big)$  and 
		\begin{equation*}
			\partial_tv^Z_{n,\epsilon}(t,x)-p_Z(\nabla_xv^Z_{n,\epsilon}(t,x))=f_n^{(\epsilon)}(t,x),
		\end{equation*}
		where 
	$
			p_Z(a):=\hat{\mathbb{E}}[\langle a,Z\rangle], \ a\in \mathbb{R}^d$, $C_{\zeta}=\max\Big\{\frac{5}{2}|\nabla_x\zeta|_{L^1}, 2|\partial_t\zeta|_{L^1}\Big\}
	$ and $\zeta$ is from (equation eq:huang of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma equivlemma of arXiv:2412.02087, 'The spectral distribution of random graphs with given degree sequences'] We assume that for arbitrarily large $C > 0$ and arbitrarily small $\varepsilon > 0$, the degree sequence satisfies that $\sum_{i = 1}^n \mathbbm{1}\{ d_i^{(n)} < C \sqrt{D^{(n)}/n} \} \leq \varepsilon n$ for all large $n > N(C, \varepsilon)$. Then, with probability $1 - o(1)$, we may remove at most $2 \varepsilon n$ vertices and edges adjacent to them, so that the following holds:
    \begin{enumerate}
        \item The total number of edges removed is no larger than $4\varepsilon C \sqrt{nD}$;
        \item Each vertex of the remaining graph has a degree larger than $C \sqrt{D^{(n)}/n}$;
        \item Condition on the degree sequence of the remaining graph, its law is given by the configuration model.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 8 of arXiv:2609.01101, '2609.01101'] There is $A_0\ge1$ such that, uniformly for
\begin{equation*}
1\le\lambda\le\tfrac12\log T
\qquad\hbox{and}\qquad |b_i|\le T/2,
\end{equation*}
one has
\begin{equation}
(2+\lambda)^{-A_0}B(T,\mathbf b,\mathbf a)
\ll H_\lambda(T)
\ll(2+\lambda)^{A_0}B(T,\mathbf b,\mathbf a),
\end{equation}
where
\begin{equation}
H_\lambda(T)=\sum_{n=1}^{\infty}
\frac{|c_{\mathbf b}(n)|^2}{n^{1+\lambda/\log T}}.
\end{equation}
Also, for some $A_1\ge1$,
\begin{equation}
(\log T)^{-A_1}\ll B(T,\mathbf b,\mathbf a)
\ll(\log T)^{A_1}.
\end{equation}

