[Definition 17 ({\cite[Definition 4.4) of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] {ZB+GD-21}}]
		The sequence $\{X_m\}_{ \in \N }$ of $\Sb -$valued random variables
		satisfies  condition $[\mathbf{\wtilde{T}}]$ if and only if for all $ \eps >0,$ for all $ \eta >0,$ there exists  $ \delta  >0 $ such that
		\begin{equation} 
			\sup_{m \in \N } \, \Pr \bigl\{  \mu (X_m ,\delta )  > \eta \bigr\}  \le \eps .
		\end{equation}

[Lemma lem:signature-dynamics of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Between jumps,
\begin{equation}
\frac{\,\mathrm{d}}{\,\mathrm{d} t}S_w(t)=
\begin{cases}
S_v(t),& w=v0,\\
0,& \text{otherwise.}
\end{cases}
\end{equation}
At a jump of $N$, the signature is right-multiplied by $\exp_{\otimes}(e_1)$, so
\begin{equation}
S_w(t)=\sum_{k=0}^{\rho(w)}\frac{1}{k!}S_{w^{[-k]}}(t-).

\end{equation}

[Lemma 10 of arXiv:2512.02322, 'Ursell functions in lattice gauge theory'] Consider Ising lattice gauge theory with parameter $\beta \geq \beta_0$, and $(\gamma_i)_{i \in [n]}$ being $n$ Wilson loops. Then, 
        \begin{equation}

        U_n^W(W_\gamma) = \sum_{\mathfrak{P} \in \mathfrak{F}_n} (-1)^{|\mathfrak{P}|-1}(|\mathfrak{P}|-1)! \myexp \Big(- 2 \sum_{I \subseteq [n]} c_{I,\mathfrak{P}} \Psi_\beta[I] \Big).
        \end{equation}

