[Lemma cotensoring-fully-homotopical of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $X$ be a finite based $G$-CW-complex. Then the cotensoring 
    \begin{equation}
        \textbf{\textup{maps}}_*(X,-)\colon\cat{$\bm G$-$\textbf{\textup{L}}$-Top}_*\to\cat{$\bm G$-$\textbf{\textup{L}}$-Top}_*
    \end{equation}
    preserves $G$-global weak equivalences. 
    \begin{proof}
        Applying Lemma~(lemma:smash-lQ of the paper) levelwise shows that $((eq:L-Top*-cotensoring of the paper))$ is right Quillen for the $G$-global \emph{level} model structure, hence it preserves $G$-global level weak equivalences by Ken Brown's Lemma. Taking functorial cofibrant replacements in the $G$-global level model structure, we are therefore reduced to proving that $((eq:L-Top*-cotensoring of the paper))$ preserves $G$-global weak equivalences between cofibrant pointed orthogonal $G$-spaces. Note that any cofibrant pointed orthogonal $G$-space $X$ is in particular closed: by Lemma~(lemma:restr-inj-left-Quillen of the paper), $1\to X$ is a cofibration in $\cat{$\textbf{\textup{L}}$-Top}$, and $1=\textbf{\textup{L}}(0,-)$ is cofibrant, so that $X$ is cofibrant in $\cat{$\textbf{\textup{L}}$-Top}$ and hence closed by Lemma~(lemma:cofibrant-closed of the paper). Thus, it suffices to prove that $\textbf{\textup{maps}}_*(X,-)$ preserves $G$-global weak equivalences between closed pointed orthogonal $G$-spaces.

        For this, we fix a compact Lie group $H$ and a complete $H$-universe ${\mathcal{U}}_H$. Then 
        \begin{equation}
            \textbf{\textup{maps}}_*(X,-)\colon\cat{$\bm{(G\times H)}$-Top}_*\to\cat{$\bm{(G\times H)}$-Top}_*
        \end{equation}
        preserves sequential colimits along closed embeddings, so choosing a cofinal sequence in the poset of finite-dimensional subrepresentations of ${\mathcal{U}}_H$, we see that $\textbf{\textup{maps}}_*(X,Y({\mathcal{U}}_G))\cong\textbf{\textup{maps}}_*(X,Y)({\mathcal{U}}_G)$ natural in $Y\in\cat{$\bm G$-$\textbf{\textup{L}}$-Top}_*$. It therefore suffices that $((eq:cotensoring-graph of the paper))$ preserves $\mathcal G_{H,G}$-weak equivalences, which again follows from Lemma~(lemma:smash-lQ of the paper) and Ken Brown's Lemma.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm clt:Randic of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] For all $m\ge 2$ and all $\alpha\in \mathbb{R}$ we have
    \begin{align*}
        \,{\mathbb{E}}\left[R_n^{[\alpha]}\right]&=\frac{m-1}{m^{2\alpha}}n^{2\alpha}+\frac{1}{m^\alpha}n^{\alpha+1}\\
        &\quad +\left(\frac{2\alpha(m-1)}{m^\alpha}+(m-1)\frac{2\alpha+\alpha(\alpha-1)}{2m^\alpha}\right)n^\alpha+o(n^\delta)
    \end{align*}
    with $\delta=\max\{2\alpha,\alpha\}$.\\
    For $m=2$ and $(N_1,N_2)$ defined in (equation N_i of the paper) we have for all $\alpha \in \mathbb{R}$
    \begin{align*}
        \frac{R_n^{[\alpha]}-\,{\mathbb{E}}\big[R_n^{[\alpha]}\big]}{n^\alpha} \overset{d}{\longrightarrow} \frac{(2\alpha+\alpha(\alpha-1))}{2^\alpha}\left(N_1^2+N_2^2-\frac{1}{2}\right).
    \end{align*}
    Let $m \ge 3$.
    \begin{enumerate}
    \item[(i)] For $\alpha > \frac{1}{2}$ it holds that
    \begin{align*}
       \frac{R_n^{[\alpha]}-\,{\mathbb{E}}\big[R_n^{[\alpha]}\big]}{n^{2\alpha-1/2}} \overset{d}{\longrightarrow} 

       \mathcal{N}\left(0,\frac{2\alpha^2(m-2)}{m^{4\alpha}}\right).
    \end{align*}
    \item[(ii)] For $\alpha < \frac{1}{2}$ it holds that
    \begin{align*}
        \frac{R_n^{[\alpha]}-\,{\mathbb{E}}\big[R_n^{[\alpha]}\big]}{n^\alpha} \overset{d}{\longrightarrow} \frac{2\alpha+\alpha(\alpha-1)}{2m^{\alpha-1}}\left(\sum_{i=1}^m N_i^2-\frac{m-1}{m}\right).
    \end{align*}
    \item[(iii)] For $\alpha=\frac{1}{2}$ it holds that
    \begin{align*}
        \frac{R_n^{[1/2]}-\,{\mathbb{E}}\big[R_n^{[1/2]}\big]}{\sqrt{n}}\overset{d}{\longrightarrow} \frac{1}{2}(N_1+N_m)+\frac{3\sqrt{m}}{8}\left(\sum_{i=1}^m N_i^2-\frac{m-1}{m}\right).
    \end{align*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 of arXiv:2604.04100, '\LARGE Learning Equilibrium Fluctuation Expansions from Overdamped Langevin Dynamics'] Suppose that $F\in C^{n+1}(\mathbb{R})$ and satisfies \eqref{assump-F}.
	Let $(b_m(F))_{0\leq m\leq n}$ be the long-time limit coefficients defined in Theorem \ref{thm-longtime-intro} with the assumption $\mathbb{P}(\xi_0 > 0) = \mathbb{P}(\xi_0 < 0) = 1/2$. Let $(B_m(F))_{0\leq m\leq n}$  be the coefficients defined in Proposition \ref{prop-invariant-exp}. Then for every $m \in \{0, \dots, n\}$, we have
	\begin{equation*}
		b_m(F) = B_m(F).
	\end{equation*}

[Lemma singularmutualgoods of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Fix $N\in\mathbb{N},n,d,k\in\mathbb{N}$ with $n-d\geq 2d\geq 2k$. Consider $H$ an $(n-d)\times 2d$ matrix with $\sigma_{2d-k}(H)\geq c_0\sqrt{n}/16$. Fix intervals $B_1,\cdots,B_{n-d}\subset\mathbb{Z}$ with $|B_i|\geq N$. Let $X$ be sampled uniformly from the product box $\mathcal{B}=B_1\times\cdots\times B_{n-d}$. Then 
$$
\mathbb{P}_X(\|HX\|_2\leq n)\leq (\frac{Cn}{dc_0N})^{2d-k}
$$
    for a universal constant $C>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 of arXiv:2604.08623, 'Central limit theorem for the Allen-Cahn equation with supercritical random initial condit'] For any \(t > \eps^2\) and  any \(x_1, \cdots, x_{p},y_1,\cdots,y_q \in \mathbb{R}^d\), we have that
  \begin{align}
  &\left|\mathbf{E}\left[\prod_{i=1}^p u_\eps(t, x_i) \prod_{k=1}^q u_\eps(t, y_k)\right]-\mathbf{E}\left[\prod_{i=1}^p u_\eps(t, x_i)\right]\mathbf{E}\left[\prod_{k=1}^q u_\eps(t, y_k)\right]\right|\\
  &\lesssim_{p,q} t^{-\frac{(p+q)d}{4}} \exp\left(-\frac{\underset{i,k}{\inf}\|x_i - y_k\|^2}{Ct}\right). \end{align}

[Prp 86 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Set $r_n=n^{\theta},\;\theta\geq 0$ and suppose that $\kappa\in (1/2,1]$ and $\alpha>1$.
Then, for any $\zeta\in (0,\alpha)$,
it holds that
\begin{align*}
  \bbE[d_{\BL^{\kappa}}(\mu^{(r_n)},\mu_n^{(r_n)})^{\zeta}]
  \lesssim  
  \begin{dcases}
    n^{-\zeta(1-\frac{1}{\alpha}-\theta)}, & \alpha\in (1,2),\\
    n^{-\zeta(\frac{1}{2}-\theta)}(\log n)^{\zeta/2}, & \alpha=2,\\
    n^{-\zeta(\frac{1}{2}-\theta)}, & \alpha\in (2,\infty).
    \end{dcases}  
 \end{align*}

