[Lem 11 of arXiv:2608.13374, 'Nearly Sharp Comparison Results for sliced and max-sliced Wasserstein distances'] For $1 \leq k < d$ and $U \in \mathfrak{G}_{d,k}$, write $U\cY := \sbrac{Uy : y \in \cY} \subseteq \R^k$ and $d(z, U\cY) := \inf_{y \in \cY}\norm{z - Uy}$. Then
	\begin{equation}
		W_p^p(U_\#\mu, U_\#\nu) \geq \int_{\R^d} d(Ux, U\cY)^p \dd\mu(x)\,.
	\end{equation}
	In particular, for $\theta \in \mathbb{S}^{d-1}$, writing $\cY_\theta := \sbrac{\abrac{\theta, y}: y \in \cY}$,
	\begin{equation}
		W_p^p(\theta_\#\mu, \theta_\#\nu) \geq \int_{\R^d} d(\abrac{\theta, x}, \cY_\theta)^p \dd\mu(x)\,.
	\end{equation}

[Lemma smoothing-properties-clean of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Let $C$ be an absolutely continuous
copula with density $c$, and let $C_{\varepsilon }$ be defined by (\ref
{822.2})--((822.3 of the paper)). Then, for each $\varepsilon >0$:

\begin{enumerate}
\item[(1)] $C_\varepsilon$ is a copula with continuous density $
c_\varepsilon $;

\item[(2)] if $C_{1}\leq _{c}C_{2}$ in concordance order and the smoothing
kernels are $TP_{2}$, then 
\begin{equation}
C_{1,\varepsilon }\leq _{c}C_{2,\varepsilon };  
\end{equation}

\item[(3)] if $c$ is continuous, then $c_{\varepsilon }\rightarrow c$
uniformly on $[0,1]^{2}$ as $\varepsilon \downarrow 0$, and consequently 
\begin{equation}
C_{\varepsilon }(u,v)\rightarrow C(u,v)\qquad \text{uniformly on }[0,1]^{2}.

\end{equation}
More generally, if $c\in L^{1}([0,1]^{2})$, then $c_{\varepsilon
}\rightarrow c$ in $L^{1}$, and hence $C_{\varepsilon }(u,v)\rightarrow
C(u,v)$ at every continuity point of $C$.
\end{enumerate}

