[Theorem 2 of arXiv:2606.18433, '\bfseries \Large On a class of Reflected Mean-Field Stochastic Differential Equations with'] For all $ t \in [0,T]$, and $\zeta,\zeta' \in\mathbb{L}^2(\Omega,\mathcal{F}_t,\mathbb{P};\bar{G})$, There exists a constant $C>0$ such that
	\begin{itemize}
		\item [(i)]\quad$\mathbb{E} \Big[ \underset{s\in [t,T]}{\sup} \left|X^{t,\zeta}_s -X^{t,\zeta'}_s\right|^4\Big|\mathcal{F}_t \Big]\leq C \left|\zeta-\zeta'\right|^4,$ 
		\item [(ii)]\quad$ \mathbb{E} \Big[\underset{s\in [t,T]}{\sup} \left|A^{t,\zeta}_s -A^{t',\zeta'}_s\right|^4\Big|\mathcal{F}_t \Big] \leq C \left|\zeta-\zeta'\right|^4.$
	\end{itemize}
	If moreover we assume that $G$ is convex, we have for a constant $C>0$
		\begin{itemize}
		\item [(iii)] \quad$\mathbb{E} \Big[ \underset{s\in [t,t+\theta]}{\sup} \left|X^{t,\zeta}_s-\zeta \right|^2 \Big| \mathcal{F}_t \Big]\leq C\theta^2, \quad a.s.$, for any $0\leq \theta \leq T-t$.
		\item [(iv)] \quad$\mathbb{E} \Big[\left|A^{t,\zeta}_{t+\theta}\right|^2 \Big| \mathcal{F}_t \Big]\leq C\theta^2, \quad a.s.$, for any $0\leq \theta \leq T-t$, 
		\item [(v)]\quad$ \mathbb{E} \Big[ e^{\mu A^{t,\zeta}_s}\Big|\mathcal{F}_t\Big]\leq C(\mu,s),\quad \forall s\in [t,T]$, $\quad \forall \mu >0$.	

	\end{itemize}

