[Lemma lem:structure of arXiv:2607.00800, 'Brownian motion in Minkowski normed spaces'] Under \textnormal{(H1)--(H3)}, the following hold.
\begin{enumerate}[(i)]
\item $D^2Q$ is positively $0$-homogeneous on $\mathbb{R}^d\setminus\{0\}$, and $A$ defined as 
\[
A(x):=\bigl( D^2Q(x)\bigr)^{-1} \quad (x\neq 0), \qquad  A(0):= I,
\]
is bounded, Borel measurable, symmetric and uniformly elliptic: 
\[
\frac{1}{\Lambda}I\le A(x)\le \frac{1}{\lambda}I
\qquad \forall x \in \mathbb{R}^d\setminus \{0\};
\]
\item
$x\cdot\nabla Q(x)=2Q(x)$ for all $x \in\mathbb{R}^d$;
\item
We have
\begin{equation}
A(x)\nabla Q(x)=x,
\qquad \forall x \in \mathbb{R}^d\setminus \{0\};
\end{equation}
\item
For $B = (B_1,\dots,B_d)$ with $B_i(x):= \partial_j A_{ij}(x)$, $x \in \mathbb{R}^d \setminus \{0\}$, there exists $C>0$ such that
\begin{equation}
|B(x)|\le \frac{C}{|x|}
\qquad \forall x \in \mathbb{R}^d\setminus \{0\}.
\end{equation}
\end{enumerate}

