d\widetilde{G}_{t}(y,z) = -\mathrm{Re}\left(\frac{2}{\widetilde{f}_{t}(y)}\right)\mathrm{Re}\left(\frac{2}{\widetilde{f}_{t}(z)}\right)dt
\end{align*}

