[Defs 21 (Core) of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] For $r>0$, $\mathcal C_r$ is defined as the space of functions $u$ such that
\begin{enumerate}[$(a)$]
\item $u\in L^\infty(\U, \mu)$; 
\item $u_r^\eta \in {\rm LIP}_b(\U(B_r), \mssd_\U)$ for $\QP$-a.e.~$\eta$;
\item  The following integral is finite:
\begin{align}  
\E^{\U, \QP}_r(u):=\int_{\U} {\E^{\U(B_r), \QP_r^\eta}(u_r^\eta)} \diff\QP(\eta) <+\infty \fstop
\end{align} 
\end{enumerate}

[Theorem thm:Dn_limit of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] Let $w\in\{a,b\}^*$ be a word of exponent $d$ and let $g\geq 1$. Then for any tuple $\mathbf{z}=(z_0,\dots,z_{g-1})\in \mathbb{C}^g$, we have the convergence in distribution
\begin{align}
		\lim_{L\rightarrow \infty}
		\lim_{n\rightarrow \infty}
		\frac{D^w_n(L,g;\mathbf{z})}{\log L} 
=

		\frac{1}{\mathrm{lcm}(d,g)}\sum_{r=1}^{\mathrm{lcm}(d,g)}z_{(r\textnormal{ mod } g) }\bigl|\{c:c|d, \mathrm{gcd}(c,r))=1\}\bigr|.
	\end{align}

	Moreover, the convergence also holds for the expectation, and in probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:middle-energy of arXiv:2608.26707, 'An Exponential Lower Bound for the Permanent\\of Random Bernoulli Matrix'] Let $m=\left\lfloor n/2\right\rfloor$.
Then, for every realization of the first $m$ rows,
\begin{equation}
 S_m\geq\prod_{k=0}^{m-1}(n-2k)\geq m!.
\end{equation}

[Lemma lemma4.2 of arXiv:2609.02607, 'Spatial inhomogeneity for a three-dimensional doubly degenerate nutrient system with indir'] Let $K>0$ with the property that (equation 1.6 of the paper) holds. Given
  $\sigma>0$ and $C=C(K)>0$ as in Lemma (lemma4.1 of the paper), then for any nondecreasing $(t_{k})_{k\in \mathbb{N}}\subset [0,\infty)$, we have
\begin{align}
   \sum_{k=1}^{\infty}\|u(\cdot,t_{k+1})-u(\cdot,t_{k})\|_{(W^{1,\infty}(\Omega))^*}dt\leq C\cdot \left\{\int_\Omega v_{0}\right\}^{\sigma},
\end{align}
where  we set $u(\cdot,0):=u_0$.

