[Corollary 11 of arXiv:2605.11801, 'A non-local singular non-linear Fokker-Planck PDE'] Let suppose Assumption \ref{ass:F}  and $K\in\shp(\R^d)$. The following holds. 
	\begin{itemize}
		\item[(i)] $K*f\in C_T\shc^\gamma$ and
	\begin{equation}
	\|K*f\|_{C_T\shc^\gamma}\leq \|f\|_{C_T\shc^\gamma},
      \end{equation}
      for every $f\in C_T\shc^\gamma$.
\item[(ii)] $F(K*f)\in C_T\shc^\gamma$ and 
\begin{equation}
	\|F(K*f)\|_{C_T\shc^\gamma}\leq C_F(1+\|f\|_{C_T\shc^\gamma}),  \forall f \in C_T\shc^\gamma.
\end{equation}
\end{itemize}

