[Def besov-prior of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d,k\in\mathds{N}$, $\alpha,\beta,\gamma,\theta\in\mathds{R}$, $\mu,\nu\in (-\infty,0]$, and let $X$ be a (real-valued) random variable.
\begin{enumerate}[label={(\alph*)},leftmargin=*,align=left,noitemsep]
\item{We say that $f$ \emph{follows a Besov prior with parameters $(\alpha,\beta,\gamma,\theta,k)$ and template random variable $X$} if the orthonormal basis $(\Psi_{j,t,m})_{(j,t,m)\in J}$ of $L_2(\mathds{R}^d)$ is the one from 
  \hyperref[{eq:wavelet-tensorization}]{\textup{\tagform@{\ref*{eq:wavelet-tensorization}}}}
 (with $\psi_F,\psi_M\in C^k(\mathds{R})$ and $\psi_M$ having $k$ vanishing moments as in (thm:compactly-supported-wavelet of the paper)) and there are i.i.d.\ random variables $\xi_{j,t,m}\sim X$ for $(j,t,m)\in \mathds{N}_0\times \left\{F,M\right\}^d\times \mathds{Z}^d$ such that 
\begin{equation}
f=\sum_{(j,t,m)\in J}2^{j\alpha}(j+1)^\theta \lr{1+\frac{\left\lVertm\right\rVert_\infty}{2^j}}^{\beta + (\gamma-\beta)\mathds{1}_{j=0}}\xi_{j,t,m}\Psi_{j,t,m},
\end{equation}
with unconditional convergence of the series in the sense of tempered distributions.}
\item{We say that $f$ \emph{follows a Besov--Bernoulli{} prior with parameters $(\alpha,\beta,\gamma,\mu,\nu,k)$ and template random variable $X$} if the orthonormal basis $(\Psi_{j,t,m})_{(j,t,m)\in J}$ of $L_2(\mathds{R}^d)$ is the one from 
  \hyperref[{eq:wavelet-tensorization}]{\textup{\tagform@{\ref*{eq:wavelet-tensorization}}}}
 (with $\psi_F,\psi_M\in C^k(\mathds{R})$ and $\psi_M$ having $k$ vanishing moments), there are i.i.d.\ random variables $\xi_{j,t,m}\sim X$ for $(j,t,m)\in \mathds{N}_0\times \left\{F,M\right\}^d\times \mathds{Z}^d$, and
Bernoulli$(\varrho_{j,m})$-distributed random variables $\lambda_{j,t,m}$ for $(j,t,m)\in \mathds{N}_0\times \left\{F,M\right\}^d\times \mathds{Z}^d$, independent among each other and from all the $\xi_{j,t,m}$, with
\begin{equation*}
\varrho_{j,m}=2^{j\mu}\lr{1+\frac{\left\lVertm\right\rVert_\infty}{2^j }}^\nu
\end{equation*}
such that
\begin{equation}
f=\sum_{(j,t,m)\in J}2^{j\alpha} \lr{1+\frac{\left\lVertm\right\rVert_\infty}{2^j}}^{\beta + (\gamma-\beta)\mathds{1}_{j=0}}\lambda_{j,t,m}\xi_{j,t,m}\Psi_{j,t,m},
\end{equation}
with unconditional convergence of the series 
  \hyperref[{eq:expansion-bernoulli}]{\textup{\tagform@{\ref*{eq:expansion-bernoulli}}}}
 in the sense of tempered distributions.}
\end{enumerate}
Here $\mathds{1}_{j=0}\mathrel{\mathop:}= 1$ if $j=0$, and $\mathds{1}_{j=0}\mathrel{\mathop:}= 0$ else.
Furthermore, if $j=0$ for a summand in the expansion 
  \hyperref[{eq:expansion}]{\textup{\tagform@{\ref*{eq:expansion}}}}
, then also $t=(F,\ldots,F)$ is fixed, and in that case we shorten notation by omitting both of them and only keep the relevant index $m\in\mathds{Z}^d$, i.e., we write $\xi_m\mathrel{\mathop:}= \xi_{0,(F,\ldots,F),m}$ and $\lambda_m\mathrel{\mathop:}=\lambda_{0,(F,\ldots,F),m}$.

