[Theorem theo:convergence_at_carrying_capacity of arXiv:2507.12601, 'Multi-type logistic branching processes with selection: frequency process and genealogy fo'] {\emph{(At carrying capacity, forward in time)}}
    Assume that $X_K(0) \Rightarrow X(0) = (1-W_0, W_0)$ with $W_0$ a.s.\ in $[0,1]$. Assume also that there exists $\eta>0$ such that $\sum_{i\geq 0} i^{2+\eta} \mu_K^\pm(i)$ is uniformly bounded in $K$. 
    Then, $X_K$ converges weakly to $X = (1-W, W)$ where $0\leq W\leq 1$ is the unique strong solution to the Gillespie--Wright--Fisher SDE with mutation
    \begin{equation}
    \begin{split}
        \mathrm{d}W(t) &= -\Big(\big(\mathfrak{s}^+ -\mathfrak{v}^+\big)-\big(\mathfrak{s}^- - \mathfrak{v}^-\big)\Big)W(t)\big(1 - W(t)\big) \mathrm{d}t\\
        &\qquad+ \Big(\theta^+\big(1 - W(t)\big) - \theta^- W(t)\Big)\mathrm{d}t \\
        &\qquad + \sqrt{(\mathfrak{m}+\mathfrak{v}^-)W(t)\left(1-W(t)\right) - (\mathfrak{v}^+ - \mathfrak{v}^-)W^2(t)\left(1-W(t)\right)}\mathrm{d}B(t),
    \end{split}
    \end{equation}
    started from $W(0) = W_0$ and where $B$ is a standard Brownian motion. 
    Furthermore, if 
    \[
    \mathfrak{s}^+ -\mathfrak{v}^+\geq \mathfrak{s}^- -\mathfrak{v}^-,  \quad \mathfrak{v}^+ \geq \mathfrak{v}^-\quad\text{ and }\quad\theta^- = 0,
    \]
    the process $W$ satisfies the moment duality 
    \begin{equation}
      \mathbb{E}\left[\left(W(t)\right)^n \vert W(0)=w\right]=\mathbb{E}\left[w^{A(t)} \vert A(0)=n\right],
    \end{equation}
    for all $t \geq 0$ where $\left(A(t)\right)_{t \geq 0}$ is the $\mathbb{N}_0$-valued Markov branching--coalescing process with annihilation, with generator
    \begin{equation}
    \begin{split}
        \mathcal{L}_{\text{\emph{dual}}}f(n)=&\,\theta^+ n \big(f(n-1)-f(n)\big)\\
        &+ \Big(\big(\mathfrak{s}^+ -\mathfrak{v}^+\big)-\big(\mathfrak{s}^- - \mathfrak{v}^-\big)\Big)n \big(f(n+1)-f(n)\big)\\
        &+ (\mathfrak{m}+\mathfrak{v}^-)\binom{n}{2}\big(f(n-1)-f(n)\big)\\
        &+(\mathfrak{v}^+ - \mathfrak{v}^-)\binom{n}{2}\big(f(n+1)-f(n)\big).
        \end{split}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 54 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] Let $f \in \mathcal{B}^n$ \eqref{absolutetails}. Let $V \subset \mathbb{R}^n$ be closed. Then there exists $0 \in G = G^1 \times \cdots \times G^n \subset \mathbb{R}^n$ 
Borel measurable, $G^k_{|\cdot|}$ closed, $k=1,...,n$, such that\footnote{$\mathscr{S}$ is at definition~\ref{Sdef} and $\mathcal{T}(f)$ at \eqref{T(f)}.}
\begin{equation}
\sup_{X \in \mathcal{T}(f)} P(X \in V) = P(\mathscr{S}(f,G) \in V).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 35 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Let {us consider the processes} $\wtilde{M}_m$ and $\wtilde{M}$ defined in \eqref{eqn-martingale} and \eqref{eqn-martingale-1}, respectively. Then, for $\psi,\xi\in L^2(\bO)$ and $0\le s\leq t\le T$
				\begin{align}
					& \lim_{m\to\infty}\wtilde{\E}\big[\big((\wtilde{M}_m(t),\psi)(\wtilde{M}_m(t),\xi) - (\wtilde{M}_m(s),\psi)(\wtilde{M}_m(s),\xi)\big)h(\wtilde{u}_{m}|_{[0,s]})\big]\\
