body:
[Lm 14 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] The functions defined by \eqref{eq:Q-kernel},\eqref{eq:p-kernel} and \eqref{eq:R-kernel} satisfy the following recurrence relations
	\begin{align}
        \begin{split}
    		Q_{i+1,j}(s_{i},x_{j})-Q_{i+1,j}(x_{i},x_{j}) & = \sum_{y_i=s_i}^{x_i-1} Q_{i,j}(y_i,x_j), \\
    		Q_{i,j+1}(x_{i},s_{j})-Q_{i,j+1}(x_{i},x_{j}) & = \sum_{y_j= s_j}^{x_j-1} Q_{i,j}(x_i,y_j), \\
    		U_{k+1}(s)-U_{k+1}(z) & = \sum_{y= s}^{z-1} R_{k}(y), \\
    		p_{k+1}(s)-p_{k+1}(z) & = \sum_{y=s}^{z-1} p_k(y).
        \end{split}
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem LLT of arXiv:2411.03634, '\bf{Local limit theorems for random walks on a large discrete torus }'] For the random walk given  in  Definition (def-CRM of the paper), 
		assume   that there is a fixed real number $x_0\in [0,\frac{L}{2W})^d$ such that $f$ is continuous   at $x_0$ and $f(x_0)>0$, and 
		the covariance matrix $\Gamma=(\Gamma_{ij})$ of density $f$ given   by 
		\begin{equation}  
			\Gamma_{ij}= \int_{\mathbb{R}^d} x_i x_j f(x)dx \end{equation} 
		exists and  is positive definite. Set 

		\begin{equation} 
			(\Gamma_{L})_{ij}
			= \frac{1}{\Omega_W} \sum_{0\neq x\in \Lambda_{L,d}} 
			\frac{x_i x_j}{W^2} f\left(\frac{x}{W}\right),  \ i,j=1, \ldots,L,
		\end{equation}
		and 
		\begin{equation} \sigma_{L}^2:=\frac{W^2}{L^2} <k\Gamma_L, k>.



		\end{equation}

		As $L \to \infty $ and $W\to\infty$, the following three types of local  limits  hold.
		\begin{itemize}
			\item [(I)](Subcritical regime)  When $\log W\ll n \ll (L/W)^2$ and $\|x\|_2 \ll n^{2/3}W$,
			\begin{equation}

				p_n(x)=	
				\frac{1+o(1)}{ (\sqrt{2\pi nW^2\det \Gamma_L})^{d}}   e^{-\frac{1}{2nW^2} 
					<x\Gamma_L^{-1},x> }.
			\end{equation}

			\item[(II)] (Critical regime)
			When $ n \sim (L/W)^2$ and $n\gg \log W$,  and  $\|x\|_2 \ll n^{2/3}W$
			\begin{equation}

				p_n(x)	=\frac{1}{N}  \theta\big(\frac{x}{L}
				,  2\pi \frac{n W^2}{L^2}\Gamma_{L}
				\big)\big(1+o(1)\big).
			\end{equation}	


			\item[(III)] (Supercritical regime) When  $n\gg (L/W)^2$ and $n\gg \log L$,
			\begin{equation}	
				p_n(x)	=\frac{1}{N}\big(1+o(1)\big).
			\end{equation}

		\end{itemize}	
		In addition,  it is also assumed     that 
		$\int_{\mathbb{R}^d} \|x\|_{2}^3  f(x)dx<\infty$ in Case (I) and Case (II). (Proof in the paper; no proof environment follows the statement in the TeX.)

