[Proposition prop:diamond of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] Let $X$ be an $\mathbb{R}^d$-valued continuous semimartingale. Then, for all words ${\color{NavyBlue}{\mathbf{u_1}}}, {\color{NavyBlue}{\mathbf{u_2}}} \in V$, letter ${\color{NavyBlue}{\mathbf{k}}} \in \alphabet[]$, and $\bm{\ell}, \bm{\ell}' \in \TA$,
\begin{equation}
    \int_0^T\langle\bm{\ell}, \sigX[t]\otimes{\color{NavyBlue}{\mathbf{u_1}}}\otimes\sigX[t, T]\rangle \,\langle\bm{\ell}', \sigX[t]\otimes{\color{NavyBlue}{\mathbf{u_2}}}\otimes\sigX[t, T]\rangle \circ dX_t^k 
    = \bracketsigX[T]{\bm{\ell} \diamond^{{\color{NavyBlue}{\mathbf{u_1}}}, {\color{NavyBlue}{\mathbf{u_2}}}}_{{\color{NavyBlue}{\mathbf{k}}}} \bm{\ell}'}.
\end{equation}

[Lemma 14 of arXiv:2607.16502, 'Asymptotic Behavior of Path Functionals for Vector-Valued Gaussian Processes at High Level'] Suppose that \( \bm{X}_{u, \tau}(t) \), \( t \in E \), \( u > 0 \), \( \tau \in Q_u \) satisfy~\ref{A1}--\,\ref{A3} and that \( \Gamma \) satisfies~\ref{F1}.
    Let \(I\dot\cup\Jtan\dot\cup\Jsl=\{1,\ldots,d\}\) be the
    quadratic-programming decomposition associated with \((\Sigma,\bm b)\),
    and use the normalization in \eqref{def hat u}, namely
    \[
      (\uu)_I=u\bm1_I,
      \qquad
      (\uu)_{\Jtan}=\bm1_{\Jtan},
      \qquad
      (\uu)_{\Jsl}=u^{-1}\bm1_{\Jsl}.
    \]
    Let \( \bm{W}(t) \), \(t \in E\), be a centered Gaussian random field with covariance
    matrix function \( K (t, s) \). For \(\bm x\in\R^d\), put
    \[
      \mathcal W_{\bm x}
      =
      \begin{pmatrix}
        \bm W_I-\bm d_I-\bm x_I\\
        -\bm x_{\Jtan}\\
        (\bb-\bm b)_{\Jsl}
      \end{pmatrix}.
    \]
    Assume moreover that \(\Gamma\) satisfies conditions~\ref{F2}--\ref{F3} for
    this shifted limiting random element \(\mathcal W_{\bm x}\). Then, as
    $u \to \infty$, we have
    \begin{equation*}
      \pk{\Gamma ( \uu ( \bm{X}_{u, \tau} - u \bm{b} ) ) > 0}
      \sim
      H_{\Gamma, \bm{W}, \bm{d}, \Sigma, \bm{b}} \,
      u^{-|I|} \, 
      \varphi_{\Sigma_{u, \tau}} ( u \bb ),
    \end{equation*}
    where
    \begin{equation*}
      H_{\Gamma, \bm{W}, \bm{d}, \Sigma, \bm{b}}
      \coloneqq
      \int_{\R^d}
      \exp \left(
      \bm{x}_I^\top \bm{w}_I 
      - \frac{1}{2} \, \bm{x}_J^\top ( \Sigma^{-1} )_{J J} \, \bm{x}_J
      \right)
      \pk{
        \Gamma 
        \begin{pmatrix}
          \bm{W}_I - \bm{d}_I - \bm{x}_I \\
          -\bm{x}_{\Jtan}                                  \\
          ( \bb - \bm{b} )_{\Jsl}
        \end{pmatrix}
        > 0
      }
      \, d \bm{x}
    \end{equation*}
    uniformly in $\tau \in Q_u$.

