[Definition 32 ($(L)-\overline{I}_j~a.e.$) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] For a given node $(S,j)$, the following two properties will be referred  as the property $(L)-\overline{I}_j~a.e.$ on $\mathcal{S}_{(S,j)}$,
 \begin{enumerate}
     \item $(L_{(S,j)})$ holds,
     \item $\mathcal{N}^{(L_{(S,j)})} \equiv \{\hat{S} \in \mathcal{S}_{(S,j)}: \exists~k~\geq j~ \mbox{s.t.}~ (L_{(\hat{S}, k)}) ~\mbox{fails}\}$~is~a ~$\overline{I}_j$-null set (in particular $(L_{(\hat{S}, k)})$~holds~$\overline{I}_j-a.e.$~ for~ every~ $k \geq j$). 
  \end{enumerate}

[Theorem th: affine formula of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Set $X_0=x_0\in S$, fix $\mathbf{u}\in \mathcal V^*$, and suppose that the following conditions hold true.
\begin{enumerate}\phantomsection
    \item The sequence-valued  ODE
    \begin{align}
        \bm{\psi}(t)=\mathbf{u}+\int_0^tR(\bm{\psi}(s))ds, \qquad t\in [0,T],
    \end{align}
    admits a $\mathcal V^*$-valued solution $(\bm{\psi}(t))_{t\in[0,T]}$ such that 
   \begin{align}
       h_{\bm{\psi}(t)}(x)=h_\mathbf{u}(x)+\int_0^th_{R(\bm{\psi}(s))}(x)ds,
   \end{align}
  for all $x\in S$, $t\in[0,T]$.
    \item The process $N^{\exp(h_{\bm{\psi}(s)})}$ given in equation (equation eq:localmart of the paper) defines a true martingale for each $s\in [0,T].$
    \item $\int_0^T\int_0^T\mathbb E[|\mathcal{A}\exp(h_{\bm{\psi}(s)})(X_t)|]dsdt<\infty$.
\end{enumerate}
Then it holds that 
\begin{align}
    \mathbb E[\exp(h_\mathbf{u}(X_T))]=\exp(h_{\bm{\psi}(T)})(x_0).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:estimate of arXiv:2412.03450, 'On intermediate levels of nested occupancy scheme in random environment generated by stick'] Suppose (equation eq:estim of the paper). Then
\begin{equation}
|V_n(t)-\rho_n t^{\alpha n}|\leq\sum_{i=0}^{n-1}{n \choose i}\frac{(\Gamma(\alpha+1))^i (\Gamma(\beta+1))^{n-i}}{\Gamma(\alpha i+\beta (n-i)+1)}(Ct^\alpha)^i(Dt^\beta)^{n-i},\quad n\in\mathbb{N},~t \geq 0,
\end{equation}
where $\rho_n$ is as given in (equation def:fi of the paper).

