body:
[Definition 81 of arXiv:2609.03875, 'Measure theory without infinities'] A set $\mathcal Q$ is called a semi-monotone class if the following conditions are satisfied:
  \begin{enumerate}
  \item Let $\mb A\colon\N\to\mathcal{Q}$ be an increasing sequence of sets and $A = \bigcup_{n\in\N} \mb A(n)$. If $A$ is a subset of some element of $\mathcal Q$, then $A\in \mathcal Q$. 
  \item If $\mb A\colon\N\to\mathcal{Q}$ is a decreasing sequence of sets, then  $\bigcap_{n\in \N} \mb A(n)\in\mathcal Q$.
  \end{enumerate}

[Lemma of arXiv:2411.06089, '{\Large \bf Averaging principle for semilinear slow-fast rough partial differential equati'] For each $T>0$, let $(Z^\varepsilon, \mathcal G(Z^\varepsilon)) \in \mathcal D_{\mathbf \Xi}^{2\gamma ,\eta}([0,T];\mathscr{H})$ be the unique solution of Eq. \emph{((eq2 of the paper))} on $[0, T]$,
then $(X^\varepsilon, G_1(X^\varepsilon)) \in \mathcal D_{\mathbf B}^{2\gamma ,\eta}([0,T];\mathcal{H})$ is the unique solution of the following RPDE
\begin{equation*}
X_t^\varepsilon=S_t x+\int_0^t S_{t-s} F_1 (X_s^\varepsilon,Y_s^\varepsilon)ds+ \int_0^t S_{t-s} G_1 (X_s^\varepsilon) d\mathbf{B}_s, ~~~~(X^\varepsilon)'_t=G_1 (X_t^\varepsilon).
\end{equation*}

