\begin{equation}
    \begin{split}
    \mathbb{E}[\operatorname{Trace}(\mathcal{U}(T))]=&\mathbb{E}\left[\sum_{i=1}^{\infty}e^{\frac{T\eta_{i}}{2}}\right]\\
    =&\frac{2}{\pi}T^{-\frac{3}{2}}\mathbb{E}\left[\exp\left(-\frac{T^{\frac{3}{2}}}{2}\int_{0}^{1}\mathfrak{E}(t)dt+\frac{T^{\frac{3}{2}}}{2\beta}\int_{0}^{\infty}(l_{y})^{2}dy\right)\right],
