		&=\frac{1}{\Gamma(\alpha)}\sum_{r=0}^{n}\frac{r}{\mathrm{Pr}\{\hat{M}(t)=n\}}\int_{0}^{t}(t-s)^{\alpha-1}\mathrm{Pr}\{\hat{M}(s)=r\}\mathrm{Pr}\{\hat{M}(t-s)=n-r\}\,\mathrm{d}s.
	\end{align*}
