[Definition WeightedSemiNorms of arXiv:2607.19037, 'Semiclassical analysis for Yang--Mills \\ random connections on compact surfaces'] Near $a\in  \mathsf{Crit}(f)$, define the local semi-norm 
\begin{eqnarray*}
 \Vert A\Vert_{\mathcal{W}^{p;\alpha,\alpha-1,s} (D_a) }^p \coloneq \sum_{\substack{i\in I \\\square_i\cap C_a \neq \emptyset}}\ \sum_{n=0}^\infty  \left(2^{n(s-\frac{2}{p})}\Vert \mathcal{S}^{2^{-n} ,\star}_{a} A\Vert_{\mathcal{W}^{\alpha,\alpha-1;p} (\square_i) }\right)^p   
\end{eqnarray*}
Define the global norm $\mathcal{W}^{p;\alpha,\alpha-1,s}\big(\Sigma\setminus \max(f)\big)$ by
\begin{align*}
    &\Vert A\Vert_{\mathcal{W}^{\alpha,p,s,\ell}(\Sigma\setminus \max(f)) }^p\\
    &\hspace{2cm}=\sum_{a\in \mathsf{Crit}_1(f)}\Vert A\Vert_{\mathcal{W}^{p;\alpha,\alpha-1,s} (D_a) }^p
+ \sum_{a\in \{\min(f),\max(f)\} } \Vert A\Vert_{\mathcal{W}^{p;\alpha,\alpha-1,\ell} (D_{a}) }^p
+\sum_{i\in I}  \Vert A \Vert_{\mathcal{W}^{\alpha,\alpha-1,p}(\square_i) }^p.
\end{align*}
We can now define the space $\mathcal{W}^{\alpha,p,s,\ell}$.

[Theorem thm:mainthm of arXiv:2411.07125, 'Mixing on the cycle with constant size perturbation'] Considering the upper bound: for any $\delta>0$ target exception probability there exist $\gamma(\delta)<\infty$ 
with the following property. For $n$ large enough and any $0<\varepsilon<1/2$, with probability at least $1-\delta$ in terms of the $k$ random extra edges we have
\begin{equation}

    t_{\rm mix}(\varepsilon) \le \gamma(\delta) n^{\frac{k+2}{k+1}} \log\frac 1 \varepsilon.
\end{equation}

Considering the lower bound: there exist $\gamma^*,\varepsilon^*>0$ 
with the following property. For $n$ large enough asymptotically almost surely (a.a.s.) in terms of the $k$ random extra edges we have
\begin{equation}

    t_{\rm mix}(\varepsilon^*) \ge \gamma^* n^{\frac{k+2}{k+1}}.
\end{equation}
Furthermore, no cutoff occurs. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Suppose that the assumptions of Theorem \ref{thmGS} are satisfied. Define
		\begin{align}
			\Xi(t) \, = \, T_{n+1}-t, \qquad T_n \le  t < T_{n+1},
		\end{align}
		i.e. $\Xi (t) = T^+(t)-t$, $t \geq 0$. Denote by $N^-(s):= N(s-)$, $s \geq 0$.
		Then the process $(Y^+(t-), \Xi(t-))$, $t \geq 0$, is a time-homogeneous Markov process, under all $\PP^{(x,s)}$, $(x,s)\in \RR^d\times (-\infty,0]$, and the filtration $\mathcal{G}^-_t$, $t \geq 0$, generated by $N^-(s)$, $S_0, \dots, S_{N^-(s)+1}$, $T_0, \dots, T_{N^-(s)+1}$, $s \leq t$. Its semigroup $P_t^+$, $t \geq 0$, satisfies for $t\ge 0$ and $(x,s)\in\RR^d\times [0,+\infty)$
		\begin{align}
			P_t^+f(x,s) \, = \, \mathds{1}_{[0 \leq t \le  s]} f(x,s-t)+ \mathds{1}_{[0 \leq s <t]} P_{t-s}^+f(x,0),
		\end{align}
		and
		\begin{align}
			P_t^+f(x,0) \, = \, \mathds{E}^{(x,0)}f(Y(t-), \Xi(t-)),\quad t>0,\, x\in \RR^d.
		\end{align}
		for any function $f \in \mathcal{B}_b (\mathbb{R}^d \times [0, +\infty))$.

