[Theorem t: main theorem rate of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $\Phi$ is a locally square-integrable invariant random complex measure, and let $K$ be an invariant transport kernel. We distinguish the following two cases. 
\begin{enumerate}[label=(\roman*)] 
    \item Let $p\in[-d,\infty)$, and assume that either Condition~(c:condition square-integrable general with p of the paper) or Condition~(c:condition square-integrable Markov with p of the paper) holds. For $q\in\N_0$ with $q<\max(\frac{d+p}{2}, 1)$, define $\Psi_q$ like in Theorem~(t:main theorem of the paper). Assume that there is a $q_0<\max(\frac{d+p}{2}, 1)$ such that $\Psi_{q_0}$ is $(p-2q_0)$-uniform, and else that $\Psi_q$ is beyond \linebreak $(p-2q_0)$-uniform for all $q<\max(\frac{d+p}{2}, 1)$ with $q\neq q_0$. Further, assume that $f$ is compactly supported and Fourier-smooth with exponent $2(d+1)+\lfloor\max(p,0)\rfloor+\vartheta$ for some $\vartheta>0$. Then, if either limit exists,
    \begin{equation}
    \lim_{r\to\infty} \frac{\BV[K\Phi(f_r)]}{r^{d-p}} = \lim_{r\to\infty} \frac{\BV\big[\Psi_{q_0}\big(f_r^{(q_0)}\big)\big]}{(q_0!)^2 r^{d-p}},
    \end{equation}
    $K\Phi$ is $p$-uniform, and if the limit is not $0$, then $K\Phi$ is solely $p$-uniform.

    \item Let $\varepsilon>0, q_0\in\N_0$, assume that Condition~(c:condition square-integrable stealthy of the paper) holds, and assume that $\Psi_q$ is $\infty$-uniform with radius $\varepsilon$ for $q\in\N_0\setminus\{q_0\}$. Further, suppose that $f\in L^1(\R^d, \C)$ such that \linebreak $\supp(\hat{f})\subseteq \overline{B_\varepsilon}$. Then,
        \begin{equation}
            \BV\big[K\Phi(f)\big] = \frac{1}{q_0!^2} \BV\big[\Psi_{q_0}\big(f^{(q_0)}\big)\big].
        \end{equation}
    Hence, if $\Psi_{q_0}$ is $\infty$-uniform with radius $\varepsilon_0\in(0,\varepsilon)$, then $K\Phi$ also is $\infty$-uniform with radius $\varepsilon_0$, and if the above variance is not $0$ for a sequence $(f_n)_{n\in\N}$ such that $f_n\in L^1(\R^d, \C)$ and $\supp(\hat{f_n})\subseteq B_{\varepsilon_0+\frac{1}{n}}$ for $n\in\N$, then $K\Phi$ is $\infty$-uniform with maximal radius $\varepsilon_0$.
\end{enumerate}
\begin{proof}
We start with the first part and let $p\in[-d, \infty)$, and $q_0\in\N_0$ with $q_0<\max(\tfrac{d+p}{2},1)$. Further, we assume that either Condition~(c:condition square-integrable general with p of the paper) or Condition~(c:condition square-integrable Markov with p of the paper) holds, and that $\Psi_{q_0}$ is \linebreak $(p-2q_0)$-uniform, and else $\Psi_q$ is beyond $(p-2q)$-uniform for all $q<\max(\frac{d+p}{2}, 1)$ with \linebreak $q\neq q_0$. Finally, we suppose that $f$ is compactly supported and Fourier-smooth with exponent $2(d+1)+\lfloor\max(p,0)\rfloor+\vartheta$ for some $\vartheta>0$, and define $f_r:=f(\frac{\cdot}{r})$ for $r>0$. Note that Lemma~(l: fourier smooth differentiation of the paper) yields that $f$ is $\lfloor \tfrac{d+\max(p,0)}{2}+1\rfloor$-times continuously differentiable and that the derivatives are sufficiently Fourier-smooth for the following conclusions. By Theorem~(t:main theorem formula of the paper), we know that, with convergence in $L^2$,
\begin{equation}
    K\Phi(f_r) = \sum_{q=0}^{\big\lfloor\tfrac{d+p}{2}\big\rfloor}\frac{1}{q!} \Psi_q\big(f_r^{(q)}\big) + o\Big(r^{\tfrac{d-p}{2}}\Big),
\end{equation}
where the last summand can be dropped if $\tfrac{d+p}{2}\in\N$. Then, using the Cauchy-Schwarz inequality like in the proof of Theorem~(t:main theorem of the paper), we can show that
\begin{equation}
    K\Phi(f_r) = \frac{1}{q_0!} \Psi_{q_0}\big(f_r^{(q_0)}\big) + o\Big(r^{\tfrac{d-p}{2}}\Big),
\end{equation}
which implies~(equation e: exact variance asymptotic of the paper) if either limit exists. Further, $K\Phi$ is $p$-uniform by an application of Theorem~(t:main theorem of the paper). Moreover, the fact that a non-zero limit implies that $K\Phi$ is not beyond $p$-uniform is a direct implication from Theorem~(t:asymptotic variance test function of the paper). Actually, divergence would yiel (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:probabilityParticlesBalls of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] For all $\xi\in \mathcal{W}(\Tilde{c})$ and $\epsilon \in (0,1)$, there exist positive constants $C=C(\xi,\epsilon,d), \Gamma=\Gamma(\xi,\epsilon,d)$, and $T_0=T_0(\epsilon, \xi, d, \|R\|_{C^{0,\alpha}})$ such that, for every $t>T_0$,
