        \sup_{x\in \mathbb{R}^d} \proba{x}{}{(\mathcal{X}_t-x-t\bar{\mathbf{v}})\cap tB(\xi,\epsilon)=\emptyset } \leq Ce^{-\Gamma t}.
    \end{equation}

