[Proposition 29 (The existence of on/off super Brownian motion (ooSBM), Blath and Jacobi \cite{blath2023off}) of arXiv:2604.01852, 'The on/off Brownian snake'] Let $(\mu_{\rm d}, \mu_{\rm a}) \in \mathcal{M}_F(\mathbb{R}^d)^2$. Then there exists a measure-valued Markov process $((\mathcal{Y}^{(\rm d)}_s, \mathcal{Y}^{(\rm a)}_s), s \geq 0)$ that takes values in $\mathcal{M}_F(\mathbb{R}^d)^2$ with $(\mathcal{Y}^{(\rm d)}_0, \mathcal{Y}^{(\rm a)}_0)=(\mu_{\rm d}, \mu_{\rm a})$ which is the scaling limit of ooBBM in the following sense. For $\varepsilon>0$, let $((\mathcal{Z}^{(\varepsilon, \rm d)}_s, \mathcal{Z}^{(\varepsilon, \rm a)}_s))_{s \geq 0}$ be $\text{ooBBM}(\gamma/\varepsilon, c, \Tilde{c})$ with $\mathcal{Z}_0^\varepsilon$ distributed as a Poisson random measure with intensity $(\mu_{\rm d}/\varepsilon, \mu_{\rm a}/\varepsilon)$. Then we have 
\begin{equation*}
    ((\varepsilon\mathcal{Z}^{(\varepsilon, \rm d)}_s, \varepsilon\mathcal{Z}^{(\varepsilon, \rm a)}_s))_{s \geq 0} \rightarrow ((\mathcal{Y}^{(\rm d)}_s, \mathcal{Y}^{(\rm a)}_s))_{s \geq 0}
\end{equation*}
as $\varepsilon$ goes to $0$, in distribution on $\mathbb{D}([0,\infty), \mathcal{M}_F(\mathbb{R}^d)^2)$. The process $((\mathcal{Y}^{(\rm d)}_s, \mathcal{Y}^{(\rm a)}_s))_{s \geq 0}$ is called $\text{ooSBM}(\gamma, c, \Tilde{c})$ started at $(\mu_{\rm d}, \mu_{\rm a})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:marcus-unique of arXiv:2606.28869, '\bfseries A General Theory of Paths:\\ \large Signatures, Jump Lifts, and Expected Signatu'] Let $x,y:[0,T]\to\mathbb{R}$ be finite-variation c\`adl\`ag{} paths with $x_0=y_0=0$, nondecreasing continuous parts, and strictly positive jumps. Let
\begin{equation}
\Gamma(x)_t=(t,x_t)
\end{equation}
be the time-augmented path, and let $\widehat\Gamma(x)$ denote its Marcus completed graph. If
\begin{equation}
\mathrm{Sig}(\widehat\Gamma(x))=\mathrm{Sig}(\widehat\Gamma(y)),
\end{equation}
then $x=y$ as c\`adl\`ag{} paths. Moreover, the forward It\^o{} lift of a path with at least one nonzero jump is not a geometric signature lift of the same completed graph.

[Proposition 8 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Fix $n\ge 1$ and $\kappa\in (0,4]$ and $\bs{\alpha}, \bs{\beta}\in\LX_n$. 
\begin{itemize}
\item Assume $\LF_1: \R_{>0}\times\R\times\R\to \R$ is positive, smooth and rotation-invariant.  
Assume further that $\LF_1$ satisfies annulus BPZ equations~\eqref{eqn::annulusBPZ_single}. 
\item Assume $\LF_n: \R_{>0}\times\LX_n\times\LX_n\to \R $ is positive, smooth and rotation-invariant. Assume further that $\LF_n$ satisfies the system of annulus BPZ equations~\eqref{eqn::annulus_BPZ_alpha} with $F(r)=F_n(r)$ defined in~\eqref{eqn::F(r)inBPZ}. 
\end{itemize}
For $1\le j\le n$, let $\gamma^j$ be the annulus $\SLE_{\kappa}(\LF_1)$ in $(\A_r; \ee^{\ii\alpha_j}, \ee^{\ii\beta_j-r})$. Let $\Pind{n}^{(\kappa)}(\LF_1)$ be the probability measure on $\bs{\gamma}=(\gamma^{1}, \ldots, \gamma^{n})$ under which the curves are independent. 
We parameterize $\bs{\gamma}$ by $n$-time parameter $\bs{t}$, and let $\bs{W}_{\bs{t}} = (W_{\bs{t}}^{1},\ldots,W_{\bs{t}}^{n})$ be the multi-slit driving function (it is unique up to rotation).
Then the following process is $n$-time local martingale under $\Pind{n}^{(\kappa)}(\LF_1)$: 
\begin{align}
\begin{split}
	M_{\bs{t}}(\LF_1; \LF_n)
	:= \; & \one_{\LE_{\emptyset}(\bs{\gamma}_{\bs{t}})} \, \exp\bigg(\frac{\mathfrak{c}}{2}\blm_{r,\bs{t}} + \mathfrak{b} \sum_{j=1}^{n} (r-t_j) - n \mathfrak{b} \Mod(\A_r\setminus \bs{\gamma}_{[\bs{0},\bs{t}]}) \bigg) 
	\; \times \prod_{j=1}^{n} \mathfrak{\covmap}_{\bs{t},j}'(\zeta_{t_j}^{j})^{\mathfrak{b}}  \\
	& \times \prod_{j=1}^{n} \frac{\mathfrak{\covmap}_{\bs{t}}'(\beta_j+\ii r)^{\mathfrak{b}}}{(\mathfrak{\covmap}_{t_j}^j)'( \beta_j + \ii r)^{\mathfrak{b}}}  \times \frac{\LF_n(\Mod(\A_r\setminus \bs{\gamma}_{[\bs{0},\bs{t}]});\bs{W}_{\bs{t}},\Re \mathfrak{\covmap}_{\bs{t}} (\bs{\beta}+\ii r)) }{\prod_{j=1}^{n} \LF_1(r-t_j;\zeta_{t_j}^j,\Re \mathfrak{\covmap}_{t_j}^j(\beta_j+\ii r))};
\end{split}
\end{align}
where $\LE_{\emptyset}(\bs{\gamma}_{\bs{t}}) = \{ \gamma_{[0,t_j]}^{j} \cap \gamma_{[0,t_i]}^{i}=\emptyset, \, \forall i\neq j\}$ is the event that different curves are disjoint, and 
$\blm_{r,\bs{t}}$ is the Brownian loop term defined in~\eqref{eqn::mt_blm_annulus}: 
\[	\blm_{r,\bs{t}}:=\blm \left(\A_r;\gamma_{[0,t_1]}^{1},\ldots,\gamma_{[0,t_n]}^{n} \right).\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:C of arXiv:2411.16058, 'Gaussian deconvolution on $\mathbb R^d$ \\ with application to self-repellent Brownian mot'] Let $d > 2$ and let $ a_d = \frac{ \Gamma(\frac{ d-2 } 2 ) }{ 2\pi^{d/2}}$. 
We have
\begin{equation}
C(x)  =  \frac{ a_d }{ \sqrt{\det \Sigma} } \frac 1 { ( x \cdot \Sigma^{-1} x )^{(d-2)/2} } 
	+ O_\Sigma \bigg( \frac 1 {  \abs x^{d+2} } \bigg)
	\qquad \text{as $\abs x \to \infty$.}
\end{equation}

