body:
[Proposition aux4AiandBi of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] ([olver1997asymptotics]) Let $Bi(x)$ be the other solution of the Airy equation and $c$ be the largest negative root of $Ai(x)=Bi(x)$ (see [olver1997asymptotics] for the explicit expression for both $Bi$ and $c$). Define the modulus function $\mathbf{M}$ and weight function $\mathbf{E}$ as:
    \begin{equation*}
        \mathbf{E}(x):=\left\{\begin{array}{cc}
\sqrt{\frac{Bi(x)}{Ai(x)}},~~x>c\\
1,~~~x\le c
        \end{array}\right.~~and~~ \mathbf{M}(x):=\sqrt{\mathbf{E}^2(x)Ai^2(x)+\frac{Bi^2(x)}{\mathbf{E}^2(x)}}.
    \end{equation*}
    Then $|Ai(x)|\le\left|\frac{\mathbf{M}(x)}{\mathbf{E}(x)}\right|$, and $\mathbf{E}$ increasing on $(0,\infty)$. Moreover, as $x\rightarrow\infty$,  $\mathbf{E}(x)\sim\frac{1}{\sqrt2}\exp\left(\frac{2}{3}x^\frac{3}{2}\right)$ and $\mathbf{M}(x)\sim\frac{1}{\pi^\frac{1}{2}x^\frac{1}{4}}$. Introduce the phase parameter $\theta(x):=\arctan\left(\frac{\mathbf{E}^2(x)Ai(x)}{Bi(x)}\right)$. Then $Ai$ and $Bi$ are related by:
    \begin{equation}
        Ai(x)=\frac{\mathbf{M}(x)}{\mathbf{E}(x)}\sin\theta(x),~~Bi(x)=\mathbf{M}(x)\mathbf{E}(x)\cos\theta(x).
    \end{equation}
    In terms of $Ai'$ and $Bi'$, further define a new modulus function $\mathbf{N}$ and phase function $\omega(x)$ by:
        \begin{equation*}
        \begin{split}
                   & \mathbf{N}(x):=\left\{\begin{array}{cc}
\sqrt{\frac{Ai'^2(x)Bi^2(x)+Ai^2(x)Bi'^2(x)}{Ai(x)Bi(x)}},~~x>c\\
\sqrt{Ai'^2(x)+Bi'^2(x)},~~x\le c
        \end{array}\right.\\&   \omega(x):=\left\{\begin{array}{cc}
           \arctan\left(\frac{Ai'(x)Bi(x)}{Ai(x)Bi'(x)}\right),~~x>c\\
           \arctan\left(\frac{Ai'(x)}{Bi'(x)}\right),~~x\le c
        \end{array}\right..
        \end{split}
    \end{equation*}
    Then $Ai'$ and $Bi'$ are related by:
    \begin{equation}
         Ai'(x)=\frac{\mathbf{N}(x)}{\mathbf{E}(x)}\sin\omega(x),~~Bi'(x)=\mathbf{N}(x)\mathbf{E}(x)\cos\omega(x).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:GeoErgcond of arXiv:2606.11677, 'Feynman--Kac formula for the heat equation with a one-center point interaction in $d=3$.'] ([Bax05])
Suppose $X$ satisfies the following conditions:
\begin{enumerate}[label=(\roman*)]
\item \textit{Minorization condition}. There exists $B\in \mathcal{B}({\mathbb{R}}^d)$, $\tilde{\beta}>0$ and a probability measure $\nu$ on $({\mathbb{R}}^d,\mathcal{B}({\mathbb{R}}^d)$ such that \begin{align*}
P(x,A)\geq \tilde{\beta}\nu(A)
\end{align*} 
for any $x\in B$ and $A\in \mathcal{B}({\mathbb{R}}^d)$.
\item \textit{Drift condition}. There exist a measurable function $V:{\mathbb{R}}^d\to [1,\infty)$ and  constants $\lambda<1$ and $K<\infty$ satisfying \begin{align*}
\int_{{\mathbb{R}}^d}V(y) P(x,\text{\rm d} y)\leq \begin{cases}
\lambda V(x),\quad &x\not\in B\\
K,\quad &x\in B.
\end{cases}
\end{align*}
\item \textit{Strong aperiodicity condition}. There exists $\beta>0$ such that $\tilde{\beta}\nu(C)\geq \beta$. 
\end{enumerate}
Then, $X$ is $V$-uniform ergodic, where $V$ is a measurable function given in (item:Drift of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:multiplier-estimate of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] The multiplier satisfies
\begin{equation}
\ell_{\varepsilon,f}\in C^{0,\alpha}_{\gamma+2}(\Gamma),
\qquad
\|\ell_{\varepsilon,f}\|_{C^{0,\alpha}_{\gamma+2}}
\le
C\left(
\varepsilon\|f\|_{C^{2,\alpha}_\gamma}
+\varepsilon^3
\right).
\end{equation}
Define
\begin{equation}
\Delta_\varepsilon(f)
:=
\Pi_{\varepsilon,f}
\left[
N_\varepsilon(U_{\varepsilon,f}+v_{\varepsilon,f})
-
N_\varepsilon(U_{\varepsilon,f})
\right].
\end{equation}
Then
\begin{equation}
\|\Delta_\varepsilon(f)\|_{C^{0,\alpha}_{\gamma+2}}
\le C\varepsilon^3,
\end{equation}
and
\begin{equation}
\ell_{\varepsilon,f}
=
-\varepsilon\left[J_\Gamma f+\mathcal Q_\Gamma(f)\right]
+\varepsilon^3G_{\varepsilon,f}
+\Delta_\varepsilon(f).
\end{equation}

[Lem property:distance-points of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] Assume that the event $F$ holds. Then
\begin{enumerate}[(a)] 
\item No two distinct points of $\mathscr{S}^{\bullet}\cup \mathscr{S}^{\circ}\cup \{v_k:k\neq i,j\}$ are within distance $c_1c_2R^{-f}$ of each other;
\item Given any $z\in \mathscr{S}^{\bullet}\cup \mathscr{S}^{\circ}\cup \{v_k:k\neq i,j\}$, changing the state of sites in $B\!\left(z,\frac{1}{2}c_1c_2R^{-f}\right)$ does not change the distance between $v_i$ and $v_j$ in $\intt\phi$;
\item Upon resampling all of the open connections between clusters in $\mathscr{S}^\circ$, the clusters of $\mathscr{S}^{\bullet}$ are still connected via closed paths to both $v_i$ and $v_j$.
\end{enumerate}

[Theorem thm:cyl-ball of arXiv:2512.06984, 'Infinite Dimensional Multifractal Analysis of the Wiener measure'] Let $ \bar{\omega} \in \Omega$. For every $ \varepsilon > 0 $ and every $n$ such that $ \Delta_n ( \bar{\omega} ) < \varepsilon $, we have
        \begin{equation*}
                W( B ( \bar{\omega} , 3 \varepsilon ) ) \ge \mathrm{exp} ( -   2 n^{2} \varepsilon^2 ) \cdot W ( \mathcal{C}_n ( \bar{\omega} , \varepsilon) )  \; . 
        \end{equation*}

[Prop PropIntegerMoments of arXiv:2602.08739, '\large \bf MOMENTS OF C$\beta$E FIELD PARTITION FUNCTION, $\mathsf{Sine}_{\beta}$ CORRELAT'] Let $\beta,\delta,s>0$ and $m \in \mathbb{N}$ be such that $2s(2\delta-(m+1)s)>\beta$ and $4m(\delta-m s)s>\beta$. Then, we have, as $N \to \infty$,
\begin{equation}
\mathbb{E}\left[\left(\int_{-\pi N}^{\pi N}\left|\mathfrak{q}_N^{\beta,\delta}(\mathrm{e}^{\mathrm{i}x/N})\right|^{2s}\mathrm{d}x\right)^m\right]\longrightarrow \mathbb{E}\left[\left(\int_{-\infty}^\infty \left|\tilde{\boldsymbol{\xi}}^{\beta,\delta}(x)\right|^{2s}\mathrm{d}x\right)^m\right].
\end{equation}

