[Prop valoriHgamma of arXiv:2506.08202, 'Stochastic dissipative systems in Banach spaces driven by L\'evy noise'] Let $\delta\geq 0$. Assume that $\nu(H\setminus H_\delta)=0$, $m =0$,   and  
\begin{equation}
\int_H{\left|z\right|}_\delta^2\nu(dz) = \int_{H_{\delta}}{\left|z\right|}_\delta^2\nu(dz) <+\infty. 
\end{equation}
Then the following statements hold.
\begin{enumerate}
\item $\{L(t)\}_{t\geq 0}$ is a Lévy process on $H_\delta$.
\item $\{L_A(t)\}$ is a mean square continuous $H_{\gamma}$-valued stochastic process, for every $\gamma<1/2+\delta$,  namely for every $t_0\geq 0$ we have
\begin{equation}
\lim_{t\rightarrow t_0}\mathbb{E}\left[{\left\|L_A(t)-L_A(t_0)\right\|}_\gamma^2\right]=0,
\end{equation}
in the case $t_0=0$ we consider only the right limit in (equation Mean-cont of the paper).
\end{enumerate}

