 \quad\text{and}\quad
 \partial_tu(t,x)=-\frac12(u_{xx}(t,x)+mu_x(t,x)^2).
\end{equation*}
Differentiating $Q(t,x)=\rho_t(x)e^{-mu(t,x)}$ twice in $x$ and once in $t$ gives $\partial_tQ(t,x)=\partial_{xx}Q(t,x)/2$. If $t\in(0,1)$ is a jump point of $\gamma$, the continuity of $u$ and $\rho$ in $t$ gives
\begin{equation*}
 \frac{Q(t,x)}{Q(t-,x)}
 =e^{-(\gamma(t)-\gamma(t-))u(t,x)},
 \qquad \forall x\in\R,
\end{equation*}
which proves","release_manifest_digest":"sha256:f00e0708bfb477ac969dcacf5baa9a6c269b8e1bd205a7efb064f5c236efbfe5","revision_digest":"sha256:76883d22a0b461a59558d700d5a3b0a06de27ac5abeed62c7410061dd63ad1cb","source_id":"arxiv:2607.18032","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

body:
[Proposition prop:mart_bound of arXiv:2411.07878, 'Bernstein-type and Bennett-type inequalities for unbounded matrix martingales'] Let $(\mathbf{Y}_i)_{i=1}^n \subset \mathbb{H}(d)$ be a matrix-valued stochastic process adapted to filtration $(\mathscr{F}_i)_{i=1}^n$. 
    Define
    \begin{gather*}
        \mathbf{V}_i \coloneqq \ln \E\left[e^{\mathbf{Y}_i} \middle| \mathscr{F}_{i-1}\right] \in \mathbb{H}(d), \quad i = 1, \dots, n,\\
        \mathbf{Z}_k \coloneqq \sum_{i=1}^k (\mathbf{Y}_i - \mathbf{V}_i), \quad k = 0, \dots, n.
    \end{gather*}

    Then for any $\mathbf{A} \in\mathbb{H}(d)$ it holds that
    \begin{equation}

        \E\left[\tr \exp\left\{\mathbf{Z}_k - \mathbf{A} \right\} \middle| \mathscr{F}_{k-1}\right] 
        \le \tr \elr{\mathbf{Z}_{k-1} - \mathbf{A}} \text{~~a.s.\ for all~~} k \in [n],
    \end{equation}
    and
    \[
    \mathbb{P}\lrc{\max_{k \in [n]} \lambda_{\max}\left(\mathbf{Z}_k - \mathbf{A}\right) \ge 0}
    \le \tr e^{-\mathbf{A}} .
    \]

