body:
[Theorem thm:grav-GAF-poisson-diameters of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] Let $  \mathscr   C= \{B_{ i};i\geqslant 1\}$ the Coulomb partition associated to a point process $ \mathsf{P}.$ There exist $ C_{ -},C_{  + }<\infty $  depending on the dimension such that the following holds.
\begin{itemize}
\item  Case $\mathsf{P} =  \mathsf{P}^{   { \mathsf{ GAF}}}$  on $  \mathbb C $ [NSV]:    Then a.s. the $ B_{ i}$ are bounded and 
\begin{align*}
C_{ -}\exp(-C_{  + }R\ln(R)^{ 3/2})\leqslant  \mathbf P (  { \rm diam}(B_{*})>R)\leqslant C_{  + }\exp(-C_{ -}R\ln(R)^{ 3/2})
\end{align*}
\item  Let $ \mathsf{P} = \mathsf{P}^{ \text{\rm{Poi}}(1)}$ in dimension $ d\geqslant 3$   [CPPR]. Then a.s. the $ B_{ i}$ are bounded and
\begin{align*}
 \mathbf P (  { \rm diam}(B_{ *})>R)\leqslant C_{  + }\exp(-C_{ -}R(\ln(R))^{ \alpha _{ d}})
\end{align*}
where $ \alpha _{ 3} > \frac{ 4}{3}$ and $ \alpha _{ d} = \frac{ d-2}{d}$ for $ d\geqslant 4.$
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:kappaFormulas of arXiv:2609.03094, 'Discrete Gromov--Wasserstein Duality: Algorithms and Isomorphism Testing'] Fix a graph $G\in\mathcal G_N$ with $m>0$ edges. Then, $\kappa(G,G)\geq m+4$ with equality if and only if $G=G_{ij}$ for some $i,j\in[N]$ with $i\neq j$. Furthermore, for each $i,j\in[N]$ with $i\neq j$,
 \begin{equation}

            \kappa(G,G_{ij}) = \begin{cases} 2(\mathrm{deg}(v_i(G))+\mathrm{deg}(v_j(G)))+1, & \text{if } (\mathrm{A}_G)_{ij}=1 ,
            \\
            2(\mathrm{deg}(v_i(G))+\mathrm{deg}(v_j(G))),&\text{otherwise},
            \end{cases}
      \end{equation}
        where $v_i(G)$ denotes the $i$-th vertex of $G$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary of arXiv:2609.00105, 'Weighted composition operators and classification of weighted Hardy spaces'] Let $\mathcal{H}$ be a weighted Hardy space with the scalar Pick property and let $\rho$ be a bounded non-zero functional on $\mathcal{H}$. Then the following are equivalent.
    \begin{enumerate}
        \item $\rho(\phi g)=\rho(\phi)\rho(g)$ for all $\phi\in\operatorname{Mult}(\mathcal{H})$ and all $g\in\mathcal{H}$;
        \item $\rho(fg)=\rho(f)\rho(g)$ whenever $f,g\in\mathcal{H}$ such that $fg\in\mathcal{H}$.
    \end{enumerate}

[Lemma lem:gauge_change_loop of arXiv:2506.12171, 'The multinomial dimer model'] Let $G=(V,E)$ be a finite bipartite graph. The weight function $\mathbf w : E\to \mathbb{R}$ is gauge equivalent to the uniform weight function if and only if for every loop $\gamma$ of $G$, we have 
    \begin{align}
        w_{e_1}w_{e_3}\dots w_{e_{2k-1}} = w_{e_2} w_{e_4}\dots w_{e_{2k}}
    \end{align}
    where $e_1,\dots, e_{2k}$ are the edges around $\gamma$.

