[Thm 41 (Wasserstein contraction) of arXiv:2509.06869, 'Infinite Interacting Brownian Motions and EVI Gradient Flows'] Suppose \ref{ass:CE}, ~\ref{ass:ConditionalClos} and  Assumption~\ref{a:AP}.  Then, for $1 \le p <\infty$, 
\begin{align}
\mssW_{p, \mssd_\U}\bigl(\mathcal T_t^{\U, \QP}\nu, \mathcal T_t^{\U, \QP}\sigma\bigr) \le e^{-Kt}\mssW_{p, \mssd_\U}(\nu, \sigma)  \cquad  t>0 \cquad  \nu, \sigma \in \mcP_\Theta \fstop
\end{align}
In particular, $\mcT_t^{\U, \QP}$ can be extended to the $\mssW_{p, \mssd_\U}$-completion and 
\begin{align}
\mssW_{p, \mssd_\U}\bigl(\mathcal T_t^{\U, \QP}\nu, \mathcal T_t^{\U, \QP}\sigma\bigr) \le e^{-Kt}\mssW_{p, \mssd_\U}(\nu, \sigma)  \cquad  t>0 \cquad  \nu, \sigma \in \overline{\mcP_\Theta}^{\mssW_{p, \mssd_\U}} \fstop
\end{align}

