[Proposition prop:gaussian of arXiv:2609.02304, 'Bayes-Optimal BER and AUC: \\Estimation and Evaluation of Estimators'] Under the shared-covariance Gaussian mixture model described above,
  the optimal BER and AUC are given by
  \begin{equation}
    \mathrm{BER}^* = \Phi\paren{- \frac{J}{2}}
    \text{,} \quad
    \mathrm{AUC}^* = \Phi\paren{\frac{J}{\sqrt{2}}}
    \text{,}
  \end{equation} 
  where
  $\Phi$ is the cumulative distribution function of 
  the standard normal distribution and
  $J \coloneqq \sqrt{(\mu_1 - \mu_0)^\top \Sigma^{-1} (\mu_1 - \mu_0)}$
  is the Mahalanobis distance between $\mu_{0}$ and $\mu_{1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:exMetr of arXiv:2604.16206, 'Extrapolation of max--stable random fields with Fr\'echet marginals'] Let  the random vector $\mathbf{X}$ be as in Theorem (Em:MC:l of the paper).
    For every vector $\mathbf{w}=(w_1,\ldots,w_n)\in \mathbb{R}_+^n$ and $\gamma_k\in[0,w_k]$,  $k=1,\ldots,n$,   
    it holds
    \begin{equation}
 \mathcal{E}_{H_\alpha} (M(\mathbf{w},\mathbf{X}), \gamma_k X_k)= \frac{1}{\gamma_k^\alpha +1}-\frac{1}{l_\mathbf{X}(\mathbf{w}^\alpha)+1}.
\end{equation}
 Let the extended random vector $\mathbf{X}_e=(X_0,\mathbf{X})$ be max--stable   with $H_\alpha$--distributed marginals and tail dependence function $l_{\mathbf{X}_e}$. For $\gamma_0\geq 0$, we have
    \begin{align}
    \mathcal{E}_{H_\alpha} (M(\mathbf{w},\mathbf{X}), \gamma_0 X_0)= \frac{1}{\gamma_0^\alpha+1} +\frac{1}{l_\mathbf{X}(\mathbf{w}^\alpha)+1}- \frac{2}{l_{\mathbf{X}_e}((\gamma_0^\alpha,\mathbf{w}^\alpha))+1}.
    \end{align}

