body:
[Theorem 2 (Quantitative propagation of chaos) of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] Fix $k, N \in \bbN$. Let $v \subset \{1, \ldots, N\}$ satisfy $|v| = k$. There exist constants $c_0, c_1 \in (0, \infty)$ such that for every $t\leq T, r\geq 0$ and  every $f:\mC_t^k\to \R$ that satisfies one of the following:
\begin{enumerate}
    \item $f$ is 1-Lipschitz in the $L^2([0, t]; \R^k)$ norm, that is
    \[|f(x)-f(y)|^2\leq \int_0^t |x_s-y_s|^2\,ds, \quad x, y \in \mC^k_t.\] 
    \item There exists $s \in [0, t]$ such that $f(x) = f_s(x_s)$ for a 1-Lipschitz function $f_s:\R^k \rightarrow \R$.
\end{enumerate}
Then we have
\begin{equation}

\bbP\bigg(\,\bigg| \int f(x) \,d\Big( P^{N, v}_{[t]}(\bfJ) - \mu^{\otimes k}_{[t]}\bigg)(x) \bigg|\geq r \bigg) \leq c_0e^{-c_1 r^2\frac{N}{k}}.
\end{equation}
Moreover there exists a constant $C \in (0, \infty)$ such that for all $t \in [0, T]$, we have
\[\bbE\Big[\bbW_1\big(P_{t}^{N,v}(\bfJ), \mu^{\otimes k}_t\big)\Big] \leq \left \{ \begin{aligned}
    & \frac{C}{\sqrt N}, &\quad & k =1\\
    & \frac{C\log N}{\sqrt N}, &\quad & k =2 \\
    &  \frac{Ck}{N^{1/k}}
    , &\quad &k \geq 3.
\end{aligned} \right. \] (Proof in the paper; no proof environment follows the statement in the TeX.)

