[Lemma lem_an_tube_scale of arXiv:2411.13972, 'The Stochastic Bessel operator at high temperatures'] ~\\
For any $x_0<0$, 
\begin{equation*}
\mathfrak{s}'_\beta\longrightarrow \mathfrak{s}' \text{ and } \mathfrak{s}_\beta \longrightarrow \mathfrak{s} \text{ uniformly on }[x_0, 0].
\end{equation*}
Furthermore, $\mathfrak{s}_\beta\big(l_2\big)\longrightarrow \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:iter_int_of_mal_der of arXiv:2604.22528, 'Malliavin calculus for signatures with applications to finance'] For all $i_1, \ldots, i_n \in \{1, \ldots, d\}$ and $j_1, \ldots, j_n \in \{0, 1, \ldots, d\}$, we have
    \begin{equation*}
        \int_{0 \le s_1 \le \ldots \le s_n \le t} 
        (\mathbf{D}_{s_1}^{i_1} \ldots \mathbf{D}_{s_n}^{i_n} \sig) \circ d\widehat{W}_{s_1}^{j_1} \ldots \circ d\widehat{W}_{s_n}^{j_n} 
        = {\bf \Psi}_{{\color{NavyBlue}{\mathbf{i_1, \ldots, i_n}}}}^{{\color{NavyBlue}{\mathbf{j_1, \ldots, j_n}}}} (\sig).
    \end{equation*}
    Moreover, for all $\bm{\ell} \in \TA[d+1]$,
    \begin{equation*}
        \int_{0 \le s_1 \le \ldots \le s_n \le t} 
        \mathbf{D}_{s_1}^{i_1} \ldots \mathbf{D}_{s_n}^{i_n} \langle \bm{\ell}, \sig \rangle 
        \circ d\widehat{W}_{s_1}^{j_1} \ldots \circ d\widehat{W}_{s_n}^{j_n} 
        = \bracketsigW{ {\bf \Psi}^{{\color{NavyBlue}{\mathbf{i_1 \ldots i_n}}}}_{{\color{NavyBlue}{\mathbf{j_1 \ldots j_n}}}} (\bm{\ell}) }.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:inverse_kasteleyn_matrix of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] {borodin-gr2009q}}]

	The inverse Kasteleyn matrix is expressed through the two-dimensional correlation kernel
	$\widetilde{K}$ (equation eq:K_kernel_two_dimensional of the paper)
	as follows:
	\begin{equation}

		\mathrm{Kast}^{-1}\left( s,x;t,y \right)
		=
		\frac{G(s,x)}{G(t,y)}
		\frac{\mathbf{1}_{s=t}\mathbf{1}_{x=y}- \widetilde{K}(s,x;t,y)}{\mathsf{w}_{q,\kappa}(x-\tfrac s2+1)},
	\end{equation}
	where
	$(s,x)$ and $(t,y)$ are the coordinates of a black (resp., white) triangle.
	The factor $G$ is
	\begin{equation}

		G(t,x)\coloneqq
		\frac{1}{\sqrt{\widetilde{w}_t(x)}}
		\frac{(-1)^{x} \kappa^{-t}
		q^{x(T+N-t-1)+t(S/2-1/2)+t(t+1)/4} \left(1-\kappa^2 q^{2x-t-S+1}\right)}
		{(\frac{1}{q}; \frac{1}{q})_{S+N-1-x} (q;q)_{T-S+x-t} (\kappa^2 q^{x-T+1}; q)_{T+N-t}}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop-Burkholder inequality of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] For every $p \ge 2$,
 there exists $c(p) >0$ such that for every process $F$ as in Proposition (prop-Ito integral of the paper) and for every $T\geq 0$, the following inequality holds
  \begin{equation}  
  \begin{aligned}
\mathbb{E} \Big[\sup_{0 \le s \le T} |Z_s\vert^p\Big]
     \le  c(p)
   \mathbb{E} \left[ \Bigl(\int_0^T \int_{C}|F(s,z)\vert^2  \nu(d z)ds \Bigr)^{p/2}
 +
 \,  \int_0^T \int_{C}|F(s,z)\vert^p  \nu(dz)ds\right].
 \end{aligned}
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 56 (Finite Brownian blocks) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] Let
\[
 \mathcal L^{(d)}
 :=\operatorname{Alt}_2\int_0^1B_t\otimes\mathop{}\!\mathrm dB_t
\]
for standard Brownian motion in \(\mathbb R^d\), with the same
half-commutator normalization as in
\eqref{cc:eq-critical-martingale-area}.  There are numerical constants
\(a,\eta,c_0>0\) such that
\begin{align}
 \mathbb P\left\{s_{\lfloor\eta d\rfloor}
       (\mathcal L^{(d)})\geq a\right\}&\longrightarrow1,
 \\
 \mathbb P\left\{s_k(\mathcal L^{(d)})
       \geq c_0\frac d k,\ 1\leq k\leq m\right\}
 &\geq1-\varepsilon

\end{align}
for every fixed \(m\) and \(\varepsilon>0\), once the even dimension \(d\)
is sufficiently large.

[Lemma 20 of arXiv:2608.13235, 'Mixing Properties of Random Laguerre Tessellations'] Let $a > 0$ and denote $\Hat{\Theta}_{r,K_3,K_1} \coloneqq (E^3_{r,K_3} \cup E^1_{(K_3+1)r,K_1})^c$ for $r \geq \max \{a,1\}$ and $K_1,K_3  > 0$. Then for any $\mathsf{A} \in \tailF{a}^1$ we have
    \begin{align} 
        \Hat{\Theta}_{r,K_3,K_1} \cap \{\varphi: L(\varphi) \in \mathsf{A}\} = \Hat{\Theta}_{r,K_3,K_1} \cap \{\varphi: L(\varphi \cap (K_1(K_3+1)rB^d \times \R)) \in \mathsf{A}\}.
    \end{align}

