[Lemma 7 (Action of $L^{X^{(N)}}$ on $h_m^{(N)}$) of arXiv:2606.00781, '2606.00781'] The generator $L^{X^{(N)}}$ acts on $h_m^{(N)}$ via
   \begin{equation} 
      L^{X^{(N)}}h_m^{(N)}
      \ =\ \sum_{k=1}^m \varphi(k,m)h_{m-k}^{(N)} - 2\varphi(m)h_m^{(N)},
      \qquad m\in\{0,\ldots,N\},
   \end{equation}
   where $\varphi(.,.)$ and $\varphi(.)$ are defined via (\ref{lambda_rep}) and
   (\ref{totalrate}). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma thm:alt_to_un of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] Let $\lambda \in \Sig_n, \nu \in \Sig_{n-1}$ be fixed, let $r\in\mathbb{Z}_{\ge 0}$ be sufficiently large, and let $\kappa=(r+|\lambda|-|\nu|,\nu_1,\ldots,\nu_{n-1})$. Let $A,B \in \Mat_n(\tilde{F})$ be two matrices with i.i.d. additive Haar entries chosen from a degree $2$ unramified extension $\tilde{F}$ of $F$. Then
\begin{equation}
\mathbf{P}_{(r)\lambda}^{\alt,\kappa} = \mathbf{P}(\SN(AB)=\kappa\mid \SN(A)=\lambda, \SN(B)=(r)),
\end{equation}
where $\mathbf{P}_{(r)\lambda}^{\alt,\kappa}$ is as defined in (thm:Product process of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 24 of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] Let $F \in \bW^{k+1, p}$, $\Delta_F^{-1} \in L^q(\Omega)$, and $G \in \bW^{k, r_0}$ for some $k \in \N$ and $p, q, r_0 \in (1, \infty)$. 
Define $r_j, \  j \in \{1, \ldots, k+1\}$ by \eqref{r_k def}.
If $r_{2j} > 1$ for some $j \in \{1, \ldots, \floor{\frac{k+1}{2}}\}$, then for every $i \in \{1, \ldots, j\}$, we have $\Upsilon_F^{\circ i}(G) \in \bW^{k-2i, r_{2i}}$ and 
\begin{equation}
    \norm{\Upsilon_F^{\circ i}(G)}_{\bW^{k - 2i, r_{2i}}} 
    \lesssim_{i, k, p, q, r_0} 
    \norm{G}_{\bW^{k,r_0}}(1+\norm{F}_{\bW^{k+1, p}}^2)^{2i(k-i+1)}(1+\norm{\Delta_F^{-1}}_{L^q(\Omega)})^{i(2k-2i+3)}.
\end{equation}

