		Let $d>6$. For the nearest neighbour model for which the two point function satisfies~(equation twopoint of the paper) and for the sufficiently spread out percolation model we have 
		\begin{equation}
			\mathbb P(0\longleftrightarrow \partial B(0,r)) \asymp \frac 1{r^2}. 
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 (Bounds for lower-chaos contraction kernels) of arXiv:2608.29726, '\LARGE A Priori Estimates for Singular Fractional Stochastic Burgers Equations'] Assume
\[
 \frac{\delta}{3}<q\le\frac{2\delta}{5},
\]
For \(\zeta=(\omega,k)\), \(\zeta'=(\omega',k')\), and
\(\zeta''=(\omega'',k'')\), uniformly in \(\eps\),
\begin{subequations}
\begin{equation}
\begin{aligned}
 &\sum_{K\in2^{\mathbb N_0}}
 \left|
 \sum_{1+\abs k\asymp K}\int_\R
 \abs{H_\alpha^\eps(\zeta)}^2
 \chi_\odot(-k,k+k')
 M_\gamma(\zeta+\zeta')\,\dd\omega
 \right|
 \lesssim
 \langle\zeta'\rangle_\gamma^{\delta-2q}.
\end{aligned}
\end{equation}
and
\begin{equation}
\begin{aligned}
 \left|
 \int_{\R\times\mathbb Z}
 \abs{H_\alpha^\eps(\zeta)}^2
 \chi_\odot(-k,k+k')
 M_\gamma(\zeta'-\zeta)M_\gamma(\zeta''-\zeta)\,\dd\zeta
 \right| \lesssim
 \max\left\{\langle\zeta'\rangle_\gamma,
        \langle\zeta''\rangle_\gamma\right\}^{-2q+}.
\end{aligned}
\end{equation}
\end{subequations}

[Lemma 10 of arXiv:2608.01081, 'The Optimal Rate in the Averaged Random-Marginal Central Limit Theorem for Log-Concave Mea'] The matrix $B$ satisfies
\begin{equation}
 \norm B_{\HS}\le8\sqrt n.
\end{equation}

[Lemma 31 of arXiv:2511.02725, 'Mixing of general biased adjacent transposition chains'] There exist constants $C_{\mathsf{block}}>0$ (independent of $\eps$), $C_{\mathsf{block}}'(\eps) = e^{O(1/\eps)}$, $n_0 = O (\log(1/\eps)/\eps)$ and $n_1 = e^{O(1/\eps)}$, such that 
    \begin{itemize}
        \item for all $N\ge n_1$, the inverse gap of the block dynamics restricted to $\vec{\ell}\loc$ for $\vec{\ell}\in \mathcal L_N$ is at most $C_{\mathsf{block}}$;
        \item for all $N\in [n_0,n_1]$, the inverse gap of the block dynamics restricted to $\vec{\ell}\loc$ for $\vec{\ell}\in \mathcal L_N$ is at most $C_{\mathsf{block}}'(\eps)$.
    \end{itemize}

