[Lemma lem:R(t) of arXiv:2506.15949, 'On the passage times of self-similar Gaussian processes on curved boundaries'] $\mathscr{R}(t)<\infty$ for one, hence all $t>0$, if and only if
	\begin{equation}
		\gamma >  \frac{\beta}{2-\nu}.
	\end{equation}

[Lem 50 of arXiv:2605.27974, 'Discrete approximation of semi-Dirichlet forms with non-symmetric perturbations of resista'] For any $\alpha > \lambda$ and $f \in C(X)$, we have the following: 
\begin{equation}
\limtoinfty{n}\norm{
\tilde{G}^{n}_{\alpha}f\lvert_{V_{n}}
-(\tilde{G}_{\alpha}f)\lvert_{V_{n}}
}_{\infty}=0.
\end{equation}
\begin{proof}
For the sake of simplicity, let $\mathscr{H}_{n}$ (resp.\ $\mathscr{H}$) denote $L^2(V_{n},\mu_{n})$ (resp.\ $L^2(X,\mu)$). 
For any $n \in \N$, by Proposition~\ref{prp5}, we have 
\begin{align}
\mathcal{E}^{n}_{1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}])
\leq
\mathcal{E}^{n}_{\lambda+1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}])
\leq
(1-s)^{-1}\mathcal{A}^{n}_{\lambda+1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}]).
\end{align}
Thus we obtain $\supover{n}\mathcal{E}^{n}_{1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}]) < \infty$
since the following holds:
\begin{align}
\mathcal{A}^{n}_{\lambda+1}({G}^{n}_{\alpha}[f\lvert_{V_{n}}])
&=([f\lvert_{V_{n}}],{G}^{n}_{\alpha}[f\lvert_{V_{n}}])_{\mathscr{H}_{n}}
+(\lambda+1-\alpha)\norm{{G}^{n}_{\alpha}[f\lvert_{V_{n}}]}^{2}_{\mathscr{H}_{n}} \\
&\leq
\norm{{G}^{n}_{\alpha}}_{\mathrm{op}}
\norm{[f\lvert_{V_{n}}]}^{2}_{\mathscr{H}_{n}}
+\abs{\lambda+1-\alpha}
\norm{{G}^{n}_{\alpha}}^{2}_{\mathrm{op}}
\norm{[f\lvert_{V_{n}}]}^{2}_{\mathscr{H}_{n}} \\
&\leq
\left\{(\alpha-\lambda)^{-1}+\abs{\lambda+1-\alpha}(\alpha-\lambda)^{-2}\right\}
\norm{f}^{2}_{\infty} < \infty.
\end{align}
On the other hand, since $[f\lvert_{V_{n}}] \in \mathscr{H}_{n}$ strongly K-S converges 
to $[f] \in \mathscr{H}$ and ${G}^{n}_{\alpha}$ strongly K-S converges to ${G}_{\alpha}$ 
by Proposition~\ref{main1}, ${G}^{n}_{\alpha}[f\lvert_{V_{n}}] \in \mathscr{H}_{n}$ 
strongly K-S converges to ${G}_{\alpha}[f] \in \mathscr{H}$. Therefore, we obtain the conclusion 
from Corollary~\ref{cor2} and Proposition~\ref{cptop}, noticing that 
$[\tilde{G}_{\alpha}f]=G_{\alpha}[f]$ 
(resp.\ $[\tilde{G}^{n}_{\alpha}f\lvert_{V_{n}}]=G_{\alpha}^{n}[f\lvert_{V_{n}}]$)
holds by Proposition~\ref{resolvdouitu}.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:clconvhull of arXiv:2605.10491, 'Zero-couplings of infinite measures with cyclically monotone support and multivariate regu'] Let $\psi : \mathbb{R}^d \to \mathbb{R} \cup \{\infty\}$ be a closed convex function and let $D \subset \mathbb{R}^d$ be such that $D \cap \operatorname{dom} \psi \ne \varnothing$. Define the function $\phi$ by $\phi = \operatorname{cl}(\operatorname{conv} g)$, where $g(x) = \psi(x)$ if $x \in D$ and $g(x) = \infty$ if $x \in \mathbb{R}^d \setminus D$. Then $\phi$ is a closed convex function with the following properties:
	\begin{enumerate}[label=(\alph*)]
		\item $\phi \geqslant \psi$;
		\item $\phi(x) = \psi(x)$ for $x \in D$;
		\item $\partial \phi(x) = \{ v \in \mathbb{R}^d : \forall z \in D, \, \psi(z) \geqslant \psi(x) + \langle{z-x,v}\rangle \} \supset \partial \psi(x)$ for $x \in  D$;
		\item $\operatorname{dom} \nabla \phi \subset \operatorname{dom} \partial \psi$;
		\item $D \cap \operatorname{dom} \nabla \phi \subset \operatorname{dom} \nabla \psi$ and $\nabla \phi(x) = \nabla \psi(x)$ for all $x \in D \cap \operatorname{dom} \nabla \phi$.
	\end{enumerate}

[Theorem 1 (Sharp Poincar\'e interpolation) of arXiv:2607.10769, '\fontsize{14}{17}\selectfont\bfseries Sharp Poincar\'e interpolation along Wasserstein geo'] For every $t\in[0,1]$, we have
\begin{equation}
 \Var_{\mu_t}(f)
 \leq\left(\frac{1-t}{\sqrt{\kappa_0}}
           +\frac{t}{\sqrt{\kappa_1}}\right)^2
       \int|\nabla f|^2\,\d\mu_t,
       \qquad\text{for every }f\in C_c^\infty(\R^n).
\end{equation}
Equivalently,
\[
 \sqrt{C_P(\mu_t)}\leq \frac{1-t}{\sqrt{\kappa_0}}
+\frac{t}{\sqrt{\kappa_1}}.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

