[Lem 5 of arXiv:2607.24166, 'Strong rate of convergence for the Euler--Maruyama scheme of additive fractional SDEs with'] Let $q \ge 2$. Suppose that there exist measurable functions $\mathcal{A} \colon \Omega \times [0,1] \to \mathbb{R}^d$, $A \colon \Omega \times \Delta_{[0,1]}^{\mathrm{shift}} \to \mathbb{R}^d$ and a complete filtration $(\mathcal{F}_t)_{t \in [0,1]}$ such that the following holds:
    \begin{enumerate}
        \item There exists a process $\cA = \{\cA_t : t \in [0, 1]\}$ such that for any $(s, t) \in \Delta_{[0, 1]}$
        \begin{equation}
        \mathcal{A}_t - \mathcal{A}_s = \lim_{m \to \infty} \sum_{i=1}^{m-1} A_{s+i\frac{t - s}{m}, s+(i+1)\frac{t - s}{m}} \text{ in probability.} 
        \end{equation}

        \item for any $(s,t) \in \Delta_{[0,1]}^{\mathrm{shift}}$, the random variable $A_{s,t}$ is $\mathcal{F}_t$-measurable;

        \item there exist $\Gamma_1, \Gamma_2, \varepsilon_1, \varepsilon_2 > 0$ such that for every $(s,t) \in \Delta_{[0,1]}^{\mathrm{shift}}$ and $u = (s+t)/2$ we have
        \begin{align}
        \| A_{s,t} \|_{L^q} &\le \Gamma_1 |t - s|^{1/2 + \varepsilon_1}, \\
        \| \mathbb{E}^{s-(t - s)} \delta A_{s,u,t} \|_{L^q} &\le \Gamma_2 |t - s|^{1 + \varepsilon_2}. 
        \end{align}
    \end{enumerate}
    Then there exist constants $K_1, K_2 > 0$, which depend only on $\varepsilon_1, \varepsilon_2, q$ and $d$ such that for any $0 \le s \le t \le 1$ we have
    \begin{equation}
    \| \mathcal{A}_t - \mathcal{A}_s \|_{L^q} \le K_1 \Gamma_1 |t - s|^{1/2 + \varepsilon_1} + K_2 \Gamma_2 |t - s|^{1 + \varepsilon_2}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma L:intml of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Let $T > 0$, and let $0 < s_1 \leq s_2 < T$. Denote by
    \begin{align*}
      I (s_1,s_2) \coloneqq \int_0^{\infty} \ensuremath{\mathrm{d} } x \; x^{\theta} E_{a,b} (- s_1 x) E_{a,b}(- s_2 x),
  \end{align*}
  where the parameter $\theta \in (-1,1)$.
  \begin{enumerate}[\rm (i)]
    \item Assume either $(a,b) \in (0,2) \times [a,\infty)$; or $a = 2$ and $b \in [3,\infty)$. Then, it holds that
          \begin{align}
            I (s_1, s_2)  \lesssim
            \begin{dcases}
              s_1^{-\theta} s_2^{-1},                   & \theta \in (0,1),  \\
              s_2^{-1} (1 + \log \left(s_2/s_1\right)), & \theta = 0,        \\
              s_2^{- \theta - 1},                       & \theta \in (-1,0).
            \end{dcases}
          \end{align}
    \item In case $a = 2$, $b \in (1,2) \cup (2,3]$, such that $b - \theta > 3/2$, then the next inequality is true,\footnote{The condition $b - \theta > 3/2$ is necessary to ensure the integrability of $I_{3,1,1}$ and $I_{3,1,2}$ in~(equation E_:intml-a=2-3-1-1 of the paper) and~(equation E_:intml-a=2-3-1-2 of the paper).}
          \begin{align}
            I (s_1, s_2)  \lesssim
            \begin{dcases}
              s_1^{b/2 - \theta - 3/2} s_2^{- \frac{b-1}{2}} + s_1^{-\frac{b-1}{2}} s_2^{-\frac{b-1}{2}} \left(\sqrt{s_2} - \sqrt{s_1}\right)^{2b - 2\theta -4}, & b < 2 + \theta ,               \\
              s_1^{-(b-1)/2} s_2^{-(b-1)/2} \left(1 + |\log \left((\sqrt{s_2} - \sqrt{s_1})/\sqrt{s_2}\right)| \right) ,                                         & b = 2 + \theta,                \\
              s_1^{b/2 - \theta - 3/2} s_2^{-(b-1)/2},                                                                                                           & 2 + \theta < b < 3 + 2\theta , \\
              s_2^{- \theta - 1} \big(1 + \log (s_2/s_1 )\big),                                                                                                  & b = 3 +  2\theta,              \\
              s_2^{- \theta - 1},                                                                                                                                & b > 3 + 2\theta.
            \end{dcases}
          \end{align}
  \end{enumerate}

