[Lemma lem:scaling_limit_diagrams_no_cutoff2 of arXiv:2508.18807, '{\bf Critical long-range percolation I: High effective dimension}'] We have that
\begin{equation*}
\lim_{s \to \infty} \lim_{R\to \infty} \frac{1}{\eta(R)}\mathbb E_{\beta_c,\sigma^{-1}(s R)} \left[ f(\mu_R[\psi]) \left(\mu_R[\varphi]\right)^n \right] 
= \mathbb N\left[f(\mu_R[\psi])(\mu[\varphi])^n\right]
\end{equation*}
for each pair of compactly-supported, continuous, non-negative functions $\varphi,\psi$, integer $n\geq 0$, and bounded continuous function $f:[0,\infty)\to [0,\infty)$ whose support does not contain zero. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfn 30 (Resistance form, {\cite[Definition 3.1) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {Kig12}}]
Let $F$ be a non-empty set.
A pair $(\calE,\calF)$ is called a resistance form if it satisfies the following conditions.
\begin{itemize}[leftmargin=3.5em, labelsep=0.3em]
  \item [(RF1)]$\calF$ is a linear subspace of $\R^F$ containing the constant functions.
  $\calE$ is a non-negative symmetric quadratic form on $\calF$ satisfying
  \begin{align*}
    \calE(u,u)=0\iff \text{$u$ is a constant.}
  \end{align*}
  \item[(RF2)]Let $\sim$ be an equivalence relation on $\calF$ defined by $u\sim v$ if and only if $u-v$ is constant.
  Then $(\calF/\sim,\calE)$ is a Hilbert space.
  \item[(RF3)] If $x\neq y\in F$, then there exists $u\in\calF$ such that $u(x)\neq u(y)$.
  \item[(RF4)]For any $x,y\in F$,
  \begin{align*}
    R(x,y)
    :=&\sup\left\{ \frac{|u(x)-u(y)|^2}{\calE(u,u)}:u\in\calF,\calE(u,u)>0 \right\}\\
    =&\inf\{\calE(u,u):u(x)=1,u(y)=0,u\in\calF\}^{-1}
  \end{align*} 
  is finite.
  \item[(RF5)]For $u\in \calF$, set $\bar{u}:=0\vee(u\wedge 1)$. 
  Then $\bar{u}\in\calF$ and $\calE(\bar{u},\bar{u})\leq \calE(u,u)$ hold. 
\end{itemize}
The function $R:F\times F\to[0,\infty)$ defined by (RF4) is a metric on $F$ (see \cite[Theorem 2.3.4]{Kig01}) and called the resistance metric associated with $(\calE,\calF)$.

[Proposition 4 (When the quality-constrained decision is point-identified) of arXiv:2608.29560, 'Which LLM for Which Work?\\Budgeted Model Allocation under Uncertain Evaluation'] Under Assumption~\ref{as:recover} and the admissible error set $\mathcal C$
of \eqref{eq:cset}, fix a workload $j$ with at least two candidate models. Taking
\emph{admissible} as in \S\ref{sec:rules}, call a model \emph{ambiguous} when it is admissible under
some $C\in\mathcal C$ but not all. Then
\begin{equation}
  \text{model }k\text{ is}\quad
  \begin{cases}
    \text{admissible under every }C\in\mathcal C, & D_{kj}\le\delta-\eta_j,\\[1pt]
    \text{admissible under no }C\in\mathcal C,    & D_{kj}>\delta+\eta_j,\\[1pt]
    \text{ambiguous},                             & \text{otherwise.}
  \end{cases}
\end{equation}
The decision $\pidel$ is point-identified in workload $j$ if and only if a universally admissible
model exists and no ambiguous model precedes the cheapest such model in the cost and tie-breaking
order. In particular, $|D_{kj}-\delta|>\eta_j$ for every $k$ is sufficient. (Proof in the paper; no proof environment follows the statement in the TeX.)

