body:
[Theorem thm:main of arXiv:2606.15850, 'A 0-1 Law for Multifractal Spectra\\ via the HGDS Scale Derivative'] Let $X:[0,1]\times\Omega\to\mathbb{R}$ have locally stationary increments, be
jointly measurable, and have HGDS macro derivative $\eth_\Lambda X$
defined via wavelet decomposition with parameter $H\in(0,1)$. Write
$\bar{h}(t)=\mathbb{E}[h_X(t,\cdot)]$ and $\bar D(h)=\dim_H\{t:\bar{h}(t)=h\}$.

Suppose:
\begin{align}
  &\sum_{n=1}^\infty
  \frac{\int_{e^{-n}}^1\!\int_{e^{-n}}^1
    |\mathrm{Cov}(\eth_s X(t),\eth_u X(t))|\,(su)^{-1}\,ds\,du}
  {\bigl(\int_{e^{-n}}^1\mathbb{E}[|\eth_s X(t)|]s^{-1}\,ds\bigr)^2}
  <\infty\quad\text{uniformly in }t,\tag{C-i}\\
  &\mathbb{E}\bigl[|\eth_s X(t)-\eth_s X(t')|^p\bigr]
  \le C|t-t'|^{pH}s^{p(H-1)}
  \;\text{ for some }p>2/H,\tag{C-ii}\\
  &\mathbb{E}\bigl[|\eth_s X(t)|\bigr]\asymp s^{\bar{h}(t)-1}
  \text{ as }s\to0,\;\text{uniformly in }t,\tag{C-iii}\\
  &\bar{h}(t)\text{ is not constant on any interval.}\tag{C-iv}
\end{align}
Then $D(h,\omega)=\bar D(h)$ a.s.\ for all $h\ge0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 23 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb$ and $f\in \Sob^k(\Rbb^n,\gamma_n)$,
\begin{equation}
    \Wop^{\geq k}(f) \leq \sum_{\kappa\in \Nbb^n:|\kappa|=k} \Vop^\kappa(f)  \leq \Vop^k(f) \leq \left\|\left|\grad^k f\right|\right\|_{\Leb^2}^2.
\end{equation}

