[Theorem 2 of arXiv:2608.06392, '2608.06392'] Suppose that the conditions of {\hyperref[AISRTh1]{Theorem~\ref{AISRTh1}}} hold and set $\gamma:=\alpha-2$.
    Then the deviation of the renewal convolution from the Stone constant admits the following asymptote:
\begin{equation}     
    {\mathcal{S}_\mu}-{\int_{[0,t]}Q_F(t-x)\,dU(x)}
    ={\frac{1}{\,\mu\,}}\rho(t)-2{\mathcal{S}_\mu}\,Q_F(t)\!\big(1+o(1)\big)
\end{equation}
    as $t\to\infty$, where $\rho(t)$ is entirely governed, at the asymptotic level, by the tail
    of $Q_F(t)$, namely,
\begin{equation}
    {\frac{\rho(t)}{Q_F(t)}} \sim {\frac{1}{\,\gamma\,}}\,{t} \qquad \text{as} \quad {t\to\infty}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:G of arXiv:2506.15949, 'On the passage times of self-similar Gaussian processes on curved boundaries'] \begin{compactenum}[\rm (1)]
	\item $G(t)\in \mathcal{C}_0^\infty(\mathbb{R}^d)\cap L^2(\mathbb{R}^d)$ for all $t>0$;
	\item If $0<\gamma \leqslant 2$ then $G(t)>0$ is a probability density function on $\mathbb{R}^d$ for all $t>0$;
	\item $G(t)\in L^1(\mathbb{R}^d)$ and 
		$\int_{\mathbb{R}^d} G(t\,,x)\,{\rm d} x=1$ for all $t>0$;
	\item $G(t+s)=G(t)*G(s)$ for all $t,s>0$;
	\item If $\gamma>2$, then $G(t)$ is signed for all $t>0$.
	\end{compactenum}

