[Proposition eq the jensen inequality of arXiv:2512.13200, 'Martingales on a Euclidean manifold with a boundary and reflected BSDEs in non-convex doma'] Let Assumption (ass:3 of the paper) hold, and let $\xi$ be a random variable with values in $\bar{\mathcal{D}}$. Then, there exists a unique minimizer of
    \begin{align}
        \inf_{x \in \bar{\mathcal{D}}} \ensuremath{\mathbb{E} \!\! \left[\Psi(x,\xi)\right] },
    \end{align}
    which is denoted by $\mathcal{E}(\xi)$. Moreover, we have 
    \begin{align}
        \Psi(\mathcal{E}(\xi),\mathcal{E}(\xi')) \le \ensuremath{\mathbb{E} \!\! \left[\Psi(\xi,\xi')\right] },
    \end{align}
    for all random variables $\xi,\xi'$ with values in $\bar{\mathcal{D}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 8 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] For an increasing $f\colon X\to Y$, we define $\varphi_\alpha(f)\colon\varphi_\alpha(X)\to\varphi_\alpha(Y)$ recursively as follows:
    \begin{enumerate}
        \item $\varphi_\alpha(f)(0)=0$.
        \item $\varphi_\alpha(f)(E_x)=E_{f(x)}$.
        \item $\varphi_\alpha(f)(\varphi_i(\xi))=\varphi_i(\varphi_\alpha(f)(\xi))$.
        \item For principal terms $p_0,\ldots,p_{m-1}$ in $\varphi_\alpha(X)$ with $m>1$, we define
        \begin{equation*}
        \varphi_\alpha(f)(p_0+\cdots+p_{m-1})
        =
        \varphi_\alpha(f)(p_0)+\cdots+\varphi_\alpha(f)(p_{m-1}).
        \end{equation*}
    \end{enumerate}
    We also define the support transformation $\supp^{\varphi_\alpha}_X\colon \varphi_\alpha(X)\to [X]^{<\omega}$ recursively as follows:
    \begin{enumerate}
        \item $\supp^{\varphi_\alpha}_X(0)=\varnothing$.
        \item $\supp^{\varphi_\alpha}_X(E_x)=\{x\}$.
        \item $\supp^{\varphi_\alpha}_X(\varphi_i(\xi))=\supp^{\varphi_\alpha}_X(\xi)$.
        \item For principal terms $p_0,\ldots,p_{m-1}$ in $\varphi_\alpha(X)$ with $m>1$,
        \begin{equation*}
        \supp^{\varphi_\alpha}_X(p_0+\cdots+p_{m-1})
        =
        \bigcup_{i<m}\supp^{\varphi_\alpha}_X(p_i).
        \end{equation*}
    \end{enumerate}

[Lemma Ergodic:WeakErgodic of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] Let $\nu\in C^{2,\alpha}_p(\mathbb{R}^d)$ be the density of the unique invariant measure of $(\dot{Z}_t)_{t\geq 0}$ on $
    \mathbb{T}^d$ and $f\in C^{0,\alpha}_p(\mathbb{R}^d)$ be such that $\nu(f)=0$. Fix $\epsilon>0$. There exists a constant $C=C(d,\|f\|_{0,\alpha})>0$ such that, for all $t$ sufficiently large (depending on $d$, $\|f\|_{0,\alpha}$, and $\epsilon$),
    \begin{equation}
        \sup_{x\in \mathbb{R}^d} \probbb{x}{}{\frac{1}{t}\Big|\int_0^t f(Z_s)ds \Big|>\epsilon}\leq C\epsilon^{-2}t^{-1}.
    \end{equation}

