body:
[Lemma 16 of arXiv:2606.25494, 'A functional central limit theorem for kernel gradient flow and infinitesimal gradient boo'] \begin{enumerate}[(i)]
    \item For any measurable $F:[0,1]^p\to\mathbb{R}$ and any $n\ge 1$, $\mathcal{T}_n(F)\in\mathcal{H}$ and can be written as
    \[
    \mathcal{T}_n(F)(z)
    =
    \int \Psi(\bar{\xi},v,F,\P_n)\,\1_{A_v^{\xi^1}}(z)\,Q_0^K(\mathrm{d}\bar{\xi})\,\nu(\mathrm{d}v),
    \]
    with
    \begin{equation}
    \Psi(\bar{\xi},v,F,\P_n)
    = \Psi_1(\xi^1,v,F,\P_n)\Psi_2(\bar{\xi},F,\P_n),
    \end{equation}
    where
    \begin{equation}
    \Psi_1(\xi^1,v,F,\P_n)
    = \frac{\P_n[\partial_1\ell(F(x),y)\1_{A_v^{\xi^1}}(x)]}{\P_n(A_v^{\xi^1})}
    \end{equation}
    and
    \begin{equation}
    \Psi_2(\bar{\xi},F,\P_n)
    = \prod_{w\in \mathscr{T}_{d-1}}
      \frac{\exp\!\big(\beta\,\Delta_n(j_w^{1},u_w^{1}; A_w^{\xi^1})\big)}
           {K^{-1}\sum_{k=1}^K \exp\!\big(\beta\,\Delta_n(j_w^{k},u_w^{k}; A_w^{\xi^1})\big)}.
    \end{equation}
    We recall that $(j_w^k,u_w^k)$ denotes the split at node $w$ in the splitting scheme $\xi^k$ and $\Delta_n(j,u,A)$ denotes the score of the split $(j,u)$ of $A$ as defined in Equation~\eqref{eq:score}.
    \item In the infinite-population case, for any  $F\in L^2(\P)$, we define  $\mathcal{T}(F)\in\mathcal{H}$  by the formula
    \[
    \mathcal{T}(F)(z)
    =
    \int \Psi(\bar{\xi},v,F,\P)\,\1_{A_v^{\xi^1}}(z)\,Q_0^K(\mathrm{d}\bar{\xi})\,\nu(\mathrm{d}v),
    \]
    where $\Psi(\bar{\xi},v,F,\P)\in L^2(Q_0^K\otimes\nu)$ is defined by Equations~\eqref{eq:def-Psi},~\eqref{eq:def-Psi1},~\eqref{eq:def-Psi2} with $\P_n$ replaced by $\P$. 
\end{enumerate}

