body:
[Lem 152 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Given any $\upp,\eta\in (0,1)$, if $\linit$ is sufficiently large
depending on $\upp,\eta$, then
  \[
        \sup_{1\leq \ell\leq 3\linit/4}
        \lt\{
        \plim_{N\to\infty} 
  \bigg\{
  \frac{|(
  \hat{\by}^{-\ell},
  \tilde \by^{-\ell})|}{N}
  +\frac{| (
  \hat{\bv}^{-\ell},
  \tilde\bv^{-\ell})|}{M}\bigg\}
        \rt\}
  \leq \eta\,.
  \]

\begin{proof} 
From \eqref{eq:example-AMP-for-correlated-disorder} and the surrounding discussion, we have
        \begin{align}
         \nonumber
    & \frac{(\hat{\by}^{-1},\tilde{\by}^{-1})}{N}
    \simeq
    \upp
    \cdot
    \frac{(\hat{\bv}^{-2},\tilde{\bv}^{-2})}{M}
    \simeq
    \upp^2
    \cdot  \frac{(
    \hat{\by}^{-2},\tilde\by^{-2})}{N}  \\
    &\qquad\simeq 
    \dots
    \simeq
    \upp^{2(\linit-1)}
    \frac{(\hat{\by}^{-\linit},
    \tilde\by^{-\linit})}{N}
  \simeq
  \upp^{2(\linit-1)} \,.
  \end{align}
The claim follows.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary corollary_contraction_on_observables_with_limits of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] Let $d \in \mathbb{N}$ and let $f:\mathbb{Z} \to \mathbb{R}^d$ be such that the limits
\begin{align*}
\lim_{k \to +\infty} f(k)  \overset{\textup{\tiny def.}}{=} f^+ \qquad \text{and} \qquad \lim_{k \to -\infty} f(k)  \overset{\textup{\tiny def.}}{=} f^-
\end{align*}
exist. Then the sequence $\big(\ell_n(f)\big)_{n \in \mathbb{N}}$ satisfies a LDP with good rate function $I_f : \mathbb{R}^d \to [0,\infty]$ given by
\begin{equation*}
I_f(x)=\inf \left\{ I(\mu) \; : \; \mu \in \mathcal{P}(\overline{\mathbb{Z}}) \; ,\; \alpha_{+} f^+ + \alpha_0 \sum_{k \in \mathbb{Z}} f(k) \mu_0(\{k\}) + \alpha_{-} f^- = x \right\}, \quad x \in \mathbb{R}^d.
\end{equation*}

