[Prop prp:UniformRecursiveEstimate of arXiv:2410.23859, 'Subcritical regimes in the Poisson Boolean percolation on Ahlfors regular spaces'] Let $\lambda > 0$. For all $r >0$, we have
        \begin{equation*}
            \sup_{x \in S} \mathbb{P}_\lambda(G(x,10\sigma^3r)) \leq C_1 \biggl(\sup_{x\in S}\mathbb{P}_\lambda\bigl(G(x,r)\bigr)\biggr)^2 + \sup_{x \in S}\mathbb{P}_\lambda(\widetilde{H}(x,r)),
        \end{equation*}
        where $C_1 = M_1M_2$.

[Corollary 2 (Uniform moment bounds) of arXiv:2607.09575, 'Probabilistic estimates for a system of\\noisy integrate-and-fire neurons'] For any $p \ge 1$, we have 



	\begin{equation*}
		\E\left[\sup_{0\le t \le T}\nnorm{X_t^i}^p + \left(J_T^i\right)^p + \left(F_T^i\right)^p + \left(F_T^N\right)^p\right] \le C_{T,\,p},
	\end{equation*}
	where $C_{T,\,p} > 0$ is independent of $i$ and $N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:interval-cycle of arXiv:2608.29719, 'Persistence Pairing Graphs: Tracking Changes of Selected Homology Bases'] Let $\sigma_i$ be a positive $q$-cell. The \emph{interval cycle} is
\begin{equation}

\rho_i :=
\begin{cases}
R_j, & \text{if }\operatorname{pair}(i)=j<\infty,\\
z_i, & \text{if }\operatorname{pair}(i)=\infty.
\end{cases}
\end{equation}

[Defn 7 ({{\bf {\boldmath$\mathscr{E}_{\alpha}$}-subharmonicity}}) of arXiv:2506.17979, '\large\bf A remark on subharmonicity for symmetric Dirichlet forms'] {\rm Fix $\alpha>0$ and an open set $D$. A function $u:E\to\R$ is called \emph{$\mathscr{E}_{\alpha}$-subharmonic} (resp.~\emph{$\mathscr{E}_{\alpha}$-superharmonic}) \emph{in $D$} if $u\in 
D(\mathscr{E})_{\loc}^{\diamond}$ 
and 
\begin{align}
\mathscr{E}_{\alpha}(u,v)\leq0\quad \text{\rm (resp.~}\geq0\text{\rm )}
\end{align}  
for all $v\in D(\mathscr{E}_D)_c\cap L^{\infty}(D;{\m})_+$. 
Here $L^{\infty}(D;{\m})_+$ denotes the family of non-negative bounded ${\m}$-measurable function on $D$. 
A function $u:E\to\R$ is called \emph{$\mathscr{E}_{\alpha}$-harmonic in $D$} if it is 
 $\mathscr{E}_{\alpha}$-subharmonic and $\mathscr{E}_{\alpha}$-superharmonic in $D$. 
A function $u:E\to\R$ is called \emph{$\mathscr{E}$-subharmonic} (resp.~\emph{$\mathscr{E}$-superharmonic}) \emph{in $D$} if $u\in 
D(\mathscr{E})_{e,\loc}^{\diamond}$ 
and 
\begin{align}
\mathscr{E}(u,v)\leq0\quad \text{\rm (resp.~}\geq0\text{\rm )}
\end{align}  
for all $v\in D(\mathscr{E}_D)_c\cap L^{\infty}(D;{\m})_+$. 
A function $u:E\to\R$ is called \emph{$\mathscr{E}$-harmonic in $D$} if it is 
 $\mathscr{E}$-subharmonic and $\mathscr{E}$-superharmonic in $D$. 
}

