[Lemma 10 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $f:[0,\sigma] \rightarrow \mathbb{R}^d$ be a continuous function and let $L:[0,\sigma] \rightarrow [0,\infty)$ be a continuous increasing function with $L(0)=0$. Consider the Lebesgue-Stieltjes measure $dL$ defined from $L$. Let $Y$ be the measure defined via Borel-measurable functions $\Phi:\mathbb{R}^d \rightarrow [0,\infty)$ as 
    \begin{equation*}
        \langle Y, \Phi \rangle \coloneqq \int_{b \in \mathbb{R}^d} \Phi(b)Y(db) := \int_{r=0}^\sigma \Phi(f(r)) dL(r).
    \end{equation*}
    Then we have that
    \begin{equation*}
        \text{supp}(Y) = \{f(r): r \in \text{supp}(dL)\}.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:intervallefttail of arXiv:2608.11378, 'On the most likely geodesic in last passage percolation'] Let $\tilde{M}^{\mathord{\text{
\tikz[baseline=0.1ex, line join=round] {
\draw[line width=0.06em] (0,0) -- (1ex,0) -- (0,1ex) -- cycle;
}
}}}_{c, d} = \max_{c \le k \le d}\left[L^{\mathord{\text{
\tikz[baseline=0.1ex, line join=round] {
\draw[line width=0.06em] (0,0) -- (1ex,0) -- (0,1ex) -- cycle;
}
}}}(0, k; n) - (n - k)\mu\right]$. Fix $\epsilon > 0$ and suppose $a \le \floor{n^{2/3 - \epsilon}}$. Suppose $c_l > 0$ is such that for constants $T,\, \rho > 0$ and $0 < \zeta < \frac{1}{2}$, the following inequality holds uniformly for $t$ with $T \le t \le \rho n^{1/6 + \zeta}$:
    \[
        \log \mathbb{P}(L^{\mathord{\text{
\tikz[baseline=0.1ex, line join=round] {
\draw[line width=0.06em] (0,0) -- (1ex,0) -- (0,1ex) -- cycle;
}
}}}(0, 0; n) - n \mu \le -t n^{1/3}) \ge -c_l t^{3} + o(t^3).
    \]
