[Lemma 5 of arXiv:2605.25719, 'A note on convergence rate for reflected BSDEs with quadratic generators by penalization m'] Let assumptions $(A1^{'})$, $(A2)$, $(A3)$ and $(H)$ be satisfied, then for numerical scheme \eqref{e3} we have
\begin{equation*}
M_{\lambda} \leq C\lambda,\quad N_{\lambda}\leq C\lambda^{max\{2,\frac{2}{\epsilon}\}}.
\end{equation*}
\begin{proof}
For any $i=1,\dots,n$ and $t\in[T_{n-i},T_{n-i+1}]$, let $(Y_{t}^{n,i,0},Z_{t}^{n,i,0})$ be the unique solution of 
\begin{equation*}
Y_{t}^{n,i,0}=Y_{T_{n-i+1}}^{n,i-1,0}+\int_{t}^{T_{n-i+1}} f \left( s,
E^{\mathcal{F}_{s}} \left[ Y_{T_{n-i+1}}^{n,i-1,0} \right],Z_{s}^{n,i,0} \right)ds-\int_{t}^{T} 
Z_{s}^{n,i,0} dW_{s}
\end{equation*}
where $Y_{T}^{n,0,0}=\xi$. From  \cite[Lemma 2.1]{HT}, we have $ Y_{t}^{n,1,\lambda} \geq Y_{t}^{n,1,0}$ in $[T_{n-1},T_{n}]$, which implies that
\begin{equation*}
f\left( s,E^{\mathcal{F}_{s}} \left[ Y_{T_{n-1}}^{n,1,0} \right],z \right) \leq f\left( s,E^{\mathcal{F}_{s}} \left[ Y_{T_{n-1}}^{n,1,\lambda} \right],z \right) \leq f^{\lambda}\left( s,E^{\mathcal{F}_{s}} \left[ Y_{T_{n-1}}^{n,1,\lambda} \right],z \right).
\end{equation*}
Thus, we can deduce inductively that $Y_{t}^{n,2,\lambda} \geq Y_{t}^{n,2,0}$ in $[T_{n-2},T_{n-1}]$ and $Y_{t}^{n,\lambda} \geq Y_{t}^{n,0}$ in $[0,T]$. Note that $Y_{t}^{n,0}$ is independent of $\lambda$, and there exists 
\begin{equation*}
K:=\sup \limits_{n\in \mathbb{N}} \left\{ \Vert Y^{n,0} \Vert_{\mathcal{S}^{\infty}(R)} \right\} \leq C
\end{equation*}
from \cite{LT}, which implies that $Y_{t}^{n,\lambda} \geq -K$.\par
On the other hand, let $(\hat{Y}_{t}^{n,i,\lambda},\hat{Z}_{t}^{n,i,\lambda})$ be the unique solution of
\begin{equation*}
\hat{Y}_{t}^{n,i,\lambda}=\hat{Y}_{T_{n-i+1}}^{n,i-1,\lambda}+\int_{t}^{T_{n-i+1}} g^{\lambda} \left( s,
E^{\mathcal{F}_{s}} \left[ \hat{Y}_{T_{n-i+1}}^{n,i-1,\lambda} \right],\hat{Z}_{s}^{n,i,\lambda} \right)ds-\int_{t}^{T_{n-i+1}} 
\hat{Z}_{s}^{n,i,\lambda} dW_{s}
\end{equation*}
where $g^{\lambda}(s,y,z)=f(s,y,z)+\lambda(K+S_{s}^{+})$ and $\hat{Y}_{T}^{n,0,\lambda}=\xi$. The comparison theorem implies that $Y_{t}^{n,1,\lambda} \leq \hat{Y}_{t}^{n,1,\lambda}$. We also have
\begin{equation*}
\begin{aligned}
f^{\lambda}\left( s,E^{\mathcal{F}_{s}} \left[ Y_{T_{n-1}}^{n,1,\lambda} \right],z \right) 
&\leq f \left( t,E^{\mathcal{F}_{s}} \left[ Y_{T_{n-1}}^{n,1,\lambda} \right],z \right) + \lambda \left( E^{\mathcal{F}_{s}} \left[ Y_{T_{n-1}}^{n,1,\lambda} \right]^{-}+S_{s}^{+} \right) \\
&\leq g^{\lambda} \left( s,E^{\mathcal{F}_{s}} \left[ \hat{Y}_{T_{n-1}}^{n,1,\lambda} \right],z \right).
\end{aligned}
\end{equation*}
Then using the same technique we have $Y_{t}^{n,2,\lambda} \leq \hat{Y}_{t}^{n,2,\lambda}$ in $[T_{n-2},T_{n-1}]$ and $Y_{t}^{n,\lambda} \leq \hat{Y}_{t}^{n,\lambda}$ in $[0,T]$. 
Using the inequality $\vert z \vert^{2-\varepsilon} \leq 1+\vert z \vert^{2}$ we have
\begin{equation*}
\begin{aligned}
g^{\lambda} \left( s,
E^{\mathcal{F}_{s}} \left[ \hat{Y}_{T_{n-i+1}}^{n,i-1,\lambda} \right],z \right)
&\leq \overline{C} \left( 1+\Vert \hat{Y}^{n,i-1,\lambda} \Vert_{\mathcal{S}^{\infty,i-1}(\mathbb{R})} + \vert z \vert^{2-\varepsilon} \right) + \lambda \left( K+\Vert S^{+} \Vert_{\mathcal{S}^{\infty}(\mathbb{R})} \right)\\
&\leq \left( 2\overline{C}+\lambda K+\lambda \Vert S^{+} \Vert_{\mathcal{S}^{\infty}(\mathbb{R})} \right) + \overline{C} \Vert \hat{Y}^{n,i-1,\lambda} \Vert_{\mathcal{S}^{\infty,i-1}(\mathbb{R})} + \overline{C} \vert z \vert^{2} \\
&= \alpha_{\lambda}+\overline{C} \Vert \hat{Y}^{n,i-1,\lambda} \Vert_{\mathcal{S}^{\infty,i-1}(\mathbb{R})} + \overline{C} \vert z \vert^{2}.
\end{aligned}
\end{equation*}
Then from \cite[Lemma 2.1]{HT}, we have
\begin{equation*}
\begin{aligned}
\Vert \hat{Y}^{n,i,\lambda} \Vert_{\mathcal{S}^{\infty,i}(\mathbb{R})}
\leq &\alpha_{\lambda}\frac{T}{n} + \left( 1+\frac{\overline{C}T}{n} \right) \Vert \hat{Y}^{n,i-1,\lambda} \Vert_{\mathcal{S}^{\infty,i-1}(\mathbb{R})}\\
\leq &\alpha_{\lambda} \frac{T}{n} + \left( 1+\frac{\overline{C}T}{n} \right)
\left[  \alpha_{\lambda}\frac{T}{n} + \left( 1+\frac{\overline{C}T}{n} \right) \ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2608.09840, 'Langevin dynamics along the zero set of real-analytic potentials'] Fix a singularity type $(\lambda,m)$, a function $f \in C^\infty_c(D_{\lambda,m})$, and a monomializing chart $(U,y)$. Then for any compact set $K \subset U$ there is $\varepsilon > 0$ such that
\begin{equation} 
K \cap \supp(f \circ \pi) \subset \{|y_i| \ge \varepsilon \text{ for all } i \in I_\supcr\}
\end{equation}
and
\begin{equation} 
K \cap \supp(f \circ \pi) \cap \{y_I = 0\} \subset \{|y_i| \ge \varepsilon \text{ for all } i \in I_\crit \setminus I\}, \quad I \subset I_\crit, \ |I| = m.
\end{equation}

[Definition Def.SchurProcess of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Fix $m, \in \mathbb{N}$, $q \in (0, 1)$, and $c \in [0, q^{-1})$. We define the {\em Pfaffian Schur process} to be the probability distribution on sequences of partitions $\lambda^0,\dots,\lambda^m$, given by
\begin{equation}
\begin{split}
&\mathbb{P}\left(\lambda^{0},\dots,\lambda^{m}\right)\propto  c^{\sum_{j=1}^{\infty}(-1)^{j-1}\lambda_j^0} \cdot s_{\lambda^{1}/\lambda^{0}}(q)\cdots s_{\lambda^m/\lambda^{m-1}}(q) \cdot s_{\lambda^{m}}(\underbrace{q,q, \dots, q}_{\text{$m$ times}}).
\end{split}
\end{equation}

[Corollary 10 (Effect of a frequency cutoff) of arXiv:2609.01403, '2609.01403'] Let \(\chi\in C_c^\infty(\mathbb R^n)\) be radial and equal to \(1\)
near the origin, and set \(\eta=1-\chi\).

\begin{enumerate}

\item If \(\alpha>0\) and
\(\alpha\notin\{n,n+2,n+4,\ldots\}\), then
\begin{equation}
    \mathcal F^{-1}(\eta|\xi|^{-\alpha})(x)
    =\kappa_{n,\alpha}|x|^{\alpha-n}+H_\alpha(x),

\end{equation}
where \(H_\alpha\) is smooth and radial near the origin. At
\(\alpha=n\),
\begin{equation}
    \mathcal F^{-1}
    \bigl(\eta\operatorname{Fp}|\xi|^{-n}\bigr)(x)
    =c_n\log\frac1{|x|}+H_n(x),

\end{equation}
where \(H_n\) is smooth and radial near the origin.

\item If \(\alpha<n\) and
\(\alpha\notin\{0,-2,-4,\ldots\}\), then, for every \(N>0\),
\begin{equation}
    \mathcal F^{-1}(\chi|\xi|^{-\alpha})(x)
    =\kappa_{n,\alpha}|x|^{\alpha-n}
    +O(|x|^{-N}),
    \qquad |x|\to\infty.

\end{equation}
If \(\alpha\in\{0,-2,-4,\ldots\}\), then
\(\mathcal F^{-1}(\chi|\xi|^{-\alpha})\) is a Schwartz function.

\end{enumerate}

[Lemma 27 of arXiv:2512.04807, 'Existence and uniqueness of the canonical Brownian motion in non-simple conformal loop ens'] Suppose that $n \in \N \cup \{\infty\}$ and $V_i \in \metregions$, $0 \le i < n$, are such that for each $i,j > 0$, $i \neq j$, we have $\dpathY(V_i,V_j) > 0$ and $\ol{V_i} \cap \ol{V_0}$ consists of a single point. Let $V = \bigcup_{i=0}^n V_i$. Then
\begin{align*}
 \rfdomainres{V}{\Gamma} &= \left\{ f : f|_{V_i} \in \rfdomainres{V_i}{\Gamma} \text{ for each } 0 \le i < n ,\ \sum_{i=0}^n \rformres{V_i}{f}{f}{\Gamma} < \infty \right\} \\
 \text{and}\quad
 \rformres{V}{f}{f}{\Gamma} &= \sum_{i=0}^n \rformres{V_i}{f}{f}{\Gamma} .
\end{align*}

[Lemma 17 of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] For $\eps\le r\le r_0$, we have
\begin{equation}
  \Vol_{\omega_\eps}\{r<d<2r\}\le Cr^4,
  \qquad
  \Vol_{\omega_\eps}\{d<2\eps\}\le C\eps^4.
\end{equation}
Moreover, for every fixed $\chi\in C^\infty(X)$, pulled back to $\widetilde X$, we have
\begin{equation}
  |\mathcal P_\eps^*\chi|\le C_\chi\tau^{-3}.
\end{equation}

