[Proposition proposition_exponential_rate_decay_I_DV of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] For all $\mu_0 \in \mathcal{P}(\mathbb{Z}) \subseteq \mathcal{P}(\overline{\mathbb{Z}})$,
\begin{align*}
\lim_{\varepsilon \to 0^+} \liminf_{n \to \infty} \frac{1}{n} \log \mathbb{P}\left( \ell_n \in B_{\overline{\mathbb{Z}}}(\mu_0,\varepsilon) \right) & = \lim_{\varepsilon \to 0^+} \limsup_{n \to \infty} \frac{1}{n} \log \mathbb{P}\left( \ell_n \in B_{\overline{\mathbb{Z}}}(\mu_0,\varepsilon) \right) \notag \\
& = -I_{\textup{DV},\mathbb{Z}}(\mu_0).
\end{align*}

[Lemma lem:LBJ-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = \ell^2(\mathbb{Z})$.  The seed functions
$\psi_{t,r,n}$ and $\phi_{t,r,n}$ defined in
\S(sec:LBJ-kernel-reform of the paper) satisfy the linear problem
(equation eq:Linear-Psi-3 of the paper) and the adjoint linear problem
(equation eq:Linear-Phi-Prob of the paper) on $\mathcal{V}$ with edge
weights $(c_k, \lambda_k)$.  Explicitly, for each fixed
$r \in \mathbb{Z}$:
\begin{align}
\psi_{t,r,n+1}
&= (1{-}\theta)^{-1}\psi_{t,r+1,n}
   - (1{-}\theta)^{-1}\theta\psi_{t,r,n},
 \\
\psi_{t+1,r,n}
&= p\theta^{-1}\psi_{t,r+1,n}
   + q\psi_{t,r,n},

\end{align}
and
\begin{align}
\phi_{t,r+1,n}
&= (1{-}\theta)^{-1}\phi_{t,r,n+1}
   - (1{-}\theta)^{-1}\theta\phi_{t,r+1,n+1},
 \\
\phi_{t,r+1,n}
&= p\theta^{-1}\phi_{t+1,r,n}
   + q\phi_{t+1,r+1,n}.

\end{align}

