[Theorem 1 of arXiv:2604.27519, 'Quantitative homogenization of the maximal action of curves in a Brownian potential'] There exists a deterministic constant $a^*\in(0,\infty)$ such that

\begin{align*}
\big\|A_L-a^*\ln L\big\|_{3/2}\lesssim 1,
\end{align*}

where $\lesssim$ is short for $\le C$ for some universal constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi 24 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] Let $0\leq s< T<\infty$. 
Let $\left(\nu_t\right)_{t\in (s,T)}\subset \mathcal{M}(\mathbb{R}^d)$ be a Borel curve in $\mathcal{M}(\mathbb{R}^d)$.

\begin{enumerate}
    \item[(i)] $\left(\nu_t\right)_{t\in (s,T)}$ is called a (weak, or distributional) solution on $(s,T)$ to the linear Fokker-Planck equation  
    \begin{equation}
        \frac{d}{dt} \nu_t = \left({\sf L}_t^K\right)^\ast \nu_t, \quad t\in (s,T),
    \end{equation}
    if
    \begin{equation*}
        \int_s^T\int_{B(0,R)} \|b(t,x)\|+\|a(t,x)\| \; \nu_t(dx) dt <\infty, \quad R>0,
    \end{equation*}
    and
    \begin{equation*}
        \int_s^T\int_{\mathbb{R}^d} {\sf \overline{L}^K}f(t,x) \;\nu_t(dx) dt = 0, \quad f\in C_c^\infty \left((s,T)\times \mathbb{R}^d\right).
    \end{equation*}  
    \item[(ii)] $\left(\nu_t\right)_{t\in [s,T]}$ is called a (weak, or distributional) solution on $(s,T)$ to the linear Fokker-Planck equation  
    \begin{equation}
        \frac{d}{dt} \nu_t = \left(\mathcal{L}_t^K\right)^\ast \nu_t, \quad t\in (s,T),
    \end{equation}
    if it is weakly continuous and
    \begin{equation*}
        \nu_T(f(T,\cdot))=\nu_s(f(s,\cdot))+\int_s^T\int_{\mathbb{R}^d} {\mathcal{L}^K}f(t,x) \;\nu_t(dx) dt , \quad f\in \mathcal{D}_b(\mathcal{L}),
    \end{equation*}  
    where recall that $\mathcal{D}_b(\mathcal{L})$ is given by \eqref{eq:D(L)_weak}, whilst $\mathcal{L}^K$ is given by \eqref{eq:L^K}; see also \Cref{prop:X^K}, (iv).
\end{enumerate}
If $(\nu_t)_{t\in[s, T]}\subset \mathcal{M}(\mathbb{R}^d)$ is weakly continuous and is a solution to \eqref{eq:LFPshortKcal} or \eqref{eq:LFPshortKbar} from above, then $\nu_s$ is considered to be the initial condition of the corresponding Fokker-Planck equation.

[Definition Head point process of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] The point process 
	\begin{equation}
		{\mathcal H }:=\sum_{i\in \mathbb{N}}\delta_{(T_i, H_i)},
	\end{equation}
on $\mathbb{H}^+$, formed by the minimum time-space points $(T_i, H_i)$, as defined in ((eq:heada of the paper)), associated with the atoms
$(R_i,\alpha_i)$ of $\tilde{\Phi}$, will be called the {\em head point process}.

[Theorem 22 (Asymptotic variance of a chaotic component) of arXiv:2604.19738, 'Phase Transitions in the Fluctuations of Functionals of Random Neural Networks \\'] For $q\in \N$ with $q\geq 2$.

If $q<d/(2\nu)$, as $L\rightarrow\infty$ we have
	\begin{equation}

		\Var(F_L[q])= \frac{\lambda^{Lq}}{(1-b)^q} \omega_d \omega_{d-1}\,q!\varphi_q^2\,
		\int_{-1}^1\widehat \beta^q(u)\di \mu(u)\,(1+o(1))\,\,\,.
	\end{equation}
where $\widehat\beta$ is given in~\eqref{beta-hat-high}.

If $q\ge \frac{d}{2\nu}$, and $q$ is even whenever $\kappa$ is odd, we have
\begin{align}
		\Var(F_L[q]\,\asymp \,
		\begin{cases}
			\lambda^{qL}\,L\,\, &\textnormal{if } q=d/(2\nu) \\
			\lambda^{\frac{d}{2\nu}L}\,\, &\textnormal{if }q>d/(2\nu)
		\end{cases}
		\qquad\,.
	\end{align}

[Lemma 8 of arXiv:2609.00680, 'Sharp embeddings between quasi-Banach Besov spaces and shallow ReLU Variation spaces'] Let $0<p\le 1$, $0<q\le\infty$, and $s>0$. Suppose that
$\left\{u_i\right\}_{i\ge0}\subset\mathcal S'(\mathbb R^d)$ is such that
$\sum_{i=0}^\infty u_i$ converges in $\mathcal S'(\mathbb R^d)$, and
there exist $\delta>0$ and a nonnegative
sequence $b=\left\{b_i\right\}_{i\ge0}\in\ell^q$ such that
\begin{equation}

  2^{js}\|\Delta_j u_i\|_{L^p(\mathbb R^d)}
  \lesssim 2^{-\delta|j-i|}b_i,
  \qquad i,j\ge0.
\end{equation}
The following estimate holds:
\begin{equation}

 \left\|\sum_{i=0}^\infty u_i\right\|_{B_{p,q}^s(\mathbb R^d)}
 \lesssim \|b\|_{\ell^q}.
\end{equation}

[Cor shuffling-sg-with-iid of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $(\mathbb{X},\mathcal X,\nu)$ be a probability space, and let $\psi$ be a measurable $\mathbb{X}$-shuffling rule.
	If $\psi$ is $\mathfrak{S}$-equivariant, then for every non-negative sequence ${\mathbf{w}}=(w_0,w_1,\dots)$ with $w_0w_1>0$, and for every $n\geq1$, the probability measure
	\begin{align*}
	\SimpGen{{\mathbf{w}}}{n}(\mathrm{d}T)\cdot\nu^{\otimesT}(\mathrm{d}{\boldsymbol{x}})
	\end{align*}
	is invariant under the mapping $F^\psi\colon(T,{\boldsymbol{x}})\mapsto \bigl(({\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}})\cdotT,({\boldsymbol{\sigma}}^\psi_{T,{\boldsymbol{x}}})_*\,{\boldsymbol{x}}\bigr)$.

[Definition 12 of arXiv:2604.01685, 'Probability with Measure\footnote{Lecture notes. University of Ljubljana.}'] We put
	\begin{equation*}
	\AA\vert_A:=\{A'\cap A:A'\in\AA\}
	\end{equation*}
	for the trace of $\AA$ on $A$.\footnote{Not to be confused with the restriction of a function $\AA$ to a subset $A$ of its domain! Let us agree that if it is given a priori that $\AA$ is a function and $A$ a subset of its domain, then the latter (not the trace) meaning of $\AA\vert_A$ prevails (this is still wrong, but hopefully enough to prevent confusion). Of course this is not the only notational shenanigan that we have hitherto seen, another screaming example being $f^{-1}(x)$ which can refer to the preimage of $x$ under $f$ or the pull-back of $x$ under $f$, yet another $2^\Omega$ (is it the power set of $\Omega$, or $\{0,1\}^\Omega$ -- the maps from $\Omega$ into $2=\{0,1\}$?); somehow we trust that it can be gathered from context which of these is intended.}

[Thm null vector equation angular coordinate constant h of arXiv:2505.14762, 'Multiple radial SLE($\kappa$) and quantum Calogero-Sutherland system'] For a local multiple radial SLE(\(\kappa\)) system in the unit disk \( \mathbb{D} \) with boundary points $z_1=e^{i\theta_1},z_2=e^{i\theta_2},\ldots,z_n=e^{i\theta_n}$ and a marked point at \( q = 0 \), there exists a positive partition function \( \psi(\boldsymbol{\theta}) \) such that the drift term \( b_j \) in equation ((sle with drift of the paper)) satisfies  
\begin{equation}
    b_j = \kappa \frac{\partial_j \psi}{\psi}, \quad j = 1,2,\dots,n.
\end{equation}  
Moreover, \( \psi(\boldsymbol{\theta}) \) satisfies the null vector equation  
\begin{equation} 
    \frac{\kappa}{2} \partial_{ii} \psi + \sum_{j \neq i} \cot\left(\frac{\theta_j - \theta_i}{2}\right) \partial_i \psi 
    + \left(1 - \frac{6}{\kappa}\right) \sum_{j \neq i} \frac{1}{4 \sin^2\left(\frac{\theta_j - \theta_i}{2}\right)} \psi - h \psi = 0,
\end{equation}  
for some constant \( h \).  

Furthermore, there exists a real constant \( \omega \) such that for all \( \theta \in \mathbb{R} \),  
\begin{equation} 
    \psi(\theta_1 + \theta, \dots, \theta_n + \theta) = e^{-\omega \theta} \psi(\theta_1, \dots, \theta_n).
\end{equation}

Conversely, given a positive partition function \( \psi(\boldsymbol{\theta}) \) satisfying both the null vector equation ((null vector equation angular coordinate constant h of the paper)) and the rotation invariance condition ((rotation_invariance of the paper)), consider the multiple radial Loewner chain 

the multiple radial SLE($\kappa$) Loewner chain as a normalized conformal map $g_t = g_t(z)$, with the initial condition $g_0(z) = z$ and the evolution given by the Loewner equation
\begin{equation}
\partial_t g_t(z) = \sum_{j=1}^n \nu_j(t) g_t(z) \frac{z_j(t) + g_t(z)}{z_j(t) - g_t(z)}, \quad g_0(z) = z.
\end{equation}

The Loewner chain for the covering map $h_t(z) = -i \log(g_t(e^{iz}))$ is given by
\begin{equation}
\partial_t h_t(z) = \sum_{j=1}^n \nu_j(t) \cot\left( \frac{h_t(z) - \theta_j(t)}{2} \right), \quad h_0(z) = z.    
\end{equation}

driven by the functions \( \theta_j(t) \), for \( j = 1, \dots, n \), evolving as  
\begin{equation}
d{\theta}_j = \nu_j(t) \frac{\partial_j \log \psi(\boldsymbol{\theta})}{\partial \theta_j} dt 
+ \sum_{k \neq j} \nu_k(t) \cot\left( \frac{\theta_j - \theta_k}{2} \right) dt 
+ \sqrt{\kappa} dB_{t}^{j},
\end{equation}
where \( \boldsymbol{\nu} = (\nu_1, \dots, \nu_n) \) is a set of capacity parametrizations, with each \( \nu_i: [0, \infty) \to [0, \infty) \) assumed to be measurable. Here, $B^{j}(t)$ denotes a set of independent Brownian motion.

This process defines a local multiple radial SLE(\(\kappa\)) system. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 20 of arXiv:2604.07275, 'Some probabilistic properties and time-changed versions of a renewal process based on Mitt'] The time-changed process $\{\bar{N}_\alpha^{f}(t)\}_{t \ge 0}$ is a renewal process with i.i.d. waiting times $\{J_n\}_{n \ge 1}$, which satisfy 
		\begin{equation}
			\Pr\{J_n > t\}= \mathbb{E}\big((1+\lambda Y_{\psi}(t)) e^{-\lambda Y_{\psi}(t)}\big),   
		\end{equation} 
		where $\{Y_{\psi}(t)\}_{t \ge 0}$ is the inverse subordinator corresponding to ${\psi}(s)=(f(s))^\alpha$.

