body:
[Theorem prop:monotonicity of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] For any finite set $\Lambda \subseteq \ensuremath{\mathbb{Z}}^2$, any collection of conductances $J , \widetilde J \in [0, \infty)^{E(\Lambda)}$ and any $x \in \ensuremath{\mathbb{Z}}^2$, we have
\begin{equation} 
    \forall \{ y , y' \} \in E(\Lambda), ~ J_{yy'} \leq \widetilde J_{yy'} ~ \implies ~ \mathrm{Var}_{\Lambda , J}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}} \left[ \varphi(x) \right] \leq \mathrm{Var}_{\Lambda , \widetilde J}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}} \left[ \varphi(x) \right].
\end{equation}
Similarly, for any $n \in \ensuremath{\mathbb{N}}^*$ and any collections conductances $J , \widetilde J \in [0, \infty)^{E(\Lambda) \times \{1 , \ldots , n\}}$, we have
\begin{equation} 
    \forall \{ x , y \} \in E(\Lambda), ~\forall k \in \{1 , \ldots, n\}, ~ J_{xy,k} \leq \widetilde J_{xy,k} ~ \implies ~ \mathrm{Var}_{\Lambda , J}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} \left[ \varphi(x) \right] \leq \mathrm{Var}_{\Lambda , \widetilde J}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} \left[ \varphi(x) \right].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi eq:w gap of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] For $p\geq 1$  and  $\Pi_i\in \mathcal P_{s,1}( \mathsf{S})$, $i=0,1$, 
define 
\begin{align}
   \mathscr W_{gap,p}^p(\Pi_0,\Pi_1):=\inf_{\mathsf U\in  \mathsf{Cpl}_s(\Pi_0,\Pi_1)}\int \left\lvert \mathsf{s}_1- \mathsf{s}'_1\right\rvert^p\mathsf U(d \mathsf{s},d \mathsf{s}').
\end{align}

[Definition d:AzuHoef of arXiv:2411.04116, 'Poisson genericity in numeration systems with exponentially mixing probabilities'] Let $ X_1, {X_2}, X_3, \dots$  be a sequence of random variables defined on $(\mathbb X, {\cal F}, \mathds{P}{ })$
taking values on some $\Omega.$ Consider the filtration of sub-sigma-algebras~${\cal F}_i$, \begin{align*}
{\left\{ \emptyset, \mathbb X \right\}} = {\cal F}_0\subseteq   
{\cal F}_1 \subseteq \ldots \subseteq  {\cal F}.
\end{align*}
and $\mathcal F$ is the smallest sigma-algebra containing all the others.
Consider a function  $\varphi :\Omega^{\mathbb N} \to \mathbb R$. For  $X=X_1 X_2\cdots$, we define, for each $i\in \mathbb N $, 
\begin{align*}
    V_i(\varphi) = {\mathds{E}}\corch{\varphi(X) \, | \, {\cal F}_i } - 
    {\mathds{E}}\corch{\varphi(X) \, | \, {\cal F}_{i-1} }
\end{align*}
and we  define  the Azuma--Hoeffding  coefficients 
\begin{align}
d_i = 
\sup
_{\mathbb X}  |V_i(\varphi)|.    
\end{align}

[Lemma 6 of arXiv:2609.02175, '2609.02175'] Assume \eqref{eq:radial-short-range},
	\eqref{eq:radial-keller}, \eqref{eq:radial-energy}, and
	\eqref{eq:radial-convexity}. Then the deflection function
	$b\mapsto\Theta_\lambda(b)$ is strictly decreasing:
	\begin{equation}
		\Theta_\lambda'(b)<0,
		\qquad b>0.
	\end{equation}
	Moreover,
	\begin{equation}
		\lim_{b\to0^+}\Theta_\lambda(b)=\pi,
		\qquad
		\lim_{b\to+\infty}\Theta_\lambda(b)=0.
	\end{equation}
	In particular, for every scattering angle
	$\Theta\in(0,\pi)$, there exists a unique impact parameter
	$b>0$ such that
	\begin{equation}
		\Theta_\lambda(b)=\Theta.
	\end{equation}

