[Lemma 5 (\citeauthor{F10}, \citeyear{F10}, Lemma 5.9) of arXiv:2606.06739, 'The relationship between the transition functions of the labeled and unlabeled versions of'] For $\bm m=(m_1,\ldots,m_k)$ with $m_1\ge\cdots\ge m_k\ge1$, $\bm n=(n_1,\ldots,n_l)$ with $n_1\ge\cdots\ge n_l\ge1$, $k,l\in{\bf N}$, $m=|\bm m|$, and $n=|\bm n|$,
\begin{align}
&\textbf{E}[P_{\bm m}(\rho(\varepsilon V_1^{\bm n},\ldots,\varepsilon V_l^{\bm n},(1-\varepsilon)\rho_1,(1-\varepsilon)\rho_2,\ldots))]\nonumber\\
&\quad{}=C(\bm m)\sum_{r=0}^{k\wedge l}\bigg[\sum_{\substack{I\subset\{1,\ldots,k\}:\\ |I|=r}}\;\sum_{\substack{\gamma:I\mapsto\{1,\ldots,l\}\\ \text{\rm one-to-one}}}\nonumber\\
&\qquad\qquad\qquad\quad\dfrac{\prod_{i\in I}(m_i+n_{\gamma(i)}-1)!\,\prod_{i\in I^c}(m_i-1)!}{\prod_{i\in I}(n_{\gamma(i)}-1)!}\bigg]\,\frac{\theta^{k-r}}{(n+\theta)_{(m)}}.
\end{align}

