[Cor cor-freeenergyVP of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] In the situation of Theorem~(thm-freeenergy of the paper),
\begin{equation}
\begin{aligned}
\beta \,{\rm f}(\beta, \rho)=-\overline q+\inf_{\rho_1,\rho_2\geq 0\colon \rho_1+\rho_2=\rho}\chi(\rho_1,\rho_2)=-\overline q+\overline\chi(\rho),
\end{aligned}
\end{equation}
where
\begin{equation}
\begin{aligned}
\overline\chi(\rho)=\inf\Big\{{\rm h}^{\ssup{{\mathcal L },{\mathcal S }}}(P)+\langle F_U,P\rangle\colon P\in {\mathcal M }_1^{{{\scriptscriptstyle{({\rm s}})}}}({\mathcal L }\times {\mathcal S }), \langle P,{\mathfrak N}_U^{\ssup{\ell,{\mathcal L }}}+{\mathfrak N}_U^{\ssup{\ell,{\mathcal S }}}\rangle=\rho\Big\}.
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Definition_block_height of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] For a block process $\vec \mathbf p$ and compatible virtual block process $\vec\boldsymbol{\upsilon}$, a compatible \emph{block height} is a function $\mathbf H:\mathbf \Delta\cup\{\mathbf Q_\ell\mid \ell\in  \llbracket 0, m\rrbracket\}\cup\{\mathbf Q_{\ell-1}+\boldsymbol{\upsilon}_\ell \mid \ell\in  \llbracket 1, m\rrbracket,\, \boldsymbol{\upsilon}_\ell\ne \varnothing\} \to \mathbb R_{\ge 0}$, such that
\begin{itemize}
    \item $\mathbf H(\mathbf Q_\ell)=\mathbf p^0(\mathbf Q_\ell-)$ for each $\ell \in \llbracket 1, m\rrbracket$ and $\mathbf H(0)=0$;
    \item $\mathbf H(\mathbf Q_{\ell-1}+\boldsymbol{\upsilon}_\ell)=\mathbf p^0(\mathbf Q_{\ell-1}-)$ for each $\ell$ with $\boldsymbol{\upsilon}_\ell\neq\varnothing$;
    \item for all $x\in \mathbf \Delta$, we have $\mathbf H(x)\ge  \max\bigl(\mathbf p^0(x),\mathbf p^0(x-)\bigr)$;
    \item if $j\in \llbracket 1, m+\mathbf u\rrbracket$ and $x\in \mathbf \Delta$ is a discontinuity point for $\mathbf p_j$, then the jump $\mathbf p_j(x)-\mathbf p_j(x-)$ and the difference $\mathbf H(x)-\mathbf p^0(x-)-\mathbf p_j(x)$ have the same sign;
    \item if $\boldsymbol{\upsilon}_\ell=\varnothing$ for $\ell\in \llbracket 1, m\rrbracket$, then  $\mathbf H\bigl(\min\bigl(\bigcup_{j=1}^{m+\mathbf u}\mathbf \Delta_{j,\ell}\cup \{\mathbf Q_\ell\}\bigr)\bigr)\ge \mathbf H(\mathbf Q_{\ell-1})$.
\end{itemize}

[Lem 19 (Spherical second and fourth moments in a subspace) of arXiv:2605.30779, '2605.30779'] Let \(\mathbb F\in\{\mathbb R,\mathbb C\}\), and put
  \[
    \beta_{\mathbb F}:=\dim_{\mathbb R}\mathbb F
    =
    \begin{cases}
      1, & \mathbb F=\mathbb R,\\
      2, & \mathbb F=\mathbb C.
    \end{cases}
  \]
  Equip \(\mathbb F^N\) with the standard Euclidean/Hermitian inner product. Let \(V\subset \mathbb F^N\) be an \(m\)-dimensional \(\mathbb F\)-linear subspace, and let \(P\) be the matrix representing the orthogonal projection onto \(V\). If \(v\) is a random unit vector in \(V\) uniformly distributed on the unit sphere of \(V\), then, with $v^\ast$ understood as $v^{\top}$ if $\mathbb F = \realR$,
  \begin{equation}
    \mathbb E[vv^\ast]=\frac1m P.
  \end{equation}
  Moreover, for any \(N\times N\) matrices \(A\) and \(B\) that are real symmetric if \(\mathbb F = \realR\) and are Hermitian if \(\mathbb F = \compC\),
  \begin{equation}
    \mathbb E\bigl[(v^\ast A v)(v^\ast B v)\bigr]
    =
    \frac{
      \tr(PAP)\tr(PBP)+\frac{2}{\beta_{\mathbb F}}\tr(PAPBP)
    }{
      m\bigl(m+\frac{2}{\beta_{\mathbb F}}\bigr)
    }.
  \end{equation}

