[Proposition 7 of arXiv:2608.23301, 'On a Telegraph Process with Generalized Mittag-Leffler Waiting times and Velocity Driven b'] The probabilities that the particle is at position $v_1 t$ and $-v_2 t$ are given by
		{\begin{align}
			\mathrm{Pr}\{\mathbb{X}_{\alpha}(t)=v_1 t\}&=\frac{b}{b+r}\Big(1-(\lambda t^\alpha)^{\frac{b}{c}+1}E_{\alpha,\alpha(\frac{b}{c}+1)}^{\frac{b}{c}+1}(-\lambda t^\alpha)\Big)\nonumber\\
			&\ \ +\frac{b(\lambda t^\alpha)^{\frac{b}{c}+1}}{(b+r)\Gamma(\frac{b}{c}+1)}{}_2\Psi_2\!\left[
			\begin{array}{c}
				(\frac{b}{c}+2,1) (\frac{b+r}{c}+1,1)\vspace{0.5em}\\
				(\frac{b+r}{c}+2,1) (\alpha(\frac{b}{c}+1)+1,\alpha)
			\end{array}
			\,\middle|\, -\lambda t^\alpha
			\right]
		\end{align}}
	and
	\begin{align}
		\mathrm{Pr}\{\mathbb{X}_{\alpha}(t)=-v_2 t\}&=\frac{r}{b+r}\Big(1-(\mu t^\alpha)^{\frac{r}{c}+1}E_{\alpha,\alpha(\frac{r}{c}+1)}^{\frac{r}{c}+1}(-\mu t^\alpha)\Big)\nonumber\\
		&\ \ +\frac{r(\mu t^\alpha)^{\frac{r}{c}+1}}{(b+r)\Gamma(\frac{r}{c}+1)}{}_2\Psi_2\!\left[
		\begin{array}{c}
			(\frac{r}{c}+2,1) (\frac{b+r}{c}+1,1)\vspace{0.5em}\\
			(\frac{b+r}{c}+2,1) (\alpha(\frac{r}{c}+1)+1,\alpha)
		\end{array}
		\,\middle|\, -\mu t^\alpha
		\right],
	\end{align}
	respectively.

