[Definition 25 of arXiv:2608.29086, '2608.29086'] [$INT(U)$]
Given $U \subset A$. $INT(U)$ denotes the collection of all integral molecules whose supports are contained in $U$, i.e.,
\begin{equation*}
INT(U):=\{\phi \in INT(Mol) \cap MOL(M_0)\ |\ Supp(\phi) \subset U \}.
\end{equation*}

[Lemma 25 of arXiv:2604.21669, 'Discontinuous transition in 2D Potts:\\ II. order-order interface convergence'] There is \(c\in (0,+\infty)\) such that for any \(n\geq 1\), \(i,i'\in \Z\) with \(i> i'\),
	\begin{equation*}
		\tfrac{\min(i-i',\sqrt{n})}{c\sqrt{n}}
		\leq
		q_{i,i'}^+(n)
		\leq
		\tfrac{c\min(i-i',\sqrt{n})}{\sqrt{n}}.
	\end{equation*}
	The same holds for \(\overleftarrow{q}^+\).

[Proposition chain_expressions of arXiv:2412.06701, 'Matsumoto-Yor processes on Jordan algebras'] For $k\ge 0$,
\begin{enumerate} 
\item $L^{n}_k=\mathrm P(w^{n}_k)\dots \mathrm P(w_1^{n})(\ell_0+I^{n}_k),$
\item $\Lambda^n_k=\mathrm P(L^n_{k})\mathrm P((w^n_{k})^{-1})\dots \mathrm P((w^n_{1})^{-1})\mathrm P(\ell_0^{-1})(\lambda_0)$.
\end{enumerate}

