[Proposition prop:limit_of_kernel of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] We have the following limits of the correlation kernel $K_t$ on a slice.
	On the center line, that is
	$\mathsf{N}<\mathsf{T}$,
	$\mathsf{t}_l<\mathsf{t}<\mathsf{t}_r$,
	$\mathsf{x}=\tfrac12(\mathsf{S}+\mathsf{t})$, and $\lfloor L\hspace{1pt} \mathsf{x}\rfloor=\tfrac{1}{2}(S+t)$,
	we have
	\begin{equation}

		\lim_{L\to+\infty} K_{\lfloor L\hspace{1pt} \mathsf{t} \rfloor }(\lfloor L\hspace{1pt} \mathsf{x}\rfloor+\Delta x,
		\lfloor L\hspace{1pt} \mathsf{x}\rfloor+\Delta y)=\mathbf{1}_{\Delta x=\Delta y}\quad \textnormal{for all
		$\Delta x,\Delta y\in \mathbb{Z}$}.
	\end{equation}
	Outside the waterfall region, that is,
	for $(\mathsf{t},\mathsf{x})\in \mathcal{W}^+\cup \mathcal{W}^-$,
	we have
	\begin{equation}

		\lim_{L\to+\infty}
		K_{\lfloor L\hspace{1pt} \mathsf{t} \rfloor }
		(\lfloor L\hspace{1pt} \mathsf{x}\rfloor+\Delta x,
		\lfloor L\hspace{1pt} \mathsf{x}\rfloor+\Delta y)=0\quad \textnormal{for all
		$\Delta x,\Delta y\in \mathbb{Z}$}.
	\end{equation}

[Proposition 2 of arXiv:2606.30080, 'Ergodicity of reflected stochastic reaction-diffusion equations driven by space-time white'] Let $\{\sigma(s,y): (s,y)\in\mathbb{R}_+\times [0,1]\}$ be a random field such that the stochastic integral against space-time white noise is well defined. Then for any $p>2$, $\beta>0$ and $\alpha>0$ satisfying $\frac{1}{2p}<\alpha<\frac{1}{4}$, there exists a constant $C_{p,\beta,\alpha}>0$ independent of $t$ such that for any $t\geq 0$,
  \begin{align}
    & {\mathbb{E}}\left[\sup_{x\in [0,1]}\left|\int_0^t\int_0^1 e^{-\beta (t-s)}p_{t-s}(x,y)\sigma(s,y)\,W(ds,dy) \right|^p\right] \nonumber\\
    \leq & C_{p,\beta,\alpha} \sup_{s\in [0,t]}\left(\int_0^s (s-r)^{-2\alpha-\frac{1}{2}} e^{-2\beta (s-r)} \sup_{z\in[0,1]}\left\Vert \sigma(r,z)\right\Vert_{L^p(\Omega)}^2\,dr\right)^{\frac{p}{2}} .
  \end{align}
In particular, for any $T>0$, 
  \begin{align}
     & \sup_{t\in [0,T]}\left\Vert \sup_{x\in [0,1]}\left|\int_0^t\int_0^1 e^{-\beta (t-s)}p_{t-s}(x,y)\sigma(s,y)\,W(ds,dy) \right|\right\Vert_{L^p(\Omega)} \nonumber\\
    \leq  & C_{p,\beta} \sup_{s\in [0,T]} \sup_{y\in[0,1]}\Vert \sigma(s,y)\Vert_{L^p(\Omega)},

  \end{align}
where the constant $C_{p,\beta}$ is independent of $T$ and can be bounded by
\begin{align}
  C_{p,\beta} < \frac{\sqrt{4p}}{\pi}\left(\frac{1}{2\sqrt{\pi}}\right)^{\frac{1}{p}+\frac{1}{2}} \frac{1}{\beta^{\frac{1}{4}-\frac{1}{2p}}} \times \left(\Gamma\Big(\frac{p-2}{6p}\Big)\right)^{\frac{3}{2}}, 
\end{align}
where $\Gamma(\cdot)$ is the gamma function.

