[Definition 3 of arXiv:2607.28215, 'Almost stochastic dominance via optimal transport'] For two $E$-valued random variables $X,Y$ we define
\begin{align*}
X \le_{st} Y \quad \Longleftrightarrow \quad \E[f(X)] \le \E[f(Y)] \ \ \text{for all bounded measurable increasing }f:E \to \R.
\end{align*}

[Lemma 37 of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] For any $x \in \mathbb{R}^{d}$ and $\theta \in \mathbb{R}$, the following inequality holds:
  \begin{align*}
    \limsup_{t \to \infty} \frac{1}{t} \log \mathbb{E}_{x} \left[ \exp(\theta A_{t}^{\mu}) \right] \le -\lambda_{\infty}(\theta\mu).
  \end{align*}

[Definition 45 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Fix $m \in \mathbb{N}$,  $t_1 < \cdots < t_m$, and set $\mathcal{T} = \{t_1, \dots, t_m\}$. If $
u = (
u_{t_1}, \dots, 
u_{t_m})$ is an $m$-tuple of locally finite measures on $\mathbb{R}$, we define the (locally finite) measure $\mu_{\mathcal{T},
u}$ on $\mathbb{R}^2$ by
 egin{equation}
\mu_{\mathcal{T},
u}(A) = \sum_{t \in \mathcal{T}} 
u_t(A_{t}), \mbox{ where } A_{t} = \{ y \in \mathbb{R}: (t,y) \in A\}.
\end{equation}

[Theorem 9 of arXiv:2605.30737, 'Reducing Kolmogorov’s Reversibility Criterion Via a Basis for the Interaction Graph Kernel'] Given a continuous time Markov chain with finite state space $S$, such that $|S|=N$ and infinitesimal generator $Q$ such that
 $q_{ij}>0$ for all $i\neq j$; a necessary and sufficient condition for a chain to be in equilibrium is that for all triple
$(i,i+1,i+1+j)$ with $1\le i\le N-2$ and $1\le j\le N-(i+1)$, the determinants  
\begin{eqnarray}
\Delta_{(i,i+1,i+1+j)}:=&\left|\begin{array}{ccc}
q_{i,i+1}&-q_{i+1, i}&0\\
q_{i, i+1+j}&0&-q_{i+1+j, i}\\
0&q_{i+1,i+1+j}&-q_{i+1+j, i+1}
\end{array}\right|
\end{eqnarray}
are equal to zero.

