[Corollary 17 of arXiv:2606.01832, 'MA(1) processes with uniform innovations conditioned to stay positive in the non-expanding'] For $\theta <0$ and $a>0$, we have with the abbreviation $\tilde{y}\coloneqq\frac{-y}{a}$ on the common domain of convergence       \begin{align}
        \hat{P}_{a,y,\theta}(z)=\frac{\hat{P}_{\frac{1}{a},\tilde{y},\theta}(-z)}{1-z\cdot\hat{P}_{\frac{1}{a},\theta}(-z)}.
    \end{align}

[Definition 144 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] With the notations  of \Cref{prop:AI}, set  $Q = \mathfrak{d} q / 2$ and $M = \mu/\gamma''$. Define 
                \begin{equation}
                \Phi_{M,Q}({\hat x}):={\hat x}+Q(M{\hat x}+ {\hat x}^2),
              \end{equation}
              so that the change of variables \eqref{eq:C138} from $(X,Y)$ to $({\hat x},{\hat y})$ is $(X,Y)=(\Phi_{M,Q}({\hat x}),{\hat y})$. Define $G_{M,Q}({\hat x},{\hat y}):=\mathtt H_{\gamma''}\bigl(\Phi_{M,Q}({\hat x}),{\hat y}\bigr).$ Given $h>0$ and ${\hat x}$ such that ${\hat x},\Phi_{M,Q}({\hat x})>-\sqrt{2h/\gamma''}$, let $U_h({\hat x})$ and $U_{h;M,Q}({\hat x})$ denote the unique values such that
              \begin{equation}
                \mathtt H_{\gamma''}({\hat x},U_h({\hat x}))=
                G_{M,Q}({\hat x},U_{h;M,Q}({\hat x}))\Bigl(=\mathtt H_{\gamma''}(\Phi_{M,Q}({\hat x}),U_{h;M,Q}({\hat x}))\Bigr)=h.

              \end{equation}

[Lemma msc_imaginary_bounds of arXiv:2606.17425, 'Order statistics for edge eigenvectors of Wigner matrices'] The imaginary part of the Stieltjes transform of the semicircular law satisfies
	\begin{equation}
		\left\lvert\im m_{\mathrm{sc}}(z)\right\rvert \sim \begin{cases}
			\sqrt{\kappa + b}, & \mathrm{if } a \in [-2, 2], \\
			\frac{b}{\sqrt{\kappa + b}}, & \mathrm{otherwise},
		\end{cases}

	\end{equation}
	uniformly in $z \in \{a + \ii b : \left\lverta\right\rvert \le 5, 0 < b \le 10\}$, with $\kappa := \min\{\left\lverta - 2\right\rvert, \left\lverta + 2\right\rvert\}$. Moreover, $\left\lvertm_{\mathrm{sc}}(z)\right\rvert \le 1$ holds on the same spectral domain. (Proof in the paper; no proof environment follows the statement in the TeX.)

