[Lemma partialt of arXiv:2512.06640, 'Existence and sharpness of the phase transition for the frog model on transitive graphs'] For any $\lambda, t > 0$ and any finite set $\Lambda \subset V$, we have
\begin{align}
    \frac{\partial}{\partial t} \mathbb P_{\lambda, t}(\mathbf{0} \xrightarrow[]{} \Lambda^c) \ge \frac{\lambda e^{-t}}{ t} \inf_{\substack{  S \ni \mathbf{0}  \\ S \subseteq \Lambda}} \phi_{\lambda, t}(S) \left( 1 - \mathbb P_{\lambda, t}(\mathbf{0} \xrightarrow[]{}\Lambda^c) \right).
\end{align}

[Proposition eq:theta_upper_semi_continuity of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{prop:theta_upper_semi_continuity}
    Let $G$ be a transitive graph of polynomial growth, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel.

    Let $\beta \in \mathbf{R}_+$ and let $\beta_n \to \beta$.

    Let $(G_n,J_n)_{n \in \mathbf{N}}$ be a sequence of transitive graphs and kernels converging locally to $(G,J)$ with $(J_n)_{n \in \mathbf{N}}$ uniformly integrable. 

    Then

    \begin{equation}

        \limsup_{n \to \infty} 
        \theta(\beta_n,G_n,J_n) 
        \leq 
        \theta(\beta,G,J).
    \end{equation}

[Lemma 21 of arXiv:2607.06428, 'Impact of spinning on the early-warning signs in non-Markovian stochastic systems'] Let $(\mathbf{x}_t)_{t\geq 0}$ be the stationary solution of \eqref{eq:fast system} in the setting \nameref{S2}. Then, the SD of $\mathbf{x}$ denoted by $ S_{\mathbf{x}\mathbf{x}}$ is given for all $H\in(0,1)$ by
    \begin{align}
    S_{\mathbf{x}\mathbf{x}}(\omega) = C_H\left(M(\lambda)-i\omega I\right)^{-1}Q\left(M(\lambda)^*+i\omega I\right)^{-1}|\omega|^{1-2H}.
    \end{align}

[Prop PropositionLimitingGibbs of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] Let $(\mathcal{L}^{(N)})_{N\in\mathbb{N}} $ be a sequence of line ensembles such that for each $N\in\mathbb{N}$, with $\mathcal{L}^{(N)}\in \mathrm{C}(\llbracket 1, N \rrbracket \times \mathbb{R}_+)$  satisfies the Gibbs resampling property with respect to the law of a $\mathsf{A}_N$-bridge. Let $\mathcal{L}$ be a $\mathrm{C}(\mathbb{N}\times\mathbb{R}_+)$-valued line ensemble. Moreover, assume that as $N \longrightarrow \infty$, for all $M \in \mathbb{N}$ (when $N\ge M$),
\begin{align*} \left(\mathcal{L}^{(N)}_{i}(t)\right)_{i\in \llbracket 1, M \rrbracket, t\in \mathbb{R}_+}\overset{\mathrm{d}}{\longrightarrow}\left(\mathcal{L}_{i}(t)\right)_{i\in \llbracket 1, M \rrbracket, t\in \mathbb{R}_+} \ \textnormal{ in }\; \mathrm{C}\left(\llbracket 1, M \rrbracket \times\mathbb{R}_+\right), 
\end{align*}
and that for any fixed $t\ge 0$, almost surely $(\mathcal{L}_i(t))_{i\in \mathbb{N}}\in \mathbf{W}_\infty^\circ$. Finally, we assume that for any $[a,b]\subset \mathbb{R}_+$ and any $x_N,y_N \in \mathbb{R}$, whenever $x_N \to x$ and $y_N \to y$, we have the weak convergence of probability measures
\begin{equation*}
\mathbf{P}_N^{a,b;x_N,y_N} \longrightarrow\mathbf{P}^{a,b;x,y}, \ \ \textnormal{ as } N \longrightarrow\infty,
\end{equation*}
where $\mathbf{P}_N^{a,b;x_N,y_N}$ and $\mathbf{P}^{a,b;x,y}$ correspond to the law of a $\mathsf{A}_N$-bridge and $\mathsf{A}$-bridge respectively. Then, $\mathcal{L}$ satisfies the Gibbs resampling property with respect to the law of an $\mathsf{A}$-bridge.
In particular, the paths of $\mathcal{L}$ are almost surely non-intersecting.

[Theorem 38 of arXiv:2608.30570, '2608.30570'] Suppose $\Sigma$ is a complete translating soliton in ${\mathbb R}^4$ satisfying the assumptions in Theorem \ref{maintheorem}, then there exists a constant $C$ depending on $\Lambda$ and $\delta$ such that
		\begin{equation}
			|\overline{\nabla}J_{\Sigma}|^2(x) \leq C|x|^{-\frac{\beta}{4}},\ \ for\ \ all \ |x|\geq R_2+2,
		\end{equation}
where $\beta$ and $R_2$ are given in Theorem \ref{prop-alpha-decay}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 (Large-trace spectral structure) of arXiv:2609.03958, '2609.03958'] Let $n\geq 2$ and $K\geq 0$. Suppose that $\lambda\in \Gamma_2$ satisfies $\lambda_1\ge\cdots\ge\lambda_n\geq -K$ and $\sigma_2(\lambda)=f$ with $f_0\leq f\leq f_1$ for two constants $f_1\geq f_0>0$.  Then there exists  $S_0 >0$ depending only on
$n$, $K$, $f_0$ and $f_1$ such that whenever $\sigma_1(\lambda)\geq S_0$, we have 
$$\frac{\sigma_1(\lambda)}{n}\leq  \lambda_1\leq \sigma_{1}(\lambda),$$
$$-K\leq\lambda_i  \leq n \frac{2(f_1+(n-1)^2K^2)}{S_0}+(n-2)K,\qquad i\geq2,$$
\begin{equation}
  \frac{f_0}{2\sigma_1(\lambda)}\leq  \sigma_{1;1}(\lambda)\leq  \frac{2n(f_1+(n-1)^2K^2)}{\sigma_1(\lambda)},
\end{equation}
$$\frac{1}{2}\sigma_1(\lambda)\leq \sigma_{1;i}(\lambda)\leq 2\sigma_1(\lambda),\qquad i\geq2.$$
In fact, we can take 
\begin{equation*}
  \begin{split}
    S_0&=\max \Big \{2n(n-1)K, \sqrt{\frac{n-2}{n-1} } \frac{2n(f_1+(n-1)^2K^2)}{\sqrt{f_0}},  \\
      & (n-2)K+\sqrt{4nf_1+(4n(n-1)^2+(n-2)^2)K^2}\Big \}.
  \end{split}
\end{equation*}

