body:
[Proposition 43 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] Let $V_0, V_1 \in \cC^4(X_1,\dots,X_d)$ be self-adjoint, i.e., such that for all $(\cA,\tau) \in\W$, $x_1,\dots,x_d\in\cA$ self-adjoint, $V_0(x)$ and $V_1(x)$ are self-adjoint. Let $(\bX_t^{s,H})_{t\geq 0}$ be the solution of
    \begin{equation}

        \bX_{t,p}^s(H) = H - \frac{1}{2} \int_0^t \bD_p V_s\left( \bX_u^s(H) \right) du + S^N_p(t),\quad 1\leq p\leq d,
    \end{equation}
    where $V_s\coloneqq s V_0 + (1-s) V_1$, $\bD_p \coloneqq \cD_p + \id\otimes\tr \circ \widetilde{\partial}_p$, and $S^N_p(t) \coloneqq S_{t,p}(X^N)$ where $X^N$ is a family of independent GUE random matrices and $S_{t,p}$ is as in Equation \eqref{skgjnslvms}. We set 
    \begin{equation}

        \Psi_s:H\in\M_N(\C)_{sa}^d \mapsto \left( -\frac{1}{2} \int_0^{\infty}\E\left[ \bD_p\left( \dot{V}_s\circ \bX_t^s\right)(H)  \right]  dt \right)_{1\leq p\leq d},
    \end{equation}
    where $\dot{V}_s = V_1-V_0$.
    Then, if $(T_s^N)_{0\leq s\leq 1}$ is solution to the linear differential equation
    $$ \dot{T}_s^N = \Psi_s \circ T_s^N,\quad T_0^N=\id_{\M_N(\C)_{sa}^d},$$
    then it is a transport map between $V_0$ and $V_1$. Concretely, for all measurable function $f$,
    $$ \int_{\M_N(\C)_{sa}^d} f(H) \frac{e^{-N\Tr_N(V_s(H))}}{Z_{V_s}}\ dH = \int_{\M_N(\C)_{sa}^d} f\circ T_s^N(H) \frac{e^{-N\Tr_N(V_0(H))}}{Z_{V_0}}\ dH. $$

[Proposition u1pn of arXiv:2411.16647, 'The stochastic evolution of an infinite population with logistic-type interaction'] Assume that: (a) for each $t>0$, the family $\{\mu^\sigma_t: \sigma \in (0,1]\}\subset \mathcal{P}(\Gamma_*)$ is weakly relatively compact; (b) for each $T>0$, there exists $C(T)>0$ such that for each triple $(t_1, t_2 , t_3)$ satisfying $t_3\leq T$ the following holds
 \begin{equation}

  \widehat{W}^\sigma(t_1, t_2, t_3) \leq C(T)(t_3 - t_1)^2. 
 \end{equation} 
Then:
\begin{itemize}
 \item[(i)] For each $\sigma\in (0,1]$, the transition function $p^\sigma$ and $\mu\in \mathcal{P}_{\rm exp}$, see (equation u5 of the paper), determine a probability measure $P^\sigma_\mu$ on $\mathfrak{D}_{\mathds{R}_{+}} (\Gamma_*)$.
 \item[(ii)] The family $\{P^\sigma_\mu: \sigma\in (0,1]\}$ of the path measures just mentioned is tight, hence possesses accumulation points in the weak topology of $\mathcal{P}(\mathfrak{D}_{\mathds{R}_{+}}(\Gamma_*))$. 
 \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

