[Defn 2 of arXiv:2608.11695, 'Generalised stochastic curvature flow in $d \geq 2$, and sharp interface limit for the sto'] For $\alpha \in (\frac{1}{3}, \frac{1}{2}]$, an $\alpha$-H\"older rough path over $\RR^m$ is a pair $\X = (X, \XX)$ with $X: [0,T] \rightarrow \RR^m$ and $\XX: \Delta_{[0,T]} \rightarrow \RR^{m \times m}$ such that
    \begin{itemize}
        \item Chen's identity: for every $0 \leq s \leq r \leq t \leq T$, one has
        \begin{equation*}
            \XX_{s,t} = \XX_{s,r} + \XX_{r,t} + (X_r - X_s) \otimes (X_t - X_r)
        \end{equation*}
        \item We have
        \begin{equation*}
            \|X\|_\alpha := \sup_{0 \leq s < t \leq T} \frac{|X_t - X_s|}{|t-s|^\alpha} < +\infty\;, \quad \|\XX\|_{2 \alpha} := \sup_{0 \leq s < t \leq T} \frac{|\XX_{s,t}|}{|t-s|^{2\alpha}} < +\infty\;.
        \end{equation*}
    \end{itemize}

[Lemma 15 of arXiv:2607.08129, '2607.08129'] For $\delta>0$, set
\begin{equation}
 V_n(\delta)
 :=\sup_{\substack{0\le s\le t\le1\\t-s\le\delta}}
 \frac1{n\log n}
 \sum_{\sqrt n<p\le n}(\log p)^2
 \Prob(s<x_{n,p}G_{n,p}\le t).
\end{equation}
Then
\begin{equation}
 \limsup_{n\to\infty}V_n(\delta)
 \le2c_\theta\delta,
 \qquad 0<\delta\le1.
\end{equation}

