[Theorem 5 of arXiv:2608.12070, 'Central limit theorems for a heavy-tailed subcritical Galton-Watson process with state-dep'] Suppose the process $\mathbf{X}=\{X_n:n\geq0\}$ is defined by \eqref{111} and satisfies {\bf (B)}. Then as $n\to \infty$,  
\begin{align*}
\frac{S_n-  n\beta\pi_0/(1-m)}{a_n}\stackrel{d}{\rightarrow} \pi_0^{-1/\alpha}\zeta_\alpha,
\end{align*}
where $a_n$ and $\zeta_\alpha$ are the same as in Theorem \ref{th02}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 of arXiv:2609.03243, 'Weighted Ces\`aro type operators on the weighted Bergman spaces in the unit ball'] Let $0<p<\infty$ and $I_k=[1-2^{-k}, 1-2^{-(k+1)})$ for $k\geq 1$. Then
\begin{equation}
\sum_{k=1}^{\infty}2^{-k(n+1+\alpha)}\sup_{t\in I_k}|f(tz)|^p\lesssim \|f\|_{p,\alpha}^p
\end{equation}
for all $f\in A_{\alpha}^p(\mathbb{B}_n)$ and $z\in\mathbb{B}_n$.

[Theorem thm:criterion-edge of arXiv:2606.30517, '\textsc{Convergence towards Ideal Poisson--Voronoi tessellations with a focus on Diestel--'] Let $E$ be the weighted edge-measured graph corresponding to a weighted graph $G$, and let $\mathbf{o}\in G$.


			If the following conditions hold for some sequence $(\lambda_n)_{n \geq 1}$, then the limit measure $\nu \coloneqq \lim_{n \to \infty}\lambda_n \iota_n^*\mu$‌ exists in $\mathcal M$.
			\begin{enumerate}[label=(\roman*)]
				\item  $\restrict{F}{\mathbb N}$ is log-regularly varying with index $b>0$, and
				\item  the measures $\lambda_n\alpha_0^n$ and $\lambda_n\alpha_1^n$, defined in~(equation eq:inter-level of the paper) and~(equation eq:same-level of the paper) (representing same-level and inter-level edges), regarded as measures on $\overline{G}^2$, converge weakly to finite measure $\alpha_0$ and $\alpha_1$ on $(\partial G)^2$ respectively.

			\end{enumerate}

			Moreover, under (thm:criterion-edge:1 of the paper) and~(thm:criterion-edge:2 of the paper), $\nu$ exists and is nonzero if and only if $\lim_{n \to \infty} \lambda_n F(n) = p^{\xi}$ for some $\xi\in\mathbb R$, where $p=e^b$. 

			In this case, if the total mass of $\alpha_i$ is $c_i$ for $i=0,1$, then the claims of (thm:critArithmetic of the paper)  hold for $\varphi \coloneqq \frac{2 c_0+c_1}{c_0+c_1} \restrict{\mathrm{Leb}}{[0,1/2]} + \frac{c_1}{c_0+c_1} \restrict{\mathrm{Leb}}{[1/2,1]}$ and 
