\begin{equation}
E_{\mathbb{H}}Z=U\begin{pmatrix}\iint_{(-\infty,\lambda_{1}]\times(-\infty,\lambda_{2}]}ug_{1}(u,v)dudv & 0\\
0 & \iint_{(-\infty,\lambda_{1}]\times(-\infty,\lambda_{2}]}vg_{2}(u,v)dudv
\end{pmatrix}U.
\end{equation}

[Definition 15 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $\left(\mathcal{X},\rho\right)$ be a metric space. A map $f:\mathcal{X}\rightarrow\mathcal{X}$ is said to be a contraction mapping if there exists a real constant $k\in[0,1)$ such that
    \begin{equation*}
        \rho(f(x),f(y)) \leq k\rho(x,y),\quad \forall x,y\in\mathcal{X}.
    \end{equation*}

[Proposition 18 of arXiv:2604.23656, 'Doubly Reflected Backward SDEs Driven by $G$-Brownian Motion with Quadratic Generator'] Let $\xi,f$ satisfies (H1) and (H3). Assume that $L,U\in S^{2p}_G(0,T)$ satisfies $L_t\leq N_1\leq U_t$, q.s. for any $t\in[0,T]$, where $p>1$ and $N_1\in\mathbb{R}$. Suppose that $(Y,Z,A)\in \mathcal{S}^{2p}_G(0,T)$ is a solution to the doubly reflected $G$-BSDE with parameters $(\xi,g,L,U)$ such that $(Y,A)$ satisfies $(\textmd{ASC}_{2p})$. Moreover, assume that 
    \begin{align*}
        \|L_z(1+|Z|)\|_{BMO_G}<\phi(q):\left(1+\frac{1}{q^2}\log \frac{2q-1}{2(q-1)}\right)^{\frac{1}{2}}-1,
    \end{align*}
    where $q$ satisfies $p>\frac{q}{q-1}$. Then, there exists a constant $C:=C(T,L_z,L_y,\bar{\sigma},N_1)$, such that for any $t\in[0,T]$
    \begin{align*}
        \|Y_t\|_{L^\infty_G}\leq C\left(1+\|\xi\|_{L^\infty_G}+\left\|\int_0^T|g(s,0,0)|^2ds\right\|_{L^\infty_G}^{\frac{1}{2}}\right).
    \end{align*}

