[Question of arXiv:2609.00436, 'A counterexample to the stable forking conjecture'] \begin{itemize}
            \item Do supersimple theories of finite $\mathrm{SU}$-rank satisfy the conclusion of the stable forking conjecture?

            \begin{itemize}
                \item Is the conclusion of the stable forking conjecture satisfied for $a, b  \subset \mathbb{M} \models T$, for a supersimple theory $T$ and $a\mathop{\mathpalette\setbox0=\hbox{$x$}\kern\wd0\hbox to 0pt{\mathchardef \nn=12854\hss$\nn$\kern1.4\wd0\hss}\hbox to 0pt{\hss$\mid$\hss}\lower.9\ht0 \hbox to 0pt{\hss$\smile$\hss}\kern\wd0{}} b$, where $\mathrm{SU}(a)=\mathrm{SU}(b) = 3$?\footnote{As stated in the introduction, Brower proves the case where $\mathrm{SU}(a) = 2$ and $\mathrm{SU}(b) < \omega$, improving on work of Peretz, so this is the least-rank case that remains open.}
            \end{itemize}
            \item Do countably categorical simple theories satisfy the conclusion of the stable forking conjecture?
        \end{itemize} (Stated as a question by the paper; open unless the paper says otherwise.)

[Theorem 108 (Critical logarithmic Wick multipliers via gap reconstruction) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Assume the hypotheses of
Theorem~\ref{thm:geom-covariance-block-transfer} and the profile growth
\eqref{eq:geom-general-profile-growth}.  Define
\begin{equation}

 \LogOp:=\log(e+\Lambda_g).
\end{equation}
For dyadic $L,Q$, define
\[
 A_{L,a,\alpha}:=\Lambda_g^{-a}\LogOp^{-\alpha}\Delta_L,
 \qquad
 B_{Q,b,\zeta}:=\Delta_Q\LogOp^{-\zeta}\Lambda_g^{-b},
\]
let $a_{L,a,\alpha,x}$ and $b_{Q,b,\zeta,x}$ be their $x$-columns, and put
\begin{equation}

 K_{\nu,L,Q}^{a,b;\alpha,\zeta}
 :=\int_M\eta_{\nu,x}^{\otimes m}
 \otimes\overline{b_{Q,b,\zeta,x}}
 \otimes a_{L,a,\alpha,x}\,dV_g(x).
\end{equation}
Then
\begin{equation}

 I_m(K_{\nu,L,Q}^{a,b;\alpha,\zeta};W)
 =A_{L,a,\alpha}M_{\Phi_{m,\nu}}B_{Q,b,\zeta}.
\end{equation}
Let $1\le q<\infty$, assume $\beta<d/q$, let
$\alpha,\zeta\in\R$, and assume
\begin{equation}

 a>\beta,\qquad b>\beta,\qquad
 a+b=\beta+\frac dq,
 \qquad
 \rho_{\log,q}:=\alpha+\zeta-\kappa-\frac1q>0.
\end{equation}
Then the coefficient series
$\sum_{L,Q}K_{\nu,L,Q}^{a,b;\alpha,\zeta}$ converges unconditionally in
$\Coeff_{m,q}$, and its evaluation defines
\begin{equation}

 T_\nu^{a,b;\alpha,\zeta}
 :=\Lambda_g^{-a}\LogOp^{-\alpha}
   M_{\Phi_{m,\nu}}
   \LogOp^{-\zeta}\Lambda_g^{-b}
 \in L^p(\Omega;\Sch_q)
\end{equation}
for every finite $p$.  The family is uniformly bounded in every such space.
If the covariance family is ultraviolet Cauchy at order $m$, then
$T_\nu^{a,b;\alpha,\zeta}$ converges in every finite
$L^p(\Omega;\Sch_q)$ to a canonical limit, independent of every jointly
compatible ultraviolet profile and of the admissible dyadic resolution.

If, in addition,
$\varepsilon_{N,N'}^{(m)}\lesssim N^{-\vartheta}$ for $N'\ge N$, then
\begin{equation}

 \|T_N^{a,b;\alpha,\zeta}-T^{a,b;\alpha,\zeta}\|
 _{L^p(\Omega;\Sch_q)}
 \lesssim_{m,q}(p+q+2)^{m/2}
 \ell_N^{-\rho_{\log,q}}.
\end{equation}
The convergence is almost sure in $\Sch_q$ along dyadic ultraviolet cutoffs.
Moreover,
\begin{equation}

 (T^{a,b;\alpha,\zeta})^*=T^{b,a;\zeta,\alpha}.
\end{equation}

