 \begin{align}
&- D\mathbb{E}\langle \underline{G_1E_aM_2HG_2E_b}\rangle=\opr{N^{-3/2}\eta^{-2} +N^{-2}\eta^{-2}\big\|\big({1-\widehat M}\big)^{-1}\big\|} \nonumber\\ &+\frac{D\kappa^{(2, 2)}}{N}\sum_{x=1}^D \left[  { \langle \mathrm{diag}(M_2)^2E_x\rangle }\widetilde K_{ba}(M_2\mathrm{diag}(M_2)E_x) +\langle M_1 \mathrm{diag}(M_2)E_x\rangle  \widetilde K_{bx}(\mathrm{diag}(M_1E_aM_2))\right]\nonumber\\
&+\frac{D\kappa^{(2, 2)}}{N}\sum_{x=1}^D   \left[\langle M_1E_aM_2 \mathrm{diag}(M_1)E_x\rangle  \widetilde K_{bx}(\mathrm{diag}(M_1))+\langle M_1E_aM_2 \mathrm{diag}(M_2)E_x\rangle  \widetilde K_{bx}(\mathrm{diag}(M_2))\right]  ,
    \end{align}
