[Theorem 5 of arXiv:2608.13235, 'Mixing Properties of Random Laguerre Tessellations'] Let $\ppp$ be a stationary marked point process on $\rd \times \R$ with a stationary mark distribution $\markdist$. Assume that there exists $\delta > 0$ such that the typical mark $M \sim \markdist$ satisfies 
\begin{equation} 
\e M_-^\frac{d+\delta}{2}< \infty,
\end{equation} 
where $M_-$ is the negative part of $M$. Then the following implications hold.
\begin{itemize}
    \item[(a)] If $\ppp$ is ergodic, then $L(\ppp)$ is \as a tessellation of $\rd$ and it is also ergodic.
    \item[(b)] If $\ppp$ is mixing, then $L(\ppp)$ is mixing.
    \item[(c)] If $\ppp$ is $\alpha$-mixing, then $L(\ppp)$ is $\alpha$-mixing.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2608.30602, '2608.30602'] Suppose that $f$ is smooth on $(0,\infty)$ and that
\begin{equation}
e^{\mp iz}f^{(m)}(z)=\Pi_{m}^{\pm}(z)=\mathcal{O}_{\infty}(z^{\sigma_{m}}),
\qquad m=0,1,2.
\end{equation}
Then, for $k=0,1,2$,
\begin{equation}
\bigl|\partial_{\lambda}^{k}\mathcal{A}_{f}^{\pm}(\lambda,a,b)\bigr|
\lesssim \lambda^{2-k}\langle x\rangle^{2}
\Bigl[(\lambda(a+b))^{\sigma_{0}}+(\lambda a)^{\sigma_{0}}
+(\lambda a)^{\sigma_{1}}\Bigr],
\qquad \lambda|b|\gtrsim 1,
\end{equation}
and, whenever $\sigma_{2}\in[-2,0]$ and $\lambda|b|\lesssim1$,
\begin{equation}
\begin{aligned}
\bigl|\partial_{\lambda}^{k}\mathcal{A}_{f}^{\pm}(\lambda,a,b)\bigr|
\lesssim\lambda^{2-k}\langle x\rangle^{2}
\begin{cases}
(\lambda a)^{\sigma_{1}-1}+\bigl(\lambda a\bigr)^{\sigma_{2}},
&\sigma_2\in (-2, 0], \\[4pt]
(\lambda a)^{\sigma_{1}-1}
+(\lambda a)^{-\frac32}(\lambda a+\lambda b)^{-\frac12},
&\sigma_2=-2.
\end{cases}
\end{aligned}
\end{equation}

