body:
[Corollary 14 (Extended restatement of \autoref{cor:linear-persistent-excitation}) of arXiv:2608.24426, 'Sequential operator learning under dependent data'] Let the assumptions of \autoref{thr:linear-regression} hold and define $\operator{G}_\iteridx:=\sum_{i=1}^\iteridx\obsop_i\obsop_i^\adj$. Suppose there exists a fixed $d$-dimensional subspace $\mathcal{S}\subset\fspace$, constants $L,\kappa>0$, and $\iteridx_0\in\N$ such that, almost surely, $\operatorname{Ran}(\obsop_\iteridx)\subseteq\mathcal{S}$ and $\norm{\obsop_\iteridx}_\opnorm\leq L$ for every $\iteridx\in\N$, while:
\begin{equation}
    \operator{G}_\iteridx
    \succeq
    \kappa\iteridx P_{\mathcal{S}},
    \qquad
    \iteridx\geq\iteridx_0,

\end{equation}
where $P_{\mathcal{S}}$ denotes the orthogonal projection onto $\mathcal{S}$ in $\mdlspace$. Let $C_{\mathcal{S}} := \sup_{\substack{\testop\in\mathcal{S}\\\testop\neq0}} \frac{\norm{\testop}_1}{\norm{\testop}_2} <\infty$. Then, for every $\delta\in(0,1]$, with probability at least $1-\delta$, simultaneously for every $\iteridx\geq\iteridx_0$ and $\testop\in\mathcal{S}$,
\begin{equation}
    \abs{\pairing{\targetop-\learntop_\iteridx,\testop}}
    \leq
    \frac{
        \regfactor C_{\mathcal{S}}
        \norm{\targetop}_\opnorm
        \norm{\testop}_2
    }{
        \regfactor+\kappa\iteridx
    }
    +
    \frac{
        \sigma_\vnoise\norm{\testop}_2
    }{
        \sqrt{\regfactor+\kappa\iteridx}
    }
    \sqrt{
        2\log\frac{1}{\delta}
        +
        d\log\paren*{
            1+\frac{\iteridx L^2}{\regfactor}
        }
    }.

\end{equation}
Consequently, for fixed $\delta$ and $\testop\in\mathcal{S}$,
\begin{equation*}
    \abs{\pairing{\targetop-\learntop_\iteridx,\testop}}
    =
    O\paren*{
        \sqrt{\frac{\log\iteridx}{\iteridx}}
    }.
\end{equation*}

