body:
[Lemma lem:stable-conditions of arXiv:2411.09716, 'Stable Tables'] A matching $\mu$ is stable under preferences $\pi\in \Pi_n$ if and only if:
\begin{enumerate}
    \item all natural pairs are matched to each other,
    \item all preferred people are matched to someone,
    \item and no two neighbors are both unmatched.
\end{enumerate}

[Corollary EPOV of arXiv:2505.13382, 'The localization transition for the directed polymer in a random environment is smooth'] For every $K>0$ we have
\begin{equation}
 \lim_{\beta  \downarrow \beta_c} (\beta-\beta_c)^{-K} \limsup_{n\to \infty} \mathrm{EP
    }^{\beta,\omega}_n =0.
\end{equation}
If the environment is Gaussian ($\omega_{1,0}\sim {\ensuremath{\mathcal N}} (0,1)$)  then for every $K>0$,
\begin{equation}
  \lim_{\beta  \downarrow \beta_c}  (\beta-\beta_c)^{-K}\limsup_{n\to \infty} {\ensuremath{\mathbb E}} \left[ \mathrm{OV}^{\beta,\omega}_n \right]=0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conjecture Belinsky, 1997 of arXiv:2608.30575, 'A Counterexample to Belinsky's Conjecture on Ces\`aro Means at Lebesgue Points'] Let $(a_k)$ be a convex increasing sequence of positive integers. Then
(equation CTZ of the paper) is necessary and sufficient for
\begin{equation*}
 T_m^a f(x)\longrightarrow f(x)
\end{equation*}
at every Lebesgue point $x$ of every function $f\in L^1(\mathbb T)$. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Cor 6 of arXiv:2512.05687, '$L^p$-Boltzmann-Gibbs principle \\ via Littlewood-Paley-Stein inequality'] Let $p\ge 2$.
For a function $F=F(t,\eta)$ on $[0,T]\times \mathcal{X}_{N,m}$, we have
\begin{align*}
E_{\mu_{N,m}}\Big[ \sup_{t\in [0,T]} \Big| \int_0^t L_0F(s,\eta_s^N) ds\Big|^p \Big]
\le C_p N^{-p} T^{(p-2)/2} \int_0^T E^{\mu_{N,m}}\Big[ \{\Ga(F(t,\cdot))\}^{p/2} \Big] dt.
\end{align*}
In particular, for  $V(s,\eta)$ on $[0,T]\times \mathcal{X}_{N,m}$ satisfying
$E^{\mu_{N,m}}[V(s,\cdot)]=0$ for each $s\in [0,T]$,
\begin{align*}
E_{\mu_{N,m}}\Big[ \sup_{t\in [0,T]} \Big| \int_0^t V(s,\eta_s^N) ds\Big|^p \Big]
\le C_p N^{-p} T^{(p-2)/2} \int_0^T E^{\mu_{N,m}}\Big[ \{\Ga((-L_0)^{-1}V(t,\cdot))\}^{p/2} \Big] dt.
\end{align*}
For  $V(t,s,\eta)$, $s\in [0,t]$  satisfying
$E^{\mu_{N,m}}[V(t,s,\cdot)]=0$, we have without supremum in $t$
\begin{align*}
E_{\mu_{N,m}}\Big[ \Big| \int_0^t V(t,s,\eta_s^N) ds\Big|^p \Big]
\le C_p N^{-p} t^{(p-2)/2} \int_0^t E^{\mu_{N,m}}\Big[ \{\Ga((-L_0)^{-1}V(t,s,\cdot))\}^{p/2} \Big] ds.
\end{align*}

