body:
[Lemma 11 of arXiv:2609.02610, 'The frame set of the first Hermite function'] Let $N \in \N$, $N \geq 2$, let $U\subset\C$ be a connected open neighborhood of $\lambda\in\C$,
and let $f_0,\ldots,f_{N-1}$ be holomorphic on $U$. Define
\begin{equation}
    \cW(z)
    :=
    \Wr(f_0,\ldots,f_{N-1})(z)
    =
    \det\bigl(f_j^{(r)}(z)\bigr)_{0\leq r,j<N},
    \qquad \text{ for } z\in U.
\end{equation}
Suppose that
\begin{equation}
    f_j'(\lambda)=0,
    \qquad \text{ for all } j=0,\ldots,N-1.
\end{equation}
Then
\begin{equation}
    \cW^{(m)}(\lambda)=0,
    \qquad \text{ for all } m=0,\ldots,N-2.
\end{equation}
Consequently, if $\cW\not\equiv 0$, then
\begin{equation}
    \ord_{\lambda}\cW\geq N-1.
\end{equation}

