[Proposition 27 (Elimination and zero occupation on one face) of arXiv:2605.23529, 'Generalized Bessel-Dunkl diffusions'] Assume \ref{ass:k:dom} and \ref{ass:face:sign}. Let $S\in\mathfrak S$, and let
$T,r,\eta>0$. Let $\theta$ be a stopping time such that
\begin{equation*}
    \theta\le T,
    \qquad
    \theta<\zeta \quad \text{a.s.},
    \qquad
    X(s)\in\mathcal U_{S,\eta,r},
    \quad 0\le s\le\theta .
\end{equation*}
Then, almost surely, for every $\beta\in S$ and every $t\ge0$,
\begin{equation}

    \int_0^{t\wedge\theta}
    \mathbf 1_{\{\tau_S(X(s))=0\}}\,d\Lambda^\beta(s)
    =
    0 .
\end{equation}

If, in addition, Assumption~\ref{ass:nonsticky} holds, then, almost surely,
for every $t\ge0$,
\begin{equation}

    \int_0^{t\wedge\theta}
    \mathbf 1_{\{\tau_S(X(s))=0\}}\,ds
    =
    0 .
\end{equation}

