[Theorem thm:Maruyama_stationary_increments_1 of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] Let $B$ be a real-valued Gaussian process with stationary increments.
		\begin{itemize}
			\item $B$ is ergodic (and weakly-mixing) if and only if $\mu$ is non-atomic,
			\item $B$ is mixing if and only if
			\begin{equation*}
				V_{a,b}(t) \underset{\|t\|\to +\infty}{\longrightarrow}  0, \quad a,b \in \mathbb{R}^{d},
			\end{equation*}
			where 
			\begin{align*}
				V_{a,b}(t)&=\cov{B_{-a}}{ B_{t+b}-B_{t}}\\
				&=v(t+a)+v(t+b)-v(t+a+b)-v(t).
			\end{align*}
		\end{itemize}
		In particular, if $\mu$ is absolutely continuous, then $B$ is mixing. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 (Averaged diagonal self-averaging) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] Let $A_n=(1-\alpha)I_n+\alpha W_r^{(n)}$. For every fixed
$L<\infty$,
\begin{equation}
\begin{aligned}
  \max_{0\leq k,\ell\leq L}
  \frac{1}{n}\sum_{i=1}^n
  \Bigl|
  \bigl[A_n^k(A_n^\ell)^\top\bigr]_{ii}
  -\tau_{k,\ell}
  \Bigr|^2
  \xrightarrow{\mathbb{P}}0.
\end{aligned}

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop: asymptotic of cnnk containing e and f of arXiv:2603.10738, 'Pairwise Negative Correlation for Uniform Spanning\\ Subgraphs of the Complete Graph'] Suppose $e,f$ are a pair of adjacent edges in $K_n$. Then for  $k\in\{1,2,\ldots,5\}$, we have the following estimates for $C_{n,n+k}^{e,f}$:
	\begin{equation}
	C_{n,n+1}^{e,f}={ \frac{5}{8}n^{n-1}-\frac{7\sqrt{2\pi}}{8}n^{n-\frac{3}{2}}+\frac{35}{6}n^{n-2}+O(n^{n-\frac{5}{2}}) }  \,,\nonumber
	\end{equation}
	and
	\begin{equation}
	C_{n,n+2}^{e,f}
	=\frac{15\sqrt{2\pi}}{256}n^{n + \frac{1}{2}} - \frac{35}{48}n^{n}+\frac{3179\sqrt{2\pi}}{3072}n^{n - \frac{1}{2}}+O(n^{n-1})\,,\nonumber
	\end{equation}
	and
	\begin{equation}
	C_{n,n+3}^{e,f}=\frac{221}{8064}n^{n + 2} - \frac{35\sqrt{2\pi}}{512}n^{n + \frac{3}{2}}+\frac{45173}{60480}n^{n + 1}+O(n^{n+\frac{1}{2}}) \,,\nonumber
	\end{equation}
	and
	\begin{equation}
	C_{n,n+4}^{e,f}= \frac{113\sqrt{2\pi}}{65536}n^{n + \frac{7}{2}} - \frac{221}{6912}n^{n + 3}+\frac{50909\sqrt{2\pi}}{786432}n^{n + \frac{5}{2}}+O(n^{n+2}) \,,\nonumber
	\end{equation}
	and	
	\begin{equation}
	C_{n,n+5}^{e,f}= \frac{16565}{27675648}n^{n + 5} - \frac{791\sqrt{2\pi}}{393216}n^{n + \frac{9}{2}}+\frac{1196681}{41513472}n^{n + 4}+O(n^{n+\frac{7}{2}}) \,,\nonumber
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 18 of arXiv:2604.07275, 'Some probabilistic properties and time-changed versions of a renewal process based on Mitt'] The time-changed process $\{\bar{N}^f(t)\}_{t \ge 0}$ is a renewal process with i.i.d. waiting times $\{J_n\}_{n \ge 1}$ that  satisfy 
		\begin{equation}
			\Pr\{J_n > t\}= \mathbb{E}\big((1+\lambda Y_{f}(t)) e^{-\lambda Y_{f}(t)}\big). 
		\end{equation}

