[Theorem thm:ville-expectation of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $(\mathcal{Y},\hat\mathcal{Z},T)$ be a real-valued sequential gamble space.
  Then for all $X:\mathcal{Y}^T\to\overline{\mathbb{R}}$ we have
  \begin{align}

    \overline{\textsf{\textbf{E}}} X = \inf\{ X_0 \mid \{X_t \in \mathbb{R}\}_t \text{ game-theoretic supermartingale}, X_T > X \}~,
  \end{align}
  where $X_\infty := \liminf_{t\to\infty} X_t$.

[Prop ch5-p30 of arXiv:2410.23995, 'Sample path properties of parabolic SPDEs with non constant coefficients'] Let $\Gamma$ satisfy $({\bf H_\Lambda})$ and $({\bf \bar{H}_\Gamma})$.
 Let
$Z = (Z(t,x),\, (t,x)\in[0,T]\times D)
$ be a jointly measurable adapted process such that
\begin{equation*}
\sup_{(t,x)\in[0,T]\times D}E(|Z(t,x)|^p) < \infty.
\end{equation*}
Fix $\delta\in\left]0,\frac{1-\eta}{2}\right[$ and for $(t,x)\in [0,T]\times D$, define
\begin{equation}

Y_\delta(t,x) = \int_0^t \int_{D} \Gamma(t,x;s,y) (t-s)^{-\delta}Z(s,y) W(ds,dy).
\end{equation}
Then the stochastic process $(Y_\delta(t,x),\, (t,x)\in [0,T]\times D)$ is a well-defined jointly measurable adapted process such that, for any $p\in[2,\infty[$,
\begin{equation}

\sup_{(t,x)\in [0,T]\times D} E\left(\left\vert Y_\delta(t,x)\right\vert^p\right) < \infty.
\end{equation}
In addition, the following formula holds:
\begin{align}

&\int_0^t \int_{D} \Gamma(t,x;s,y)Z(s,y) W(ds,dy)\nonumber\\
&\qquad  = \frac{\sin(\pi\delta)}{\pi} \int_0^t ds\, (t-s)^{\delta-1}\int_{D} dy\,  \Gamma(t,x;s,y)\, Y_\delta(s,y).
\end{align}

