[Proposition p: hyperfluctuating centroids of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] The point process $\Psi$, defined as in~(equation e: hyperfluctuating centroids of the paper), is solely \linebreak$(-d+4+p)$-uniform. This degree is negative iff $d\geq 5$.
\begin{proof}
    The proof is very similar to that of Proposition~(p: hyperfluctuating points in lattice of the paper). First of all, we note that $\Phi$ is $(-d+p)$-uniform, as shown in Proposition~(p: d>=1 hyperfluctuationg lattice thinning of the paper). Let $\tilde\Phi:=\Z^d+U$ and define the invariant transport kernel $K$ by
        \begin{equation}
            K_x := \I\{\Phi(\{x\})=1\} (\delta_{x+\frac{1}{2}e_1} +\delta_{x-\frac{1}{2}e_1}) + \I\{\Phi(\{x\})=0\} (\delta_{x+\frac{1}{2}e_2} +\delta_{x-\frac{1}{2}e_2}), \quad x\in\R^d.
        \end{equation}
        Note that therefore $\Psi = K\tilde\Phi$, and
        \begin{equation}
            K^\ast_x = \delta_{\frac{1}{2}e_{2-\Phi(\{x\})}} + \delta_{-\frac{1}{2}e_{2-\Phi(\{x\})}}, \quad x\in\R^d.
        \end{equation}
        Now we apply Theorem~(t:main theorem of the paper) with the parameter $\tilde{p}:=-d+2+p$. As $K$ is a transport kernel with constant mass and the transport distance is bounded by $\frac{1}{2}$, Condition~(c:condition square-integrable general with p of the paper) is obviously fulfilled. Let us now define $\Psi_q$ for $q\in\N_0$ like in~(equation e:Psi_q definition of the paper), whereby
        \begin{equation}
            \Psi_q(dy) = \bigg(\Big(\frac{1}{2}e_{2-\Phi(\{x\})}\Big)^{\otimes q} + \Big(-\frac{1}{2}e_{2-\Phi(\{x\})}\Big)^{\otimes q}\bigg) \tilde\Phi(dy).
        \end{equation}
        Hence, for $q\in2\N_0$ we have $\Psi_q = \frac{1}{2^{q-1}}(e_1^{\otimes q}-e_2^{\otimes q})\Phi + \frac{1}{2^{q-1}}e_2^{\otimes q}\tilde\Phi$, which implies that it is \linebreak $(-d+p)$-uniform for $q\in2\N$ and even of degree $\infty$ for $q=0$. Moreover, for $q\in2\N_0+1$, we have $\Psi_q = 0$, which implies that it is $\infty$-uniform. In total, Theorem~(t:main theorem of the paper) yields that $\Psi$ is \linebreak $(-d+4+p)$-uniform, where the dominant contribution comes from $\Psi_2$. We improve this result by applying Theorem~(t: main theorem rate of the paper) to show that $\Psi$ is not beyond $(-d+4+p)$-uniform. Let \linebreak $0\neq f\in\cC_c^\infty(\R, [0,\infty))$ and define $\tilde{f}:\R^d\to[0,\infty), \tilde{f}(x):=f(x_1)\cdots f(x_d), x\in\R^d$. Further, define $f_r:=f(\frac{\cdot}{r})$ and $\tilde{f}_r:=\tilde{f}(\frac{\cdot}{r})$ for $r>0$. Now we have to show that
        \begin{equation}
            \limsup_{r\to\infty} \frac{\BV\big[\Psi_2\big(\tilde{f}_r''\big)\big]}{r^{2d-(4+p)}} > 0.
        \end{equation}
        Let $\Phi_1,...,\Phi_d$ be the independent renewal processes from~(equation e: d>=1 hyperfluctuationg lattice thinning of the paper) such that $\Phi = \Phi_1\otimes\cdots\otimes \Phi_d$. As derivatives integrate to $0$, we can calculate that, as $r\to\infty$,
        \begin{align*}
            \frac{\BV\big[\Psi_2\big(\tilde{f}_r''\big)\big]}{r^{2d-(4+p)}} &= \frac{1}{4^{q-1}r^{2d-(4+p)}}\BV\big[\Phi\big(\partial_1^2 \tilde{f}_r-\partial_2^2 \tilde{f}_r\big)\big] + o(1)\nonumber\\
            &= \frac{1}{4^{q-1}r^{2d-(4+p)}}\BE\Big[\Phi\big(\partial_1^2 \tilde{f}_r-\partial_2^2 \tilde{f}_r\big)^2\Big] + o(1)\nonumber\\ 
            &= \frac{1}{4^{q-1}r^{2d-(4+p)}}\BE\Big[\big(\Phi_1(f_r'')\Phi_2(f_r)-\Phi_1(f_r)\Phi_2(f_r'')\big)^2\Big] \BE\big[\Phi_1(f_r)^2\big]^{d-2} + o(1)\nonumber\\ 
            &= \frac{2r^p}{4^{q-1}}\Big(\BE\big[\Phi_1(f_r'')^2\big]\BE\big[\Phi_1(f_r)^2\big]-\BE\big[\Phi_1(f_r'')\Phi_1(f_r)\big]^2\Big) \frac{\BE\big[\Phi_1(f_r)^2\big]^{d-2}}{r^{2d-4}} + o(1).
        \end{align*}
        Since
        \begin{align*}
            \frac{\BE\big[\Phi_1(f_r)^2\big]^{d-2}}{r^{2d-4}} &= \frac{\big(\BV[\Phi_1(f_r)]+\BE[\Phi_1([0,1))]^2\lambda_1(f)^2r^2\big)^{d-2}}{r^{2d-4}} \nonumber\\
            &\xrightarrow{r\to\infty} \BE[\Phi_1([0,1))]^{2d-4}\lambda_1(f)^{2d-4}>0,
        \end{align*}
        we can continue with
        \beg (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn d:stabilizing-graph of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] We say that a family of graphs 
    $(\Psi(\mathcal{P}_n))_{n \in \mathbb{N}}$  (where each graph is generated by the same rule \(\mu \mapsto \Psi(\mu)\) represented by the marking neighborhood $\bar N$) forms a {\em stabilizing interaction graph} \(\Psi\) on finite windows with respect to a point process \(\mathcal{P}\) if   for every \(p \in \mathbb{N}\), there exist a fast decreasing function $\varphi_p'$ (see~(equation varphibd of the paper)), such that the  interaction range satisfies:
\begin{equation} 
\sup_{1 \leq n < \infty} \sup_{x_1, \ldots, x_p \in W_n} \mathbb{P}_{\bk x1p}
\bigl(S_n(x_1, \mathcal{P}_n) > s\bigr) \leq \varphi_p'(s), \quad s > 0.
\end{equation}
Without loss of generality, we assume that $\varphi_p'(\cdot)\le \varphi_{p+1}'(\cdot)$ for $p \in \mathbb{N}$.

[Lemma 97 (Covariance--Gram identities) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Under the preceding assumptions,
\begin{equation}

 \norm K^2
 =\int_{X^2}
 \gamma(x,y)^mA(x,y)\conj{B(x,y)}
 \,d\mu(x)d\mu(y).
\end{equation}
In particular, the integral is real and nonnegative.

Let $J_j:\cH\to\cH_j$ identify $\cH$ with labelled copies and set
$\widetilde K=\Dec_mK$.  For $S\subset[m]$, $k=|S|$, define
\[
 h_{S,x}:=\bigotimes_{j\in S}J_j\eta_x,\qquad
 h_{S^c,x}:=\bigotimes_{j\in S^c}J_j\eta_x,
\]
\[
 d_{S,x}:=\conj{h_{S,x}}\otimes b_x,\qquad
 u_{S,x}:=h_{S^c,x}\otimes a_x.
\]
The synthesis operators
\begin{align}
 U_S:L^2(X)&\to\cH_{S^c}\otimes\cE,
 &U_Sf&:=\int_Xf(x)u_{S,x}\,d\mu(x),\\
 V_S:L^2(X)&\to\conj{\cH_S}\otimes\cC,
 &V_Sf&:=\int_Xf(x)d_{S,x}\,d\mu(x)
\end{align}
are Hilbert--Schmidt and, up to canonical tensor permutations,
\begin{equation}

 \Flat_S(\widetilde K)=U_SV_S^*.
\end{equation}
Their vector-valued Gram kernels are
\begin{align}
 \ip{u_{S,x}}{u_{S,y}}
 &=\gamma(x,y)^{m-k}A(x,y),\\
 \ip{d_{S,x}}{d_{S,y}}
 &=\conj{\gamma(x,y)}^{\,k}B(x,y).
\end{align}

