[Proposition prop.prop2.9 of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Let $k \in \ensuremath{\mathbb{N}}$. Given an edge $\{ y, z\} \in E$, we denote by $\widetilde G$ the graph obtained by adding $k$ new vertices on the edge $yz$ (see Figure~(fig:addingvertices of the paper)). We denote by $\widetilde J$ the collection of conductances on the graph $\widetilde G$ defined as follows:
\begin{itemize}
\item On all the edges of $\widetilde G$ which are not incident to one of the new vertices, we set $\widetilde J = J$,
\item On the edges which are incident to one of the new vertices, we set $\widetilde J = J/(k+1)$.
\end{itemize}
Then
\begin{equation*}
    \forall ~ x \in  V,~\mathrm{Var}_{\widetilde G , \widetilde J}^{\ensuremath{\mathbb{Z}}\mathrm{-GFF}}\left[ \varphi(x) \right] \leq \mathrm{Var}_{G , J}^{\ensuremath{\mathbb{Z}}\mathrm{-GFF}}\left[\varphi(x) \right].
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Geometric-time embedding) of arXiv:2608.17927, 'Near-unit-root persistence of symmetric stable \\ autoregressive sequences'] Let $X$ satisfy \eqref{eq:ar1} with innovations normalized by \eqref{eq:stable-cf}, and set
\begin{equation}

u_{0} = 0, \quad u_{n} \,\deq\, \sigma^{\alpha}\sum_{j=1}^{n}a^{-\alpha j} =
\sigma^{\alpha}\biggl(\frac{a^{-\alpha n}-1}{1-a^{\alpha}}\biggr).
\end{equation}
Then, as random elements of $\RR^{\NN_{0}}$,
\begin{equation}

(X_{n})_{n \geq 0} \,\dis\, (a^{n}(x+L_{u_{n}}))_{n \geq 0}.
\end{equation}
In particular,
\begin{equation}

Q_{n}(x;a,\alpha,\sigma) = \PP(x+L_{u_{k}} > 0,\ 1 \leq k \leq n).
\end{equation}

[Definition 10 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Stochastic Localization Process}


    Let $\nu$ be a probability measure on $\R^n$ and $B_t$ a standard Brownian motion in $\R^n$ adapted to a filtration $(\mathcal F_t)_{t\geq0}$. Let $(C_t)_{t \geq 0}$ be an $\mathcal F_t$-measurable process where $C_t \in \R^{n\times n}$ and $C_t \succ 0$. Then, we call the following measure-valued stochastic process a stochastic localization process
    \begin{align*}
        d\nu_t(x) \propto F_t(x)d\nu(x),
    \end{align*}

    where $F_t$ solves the SDEs $F_0(x) = 1$ and $dF_t(x) = F_t(x)(x-\int_{\R^n} yd\nu_t(y))\T C_t dB_t$ for all $x \in \R^n$.

[Proposition 22 of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] Let $\mathpzc{l}(D)<+\infty$\footnote{We keep denoting by $\mathpzc{l}(\cdot)$ the Lebesgue measure in $\R^d$.}. The space $C_c^2(D)$ is contained in the $L^2(D)$-domain of $-\LpsiD$ and for $u\in C_c^2(D)$ it holds that
		\begin{align*}
			\LpsiD u=\Lpsi u,\quad \textit{in $D$}.
		\end{align*}
		On the other hand, if $\mu\not\equiv0$, and if $u\in C_c^2(D)$, $u\not\equiv 0$, with $u\ge0$ or $u\le 0$, then $u$ is not in the $C_0(D)$-domain of $-\LpsiD$ (where the regularity of $D$ is implicitly assumed).

