body:
[Lemma 12 of arXiv:2608.09840, 'Langevin dynamics along the zero set of real-analytic potentials'] Let $D \subset \R^d$ be an open domain, and let $X \subset D$ be a subanalytic set closed in $D$ with a subanalytic Whitney stratification $\Scal$ that satisfies the frontier condition.
We then have:
\begin{enumerate}
\item $C^1_{c,\,\textnormal{strat}}(\Scal)$ is a subalgebra of $C_c(X)$, i.e., a linear subspace closed under pointwise products;
\item for every $\varepsilon > 0$, there is a function $\phi_\varepsilon \colon \R \to \R$ satisfying
\[
\phi_\varepsilon(t) = t \text{ on } [0,1], \quad -\varepsilon \le \phi_\varepsilon \le 1 + \varepsilon, \quad 0 \le \phi_\varepsilon(t) - \phi_\varepsilon(s) \le t-s \text{ for } s \le t,
\]
such that $\phi_\varepsilon \circ f \in C^1_{c,\,\textnormal{strat}}(\Scal)$ for every $f \in C^1_{c,\,\textnormal{strat}}(\Scal)$.
\item for any open relatively compact set $G \subset X$ and compact set $K \subset G$, there is a function $h \in C^1_{c,\,\textnormal{strat}}(\Scal)$ with $h \ge 0$, $h = 1$ on $K$, and $h = 0$ on $X \setminus G$;
\item $C^1_{c,\,\textnormal{strat}}(\Scal)$ is dense in $C_c(X)$ with respect to the uniform norm, and dense in $L^2(X,\mu)$ for any Radon measure $\mu$ on $X$.
\end{enumerate}

[Theorem 68 of arXiv:2609.03070, 'Variants of order semicontinuity in Banach lattices'] The following conditions are equivalent:
\item[(i)] $F$ is countably ($r$-)monotonically complete;
\item[(ii)] Every countable directed dominable subset of $\Ba_{F_{+}}$ has a supremum in $F$ (of norm at most $r$);
\item[(iii)] $F$ is norm complete and every countable disjoint $D\subset F_{+}$ such that $D^{\vee}\subset\Ba_{F}$ has a supremum in $F$ (of norm at most $r$);
\item[(iv)] The sequential order adherence of $\Ba_{F}$ in $F^{u}$ is contained in $F$ (in $r\Ba_{F}$);
\item[(v)] Every uo-Cauchy sequence in $\Ba_{F}$ has a uo-limit (of norm at most $r$).\medskip

In particular, $F$ is countably monotonically complete and $\sigma$-semicontinuous if and only if $\Ba_{F}$ is sequentially complete with respect to uo convergence.

[Lemma lem:sup:to:pointwise of arXiv:2607.04047, 'Top Singular Value in Sum-Products of Random Matrices'] There exists a universal constant $C > 0$ such that, for any $\epsilon \in (0,1)$ and $\theta \in \mathcal{S}^{n-1}$, we have
\begin{align*}
    {\mathbb P}\Big( 
        \Big| 
            \mfrac{1}{N}
            \log \| X \theta \|
            - 
            \mfrac{1}{N}
            \sup_{\theta' \in \mathcal{S}^{n-1}} 
            \log \| X \theta' \|
        \Big|  
        \,\geq\,
        \mfrac{1}{2 N} \log \Big( \mfrac{n}{\epsilon^2} \Big)
    \Big)
    \leq 
    (C \epsilon)^{1/2}
    \;.
\end{align*}

[Theo 14 of arXiv:2512.02766, 'Fine-Graining and Continuous Space Scaling Limit of the $H^{2|2}$ Model on the Hierarchica'] Recall from Theorem~\ref{th:VRJP_Dichotomy} that the Vertex Reinforced Jump Process on $\mathbb{X}$ with spectral dimension $d_s=2$ is either almost surely recurrent or almost surely transcient. Furthermore,
\begin{itemize}
    \item If every vertex is visited infinitely often, then almost surely, the limiting measure $\mathfrak{m}_{\mathbb{X}}$ is singular with respect to the Lebesgue measure $d\lambda$;
    \item If every vertex is visited finitely often, then almost surely, the limiting measure $\mathfrak{m}_{\mathbb{X}}$ has an absolutely continuous component with everywhere non-trivial density with respect to the Lebesgue measure $d\lambda$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t:BendikovSaloffCoste of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] The quadratic form~$(\boldsymbol\mssE,\Cyl{}{})$ on~$L^2(\boldsymbol\nu)$ defined by
\begin{equation}
\boldsymbol\mssE(u,v)\eqdef \scalar{u}{-\boldsymbol\mssL v}_{L^2(\boldsymbol\nu)} \,\mathrm{,}\;\, \qquad u,v\in \Cyl{}{}\,\mathrm{,}\;\,
\end{equation}
is closable.
Its closure~$\big({\boldsymbol\mssE,\msD(\boldsymbol\mssE)}\big)$ is a quadratic form on~$L^2(\boldsymbol\nu)$ with generator the $L^2(\boldsymbol\nu)$-Friedrichs extension~$\big({\boldsymbol\mssL,\msD(\boldsymbol\mssL)}\big)$ of~$(\boldsymbol\mssL,\Cyl{}{})$.

Further define the following assumptions:
\begin{enumerate}[$(a)$]
\item $\mssH_{k,\bullet}$ is irreducible and is represented by a kernel~$\mssh_{k,\bullet}$ absolutely continuous w.r.t.~$\nu_k$, and $\big({-\mssL_k,\msD(\mssL_k)}\big)$ has spectral gap
\[
\lambda_k\eqdef \inf \set{\scalar{-\mssL_k f}{f}_{L^2(\nu_k)}: f\in\msD(\mssL_k)\,\mathrm{,}\;\, \left\lVertf\right\rVert_{L^2(\nu_k)}=1\,\mathrm{,}\;\, \int_{M_k} f \mathop{}\!\mathrm{d}\nu_k=0}>0 \,\mathrm{.}
\]
\item there exist constants $c,C>0$ such that, for each~$k$,
\[
\nu_k^{\scriptscriptstyle\otimes 2}\text{-}\esssup_{x,y\in M_k} \mssh_{k,\epsilon_k}(x,y) \leq C \quad \text{for some~$\epsilon_k$ satisfying~$\epsilon_k\leq c/\lambda_k$}\,\mathrm{;}\;\,
\]
\item setting~$t_*\eqdef\inf\set{t>0: \sum_k e^{-2t\lambda_k}<\infty}$ it holds that~$t_*=0$;
\item $\msA_k\subset\msD(\mssL_k)$ and~$\mssH_{k,t}\msA_k\subset \msA_k$ for every~$t>0$.
\end{enumerate}

If~(i:t:BendikovSaloffCoste:a of the paper)--(i:t:BendikovSaloffCoste:e of the paper) hold, then
\begin{enumerate}[$(i)$]
\item the measure $\boldsymbol\mssh_t(\mbfx,\mathop{}\!\mathrm{d}\mbfy)\eqdef \Pi_k \mssh_{k,t}(x_k,\mathop{}\!\mathrm{d} y_k)$ is absolutely continuous w.r.t.~$\boldsymbol\nu$ for every~$t>0$ and every~$\mbfx\in\mbfM$ if and only if~(i:t:BendikovSaloffCoste:e of the paper) holds.
In this case,~$\boldsymbol\mssh_t$ has density~$\boldsymbol\mssh_t(\mbfx,\mbfy)\eqdef \Pi_k \mssh_{k,t}(x_k,y_k)$ in~$L^\infty(\boldsymbol\nu)$.
\end{enumerate}

If~(i:t:BendikovSaloffCoste:a of the paper)--(i:t:BendikovSaloffCoste:f of the paper) hold, then, additionally,
\begin{enumerate}[$(i)$]\setcounter{enumi}{1}
\item $(\boldsymbol\mssL,\Cyl{}{})$ is essentially self-adjoint on~$L^2(\boldsymbol\nu)$;
\item the semigroup~$\boldsymbol\mssT_\bullet$ of~$\big({\boldsymbol\mssL,\msD(\boldsymbol\mssL)}\big)$ coincides with the Markov semigroup~$\boldsymbol\mssH_\bullet$ represented by~$\boldsymbol\mssh_\bullet$. In particular,~$(\boldsymbol\mssE,\msD(\boldsymbol\mssE))$ is a Dirichlet form;
\item the semigroup~$\boldsymbol\mssT_\bullet$ is irreducible;
\item $(\boldsymbol\mssE,\msD(\boldsymbol\mssE))$ is a $\tau_\mrmp$-quasi-regular Dirichlet form, and it is $\tau_\mrmp$-regular if and only if cofinitely many~$M_k$'s are compact.
\item $(\boldsymbol\mssE,\msD(\boldsymbol\mssE))$ is properly associated with a Hunt process~$\boldsymbol\mssW$ identical to~$\left(\mssW_k\right)_k$ in distribution;

\item for every Borel probability measure~$\boldsymbol\sigma$ on~$\mbfM$ with~$\boldsymbol\sigma\ll\boldsymbol\nu$, the process~$\boldsymbol\mssW$ is the ---unique up to $\boldsymbol\nu$-equivalence--- $\boldsymbol\nu$-substationary (see Dfn.~(d:Substationary of the paper)) $\boldsymbol\nu$-special standard process solving the martingale problem for~$(\boldsymbol\mssL,\Cyl{}{},\boldsymbol\sigma)$. 
In particular, denoting by~$\mbfX_\bullet$ the trajectories of~$\boldsymbol\mssW$, and by~$\boldsymbol{\mathsf{\Gamma}}$ the carr\'e du champ of~$\boldsymbol\mssL$, viz.
\[
\boldsymbol{\mathsf{\Gamma}}(u,v)\eqdef \boldsymbol\mssL(uv)-u\boldsymbol\mssL v -v\boldsymbol\mssL u\,\mathrm{,}\;\, \qquad u,v\in\Cyl{}{}\,\mathrm{,}\;\,
\]
