body:
[Proposition 40 (Spatial Regularity of Convolutions) of arXiv:2607.03318, 'Continuous Differentiability of the Value Function for Infinite-Dimensional Finite-Horizon'] Let Assumptions \ref{ass:coefficients} and \ref{ass:smoothing} hold, and let $f \in \mathcal{B}_m([0, T] \times H)$. For any $t \in [0, T)$, the temporal convolution
\begin{equation}
    g(t, x) := \int_t^T P_{t,s}[f(s, \cdot)](x) \, \mathrm{d}s
\end{equation}
satisfies the following regularity properties on $H$:
\begin{enumerate}[label={(\textit{\roman*})}, leftmargin=*]
\item The mapping $g(t, \cdot)$ is continuously Fréchet differentiable on $H$. The spatial differential operator commutes with the temporal integral, and there exists a constant $C_2 > 0$ such that the following bound holds:
    \begin{equation} 
        \|\nabla g(t, x)\|_H \le C_2 \frac{(T-t)^{1-\gamma}}{1-\gamma} w_m(x) \|f\|_{\mathcal{B}_{m, T}}.
    \end{equation}

    \item The spatial gradient $x \mapsto \nabla g(t, x)$ is locally equi-Hölder continuous. Specifically, for any Hölder exponent $\beta \in (0, 1)$ satisfying $\gamma(1+\beta) < 1$, the following estimate holds for all $x, y \in H$:
    \begin{equation}
        \|\nabla g(t, x) - \nabla g(t, y)\|_H \le C_3 \frac{(T-t)^{1-\gamma(1+\beta)}}{1-\gamma(1+\beta)} \Big(1 + \sup_{z \in [x,y]} \|z\|_H^m\Big) \|f\|_{\mathcal{B}_{m, T}} \|x - y\|_H^{\beta}.
    \end{equation}
\end{enumerate}

