[Proposition eq:semi-marg of arXiv:2509.23086, 'On Optimal Markovian Couplings of L\'evy Processes'] Let $\mathcal{A},\mathcal{B}\in\mathcal{G}(\Pi)$ and $\mathcal{J}\in \mathcal{G}(\Pi^2)$. The following are equivalent.

	\begin{enumerate}[label=(\roman*)]
		\item For all $\varphi,\psi\in C_0(\Pi)$, it holds
		\begin{align}
			e^{t\mathcal{J}}[\varphi\otimes 1]=(e^{t\mathcal{A}}\varphi) \otimes 1,\qquad e^{t\mathcal{J}}[1\otimes\psi]= 1\otimes (e^{t\mathcal{B}}\psi),\qquad t\ge 0. 
		\end{align}
		\item For all $\varphi,\psi\in C_b(\Pi)$, (equation eq:semi-marg of the paper) holds. 
		\item For all $\varphi\in C(\mathcal{A}),\psi\in C(\mathcal{B})$, (equation eq:semi-marg of the paper) holds.
		\item For all $\varphi\in \bar D(\mathcal{A}),\psi\in \bar D(\mathcal{B})$, it holds
		\begin{align}
			\mathcal{J}[\varphi\otimes 1]=(\mathcal{A}\varphi)\otimes 1,\qquad \mathcal{J}[1\otimes \psi]= 1\otimes (\mathcal{B}\psi). 
		\end{align}
		\item For all $\varphi\in D(\mathcal{A}),\psi\in D(\mathcal{B})$, (equation eq:gen-marg of the paper) holds.
		\item For all $\lambda>0$, and $\varphi,\psi \in C_0(\Pi)$ that 
		\begin{align*}
			R_\lambda(\mathcal{J})[\varphi\otimes 1]= (R_\lambda(\mathcal{A})\varphi)\otimes 1, \qquad R_\lambda(\mathcal{J})[1\otimes \psi]= 1\otimes (R_\lambda(\mathcal{B})\psi).
		\end{align*}
	\end{enumerate}

[Cor 6 of arXiv:2608.26723, 'Extrinsic upper bounds for the harmonic mean of eigenvalues in curved manifolds'] Settings as in Theorem \ref{thm-nonpositive} or Theorem \ref{thm-positive}.
	If
	\begin{equation*}
		\lambda_1= \frac{m}{\vol(M)}\int_M\big(\delta+|\mathbf{H}|^2\big),
	\end{equation*}
 then the multiplicity of $\lambda_1$ is at least $m$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop main_2 of arXiv:2607.10105, 'The four-dimensional Anderson model: a case study for critical SPDEs'] Define
\begin{equation}H(x_1,y_1,x_2,y_2):=\int_{\mathbb T^4}G(x_1-z)G(y_1-z)G(x_2-z)G(y_2-z)\,\mathrm{d}z.
\end{equation} Also fix $B$ and $r$. Then, for each $1\leq m_j\leq B$ and $(\alpha_j,\beta_j)_{j\leq r}$, we have 
\begin{equation}\bigg|\mathbb E\bigg(\prod_{j=1}^r\widehat{\mathcal P_{m_j}}(\alpha_j,\beta_j)\bigg)-\sum_{\kappa}\prod_{\{i,j\}\in\kappa}\mathbb E\big(\widehat{\mathcal P_{m_i}}(\alpha_i,\beta_i)\cdot\widehat{\mathcal P_{m_j}}(\alpha_j,\beta_j)\big)\bigg|\leq\frac{(\lambda_\varepsilon)^r}{|\log\varepsilon|}\cdot O_{B,r,\alpha_j,\beta_j}(1),
\end{equation} where $\kappa$ in ((eq.setup_22 of the paper)) runs over all full pairings of $[1,r]$.

Moreover, there exists a function $\mathfrak X(m_1,m_2)$, which is bounded by $|\mathfrak X|\leq C(C\lambda)^{m_1+m_2-2}$, such that for any $m_1,m_2\leq B$ and $(\alpha_1,\beta_1,\alpha_2,\beta_2)$, we have
\begin{gather}
\big|\mathbb E\big(\widehat{\mathcal P_{m_1}}(\alpha_1,\beta_1)\cdot\widehat{\mathcal P_{m_2}}(\alpha_2,\beta_2)\big)-\lambda_\varepsilon^2\cdot\mathfrak X(m_1,m_2)\cdot\widehat{H}(\alpha_1,\beta_1,\alpha_2,\beta_2)\big|
\leq\frac{\lambda_\varepsilon^2}{|\log\varepsilon|}\cdot O_{B,\alpha_j,\beta_j}(1);\\

\sum_{m_1+m_2=m}\mathfrak X(m_1,m_2)=\left\{
\begin{aligned}
&(\lambda/\sqrt{2}\pi)^{m-2},&&\textrm{for $m$ even},\\
&0,&&\textrm{for $m$ odd}.
\end{aligned}
\right.
\end{gather}

