[Cor 6 of arXiv:2607.00853, '\sf Energy integrals and asymmetric co-potentials for closed forms'] Assume $\beta_0=0$. For any $\mu\in {\sf S}_{0}^{(0)}$ and $f\in D(\form)_e$, we have
\begin{align*}
\int_Ef^2d\mu\leq K^2\|U\mu\|_{\infty}^{1/2}\|\widehat{U}\mu\|_{\infty}^{1/2}\form(f,f).
\end{align*}
If we further assume that $(\widehat{\form},D(\form))$ satisfies $(\form.4)$, then for any $\mu\in {\sf S}$ and $f\in D(\form)_e$, we have
\begin{align*}
\int_Ef^2d\mu\leq K^2\|R\mu\|_{\infty}^{1/2}\|\widehat{R}\mu\|_{\infty}^{1/2}\form(f,f),
\end{align*}
where $R\mu(x)=\mathbb{E}_x[{\sf A}_{\infty}^{\mu}]$ and $\widehat{R}\mu(x)=\widehat{\mathbb{E}}_x[\widehat{\sf A}_{\infty}^{\mu}]$.

[Lemma lem:RBJ-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = \ell^2(\mathbb{Z})$.  The seed functions
$\psi_{t,r,n}$ and $\phi_{t,r,n}$ defined in
\S(sec:RBJ-kernel-reform of the paper) satisfy the linear problem
(equation eq:Linear-Psi-3 of the paper) and the adjoint linear problem
(equation eq:Linear-Phi-Prob of the paper) on $\mathcal{V}$ with edge
weights $(c_k, \lambda_k)$.  Explicitly, for each fixed
$r \in \mathbb{Z}$:
\begin{align}
\psi_{t,r,n+1}
&= (1{-}\theta)^{-1}\psi_{t,r+1,n}
   - (1{-}\theta)^{-1}\theta\psi_{t,r,n},
 \\
\psi_{t+1,r+1,n}
&= q\psi_{t,r+1,n}
   + p\theta\psi_{t,r,n},

\end{align}
and
\begin{align}
\phi_{t,r+1,n}
&= (1{-}\theta)^{-1}\phi_{t,r,n+1}
   - (1{-}\theta)^{-1}\theta\phi_{t,r+1,n+1},
 \\
\phi_{t,r+1,n}
&= q\phi_{t+1,r+1,n}
   + p\theta\phi_{t+1,r+2,n}.

\end{align}

