[Lem 7 (\textit{cf.} {\cite[Lemma 1.5.3) of arXiv:2511.21496, 'Optimal local central limit theorems on Wiener chaos'] {Nualartbook}}]

Let $\alpha > 0$ and $p \in (1,\infty)$. 
Let $\fE$ be a real separable Hilbert space. 
If a sequence $\{F_n\}_{n \in \N} \subset \bW^{\alpha, p}(\fE)$ converges weakly to $F$ in $L^p(\Omega; \fE)$ and satisfies
\begin{equation}
    \sup_{n \in \N} \norm{F_n}_{\bW^{\alpha, p}(\fE)} < \infty,
\end{equation}
then $F \in \bW^{\alpha, p}(\fE)$ and $F_n$ converges weakly to $F$ in $\bW^{\alpha,p}(\fE)$.
In particular, 
\begin{equation}
    \norm{F}_{\bW^{\alpha, p}(\fE)} \leq \liminf_{n \to \infty} \norm{F_{n}}_{\bW^{\alpha,p}(\fE)} \leq \sup_{n \in \N} \norm{F_n}_{\bW^{\alpha, p}(\fE)}.
\end{equation}

