[Defi defi 2.8 of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] A stochastic homeomorphisms flow of class $C^{\beta}$ with $\beta\in (0,1)$ on $(\Omega,\mathfrak{F},\mathbb{P},(\mathfrak{F}_t)_{0\leq t \leq T})$ associated to (equation 2.1 of the paper) is a map $(s,t,x,\omega)\mapsto X_t^{s,x}(\omega)$, defined for $0\leq s\leq t \leq T$, $x\in \mathbb{R}^d$, $\omega \in \Omega$ with values in $\mathbb{R}^d$, such that 
				\begin{itemize}
					\item[(i)] The process $\{ X_t^{\cdot,x}\} = \{ X_t^{s,x} \}_{s\leq t\leq T}$ is a continuous $(\mathfrak{F}_{s,t})_{s\leq t \leq T}\text{-adapted}$ solution to (equation 2.1 of the paper), for every $s\in [0,T]$, $x\in \mathbb{R}^d$;
					\item[(ii)] The function $X_t^{s,x}$ and $(X_t^{s,x})^{-1}$ are continuous in $(s,t,x)$ and are of class $C^{\beta}$ in $x$ uniformly in $(s,t)$, $\mathbb{P}\text{-a.s.},$ for all $0\leq s\leq t \leq T$;
					\item[(iii)] $X_t^{s,x} = X_t^{s,X_r^{s,x}}$ for all $0\leq s \leq r \leq t \leq T$, $x\in \mathbb{R}^{d}$, $\mathbb{P}\text{-a.s.},$ and $X_s^{s,x}= x$. 
				\end{itemize}
				Moreover, if the map $(s,t,x,\omega)\mapsto X_t^{s,x}(\omega)$ satisfies ${\bf(iv)}$, it is called a stochastic flow of $C^k$ diffeomorphisms
				\begin{itemize}
					\item[(iv)] $(s,t,x,\omega)\mapsto X_t^{s,x}(\omega)$ is $k\text{-times}$ differentiable with respect to $x$ for all $s,t$ and the derivatives are continuous in $(s,t,x)$.
				\end{itemize}

[Definition def:LSMFinite of arXiv:2601.19630, 'Mass generation for the two dimensional O(N) Linear Sigma Model in the large N limit'] The  Linear Sigma Model on $\Lambda_{L}$ corresponding to a Wick renormalization of the classical potential (equation e115 of the paper), is the unique probability measure $\nu^{N}_{m,L}$ such that for any continuous bounded observable $F: \mathcal{D}'(\Lambda_{L})^{N} \mapsto \mathbb{R}$
\begin{align}
&\int_{\mathcal{D}'(\Lambda_{L})^{N} } F(\Phi)d \nu^{N}_{m,L}(\Phi) \nonumber \\
&\stackrel{\text{def}}{=} \lim_{\epsilon \to 0} \frac{1}{\mathbf{Z}_{m,L,\epsilon}^{N,\lambda} } \int_{\mathcal{D}'(\Lambda_{L})^{N} }F(Z_{\epsilon}) \text{exp} \bigg (-\frac{\lambda}{4N}\int_{\Lambda_{L}}:\|Z_{\epsilon}(x)\|_{\mathbb{R}^{N}}^{4}:dx\bigg )  d \mu_{m,L}^{\otimes N}(Z). \nonumber 
\end{align}

[Theorem 17 of arXiv:2506.13913, '2506.13913'] {The strong Markov property for Itô diffusions}{}
Let \(\{X_t\}_{t \geq 0}\) be an Itô diffusion in \(\mathbb{R}^d\), adapted to a filtration \(\{\mathcal{F}_t\}_{t \geq 0}\), and let \(\tau\) be a \textit{stopping time} with respect to \(\{\mathcal{F}_t\}_{t \geq 0}\), meaning that \(\{\tau \leq t\} \in \mathcal{F}_t\) for all \(t \geq 0\).  
Then, for every stopping time \(\tau\), every \(t \geq 0\), and any bounded measurable function \(f: \mathbb{R}^d \to \mathbb{R}\), we have
\[
\mathbb{E} [ f(X_{t+\tau}) \mid \mathcal{F}_\tau ] = \mathbb{E} [ f(X_{t+\tau}) \mid X_\tau ], \quad \mathbb{P}-\text{a.s.}
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 11 of arXiv:2609.00739, '2609.00739'] For almost every $0<r<1$,
\begin{equation}
\int_{B_r}(2a+x\cdot\nabla a)\frac{V(u)}{\eps}
=r\int_{\partial B_r}
\left\{\frac{\eps}{2}(\abs{\nabla_\tau u}^2-\abs{\partial_ru}^2)
+\frac{a}{\eps}V(u)\right\}.
\end{equation}
More generally, for almost every admissible radius of a ball $B_r(x_0)$ with
$\overline{B_r(x_0)}\subset B_1$,
\begin{equation}
\left(2-\frac{r\norm{\nabla a}_{L^\infty}}{a_-}\right)
\mathbb V_{\eps,a}(u;B_r(x_0))
\le r\int_{\partial B_r(x_0)}e_{\eps,a}(u).
\end{equation}
Thus, if $\frac{r\norm{\nabla a}_{L^\infty}}{a_-}\leq\frac{1}{2}$,
\begin{equation}
\mathbb V_{\eps,a}(u;B_r(x_0))
\le \frac{2r}{3}\int_{\partial B_r(x_0)}e_{\eps,a}(u).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma invariance_restriction of arXiv:2411.11425, 'Non-equilibrium steady states with a spatial Markov structure'] Let $\phi:\mathbb{R}^2 \times \mathbb{R}^2\rightarrow \mathbb{R}$ be a continuous symmetric function which satisfies the following scale and shift properties

\begin{equation}
\begin{cases}
    \phi(\gamma \cdot x, \gamma \cdot y) = \widetilde{\lambda}(\gamma) \cdot \phi(x,y)\\
    \phi(x + \gamma, y + \gamma) = \widehat{\lambda}(\gamma) \cdot  \phi(x,y) 
\end{cases}
\end{equation}

for some continuous 
 functions $\widetilde{\lambda}, \widehat{\lambda}: \mathbb{R}^+ \rightarrow \mathbb{R}^+$. Then $\phi$ is of the form

\begin{equation}
    \phi(x,y) = t \cdot |x-y|^\sigma
\end{equation}
with $\sigma,t \in \mathbb{R}$. As a consequence,  $\widetilde{\lambda}(\gamma)=\gamma^\sigma$ and $\widehat{\lambda} = 1$.

