[Lemma 3 of arXiv:2608.30155, 'Gradient Estimates Near the Natural Exponent for Very Weak Solutions to $A_p$-Weighted Qua'] Let $1<p<\infty$ and let $\omega \in A_p$. Then the following properties hold:
	\begin{enumerate}
		\item[(a)] (Doubling property) Let $E$ be a measurable subset of a ball $B$. Then
		\begin{eqnarray}
			\frac{1}{[\omega]_{A_{p}}}\left( \frac{|E|}{|B|} \right)^{p}  \leq \frac{\omega(E)}{\omega(B)}.
		\end{eqnarray} In particular, the weight \(\omega\) satisfies the doubling property
		\begin{equation}
		\omega(B_{\rho})
		\leq \omega(B_{2\rho})
		\leq 2^{np}[\omega]_{A_{p}}\omega(B_{\rho}),
		\end{equation}
		for every ball \(B_{\rho}\subset \mathbb{R}^{n}\).
		\item[(b)] (Self-improving property) 
		There exists a positive constant $p_{0} \in (1,p)$, depending only on $n, p$ and $[\omega]_{A_{p}}$, such that
		$$
		 \omega \in A_{p_{0}}
		$$
		with $[\omega]_{A_{p_{0}}} \leq C(n, p, [\omega]_{A_{p}}).$	

		\item[(c)] Assume $\delta \in \left(0,\frac{p-p_{0}}{2}\right]$. Let $f$ be a non-trivial
		locally integrable function on $B_{\rho} \subset \mr^n$, extended $f$ by zero to
		$\mathbb{R}^{n}$. Then the weight $[\mathcal{M}(|f|)]^{-\delta} \omega$ is in the Muckenhoupt class $A_{p}$ with
		\begin{align}
			\notag [ [\mathcal{M}(|f|)]^{-\delta} \omega ]_{A_{p}} \leq c,
		\end{align}
		where the constant $c$ depends on  $n, p$ and $[\omega]_{A_{p}}$. 	Consequently, if $|f|^{p-\delta}\omega \in L^1(B_{\rho})$, then we have
		\begin{align}
			\notag \int_{\mr^n} [\mathcal{M}(|f|)(x)]^{p-\delta}\omega(x)\,dx
			\leq
			c\int_{B_{\rho}} |f(x)|^{p-\delta}\omega(x)\,dx.
		\end{align}
		for some positive constant $c$ depending on $n, p$ and $[\omega]_{A_{p}}$. 
	\end{enumerate}

