[Lemma 10 (Four-dimensional three-form algebra) of arXiv:2608.30638, 'On compact steady pluriclosed soliton surfaces'] Let $(V,g)$ be an oriented real four dimensional vector space endowed with a positive definite metric $g$. If $\theta$ is a one-form and
$H=-*\theta$, then for every vector $X\in V$,
\begin{equation}
 \iota_XH=-*(\theta\wedge X^\flat),
 \qquad
 H^2=2\bigl(|\theta|^2g-\theta\otimes\theta\bigr).
\end{equation}
Thus $H^2\geq0$ and, wherever $H\ne0$,
\begin{equation}
 \ker H^2=\{X:\iota_XH=0\}=\mathbb R\theta^\sharp.
\end{equation}

[Lemma 6.2 of arXiv:2507.06186, '2507.06186'] For every $\ka>0$, there exists some $\th_\ka>0$ such that
for every $m=1,2$ and $t\in(0,\th_\ka)$ the following sequences of random variables are uniformly integrable:
\[\big\{\msf T_{\ka,\eps}(t)^m\mr e^{-mt\msf c_{\ka,\eps}}:\eps>0\big\}
\qquad\text{and}\qquad
\big\{\msf M_{\ka,\eps}(t)^m\mr e^{-mt\msf c_{\ka,\eps}}:\eps>0\big\}.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:LaCroix-marginal-map-series of arXiv:2609.03532, 'Airy limit for the Jack process and topological expansion'] For $\boldsymbol y=(y_1,y_2,\ldots)$, define
\begin{equation*}
  \mathcal M(x,\boldsymbol y,z;b)
  :=
  \sum_{E\geq1}
  \sum_{\nu\vdash2E}
  \sum_{v\geq1}
  d_{v,\nu}(b)x^v y_\nu z^E.
\end{equation*}

[Proposition prop:strongconcave1D-shift of arXiv:2601.13426, 'A uniformity principle for spatial matching'] Under the conditions of~(prop:domination2drivers-shift of the paper),
\begin{align*}
    \delta_m(r_1+\tau,\mathsf{R}) + \delta_m(r_2-\tau,\mathsf{R}) - \delta_m(r_1,\mathsf{R}) - \delta_m(r_2,\mathsf{R})
    \geq {8\,} \alpha_{\xi, \gamma, \eta} \, \tau^3 - {14 \eta \, \gamma }/{n} \, , 
\end{align*}
where $\alpha_{\xi, \gamma, \eta} $ is defined in~(equation eq:def-CMB-NMB-alphaMB of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2606.30938, 'Poissonian potential measures for refracted-reflected L\'evy processes'] Let $q \geq 0$. Then, for $\lambda, \gamma > 0$, $x,b \in [0,a]$ and $u \in [0,\infty)$,
			\begin{align}
				&\mathbb{E}_x \Bigl(\int_0^{\infty} e^{-q t} 1_{\left\{U_t \in \dd u, t < T_{b,U}^{-,\gamma} \wedge T_{a,U}^{+,\lambda} \right\}} \mathrm{d} t\Bigr) \big/ \dd u \notag \\
				&= \frac{\lambda \int^\infty_0 \ee^{-\varphi_{q+\lambda}y}\overline{w}_b^{(q+\gamma,-\gamma)}(y+a;u) \dd y \1_{\{u \in [0,a]\}} + \ee^{-\varphi_{q+\lambda}(u-a)}\1_{\{u \in (a,\infty)\}}}{\lambda \int^\infty_0 \ee^{-\varphi_{q+\lambda}y}\overline{z}_b^{(q+\gamma,-\gamma)}(y+a) \dd y} \overline{z}_b^{(q+\gamma,-\gamma)}(x) -  \overline{w}_b^{(q+\gamma,-\gamma)}(x;u), 



