[Theorem th:BE of arXiv:2508.21055, 'Modern aspects of Markov chains:\\entropy, curvature and the cutoff phenomenon'] For any $\rho\in\mathbb {R}$, the following are equivalent:
\begin{enumerate}[(i)]
\item \red[Bakry-\'Emery $\mathrm{CD}(\rho,\infty)$ criterion]:
\begin{eqnarray}

\forall f\in\mathcal {F},\qquad \Gamma_2 f & \ge & \rho\,\Gamma f.
\end{eqnarray}
\item \red[Exponential sub-commutation]: 
\begin{eqnarray}

\forall f\in\mathcal {F},\quad\forall t\ge 0,\quad \Gamma P_t f & \le & e^{-2\rho t}P_t\Gamma f.
\end{eqnarray} 
\item \red[Local Poincaré inequality]: from any non-random initial condition $X_0$, we have
\begin{eqnarray}

\forall f\in\mathcal {F},\quad\forall t\ge 0,\quad
\mathrm{Var}(f(X_t)) & \le & \left(\int_0^t 2e^{-2\rho u}\,\mathrm{d} u\right){\mathbb{E}}[\Gamma f(X_t)].
\end{eqnarray}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2607.11076, 'Smoluchowski-Kramers Approximation for Stochastic Differential Equations driven by Fractio'] \cite[Theorem1.10.3]{mishura2008stochastic}
		Let \( H \in (\frac{1}{2}, 1) \), \( f \in L_{\frac{1}{H}}[0,T] \), and define
		\[
		I_t(f) = \int_0^t f(s) dB^H(s).
		\]
		Then for any \( p > 0 \), there exists a constant \( C_p(H) > 0 \) such that
		\begin{equation}
			\left\| \sup_{0 \leq t \leq T} |I_t(f)| \right\|_p \leq C_p(H) \|f\|_{L_{\frac{1}{H}}[0,T]},

		\end{equation}
		where \( \| \cdot \|_p \) denotes the \( L^p \)-norm with respect to the probability measure. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main of arXiv:2608.30831, 'Sharp discrete Hardy constants in dimensions three and four\\ and strict upper bounds from'] For every $N\ge3$ one has
\begin{equation}
 C(N)\le A_N.
\end{equation}
More precisely,
\begin{equation}
 C(3)=A_3=\frac14,\qquad C(4)=A_4=1,
\end{equation}
while
\begin{equation}
 C(N)<A_N\qquad(N=9,10).
\end{equation}
If
\[
 \Lambda_2(N):=3N-\sqrt{N^2+8N-8},
\]
then
\begin{equation}
 C(N)\le \Lambda_2(N)<\min\{A_N,2N\}
 \qquad(N\ge11).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm eq:hockey of arXiv:2411.02541, 'The hockey-stick conjecture for\\ activated random walk'] \thlabel{thm:hockey}
For any $\lambda,\rho,\epsilon >0$,
\begin{align}
  \mathbf{P}\Bigl(\abs[\big]{D_\rho(n,\lambda) - \min(\rho,\rho_{\mathtt{FE}}(\lambda))}>\epsilon\Bigr)\leq Ce^{-cn}
\end{align}
for constants $c,C>0$ depending only on $\lambda$ and $\epsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2607.27786, 'Gaussian free field in annulus: \\BPZ equations and crossing probabilities for level lines'] Fix an even number $n=2N$ and $\bs{\theta}=(\theta_1, \ldots, \theta_{n})\in\LX_{n}$. We write $x_j=\ee^{\ii\theta_j}$ for $1\le j\le n$.  
Let $\varphi_n$ be the bounded harmonic function in $\U$ with alternating boundary data:
\begin{equation} 
\pi\text{ on }\cup_{j=1}^N (x_{2j-1}x_{2j}), \qquad 0\text{ on }\cup_{j=1}^N (x_{2j}x_{2j+1}). 
\end{equation}
Then
\begin{equation} 
\| \varphi_n\|_{\nabla(\U),\mathrm{reg}}^2= -2\pi \sum_{1\le i<j\le n} (-1)^{j-i} \log |x_i-x_j|. 
\end{equation}
Moreover, its regularized Dirichlet energy is related to the partition function $\LZ_n$ in~\eqref{eqn::LZunitdisc_def}:
\begin{align*}
\LZ_n(\bs{\theta})=\exp\left(-\frac{1}{4\pi}\| \varphi_n\|_{\nabla(\Omega),\mathrm{reg}}^2\right)=\prod_{1\le i<j\le n}\left|\ee^{\ii\theta_i}-\ee^{\ii\theta_j}\right|^{\frac{1}{2}(-1)^{j-i}}. 
\end{align*}

