[Lemma EHI:l:m2lambdaComparable of arXiv:2511.08956, '\textbf{Towards a characterization of elliptic Harnack inequality for jump processes}'] Let $X$ be an isotropic unimodal L\'{e}vy jump process. For all $r_0>0$, we have
    \begin{equation*}
        \frac12 m_2(r_0) \leq m_2\left\langle r_0 \right\rangle \leq m_2(r_0) \qquad\mbox{and}\qquad \lambda\left\langle r_0 \right\rangle \geq \lambda(r_0).
    \end{equation*}
    If $X$ satisfies (equation EHI:e:regularJumps of the paper) for all $r>0$, then we also have
    \begin{equation*}
        \lambda\left\langle r_0 \right\rangle \lesssim \lambda(r_0),
    \end{equation*}
    where the constant implicit in $\lesssim$ depends only on $c_j$ (from (equation EHI:e:regularJumps of the paper)) and $d$.

[Definition def:underline of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Suppose that $f$ and $g$ are matrix-valued functions. Define
\begin{equation}
\underline{g(H)Hf(H)} := g(H)Hf(H)-\widetilde{\mathbb{E}}g(H)\widetilde{H}(\partial_{\widetilde{H}}f)(H) - \widetilde{\mathbb{E}}(\partial_{\widetilde{H}}g)(H)\widetilde{H}f(H),
\end{equation}
where $\widetilde{H}$ is an indepdent copy of $H$, $\widetilde{\mathbb{E}}$ denotes the partial expectation with respect to $\widetilde H$, and $(\partial_{\widetilde{H}}f)(H)$ denotes the directional derivative of the function $f$ in the direction $\widetilde H$ at the point $H$, i.e.,
\begin{equation}
[(\partial_{\widetilde{H}}f)(H)]_{xy} = (\widetilde{H}\cdot \nabla f(H))_{xy} := \sum_{\alpha,\beta\in \mathcal{I}}\widetilde{H}_{\alpha\beta}\frac{\partial f(H)_{xy}}{\partial H_{\alpha\beta}}.
\end{equation}

[Theorem thm:unknown-class-prior:ber-hoeffding of arXiv:2609.02304, 'Bayes-Optimal BER and AUC: \\Estimation and Evaluation of Estimators'] For any $\epsilon > 0$,
  it holds that
  \begin{equation}
    \P{
      \abs{
        \widehat{\mathrm{BER}^*}(\thetahat)
        -
        \mathrm{BER}^*
      }
      > \epsilon
    }
    \leq
    4 \exp \paren{
      - \frac{
        n \theta^{2} (1 - \theta)^{2} \epsilon^{2}
      }{8}
    }
    \text{.}
  \end{equation}
  Or equivalently,
  for any $\delta \in (0, 1)$,
  with probability at least $1 - \delta$,
  \begin{equation}
    \abs{
      \widehat{\mathrm{BER}^*}(\thetahat)
      -
      \mathrm{BER}^*
    }
    \leq
    \frac{1}{\theta (1 - \theta)}
    \sqrt{
      \frac{8 \log (4 / \delta)}{n}
    }
    \text{.}
  \end{equation}

