[Proposition 22 of arXiv:2606.19115, 'Finite free perpetuities'] Fix \(a\geq 1\) and \(b\ge 1\). Then by Proposition \ref{prop:pff_shift_factorization}, $q_n=p_{n,(a,b)}$ satisfies \eqref{eq:fixedq} and by Proposition \ref{pro:conv_pn},
\begin{itemize}
    \item[(i)] $\meas{p_{n,(a,a+b)}}\weak  f\mathcal{B}'_{a,a+b}=:\mu_{\A}$,
    \item[(ii)] $\meas{q_n}\weak f\mathcal{B}'_{a,b}=:\mu_{\X}$.
\end{itemize}
Moreover, by Corollary \ref{cor:iterated_approximation} applied to  \eqref{eq:fixedq}, we obtain 
\begin{align}
\mu_\X = \mu_{\A}\boxtimes (\delta_1\boxplus \mu_{\X}).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2609.02610, 'The frame set of the first Hermite function'] Let $N \in \N$, $N \geq 2$, $\delta \in (0,1)$, and $\beta >0$. Define
\begin{equation}
  \sigma=\frac{N-1}{2}\,\delta.
\end{equation}
Then, for every $z\in\C$,
\begin{equation}
  \cW_N(z+\ii\beta)
  =\e^{\pi N\beta-2\pi\ii N(z-\sigma)}\cW_N(z)
  = \rho_{\beta}(z-\sigma)^N \cW_N(z),
\end{equation}
and
\begin{equation}
  \sup_{\substack{x\in\R\\0\leq y\leq\beta}}|\cW_N(x+\ii y)|<\infty.
\end{equation}

