[Lemma 8 (Symmetry of $A_s$) of arXiv:2606.00586, 'Stein's Method for Convergence Rates of Invariant Measures in the Nonlocal-to-Local Limit'] Let $s \in [7/4, 2]$ and $0<\eps\ll1$. The operator $A_s$ given by \eqref{eq:def_As} satisfies 
\begin{equation*}
    \langle A_s f, g \rangle = \langle f, A_s g \rangle, \quad f \in \mathcal{X}_{s,\eps} ~\text{ and }~ g \in C_c^\infty(\mR^d). 
\end{equation*}

[Corollary 23 of arXiv:2604.09365, 'Cotlar martingale transforms and related singular integrals'] \begin{equation}
|\{x\in \R: |H1_A(x)|> \lambda\}|=
\lim_{a\to\infty}
\pi a\, \frac{2}{\pi}
\arctan\!\left(\frac{\sin(\pi \beta_{a})}{\sinh(\pi  \lambda)}\right)
=
\frac{2|A|}{\sinh(\pi  \lambda)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be an $N\times N$ Wigner matrix satisfying Assumption~\ref{ass:momass}. Fix a (small) $\varepsilon>0$ and a (large) $C>0$. It holds that
\begin{equation}
\E^{(W)} \left[\Delta(\bm{k})\overline{\Delta(\bm{l})}\right]\lesssim 1.
\end{equation}
uniformly in $z\in \C$ with $|\Im z|\ge \varepsilon$ and $|z|\le C$, for any fixed $n_1,n_2\in\N\cup\{0\}$ and multi-indices $\bm{k}\in\N^{n_1}$, $\bm{l}\in\N^{n_2}$.

