body:
[Theorem 10 of arXiv:2508.04938, 'Perfect t-embeddings of doubly periodic Aztec diamonds'] Let~$\G$ be a finite planar bipartite graph with outer boundary of degree four. 
Let~$w_0, b_0, w_1, b_1$ be the boundary vertices of~$\G$ listed counterclockwise. Define
\begin{align} 
a_{\scriptscriptstyle \G}=\sqrt{-\frac{K_{\G}^{-1}(w_0, b_0)\cdot K_{\G}^{-1}(w_{1}, b_{1})}
{K_{\G}^{-1}(w_0, b_{1})\cdot K_{\G}^{-1}(w_{1}, b_0)}}, 
\end{align}
where $K_{\G}$ is a Kasteleyn matrix of $\G$. 

By applying a gauge transformation, we can assume that 
\[
 K_{\G}^{-1}(w_0, b_0)
= K_{\G}^{-1}(w_{1}, b_{1})=a_{\scriptscriptstyle \G}
\quad \text{ and } \quad
  K_{\G}^{-1}(w_0, b_{1})
 = - K_{\G}^{-1}(w_{1}, b_0)=1.
\] 
Then the Coulomb gauge functions 
\begin{align}
           \mathcal{F}^\bullet(b) =-\sqrt{-a_{\scriptscriptstyle \G}-\i} \,  K_{\G}^{-1}(w_0, b) - 
    \sqrt{a_{\scriptscriptstyle \G}+\i} \,   K_{\G}^{-1}(w_{1}, b),
        \end{align}
    and 
    \begin{align}
     \mathcal{F}^\circ(w) = -\sqrt{-a_{\scriptscriptstyle \G}+\i} \,  K_{\G}^{-1}(w, b_{0}) + 
    \sqrt{a_{\scriptscriptstyle \G}-\i} \,  K_{\G}^{-1}(w, b_{1}).
    \end{align}
 define a perfect t-embedding~$\mathcal{T}$ of the augmented dual~$\G^*$, such that the boundary polygon of~$\mathcal{T}(\G^*)$ is a rhombus with boundary points at~$\{0,\, (a+\i)\sqrt{a^2+1},\, 2a\sqrt{a^2+1}, \, (a-\i)\sqrt{a^2+1} \}$. And the corresponding boundary points of the origami map $\cO(\G^*)$ are points~$\{0,\, -(a^2+1),\,0, \,-(a^2+1)\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 6 (Exact ordered tuple formula) of arXiv:2608.04799, '2608.04799'] If \(K\le n\) and
\(k_i+r_i-1\le\binom{k_i}{2}\) for every \(i\), then
\begin{equation}
  L_n(\mathbf k,\mathbf r)=\frac{(n)_K}{\prod_{i=1}^q k_i!}\prod_{i=1}^q c(k_i,k_i+r_i-1)\,p_n^{K+R-q}(1-p_n)^{A},
\end{equation}
where
\begin{equation}
\begin{aligned}
  A
  &=K(n-K)
    +\sum_{1\le i<j\le q}k_ik_j
    +\sum_{i=1}^q
      \left\{\binom{k_i}{2}-(k_i+r_i-1)\right\}
  \\
  &=Kn-\frac{K^2}{2}-\frac{3K}{2}-R+q.
\end{aligned}
\end{equation}
If the feasibility conditions fail, then \(L_n(\mathbf k,\mathbf r)=0\).

[Lem eq:conf_theta_2 of arXiv:2609.01458, 'Confluence relations for $q$-analogues of multiple zeta values'] We have
\begin{equation}
\pi(\left.\Theta(\boldsymbol{k})\right|_{z=1})=0\qquad(\boldsymbol{k}\in\operatorname{Ind}_{\mathrm{BZ}}\setminus\{\emptyset\})
\end{equation}
and
\begin{equation}
\pi(\left.T(\Theta(\boldsymbol{k}))\right|_{z=1})=b_{\rho(\boldsymbol{k})}\qquad(\boldsymbol{k}\in\operatorname{Ind}_{\mathrm{BZ}}),
\end{equation}
where $\rho\colon\operatorname{Ind}_{\mathrm{BZ}}\to\operatorname{Ind}_{\mathrm{SZ}}$
is the map defined by 
\[
\rho((k_{1},\dots,k_{d}))=(k_{1}-1,\dots,k_{d}-1).
\]

