[Lem 18 of arXiv:2608.20552, 'One-point fluctuations for exponential last passage percolation under upper-tail condition'] For $(x,y)\neq(1,1)$ in $U_1$ or $U_2^<$, or on either the $U_1/U_2^<$ boundary or the $U_2^</U_3^<$ boundary, the following phase gaps are strictly positive whenever they are defined:
\begin{itemize}
\item $\tDel:=\Thetao(\tzo^+)-\Thetao(\tzo^-)>0$. 
\item $\tDelt:=\Thetat(\tzt^+)-\Thetat(\tzt^-)>0$ if $\tzt^-<\tzt^+$. 
\item $\tDelr:= \Thetar(\tzrb)-\Thetar(\tzra)>0$ if $\tzra, \tzrb\in (-1,0)$. 
\end{itemize}

[Definition d:pw of arXiv:2605.03718, 'Potential Hessian Ascent III:\\ Sampling the Sherrington--Kirkpatrick Model at $\beta < 1/'] {anari2024trickle}}]

    Let $\mu$ be a distribution on $\mathcal P([n])$. Define the polar homogenization kernel $\Pi$ from $\mathcal P([n])$ to $\binom{[n]\sqcup [n]}{n}$, by taking $S_1$ to $S_1\sqcup S_2$ where $S_2\in \binom{[n]}{n-|S_1|}$ is chosen uniformly at random. Note that its adjoint $\Pi^*$ takes $S_1\sqcup S_2$ (where $S_1,S_2$ are subsets of the disjoint copies of $[n]$) to $S_1$.

    Define the \emph{polarized walk} for $\mu$ as the Markov chain defined as the composition of the down and up operators $P_\nu^{\mathrm{pol}} = D^{\mathrm{pol}} U_\nu ^{\mathrm{pol}}$, defined below. These correspond to the down and up operators on the polar homogenized distribution.
    \begin{enumerate}
        \item The down operator $D^{\mathrm{pol}}$ is defined as $D^{\mathrm{pol}} = \Pi D_{n\to n-1} \Pi^*$. Explicitly, 
        \begin{align}
            D^{\mathrm{pol}}(S,T) =\begin{cases}
                \frac{1}{n} , & \text{if $T=S\setminus \{i\}$ for some $i\in S$,}\\
                \fc{n-|S|}{n}, & \text{if $T=S$,}\\
                0,&\text{otherwise.}
            \end{cases}
        \end{align}
        \item The up operator $U_\mu ^{\mathrm{pol}}$ is defined as $U^{\mathrm{pol}} = \Pi U_{n-1\to n,\mu}\Pi^*$. Explicitly,
        \begin{align}
            U_\nu^{\mathrm{pol}}(T,S) = \begin{cases}
                \frac{1}{n}\cdot \fc{\mu(S)}{\mu D^{\mathrm{pol}}(T)}, & \text{if $S=T\cup \{i\}$ for some $i\in [n]\setminus T$}\\
                \fc{n-|T|}{n} \cdot \fc{\mu(S)}{\mu D^{\mathrm{pol}}(T)}, & \text{if $S=T$,}\\
                0, &\text{otherwise.}
            \end{cases}
        \end{align}
    \end{enumerate}
    For a distribution $\mu$ on $\{\pm 1\}^n$, define the polarized walk centered at $x_0$ by the above with the bijection $\{\pm 1\}^n\to \mathcal P([n])$ defined by 
    $x\mapsto x_+:= \set{i}{x_i \ne (x_0)_i}$. 


























    Let $\rho_{\text{EC}}(\mu)$ denote the maximum $\rho$ for which $D^{\mathrm{pol}}$ satisfies $(1-\rho)$-entropy contraction with respect to $\mu$.\footnote{Note that the dependence on $x_0$ is implicit in the notation. When $\mu$ is supported on the wedge $B_r(x_0)$, we take $x_0$ as the center for the polarized walk.}

[Lem 19 of arXiv:2609.03777, '2609.03777'] Let $\nu\in\ZZ_{>0}\cup\{\infty\}$ and $r\geq0$. For $\tau\in C$ and lattice points $\mu_1,\mu_2\in\Lambda_\tau$ with $\mu_1\succ_\nu\mu_2$, we have
\begin{align}
\left|G^{(\nu;\mu_1,\mu_2)}_{\{2\}^r}(\tau)\right|&\ll_{C,r}\LL(|\mu_1|+|\mu_2|)^r\,.
\end{align}

