body:
[Lemma 5 of arXiv:2607.01629, 'Quadratic fluctuations of speed-change Kawasaki dynamics'] \begin{enumerate}
			\item \cite[Proposition 4.3 (1)]{gu2025relaxation}:
			The local corrector $\phi_L^z$ is a local function and  $\F_{(\Lambda_L^z)^-}$-measurable.
			\item \cite[Lemma 4.4]{FGW24}: 
			There exists a finite positive constant $C(d,\lambda)$ such that the $L^\infty$ and $L^{2}$ norms for the corrector $\phi_L^z$ satisfy the following estimate:
			\begin{align*}
				&\norm{\phi_{L,e_i}^z}_{L^\infty}\leq CL^{d+2}\log L,\qquad 1\leq i\leq d,\ z\in \Z_L,\\
				&\norm{\phi_{L,e_i}^z}_{L^2}^2\leq CL^{d+2},\ \ \ \ \ \ \ \qquad 1\leq i\leq d,\ z\in \Z_L.
			\end{align*}
			\item \cite[Proposition 4.3 (3)]{gu2025relaxation}:
			There exists a finite positive constant $C(\lambda,\rho)$ such that the corrector satisfies:
			\begin{equation*}
				\sum_{b\in{(\Lambda_L^z)^*}}\E_{\rho}\left[c_b(\eta)\left(\pi_b\phi_{L,e_i}^z\right)^2\right]\leq CL^d,\quad 1\leq i\leq d,\ z\in \mathcal Z_L.
			\end{equation*}
			\item\cite[Proposition 4.3 (4)]{gu2025relaxation}
			There exists an exponent $\alpha(\lambda,\r) > 0$ and a positive constant $C(\lambda,\r) < \infty$, such that for every $G : \X \to \R$ and $1\leq i\leq d$, we have 
			\begin{align*}
				\Ll\vert L^{-d}\sum_{b \in \bar{\left(\Lambda_L^z\right)^*} }\E_\rho\left[(\pi_b G) \mathbf g_{L,e_i, b}^z\right] \Rr\vert \leq C L^{-\alpha}\left(L^{-d}\sum_{b \in \bar{\left(\Lambda_L^z\right)^*} }\E_\rho\left[(\pi_b G)^2\right]\right)^\frac{1}{2}.
			\end{align*}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

