[Prop LyapTorus of arXiv:2412.03560, 'Non-asymptotic entropic bounds for non-linear kinetic Langevin sampler with second-order s'] Assume that $\mathbb X=\mathbb T^d$ and 
    \begin{equation}

    \|D F\|_\infty = \sup_{\mu\in\mathcal P_2(\mathbb T^d)} \sup_{x\in\mathbb T^d} |DF(\mu,x)| < \infty\,, \end{equation}
        and write
    \begin{equation}

    \mathbf V(\mathbf{z})  = \sum_{i=1}^N |v_i|^6\,.
    \end{equation}
    Then, for all $\mathbf{z}\in\mathbb X^N\times\mathbb R^{dN}$,
    \begin{equation}

         \mathcal P \mathbf V(\mathbf{z}) \leqslant   (1-\gamma h)  \mathbf V(\mathbf{z}) + Nh \left[ 766   \gamma  d^3    + \frac{\|D F\|_\infty^6  }{\gamma^5}\right] \,.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition defin:energysolution of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] We say that a process $(\mathcal{Z}_t)_{t\in [0,T]}$ with continuous~$\mathscr{S}'(\mathbb{R} )$-valued trajectories is an \emph{energy solution} to the SBE (equation eq:SBE of the paper) if the following four conditions are satisfied:
    \begin{enumerate}[label=(\roman*)]
        \item For any $t\in [0,T]$, the random variable $\mathcal{Z}_t$ is distributed as a spatial white noise on $\mathbb{R}$ with variance $\sigma^2$ ;
        \item The process $(\mathcal{Z}_t)_{t\in [0,T]}$ satisfies the energy estimate (equation eq:energyestimate of the paper) ;
        \item For any $\varphi\in\mathscr{S}(\mathbb{R} )$, the process defined for any $t\in [0,T]$ by
        \begin{equation*}
            \mathcal{M}_t(\varphi) = \mathcal{Z}_t(\varphi )-\mathcal{Z}_0(\varphi )-\mathfrak{a}\int_0^t \mathcal{Z}_s(\Delta\varphi )\,\mathrm{d} s  + \mathfrak{g}\mathcal{A}_t(\varphi )
        \end{equation*}
        is a continuous mean-zero martingale with respect to the natural filtration of $(\mathcal{Z}_t)_{t\in [0,T]}$, and where $\mathcal{A}_t$ has been defined as the $L^2$-limit (equation eq:Atlimit of the paper). Moreover, its quadratic variation is given by $\langle\mathcal{M}(\varphi )\rangle_t = 2\mathfrak{a}\sigma^2t\|\nabla\varphi\|_{L^2}^2$ ;
        \item The reversed process $(\widehat{\mathcal{Z}}_t=\mathcal{Z}_{T-t})_{t\in [0,T]}$ also satisfies (energysol_item3 of the paper) with the process $(\mathcal{A}_t)_{t\in [0,T]}$ replaced by the process $(\widehat{\mathcal{A}}_t = \mathcal{A}_{T-t}-\mathcal{A}_T)_{t\in [0,T]}$.
    \end{enumerate}

