[Lemma lemma_paths of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$ and $\delta\in (0,1)$, there exist $0<c<c'<c''<1$ depending on $d$ and $\delta$ such that the following holds. Arbitrarily fix $N_{-1}>N_{1}\ge 1$, $x_1\in \partial B(N_{1})$, $x_{-1}\in \partial B(N_{-1})$ and $D\subset \widetilde{B}(cN_{1})\cup [\widetilde{B}(c^{-1}N_{-1})]^c$. For each $j\in \{1,-1\}$, we arbitrarily take $y_{j}\in \partial B((c'')^{j}N_{j})$ and $y_{j}'\in \partial B((10c'')^{j}N_{j})$ and consider the following two random paths:
\begin{equation}
	\widetilde{\eta}_{1,j}\sim \widetilde{\mathbb{P}}_{x_{j}}\big(\{\widetilde{S}_t\}_{0\le t\le \tau_{\partial B(N_{-j})}}\in \cdot \mid \tau_{\partial B(N_{-j})}=\tau_{x_{-j}}<\tau_{D}\big),
\end{equation} 
\begin{equation}
	\widetilde{\eta}_{2,j} \sim \widetilde{\mathbb{P}}_{y_{j}}\big(\{\widetilde{S}_t\}_{0\le t\le \tau_{\partial B((10c'')^{j}N_{j})}}\in \cdot \mid \tau_{\partial B((10c'')^{j}N_{j})}=\tau_{y_{j}'}<\tau_{D}\big).
\end{equation}
For each $i\in \{1,2\}$ and $j\in \{1,-1\}$, let $\mathbf{z}_{i,j}^{\mathrm{F}}$ be the position where $\widetilde{\eta}_{i,j}$ first hits $B((c')^{j}N_{j})$ and let $\mathbf{z}_{i,j}^{\mathrm{B}}$ be the last position where $\widetilde{\eta}_{i,j}$ stays in $B((c')^{j}N_j)$ (when $\widetilde{\eta}_{i,j}$ does not reach $B((c')^{j}N_j)$, we set $\mathbf{z}_{i,j}^{\mathrm{F}}=\mathbf{z}_{i,j}^{\mathrm{B}}=\emptyset$). Then for any $v,w\in \partial B((c')^{j}N_j)$, 		
		\begin{equation}
			\mathbb{P}_{\widetilde{\eta}_{1,j}}(\mathbf{z}_{1,j}^{\mathrm{F}}=v, \mathbf{z}_{1,j}^{\mathrm{B}}=w) \le \delta \mathbb{P}_{\widetilde{\eta}_{2,j}}(\mathbf{z}_{2,j}^{\mathrm{F}}=v, \mathbf{z}_{2,j}^{\mathrm{B}}=w).
					\end{equation}

