[Lem HT comp of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] For each $a > 0$ and $t > 0$, set 
  \begin{equation}
    F(a,t)
    \coloneqq 
    \left\{ s \in \supp \mathcal{C}_t \,\middle |\,
    \varlimsup_{\delta \downarrow 0}
    \frac{\mathcal{C}_t([s-\delta,s+\delta])}{\Psi_{\mathrm{ct}}(\delta)}
    < a\right\}.
  \end{equation}
  Then, for all sufficiently small $a > 0$, $\mathcal{H}_{\Psi_{\mathrm{ct}}}(F(a,t)) = 0$ for all $t > 0$,
  $\hat{P}_{\bm{\rho}}$-a.s.

[Thm eq:diff-SL0 of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let  ${\kappa}_1,\ldots, k_{d_2-1} > -1$ and ${\kappa}_{d_2} = -1$. For $(\bm x,\bm y) \in {\mathbb S}^{d_1-1} \!\rtimes {\mathbb R}_\Sigma^{d_2}$, 
let ${\mathfrak D}_{{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \Sigma}$ be the differential operator defined by 
\begin{align}
  {\mathfrak D}_{{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \Sigma}:= &  \sum_{i=1}^{d_2} \left( y_i \partial_{y_i}^2 + (\kappa_i +1) \partial_{y_i} \right) 
      - 2 {\langle} \bm y, \nabla_{\bm y} {\rangle} \partial_{y_{d_2}}  + 2 |{\bm y}|  \partial_{y_{d_2}}^2   \\
       & +(d_1-2) \partial_{y_{d_2}} - (|{\boldsymbol{\kappa}}| - d_1+d_2+1) \partial_{y_d} + \frac{1}{|\bm y|} \Delta_0^{(\bm x)}, \notag
\end{align}
where $\Delta_0^{(\bm x)}$ is the Laplace-Beltrami operator on the unit sphere in $\bm x$ variable. 
Then 
\begin{align}
  {\mathfrak D}_{{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \Sigma} u = - n u, \qquad
       \forall u \in {\mathcal V}_n\big({\mathbb S}^{d_1-1} \!\rtimes {\mathbb R}_\Sigma^{d_2}, {\mathsf W}_{{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \Sigma} \big).
\end{align}

[Prop EHI:p:h1 of arXiv:2511.08956, '\textbf{Towards a characterization of elliptic Harnack inequality for jump processes}'] Let $X$ be an isotropic unimodal L\'{e}vy jump process on $\mathbb{R}^d$. If (equation EHI:e:regularJumps of the paper) holds for all $r>0$, then for all $L>1$, there exists a constant $C_{(EHI:p:h1 of the paper)}(L, c_j)$ (depending on $L$ and $c_j$) such that for all $r_0>0$, $r \in (0, Lr_0]$, $x \in B(0, r)$, and $w \in B(0, r)^c$, we have
    \begin{equation*}
        K^{\left\langle r_0 \right\rangle, >0}_{B(0, r)}(x, w) \leq C_{(EHI:p:h1 of the paper)} \left( L, c_j \right) K^{\left\langle r_0 \right\rangle, >0}_{B(0, r)}(-x, w).
    \end{equation*}

[Definition Measurable fields of closable operators of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Let~$H$ be as in~(equation eq:DirInt of the paper). For each~$\zeta\in Z$ further let~$(A_\zeta,D_\zeta)$ be a closable operator on~$H_\zeta$.
A field of closable operators~$\zeta\mapsto (A_\zeta, D_\zeta)$ is called \emph{$\nu$-measurable} (\emph{with underlying space~$S$}) if
\begin{enumerate*}[$(a)$]
\item $\zeta\mapsto A_\zeta u_\zeta\in H_\zeta$ is a $\nu$-measurable vector field for every $\nu$-measurable vector field~$u$ with~$u_\zeta\in D_\zeta$ for every~$\zeta\in Z$;
\item there exists a sequence~$\left(u_n\right)_n$ of $\nu$-measurable vector fields such that~$u_{n,\zeta}\in D_\zeta$ and~$\tseq{(u_{n,\zeta},A_\zeta u_{n,\zeta})}_n$ is a total sequence in~$\Graph(\overline{A_\zeta})$ for all~$\zeta\in Z$.
\end{enumerate*}
For a $\nu$-measurable vector field of closable operators~$\zeta\mapsto (A_\zeta, D_\zeta)$, its direct-integral operator~$(A,D)$ is the operator on~$H$ defined as
\begin{gather*}
D\eqdef \set{u\in H : \begin{gathered} u_\zeta\in D_\zeta {\textrm{\,for ${\nu}$-a.e.~}} \zeta\in Z\,\mathrm{,}\;\, \\ \zeta\mapsto A_\zeta u_\zeta \text{~is square-integrable}\end{gathered}}\,\mathrm{,}\;\,
\\
A u \eqdef (\zeta\mapsto A_\zeta u_\zeta)\,\mathrm{,}\;\, \qquad u\in D\,\mathrm{.}
\end{gather*}

[Prop 66 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] For every $w\in\C$, $x>0$ and $y\in\R$ such that $\vert y\vert <x$,
the following holds:
\begin{equation}

\sum_{n=1}^{+\infty}
\dfrac{1}{n!}
\Big(\sum_{k=1}^{n}\dfrac{n! (n-1)!}{(n-k)! k! (k-1)! }
\,\vert y\vert^{n-k}\,\vert w\vert^{k}
\Big)
\dfrac{1}{x^{n}}
<+\infty,
\end{equation}
and
\begin{eqnarray}

\sum_{n=1}^{+\infty} (-1)^{n-1}
\dfrac{1}{n!}
\dfrac{w^{n}}{(x-y)^{n}}
&=&
\sum_{n=1}^{+\infty} (-1)^{n-1}
\dfrac{1}{n!}
\Big(\sum_{k=1}^{n}(-1)^{n-k}\dfrac{n! (n-1)!}{(n-k)! k! (k-1)! }
\,y^{n-k}\,w^{n}
\Big)
\dfrac{1}{x^{n}}
\\ 
\nonumber
&=&
\sum_{n=1}^{+\infty} (-1)^{n-1}
\dfrac{1}{n!}
\Lambda_{n}(w,y)
\dfrac{1}{x^{n}}.
\end{eqnarray}

