[Corollary Strongly local case of arXiv:2411.14936, 'Massive Particle Systems,\\Wasserstein Brownian Motions,\\ and the Dean--Kawasaki Equation'] Fix~$\pi\in\msP(\mbfT_\circ)$.

If Assumption~(ass:SettingLocal of the paper) 
holds, then
\begin{enumerate}[$(i)$, leftmargin=2em]
\item in the setting of Theorem~(t:DirInt of the paper),
\begin{enumerate}[$({i}_1)$]
\item the Dirichlet form~$\big({\widehat\boldsymbol\mssE_\pi,\msD(\widehat\boldsymbol\mssE_\pi)}\big)$ on~$L^2(\widehat\boldsymbol\nu_\pi)$ is additionally strongly local;
 \item the process~$\widehat\boldsymbol\mssW_\pi$ in~(equation eq:i:t:DirInt:6:0 of the paper) is a conservative $\tau_\mrmp$-diffusion on~$\widehat\mbfM_\circ$;
 \item the martingale~$M^{\class{\mbfu}}_\bullet$ in~(equation eq:t:DirInt:1 of the paper) has quadratic variation~$\quadvar{M^{\class{\mbfu}}}_\bullet=\tsharpb{M^{\class{\mbfu}}}_\bullet$ given by the right-hand side of~(equation eq:t:DirInt:2 of the paper) for every~$\mbfu\in\mcC_b(\mbfT)\otimes\Cyl{}{}$;
 \end{enumerate}

\item in the setting of Theorem~(t:TransferQuasiHomeo of the paper),
\begin{enumerate}[$({ii}_1)$]
\item the Dirichlet form~$\big({\widehat\mcE_\pi,\msD(\widehat\mcE_\pi)}\big)$ on~$L^2(\mcQ_\pi)$ is additionally strongly local;
\item the process~$\widehat\mcW_\pi$ in~(equation eq:t:TransferP:0 of the paper) is a conservative~$\tau_\mrma$-diffusion on~$\msP^\pa$;
\item the martingale~$M^{\class{u}}_\bullet$ in~(equation eq:t:Transfer:1 of the paper) has quadratic variation~$\quadvar{M^{\class{u}}}_\bullet=\tsharpb{M^{\class{u}}}_\bullet$ given by the right-hand side of~(equation eq:t:Transfer:2 of the paper) for every~$u\in\hCylP{}{0}$.
\end{enumerate}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:combined-early-late-numerical-time of arXiv:2608.30382, 'Convergence rates for the RMSprop optimizer with full control of the hyperparameters'] Let $\rho,c,q,C_X,L_f,C_{\mathrm{Loj}},C_{\mathrm{dec}}
\in(0,\infty)$. Set
\bas{
\textcolor{magenta}{
  \eta
  =
  [
    2 C_{ \mathrm{Loj} } ( C_X + 1 )
  ]^{ - 1 }
}
  .
}
Then there exist $ C_0, C_1 \in (0,\infty) $ such that the following is true.

Let $ \beta \in [ \nicefrac{ 1 }{ 2 }, 1 ) $,
$ \varepsilon \in [ 0, 1 ] $ satisfy
\bas{
\textcolor{magenta}{
  q+3\ln\beta\ge\rho
}
  .
}
Let $V\subseteq{\mathbb R}^d$ be measurable, let $(X,U)$ be $(c,q)$-regular on
$V$ in the sense of (def:regular of the paper) and assume for every
$\theta\in V$, $i\in\{1,\dots,d\}$ that
\bas{
\textcolor{magenta}{
  \| X^{ (i) }( \theta, U ) \|_{ L^{ \infty } } \le C_X
}
  .
}
Let $ F \colon {\mathbb R}^d \to [0,\infty) $ have a globally $ L_f $-Lipschitz continuous
derivative and assume for every $\theta\in V$ that
\bas{
\textcolor{magenta}{
  f_X(\theta)=-\nabla F(\theta)
}
\qquad
\text{and}
\qquad
\textcolor{magenta}{
  F(\theta)\le C_{\mathrm{Loj}}|f_X(\theta)|^2
}
  .
}
Let $ ( \gamma_n )_{ n \in {\mathbb N} } $ be decreasing and $ (0, C_{ \mathrm{Loj} } (C_X + \varepsilon) ] $-valued and

assume for every $ j, n \in {\mathbb N} $ with $ 1 < j \le n $ that
\bas{
\textcolor{magenta}{
  \gamma_j
  \le
  \gamma_n
  C_{\mathrm{dec}}
  \exp\bigl(
  \textstyle
    \frac{ \eta }{ 2 } \sum_{ k = j + 1 }^n \gamma_k
  \bigr)
}
  .
}
Let $ \theta_0 \in {\mathbb R}^d $ and let $(\theta_n)_{n\in{\mathbb N}_0}$ be the \RMSprop\
algorithm driven by $(X,U)$ with parameter tuple
$(\beta,\varepsilon,(\gamma_n)_{n\in{\mathbb N}},\theta_0)$ defined above.
Define
$
  \tau = \inf\{ n \in {\mathbb N}_0 \colon \theta_n \notin V \}
$.
Then one has for every $ n \in {\mathbb N} $ that
\bas{

\textcolor{magenta}{
  {\mathbb E}\bigl[
    F(\theta_n)
    \1_{ \{ \tau \ge n \} }
  \bigr]
\le
  \exp\bigl(
  \textstyle
    - \eta \sum_{ k = 2 }^n \gamma_k
  \bigr)
  \,
  \bigl[
    F( \theta_0 )^{ 1 / 2 }
    +
    \gamma_1
    ( 2^{ - 1 } L_f d )^{ 1 / 2 }
  \bigr]^2
  + C_0 \gamma_n
  + C_1 ( 1 - \beta)^2
}
  .
} (Proof in the paper; no proof environment follows the statement in the TeX.)

