body:
[Proposition 32 of arXiv:2508.04938, 'Perfect t-embeddings of doubly periodic Aztec diamonds'] For non-boundary dual vertices~$(2\ell x,2y)$ in~$(A_{\ell N}')^*$ and two functions~$f$ and~$g$, set
\begin{equation*}
I_{f,g}(x,y)=
\frac{1}{(2\pi\i)^2}\int_{\Gamma_s}\int_{\Gamma_l}
\frac{\prod_{m=1}^\ell (z_2-\beta_m)^N}{\prod_{m=1}^\ell (z_1-\beta_m)^N}\frac{z_1^{y}}{z_2^{y}}\frac{w_2^x}{w_1^x}\frac{f(z_2)g(z_1)\d z_2\d z_1}{z_2-z_1},
\end{equation*}
where~$\Gamma_s = \{|z| = r_s\}$, and ~$\Gamma_l = \{|z| = r_l\}$ for some~$\beta_i<r_s < 1 < r_l<\alpha_i/\gamma_i$ for all $i$, both positively oriented.

Let~$(2\ell x,2y)$ and~$(2\ell x',2y')$ be non-boundary dual vertices in~$(A_{\ell N}')^*$, and let~$f$ and~$g$ be as in~\eqref{eq:f_g_def_1xell}, and~$\bar g(z)=\overline{g(\bar z)}$. Then 
\begin{equation*}
\cT(2\ell x,2y)-\cT(2\ell x',2y')=I_{f,g}(x,y)-I_{f,g}(x',y')
\end{equation*}
and
\begin{equation*}
\cO(2\ell x,2y)-\cO(2\ell x',2y')=I_{f,\bar g}(x,y)-I_{f,\bar g}(x',y').
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:good_block_low_delta of arXiv:2607.22908, 'Epidemic Phase Transitions in the Zero-Range Process'] Let $\mathcal{S}(B_0)$ be the seeding event for $B_0$, $\mathcal{E}_{\text{empty}}^c$ be the event that the input interface of $B_0$ is not completely empty, and $\mathcal{E}_{\text{heal}}^c$ be the event that there are no healing marks inside $B_0$. We define the event $E(B_0)$ that a scale-$0$ block $B_0$ is \emph{good} as the intersection of these events:
  \begin{equation}
    E(B_0) = \mathcal{S}(B_0) \cap \mathcal{E}_{\text{empty}}^c \cap \mathcal{E}_{\text{heal}}^c.
  \end{equation}

[Theorem 4 of arXiv:2605.03100, 'Berry-Esseen bounds for multivariate martingale difference sequences in the Kolmogorov dis'] Let $\{\bm{X}_k\}_{k \in [n]}$ denote a martingale difference sequence in $\mathbb{R}^d$ that satisfies Assumption \ref{as:fixed-variation}, and let $\bm{V}_k, \bm{\Sigma}_n$ be defined as in \eqref{eq:defn-Sigma-n}. Suppose that there exist constants $\beta>0,\gamma>0$, such that for all $k \in [n]$,
\begin{align}
\mathbb{E}\|\bm{X}_k\|_{\infty}^3 \leq (\gamma \log_+ d)^{3/2}, \quad \text{and} \quad d_{\max}(\bm{V}_k) \leq \beta \quad \text{almost surely}.
\end{align}
It can then be guaranteed that
\begin{align}
d_{\mathsf{K}}\left(\frac{1}{\sqrt{n}}\sum_{k=1}^n \bm{X}_k,\mathcal{N}(\bm{0},\bm{\Sigma}_n)\right) \lesssim  \left(\frac{\gamma + \beta}{d_{\min}(\bm{\Sigma}_n)}\right)^{\frac{3}{8}} \left(\log_+^{\frac{3}{2}}d\right) n^{-\frac{1}{8}}.
\end{align}
If we further assume that there exists $\alpha>0$ such that 
\begin{align}
\min_{k=1,\ldots,n} \lambda_{\min}(\bm{V}_k) \geq \alpha, \quad \text{almost surely},
\end{align}
then 
\begin{align}
d_{\mathsf{K}}\left(\frac{1}{\sqrt{n}}\sum_{k=1}^n \bm{X}_k,\mathcal{N}(\bm{0},\bm{\Sigma}_n)\right) \lesssim  \frac{(\gamma + \beta)^{3/4}}{\sqrt{\alpha d_{\min}^{1/2}(\bm{\Sigma}_n)}} \left(\log_+^{2}d\right) n^{-\frac{1}{4}}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem incrementalweak of arXiv:2603.22652, 'A cohesive account on the ergodic behaviours and scaling limits of Random Walks in Cooling'] {AvedCos24game}}]

Assume that $\mathfrak{X}$ satisfies:
\begin{description}
	\item[\namedlabel{C}{C}] \emph{(Centering)}
\begin{equation}\notag
\forall\,m \in {\mathbb {R}}_+, \, k \in {\mathbb {N}};\quad {\mathbb {E}}\crt{X^{(k)}_m} = 0.
\end{equation}
\item[\namedlabel{W1}{W1}]  \emph{(Concentration)} 
\begin{equation}\notag
	\lim_{m\to\infty}    \sup_{k} {\mathbb {P}}\prt{\abs{X^{(k)}_m/m}>\epsilon} =0,
	\quad  \forall \varepsilon>0. 
\end{equation}   
\item[\namedlabel{W2}{W2}]  \emph{(Uniform Integrability)} 
 \begin{equation}\notag
	\lim_{A\to \infty} \sup_{k,m} {\mathbb {E}} \crt{\left\vert X_k(m)\right\vert \mathbbm{1}_{\left\vert X_k(m)\right\vert>A}} = 0. 
\end{equation}
\end{description}

Let $X_t = X_t(\mathfrak{X},\tau)$ be given by  (equation cooling-general-tau of the paper). Then,
\begin{equation}\notag
\lim_{t\to\infty}{\mathbb {P}}\left( \left\vert X_t/t\right\vert>\epsilon \right)=0,\quad  \forall \varepsilon>0. 
\end{equation}

[The 31 of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Suppose $H$ is a Tonelli Hamiltonian on $\T^n$, $\phi\in \SCL(\T^n)$, and $u$ is the viscosity solution of \eqref{eq:HJephi pre}. Let $\gamma: [0,T] \to \T^n$ be a $(u,H)$-calibrated curve with dual arc $p(t) = L_v(\gamma(t),\dot{\gamma}(t))$ for $t \in [0,T]$. The following statements are true:

	\begin{enumerate}
		\item 	If $\gamma(t_0)\in\operatorname{Alex}(u(t_0,\cdot))$ for some $t_0\in[0,T)$, then $\gamma(t)\in\operatorname{Alex}(u(t,\cdot))$ for all $t\in[t_0,T)$. Moreover, the map $t\mapsto Q(t)=D^2_xu(t,\gamma(t))$ is of class $C^1$ on $[t_0,T)$ and $Q(t)$ satisfies the following matrix Riccati equation
		\begin{equation}
			\dot{Q}(t)+Q(t)\cdot H_{pp}(\gamma(t),p(t))\cdot Q(t)+Q(t)\cdot H_{px}(\gamma(t),p(t))+H_{xp}(\gamma(t),p(t))\cdot Q(t)+H_{xx}(\gamma(t),p(t))=0. \tag{Ricc}
		\end{equation}		
		\item  If $\gamma(t_0)\in\operatorname{Alex}(u(t_0,\cdot))\cap \operatorname{supp}_{C^{1,1}}(u(t_0,\cdot))$ for some $t_0\in[0,T)$, where $\text{supp}_{C^{1,1}}(u(t_0,\cdot))$ is the $C^{1,1}$ support of $u(t_0,\cdot)$ (see the definition before Theorem \ref{thm:close_cut}), then $\gamma(t)\in\operatorname{Alex}(u(t,\cdot))$ for all $t\in[0,T)$. Moreover, the map $t\mapsto Q(t)=D^2_xu(t,\gamma(t))$ is of class $C^1$ on $[0,T)$ and $Q(t)$ satisfies \eqref{eq:Ricc}.
	\end{enumerate}

