[Lemma 49 of arXiv:2608.30602, '2608.30602'] Assume that $|V(x)|\lesssim \langle x\rangle^{-8-}$ and that zero is either a second-kind threshold singularity or an eigenvalue of $H$. Then there exists a sufficiently small $\lambda_1>0$ such that, for all $\lambda\in (0,\lambda_1)$, the operator $\Lambda^{\pm}(\lambda)$ is invertible on $(I-S_2)L^2\oplus S_2L^2$ and
\begin{equation*}
\Lambda^{\pm}(\lambda)^{-1}=
\begin{pmatrix} 
m_{00}^\pm(\lambda)^{-1}  & 0 \\[2mm] 
0 & m_{11}^\pm(\lambda)^{-1}
\end{pmatrix},
\end{equation*}
	where
	\begin{equation} 
		m_{00}^\pm(\lambda)^{-1} = 
		\begin{cases}
			h_{\pm}(\lambda)^{-1}N + QD_{0}Q +\tilde{\mathcal{O}}_2(\lambda^{3/2}), 
			& \text{if no s-wave is present}, \\[3mm]
			\begin{aligned}[t]
				&-\bigl(h_{\pm}(\lambda)+N\bigr)(S_{1}-S_2)D_{1}(S_{1}-S_2) 
				- (S_{1}-S_2)D_{1}(S_{1}-S_2)N \\
				&\qquad + QD_{0}Q +\tilde{\mathcal{O}}_2(\lambda^{3/2}),
			\end{aligned}
			& \text{if an s-wave is present},
		\end{cases}
	\end{equation}
	and
	\begin{equation}
		m_{11}^\pm(\lambda)^{-1}=
		\begin{cases}
			S_3 D_3 S_3+\tilde{\mathcal{O}}_2(\lambda^{1+}), 
			& \text{if no p-wave is present},\\[3mm]
			S_3 D_3 S_3 + g_1^\pm(\lambda)^{-1}N_1 
			+ \tilde{\mathcal{O}}_2(g_1^\pm(\lambda)^{-2}), 
			& \text{if a p-wave is present}.
		\end{cases}
	\end{equation}
	Here the operators $N$ and $N_1$ are defined in \eqref{eq:def of K} and \eqref{eq:def of K_1}, respectively.

