body:
[Lemma 14 of arXiv:2608.29501, 'Disorder Thresholds and Free Energy of Brownian Directed Polymers with\\ Product and Radia'] In the present Brownian polymer model,
\begin{equation}
  W_\infty>0~\ \text{a.s.}
  \quad\Longleftrightarrow\quad
  (W_t)_{t\ge0}\ \text{is uniformly integrable}.

\end{equation}
In particular, under weak disorder,
\begin{equation}
  W_t\longrightarrow W_\infty
  \quad\text{in }L^1(\Pp),
  \qquad
  \E W_\infty=1.

\end{equation}

[Lemma 31 of arXiv:2604.21669, 'Discontinuous transition in 2D Potts:\\ II. order-order interface convergence'] Let \(0<J<U\) satisfy \(\sinh 2J=e^{-2U}\). Then, there exist \(c>0, n_0\geq 1\) such that for any \(n\geq n_0\),
	\begin{equation*}
		\Phi_n\big( v_R\in \calC,\, v_R'\in \calC' \big)
		\geq
		\frac{c}{n^2} e^{-4\nu_1 n}.
	\end{equation*}

[Lemma 16 of arXiv:2608.30089, 'On the Coefficients of Hurwitz-Type Matrix Polynomials'] For every \(m\ge1\),
\begin{equation}\det\mathcal T_{2m}=\det\mathcal T_{2m+1}=(-1)^{qm}.
\end{equation}

[Lemma 18 (Asymptotic negative support along a relation direction) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] Let $\Lambda\in\mathfrak{L}_{\bm{\beta}}$, $\bm{\gamma}\in\Lambda$, and $\bm{g}\in L\setminus\{\bm{0}\}$.
Then there exist $q_{0}\in\N$ and $J\in\NS(\Lambda)$ such that
\begin{equation}

\nsupp(\bm{\gamma}-q\bm{g})=J\quad (q\geq q_{0}).
\end{equation}
If, in addition, $\bm{w}\cdot\bm{g}>0$, then $J \in \mathcal{U}_{\bm{w}}(\Lambda)$.

