body:
[Lemma lem:h1_tail of arXiv:2609.01697, 'Unique ergodicity of projective cocycles over the 2D stochastic Navier--Stokes equations'] In the setting of Lemma~(lem:shell_approximation of the paper)
  \begin{equation*}
    \int_0^{T_\star} \|\nabla \pi^>_t\|^2 \mathrm{\,d} t \lesssim \varepsilon^2
    \qquad\text{and}\qquad
    \|\pi^>_{T_\star}\|_{H^1} \lesssim \varepsilon .
  \end{equation*}

[Definition def:OCD of arXiv:2601.09976, 'Stochastic Calculus as Operator Factorization:\\ An Operator--Covariant Derivative and Uni'] Let $X$ be a square-integrable process with energy space~$\mathcal{H}_X$ and stochastic integral $\delta_X \colon \mathcal{H}_X \to L^2(\Omega)$. For $F \in L^2(\Omega)$, the \emph{operator--covariant derivative} $D_X F \in \mathcal{H}_X$ is the unique element satisfying
\begin{equation}
\mathbb{E}[F \cdot \delta_X(u)] \;=\; \langle D_X F,\, u \rangle_{\mathcal{H}_X}
\quad \text{for all } u \in \mathcal{H}_X.
\end{equation}
The operator $D_X \colon L^2(\Omega) \to \mathcal{H}_X$ is called the \emph{operator--covariant derivative}.

[Theorem analyticity_general of arXiv:2606.29622, 'Affine Structure of the Brownian Signature'] Let $\bm p \in \mathcal B\,$, and $\bm \xi$ be as in (equation eq:def_xi of the paper). Then, defining $\bm u_t := \mathbb{E}[\bm \xi_t]$ for all $t \in [0\,,T]\,$, we have:
    \begin{enumerate}
        \item $\bm u_t \in \mathcal A_{\infty}$ for all $t \in [0\,,T]\,$, so that
        \begin{align}
         \mathbb{E} \left[\exp\left(\bracket{\bm p}{\sigX[] \otimes \sigW[t,T]}\right) \right] = \bracket{\bm u_t}{\sigX[]}\,, \quad \sigX[] \in G\,, \quad t \in [0, T]\,.
    \end{align}
    In particular,
\begin{align}
\mathbb{E}\left[\exp \left(\bracket{\bm p}{\sigW[T]}\right)\, \Big|\, \mathcal F_t\right] = \bracket{\bm{u}_t}{\sigW[t]}, \quad t \in [0, T].     \end{align}
    \item For all $\sigX[] \in G\,$, $\sup_{t \in [0, T]}\,\|\bm u_t\|_{\sigX[]} \leq \exp\left(C_{\bm p, T} \,(1 + M_{\bm p}(\sigX[]))^{\deg_{{\color{NavyBlue}{\mathbf{1}}}}(\bm p)}\right) < + \infty\,$.
    \item $t \mapsto \bm u_t^{{\color{NavyBlue}{\mathbf{\varnothing}}}}$ is continuous on $[0\,,T]\,$. 
    \end{enumerate}

[Lemma lem:discrete of arXiv:2506.15949, 'On the passage times of self-similar Gaussian processes on curved boundaries'] Suppose that $t_{n+1}-t_n = \mathcal{o}(t_n)$ as $n\to\infty$.
	Then, there exists a constant $K >1$ with the following property:
	Whenever $m(n)$ is an integer in $(1\,,n)$ for every $n\in\mathbb{N}$,
	\[
		\mathrm{P}\{\hat{T}_c > t_n\}
		\leqslant \mathrm{P}\{ T_{c+\varepsilon,\alpha} > t_n/t_{m(n)}\}
		+ K\sum_{j=m(n)}^n \exp\left(- \frac{\varepsilon^2}{K}
		\left|\frac{t_j}{t_{j+1}-t_j}\right|^{2\alpha} \right),
	\]
	for every $c,\varepsilon>0$ and $n\in\mathbb{N}$.

[Defi of arXiv:2411.09629, 'A Kesten Stigum theorem for Galton-Watson processes with infinitely many types in a random'] Let $(F_{x,e})_{x\in\mathbb{X}, e\in\mathcal{E}}$ be a familiy of integer-valued random variables. We say that $(F_{x,e})_{x\in\mathbb{X}, e\in\mathcal{E}}$ belongs to
	\begin{itemize}[-]
		\item \textbf{BS} if and only if for each $(x,e)\in\mathbb{X}\times \mathcal{E}$, there exists a deterministic integer $A_{x,e}$ and a real number $\varepsilon >0$ such that 
		\begin{align*} {\mathbb P}[F_{x,e}\geq A_{x,e}]=0 \text{ and } \mathbb{E}\left[\sup_{x\in\mathbb{X}} \frac{A_{x,\xi_0}\left(\log^+(A_{x,\xi_0})\right)^{1+\varepsilon}}{f_{x,\xi_0}}\right]<\infty,
		\end{align*}
		\item \textbf{ExpTail} if and only if for each $(x,e)\in\mathbb{X}\times \mathcal{E}$, there exists $q(x,e)<1, \alpha(x,e)>0$ and $\beta(e)>0$ such that
		$${\mathbb P}[F_{x,e}\geq k] \overset{\beta(e)}{\asymp}\alpha(x,e) q(x,e)^k$$ and
		\begin{align*}
			\mathbb{E}\left[\frac{\beta(\xi_0)^2}{1-\sup_{x\in\mathbb{X}}q(x,\xi_0)}\right]&<\infty.
		\end{align*}
		\item \textbf{PolyTail} if and only if for each $(x,e)\in\mathbb{X}\times \mathcal{E}$, there exists $\delta(x,e)>1, \alpha(x,e)>0$ and $\beta(e)>0$, it holds
		$${\mathbb P}[F_{x,e}\geq k] \overset{\beta(e)}{\asymp}\alpha(x,e) k^{-\delta(x,e)},$$ where 
		\begin{align*}
			\mathbb{E}\left[\beta(\xi_0)^2 \inf_{x\in \mathbb{X}} \delta(x,\xi_0)\right]<\infty \text{ and } \mathbb{E}\left[\frac{\beta(\xi_0)^2}{(\inf_{x\in \mathbb{X}} \delta(x,\xi_0)-1)^{1+\varepsilon}}\right]&<\infty \text{ for some $\varepsilon>0$.}
		\end{align*}
	\end{itemize}

[Thm 32 of arXiv:2608.26642, '2608.26642'] Suppose that (\ref{RV-rq}) holds. Then for every $x\in \R$ and $s\ge 0$,
 \begin{align}

   \lim_{t\to \infty}\frac{\P_x[F_s\cdot \Gamma_t^\mu]}{\P_x[\Gamma_t^\mu]}=\P_x\left[F_s\cdot\frac{\varphi^\mu(X_s)\Gamma_s^\mu}{\varphi^\mu(x)} \right]\qquad \text{for}\ F_s\in b\F_s.
 \end{align}
Here, $\varphi^\mu$ is the function appearing in Theorem \ref{mainthm1}.

