[Theorem thm:key-area of arXiv:2606.06612, 'The limit shape and emergence of the \\ Discrete Gaussian level lines'] Fix $g\geq 0$, $n \geq 0$, and set $h = H+1-n$. The following hold for every subsets $F\subseteq V \subset\mathbb Z^2$ where $F$ is connected with $g$ holes.
        \begin{enumerate}
            \item[\emph{Mesoscopic range}] If  $|\partial F|\vee |\partial V| \leq O(L^{2/3}\exp(\sqrt{\log L}))$ then 
    \begin{align}{\widehat\pi}^0_V(\phi_x \geq -h,\, \forall x \in F) = (1+o(1))\exp\left(-\upxi_{n}|F|\right)\,.
    \end{align}
    \item[\emph{Macroscopic range}] If $|\partial F| \vee |\partial V| \leq O( L\exp(\sqrt{\log L}))$ then 
    \begin{align}\quad\;{\widehat\pi}^0_V(\phi_x \geq -h,\, \forall x \in F) \geq \exp\left(-\upxi_{n}|F| + O\big(\sqrt{L}e^{\frac{\log L}{\log\log L}}\big)\right)\,,
    \end{align}
    and if $\mathfrak{S}$ is the event that there are no disagreement polymers $\gamma$ in $\phi$ with $|\gamma| \geq \log L$, then        
\begin{align}{\widehat\pi}^0_V(\phi_x \geq -h,\, \forall x \in F \mid \mathfrak{S}) \leq \exp\left(-\upxi_{n}|F| + O\big(\sqrt{L}e^{\frac{\log L}{\log\log L}}\big)\right)\,.
    \end{align}
If $|F| \leq  \big(\frac{3\beta}{{\widehat\pi}_\infty(\phi_o > h)}\big)^2 $, then the last upper bound also applies to ${\widehat\pi}_V^0(\phi_x\geq -h,\,\forall x\in F)$.
\end{enumerate}
The above statements also hold when replacing ${\widehat\pi}_V^0$ by ${\widehat\pi}_\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:hall-heyde-quantitative-clt of arXiv:2512.21026, 'Minimax Duality in Game-Theoretic Probability\thanks{Work in progress: mistakes are likely'] Let $X_t = \sum_{j=1}^t Y_j$, with $\mathcal{F}_t$ the $\sigma$-field generated by $Y_1, Y_2, \dots, Y_t$. Let 
  \(
  V_t = \sum_{j=1}^t \mathbb{E}[Y_j^2 \mid \mathcal{F}_{j-1}], 1 \leq t \leq n,
  \)
  and suppose that for constants $M$, $C$, and $D$ we have

  \begin{equation}

    \max_{t \leq n} |Y_t| \leq n^{-1/2} M \quad \text{a.s.},
  \end{equation}
  and
  \begin{equation}

    \mathbb{P}\left( \left| V_n - 1 \right| > 9M^2 D n^{-1/2} (\log n)^2 \right) \leq C n^{-1/4} / \log n~.
  \end{equation}
  Then for $n \geq 2$,
  \begin{equation}

    \sup_{-\infty < x < \infty} \left| \mathbb{P}(X_n \leq x) - \Phi(x) \right| \leq (2 + C + 7 M D^{1/2}) n^{-1/4} \log n~.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

