body:
[Lemma lem:quantitativeDyadicCompression of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Let $\mathsf{d}/2\le\mathsf{s}<\mathsf{d}$ and $\mu\in L^\infty\cap\mathcal{P}({\mathbb{R}}^\mathsf{d})$.  There exist constants $c_0,C_0,L_0>0$, a dyadic cube $Q_0$, and, for every sufficiently small scale $\delta$ in the dyadic subdivision of $Q_0$, a finite sub-$\sigma$-algebra $\mathcal G_\delta$ of the Borel $\sigma$-algebra such that, with
\begin{align}
h_\delta
\coloneqq
{\mathbb{E}}_{\mu^{\otimes2}}\brak*{\tilde{\mathsf{g}}\mid\mathcal G_\delta\otimes\mathcal G_\delta},
\end{align}
the following properties hold:
\begin{enumerate}[(i)]
\item $h_\delta$ is bounded, symmetric, canonical, positive definite, and finite rank.
\item If $T_\delta$ denotes the integral operator with kernel $h_\delta$, then
\begin{align}
0\le T_\delta\le L_0\,\mathrm{Id}
\end{align}
in the quadratic-form sense.
\item The canonical feature map of $h_\delta$ satisfies
\begin{align}
\sup_x h_\delta(x,x)\le C_0\delta^{-\mathsf{s}}.
\end{align}
\item Its Hilbert--Schmidt norm satisfies
\begin{align}
\|h_\delta\|_{L^2(\mu^{\otimes2})}^2
\ge c_0
\begin{cases}
\log(1/\delta),&2\mathsf{s}=\mathsf{d},\\[0.3em]
\delta^{\mathsf{d}-2\mathsf{s}},&2\mathsf{s}>\mathsf{d}.
\end{cases}
\end{align}
\end{enumerate}

