[Proposition 13 (Upward and downward exit problems under reflection) of arXiv:2605.18136, 'L\'evy processes with partially stochastic resetting'] For $a, b \in \mathbb{R}$, the following limits, in terms of the resolvents ${r}_b^{(q+\lambda)}$ and  ${r}_a^{(q+\lambda)}$ defined in Section \ref{reflection},  hold
		\begin{itemize}
			\item[\upshape{(i)}] for  $x\in[b,a)$, 
			\begin{align*}
			\lim_{p\to 0}	\mathbb 	E_x(\ee ^{-q\tau^+_{a,U^b }})=\frac{{\mathcal{Z}_{b,a}^{(q+\lambda )}}(x)}{	{\mathcal{Z}_{b,a}^{(q+\lambda )}}(a)}+\frac{\int_{b}^{a}r_b^{(q+\lambda)}(x,y)\dd y \mathbf 1_{\{a,b\in \mathbb R_+\}}}{{\mathcal{Z}_{b,a}^{(q+\lambda )}}(a)\bigl(1-\lambda \int_{b}^{a}r_b^{(q+\lambda )}(b,y)\dd y \bigr)}+\lambda \int_{b}^{a}r_b^{(q+\lambda )}(x,y)\mathbf 1_{\{a,b\in \mathbb R_-\}},
			\end{align*} 
							\item[\upshape{(ii)}]  for $ x\in(b,a]$, 
							\begin{align*}
	\lim_{p\to 0}\mathbb E_x(\ee ^{-q\tau^-_{b,U^a}})&=\mathcal{Z}_{b,a}^{(q+\lambda )}(x)-\frac{\mathcal{Z}_{b,a}^{(q+\lambda )\prime}(a)}{\mathcal{W}_{b,a}^{(q+\lambda )\prime}(a)}\mathcal{W}_{b,a}^{(q+\lambda )}(x)+\lambda\int_b^ar_a^{(q+\lambda)}(x,y)\dd y \mathbf 1_{\{a,b\in \mathbb R_+\}}\\
	&\quad +\Bigl(\mathcal{Z}_{b,a}^{(q+\lambda )}(a)-\frac{\mathcal{Z}_{b,a}^{(q+\lambda )\prime}(a)}{\mathcal{W}_{b,a}^{(q+\lambda )\prime}(a)}\mathcal{W}_{b,a}^{(q+\lambda )}(a)\Bigr)\frac{\lambda\int_b^ar_a^{(q+\lambda)}(x,y)\dd y}{1-\lambda\int_b^ar_a^{(q+\lambda)}(a,y)\dd y} \mathbf 1_{\{a,b\in \mathbb R_-\}}
								\end{align*}
		\end{itemize}

[Proposition 12 (Lemma 8.6 of \cite{Gubinelli:06}) of arXiv:2606.09904, 'Non-explosion principles for branched rough differential equations with unbounded coeffici'] For any \(\phi \in C^{N}\), defining \(\phi(\mathbf{Y})\) by
  \[\phi(\mathbf{Y}) = \sum_{f \in \CF_{N - 1}} \partial^f_X \phi(\mathbf{Y}) f\]
  where
  \begin{equation}
    \partial^f_X \phi(\mathbf{Y}) = \sum_{\tau_1 \cdots \tau_{\# f} = f} \frac{1}{(\# f)!}D^{\# f}
    \phi(Y)[(\partial^{\tau_i}_X Y)_{i = 1}^{\# f}]
  \end{equation}
  for any \(f \in \CF_{N - 1}\), we have that \(\phi(\mathbf{Y})\) is
  also a controlled rough path against \(\mathbf{X}\). (Proof in the paper; no proof environment follows the statement in the TeX.)

