[Proposition 38 of arXiv:2604.19738, 'Phase Transitions in the Fluctuations of Functionals of Random Neural Networks \\'] Let $(f_n)_{n\in\mathbb N}$ be a sequence of real-analytic functions on $(-1,1)$. Assume that
\begin{enumerate}
\item $f_n(x)\to f(x)$ pointwise for every $x\in(-1,1)$;
\item The radius of convergence of $f_n$ at $0$ is at least $1$;
\item For every $n$ we have $f_n^{(k)}(0)\ge0$ $\forall\,k\ge k_0$, with $k_0$ independent of $n$.
\end{enumerate}
Then $f$ is real analytic on $(-1,1)$, with $f^{(k)}(0)\ge0$ $\forall k\ge k_0$ and the radius of convergence of $f$ at $0$ is at least $1$.

[Lemma 18 (Baker) of arXiv:2609.02478, 'Improved Weyl bounds on short intervals'] Let $P(X)=\alpha_kX^k+\cdots+\alpha_1X$ and let $M\ge2$.  If
\[
  \|P(n)\|>M^{-1}
  \qquad(1\le n\le N),
\]
then
\begin{equation}
  \sum_{m=1}^{M}|g_k(m\boldsymbol\alpha;N)|\gg N.
\end{equation}

