[Lemma 23 of arXiv:2609.02294, 'Existence and Blow-Up for Non-linear Fokker-Planck with Controlled Drift Divergence'] Let $\bar s=\frac{\|u(0)\|_1}{\|u(0)\|_\infty}$, $A:=\dfrac{k\,a_p(T)}{a_d\,k_c}$, and define
\begin{equation}
\bar\lambda_T:=
\begin{cases}
A\,\bar s^{\,k_c}\exp\ \Big(-k_c\,(2A)^{1/k_c}\,\|u_0\|_1\Big),
& k=k_c,\\[2ex]
\min\left\{
A\left(\dfrac{k}{2(k_c-k)\,(2A)^{1/k}\,\|u_0\|_1}\right)^{\frac{k\,k_c}{k_c-k}},\;
A\left(2^{-\frac{k}{k_c-k}}\,\bar s\right)^{k_c}
\right\},
& 0<k<k_c,
\end{cases}
\end{equation}
 It holds 
  \begin{equation*}
    \Phi_{\bar\lambda_T}\left(\bar s\right)\ge \|u(0)\|_1.
  \end{equation*}

