body:
[Thm 18 of arXiv:2512.02538, 'On the spectral geometry of Liouville quantum gravity'] Let $0< \gamma <2$.
We have
\begin{align}
\frac{\mathbf{N}_{\gamma}(\lambda)}{\lambda} \xrightarrow[\lambda \to \infty]{p} c_\gamma \mu_{\ph}(\Sigma),
\end{align}
where $ \xrightarrow{p}$ denotes convergence in probability, and the constant $c_\gamma$ satisfies
\begin{equation}
c_\gamma = \frac1{\pi(2- \gamma^2/2)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo 6 of arXiv:2603.25459, 'Cram\'{e}r-type moderate deviation for double index permutation statistics'] Let $(X,X^{\prime})$ be an exchangeable pair satisfying the condition (D1), and $(W,W^{\prime})$ is also an exchangeable pair, $\Delta = W-W^{\prime}$. Let $\max\{|\Delta|,|D|\}\leq \delta$ for some constant $\delta>0$. Assume that there exits a constant $\tau>0$ such that 
\begin{itemize}
    \item [$(A_{1}):$] $\mathbb{E}\{e^{tW}\}<\infty$,
    \item [$(A_{2}):$] $\mathbb{E}\{\big|1-\frac{1}{2\lambda}\mathbb{E}\{D\Delta|W\}\big|e^{tW}\}\leq \delta_1(t)\mathbb{E}\{e^{tW}\}$,
    \item [$(A_{3}):$] $\mathbb{E}\{|R|e^{tW}\}\leq \delta_2(t)\mathbb{E}\{e^{tW}\}$,
\end{itemize}
where for each $j =1,2$, the fucntion $\delta_{j}(\cdot)$ is increasing and satisfies that $0\leq \delta_{j}(\tau)<\infty$. For $\theta>0$, let $\tau_{0}(\theta) := \max\{0\leq t\leq \min\{\tau,1/\delta\}:t^2(t\delta+2\delta_{1}(t))/2+3t\delta_{2}(t)\leq \theta\}$. Then for any $\theta>0$, $0\leq z\leq \tau_{0}(\theta)$,
\begin{align}
    \left|\frac{\mathbb{P}(W>z)}{1-\Phi(z)}-1\right|\leq 31e^{\theta}(1+9\delta)\left\{(1+z^2)[\delta_1(z)+\delta+\delta\cdot\delta_{2}(z)]+(1+z)\delta_2(z)\right\}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

