[Theorem thm012504-26 of arXiv:2606.07353, 'The Gaussian structure of a perturbed KPZ'] There exists a unique invariant, Borel probability measure
 $\nu_V \in {\mathcal M}_1\big( {\rm H}\big)$ for
 the solution of (equation 011804-26 of the paper), i.e.
 \begin{equation}

   \int_{\mathrm{H}}{\mathcal U}^V_tF(u) \nu_V(du)=\int_{\mathrm{H}}F(u) \nu_V(du),\quad
   t\ge0,\,F\in B_b(\rm H).
 \end{equation}
  The measure $\nu_V$ has the following properties:

 \begin{itemize}
   \item[i)] for any $F\in C_b({\rm H})$ and $\mu\in {\mathcal M}_1\big( {\rm H}\big)$, we have
 \begin{equation}

   \lim_{t\to+\infty}\int_{\mathrm{H}}{\mathcal U}^V_tF(u) \mu(du)=\int_{\mathrm{H}}F(u) \nu_V(du),
 \end{equation}
 \item[ii)] for any $p\in[0,+\infty)$   we
have
\begin{equation}

   \int_{\mathrm{H}} \|u \|_{H^{-1}(\mathbb{T})}^p  \nu_V(du)<+\infty,
 \end{equation}
 \item[iii)] for any $\mu\in
   {\mathcal M}_1\big( {\rm H}\big)$ for which
 \begin{equation}

  u_*:= {\limsup_{t\to0+}}\,\mathbf{E}_{\mu}\|u_V(t)\|_{{H^{-1}(\mathbb{T})}}<+\infty
 \end{equation}
  there exists constant $C >0$, depending only  $u_*$ and
  $\|V\|_{L^2(\mathbb{T})}$, and $\lambda>0$, depending only on    
  $\|V\|_{L^2(\mathbb{T})}$,   such that  
 \begin{equation}

   \begin{split}
     \Big| \mathbf{E}_{\mu}\Big[u_V(t)(\varphi)\Big]&-\int_{\mathrm{H}}u(\varphi)
     \nu_V(du)\Big|
     \le C 
  e^{-\lambda t}   \|\varphi\|_{H^1(\mathbb{T})},\quad
  t\ge0,\,\varphi\in H^1(\mathbb{T}).
  \end{split}
  \end{equation}
  \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 33 (Square-root cancellation) of arXiv:2609.04155, 'The subconvexity problem for symmetric square\\ $L$-functions in Level aspect'] Let $\pi$ be as in the Theorem~\ref{thm: thm1} we have, 
            \begin{equation}
                \mathcal C(k)\ll \sqrt{p},
            \end{equation}
            where the implied constant is absolute. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (Semilocalization) of arXiv:2604.11682, 'Semilocalization for inhomogeneous random graphs'] Suppose that Assumptions \ref{hyp:upperbd-weights} and \ref{hyp:behavior-m21} hold. For any $\nu > 0$ there exists $C_{\nu} > 0$ such that the following holds with $\nu$-high probability. For any normalized eigenvector $\b q$ of $A$ with associated eigenvalue $\lambda$ and for any $\eta \leq |\lambda|/2$ we have
\begin{equation} 
    \sum_{x\in \W_{\lambda, \eta}} \scalar{\b q}{\b u_{\sgn(\lambda)}(x)}^{2} \geq 1 - \frac{C_{\nu}}{\eta^{2}}\frac{\log N}{\log\log N}\,,
  \end{equation}
  where $\b u_{\pm}(x)$ is an explicit vector supported in $B_{2}(x)$ defined in \cref{prop:ps-ev} below. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 86 of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] There exists a constant $C$ such that for all $m,\ell,n,\delta$ as before and all $k\in [\![1,2f(\ell)]\!]$, we have
    \begin{equation}

      \PP(\TP_{\ell,m}^k)\leq C\ell^{-1/3+3\delta/2}
    \end{equation}

[Thm 5 of arXiv:2606.14917, 'The Ornstein--Uhlenbeck process on $\scr P_2$ \\with a volatility operator'] If $u$ is given as in \eqref{eq:u}, \eqref{eq:ubounds}, then $u\in \D(L_{G,\lam})$ and 
	\begin{align}
		L_{G,\lam}u(\mu)=&\Big(\sum_{i=1}^m\partial_iF\big(\mu(\varphi_1),\dots,\mu(\varphi_m)\big)\big(\EE_G[a(\varphi_i)|\Psi_\lam=\mu]-{\la\id_{\RR^d},\na\varphi_i\ra}_{T_\mu}\big)\Big)\\
		&+\Big(\sum_{i,j=1}^m\partial_i\partial_jF\big(\mu(\varphi_1),\dots,\mu(\varphi_m)\big)\EE_G[b(\varphi_i,\varphi_j)|\Psi_\lam=\mu]\Big),\nonumber
	\end{align}
	$(G\circ\Psi_\lam^{-1})$-a.e.~$\mu\in \P_2$.

[Corollary 5 of arXiv:2506.11918, 'Central limit theorems for the Euler characteristic in the Random Connection Model for hig'] In the situation of Theorem \ref{Th:myRCM} we have
    \begin{align*}
        \E{F^4} \,\leq\, \max\bigg\{ 256\left[ \beta\int_W \E{ \left(\Lambda_{(x,U)}F\right)^4 }^\frac{1}2 \lambda \, (\d x)  \right]^2 \hspace*{-3pt},\, 4 \beta \int_W \E{ \left(\Lambda_{(x,U)}F\right)^4 } \, \lambda \, (\d x) + 2 \bigg\}.
    \end{align*}

[Thm 19 (Main Theorem for $n=1$) of arXiv:2609.00974, 'On Algebraic Integrability\\ of Vector Fields \\ with Rational Function Coefficients\\ tha'] Let $k$ be a field of characteristic zero. 
    Let $f\in k(x)$, $f\ne 0$. 
    Let $PHD(\frac{1}{f})=P+L+H$ with ${L}=\sum_{i=1}^d \frac{c_i}{x_i-a_i}$, see Theorem \ref{thm: PFD}.

    Let $D=f\frac{\partial}{\partial x}:k(x) \to k(x)$ be a derivation. 

    Then the following are equivalent:
    \begin{enumerate}
        \item There is a finite type model of $k$ over integers, such that for all all maximal ideals $q$ from an open dense subset of the model, $D$ reduces modulo $q$ and we have $\mu_q\in \overline{k(q)}$, where $D^p=\mu_q D$.
        \item One of the following is true:
        \begin{enumerate}
            \item $L=0$.
            \item $P=H=0$, and the vector space spanned by the residues of $\frac{1}{f}$, the vector space $\op{Span}_\mathbb{Q}(c_1,c_2,\ldots,c_d)\subset \overline{k}$, has dimension $1$ over rational numbers.
        \end{enumerate}
    \end{enumerate}

