[Corollary 23 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] Assume $v=u<0$ and $\alpha+v>0$.  If $2v\not\in\ZZ_{\leq 0}$, then 
       \begin{multline}
     \GG_N(\alpha,v,v)=
    \tfrac{1}{
    2\pi \Gamma(2v)}\int_{0}^\infty \left|\Gamma(\alpha+\i x)\right|^{2N}\tfrac{|\Gamma(v+\i x )|^4}{ |\Gamma(2\i x)|^2}\d x
    \\+
    \tfrac{2}{{ \Gamma(1-2v)}}\,\sum_{\{j\geq 0:\, j+v<0\}} \,(j+v) \tfrac{(-2v)_j^2}{j!^2} \, \left[\Gamma (-j-v+\alpha ) \Gamma
   (j+v+\alpha )\right]^N   \\ \cdot  \Big(N \left[\psi
    (j+v+\alpha )-\psi  (-j-v+\alpha )\right]+2 \left[\psi(1-j-2 v)- \psi  (j+1)\right]+\tfrac1{j+v}\Big).
    \end{multline}

[Thm YMABG of arXiv:2607.19037, 'Semiclassical analysis for Yang--Mills \ random connections on compact surfaces'] Let $N=2(g-1)\dim(G)$ if $g\geqslant 2$, $N=2\sqrt{\dim G+1}-2$ if $g=1$, and $N=0$ if $g=0$. Define $\mathrm{d} 
u=Z^{-1} \omega^{\wedge^ rac{N}{2}}$, where $Z$ is a normalization constant that turns $
u$ into a probability measure. Let 
    \[Z_\epsilon(\Sigma)=\int_{G^{2g}}p_{\epsilon}\left(\mathsf{Hol}_{\partial S}\left[\sum_{a\in\mathsf{Crit}_1(f)}\log g_a U_aight]ight)\mathrm{d} g.\]
    Then, there exists a measure $	ilde{
u}$ supported on $\mathsf{Hol}_{\partial \mathcal{S}}^{-1}(1_g)$ such that
    \[\mathrm{d} 	ilde{
u}(g_1,\cdots,g_{2g}) =\lim_{\epsilon	o 0}  rac{ p_{\epsilon}\left(\mathsf{Hol}_{\partial S}\left[\sum_{a\in\mathsf{Crit}_1(f)}\log g_a U_aight]ight)}{Z_\epsilon(\Sigma)} igotimes_{a\in\mathsf{Crit}_1(f)}\mathrm{d} g_a\]
        in the sense of weak convergence of probability measure. Moreover, the measure $	ilde{
u}$ descends to the quotient space $\mathsf{Hol}_{\partial \mathcal{S}}^{-1}(1_g)/G$, and the quotient measure is equal to $
u$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma basic energy estimate of arXiv:2609.00627, 'Global well-posedness of radially symmetric strong solutions to two-dimensional compressib'] There is a constant $C>0$ depending only on $\gamma$, $\Omega$, $\|\rho_0\|_{L^\infty}$, $\|\boldsymbol{u}_0\|_{L^2}$ and $\|\nabla\boldsymbol{d}_0\|_{L^2}$ such that
	\begin{equation}
		\begin{aligned}
			&\sup_{0 \le t \le T} \int (\rho {|\boldsymbol{u}|}^2+\rho^{\gamma}+{|\nabla \boldsymbol{d}|}^2)dx \\
			&+\int_0^T \int (\mu {|\nabla \boldsymbol{u}|}^2+(2\mu +\lambda(\rho)){(\operatorname{div} \boldsymbol{u})}^2+ {|\Delta \boldsymbol{d}+{|\nabla \boldsymbol{d}|}^2\boldsymbol{d}|}^2) dxdt \le C.
		\end{aligned}
	\end{equation}

[Definition def: identical sequence of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] A process (sequence) $\{X_t\}_{t\in \mathbb{T}}$ ($\mathbb{T}\subset \mathbb{R}_+$) of d-dimensional random vectors on a sublinear expectation space $(\Omega, \mathcal{H}, \hat{\mathbb{E}})$ is called
        \begin{enumerate}[(i)]
            \item  an identical process (sequence) if $X_t$ and $X_s$ are identically distributed for all $t,s\in \mathbb{T}$;
            \item a stationary process (sequence) if for any $n\geq 1$, $t\in\mathbb T$ and $\{t_i\}_{i=1}^n\subset \mathbb{T}$ with $\{t+t_i\}_{i=1}^n\subset \mathbb{T}$
		\begin{equation*}
			(X_{t_1},\cdots,X_{t_n})\stackrel{d}{=} (X_{t+t_1},\cdots,X_{t+t_n}).
		\end{equation*}
        \end{enumerate}

[Theorem 29 (Theorem 1.1 in \cite{MSS23}) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] Let $G = (V,E)$ be a graph with $|V|=n$, which is either of the following: 
	\begin{itemize}
		\item[(i)] a $b$-expander graph for some $b>0$ with maximum degree $\Delta<\infty$; 
		\item[(ii)] the box $[-L, L]^d\cap \Z^d$ of volume $n$, for some $d\geq 5$.
	\end{itemize}
        Let $\cT$ be the RSTRE on $G$ for some environment distribution $\mu$ with $\beta = 1$. Then there exist constants $c_1, c_2, \gamma>0$ (with $c_1 = c_1(\mu, b, \Delta)$ for case (i), and $c_1 = c_1(\mu, d), c_2 = c_2(d)$ for case (ii)), such that for all $n \geq 2$ and $\delta > n^{-\gamma}$, we have
        \begin{equation}
            \widehat \P \left( \frac{\sqrt{n}}{c_1(\delta^{-1}\log n)^{c_2}} \leq \diam(\cT) \leq c_1 (\delta^{-1} \log n)^{c_2} \sqrt{n}  \right) \geq 1-\delta .
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 61 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] For every $k$,
\begin{equation}
 \Nrm_x(\overline L_{\alpha,k})
 =\left.\partial_z^{\length(w)-k}
 \Nrm_{x,z}(\overline H_{w,\lambda})\right|_{z=0}
 \in\RV.
\end{equation}
Taking $\kk=\CC$, every nonzero homogeneous atom layer is Lorentzian and has
$M$-convex support.

[Lemma lem:PCces of arXiv:2601.10624, 'Source localisation in simple random walks'] We have
    \begin{equation*}
        \liminf_{n\to\infty} \frac{1}{n} \sum_{i=0}^{n-1} \mathbb{P}(\mathcal{C}_i) \geqslant c(\mathbb{H}).
    \end{equation*}

