[Theorem 5 of arXiv:2609.03187, 'Duality for a Martingale Transport Problem with Moment Constraints'] For every $c\in\mathcal C$ we have
\begin{equation} 
V(c)\leq \inf_{\lambda\in\mathbb R^N}\left\{\lambda\cdot c-\int \Psi_\lambda^*(x)\,\mu(dx)\right\}.
\end{equation}
Assume, in addition, that $c \in \operatorname{int} (\mathcal{C})$. Then there is no duality gap:
\begin{equation}
V(c)= \inf_{\lambda\in\mathbb R^N}\left\{\lambda\cdot c-\int \Psi_\lambda^*(x)\,\mu(dx)\right\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:corrector of arXiv:2608.17022, 'Sharp hypocoercive convergence estimates for underdamped Langevin dynamics with specular r'] For any $\phi\in\mathscr C_0$,
\begin{align}
\nrm{\mathscr{A}_m\phi}&\le\frac1{2\sqrt m}\,\nrm{\phi},\\
\nrm{\mathscr{L}_a\mathscr{A}_m\phi}&\le\nrm{\phi},\\
\nrm{\mathscr{A}_m\mathscr{L}_a(1-\Pi_v)\phi}&\le\sqrt{2+\frac{K}{2m}}\;\nrm{\phi}.
\end{align}
In particular, $\mathscr{A}_m$, $\mathscr{L}_a\mathscr{A}_m$ and $\mathscr{A}_m\mathscr{L}_a(1-\Pi_v)$ extend uniquely to bounded operators on $\Lmuz$ with the same bounds, and if $\varepsilon<\sqrt m$ then
\begin{equation}
\frac{1-\varepsilon/\sqrt m}{2}\,\nrm{\phi}^2\le\mathsf L_m(\phi)\le\frac{1+\varepsilon/\sqrt m}{2}\,\nrm{\phi}^2
\qquad\text{for any $\phi\in\Lmuz$}.
\end{equation}

[Lemma l.integralLimit of arXiv:2606.11043, 'Thick points under Gaussian free field dynamics'] Consider $f\in C([-T,T])$. For each $N\in\mathbb N$, consider $\Delta_N= T2^{-N}$ and \begin{align*}
    I_N=\{t_k = k\Delta_N, \hspace{0.1cm} k\in \{-2^N,...,2^N\}\}.
    \end{align*} Then $f\in H^1([-T,T])$ if and only if
    \begin{equation}

        \lim_{N\to \infty}\sum_{k=-2^N}^{2^N-1}
        \Delta_N
        \left(
        \frac{f(t_{k+1})-f(t_k)}{\Delta_N}
        \right)^{2}<\infty.
    \end{equation}
    Furthermore, 
    \begin{align*}
\lim_{N\to \infty}\sum_{k=-2^N}^{2^N-1}
        \Delta_N
        \left(
        \frac{f(t_{k+1})-f(t_k)}{\Delta_N}
        \right)^{2} = \int_{-T}^T |f'|^2 dt,
    \end{align*}
    where $f'$ is the weak derivative of $f$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:NL-MP of arXiv:2607.00800, 'Brownian motion in Minkowski normed spaces'] Let $\mathcal P_0 \subseteq \mathcal P$. 
   A (\emph{time-homogeneous}) \emph{nonlinear Markov process} is a family $\{P^\zeta\}_{\zeta \in \mathcal P_0} \subseteq \mathcal P(\mathcal C)$ such that, setting $\mu^\zeta_t := P^\zeta_t \in \mathcal P$ for $(t,\zeta) \in [0,\infty) \times \mathcal P_0$,
    \begin{enumerate}[(i)]
        \item $\mu^\zeta_0 = \zeta$ for all $\zeta \in \mathcal P_0$, and $\mu^\zeta_t \in \mathcal P_0$ for all $(t,\zeta) \in (0,\infty)\times \mathcal P_0$;
        \item the (\emph{time-homogeneous}) \emph{nonlinear Markov property} holds, i.e.,
        \begin{equation*}
        P^\zeta(\pi_{t+s} \in A | \mathcal F_s) ( \cdot) = P^{\mu^\zeta_s,\pi_s(\cdot)}(\pi_t \in A)\quad P^\zeta\text{-a.s.},\quad \forall s,t \geq 0, \, \zeta \in \mathcal P_0
    \end{equation*}
    for every Borel set $A \subseteq \mathbb{R}^d$,
    where for $\zeta \in \mathcal P_0$, $\{P^{\zeta,y}\}_{y\in \mathbb{R}^d}$ is the disintegration family of $P^{\zeta}$ with respect to $\pi_0$, i.e., the $\zeta$-a.s.\ unique family $\{Q^y\}_{y\in \mathbb{R}^d}$ in $\mathcal P(\mathcal C)$ such that $y\mapsto Q^y(W)$ is measurable and $P^\zeta(W) = \int_{\mathbb{R}^d} Q^y(W) \,\mathrm d \zeta(y)$ for all $W \in \mathcal B(\mathcal C)$.
    \end{enumerate}

