[Lemma lem:maximum_principle of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] Fix $T > 0$, $\kappa > 0$, and $m > 2$. Suppose $f_{\rm in} \in L^\infty_{{\rm rapid}}(\mathbb T^3\times \mathbb R^3)$ and $g\in L^\infty(0,T;L^\infty_m)$ satisfy $0 \le f_{\rm in},\,g\le 1$.
    Then, for every $\ell > 0$, the unique solution $f$ to (equation eq:semilinear of the paper) satisfies
    \begin{equation}
         \left\|f(t)\right\|_{L^\infty_{\ell}} \le \exp\bigl\{C(\kappa + \Lambda)t\bigr\}
         \norm{f_{\rm in}}_{L^\infty_\ell}, 
    \end{equation}
    where $C$ depends only on $m$ and $\ell$ and where $\displaystyle \Lambda \coloneqq \left\|g(t)\right\|_{L^\infty(0,T;L^\infty_m)}$. In particular, $f(t) \in L^\infty_{{\rm rapid}}$ for each $t \in [0,T]$.

[Defi 58 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] The length $\alpha_{\tot}\log(N)$ string $x\in [k]_0^M$ is a \textbf{collision-likely prefix} (we write $x\in \Pre$) if for all $(i,l)\in T$,
        \begin{equation}
            x \mbox{ contains } \alpha_l^{(i)}\log(N) \mbox{ of } l\mbox{-digits in positions } \{1\leq t\leq \alpha_{\tot}\log(N): \bn^{(t)}/N\in D_i\}.
        \end{equation}

[Definition of arXiv:2604.17253, 'Large Deviations for the Nonlinear Schrödinger Equation with Randomized Quasi-Periodic Ini'] The {\em first counting function} $\sigma$ on $\Gamma^{(k)}$ is defined by
\begin{align*}
\sigma(\gamma^{(k)})=
\begin{cases}
\frac{1}{2}, & \gamma^{(k)}=0, \ k\ge1; \\
\frac{3}{2}, & \gamma^{(1)}=1; \\
\sum_{j=1}^{3}\sigma(\gamma_j^{(k-1)}), & \gamma^{(k)}=(\gamma_j^{(k-1)})_{j=1}^3,\ k\ge2.
\end{cases}
\end{align*}

[Lemma 24 of arXiv:2606.13648, 'Stochastic dominations for FK percolation and sharp thinning thresholds for the Ising ener'] Take $C_1=\prod_{e=0}^n(1+q_e)$, $C_{-1}=\prod_{e=0}^n(1-q_e)$ and $Z=\sum_{F\in\F}q_F$ where $\F\subset{\mathcal P}(E)$ is the set of subsets of $E$ of even cardinality and $q_F=\prod_{e\in F}q_e$ for $F\subset E$. We have that $C_1+C_{-1}=2Z$ and
\begin{equation}
\en_J = \frac{1}{2Z}\big(C_1\cdot\ber{\frac1{1+q}}+C_{-1}\cdot\ber{\frac1{1-q}}\big)
\end{equation}
as measures. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 55 of arXiv:2607.18104, '2607.18104'] Fix $M\in \N$. For $N\in \N$ and $k=k(N) \in \lbr N \rbr$. Set $\rho=\frac{1}{2}(1-\alpha)=k/N$ for all $N$ large enough. Assume that $\rho \in [\mathfrak{a},1-\mathfrak{a}]$ for some $\mathfrak{a}>0$. 
Consider a family of $(N,k)$-periodic Bernoulli paths $h_0^{\per,(i)}$ for $i\in \lbr M \rbr$ and assume that the particle configurations $\eta_0^{\per,(i)}$, corresponding to $h_0^{\per,(i)}$, satisfy for all $i\in \lbr M \rbr$
\begin{equation}
\Ber_{\rho+CN^{-1/2}}^{N} \succeq \P( \eta_0^{\per,(i)} \in \, \cdot \, ) \succeq \Ber_{\rho-CN^{-1/2}}^{N}
\end{equation}
with some constant $C>0$. Let $\varepsilon=\varepsilon(N,k)>0$, and let $\hfix_{0}^{\per,(i),\varepsilon}$ denote the rescaled ASEP height functions from \eqref{def:RescaledPeriodicASEPheight} in Definition~\ref{def:ASEPheightRescaledPeriodic} at time $0$.
Suppose that for all $i \in \lbr M \rbr$, there exists a continuous function $\hfix_{0}^{\per,(i)} \colon \mathbb{T} \rightarrow \R$ 

such that as $\varepsilon \rightarrow 0$, $\hfix_{0}^{\per,(i),\varepsilon}$ converges weakly to $\hfix_{0}^{\per,(i)}$ with respect to the product topology induced by the uniform topology on $\mathcal{C}(\mathbb{T})$. Let $\hfixp$ denote a periodic KPZ fixed point. 
Then we have weak convergence as $\varepsilon\to 0$ of
\begin{equation}
\left(\hApeps(\hfix_0^{\per,(i),\varepsilon};\cdot,t)\right)_{i \in \lbr M \rbr, t \in \mathcal{T}} \rightarrow \left(\hfixp(\hfix_0^{\per,(i)};\cdot,t)\right)_{i \in \lbr M \rbr, t \in \mathcal{T}} . 
\end{equation}  Here, the functions on the left-hand side are coupled according to the basic coupling for the underlying periodic ASEPs, while the functions on the right-hand side are coupled as in Definition~\ref{def:PeriodicKPZfixed} with respect to the same periodic directed landscape $\Lp$, taking values in $\mathcal{T}$ for the time component. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:technical_pi01 of arXiv:2608.26904, 'Hyperarithmetic directions can all be exceptional for Marstrand's projection theorem'] Given a $Z \in 2^\omega$ and $\bar{e} = (\vec{e}_s)_{s \in \omega}$ a sequence of directions in $\mathbb{R}^2$, there is $A \subset 2^\omega \times 2^\omega$ such that:
\begin{enumerate}
\item $A$ is uniformly $\Pi^0_1(Z, \bar{e})$;
\item For all $(x, y) \in A$, neither $x$ nor $y$ is finite or cofinite (thus $\iota$ is nice on $A$);
\item For all $(x, y) \in A$, for all $n$, $Z(n) = x((n+1)!) \ominus y((n+1)!)$;
\item $A$ has Hausdorff dimension at least 1; and
\item For every $s \in \omega$, $\={Proj}_{\vec{e}_s}(\iota(A))$ has Hausdorff dimension 0, with witnessing oracle $\emptyset$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:discrete-decay of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Assume that ${(X_t,P_t)}_{t\in [t_-,t_+]}$ and ${(X_t^\mathsf{aux}, P_t^\mathsf{aux})}_{t\in [t_-,t_+]}$ evolve by~(eq:ULD of the paper) and are synchronously coupled.
    Then,
\begin{align*}
    \mathrm{d} \norm{\upphi_t(\delta X_t, \delta Z_t)}^2 \leqslant -2\,(1-\varepsilon_t)\,\lambda_{\min}(\mathcal{M}_t)\,\norm{\upphi_t(\delta X_t, \delta Z_t)}^2\,,
\end{align*}
where $\mathcal{M}_t$ is defined in Lemma~(lem:decay of the paper),
\begin{align*}
    \varepsilon_t
    &\coloneqq 
    \frac{\norm{\mathcal{N}_t}_{\rm op} + \norm{I-\upphi_t^{-1}}_{\rm op}\,(\norm{\mathcal{M}_t}_{\rm op} + \norm{\mathcal{M}_t^{\rm skew}}_{\rm op} + \norm{\mathcal{N}_t}_{\rm op})}{\lambda_{\min}(\mathcal{M}_t)}\,,
\end{align*}
and $\mathcal{M}_t^{\operatorname{skew}}$, $\mathcal{N}_t$ are defined as
\begin{align*}
    \mathcal{M}_t^{\operatorname{skew}} &\coloneqq \begin{bmatrix}
        0 & (-\eta^\mathsf{x}_t/\gamma_t + \dot{\gamma}_t/(2\gamma_t))\, I - \mathcal{H}_t/\gamma_t \\
        (\eta^\mathsf{x}_t/\gamma_t - \dot{\gamma}_t/(2\gamma_t))\,I + \mathcal{H}_t/\gamma_t & 0
    \end{bmatrix}\,, \\
    \mathcal{N}_t &\coloneqq \begin{bmatrix}
        0 & 0\\
        (-\mathcal{I}\eta^\mathsf{x}_t  + {\gamma \,\mathcal{I}\eta^\mathsf{p}_t} + \dot{\gamma}_t\,\mathcal{I}\eta^\mathsf{p}_t/\gamma_t -2\dot \gamma_t \,\mathcal{I}\eta^\mathsf{x}_t/\gamma_t^2)\,I - 2\,\mathcal{I}\eta^\mathsf{p}_t\,\mathcal{H}_t/\gamma_t & (\mathcal{I}\eta^\mathsf{x}_t-\gamma \,\mathcal{I}\eta^\mathsf{p}_t - \dot{\gamma}_t\, \mathcal{I}\eta^\mathsf{p}_t/\gamma_t)\,I
    \end{bmatrix}\,.
\end{align*}

