[Theorem thm:gartner_ellis of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Consider a sequence of random variables $(X_n)_{n \geq 1}$ and a sequence $(a_n)_{n \geq 1}$ with $a_n \gg 1$. Assume for every $\lambda \in \mathbb R$ the limit
    \begin{align*}
    \lim_{n \to \infty}\frac{1}{a_n}\log \mathbb{E}\left[\Big.\exp\big(\lambda a_nX_n\big)\right]= \Lambda(\lambda),  \addtocounter{equation}{1}\tag{\theequation} 
\end{align*}
    exists point-wise as a convex function of $\lambda$, possibly assuming an extended real value for some $\lambda$, with the origin lying inside the interior of the domain $\mathcal D_{\Lambda}:=\{\lambda \in \mathbb R:\Lambda(\lambda)<\infty\}.$ Let $\Lambda$ further satisfy the following:
    \begin{itemize}
    \item Interior of $\mathcal D_{\Lambda}$ is non empty.
    \item $\Lambda$ is differentiable at all points of the interior of $\mathcal D_{\Lambda}$.
    \item $\Lambda(\cdot)$ is steep, namely, $\lim_{n \to \infty} |\Lambda'(\Lambda_n)|=\infty$ whenever $\lambda_n$ is a sequence of interior points of $\mathcal D_{\Lambda}$ converging to some boundary point of the interior of $\mathcal D_{\Lambda}$.
\end{itemize}
Then the sequence $(X_n)_{n \geq 1}$ satisfies a LDP with speed $a_n$ and with good rate function $\Lambda^*$, the \emph{Fenchel-Legendre} transform of $\Lambda$, defined as,
\begin{align*}
    \Lambda^*(x)=\sup_{\lambda \in \mathbb R}\Big\{\lambda x -\Lambda(\lambda)\Big\}\,.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem typT poly UB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] For any $\ell \in \mathbb{N}$ and $a \in (0,\infty)$,
  \begin{equation}
    \sup_{\bm{x} \in M^k}
    \hat{P}_{\bm{x}}\!\left(C_{\delta_\ell} \geq a \Psi_{\mathrm{ct}}(\delta_\ell)\right) 
    \leq 
    \tilde{c}_1 \ell^{-\tilde{c}_2 a^{2/\hat{d}_{\mathrm{s}}^*}}.
  \end{equation}

[Lemma lemma0 of arXiv:2510.10898, 'A central limit theorem for unbalanced step-reinforced random walks'] For any $\beta\in (0,4]$, we have
\begin{eqnarray}
\mathbb{E}(|T_n^0|^{\beta})=O(a_r(n))^{\beta/2}),  
\end{eqnarray}
where
\begin{eqnarray*}
a_r(n):=\left\{ 
\begin{array}{ll}
n, &   r<3/4;\\
n\log n, &   r=3/4;\\
n^{4r-2}, &   r>3/4.
\end{array}
\right.
\end{eqnarray*}

