[Theorem thm:SobolevPoincare of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] Let $1 \leq p \leq q$, $(\mathcal{F}_p,\Gamma_p,\Psi)$ be a $p$-energy structure, $\Theta$ be a scale function and $\nu$ be a Borel measure of $X$.
    Then the following two conditions are equivalent.
    \begin{enumerate}[label=\textup{(T\arabic*)}, leftmargin=*]

        \vspace{2pt}
        \item 
        There is a constant $K \geq 1$ such that for all $x \in X$ and $r \in (0,\diam(X))$,
        \begin{equation*}
            \nu(B(x,r))^{\frac{1}{q}} \leq K \Theta(x,r) \left( \frac{\mu(B(x,r))}{\Psi(x,r)} \right)^{\frac{1}{p}}
        \end{equation*}
        \vspace{2pt}
        \item 
        There are constants $C,\sigma \geq 1$ such that for all $x \in X$, $r \in (0,\diam(X))$ and $f \in \mathcal{F}_p$,
        \begin{equation*}
    \left(\int_{B(x,r)} \abs{\tilde{f} - f_{B(x,r)}}^{q} \, d\nu \right)^{\frac{1}{q}} \leq C \Theta(x,r) \left(\int_{B(x,\sigma r)} d\Gamma_p\Span{f} \right)^{\frac{1}{p}}
        \end{equation*}
    \end{enumerate}
    Here $\tilde{f}$ is the precise representative given in (equation eq:Exact of the paper).
    This equivalence is quantitative in the sense that the constants appearing in (T2 of the paper) \textup{(}resp. (T1 of the paper)\textup{)} depend only on the constants in (T1 of the paper) \textup{(}resp. (T2 of the paper)\textup{)}, the constants appearing in (eq:PI of the paper),(eq:UCap of the paper), (equation eq:muDoubling of the paper), (equation eq:RadDiam of the paper), the constants associated with $\Psi$ and $\Theta$ in (equation eq:Psi of the paper), $p$ and $q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conjecture of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $d, \mu, \gamma$, and $q$ be as in Theorem~(thm:shuffle of the paper). Then the following hold.
    \begin{enumerate}[label=(\alph*)]
        \item The multi-stack random-to-random shuffle chain $\mathbf{X}^{\textup{shuf}}$ exhibits cutoff around time
        \begin{equation*}
            T \coloneqq n \log n \cdot \max\set{\frac{1}{2\gamma}, \frac{3}{4}}.
        \end{equation*}

        \item The restricted random-to-random shuffle chain $\mathbf{X}^{\textup{res-shuf}}$ exhibits cutoff around time
        \begin{equation*}
            T \coloneqq n \log n \cdot \max\set{\frac{1}{2\gamma}, \frac{3}{4q}}.
        \end{equation*}
    \end{enumerate} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

