[Corollary 14 of arXiv:2608.26618, 'A Unified Descriptive-Complexity Framework for Model Selection under Correlated Designs'] Assume the conditions of Theorem~\ref{thm:control} and
\begin{align*}
\frac{n}{2\sigma^2}\,\underline{\omega}\,\beta_{\min}^2>\eta_n+\lambda C_{\max}^*+\lambda_{\zeta}\log s^*
\qquad \text{for all }\lambda\in\Lambda.
\end{align*} 
Then, with probability at least $1-c\delta$, the following bounds hold for all
$\lambda\in\Lambda$:
\begin{align*}
\Delta^+(\widehat S_{\lambda})\ \le\frac{\lambda_{\zeta}\log(L/\delta)}{\eta_n+(\lambda-\lambda_{\zeta}) C_{\min}},
\qquad
\Delta^-(\widehat S_{\lambda})\ \le \frac{\lambda_{\zeta}\log(L/\delta)}
{\frac{n}{2\sigma^2}\underline{\omega}\beta_{\min}^2-\eta_n-\lambda C_{\max}^*-\lambda_{\zeta}\log s^*}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 43 (Taylor remainder) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Assume that for a family of random smooth functions $f_x$ there exist $\alpha\in\RR$ and $\eta\geq0$ such that for all $\n$ 

\begin{equation}
\EE^\frac1p|\partial^\n f_x(y) |^p 
\lesssim \ve^{\alpha-|\n|} (\ve+|x-y|)^\eta \, .
\end{equation}

Then for all $\n$ and $l\geq0$ 

\begin{equation}
\EE^\frac1p| (\mathrm{id}-T_z^{\leq l}) \partial^\n f_x (y) |^p
\lesssim \ve^{\alpha-|\n|-1-l} |y-z|^{1+l} (\ve+|x-y|+|x-z|)^\eta \, .
\end{equation}

