[Lem 24 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $0<\A{1},\A{2}\leq 1$ be such that $N^{-1}\ll  \pr{\A{1}\A{2}}^{1/2}$. Let $0< 1/C\leq \widehat{q}\in S(1,\A{1},\A{2})$ such that $\widehat{q}\sim \widehat{q}_0+\Tilde{h}\widehat{q}_1+...$ in $S(1,\A{1},\A{2})$. Then, 
    \begin{equation}
        \begin{split}
            \log\det&\pr{\widehat{q}_{N,\A{1},\A{2}}}\\
            &= \pr{N\A{1}^{1/2}\A{2}^{1/2}}^{d}\int_{\mc{T}_{\A{1},\A{2}}}\log\pr{\widehat{q}_0(\rho)}d\rho+\mc{O}\pr{N^d\pr{N\A{1}^{1/2}\A{2}^{1/2}}^{-1}}.
        \end{split}
    \end{equation}

[Lemma lm:chain of arXiv:2508.21055, 'Modern aspects of Markov chains:\\entropy, curvature and the cutoff phenomenon'] Fix $f\in\mathcal {F}^{++}$ and set $r:=\mathrm {Lip} \log f$. Then,
\begin{eqnarray*}
\phi(-r)\,\left(\frac{Lf}{f}-L\log f\right)\ \le & \Gamma \log f & \le \ \phi(r)\,\left(\frac{Lf}{f}-L\log f\right),
\end{eqnarray*}
where we have introduced the cost function $\phi(r)  = \frac{r^2}{2\left(r +e^{-r}-1\right)}$. In particular, 
\begin{eqnarray*}
{\mathbb{E}}\left[f\Gamma \log f\right] & \le & \left(1+r\right)\mathscr {E}(f,\log f).
\end{eqnarray*}

