u} \sqrt{ rac{\log N}{\log \log N}} \quad 	ext{ and } \quad \|\hat{A} - A\| \leq C_{
u}\sqrt{ rac{\log N}{\log \log N}}\,.
  \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition d:corfun of arXiv:2508.21658, 'Infinite-dimensional stochastic differential equations for Coulomb random point fields'] A symmetric, locally integrable function $ \rho_\nu^m $ on $ \Rdm $
is called the \emph{$ m $-point correlation function}
of an RPF $ \nu $ (with respect to Lebesgue measure) if
\begin{align}\notag &
\int_{ A_1^{ k_1 } \times \cdots \times A_n^{ k_n } }
\rho_\nu^m ( \x ^1 , \ldots , \x ^m ) \, d\x ^1 \cdots d\x ^m
=
\int_{ \sSS }
\prod_{ i = 1 }^{ n }
\frac{ \sss ( A_i ) ! }{ ( \sss ( A_i ) - k_i ) ! }
\, \nu ( d\sss )
,\end{align}
for any disjoint bounded measurable sets
$ A_1 , \ldots , A_n $
and nonnegative integers
$ k_1 + \cdots + k_n = m $.
Here, $ \sss ( A ) $ denotes the number of particles in $ A $
when $ \sss = \sum_i \delta_{ \si } $,
and the fraction is interpreted as zero
if $ \sss ( A_i ) - k_i < 0 $.

[Lemma 9 of arXiv:2605.11877, 'Fluctuation analysis for a randomly perturbed dynamical system with state-dependent impuls'] Given $\delta>0$ same as the in set $G^\eps_{\cdot}$, the following holds,
