[Proposition 11 of arXiv:2609.02105, 'Contact fundamental forms and \\ adjoint varieties'] Let us use the coordinates and the 1-form $\theta$ on the Heisenberg group $\sH$ in Lemma \ref{l.coordi}.   
For each holomorphic function $F$ on $\sH$,  
  define a holomorphic vector field $\overrightarrow{F}$ on $\sH$ by \begin{eqnarray*}
\overrightarrow{F} & := &  - \frac{1}{2} \sum_{a=1}^m (\frac{\p F}{\p y_a} + \frac{x_a}{2} \frac{\p F}{\p t}) \frac{\p}{\p x_a} + \frac{1}{2} \sum_{a=1}^m (\frac{\p F}{\p x_a} - \frac{y_a}{2} \frac{\p F}{\p t}) \frac{\p}{\p y_a} \\ & & +  \left(\frac{1}{4} \sum_{a=1}^m  (x_a \frac{\p F}{\p x_a} + y_a \frac{\p F}{\p y_a}) - \frac{F}{2} \right) \frac{\p}{\p t}. \end{eqnarray*} 
 Then $\overrightarrow{F}$ is the unique vector field satisfying  $\theta (\overrightarrow{F}) = F$  and  $$  {\rm Lie}_{\overrightarrow{F}} \theta = -\frac{1}{2} \frac{\p F}{\p t} \theta.$$

[Theorem 11 (Exceedance times) of arXiv:2607.16502, 'Asymptotic Behavior of Path Functionals for Vector-Valued Gaussian Processes at High Level'] Let \( \mathfrak t(u,L) \) be defined as above, with the threshold sequence
    \(L_u\) chosen as in the corresponding asymptotic theorem.
    \begin{enumerate}[(a),wide]
        \item \textbf{Stationary case.} Under the assumptions of
        Theorem~\ref{thm:stationary_case}, for every \(s\in[0,T]\),
        \begin{equation*}
          \pk{
            \mathfrak t(u,L)\le s
            \,\middle|\,
            \mathfrak t(u,L)\le T
          }
          \to \frac{s}{T}.
        \end{equation*}

        \item \textbf{Non-stationary case \(\alpha<\beta\).} Under the
        assumptions of Theorem~\ref{thm:main_theorem}(a), for every
        \(S\geq0\),
        \begin{equation*}
            \pk{
              u^{2/\beta}\mathfrak{t}(u,L)\leq S
              \,\middle|\,
              \mathfrak{t}(u,L)\leq T
            }
            \to
            \frac{
                \Gamma (1 / \beta) - \Gamma (1 / \beta, \tau_{\bm{w}} S^\beta )
            }{
                \Gamma (1 / \beta)
            }.
        \end{equation*}

        \item \textbf{Non-stationary case \(\alpha=\beta\).} Under the
        assumptions of Theorem~\ref{thm:main_theorem}(b), put
        \begin{equation*}
          G_{\mathfrak P}(S)
          =
          \frac{
          H_{\Gamma,L,\alpha,V_{I,I},\bm d_I,\Sigma,\bm b}([0,S])
          }{
          \mathcal{P}_{\Gamma,L,\alpha,V_{I,I},\bm d_I,\Sigma,\bm b}
          },
          \qquad S\ge0,
        \end{equation*}
        and define its right-continuous modification, extended to \(\R\), by
        \begin{equation*}
          F_{\mathfrak P}(S)
          =
          \begin{cases}
            0, & S<0,\\[2pt]
            \displaystyle\lim_{r\downarrow S}G_{\mathfrak P}(r), & S\ge0.
          \end{cases}
        \end{equation*}
        Assumption~\ref{B1} and the definition of the Piterbarg constant imply
        that \(G_{\mathfrak P}\) is non-decreasing and tends to \(1\); hence
        \(F_{\mathfrak P}\) is a distribution function.  Then, at every
        continuity point \(S\ge0\) of \(F_{\mathfrak P}\),
        \begin{equation*}
            \pk{
              u^{2/\beta}\mathfrak{t}(u,L)\leq S
              \,\middle|\,
              \mathfrak{t}(u,L)\leq T
            }
            \to F_{\mathfrak P}(S).
        \end{equation*}
        Consequently, if \(0\le a<r\) are continuity points of
        \(F_{\mathfrak P}\), then
        \begin{equation*}
            \pk{
              u^{2/\beta}\mathfrak t(u,L)\in(a,r]
              \,\middle|\,
              \mathfrak t(u,L)\le T
            }
            \to F_{\mathfrak P}(r)-F_{\mathfrak P}(a).
        \end{equation*}

        \item \textbf{Non-stationary case \(\alpha>\beta\).} Under the
        assumptions of Theorem~\ref{thm:main_theorem}(c), define
        \begin{equation*}
          \mathfrak C(S)
          =
          \int_{\R^d}
          \exp \left(
            \bm{x}_I^\top \bm{w}_I
            - \frac{1}{2} \, \bm{x}_J^\top ( \Sigma^{-1} )_{J J} \, \bm{x}_J
          \right)
          \Ind{
            \Gamma_{[0,S]} \left(
              -\bm{d}_I - \bm{x}_I,
              -\bm{x}_{\Jtan},
              ( \bb - \bm{b} )_{\Jsl}
            \right)>L
          }
          \,d\bm x,
          \qquad S\ge0,
        \end{equation*}
        put
        \begin{equation*}
          G_{\mathfrak C}(S)
          =
          \frac{\mathfrak C(S)}{\mathcal C_{\Gamma,L,\bm d,\Sigma,\bm b}},
          \qquad S\ge0,
        \end{equation*}
        and define its right-continuous modification, extended to \(\R\), by
        \begin{equation*}
          F_{\mathfrak C}(S)
          =
          \begin{cases}
            0, & S<0,\\[2pt]
            \displaystyle\lim_{r\downarrow S}G_{\mathfrak C}(r), & S\ge0.
          \end{cases}
        \end{equation*}
        Assumption~\ref{B1} and the definition of the deterministic constant
        imply that \(G_{\mathfrak C}\) is non-decreasing and tends to \(1\);
        hence \(F_{\mathfrak C}\) is a distribution  (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 of arXiv:2605.15781, 'Mean-Field Backward Stochastic Differential Equations with Nonlinear Resistance and Double'] Suppose that Assumptions \ref{asslip2}, \ref{assLRbounded} hold.  Let $(Y,Z,K)$ denote the unique deterministic solution to MFBSDE \eqref{MFBSDEDMR} with double mean reflections. Moreover, suppose that 
    \begin{align}
        \sup_{t\in[0,T]}\E[|Z_t|^2]<\infty.
    \end{align}
Then the process $K$ is Lipschitz continuous. Furthermore, $K$ has the density function.

