body:
[Thm 22 of arXiv:2604.13387, 'Multiradial Schramm-Loewner evolution: \\ Infinite-time large deviations and transience'] Suppose that the probability measures $(P^\kappa)_{\kappa>0}$ satisfy an LDP in a topological space $X$
with good rate function $E$. 
For each $\kappa > 0$, let $\Phi^\kappa \colon X \to [-\infty, +\infty]$ be a measurable function, 
and let $Q^\kappa$ be a measure on $X$ absolutely continuous with respect to $P^\kappa$ with Radon-Nikodym derivative 
\begin{align*}
\frac{\ud Q^\kappa}{\ud P^\kappa}(x) = \exp \Big(\frac{1}{\kappa} \Phi^\kappa(x) \Big) , \qquad x \in X . 
\end{align*}
Suppose that as $\kappa \to 0$, the functions $\Phi^\kappa$ converge steadily to $\Phi^0 \colon X \to [-\infty, +\infty]$,
and that $\Phi^0$ is bounded from above. Then, the following hold.
\begin{enumerate}
\item  
If $\Phi^0$ is upper semicontinuous on a closed subset $F$ of $X$, then
\begin{align*}
\limsup_{\kappa\to 0+} \kappa \log Q^\kappa[F]
\leq - \inf_{x \in F} \big(E(x) - \Phi^0(x)\big) .
\end{align*}

\item  
If $\Phi^0$ is lower semicontinuous on an open subset $O$ of $X$, then
\begin{align*}
\liminf_{\kappa\to 0+} \kappa \log Q^\kappa[O]
\geq - \inf_{x \in O} \big( E(x) - \Phi^0(x)\big).
\end{align*}

\item  
If $\Phi^0$ is continuous, the limit 
\begin{align}
\underset{\kappa\to 0+}{\lim} \, \kappa \log Q^\kappa[X] = - \underset{x \in X}{\inf} \, (E(x)-\Phi^0(x)) \; \in \; [-\infty,+\infty] 
\end{align}
exists. 
If the limit does not equal $-\infty$, 
then the \textnormal{(}well-defined\textnormal{)} probability measures 
\begin{align*}
\hat Q^\kappa := \frac{Q^\kappa}{Q^\kappa[X]} , \qquad \textnormal{for small enough } \kappa>0 ,
\end{align*}
satisfy an LDP with good rate function $J \colon X \to [0, \infty]$ given by
\begin{align}
J(x) := E(x) - \Phi^0(x) - \inf_{y \in X} \big( E(y) - \Phi^0(y) \big) , \qquad x \in X .
\end{align}
Moreover, if $Q^\kappa$ are probability measures, then $J(x) = E(x) - \Phi^0(x)$. 
\end{enumerate}

