[Theorem a1 of arXiv:2411.19926, 'Sparse Pseudospectral Shattering'] For any $\rho$, $M \in \mathbb C^{n\times n}$ satisfying
\begin{equation} 
    \frac{\left[\log(n)\log(2\|M\| + n)\right]^{3}}{n} \le \rho \le \frac{n^{1/2}}{n}
\end{equation}
we have
\begin{align}
    \Pr\pare{\kappa_V(M+N_g)\ge(2\left\|M\right\|+n)^{15K}}
    &\le O\pare{n^{-K}}  \\
    \Pr\pare{\eta(M+N_g)\le(2\left\|M\right\|+n)^{-15K}}
    &\le O\pare{n^{-K}},  
\end{align}
where $K=\lceil 3\log(n)/(2\log(n\rho))\rceil$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:Levy of arXiv:2606.11677, 'Feynman--Kac formula for the heat equation with a one-center point interaction in $d=3$.'] Let  $(\Omega,\mathcal{F},P)$ be a probability space and let $\{\mathcal{F}_{n,i};n\geq 1,i\geq 0\}$ be an array of sub-sigma fields $\mathcal{F}$ such that for each $n\geq 1$, and $i\geq 1$, $Z_{n,i}$ is $\mathcal{F}_{n,i}$-measurable and $\mathcal{F}_{n,i-1}\subset \mathcal{F}_{n,i}$. Let $\{Z_{n,i};n\geq 1,i\geq 1\}$ be an array of random variables on $(\Omega,\mathcal{F},P) $ with $Z_{n,i}\geq 0$ $P$-a.s. For a non-random sequence  $a_n>0$ with $\lim_{n\to \infty}a_n=\infty$ and $t\geq 0$, we define \begin{align*}
S_{n}(t)=\sum_{i=1}^{\lfloor a_n t\rfloor}Z_{n,i}.
\end{align*}
Let $\nu$ be a $\sigma$-finite measure on $(0,\infty)$ satisfying  $\int (1\wedge x)\nu(\text{\rm d} x)<\infty$, and let $\{S(t)\}_{t\geq 0}$ be the subordinator of Laplace exponent $\Phi(\theta)=\int_0^\infty (1-e^{-\theta x})\nu(\text{\rm d} x)$ $(\theta\geq 0)$. 

Suppose the following three conditions hold.
\begin{enumerate}[label=(\roman*)]
\item For any $t>0$, $x>0$ with $\nu(\{x\})=0$, \begin{align*}
\sum_{i=1}^{\lfloor a_n t\rfloor}P\left(\left.	Z_{n,i}>x	\right|\mathcal{F}_{n,i-1}\right)\to t\nu((x,\infty)),\quad \textrm{in probablity}.
\end{align*}
\item For any $t>0$, and $\delta>0$, \begin{align*}
\sum_{i=1}^{\lfloor a_n t\rfloor}P\left(\left.	Z_{n,i}>\delta	\right|\mathcal{F}_{n,i-1}\right)^2\to 0,\quad \textrm{in probablity}.
\end{align*}
\item For any $t>0$ and $\delta>0$, \begin{align*}
\lim_{a\to 0}\varlimsup_{n\to\infty}E\left(	\sum_{i=1}^{\lfloor a_n t\rfloor}Z_{n,i}1\{Z_{n,i}\leq a\}		\right)\to 0.
\end{align*} 

\end{enumerate}
 Then, $S_n$ weakly converges to $S$ under the Skorokhod topology. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:conditionalSurvival of arXiv:2608.13452, 'Wasserstein stability of the zero cell of a Poisson hyperplane tessellation under directio'] The conditional survival function of \(X\) given \(Y=y\) is given by 
    \begin{align*}
        \mathbb{P}\bigl[X \geq x \mid Y = y\bigr] 
        = g(x,y) :=
        \begin{cases}
            \frac{\partial_y F_u(x,y)}{F_u(0,1)} e^{- \gamma(F_u(x,y) - y F_u(0,1))}
            & \text{if $y'\mapsto F_u(x,y')$ is differentiable at $y$},
            \\0 & \text{otherwise}.
        \end{cases}
    \end{align*}
    In particular, this means that for any $x\geq 0$ and any Borel set $B\subset [0,\infty)$, we have
         \begin{align} 
              \mathbb{P}[X \geq x, Y \in B]
              & = \int_{B} g(x,y) \, \mathbb{P}_Y(\mathop{}\!\mathrm{d} y).
         \end{align}

