[Definition def:Minkowski integral of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] Let $\set{K_s}{s\in S}$ be a measurable family of convex bodies in $V$ indexed by a measurable space $S$. Let $\mu$ be a non negative measure on $S$ such that $\int_S \|K_s\|\,\mathrm{d} \mu(s)<\infty $ for one (and thus any) Euclidean structure on $V$. Then, the \emph{Minkowski integral} is the convex body $\int_S K_s \,\mathrm{d}\mu(s)$ whose support function is given for all $u\in V^*$ by:
  \begin{equation}
    h_{\int_S K_s \mathrm{d}\mu(s)}(u):=\int_S h_{K_s}(u) \,\mathrm{d}\mu(s).
  \end{equation}
  In the particular case where $\mu$ is a probability measure, we adopt the probabilistic notation. That is, if $K$ is a random convex body of $V$ with $\mathbb{E}\|K\|<\infty$, we write $\mathbb{E} K$ for the convex body with support function given for all $u\in V^*$ by:
  \begin{equation}
    h_{\mathbb{E} K}(u):=\mathbb{E} h_{K}(u) .
  \end{equation}

[Lemma 23 of arXiv:2506.20789, 'Central limit theory for Peaks-over-Threshold partial sums of long memory linear time seri'] Let $g=\log$. Then the assumptions of Lemma~\ref{lem:derand} hold in the settings of (i) Corollary~\ref{cor:heavy_det} and (ii) Corollary~\ref{cor:light_det}, respectively, with the following parameters:
  \begin{enumerate}[label=(\roman*)]
    \item In Corollary~\ref{cor:heavy_det}, $r_n=n^{1-1/(\nu\land 2)-d} u_n$,
\begin{align*}
    \xi(u_n)
    \ = \
    \frac{u_nf_{X_0}(u_n)}{\PP[X_0>u_n]}
    \ \to \
    \nu
    \,,
\end{align*}
and the joint limit is
    \begin{align*}
    (\Phi, \Psi)
    \ = \
    \left( \frac{\nu}{1+\nu}
    Z_{2\land\nu}, \ Z_{2\land\nu} \right)
    \,,
  \end{align*}
  with constant $c=1$ and $(\tau_n)$ any sequence satisfying \eqref{cond:tau:1} and \eqref{cond:tau:2}.
    \item In Corollary~\ref{cor:heavy_det}, $r_n=n^{1/2-d} u_n$,
\begin{align*}
    \xi(u_n)
    \ = \
    \frac{u_nf_{X_0}(u_n)}{\PP[X_0>u_n]}
    \ \sim \
   u_n^\beta
   \,,
\end{align*}
and the joint limit is $(\Phi, \Psi) = (Z_2, Z_2)$,
  with constant $c=1$ and $(\tau_n)$ any sequence
  satisfying \eqref{cond:tau:1} and \eqref{cond:tau:2}.
  \end{enumerate}

[Definition 184 (The Cartesian gradient of $\upxi$ and $|Z \SigmatTan|_g$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] \item 
	Given a type $\binom{m}{n}$ spacetime tensorfield $\upxi$, 
	we define its \emph{Cartesian gradient} 
	$\pmb{\partial} \upxi$ to be the type $\binom{m}{n+1}$ spacetime tensorfield with Cartesian components:
	\begin{align} 
		(\pmb{\partial} \upxi)_{\beta_1 \beta_2 \cdots \beta_{n+1}}^{\alpha_1 \cdots \alpha_m}
		& \eqdef
		\p_{\beta_1} \upxi_{\beta_2 \cdots \beta_{n+1}}^{\alpha_1 \cdots \alpha_m}.
	\end{align}
	\item Let $\SigmatTan$ be a $\Sigma_t$-tangent vectorfield and let $Z$ be a spacetime vectorfield.
	Relative to the Cartesian coordinates, 
	we define (see Remark~\ref{R:OMITTINGZEROCOMPONENTINCARTESIANCOORDINATES}) $|Z \SigmatTan|_g \geq 0$
	as follows:
	\begin{align} 
		|Z \SigmatTan|_g^2 
		& \eqdef g_{ab} (Z \SigmatTan^a) Z \SigmatTan^b,
	\end{align}
	where as usual $Z \SigmatTan^a = Z^{\alpha} \partial_{\alpha} \SigmatTan^a$.

[Theorem 10 (Exact shape-constrained frontiers) of arXiv:2608.21496, '2608.21496'] For integers $N>m\ge1$:
\begin{enumerate}[label=(\roman*)]
\item For monotone reliability,
\begin{equation}
\Delta^{\uparrow}_{m,N}
=2\inf_{p\in\cP_m}\|u^N-p(u)\|_\infty.

\end{equation}
Thus the worst monotone worlds may be chosen as step functions, and the exact validation problem is uniform monomial approximation rather than the unrestricted $L^1$ problem.
\item For every $0<L<\infty$, monotone $L$-Lipschitz reliability has the exact finite dual
\begin{equation}
\Delta^{\uparrow,L}_{m,N}
=\inf_{a\in\mathbb R^m}\{H_L(z_a)+H_L(-z_a)\}.

\end{equation}
Evaluation therefore reduces to the $m$ audit coefficients and the scalar threshold in Eq.~\ref{eq:cappedthreshold}.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prp Uno of arXiv:2608.10215, 'The variance of the Pitman--Yor process: a Cifarelli--Regazzini identity and inversion for'] Let $\alpha \in (0,1)$ and $\theta >0$ be fixed. Consider a pair of linear functionals
\[ 
\mathfrak{L}_1 := \int_{\mathbb{R}} \varphi \mathrm{d}\widetilde{\mathfrak{p}} \qquad \text{and} \qquad \mathfrak{L}_2 := \int_{\mathbb{R}} \psi \mathrm{d}\widetilde{\mathfrak{p}} 
\]
where $\varphi, \psi : \mathbb{R} \to \mathbb{R}$ are two measurable functions satisfying $\Vert{}\varphi\Vert{}_\infty \le 1$ and $\Vert{}\psi\Vert{}_\infty \le 1$.
Then, for any fixed probability measure $\mathsf{G}$ on $(\mathbb{R}, \mathscr{B}(\mathbb{R}))$, the joint moments of $(\mathfrak{L}_1, \mathfrak{L}_2)$ are given by:
\begin{align}
\mathbb{E}_{(\alpha, \theta)}[ \mathfrak{L}_1^n \mathfrak{L}_2^m]  &= \frac{m!}{(n+m)!} \frac{1}{(\theta)_{n+m}} \frac{\partial^{n+m}}{\partial z^n \partial w^m} 
\left[ \left( \int_{\mathbb{R}} \{1 - z [\varphi(x) + w \psi(x)]\}^\alpha \mathsf{G}(\mathrm{d} x) \right)^{-\theta/\alpha} \right]_{z=w=0} \\
&= \frac{1}{(\theta)_{n+m}} \frac{\partial^{n+m}}{\partial u^n \partial v^m} \left[ \left(  \int_{\mathbb{R}} [1 - u \varphi(x) - v \psi(x)]^\alpha \mathsf{G}(\mathrm{d} x) \right)^{-\theta/\alpha} 
\right]_{u = v =0}\ .
\end{align}
Consequently, identity (equation eq:joint_mom_linear2 of the paper) yields the joint Stieltjes transform:
\begin{equation} 
\mathbb{E}_{(\alpha, \theta)}\left[ \left(\frac{1}{1 + s\mathfrak{L}_1 + t\mathfrak{L}_2}\right)^{\theta} \right] = 
\left\{ \int_{\mathbb{R}} [1 + s \varphi(x) + t\psi(x)]^{\alpha} \mathsf{G}(\mathrm{d} x) \right\}^{-\theta/\alpha} 
\end{equation}
valid for all $\vert{}s\vert{} < 1/2$ and $\vert{}t\vert{} < 1/2$. Furthermore, if $\varphi$ and $\psi$ are non-negative and satisfy the integrability condition 
$\int_{\mathbb{R}} [\varphi(x)^{\alpha} + \psi(x)^{\alpha}] \mathsf{G}(\mathrm{d} x) < +\infty$, the validity of (equation eq:alpha-CR-double of the paper) extends to any $s, t > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

