[Lemma 4 of arXiv:2609.03187, 'Duality for a Martingale Transport Problem with Moment Constraints'] For every $\lambda \in \mathbb R^N$ the function $\Psi_\lambda(a)$ is finite, convex, and continuously differentiable on $\mathbb R$, with
\begin{equation}
\Psi_\lambda'(a)=\int T_\lambda(a+z)\,\gamma(dz),\qquad a\in\mathbb R.
\end{equation}
Moreover, the following estimate holds:
\begin{equation}
|\Psi_\lambda'(a)-a|\le L_\lambda, \qquad a\in\mathbb R.
\end{equation}
In addition, for every $x\in\mathbb R$, the function $a\longmapsto ax - \Psi_\lambda(a)$ attains its maximum at $\mathbb R$.

[Lemma lem:control-sixth of arXiv:2608.26765, 'Beyond Client Averaging: A Client-Independent Second-Order Stationary-Bias Component in St'] There exist $\gamma_{0,H}^{(C6)}>0$ and $C_{\xi,6,H}<\infty$, independent of $N$ and $\gamma$, such that for $0<\gamma\le\gamma_{0,H}^{(C6)}$,
\begin{equation}

  \frac1N\sum_{c=1}^N\mathbb{E}|\xi_c|^6\le C_{\xi,6,H}.
\end{equation}
Consequently, the client-averaged second and fourth control moments are uniformly bounded as well.

[Lem 8 of arXiv:2604.06122, 'REM universality for linear random energy'] We have 
 \been{

 g(0)=g'(0)=0,\quad g''(0)=1-m^2.
 }
 For  any $\lambda\in \mathbb{R}$
\been{

0\leq g(\lambda )\leq 2|\lambda|,\quad 0\leq \sign(\lambda)g'(\lambda )\leq 2, \quad g''(\lambda )\in (0,1).
}
and
\been{

g''(\lambda)\geq (1-m^2)e^{-2|\lambda|}
}
Moreover, for any $\lambda,\,\lambda'\in \R$
\been{

|g''(\lambda )-g''(\lambda')|\leq 2 |\lambda-\lambda'|.
}
Finally, given $h_1\in \R$ and $\lambda\in \R$
\been{

g(\lambda h_1)\leq \log\(\frac{1+\sign(h_1)m}{2}\)+\frac{1-\sign(h_1)m}{1+\sign(h_1)m}e^{-2\lambda|h_1|}+\lambda(|h_1|-m h_1)
}

