[Theorem T:graph main of arXiv:2507.01236, 'Disintegration theorem for multifunctions, \\ with applications to empirical Wasserstein d'] Suppose that~$\mu$ has density~$f$ with respect to uniform probability on~$\mathfrak{X}$ such that
\begin{equation}

c \leq f(x) \leq C\mbox{\rm \ for every $x \in \mathfrak{X}$},
\end{equation}
where $0 < c \leq C < \infty$. 
Given $\alpha \in (0, \infty)$, let
\begin{equation}

r(n)\equiv r(n,c, \alpha) := 4 c^{-1} \sqrt{(2 + \alpha) \frac{\ln n}{n}}.
\end{equation}
Then there is $n_0\equiv n_0(c,C,\alpha)$ such that $n\geq n_0$ implies that $(\mathfrak{X},d,\mu)$ is $([|E| (|E| - 1)]^{|E| - 1} n^{ - \alpha},r(n))$-disintegrable (with $0^0$ interpreted as $1$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 8 (Well-posedness and Stability of McKean-Vlasov SDEs) of arXiv:2506.13587, 'Non-exchangeable mean-field theory for adaptive weights: propagation of dissociatedness an'] Consider the SDE system \eqref{eqn:main_McKean_Vlasov} with coefficients satisfying Assumption~\ref{assu:coefficients}.
    Assume that the initial data $(\overline{\mathsf{X}}_0, \overline{\mathsf{W}}_0)$ defined on the probability space $(\Omega, \mathcal{A}, \pi)$ satisfies Assumption~\ref{assu:initial_data}.
    Let $(\overline{\mathsf{B}}(t))_{t \in [0,T]}$ be the canonical Brownian motion defined on the filtered probability space $(\widehat{\Omega}, \widehat{\mathcal{F}}, (\widehat{\mathcal{F}}_t)_{t \ge 0}, \widehat{\pi})$.

    Then, there exists a unique (in the almost sure sense) pair of stochastic processes
    \begin{equation*}
        (\overline{\mathsf{X}}_{\xi,\widehat{\xi}}(t))_{(\xi,\widehat{\xi}) \in \Omega \times \widehat{\Omega}, t \in [0,T]} \quad \text{and} \quad (\overline{\mathsf{W}}_{(\xi,\widehat{\xi}),(\zeta,\widehat{\zeta})}(t))_{(\xi,\widehat{\xi}),(\zeta,\widehat{\zeta}) \in (\Omega \times \widehat{\Omega})^2, t \in [0,T]}
    \end{equation*}
    satisfying the integral equations corresponding to \eqref{eqn:main_McKean_Vlasov} almost surely on $[0,T]$, with the following properties:
    \begin{itemize}
        \item Adaptedness: The process $\overline{\mathsf{X}}(t)$ is measurable with respect to $\mathcal{A} \otimes \widehat{\mathcal{F}}_t$, and the process $\overline{\mathsf{W}}(t)$ is measurable with respect to the product filtration $(\mathcal{A} \otimes \widehat{\mathcal{F}}_t)^{\otimes 2}$.

        \item Moment Control: For some constant $C_T > 0$ depending on $T$ and the bounds in Assumptions~\ref{assu:coefficients} and \ref{assu:initial_data}, the following holds for all $t \in [0,T]$:
        \begin{equation*}
            \|\overline{\mathsf{X}}(t)\|_{L^2(\Omega \times \widehat{\Omega})} < C_T \quad \text{and} \quad \|\overline{\mathsf{W}}(t)\|_{L^\infty((\Omega \times \widehat{\Omega})^2)} < C_T.
        \end{equation*}

        \item Path Regularity: The solutions have continuous sample paths almost surely.
    \end{itemize}

Furthermore, consider two sets of initial data $(\overline{\mathsf{X}}^{(k)}_0, \overline{\mathsf{W}}^{(k)}_0)$ ($k=1,2$) satisfying Assumption~\ref{assu:initial_data}.
If they are defined on the same latent space $\Omega$, then for any $t \in [0,T]$, the following estimate holds:
\begin{equation*}
\begin{aligned}
&\|\overline{\mathsf{X}}^{(1)}(t) - \overline{\mathsf{X}}^{(2)}(t)\|_{L^1(\Omega \times \widehat{\Omega})} + \|\overline{\mathsf{W}}^{(1)}(t) - \overline{\mathsf{W}}^{(2)}(t)\|_{\square(\Omega \times \widehat{\Omega})}
\\
& \quad \leq C(t) \big( \|\overline{\mathsf{X}}^{(1)}_0 - \overline{\mathsf{X}}^{(2)}_0\|_{L^1(\Omega)} + \|\overline{\mathsf{W}}^{(1)}_0 - \overline{\mathsf{W}}^{(2)}_0\|_{\square(\Omega)} \big).
\end{aligned}
\end{equation*}
Here, $C(t) > 0$ is a constant depending on time, dimension, and the bounds in Assumptions~\ref{assu:coefficients} and \ref{assu:initial_data}.
For general initial data (not necessarily defined on the same space), we have the stability in the unlabeled distance:
\begin{equation*}
\begin{aligned}
&\delta_{W_1,\square} \big( ( \overline{\mathsf{X}}^{(1)}(t), \overline{\mathsf{W}}^{(1)}(t) ) , ( \overline{\mathsf{X}}^{(2)}(t), \overline{\mathsf{W}}^{(2)}(t) ) \big)
 \leq C(t) \delta_{W_1,\square} \big( ( \overline{\mathsf{X}}^{(1)}_0, \overline{\mathsf{W}}^{(1)}_0 ) , ( \overline{\mathsf{X}}^{(2)}_0, \overline{\mathsf{W}}^{(2)}_0 ) \big).
\end{aligned}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm of arXiv:2609.00884, 'The weakness of typicality'] \label[theorem]{thm:p1-degrees-bounding}
Assume that our notion of smallness is tail-trivial.
A $\Pi^1_2$-problem $\mathsf{P}$ has property \textup{P}${}_1$ if and only if the class of $A$'s that are  $\mathsf{P}$-bounding is small.

[Proposition 16 of arXiv:2609.03248, 'Connections between colored restricted $b$-ary and ordinary partitions'] Let $b\geq 2$ and $\rho\geq 1$ be integers, and let $Z$ and $C_b^\rho(n;Z)$ be 
as in Definition~\ref{def:5.1}. Then $C_b^\rho(0;Z)=1$, and for integers 
$n\geq 0$ we have
\begin{equation}
C_b^\rho(bn+j;Z)
= \sum_{k=0}^n Y_{bk+j}(Z)C_b^\rho(n-k;Z) \qquad (j=0, 1,\ldots b-1),
\end{equation}
where the sequence of coefficients $Y_n(Z)$ is defined by the generating 
function
\begin{equation}
\sum_{n=0}^\infty Y_n(Z)q^n = \prod_{i=1}^\rho
\left(1+z_{i,1}q+z_{i,2}q^2+z_{i,3}q^3+\dots\right).
\end{equation}

[Defn 2 of arXiv:2609.02342, '2609.02342'] Let \(X\) be a Banach space. A one-parameter family
	\((T_t)_{t\geq0}\) is called a
	\emph{strongly continuous semigroup}, or a \(C_0\)-semigroup, on \(X\) if the
	following conditions hold:
	\begin{enumerate}
		\renewcommand{\labelenumi}{\textnormal{(\roman{enumi})}}
		\item \(T_0=I\);
		\item \(T_{t+s}=T_tT_s\) for all \(s,t\geq0\);
		\item $
		\lim_{s\to t}\|T_sx-T_tx\|=0 $
		for every \(x\in X\) and every \(t\geq0\).
	\end{enumerate}

[Corollary 15 (Convexity estimate) of arXiv:2608.25971, 'Positive \texorpdfstring{$\tau$}{tau}-bi-Ricci curvature and Mean curvature flow with surg'] For every $\varepsilon>0$ there exists
$C_\varepsilon=C(n,\alpha,\varepsilon)>0$ such that
\begin{equation}
 \lambda_1\geq-\varepsilon H-C_\varepsilon R^{-1}
\end{equation}
at every point of the smooth flow.

