[Corollary 34 of arXiv:2607.18201, 'Finding Adam in noisy trees'] For any $\alpha_2>\alpha$, we can couple the subtrees $\{\rF_n(\alpha)(v;E_v):v\in M(n^{\alpha_2})\}$ with a sequence of trees $\{\mathrm{T}(v):v\in M(n^{\alpha_2})\}$, where given $M(n^{\alpha_2})$, $\{\mathrm{T}(v):v\in M(n^{\alpha_2})\}$ is an i.i.d.\ collection of a Bienaym\' e--Galton--Watson trees with offspring distribution $\xi_{n^{\alpha_2}}$, and such that
    \begin{align*}
        \rF_n(\alpha)(v;E_v)\subseteq \mathrm{T}(v),\textrm{ for all }v\in M(n^{\alpha_2}).
    \end{align*}

[Lemma 4 of arXiv:2608.27054, 'GLOBAL WELL-POSEDNESS FOR THE 2D STOCHASTIC HYPOVISCOUS NAVIER-STOKES EQUATIONS'] Let $\gam>\half$, $s\in [\gam, 2\gam)$ and suppose that Assumption \ref{ass:X0X1_g} holds. For 
        \begin{equation*}
        |s-1|<\frac dq< 4\gam-s-1\quad \text{ and }\quad \beta: = \frac{1}{4\gam}\big(\frac{d}{q}+s+1\big)\in (\tfrac 12,1),
    \end{equation*}
    and $F$ and $G$ as in \eqref{eq:abstract_eq}, it holds that 
    \begin{align*}
        \|F(u)-F(v)&\|_{X_0}+\|G(u)-G(v)\|_{\gam(\ell^2; X_\half)}\\
       &\; \lesssim \big(1+ \|u\|_{X_\beta}+ \|v\|_{X_\beta}\big)\|u-v\|_{X_\beta},
    \end{align*}
    for all $u,v\in X_1$.

