[Corollary corr: superdiffusive a.s. conv eg 1 of arXiv:2505.05921, 'Limit Theorems for step reinforced random walks\\ with regularly varying memory'] {}
    Let $\{S_n\}_{n\geq 0}$ be the SRRW-RVM with zero mean, unit variance innovation sequence $\{\xi_n\}$. Then for $p=p_c$ and $\{\mu_n\}$ satisfying Assumption~(eg 1 of the paper) with $\alpha+\gamma+1<0$,    
    \[\left(\sqrt{{\ell_n^{{1}/{(\gamma+1)}}}} \frac{S_{\lfloor nt\rfloor}}{\sqrt{n}}: t\geq 0\right) \to \left(\sqrt{t}K_{\infty} : t\geq 0\right), \quad \text{almost surely and in $L^2$ in $D([0,\infty))$,}
    \]
     where $K_{\infty}$ is a nonrandom multiple (possibly depending on $\{\mu_n\}$) of $M_\infty$, the almost sure and $L^2$ limit of $M_n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 3 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Suppose that \cref{mainassump} is satisfied. 
  We regard $F_n,\;n\in\N,$ and $F$ as subsets of a common $\bcm$ space $(M,d^M)$.
  Let $x\in F$ and $x_n\in F_n$. Take $r_{\infty}\ge r_0$ satisfying 
  $x\in B(\rho,r_{\infty})$ and $x_n\in B(\rho_n,r_{\infty})$.
  Then there exist a constant $E=E(s,\theta,\kappa)$ and a polynomial $C_n(r)=C_n(\mu_n(F_n^{(r)}),\mu(F^{(r)}),\diam F^{(r)}\cup F_n^{(r)},\diam F^{(r)})$ (see \cref{noncpt} for explicit formulae),
  and it holds for any $f:M\to\R,\;\kappa\in [1/2,1],$ and $t>0$ that
  \begin{equation}
    \begin{aligned}
   \MoveEqLeft \Big|E_{x}[f(X_t)]-E^n_{x_n}[f(X^n_t)]\Big|\\
    \lesssim&\|f\|_{\BL^{\kappa}(M,d^M)}
    \inf\left\{\Psi_1(n,r)+C_n(r)\Psi_2(n,r)^E : r\ge r_{\infty}, \Psi_2(n,r)\le \frac{1}{2}\right\},  
    \end{aligned}
  \end{equation}
  where
  \begin{equation*}
    \Psi_1(n,r)=P_{x}(\sigma_{B(\rho,r)^c}\le t)\vee P_{x_n}^n(\sigma^n_{B(\rho_n,r)^c}\le t),
  \end{equation*}
  \begin{equation*}
    \Psi_2(n,r)=d_{\rm{H}}^M(F^{(r)},F_n^{(r)})^{\kappa}+d_{\BL^{\kappa}}^M(\mu^{(r)},\mu^{(r)}_n)+d^M(x,x_n),
  \end{equation*}
  Moreover, the time-dependence of the constant in $\lesssim$ is $t^{-[\kappa-\frac{s}{2(1+s)\theta}(2\kappa-1)]},\;t\in (0,1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2 (Exactly when the budgeted allocation is settled) of arXiv:2608.29560, 'Which LLM for Which Work?\\Budgeted Model Allocation under Uncertain Evaluation'] Let $\hat x$ be budget-feasible and optimal at $\hat\mu$. Then $\hat x$ is settled over
$\mathcal U$ if and only if every budget-feasible $x$ satisfies
\begin{equation}
  \underbrace{\sum_{j:\,x(j)\neq\hat x(j)} w_j\bigl(\hat\mu_{\hat x(j),j}-\hat\mu_{x(j),j}\bigr)}_{\text{margin of }\hat x\text{ over }x}
  \;\ge\;
  \underbrace{\sum_{j:\,x(j)\neq\hat x(j)} w_j\bigl(e_{\hat x(j),j}+e_{x(j),j}\bigr)}_{\text{uncertainty where they differ}},
\end{equation}
and equivalently if and only if $\hat x$ remains optimal at the adverse table $\check\mu$
defined in \eqref{eq:adverse}, that is, $\hat x\in X^\star[\check\mu]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma thm:OdeltaRW of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] The error $\delta^M_{[\ell-\eta_\ell,\ell]}$ in the scaling bound (equation def:scalimRW of the paper) in bounded range $\rho_\ell$, satisfies
\begin{equation} 
\delta_{[\ell-\eta_\ell,\ell]}^M=
\delta_{[\ell-\eta_\ell,\ell]}^{\mathbb{R}^n}
+ \mathrm{O}\left( \frac{\ell}{\eta_\ell}\delta^M_{[0,\ell]}\right),
\end{equation}
as $\ell\to +\infty$, for all $\alpha\in [0,1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm|forComputer of arXiv:2504.08938, 'Fourier Levels and Almost Sure Bounds on Higher-Order Derivatives in First-Passage Percola'] The following two propositions hold for every $\omega\in\Omega$.
\begin{enumerate}
\item[(a)] If $\sigma_j^a(\omega)\in E_j^C$, then $f(\sigma_j^b(\omega))=f(\sigma_j^a(\omega))$;
\item[(b)] If $\sigma_j^b(\omega)\in \hat E_j$, then $f(\sigma_j^b(\omega))=f(\sigma_j^a(\omega))+(b-a)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

