[Lemma lem:mixing of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] Let $\Lambda^*$ and $\eta,\gamma > 0$ be, respectively, the set and constants given in
Proposition (prop:goodset of the paper).
Suppose $x \in \Lambda^*$ and $x' \in \Omega$ with $\mathbf{d}_\mathrm{Ham}(x,x') = 1$.
Under the monotone coupling of the $\mu_\mathsf{H}^\eta(n,p)$ Glauber dynamics, for all $t \leq e^{\gamma n}$,
\begin{equation}
    \mathbb{E}\mleft[\mathbf{d}_\mathrm{Ham}(X_t^x,X_t^{x'})\mright] \leq \mleft(1-\frac{\kappa}{n^2}\mright)^t + e^{-\Omega(n)}.
\end{equation}
In particular, for all $t \geq n^3$,
\begin{equation}
    \mathbb{P}\mleft[X_t^x \neq X_t^{x'}\mright] \leq e^{-\Omega(n)}.
\end{equation}
Moreover, for any $z \in \Lambda^*$ and $t \geq n^3$, we have
\begin{equation}
    \mathbf{d}_\mathrm{TV}(X_t^z, X) \leq e^{-\Omega(n)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition uniform_bound_on_intersection_numbers of arXiv:2506.02611, '\textbf{The tight length spectrum of large-genus random hyperbolic surfaces with many cusp'] For any $g \ge 2$ and $p_1,\cdots,p_k,q_1,\cdots,q_r \ge 1$ such that $|\mathbf{p}|+|\mathbf{q}|  \le 3g-3$, we have 
\begin{align}
    \frac{\langle \tau_{q_1+1}\dots \tau_{q_r+1}\tau_{p_1+1}\dots\tau_{p_k+1}\tau_{2}^{3g-3 - |\mathbf{p}|-|\mathbf{q}|}\rangle_{g}}{(3g-3-|\mathbf{p}|-|\mathbf{q}|)!} &\le  \frac{\langle\tau_{p_1}\dots\tau_{p_k}\tau_{2}^{3g-3 - |\mathbf{p}|}\rangle_{g}}{(3g-3-|\mathbf{p}|)!}\cdot \frac{ 3^{|\mathbf{q}|}(15g)^r}{\displaystyle \prod_{i=1}^{r}(2q_i+3)!!}.
\end{align}

[Proposition 9 (Overshoot bound) of arXiv:2604.23133, 'High-Precision Framework for Expected Hitting Times Analysis in the Dice-Sum Process'] Assume the setup and notation of Proposition~\ref{prop:square_cutoff}, and let $K = \sqrt{N} \in \mathbb{N}$.  
Define
\begin{align*}
L_N &:= \frac{1}{6}\sum_{j=0}^{\infty}
\Bigl((K+1+j)^2 - K^2 - 5\Bigr)\,
\Bigl(\tfrac{5}{7}-\varepsilon_N\Bigr)^j
\Bigl(\tfrac{2}{7}-\varepsilon_N\Bigr), \\[4pt]
U_N &:= \sum_{j=0}^{\infty}
\Bigl((K+1+j)^2 - K^2 - 1\Bigr)\,
\Bigl(\tfrac{5}{7}+\varepsilon_N\Bigr)^j
\Bigl(\tfrac{2}{7}+\varepsilon_N\Bigr).
\end{align*}
Then, for all $K \ge 4$ and every $s \in \{0,1,\dots,N\}$,
\begin{equation}
L_N \;<\; \mathbb{E}_s\!\bigl[T-\omega_N \,\big|\, A_N\bigr]
 \;<\; U_N.
\end{equation}

[Proposition 10 of arXiv:2606.15842, 'A small noise approximation for Muller's Ratchet'] Recall all notions from Definition~\ref{def:F}, and $S$, the semigroup generated by $G^{(1)}$, from Corollary~\ref{cor2.4}. For $x \in \mathbb S_{\chi}$, let $X$ be the solution of the $(\mathbb S_{\chi}, \delta_x, G, \mathcal F)$ martingale problem from Proposition~\ref{martprob}. In addition, let 
    \begin{align}
    \mathcal D & := \text{algebra generated by } \bigcup_{{\zeta} \geq 0} \bigcup_{m=0}^\infty \mathcal D^m_{\zeta}, \\ 
    \mathcal D^m_{\zeta} & := \left\{ f_{\xi{, \zeta}} := \frac{h_{ \xi_1} \cdots h_{ \xi_m}}{g_{\alpha {\zeta}}^m}
    : h_{\xi_i} = g_{\xi_i} \text{ or }h_{\xi_i} = \frac{\partial}{\partial \xi_i} g_{\xi_i},  
    \xi \in \mathbb R_+^m
    \right\} \subseteq \mathcal C^2(\mathbb S)
    \end{align}
    and define $G = G^{(1)} + G^{(2)}$ on $\mathcal D$ as in \eqref{eq:G1} and \eqref{eq:G2}. Then, $X$ solves the local $(\mathbb S_{\chi}, \delta_x, G, \mathcal D)$ martingale problem. Moreover, for $\xi, \eta, \tau \geq 0$, 
    \begin{enumerate}
        \item It holds
        $$ g_{ \xi} g_{ \eta} \in \mathcal D_0^2, \qquad S_t (g_{ \xi} g_{ \eta}) \in \mathcal D_t^2, \qquad G^{(1)}S_t(g_{ \xi} g_{ \eta})\in\mathcal D_t^4, \qquad G^{(2)}S_t(g_{ \xi} g_{ \eta})\in\mathcal D_t^4.$$
    \item There is $C>0$ (not depending on $\nu$) such that for all $t \in [0,\tau]$
    $$ |S_t (g_{ \xi} g_{ \eta})(x)| + |G^{(1)} S_t (g_{ \xi} g_{ \eta})(x)| + \nu |G^{(2)} S_t (g_{ \xi} g_{ \eta})(x)| \leq C \exp\Big( 4 \alpha \tau m_1(x)\Big). $$
    \item It holds
    \begin{align*}
    & f_{t, \xi, \eta} := \nu G^{(2)}S_t (g_{ \xi} g_{ \eta}) \in \mathcal D_t^4, \qquad S_s f_{t, \xi, \eta} \in \mathcal D_{s+t}^a, \\ & G^{(1)} S_s f_{t, \xi, \eta} \in \mathcal D_{s+t}^{a_1}, \qquad G^{(2)} S_s f_{t, \xi, \eta} \in \mathcal D_{s+t}^{a_2}   
    \end{align*}
    with $a, a_1, a_2$ from Corollary~\ref{cor2.4}.
    \item There is $C>0$ (not depending on $\nu$) such that for all $s, t \in [0,\tau]$ with $s+t \in [0, \tau]$
    $$ |S_s f_{t, \xi, \eta}(x)| + |G^{(1)} S_s f_{t, \xi, \eta}(x)| + \nu |G^{(2)} S_s f_{t, \xi, \eta}(x)| \!\leq\! C \exp\Big( \max(a, a_1, a_2) \alpha \tau m_1(x)\Big). $$
\end{enumerate}

