body:
[Proposition 26 of arXiv:2606.09121, 'Truncated Signature Information for Mixed Fractional Brownian Paths'] For $n\ge1$ and $\alpha>0$, define
\begin{equation}
    \kappa_n(\alpha)
    :=\frac1n\sum_{k=0}^{n-1}
    \left[
        \frac12\left(
        \left(1-\frac{k}{n}\right)^\alpha
        +\left(1-\frac{k+1}{n}\right)^\alpha
        \right)
        -\frac16 n^{-\alpha}
    \right].
\end{equation}
Then
\begin{equation}
    \kappa_n(\alpha)
    =\frac{1}{2n}
     +\frac{1}{n^{\alpha+1}}\sum_{m=1}^{n-1}m^\alpha
     -\frac{1}{6n^\alpha},
\end{equation}
and $\kappa_n(\alpha)>0$.  Moreover, with
\[
    R_\theta^{(n)}(h)
    :=2\E_\theta\!\left[\pi_{122}S(Z_{t,h}^{(n)})\right],
\]
the quantity $R_\theta^{(n)}(h)$ is independent of $t$, and one has the exact representation
\begin{equation}
    R_\theta^{(n)}(h)
    =\sum_{r=1}^K v_r\kappa_n(\alpha_r)h^{\alpha_r}.
\end{equation}
For every $0<a\le b<\infty$,
\begin{equation}
    \sup_{\alpha\in[a,b]}
    \left|\kappa_n(\alpha)-\frac{1}{\alpha+1}\right|
    \le \frac{1}{2n}+\frac{1}{6n^a},
\end{equation}
and consequently
\begin{equation}
    \kappa_n(\alpha)\longrightarrow \frac{1}{\alpha+1}
\end{equation}
uniformly on compact subsets of $(0,\infty)$.

[Theorem 7 (Deterministic nonlinear reservoir kernel) of arXiv:2608.20998, 'Free-Probability Kernels for Zero-Rollout Hyperparameter Selection in Reservoir Computing'] Let $\psi\in C_b^1(\mathbb R)$. For fixed $L,t,s$ and a deterministic
bounded input sequence,
\begin{equation}
K_{\psi,n,\theta}^{(L)}(t,s)
\xrightarrow{\mathbb P}
K_{\psi,\theta}^{(L)}(t,s)
\qquad (n\to\infty).

\end{equation}
The convergence is with respect to the joint randomness of
$W_r^{(n)}$ and $W_{\rm in}^{(n)}$.

