[Proposition 35 (Bernoulli percolation on extremal URGs) of arXiv:2504.02435, 'Poisson-Voronoi percolation in higher rank'] Let $(G,\rho)$ be an extremal unimodular random graph and let $G[p]$ denote the configuration of $p$-Bernoulli percolation on $(G,\rho)$. Then the following hold:
\begin{itemize}
\item[{\rm(1)}] The number of infinite clusters in $G[p]$ is almost surely constant and $0$, $1$ or $\infty$.
\item[{\rm(2)}] There exists a constant $p_c$ such that for any $p>p_c$, $G[p]$ has an infinite cluster almost surely, while for any $p<p_c$, there is almost surely no infinite cluster.
\item[{\rm(3)}] There exists a constant $p_u$ such that for any $p>p_u$, $G[p]$ has a unique infinite cluster almost surely, while for any $p<p_u$, there is almost surely not a unique infinite cluster.
\end{itemize}

[Corollary 18 of arXiv:2605.13512, '2605.13512'] For any $x \in \bR, t \in \R_+$, there exist deterministic $r_L(x,t) < 0 < r_{U}(x,t)$ so that almost surely
\begin{equation}
    v(x,t) =\lim_{n \to \infty}n^{-1}z^{n}_{\fl{nx}}(nt) = \max_{q \in [r_L, r_U]} \left\{v_{0}(q) - g^{q}(x-q,t) \right\} = \sup_{q \in \mathbb{R}} \left\{v_{0}(q) - g^{q}(x-q,t) \right\}.
\end{equation}

[Thm offdiagflucsameside of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] [Off-diagonal two-point fluctuations]  
Fix $a,b > 0$ and $\ell> \bar{\mathcal{L}}(a,b)$. 
Let the function $h(x,y)$ and the positive numbers $\mathrm m$, $\mathsf{\sigma}$, and $\mathsf{c}_{\pm}$ be as defined in Theorems (thm:LLN of the paper) and (thm:diagfluc of the paper). 
Then, for two distinct points $(x_1, y_1), (x_2, y_2)\in (0,1)^2$ and two real numbers $\mathrm r_1, \mathrm r_2\in {\mathbb R}$, 
\begin{equation*}
\begin{split}
    &\lim_{N \to \infty} \mathbb{P} \left[\frac{\mathcal L(x_iaN, y_ibN) - h(x_i,y_i)N}{\sqrt{2} \mathsf{\sigma}   N^{1/2}} > \mathrm r_i, \ i=1, 2 \bigg| \mathcal{L}(aN, bN)= \ell N \right] \\ 
    &\qquad  \quad 
    = \begin{dcases}  \mathbb{P} \left[ \mathsf{c}_{+} \mathbb{B}^{\mathrm{br}}\left(\frac{\mathrm m y_i- x_i}{\mathrm m -1} \right) > \mathrm r_i,  i=1,2 \right] 
    \qquad &\text{if $\frac{1}{\mathrm m} < \frac{y_1}{x_1}, \frac{y_2}{x_2} < 1$,} \\
    \mathbb{P} \left[ \mathsf{c}_{-} \mathbb{B}^{\mathrm{br}}\left(\frac{\mathrm m x_i- y_i}{\mathrm m -1} \right) > \mathrm r_i,  i=1,2 \right]
\qquad &\text{if $1 < \frac{y_1}{x_1}, \frac{y_2}{x_2} < \mathrm m$,}
    \end{dcases}
\end{split} \end{equation*}
where $\mathbb{B}^{\mathrm{br}}$ is a standard Brownian bridge, and $\mathrm m$ is the constant defined in (equation eq:critical_slope of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2606.14038, 'Trivariate Hypergeometric Series Formulas\\ for Pure Partition Functions of Multiple $3$-S'] [Square Rule]
   For any $\u n=(n_1,n_2,n_3)\in \N_0^3$ and distinct $j, k\in [3]$,  $E_{\u n}(\begin{smallmatrix}
  + & + \\ j & k
\end{smallmatrix} ) $ and $E_{\u n+e_j}(\begin{smallmatrix}
  - & + \\ j & k
\end{smallmatrix} ) $ together imply $E_{\u n+e_k}(\begin{smallmatrix}
  + & - \\ j & k
\end{smallmatrix} ) $ and $E_{\u n+e_j+e_k}(\begin{smallmatrix}
  - & - \\ j & k
\end{smallmatrix} ) $.

