 +  h^2 \sum_{1 \leqslant i < j  \leqslant d} \partial_{ij}f(x) \sum_{s\in \mathcal S} a(s)  s_is_j +  \frac{h^2}{2}  \sum_{i=1}^d
\left( \sum_{s\in \mathcal{S}} a(s) s_i^2 \right) \partial_{ii} f(x) + o(h^2). \end{multline*}
Using the assumptions (equation sum_s of the paper) and  (equation sum_sisj of the paper), we finally obtain that 
\begin{equation*}
    \sum_{s \in \mathcal S} a(s) f(x +hs) -f(x)  = \frac{h^2}{2} \Delta f(x) + ...","release_manifest_digest":"sha256:22b23959cb54aa9a0c789a2a937e962e1e0e4af4b6b877b782cdc61c7cf604cf","revision_digest":"sha256:838aff04cb808386c8a523ed9b13be4e62d0c09f33472a9ee41cb71616bc31d1","source_id":"arxiv:2505.19622","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

