body:
[Lemma 12 of arXiv:2605.20115, 'Moment bounds on correctors for the degenerate random conductance model'] There exist $C=C_d>1$ and a stationary $\frac 1{8}$-Lipschitz random field $\rd\ge 2$ such that:
    \begin{itemize}
        \item For all $x\in\ZZ^d$ and $R\ge r_\diamond(x)$,
            \begin{gather}
                \Big(\fint_{\BB_R(x)}a_e^{d+1}\Big)^{\frac1{d+1}} \le C\expec{a^{d+1}}^{\frac1{d+1}};\quad
\Big(\fint_{\BB_R(x)}a_e^{-(d+1)}\Big)^{\frac1{d+1}}\le C\expec{a^{-(d+1)}}^{\frac1{d+1}}.
            \end{gather}
            \item   $\rd$ satisfies the following moment bound: there exists $c_0>0$ such that
            \begin{equation}
		\expec{r_\di^{c_0\gamma}}^{\frac1\gamma}\lesssim  \gamma^{\frac1{d+1}}\Gamma^{2}.
            \end{equation}
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm DiffusionSBP of arXiv:2411.13765, 'Schr\"odinger Bridge Problem for Jump Diffusions'] Under the setting above, there exists a unique 
(up to scaling) pair of non-negative functions $(\varphi,\hat\varphi)$ on $[0,T]\times\mathbb{R}^n$ such that $(\varphi(0,\cdot),\hat\varphi(0,\cdot),\varphi(T,\cdot),\hat\varphi(T,\cdot))$ solves the Schr\"odinger system (equation phiphihat of the paper), and the marginal distribution of $\hat\mathbf{P}$ at $t\in[0,T]$ admits a probability density function given by
\begin{equation*}
    \hat\mathbf{P}_t(x)=\varphi(t,x)\hat\varphi(t,x)\text{ for every }x\in\mathbb{R}^n.
\end{equation*}
If further $\varphi,\hat\varphi$ are of class $C^{1,2}$, then they satisfy the dynamic Schr\"odinger system (equation Equation:ItoSchrodingerSystem of the paper), and the canonical process under $\hat{\mathbf{P}}$ solves the modified SDE
\begin{equation*}
dX_t=\left(b+\sigma\sigma^T\nabla\log \varphi\right)(t,X_t)dt+\sigma(t,X_t)dB_t;\, t\in[0,T]. 
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 25 (Degree order within a sector) of arXiv:2609.01143, 'The voter model on the hyperbolic graph'] Let $\mathcal I$ be a fixed angular arc of positive length, $0<\delta<1-\alpha$, and list the vertices of $\cG$ in $\mathcal I$ in decreasing degree order as $v_1,v_2,\ldots$. Uniformly for $(\log n)^2\leq j\leq n^\delta$, with high probability,
\begin{equation}
\de(v_j)\asymp e^{h(v_j)/2}, \qquad \de(v_j)^{2\alpha}\asymp\frac nj, \qquad h(v_j)=\frac1\alpha\log\frac nj+O(1).                   
\end{equation}

[Conj local curve GW vs M2 of arXiv:2609.02409, 'Membranes and Maps'] ((conj:GW:vertex of the paper), $n=1$) For every Calabi--Yau local curve over $\bP^1$ equipped with a Calabi--Yau $\mathsf{T}$-action, we have
    \begin{equation}

        \GWargs{Z}{\mathsf{T}}{[\bP^1]}
        =
        \hat{\mathsf{A}}_{\mathsf{T}}\Big( \overline{M}_{0}\big(Z,[\bP^1]\big) \Big) \,.
    \end{equation} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Theorem 3 (Sufficient conditions of  \cref{ass:predictive-stability}) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Let $\Theta\subset\R^d$ be convex and compact. Suppose that, for every $t$, almost surely, the map $\ell_t(\cdot;(x,y))$ is continuously differentiable on a neighborhood of $\Theta$ for almost every conditional realization $(x,y)$ of $(X_t,Y_t)$, and there are nonnegative $\cG_t$-measurable envelopes $H_t,G_t,D_t$ such that
     \begin{align}
     \|\nabla\ell_t(\theta;(X_t,Y_t))-\nabla\ell_t(u;(X_t,Y_t))\|
     &\le H_t\|\theta-u\|,\qquad \theta,u\in\Theta, \\
     \sup_{\theta\in\Theta}\|\nabla\ell_t(\theta;(X_t,Y_t))\|
     &\le G_t,\\
     \sup_{\theta,u\in\Theta}|\ell_t(\theta;(X_t,Y_t))-\ell_t(u;(X_t,Y_t))|
     &\le D_t.
    \end{align}
Assume that there exists an absolute constant $C_{\rm env}>0$ such that
    \begin{equation}
    \E\sbr{\e^{\eta D_t}(H_t+\eta G_t^2)\mid\cG_{t-1}}
    \le C_{\rm env}\qquad
    \text{a.s. for every }t\in\bN.
    \end{equation}
Moreover, assume that there exists $\theta^\star\in\operatorname{int}(\Theta) $ such that
    \begin{equation}
    \E[\nabla\ell_t(\theta^\star;(X_t, Y_t))\mid\cG_{t-1}]=0
    \qquad\text{a.s.}
    \end{equation}
Then \cref{ass:predictive-stability} holds for all probability measures supported on $\Theta$, with a deterministic constant depending only on $C_{\rm env}$, $\eta$, and $\operatorname{diam}(\Theta)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:transitivity of arXiv:2609.01697, 'Unique ergodicity of projective cocycles over the 2D stochastic Navier--Stokes equations'] Fix any $T>0$ and $z_0 \in \mathcal{X}$. Then
  \begin{itemize}
    \item In the case of LNS (equation eq:two_operators_intro_NS of the paper), for any $\delta
      \pi \in T_{\pi_T} \mathbb{S}$ the following holds:
      \begin{equation*}
        \langle \delta\pi, {A}^\sharp\pi_T \rangle = 0
        \qquad \forall A \in \mathfrak{g}_{\mathrm{LNS}} \quad \Rightarrow \quad \delta \pi = 0 .
      \end{equation*}
    \item In the case of PSA~(equation eq:two_operators_intro_PS of the paper), there exists a set $\Omega_0 \subseteq \Omega$ (depending
      on the initial condition $z_0$ and the terminal time $T$) with $\mathbb{P}(\Omega_0)=1$, such that the following holds for all events $\omega \in \Omega_0$. For any $\delta \pi \in T_{\pi_T} \mathbb{S}\cap H^{5}$ the following holds:
      \begin{equation*}
        \langle \delta\pi, {A}^\sharp\pi_T \rangle = 0
        \qquad \forall A \in \mathfrak{g}_{\mathrm{PSA}} \quad \Rightarrow \quad \delta \pi = 0 .
      \end{equation*}
  \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 22 of arXiv:2512.00213, 'On strong sharp phase transition in the random connection model'] Assume that $D^*_\varphi<\infty$ and let $n\in\N$. Then for any $t, \delta>0$ 
\begin{align*}
\esssup_{v\in\BX} \BE_t e^{\delta |V_{\le n}^v|}<\infty.
\end{align*}

[Proposition 37 of arXiv:2609.02819, 'Adelic Points and Unramified Brauer Approximation for Classifying Stacks'] Let $q:Y\to\cX$ be a Brauer-detecting atlas.  Then
\begin{equation}
 q^*\Brun(\cX)=\Brun(Y).
\end{equation}
Consequently, $\cX$ satisfies the finite evaluation criterion.

[Proposition prop:W as a sum of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $\mu=\mu_n$ be such that $(\log^{3/2}n)/\sqrt{n}\ll\mu\ll n$ and {recall $t_{\mu/n}=\argmin_{t \in (0,2)}\lambda_{\mu/n}(t)$.}
    Then, for any $\epsilon_n\ll1$ such that $(\mu^2n)^{1/3}\epsilon_n^2\gg\log n$ and $\epsilon\gg(\mu/n)^{1/3}$ (which are both possible thanks to the assumption on $\mu$) the sum $W_n$ defined in~(equation eq:def W of the paper) satisfies
    \begin{align*}
        W_n=\big(1+o(1)\big)\frac{\mu}{2n}e^{-n\lambda_{\mu/n}(t_{\mu/n})}\sum_{|m-t_{\mu/n}|<\epsilon_nt_{\mu/n}}\exp\left(-\left(\frac{3}{2}+o(1)\right)\left(\frac{\mu^4}{2\pi^2n}\right)^{1/3}\big(m-t_{\mu/n}\big)^2\right)\,,
    \end{align*}
    where the $o(\cdot)$ in the exponential are uniform over all terms of the sum.

