body:
[Thm 1 of arXiv:2608.16144, 'Central limit theorem in R\'enyi divergence for lattice random variables'] Let $\alpha >1$ and $\beta=\alpha/(\alpha-1)$. Let $X_{1},\cdots,X_{n}$ be independent copies of a lattice random variable $X$ with zero mean, unit variance, and maximal span $h>0$. Then $$
D_{\alpha}(S_{n}||Z_{n})\to 0 \quad \text{as}~n\to\infty
$$  
if and only if the following two conditions are fulfilled:
\begin{enumerate}
\item $D_{\alpha}(S_{n_0}||Z_{n_0}) < \infty$ for some $n_0\in\mathbb Z$;
\item $\mathbb E e^{tX} <e^{\beta t^2/2}$ for all $t \in \mathbb R,~t\neq0$.
\end{enumerate}
Moreover, under the above two conditions, for any given integer $s\geq 3$, we have the following expansion
\begin{align*}
D_{\alpha}(S_{n}||Z_{n})=\frac{1}{\alpha-1} \sum_{j=1}^{\lfloor s/2-1 \rfloor}b_{j}n^{-j}+o\big(n^{-\frac{s-2}{2}}\big),
\end{align*}
where the coefficients $b_j$'s represent certain polynomials of the cumulants of $X$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:naive of arXiv:2509.23496, 'Crossing probabilities in geometric inhomogeneous random graphs'] We have, for all $0<u<1$ and $R\ge 4,$
\begin{equation}
    \theta_{(u), R}  \leq \pi_{(u), R/2} + \theta_{R/2, R} .
\end{equation}
Consequently, we have
\begin{equation}
    \theta_{(u), R}  \asymp  \pi_{(u), R}^{(2)}  \text{ on } \widetilde D_0,

\end{equation}
where the domain $\widetilde D_0$ is defined as
\begin{equation}
 \widetilde D_0:=   \begin{cases}
    \{ u^{-1}\ge R^{d } \log R\}& \text{ if }\delta\ge \frac 1 \gamma,\\
    \{ u^{-\gamma \delta}\ge R^d\}& \text{ if }\frac 1 \gamma>\delta.
\end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:chim of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d\ge 1$ and $\delta>0$.
Suppose that Assumptions~(ass:Omega of the paper) and~(ass:J of the paper) hold for $S_z$ for each $z\in [z_c-\delta,z_c)$, suppose that $m_z \to 0$ as $z \to z_c$,
and suppose that there are constants $M,K_{\mathrm{IR}},\zeta$ such that
$(J_z^{(\mu)},h_z^{(\mu)}) \in \mathcal{Q}_{M,K_{\mathrm{IR}},\zeta}$ uniformly in $\mu\in \overline\Omega_z$ and in $z \in [z_c-\delta,z_c)$.
Then $\chi(z) \to \infty$ as $z \to z_c$.  More precisely,
\begin{equation}

    \chi(z)
    =
    \frac{2d\hat h_{z}(0)}{\sigma_{z}^2}
      \frac{1}{m_z^{2}}
    \big[ 1+O(m_z^{\zeta\wedge2}) \big] .
\end{equation}

