[Lem lem2.4 of arXiv:2411.14766, 'Axis-Driven Random Walks on $\Z^2$ \\ (transient cases)'] Assume $0<\alpha<1$, for any $z=(x,0)$ or $z=(0,x)$ with $x$ positive and large,
    \begin{align} 
    \mathbb{E}_z(\overline{Z}_{\rho})= x + 2 x^{\alpha}-{\frac{3}{2}}-\frac{1}{6} \frac{1}{x^{\alpha}}+O\Big(\frac{1}{x^{ 2\alpha}}\Big) . 
    \end{align}

For any $\beta \leq 2$, 
\begin{align} 
    \mathbb{E}_z(\overline{Z}_{\rho}^{\beta}) = x^\beta &+2\beta x^{\beta-1+ \alpha}+O( x^{\beta-1}).  

\end{align}

[Lemma ffTheorem4kk of arXiv:2607.21862, '\bf Uniform Large Deviations of Mckean-Vlasov Stochastic Fractional $(\alpha,p)$-Laplacian'] Let conditions {\bf A}
and {\bf B} be satisfied.
If $\psi_0\in L^{2}(\Omega,\mathfrak{F}_0,\mathbb{H})$,
then for all $k\in\mathbb{N}$,
\begin{align*}
&\mathbf{E}\bigg[\sup_{r\in[0,T]}\|\psi_k(r)
\|^{2}\bigg]
+
\mathbf{E}\bigg[\int_{0}^{T}\Big(\|\psi_k(r)
\|_{\mathbb{V}_1}^{p} +\|\psi_k(r)\|^q_{\mathbb{V}_2}\Big)
 dr\bigg]\leqslant  C(T) (1+\mathbf{E}[\|\psi_0\|^2]),
\end{align*}
and
\begin{align*}
&
\mathbf{E}\bigg[\int_0^{T}
\|\mathbf{A}_1(r,\psi_k(r),\mathcal{L}_{
\psi_k(r)}) \|^{\widehat{p}}_{\mathbb{V}^*_1}dr\bigg]
+
\mathbf{E}\bigg[\int_0^{T}
\|\mathbf{A}_2(r,\psi_k(r),\mathcal{L}_{
\psi_k(r)}) \|^{\widehat{q}}_{\mathbb{V}^*_2}dr\bigg]
\nonumber\\&+\mathbf{E}\left[
\int_0^{T}
\|\mathfrak{L}_{H,S}(r,\psi_k(r),\mathcal{L}_{
\psi_k(r)})
\|^2_{\mathcal{L}_2(\ell^2,
\mathbb{H})}dr
\right]
\le  C(T) (1+\mathbf{E}[\|\psi_0\|^2]),
\end{align*}
where $C(T)>0$ is a constant independent of $k$.

