[Theorem 4 of arXiv:2606.30080, 'Ergodicity of reflected stochastic reaction-diffusion equations driven by space-time white'] Let $u$ be the solution of equation \eqref{1.1} with initial value $f$. 
\begin{itemize}
  \item [(i)] Suppose that (H2) holds. If $\alpha > 0$ and there exists $f\in L^1$ such that
\begin{align}
  \sup_{t\geq 0}\mathbb{E} \Vert u(t)\Vert_{L^1} <\infty ,
\end{align}
then there exists a unique invariant measure in $L^1$. Moreover, the solution is exponentially mixing with respect to the Wasserstein metric $W_1$.
  \item [(ii)] Suppose that (H1) and (H2) hold. 
  If $\alpha>\frac{L_{\sigma}^4}{8}$ and there exists $f\in L^2$ such that
\begin{align}
  \sup_{t\geq 0}\mathbb{E} [\Vert u(t)\Vert^2_{L^2}] <\infty ,
\end{align}
then there exists a unique invariant measure in $L^2$. Moreover, the solution is exponentially mixing with respect to the Wasserstein metric  $W_2$.
  \item [(iii)] Suppose that (H1) and (H2) hold. 
    If there exists $p>2$ such that
  \begin{align*}
    \alpha > \left\{\frac{\sqrt{4p}}{\pi}\left(\frac{1}{2\sqrt{\pi}}\right)^{\frac{1}{p}+\frac{1}{2}} \left(\Gamma\Big(\frac{p-2}{6p}\Big)\right)^{\frac{3}{2}} \times L_{\sigma}\right\}^{\frac{4p}{p-2}},
  \end{align*}
  and there exists $f\in C_0^+([0,1])$ such that
\begin{align}
  \sup_{t\geq 0}\mathbb{E} \Big[\sup_{x\in [0,1]} | u(t,x)|^p\Big] <\infty ,
\end{align}
then there exists a unique invariant measure in $C_0^+([0,1])$. Moreover, the solution is exponentially mixing with respect to the Wasserstein metric $W_p$.
\end{itemize}

