[Prop 21 of arXiv:2603.05174, 'Regularization of the superposition principle: Potential theory meets Fokker-Planck equati'] If $b$ is locally bounded then
    \begin{equation}}
        C_c^2([0,\infty)\times \mathbb{R}^d)\subset \mathcal{D}(\mathcal{L}^K)\quad \mbox{and}\quad {\sf \overline{L}^K}f=\mathcal{L}^Kf, \quad f\in C_c^2([0,\infty)\times \mathbb{R}^d).
    \end{equation} 
    Consequently, if $X^K$ is the right process constructed in \Cref{prop:X^K}, then for every $(s,x)\in E$ and every $f\in C_c^2([0,\infty)\times \mathbb{R}^d)$ we have that
    \begin{equation*}
        \mathbb{E}^K_{(s,x)}\left\{\int_0^{t} \left|{\sf \overline{L}^K}f(X^K(r))\right|\; dr
               \right\}<\infty, \quad t\geq 0,
    \end{equation*}
    and 
    \begin{equation*}
        \left(f(X^K(t))-f(X^K(0))-\int_0^{t} {\sf \overline{L}^K}f(X^K(r))\; dr\right)_{t\geq 0} \; \mbox{ is a c\`adl\`ag } \left(\mathcal{F}^K_t\right)\mbox{-martingale under } \mathbb{P}^K_{(s,x)}.
    \end{equation*}

