body:
[Proposition prop:roughbounds of arXiv:2412.04328, 'The critical Karp--Sipser core of Erdős--Rényi random graphs'] There is $\eta_0>0$ such that for all $0<\eta<\eta_0$ and $\delta >0$ and $K>0$, there exists a constant $K'$ such that for $n$ large enough, under the event $\mathcal{E}_{\eta,K}$, we have 
	\begin{equation}
		\mathbb{P} \left( \max_{k_0(\eta) \leqslant k < \widetilde{\theta}^n } \left\{ \frac{ \widetilde{A}_k}{| \log ( \varepsilon_k)|^{3/4}}, \widetilde{B}_k, \widetilde{C}_k\right\} \leqslant K' \Big| \mathcal{F}_{k_0(\eta)} \right) \geqslant 1-\delta.
	\end{equation}

[Proposition prop:four-dimensional-global-minimizer of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] There exists a nonconstant $O(2)\times O(2)$-invariant $E_{1,4}$ global minimizer $v\in C^{1,\alpha}_{\mathrm{loc}}(\mathbb R^4)$, $-1<v<1$.  Moreover,
\begin{equation}
-\operatorname{div} a_4(Dv)+W'(v)=0
\qquad\text{in }\mathbb R^4,
\end{equation}
and
\begin{equation}
Dv(0)=0.
\end{equation}

[Lem 5 of arXiv:2607.11275, 'The limit law of the maximum of discrete partial-sums distribution II'] If $\mathbb{E}S_N<0$ and $s\in\mathbb{C}$ is such that $|s|\leqslant 1$ and $s\neq0$, then

\begin{align}\nonumber
&(1-s)\sum_{j=1}^{N}
s^{m_j}
G_{X_N+X_1+\cdots+X_{j-1}}(s)
\sum_{i=0}^{-m_j-1}\pi_i^{(j+1)}
\sum_{r=0}^{-m_j-1-i}
s^{r+i}F_{X_j}(m_j+r)\\
&=
G_{\mathcal M_N}(s)\left(G_{S_N}(s)-1\right),
\end{align}
where
\begin{align*}
G_{X_N+X_1+\cdots+X_{0}}(s):=1 \quad \text{and} \quad \pi^{(N+1)}=\pi^{(1)}.
\end{align*}
Moreover,
\begin{align}
\sum_{j=1}^{N}
\sum_{i=0}^{-m_j-1}
\pi_i^{(j+1)}
\sum_{r=0}^{-m_j-1-i}
F_{X_j}(m_j+r)
=
-\mathbb{E}S_N.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 53 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] A probability measure $\mathbb{P}_T$ on space $\bZ_T$ is said to be a solution to the martingale problem $(\bX_0,\bF,\newG_0)$, where  $\bX_0\coloneqq  (\bu_{0},\phi_{0}) \in\mathbb{H}$,  i.e. the problem \eqref{eqn-compact-modified-stochastic-CHNSEs-3}, if and only if 
\begin{trivlist}
\item[(i)] for almost every $\bX$ belonging to the support of the measure $\mathbb{P}_T$, the function $\cp$ defined by
              \begin{equation}
                \cp(t)=  \Atwo \phi(t) +  \psi^\prime(\phi(t)) - \avg{\psi^\prime(\phi(t))}, \;\; t\in [0,T]    
              \end{equation}
belongs to $L^{2}(0,T;\newone{H})$ and 
\item[(ii)] 
for every $z \in \mathscr{V}$, the process $M_t^{z}$ defined on the canonical sample space $\bZ_T$ in \eqref{eqn-M^z_t} 
is a continuous $\mathbb{D}$ local martingale. 
\end{trivlist}

[Theorem 1 of arXiv:2609.00867, '2609.00867'] Under Assumption~\ref{ass:kernel-density}, for every \(\beta\ge0\),
\begin{equation}
 1\le\sup_{N\ge2}
 \cZ_{N,\rho}(\beta;g_{d,s}^{(m)})<\infty.
\end{equation}
More precisely, for \(0\le\beta\le1\),
\[
 0\le\sup_{N\ge2}
 \log\cZ_{N,\rho}(\beta;g_{d,s}^{(m)})
 \le C_{d,s,m,\rho}\beta^2,
\]
and for \(\beta\ge1\),
\begin{equation}
 \sup_{N\ge2}\log\cZ_{N,\rho}(\beta;g_{d,s}^{(m)})
 \le C_{d,s,m,\rho}
 \begin{cases}
  \beta\log(2+\beta),&s=0,\\
  \beta^{d/(d-s)},&0<s<d/2.
 \end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 39 of arXiv:2607.08696, 'Spectrum of Directed Inhomogeneous Random Graphs'] In the present setting, it holds
    \begin{equation}
        \lambda_l - \tilde \lambda_l 
        =\scaling \theta_l \frac{(v_l^-)^t \centered v_l^+}{\tilde \lambda_l} 
        + \ohp \left(\frac{\left\|V_{1,n}\right\|}{\scaling}+\sqrt{\frac{\scaling}{n}}\right).
    \end{equation}

