[Corollary cor:realbranches of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Let $\mathcal C\subset X(M)$ be the irreducible algebraic curve obtained from Theorem (thm:main of the paper), and let $x\in\widetilde{\mathcal C}\setminus\mathcal C$ be the corresponding ideal point. Then $x$ is a real point of $\widetilde{\mathcal C}$, and there is a holomorphic local coordinate at $x$, defined over $\mathbb R$, whose restriction gives a signed real analytic coordinate
\begin{equation*}
	t:(\widetilde{\mathcal C}(\mathbb R),x)\longrightarrow(\mathbb R,0)
\end{equation*}
such that, after shrinking the parameter interval, the following hold for every $t\neq0$:
\begin{enumerate}
	\item the corresponding character $\chi_t\in X(M)$ is real-valued and irreducible;
	\item if $\mu$ is a knot meridian, then $I_\mu(t) = \chi_t(\mu) = 2+Qt^2+O(t^3)$ for some $Q>0$;
	\item $\chi_t$ is the character of an irreducible representation $\rho_t:\pi_1(M)\longrightarrow SL_2(\mathbb R)$
\end{enumerate}

[Cor 35 of arXiv:2506.17979, '\large\bf A remark on subharmonicity for symmetric Dirichlet forms'] If $u$ is a Lipschitz function on $\R^d$, then $\Psi(m^{\frac{1}{\alpha}}
|\cdot|)\left(1\land\frac{1}{|\,\cdot\,|^{d+\alpha}}\right)|u|\in L^1(\R^d)$ {\rm(}resp.~$\Psi(m^{\frac{1}{\alpha}}|\cdot|)\left(1\land\frac{1}{|\,\cdot\,|^{d+\alpha}}\right)|u|^2\in L^1(\R^d)${\rm)} under $m>0$ or 
$m=0$ with $\alpha\in]1,2[$ {\rm(}resp.~$m>0${\rm)}.

