[Theorem 15 of arXiv:2607.11773, '2607.11773'] Suppose that {\bf(H1)}-{\bf(H4)}, \eqref{thetaassum2}, \eqref{dissip1} and \eqref{dissip2} hold.
   Then for every $\tau \in \mathbb{R}$,
   \begin{align*}
      \lim_{\varepsilon \to 0}
         d_{\mathcal{P}(D_\rho)}
           \left( \mathcal{A}^\varepsilon(\tau), \mathcal{A}^0(\tau) \right) = 0,
   \end{align*}
   where $d_{\mathcal{P}(D_\rho)}$ is the Hausdorff semi-metric between subsets of $\mathcal{P}(D_\rho)$.

[Defn defnSchwLine of arXiv:2607.29423, 'Schwarzian Field Theory at High Temperatures'] Let $\varkappa>0$.
\emph{Schwarzian Measure on the real line} is the Borel probability measure $\mathop{}\!\mathrm{d}\mathscr{M}_{\varkappa^2}^{\infty}$ on~$\big(C^1(\mathbb{R}),  \mathcal{T}_{C^1(\mathbb{R})}\big)$ given by
\begin{equation}
\mathop{}\!\mathrm{d}\mathscr{M}_{\varkappa^2}^{\infty}(f)
 \coloneqq 
\mathop{}\!\mathrm{d} \BM{\varkappa^2}{\infty}(\xi), 
\qquad \text{with } f(t) = \mathsf{Q}_{\xi}(t),
\end{equation}
where 
\begin{equation}
\mathsf{Q}(\xi)(t):= \mathsf{Q}_{\xi}(t):= \int_{0}^{t} e^{\xi(s)}\mathop{}\!\mathrm{d} s,
\end{equation}
and $\mathop{}\!\mathrm{d}\BM{\varkappa^2}{\infty}(\xi)$ is a probability measure on $C(\mathbb{R})$, corresponding to the two-sided Brownian Motion on $\mathbb{R}$ with $\xi(0)=0$ and variance $\varkappa^2>0$.

[Defn 6 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] We define $\mathscr{S}'_p(\R^{d})$ as the set of tempered distributions that are $\Z^d$ periodic in frequency, that is, the set of $u\in \mathscr{S}'(\R^d)$ such that,
\begin{equation*}
    \forall n\in \Z^d, \m\m\m\tau_{n}\mc{F}_{h}(u)=\mc{F}_{h}(u).
\end{equation*}

[Lem rarity-of-disagreement-regions of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] There exists $M_0(d)$ such that for all $M\ge M_0$ the following holds. Suppose that $\mathbb P(\widetilde{D}_{k-1}(B') =1)\le q_{k-1}$ for all $B' \in \mathscr{B}_{k-1}$. Then for every $B \in \mathscr{B}_k$, one has 
    \begin{align*}
        \mathbb P(|\mathsf{Dis}_{k-1}(B)|>s_k ) \le q_k/10\,.
    \end{align*}

[Lemma 20 of arXiv:2608.30602, '2608.30602'] Assume $|v(x)|\lesssim\langle x\rangle^{-3-}$. Then for $m=1,2$ we have
\begin{equation}
\mathcal{Q}_m v\bigl(R_0^+(\lambda^2)(\cdot,y)-R_0^-(\lambda^2)(\cdot,y)\bigr)
=e^{i\lambda a}\,\mathcal{Q}_m\eta_m^+(\lambda,\cdot,y)+e^{-i\lambda a}\,\mathcal{Q}_m\eta_m^-(\lambda,\cdot,y),
\end{equation}
where the amplitude functions $\eta_m^\pm(\lambda,x,y)$ satisfy, for $\lambda\in(0,1/2)$ and $k=0,1,2$,
\begin{align}
\bigl\|\partial_\lambda^k\eta_m^\pm(\lambda,\cdot,y)\bigr\|_{L^2(\mathbb{R}^2)}&\lesssim\lambda^{m-\frac12-k}a^{-\frac12},\\[4pt]
\bigl\|\partial_\lambda^k\eta_m^\pm(\lambda,\cdot,y)\bigr\|_{L^2(\mathbb{R}^2)}&\lesssim\lambda^{m-k}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 66 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] For any strong preparation map $R$, one has 
	\begin{equation} 
	\sum_{\mu\prec R\tau} \mu \otimes (R\tau)/\mu = 	\sum_{\sigma\prec \tau} R\sigma \otimes \tau/\sigma.
\end{equation}

