body:
[Lem 193 (annealed second moment bound for $\tilde{E}^{\RomIII}$) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] For $\tilde{E}^{\RomIII}$ as defined by \eqref{e:qv.ezero},
for $N$ large enough we have
	\[
	\E\bigg[
	\bigg(\frac{\Delta\tilde{E}^{\RomIII}(q_d)}{\delta_d}
	\bigg)^2\bigg]
	\le
	L^{O(1)} 
	\bigg\{
	\frac{1}{N\delta}
	+ \frac{\BUCKETS}{N}
	\bigg\}
	\]
for all $0\le d\le \dmax-1$.
 The same bound holds with $\tilde{E}^{\frozen,\RomIII}$ in place of $\tilde{E}^{\RomIII}$.

\begin{proof}
For $q_d < q_T$ we rewrite \eqref{e:qv.ezero} as
	\beq
	\frac{\tilde{E}^{\RomIII}(q_{d+1})-\tilde{E}^{\RomIII}(q_d)}{\delta_d}
	=
	\frac{q_d(p_{d+1}-p_d)}{\delta_d}
	\Big\{
	F+G
	\Big\}\,,\eeq
for $F$ and $G$ defined by 
	\[
	F
	\equiv \frac{1}{|B|}
	\sum_{a\in B}\bigg(
	\frac{(\bmeta^a,\bar{\bx})^2}{N}
	-\frac{\|\bar{\bx}\|^2}{N}\bigg)
	\equiv\frac{1}{|B|}
	\sum_{a\in B} \xi^a
	\,,\quad
	G
	\equiv \frac{\|\bar{\bx}\|^2}{N}-1\,.\]
Note that $\xi_a$ has mean zero conditional on $\cG(q_d)$. It follows that
	\begin{align*}
	\E[F^2]
	&=\E \bigg[\sum_B \frac{|B|}{M}
	\frac{1}{|B|^2}
	\bigg(\sum_{a\in B} \xi_a\bigg)^2\bigg]
	=\E \bigg[\sum_B \frac{1}{{M}|B|}
	\sum_{a\in B}
	\E(\xi_a^2\,|\,\cG(q_d))
	\bigg] \\
	&\le O(1)\,
	\E\bigg[ \frac{|\mathcal{B}(q_d)|}{M}
	{\frac{\|\bar{\bx}\|^4}{N^2}}\bigg]
	\le \frac{ L^{O(1)} \E[ |\mathcal{B}(q_d)|^2]^{1/2}}{N\alpha}
    \le \frac{\BUCKETS L^{O(1)}}{N}
	 \,,
	\end{align*}
where the second-to-last bound uses the Cauchy--Schwarz inequality together with Lemmas~\ref{l:sg.norm.bound} and \ref{l:bar.x.subgaus}. To bound the second moment of $G$, recall that in the case $q_d=0$, we define $\bar{\bx}=N^{1/2}\ind\in\R^N$, so we have simply $G=0$ in this case. Otherwise, if $q_d\ne0$, then we have
	\[
	\|\bar{\bx}\|^2
	\stackrel{\eqref{e:normalized.vectors.x}}{=}
	\frac{\|\bx(q_d)\|^2}{q_d}
	\le \frac{N}{q_d}
	\le \frac{N L^{O(1)}}{\delta}\,,
	\]
where the last bound is by \eqref{e:delta.cutoffs} and \eqref{e:deriv.p.bound}. Thus, if we regard $G$ as a function of the gaussian disorder $\bg\equiv\bar{\bG}(q_d)
\equiv \bG(q_d)/(p_d)^{1/2}$, we can bound
	\begin{align*}
	&|G(\bg)-G(\bg')|
	\le \bigg|
	\frac{(\bar{\bx}(\bg),\bar{\bx}(\bg)-\bar{\bx}(\bg') )}{N}
	\bigg|
	+\bigg|\frac{(\bar{\bx}(\bg)-\bar{\bx}(\bg'),\bar{\bx}(\bg'))}{N}
	\bigg| \\
	&\qquad\le
	\frac{\|\bar{\bx}(\bg)\| \|\bar{\bx}(\bg)-\bar{\bx}(\bg')\|}{N}
	+\frac{\|\bar{\bx}(\bg)-\bar{\bx}(\bg')\|
		\|\bar{\bx}(\bg')\|}{N}
	\le \frac{L^{O(1)}}{N} \bigg(\frac{N}{\delta}\bigg)^{1/2}
		\,.
	\end{align*}
Therefore $G$ is subgaussian with variance proxy $L^{O(1)} /(N\delta)$, and it follows that
	\[\E[G^2]
	\le \frac{L^{O(1)}}{N\delta}\,.\]
Substituting the bounds into \eqref{e:qv.ezero.rewrite}, and combining with \eqref{e:deriv.p.bound}, gives the claim.
\end{proof}

