body:
[Proposition 24 (Reeb correction to the K\"ahler shape conclusion) of arXiv:2608.29406, 'Partially Totally Real Submanifolds of Sasakian Manifolds'] For every PTR-submanifold, every $Z\in\Gamma(\Dperp)$ and $U\in\Gamma(TM)$,
\begin{equation}
 g(A_{\phi Z}U,\xi)=-g(U,Z).
\end{equation}
If, in addition, $F$ is parallel and $\Dperp$ is maximal, then
\begin{equation}
 A_{\phi Z}U\in\Gamma(\Dperp\oplus\langle\xi\rangle).
\end{equation}
Thus the K\"ahler statement $A_{JZ}U\in\mathcal H^\perp$ is replaced by \eqref{eq:AphiZ-split}; its extra component is exactly the Reeb term in \eqref{eq:AphiZ-Reeb}.

[Corollary cor:oszac_p^D_nu of arXiv:2411.08220, 'Nonlocal operators with Neumann conditions'] For $\alpha\in (0,2)$, $t>0$, $x>0$ and $y<0$,
    \begin{align*}
        \mathcal{J}(t,x,y) := \int_D  p_t^D(x,z)\nu(z,y)\,{\rm d}z \approx t^{-1} \Big(1\wedge \frac{|x|}{t^{1/\alpha}}\Big)^{\alpha/2}\Big(1\wedge \frac{|y|}{t^{1/\alpha}}\Big)^{-\alpha/2} p_t(x,y).
    \end{align*}

[Proposition Rnsecbase of arXiv:2604.07227, 'Transition probabilities of step-reinforced random walks'] Assume that $\alpha \in [0,1]$, then the elephant polynomials $(R_n(x))_{n\geq 1}$ defined by ((defelepoly of the paper)) can be written as 
    \begin{equation}

    R_n(x) =\sum_{k=0}^{\lfloor \frac{n}{2} \rfloor} (-1)^k \lambda_{n,k}x^{n-2k}(1-x^2)^k, \quad x\in \mathbb{R},
  \end{equation}
  where $\lambda_{n,k}$ $(k=0,1,2\dots, \lfloor n/2 \rfloor)$ are non-negative numbers. Moreover, for any $n\geq 1$,
  \begin{equation}

 e^{-\frac{(1-\alpha)n}{3+\alpha}}\binom{n}{2k} \alpha^k \leq \lambda_{n,k} \leq \binom{n}{2k} \alpha^k, \quad k\in \left\{0,1,\dots, \lfloor \frac{n}{2} \rfloor\right\}.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem box-poincare of arXiv:2609.03856, 'Consensus time for asynchronous $\ell^p$ relaxation: graph dependence'] For every fixed $1<p<\infty$, all integers $d\ge1$ and $L\ge2$, and every
$f:[L]^d\to\mathbb{R}$,
\begin{equation}
 \sum_{x\in[L]^d}|f(x)-\bar f|^p
 \le C_p d^{\max\{0,p/2-1\}}L^p\mathcal{E}_p(f),
 \qquad \bar f=L^{-d}\sum_xf(x).
\end{equation}
Consequently,
\begin{equation}
 \Phi_p([L]^d)\le C_p
 \begin{cases}
  dL^p,&1<p<2,\\
  d^{p/2}L^p,&p\ge2.
 \end{cases}
\end{equation}

[Thm p:300.3 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let $u \geq 0$.
\begin{equation}

\lim_{k \to \infty}
\limsup_{n \to \infty} \mathbb{P} \big( {\mathbf G}_n(u) \setminus 
{\mathbf W}_n^k(u) \neq \emptyset \big) = 0 \,.
\end{equation}
Morevoer,
\begin{equation}

\frac{ \big| {\mathbf W}_n(u) \setminus 
{\mathbf W}_n^k(u) \big|}{\sqrt{n}} \overset{\mathbb{P}}\longrightarrow 0 \,,
\end{equation}
as $n \to \infty$ followed by $k \to \infty$, and 
\begin{equation}

\frac{\big|{\rm W}_n^{[r_n, n-r_n]}(u)  \big|}{\sqrt{n}}
	\overset{\mathbb{P}}{\underset{n \to \infty}\longrightarrow} 0 \,.
\end{equation}
as $n \to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop prop-cond-on-ext of arXiv:2411.06301, 'Inverting the operation of conditioning a branching process on extinction'] Let $X = \{X(n) \}_{n\in\mathbbm N_0}$ be a positive regular, non-singular $d$-type branching process  (Definition~(def-bp-basic of the paper)) with generating function $f$. Let $E$ be the event that the process eventually becomes extinct. For $k\in \{1,\dots,d\}$, define the extinction probability 
\begin{equation*}
a_k := \mathbbm P_k\mathopen{}\mathclose\bgroup\originalleft[ E \aftergroup\egroup\originalright] .
\end{equation*} 
Then the only solutions of $f(q) =q$ in the unit cube $[0,1]^d$ are $a = (a_1,\dots,a_d)$ and $(1,\dots,1)$. 

Suppose that $0 < a_k < 1$ for every $k \in \{1,\dots,d\}$. Then for each $k\in\{1,\dots,d\}$, the $\mathbbm P_k$-conditional law of $X$ given $E$ is that of a branching process with offspring distribution determined by 
\begin{equation} 
\mathbbm E_k\mathopen{}\mathclose\bgroup\originalleft[ F(X_1(1) , \dots, X_d(1)) \,|\, E \aftergroup\egroup\originalright] 
 = \frac{1}{a_k} \mathbbm E_k\mathopen{}\mathclose\bgroup\originalleft[ F(X_1(1),\dots,X_d(1)) \prod_{j=1}^d a_j^{X_j(1)} \aftergroup\egroup\originalright]   
\end{equation} 
for every bounded measurable function $F : \mathbbm N_0^d \to \mathbbm R$. Moreover, this branching process is subcritical.

[Lemma 54 (Rectangular trace-endpoint identification) of arXiv:2606.29292, 'Intrinsic Gaussian Tensor Geometry and Random Operator Spectra'] Let $m\ge1$.  For every algebraic order-$m$ kernel $K$,
\begin{equation}

 (C_m^{\mathrm{HP}})^{-1}\norm K_{\mathfrak T_{m,1}^{\Sigma}}
 \le \norm{\cT_K^{(m)}}_{L^1(\Omega;\Sch_1)}
 \le \norm K_{\mathfrak T_{m,1}^{\Sigma}},
\end{equation}
where $C_m^{\mathrm{HP}}<\infty$ depends only on $m$.  The constant is
independent of the dimensions of the stochastic supports and of the
deterministic Hilbert spaces.

[Proposition prop:strict of arXiv:2608.23203, 'Well-posedness of fully coupled McKean--Vlasov\\ FBSDEs with jumps under full-tuple law de'] Let $n=m=1$, $d\ge1$ and $G=1$, and fix $\beta_1>0$. For every $0<\varepsilon<\beta_1$,
the drift
\begin{equation}
b(t,\theta,\mu):=-\beta_1 y+\varepsilon\,g_0\bigl(y-m_Y(\mu)\bigr),\qquad
g_0(r):=\max\{-1,\min\{1,r\}\},
\end{equation}
with $m_Y(\mu):=\int_{\mathcal H}y\,\mu(\mathrm{d}\theta)$ the $Y$-marginal mean, is
free-measure $W_2$-Lipschitz with constant $\beta_1+\varepsilon$ and satisfies, along
all $(\Theta,\mu),(\Theta',\mu')\in\mathcal D_t$,
\begin{equation}
\mathbb{E}\inner{\delta b}{\delta Y}\ \le\ -(\beta_1-\varepsilon)\,\mathbb{E}|\delta Y|^2 ;
\end{equation}
yet for every $\beta\ge0$ the pointwise bound
$\inner{\delta b}{\delta y}\le-\beta\,|\delta y|^2$ fails at a pair of free inputs with
$\theta\in\operatorname{supp}\mu$ and $\theta'\in\operatorname{supp}\mu'$.

