[Proposition prop:lip:costs of arXiv:2412.09235, 'A semiconcavity approach to stability of entropic plans and exponential convergence of Sin'] Let $\mathcal{X},\mathcal{Y}\subseteq\mathbb{R}^d$ be two open (connected, possibly unbounded) domains of $\mathbb{R}^d$ endowed with the Euclidean metric and assume that there are two constants $h(c),\,H(c) \in \mathbb{R}$ such that
\begin{equation}
h(c)\preceq\nabla^2_2c(x,y)\preceqH(c)\quad\text{ and }\quad\nabla^2_1c(x,y)\preceq H(c)\, \quad \forall x,y\in\mathbb{R}^d.
\end{equation}
 Further assume that $\nu$ satisfies (eq:TI of the paper).  We distinguish two cases.
    \begin{enumerate}[label=(\roman*)] 
    \item Assume that the cost is Lipschitz in $y$, uniformly in $x$, that is,
\begin{equation}
\sup_{x\in\mathbb{R}^d}|c(x,y)-c(x,\hat{y})|\leq \mathrm{Lip}_{\infty,2}(c)\,|y-\hat{y}|\, \quad \forall y,\hat{y}\in\mathbb{R}^d.
\end{equation}
Then, Sinkhorn's algorithm converges exponentially fast and for $\varepsilon$ small enough (as in (equation eps:small:lip2:cost of the paper)) the rate is
\begin{equation*}
1-\frac{\varepsilon^2}{\varepsilon^2+\tau\varepsilon(H(c)-h(c))+\tau\mathrm{Lip}^2_{\infty,2}(c)}\,.
\end{equation*}
        \item Assume that the cost is Lipschitz in $x$, uniformly in $y$, that is,
\begin{equation}
\sup_{y\in\mathbb{R}^d}|c(x,y)-c(\hat{x},y)|\leq \mathrm{Lip}_{1,\infty}(c)\,|x-\hat{x}|\ \quad \forall x,\hat{x}\in\mathbb{R}^d\,.
\end{equation}
Further assume that $\norm{\nabla_{12}^2c(x,y)}_2\leq H(c)$ and that $\rho$ satisfies the logarithmic Sobolev inequality (eq:LSI of the paper). Then, Sinkhorn's algorithm converges exponentially fast and for $\varepsilon$ small enough (as in (equation eps:small:lip1 of the paper)) the rate is
\begin{equation*}
 1-\frac{\varepsilon^4}{\varepsilon^4+\tau\varepsilon^3(H(c)-h(c))+2\tauH(c)^2C_\rho(\varepsilon^2+4C_\rho\mathrm{Lip}_{1,\infty}^2)}\,.
\end{equation*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 14 (Mollification limit) of arXiv:2609.02196, 'Schr\"odinger Bridges on Lie Group Manifolds for Probabilistic Intrinsic Generation'] Under Assumption~\ref{ass:rccbm-mollification-regularity},
