[Proposition 8 of arXiv:2604.01701, '\bf Chung-type laws of the iterated logarithm for $m$-fold weighted integrated fractional '] \begin{itemize}
  \item[(i)] For all $\gamma>0$ and $\alpha<H+\gamma$, 
\begin{align} 
 \lim_{\epsilon\to 0} \epsilon^{1/(H+\gamma)} \log \pr\left(\sup_{0\le  t\le 1}t^{-\alpha}\left| I_{\gamma}(B_H)(t) \right|<a_H \epsilon\right) 
 =-\frac{\kappa_{H+\gamma}}{1-\alpha/(H+\gamma)}. 
\end{align}
  \item[(ii)]  Let  $\lambda>0$, and $W_{\lambda}(t)$ be defined as \eqref{eqdefW}.  Then for $\alpha<\lambda$, 
\begin{align}
\lim_{\epsilon\to 0}\epsilon^{1/\lambda} \log \pr\left(\sup_{0\le  t\le 1}\left|W_{\lambda}(t)\right|/t^{\alpha}< \epsilon\right)
=-\frac{\kappa_{\lambda}}{1-\alpha/\lambda}.
\end{align}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm:ProjectedGDEquivalence of arXiv:2609.03762, '\vspace*{-2cm} Projected Riemannian Gradient Descent for the Bures--Wasserstein Barycenter'] Let $f : \mathrm{PD}(d) \to \mathbb{R}$ be differentiable, $g := f \circ \pi$, and $(\eta_t)_{t \geq 0}$ a sequence of step sizes.
        Let $(S_t)_{t \geq 0}$ be generated by Projected BW-GD from $S_0 \in [\alpha I, \beta I]$,
        \begin{equation} 
            S_{t+1} = \mathrm{clip}_{\alpha, \beta}\Big[ \left[I - 2 \eta_t \nabla f(S_t)\right] \, S_t \, \left[I - 2 \eta_t \nabla f(S_t)\right] \Big],
        \end{equation}
        and $(A_t)_{t \geq 0}$ by singular-value clipped Euclidean GD from any $A_0 \in \pi ^{-1} [S_0]$,
        \begin{equation} 
            A_{t+1} = \mathrm{clip}^{\mathrm{sv}}_{\sqrt{\alpha}, \sqrt{\beta}}\left[A_t - \eta_t \nabla g(A_t)\right].
        \end{equation}
        Then $\pi[A_t] = S_t$ for every $t \geq 0$.
        Consequently one may propagate $(A_t)_{t \geq 0}$ alone, for $f \in \{f_1, f_2\}$, halting once $\|\hat\nabla g(A_t)\|_\mathrm{F}^2 \leq 2 \kappa^{-3/2} \delta$ certifies $f(S_t) - f(S_\star) \leq \delta$ ((Cor:Certificate of the paper)), and return $S_t = \pi(A_t)$ only upon termination. (Proof in the paper; no proof environment follows the statement in the TeX.)

