[Theorem infinite of arXiv:2412.04396, 'Superdiffusive Scaling Limits for the Symmetric\\ Exclusion Process with Slow Bonds'] Fix $T>0$ and  speed up the process by $k^2n^{1+\beta}$. Assume that $k=k(n)\uparrow\infty$ as $n\uparrow\infty$.  Then, for every $t\in[0,T]$ and every $G\in C^2({\mathbb T})$,
	$$\lim_{n\to\infty}{\mathbb E}_{\mu^n}\Big[\Big| \langle \pi_{t}^n,G \rangle\,-\,\int_{{\mathbb T}}G(u)\rho_t(u)du\Big|\Big]\;=\;0\,,$$
	where $\rho_t(\cdot)$ is the strong solution of the heat equation:
	\begin{equation}
		\begin{cases}
			\partial_t\rho_t(u)=\alpha\Delta \rho_t(u), \quad u\in {\mathbb T} \\
			\rho_0(u)=\gamma(u),  \quad u\in {\mathbb T}.
		\end{cases}
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 12 of arXiv:2606.23099, 'Path-dependent Affine Processes'] In the setting of Theorem~\ref{main_thm}, define the $\ccM([0,T],\C^d)$-valued measure $\Psi$ by
    \begin{align}
        \Psi^j(t,T,\mu,A) & = \psi^j(t)\delta_t(A) + \mu^j(A \cap [0,t)) \notag            \\
                          & \quad + \int_t^T \Bigl( \psi(u) b^j\bigl(u, A \cap [0,t)\bigr)
        + \frac{1}{2} \psi(u)\, a^j\bigl(u, A \cap [0,t)\bigr)\, \psi(u)^\top\Bigr)\, du, \quad j = 1,\dotsc, d,
    \end{align}
    for all Borel sets $A \subseteq [0,T]$.
    Then
    \begin{equation*}
        Y(t)=\phi(t)+\Psi(t,T,\mu)\cdot X_{[0,t]}
    \end{equation*}
    and if $e^Y$ is a true martingale, then the conditional Fourier--Laplace transform admits the exponential-affine representation.
    Moreover, the pair $(\Psi,X)$ satisfies the semimartingale representation of
    Assumption~\ref{ass:sm-diff-Psi} with
    \begin{align*}
        \psi(t,T,\mu)             & = \psi(t)                                                                \\
        \alpha(t,X_{[0,t]},T,\mu) & = \psi(t,T,\mu)B(t,X_{[0,t]}) + \frac{1}{2}A(t,X_{[0,t]},\psi(t,T,\mu)).
    \end{align*}

