[Proposition prop:anisotropic:cost of arXiv:2412.09235, 'A semiconcavity approach to stability of entropic plans and exponential convergence of Sin'] Let 
  $\mathcal{X},\,\mathcal{Y}\subseteq\mathbb{R}^d$ be two open (connected, possibly unbounded) domains of $\mathbb{R}^d$ endowed with the Euclidean metric 
  and assume that $c(x,y)\coloneqq \langle x-y,\,\Sigma (x-y)\rangle/2$ for some positive definite symmetric matrix $\Sigma$. Further assume that $\nu$ satisfies (eq:TI of the paper).
\begin{enumerate}[label=(\roman*)] 
    \item  If $\mathcal{X}=\mathcal{Y}=\mathbb{R}^d$ and $\rho(\mathrm{d} x)=e^{-U_{\rho}(x)}\mathrm{d} x$, $\nu(\mathrm{d} y)=e^{-U_{\nu}(y)}\mathrm{d} y$ and there exist    $\alpha_\rho,\beta_\nu\in(0,+\infty)$ such that
    \begin{equation}
        \nabla^2 U_{\rho}(x)\succeq \alpha_\rho,\quad         \nabla^2 U_{\nu}(y)\preceq\beta_\nu \quad \forall x,y \in \mathbb{R}^d
    \end{equation}
     in semidefinite order, then Sinkhorn's algorithm converges exponentially fast. If we choose $\varphi^{0}_\varepsilon$ such that 
     $\nabla^2\varphi^{0}_\varepsilon\succeq (\sqrt{\nicefrac{\alpha_\rho}{\beta_\nu}}-1)\Sigma$,
      then
     for $\varepsilon\leq \tau \,\sqrt{\nicefrac{\beta_\nu}{\alpha_\rho}}\,\norm{\Sigma}_2$ the rate is 
    \begin{equation}
    1-\frac{\varepsilon}{\varepsilon+\tau\|\Sigma\|_2(\nicefrac{\beta_\nu}{\alpha_\rho})^{\nicefrac12}}\,.
    \end{equation}
    Otherwise, for any general initialization $\varphi^{0}_\varepsilon$ the expression appearing in~(equation eq:quick_rate of the paper) represents the asymptotic rate.
    \item    If $\mathcal{X}=\mathbb{R}^d$ and $\rho(\mathrm{d} x)=e^{-U_{\rho}(x)}\mathrm{d} x$ and  there exists $\alpha_\rho\in(0,+\infty)$ such that
    \begin{equation*}
     \nabla^2 U_{\rho}(x)\succeq \alpha_\rho \quad \forall x\in \mathbb{R}^d
    \end{equation*}
    in semidefinite order, then Sinkhorn's algorithm converges exponentially fast and for $\varepsilon\leq\|\Sigma\|_2\,\sqrt{\nicefrac{\tau}{\alpha_{\rho}}}$  the rate is
    \begin{equation}
    1- \frac{\varepsilon^2\,\alpha_\rho}{\varepsilon^2\,\alpha_\rho+\tau\,\|\Sigma\|_2^2}\,.
    \end{equation}

    \item In the quadratic cost case $\Sigma=\Id$, if $\mathcal{X}=\mathbb{R}^d$ and  $\rho$ is weakly log-concave of parameters $\alpha_\rho$ and $L$ (as in~(equation eq:weak_log_conc of the paper)), then Sinkhorn's algorithm converges exponentially fast and for $\varepsilon\leq \alpha_\rho^{-1}\sqrt{\tau(\alpha_\rho+L)}$ the rate is
    \begin{equation*}
1-\frac{\varepsilon^2\alpha_\rho^2}{\varepsilon^2\alpha_\rho^2+\tau(\alpha_\rho+L)}\,.
\end{equation*}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition d.fourfunctions of arXiv:2510.07682, 'From tug-of-war to Brownian Boost: \\ explicit ODE solutions for player-funded stochastic-'] We define four real-valued functions $\gamma,\delta,\phi_0,\phi_1$\hfff{fourfunctions}
of the triple $(\kappa,\rho,\beta) \in 
W \times (0,\infty)$, where the trail game parameters $(\kappa,\rho)$ are now accompanied by $\beta \in (0,\infty)$. These are
\begin{eqnarray}
 \gamma(\kappa,\rho,\beta)  & = & \frac{(1-\kappa)\beta^{2\rho}  + 2(1-\rho\kappa)\beta^\rho + 1 +\kappa}{2 (1+\beta^\rho)^2}  \, ,  \\
\delta(\kappa,\rho,\beta) & = & \frac{(1-\kappa)\beta^{2\rho} + 2(1+\rho\kappa) \beta^\rho + 1 + \kappa}{2(1+\beta^\rho)^2} \, ,  \nonumber \\ 
 \phi_0(\kappa,\rho,\beta) & = &  \frac{\beta \Big( (1-\kappa)\beta^{2\rho} + 2(1+\kappa\rho)\beta^\rho  + 1 +\kappa\Big)}{ (1-\kappa)\beta^{2\rho}  + 2(1-\kappa\rho)  \beta^\rho + 1+\kappa}   
\end{eqnarray}
and
\begin{equation}
\phi_1(\kappa,\rho,\beta) \, = \, \frac{\beta \Big( (1+\kappa)\beta^{2\rho} + 2(1-\kappa\rho) \beta^\rho + 1 -\kappa \Big)}{(1+\kappa)\beta^{2\rho} + 2(1+\rho\kappa)\beta^\rho + 1 -  \kappa} \, . 
\end{equation}

[Lemma 56 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] At the $t$th stage inside row $B_a$, whose global stage is
$e=b_a+t-1$ and whose colour is $i_e=a+t-1$, one has
\begin{equation}
 R_{i_e+1}^{(e-1)}
 =p_{e-1,b_a-1}^*R_{a+t}^{\langle a\rangle},
\end{equation}
where $p_{e-1,b_a-1}:X_{e-1}\to X_{b_a-1}$ is the tower projection.

[Lem 39 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma \geq 2$ and $0 \leq s \leq t \leq T$. For every $n \in \mathbb{N}_+$, it holds 
	\begin{align} 
		\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \frac{\Theta(n) K_n}{n \sqrt{n} } \int_s^t \dd r  \sum_{x} \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n})     \bar{\xi} _x^{\alpha}( \eta_r^n )  \bar{\xi} _{x+1}^{\beta}( \eta_r^n )   \Bigg\}^{2} \Bigg] \leq \widetilde{C} \| \nabla H \|^{2}_{2,n} (t-s)^{3/2} [ K_n \sqrt{n} \;]^{2}.
	\end{align}

