[Lemma EHI:l:NoA3example4 of arXiv:2511.08956, '\textbf{Towards a characterization of elliptic Harnack inequality for jump processes}'] Let $X$ be an isotropic unimodal L\'{e}vy jump process on $\mathbb{R}^d$ such that $j(r) \asymp r^{-d-2} \left(\log(r^{-1}) \right)^{-2}$ as $r \to 0^+$. Then
    \begin{equation*}
        m_2(r) \asymp \left(\log(r^{-1})\right)^{-1} \qquad\mbox{as $r \to 0^+$}
    \end{equation*}
    and
    \begin{equation*}
        \lambda(r) \asymp r^{-2}\left(\log(r^{-1})\right)^{-2} \qquad\mbox{as $r \to 0^+$}.
    \end{equation*}

