		\begin{equation}
			\mathbb{P}[	{\scaleobj{1}{\square}} \notin\Lambda(\mathcal{G}, t, C)] \leqslant C \exp\left(- C^{-1}  \size({\scaleobj{1}{\square}})^{\frac{ds}{d+t+s}}\right).
