    = -\frac{1}{(2\pi \mathrm{i})^{2m}} \int_{\vec{\gamma}} \mathrm{d} \boldsymbol{\xi} \int_{\vec{\Gamma}}\mathrm{d} \boldsymbol{\eta}
    \,\, \Pi_{\mathbf{1}}(\boldsymbol\xi, \boldsymbol{\eta})  {\mathsf{F}}^{(\mathbf{1})}_{\mathbf{M},\mathbf{N},\mathbf{T}}(\boldsymbol\xi, \boldsymbol{\eta}) 
\end{equation}
where $\boldsymbol{\xi}= (\xi^1, \cdots, \xi^m) \in {\mathbb C}^m$ and $\boldsymbol{\eta}= (\eta^1, \cdots, \eta^m) \in {\mathbb C}^m$. The contours are 
\begin{equation} 
    \vec{\gamma} = \gamma_1\times \cdots \times \gamma_m, 
    \qquad
    \vec{\Gamma} = \Gamma_1\times \cdots\times \Gamma_m, 
\end{equation}
where $\gamma_1, \cdots, \gamma_m$ are small circles around the point $z=-1$, nested from inside to outside, and $\Gamma_1, \cdots, \Gamma_m$ are small circles around the point $z=0$, also nested from inside to outside, such that all circles are mutually disjoint.

