[Theorem pro:SurgaiProp3.1 of arXiv:2505.11389, '\bf The Poisson Multiplication Formula'] [\bf Proposition 3.1 in [surgailis84]]  Let the above notation prevail, and consider the setting of {\bf Problem A}. Assume that, for all $\sigma \in {\Pi}(k_1,\dots,k_m)$ and for all $A \subseteq \sigma_{\geq 2}$,
    \begin{equation} 
      {H(\sigma, A; |f_1|, \dots, |f_m|) \in L^2(\mu^{|A| + |\sigma_1|}),}
    \end{equation} 
    Then, 
    \begin{equation} 
        \Phi:=\prod_{i=1}^m I_{k_i}(f_i) \in L^2(\mathbb{P})
    \end{equation}
    and 
    \begin{equation} \Phi \in \bigoplus_{q=0}^{K} C_q \end{equation}
    where $C_q$ is the $q$th Wiener chaos of $\eta$. Moreover, the Wiener-It\^o chaos expansion of $\Phi$, written
    \begin{equation}
    \Phi = \mathbb{E}(\Phi) + \sum_{q=1}^K I_q(h_q),
    \end{equation}
    is such that, for all $q=0,1,...,K$,
    \begin{equation}
    h_q =  \sum_{\substack{\sigma \in {\Pi}(k_1,\dots,k_m)\\ A\subseteq \sigma_{\geq 2} \\ |A| +|\sigma_1|=q }} H(\sigma, A; f_1, \dots, f_m) ,
    \end{equation}
    where we have adopted the notation (equation e:sym of the paper) and $h_0= \mathbb{E}[\Phi]$; in particular, $h_K = {\rm sym}(f_1\otimes\cdots\otimes f_m)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2604.14752, 'Strong and weak rates of convergence in the Smoluchowski--Kramers approximation for stocha'] Let Assumptions~\ref{ass:fLip} and \ref{ass:mapping-f} be satisfied. Then for all $h\in H$ and $\kappa\in[0,1)$, there exists a constant $C_{\kappa}(T)\in(0,\infty)$ such that for all $0\le s\le t\le T$ one has 
\begin{equation}
\E[\|\mathcal{D}^{h}_su^{\epsilon,N}(t)\|^2_H]\le C_{\kappa}(T)(t-s)^{-\kappa} \|Q^{\frac12}h\|_{H^{-\kappa}}^2. 
\end{equation}

[Proposition prop:asym of arXiv:2607.19844, 'Binomial probabilities at a fixed distance from the mode:\\ size-biasing and the complete '] For every $k\ge1$,
	\begin{equation}
		\widetilde A_k(t;p)-\widetilde A_k(-t;q)=\frac{\Xi_k(p)\,t^{k}}{k},
	\end{equation}
	and
	\begin{equation}
		\sum_{k\ge1}\frac{\Xi_k(p)\,t^{k}}{k\,N^{k}}=\log\frac{q\,m}{p\,(N-m)} ,
	\end{equation}
	which is exactly the ratio of the two size-bias prefactors $Np/m$ and $Nq/(N-m)$.

[Theorem 13 of arXiv:2608.26288, 'Muon with Finite Newton--Schulz: The Smoothing Benefit in Nonsmooth Nonconvex Optimization'] Suppose~\cref{ass:oracle} and~\cref{ass:smooth} hold, $\lVert G_s\rVert_{\mathrm{op}}\leq G_{\mathrm{op}}$ almost surely for every $s$, and fix $\epsilon>0$.
Running~\cref{alg:generic-o2nc} using \cref{alg:momentum-muon} as its online learner $\mathcal A$ with $1-\beta=\min\{1/2,\epsilon^2/(144r\sigma^2)\}$, $D=(1-\beta)\epsilon/(48\beta L_{\mathrm{op}})$, and depth $q=\left\lceil\log_A\max\left\{1,12rG_{\mathrm{op}}/
\epsilon\right\}\right\rceil$ gives
\begin{equation}
  \E\brk*{\lVert\nabla\mathcal L(\bar W_\tau)\rVert_*}
  \leq\frac{2}{3}\epsilon+O\left(
    \frac{\epsilon}{T}
    +\frac{L_{\mathrm{op}}\Delta_{\mathcal L}}{\epsilon T}
    +\frac{r\sigma^2}{\epsilon T}
    +\frac{r\sigma^2L_{\mathrm{op}}\Delta_{\mathcal L}}{\epsilon^3T}
  \right),

\end{equation}
so $\bar W_\tau$ satisfies $\E\brk*{\lVert\nabla\mathcal L(\bar W_\tau)\rVert_*}\leq\epsilon$ with gradient-oracle complexity
\begin{equation}
  T
  =O\left(
    \max\left\{
      \frac{L_{\mathrm{op}}\Delta_{\mathcal L}}{\epsilon^2},\
      \frac{r\sigma^2}{\epsilon^2},\
      \frac{r\sigma^2 L_{\mathrm{op}}\Delta_{\mathcal L}}{\epsilon^4}
    \right\}
  \right).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] Let  $K : T \times T \to \mathbb{R}$ be a positive semi-definite  kernel. We denote by $v_K : t \in T \mapsto K(t,t) \in \mathbb{R}$ the variance function of the kernel $K$ and by $\sigma_K := \sqrt{v_K}$ its standard deviation function.  
		 \begin{enumerate}
		 	\item The kernel $K$ is said non-singular if its variance function of $K$ takes positive values.
		 	\item If $K$ is non-singular, we denote by $c_K :(s,t) \mapsto \sigma_K^{-1}(s)\sigma_K^{-1}(t)K(s,t)$ its correlation function. Moreover, for every point $t \in T \setminus \{\sup T \}$, we define the decay rate of the correlation of $K$ at point $t$ as the function   $L^K_t : h \in (T-t) \cap \mathbb{R}_+^* \mapsto h^{-1}(1-{c_K}(t,t+h)) \in \mathbb{R}_+$.
		 	\item If for every $t \in T \setminus\{\sup T)\}$, $ \alpha^K(t) := \lim_{h \to 0^+} L_t^K(h)$ exists, then $\alpha^K : t \in T \setminus \{\sup T \} \mapsto \alpha^K(t) \in \mathbb{R}_+$ is well-defined and we call it the instantaneous decorrelation rate of $K.$
		 \end{enumerate}

[Lemma 5 of arXiv:2609.01770, 'Support of Dyson Brownian Motion'] There exists a constant \(c=c(\eps,\sfT,K_0)>0\) such that, for every
\(0\le r\le t\le\sfT\), every \(x\in\mathcal F_t\), and every
\(u\in D_0^{(t,x)}\),
\begin{equation}
  \dist\bigl(\Re z_r(u),S_r\bigr)
  \ge
  \eps-\frac{\eta_*}{2}
  +c\eps(t-r),

\end{equation}
provided \(n\) is sufficiently large.

[Lemma 9 (Endpoint entropy disintegration) of arXiv:2609.02196, 'Schr\"odinger Bridges on Lie Group Manifolds for Probabilistic Intrinsic Generation'] For \(P\ll Q\), \(\Gamma=Y_\#P\), and conditional laws \(P^y,Q^y\),
\begin{equation*}
\KL(P\|Q)=\KL(\Gamma\|\mathcal R_{0T})
+\int\KL(P^y\|Q^y)\,\Gamma(\dd y).
\end{equation*}
Hence, for fixed \(\Gamma\), the unique minimizer is \(P_\Gamma=\int Q^y\Gamma(\dd y)\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 14 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 2$ and $G=(V,E)$, $H=(V',E')$ be two subgraphs of $\mathbb Z^d$ such that $G\subset H$. Then, for every $A\subset V$, every $J\in (\mathbb R^+)^E$, $J'\in (\mathbb R^+)^{E'}$ satisfying $J_e\leq J_e'$ for $e\in E$, and every $\mathsf{h},\mathsf{h}'\in (\mathbb R^+)^{V(H)}$ satisfying $\mathsf{h}_x\leq \mathsf{h}'_x$ for $x\in V$, one has
\begin{equation}
	\langle \sigma_A\rangle_{G,J,\mathsf{h}}\leq \langle \sigma_A\rangle_{H,J',\mathsf{h}'}.
\end{equation}
Moreover, if we further assume that the restriction of $J'$ to $E$ is equal to $J$, then for every $v\in V$, one has
\begin{equation}
	\langle\sigma_v\rangle^+_{H,J'}\leq \langle \sigma_v\rangle_{G,J}^+.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Tsteinm of arXiv:2604.06012, 'Large fringe trees for random trees with given vertex degrees'] Let ${\mathbf{n}}$ and ${\mathbf{m}}$ be two degree statistics.
There exists a universal constant $C$, 
not depending on ${\mathbf{n}}$ or ${\mathbf{m}}$, such 
that if\/ $\mathcal{T}_{\mathbf{n}}\in {\rm Unif}(\mathbb{T}_{\mathbf{n}})$,
then, with $\lambda:=\operatorname{\mathbb E{}} N_{\mathbf{m}}({\mathcal T}_{{\mathbf{n}}})$,
\begin{align}
d_{\mathrm{TV}}\bigl( N_{\mathbf{m}}({\mathcal T}_{{\mathbf{n}}}),\operatorname{Po}(\lambda)\bigr)
\leqslant C\lambda\sum_{i\in\mathcal D({\mathbf{m}})}\frac{m(i)^2}{n(i)}
= 
C\lambda \frac{|{\mathbf{m}}|^2}{|{\mathbf{n}}|}\sum_{i\in\mathcal D({\mathbf{m}})}\frac{p_i({\mathbf{m}})^2}{p_i({\mathbf{n}})}
.\end{align}

