[Lemma 24 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $(\SC, \varrho)$ be a non-empty quasi-metric space.
 Let $\mu$ be a Borel probability measure on $\SC$, and let $s\in (0,\infty)$ and $t\in \RR$.
 Assume that there exist $r_0>0$ and $c>0$ such that
 \begin{equation*}
     \om{\mu} \bigl( \ball(x,r)\bigr) 
    \leq \exp
         \biggl(
           - c
             \cdot \Bigl( \frac{1}{r}\Bigr)^{s}
             \cdot \Bigl( \log_2 \Bigl(\frac{1}{r}\Bigr)\Bigr)^{t}
         \biggr)
    \quad \text{for all $x\in \SC$ and all $r\in (0,r_0)$.}
 \end{equation*}
 Then for every $\eps\in (0,r_0)$ and every $\eps$-net $\SC_{\eps}\subset \SC$ we have
 \begin{equation*}
     \num\SC_{\eps}
     \geq \exp
          \biggl(
            c \cdot \left(\frac{1}{\eps}\right)^s
              \cdot \left(\log_2 \left(\frac{1}{\eps}\right)\right)^{t}
          \biggr).
 \end{equation*}

[Definition 8 (Weighted H\"older space) of arXiv:2608.27433, 'Scalar curvature on K\"ahler blow-ups and systolic inequalities'] For $\ell\ge0$, $0<\alpha<1$, and $\mu\in\R$, define
\begin{equation}

  \norm{f}_{C^{\ell,\alpha}_\mu(\widetilde X)}
  =\sup_{x\in\widetilde X}\tau(x)^{-\mu}
   \norm{f}_{C^{\ell,\alpha}(B_x,\tau(x)^{-2}\omega_\eps)},
\end{equation}
where \(B_x=B_{\omega_\eps}(x,c\tau(x))\) for a fixed and sufficiently small constant $c>0$.  The local H\"older norm is computed using the rescaled metric $\tau(x)^{-2}\omega_\eps$. In particular, $B_x$ has uniformly bounded radius in this rescaled metric. For this choice of $c$, one also has $\tau(y)\simeq\tau(x)$ for every $y\in B_x$, uniformly in $x$ and small $\eps$. Changing $c$, the balls, or the uniformly equivalent smooth representative of $\tau$ changes the norm only by a constant independent of small $\eps$. The resulting Banach space is denoted by $C^{\ell,\alpha}_\mu(\widetilde X)$.

The factor $\tau(x)^{-\mu}$ records the size of the function, while the metric rescaling records the size of its derivatives.  In particular,
\begin{equation}

  \norm{f}_{C^{\ell,\alpha}_\mu}\le C
  \quad\Longrightarrow\quad
  |\nabla^j f|_{\omega_\eps}\le C'\tau^{\mu-j}
  \quad(0\le j\le\ell),
\end{equation}
with the corresponding scaled H\"older bounds.

[Definition of arXiv:2608.22765, 'Learning to Control Coupled-Dynamics Environments with Joint Markov Decision Processes'] A finite JMDP is a tuple $\mathcal J = (\mathcal S, \mathcal A, \gamma, J)$, where $\mathcal S$, $\mathcal A$ and $\gamma$ are as in Definition~(defn:mdp of the paper) and $J$ is a Markov kernel over full one-step counterfactual outcome tables:
\begin{equation}
J(\cdot \mid s) \in \mathcal P\Bigl(\bigl([0, 1] \times \mathcal S \bigr)^{\lvert \mathcal A \rvert} \Bigr).
\end{equation}

At state $s$, the environment draws $\bigl((R^a, S'^{a})\bigr)_{a \in \mathcal A} \sim J (\cdot \mid s)$. We call the action-indexed coordinate $(R^a,S'^a)$ the one-step branch for action $a$. The agent executes one action $A$ and observes the realized branch $(R^A,S'^A)$. The remaining branches remain counterfactual observations.

[Lem tau-double-prime-near-zero-angle of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] For all $\beta>\beta_0$, 
        \begin{align}
            \sup_{\theta \in [-\pi/4,\pi/4]} |\tau''_\beta(\theta)| \le e^{ 2\beta } \,.
        \end{align}
        In the other direction, we have for sufficiently small $c$ (independent of $\beta$), for all $\beta>\beta_0$, 
        \begin{align}
            \inf_{\theta \in [-ce^{ - 2\beta},ce^{- 2\beta}]} \tau_{\beta}''(\theta) \ge \frac{1}{8} e^{2\beta}
        \end{align}

