[Lemma 12 of arXiv:2604.04823, '2604.04823'] Under Assumptions~\ref{a:criticalpts}--\ref{a: nondegeneracy} on~$U$, the following properties hold.
    \begin{enumerate}
        \item 
        $\partial\Omega$ is a $(d-1)$-dimensional manifold of class~$C^5$.

        \item 
        There exists~$r_0 > 0$ such that for any
        \begin{equation}
            x\in \Gamma_{r_0}\defeq \set{y\in \T^d\st \dist(y, \partial\Omega) < r_0}\,,
        \end{equation}
        there exists a unique projection~$\xi(x) \in \partial\Omega$ satisfying
        \begin{equation}
            \dist(x,\partial\Omega) = |x-\xi(x)|\,.
        \end{equation}
        Moreover,
        \begin{equation}
            \xi \in C^4(\Gamma_{r_0}, \partial\Omega)\,.
        \end{equation}

        \item 
        For each~$x\in \partial\Omega$, let~$n(x), t_1(x), \ldots, t_{d-1}(x)$ denote an orthonormal collection consisting of the outward unit normal vector and tangent vectors to~$\partial\Omega$ at~$x$, respectively. 
        At the saddle point~$x=0 \in \partial\Omega$, $n(0)$ lies in the (unstable) eigenspace of~$D^2U(0)$ corresponding to the negative eigenvalue~$-\lambda_u$, and each~$t_i(0)$ lies in the (stable) eigenspace corresponding to the positive eigenvalue~$\lambda_i$, for $1\leq i\leq d-1$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2511.06414, 'Non-uniform Edgeworth expansions for weakly dependent random variables and their applicati'] For all $m$, all the conditions specified in Assumptions \ref{GrowAssum} and \ref{AssStat} are met under Assumption \ref{GenAss}.
 Moreover, 
 \begin{equation}
 \sig_n^2=n\Pi''(0)+H''(0)+O(\del^n).
\end{equation}
Furthermore, for all $j\geq 3$ we have
 \begin{equation}
  \gamma_j(S_n)=n\Pi^{(j)}(0)+H^{(j)}(0)+O(\del^n).
 \end{equation}
 In other words, Assumption \ref{AssStat} is in force with $p_k=\Pi^{(k)}(0)$ and $q_k=H^{(k)}(0)$.

[Lem lm:h-growth-rate of arXiv:2605.21366, 'The Martin boundary of the Directed Landscape'] The following holds on a full probability event.
    Let $\theta\in\mathbb{R}$ and $a_-,a_+\in[-\infty,0]$ with $a_-\vee a_+=0$. Set
    \begin{align}
    \mathfrak h(x,s)=(W^{\theta-}(x,s;x_0,s_0)+a_-)\vee(W^{\theta+}(x,s;x_0,s_0)+a_+)\quad\text{for all $x,s\in\mathbb{R}$.}
    \end{align}
    Then for all $x<y$ and $s$ in $\mathbb{R}$,
    \begin{align}
    W^{\theta-}(y,s;x,s)\le \mathfrak h(y,s)-\mathfrak h(x,s)\le W^{\theta+}(y,s;x,s).
    \end{align}
    Furthermore, for all $s\in\mathbb{R}$
    \[\lim_{y-x\to\infty}(y-x)^{-1}(\mathfrak h(y,s)-\mathfrak h(x,s))=2\theta.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

