[Proposition number_of_simple_tight_closed_geodesics of arXiv:2506.02611, '\textbf{The tight length spectrum of large-genus random hyperbolic surfaces with many cusp'] For any $\mu_g \underset{g \to +\infty}{\rightarrow}\mu_c$ such that $\mu_c - \mu_g = o(g^{-2})$, any disjoint compact intervals $([a_i,b_i])_{1\le i \le n}$ and any $r_1,\cdots,r_n \ge 1$ we have
    \begin{align*}
        \mathbb{E}\bigg[\hat{N}_{g,\mu_g,a_1,b_1,r_1\dots,a_n,b_n,r_n}\bigg] \underset{g \to +\infty}{\overset{}{\longrightarrow}} \lambda_{a_1,b_1}^{r_1}\cdots\lambda_{a_n,b_n}^{r_n}.
    \end{align*}

[Thm 27 (Uniform Harnack Inequality) of arXiv:2511.22156, ''] There exists constants $C_H,\theta>1$ which are independent of $n,r$ such that if $h$ is harmonic in $B(z,r)\cap \tilde{F}_n$, then
\begin{equation}
    \theta^{-1}\leq \frac{h(x)}{h(y)}\leq \theta, \qquad x,y\in B(z,C_H^{-1}r).
\end{equation}
\begin{proof}
If $3^{-m-1}<r\leq 3^{-m}$, then $B(x,\frac{1}{7}r)\subset G_m(x)\subset D_m(x)\subset B(x,9r)$. Then \eqref{e:6.15} follows from Theorem \ref{theorem4.1} by scaling.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theo 11 of arXiv:2608.30357, 'Mean convergence for Banach space-valued random elements indexed in measure spaces'] Let $\{K_n : n \ge 1\} \subseteq \cK(\cX)$ and let $p \in [1, \infty)$. Assume that $\{X^n_s : s \in S_n, n \ge 1\}$ is $(\nu_n)$-$\CUI(p)$ w.r.t. $\{K_n\}$. Assume for any $n \ge 1$, there exists $D_n \in \cS_n \otimes \cS_n$ such that:
	\begin{enumerate}[\rm (a)]
		\item  $\lim_{n \to \infty} N(K_n, \ep)^{1 - (\frac{1}{p} \wedge \frac{1}{2})} \lt\|K_n\rt\| ((\nu_n \otimes \nu_n) (D_n))^{\frac{1}{p} \wedge \frac{1}{2}} = 0$ for all $\ep >0$,

		\item  $X^n_s$ and $X^n_t$ are diagonally negatively dependent for $(\nu_n \otimes \nu_n)$-a.e.\ $(s, t) \in (S_n \times S_n) \backslash D_n$.
	\end{enumerate}
	Then, we have 
	\begin{align}
		\lim_{n \to \infty} \bE \lt\| \int_{S_n} \lt(X^n_s - \bE X^n_s\rt) \nu_n(\od s) \rt\|^p = 0,
	\end{align}
	and in particular, $\int_{S_n} \lt(X^n_s - \bE X^n_s\rt) \nu_n(\od s)  \to 0$ in probability as $n \to \infty$.

