body:
[Definition flow of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Given a starting time $t_0\in \mathbb{R}$ and initial values $(z_{t_0},\Lambda_{t_0})$, we define flows of $z$ and $\Lambda$ as 
\begin{equation} \frac{\mathrm{d}}{\mathrm{d} t}z_t=-\frac12 z_t- \langle M_t\rangle,\quad   \frac{\mathrm{d}}{\mathrm{d} t}\Lambda_t=-\frac12 \Lambda_t,\quad t\ge t_0, 
\end{equation}
where $M_t:= M(z_t, \Lambda_t)$ is the solution to (equation def_M of the paper) with $z$ and $\Lambda$ replaced by $z_t$ and $\Lambda_t$. Let $t_c:=\inf\{t\ge t_0: \im z_{t_c}=0\}$ be the first time $\im z_t$ vanishes. We also introduce the function $Z:\mathbb{C}\times \mathbb{C}^{DN\times DN}\to\mathbb{C}^{DN\times DN} $ as $Z(z ,\Lambda ):=z I - \Lambda$ and abbreviate that $Z_t:=Z(z_t , \Lambda_t )$. Note that $Z_t$ satisfies
\begin{equation}
 \frac{\mathrm{d}}{\mathrm{d} t}Z_t=-\frac12 Z_t- m_t,\quad \text{where}\quad m_t:=\langle M_t\rangle .
\end{equation}

Given the initial random matrix $H_{t_0}$ satisfying (main_assm of the paper) with diagonal blocks $(H_a)_{t_0}$, $a\in [\![{D}]\!]$, we define the flow $H_t$ as a $DN\times DN$ random matrix with diagonal blocks $(H_a)_{t}$ being matrix-valued OU processes 
\begin{equation} \mathrm{d} (H_a)_t = -\frac12(H_a)_t\mathrm{d} t + \frac{1}{\sqrt{N}}\mathrm{d} (B_a)_t,\end{equation}
where $(B_a)_t$, $a\in [\![{D}]\!]$, are independent complex Hermitian matrix Brownian motions (i.e., $\sqrt{2} \re (B_a)_{ij}$ and $ \sqrt{2} \im (B_a)_{i j}$, $i<j$, and $(B_a)_{i i}$ are independent standard Brownian motions and $(B_a)_{j i}=(\overline{B}_a)_{i j}$). In particular, for each $t\ge t_0$, $(H_a)_t$ has the same law as  
\begin{equation}
e^{-(t-t_0)/2}\cdot  H_a^{(0)}+ \sqrt{1-e^{-(t-t_0)}}\cdot H_a^{(g)},
\end{equation}
where $H_a^{(g)}$, $a\in [\![{D}]\!]$, are i.i.d.~GUE. Then, we define the Green's function flow 
$G_t=\left(H_t+\Lambda_t-z_t\right)^{-1}.$
Finally, with $(z_{i})_t$, $i\in \{1,2,3\}$, $\Lambda_t$, $H_t$, and $M_t$, we can define 
$$ \widehat M_{(1,2),t}=\widehat M((z_{1})_t,(z_{2})_t,\Lambda_t),\quad L_{(1,2),t}=L((z_{1})_t,(z_{2})_t,H_t, \Lambda_t),\quad K_{(1,2),t}=K((z_{1})_t,(z_{2})_t,\Lambda_t)$$ 
as in (def_wtM of the paper), and define
$$L_{(1,2,3),t}=L((z_{1})_t, (z_{2})_t, (z_{3})_t, H_t, \Lambda_t),\quad K_{(1,2,3),t}=K((z_{1})_t, (z_{2})_t, (z_{3})_t, \Lambda_t)$$ 
as in (defLK3 of the paper).

[Theorem thm:empb of arXiv:2411.09516, 'Sharp Matrix Empirical Bernstein Inequalities\footnote{NeurIPS 2025 Poster}'] Let $\{ \mathbf{X} _n\}$ be an adapted sequence of $\mathcal{S}_d$-valued random matrices with conditional means $ \mathbb E  ( \mathbf{X} _n|\mathcal{F}_{n-1}) =  \mathbf{M} _n$. Let $\{ \widehat \mathbf{X} _n \}$ be a sequence of predictable and integrable $\mathcal{S}_d$-valued random matrices such that $\lambda_{\min}( \mathbf{X} _n - \widehat{ \mathbf{X} }_n) \geqslant -1$ almost surely.
     Then, for any 

     predictable $(0,1)$-valued sequence $\{\gamma_n\}$, 
     \begin{equation}
    L_n^{\mathsf{meb2}} = \mathrm{tr} \exp\left( \sum_{i=1}^n \gamma_i( \mathbf{X} _i -  \mathbf{M} _i) - \sum_{i=1}^n \psi_{\mathrm{E}}(\gamma_i) ( \mathbf{X} _i - \widehat{ \mathbf{X} }_i)^2 \right)
\end{equation}
is a supermartingale. Denote by $\overline{ \mathbf{X} }_{n}^\gamma$ the weighted average
$
    \frac{\gamma_1  \mathbf{X} _1 + \dots + \gamma_n  \mathbf{X} _n }{\gamma_1 + \dots + \gamma_n}$
w.r.t.\ the positive weight sequence $\{ \gamma_n \}$. Then, for any $\alpha\in(0,1)$,
\begin{equation}
          \mathbb P \left(  \text{there exists }n\geqslant 1, \;    \lambda_{\max} \left( \overline{ \mathbf{X} }_n^\gamma - \overline{ \mathbf{M} }_n^\gamma \right) \geqslant \frac{  \log(d/\alpha) +\lambda_{\max}\left( \sum_{i=1}^n \psi_{\mathrm{E}}(\gamma_i) ( \mathbf{X} _i - \widehat{ \mathbf{X} }_i)^2 \right)  }{\gamma_1 + \dots + \gamma_n} \right) \leqslant \alpha;
     \end{equation}
and for any stopping time $\tau$,  $\alpha\in(0,1)$, 

     \begin{equation}
          \mathbb P \left( \lambda_{\max} \left( \overline{ \mathbf{X} }_\tau^\gamma - \overline{ \mathbf{M} }_\tau^\gamma \right) \geqslant \frac{  \log(d/\alpha) +\lambda_{\max}\left( \sum_{i=1}^\tau \psi_{\mathrm{E}}(\gamma_i) ( \mathbf{X} _i - \widehat{ \mathbf{X} }_i)^2 \right)  }{\gamma_1 + \dots + \gamma_\tau} \right) \leqslant \alpha.
     \end{equation}

