[Corollary cor:IBJ-scalar of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The one-point Fredholm determinant
$F_{t, a, n} = \det(I - K_{t, a, n})$ satisfies
\begin{align}
&\frac{q_{n+1} p_{t+1}}{1 + q_{n+1} p_{t+1}}
F_{t, a, n+1}F_{t+1, a+2, n}
+ \frac{1}{1 + q_{n+1} p_{t+1}}
F_{t+1, a+1, n}F_{t, a+1, n+1} \nonumber \\
&\qquad - F_{t, a+1, n}F_{t+1, a+1, n+1} = 0,

\end{align}
at every $(t, a, n)$ with $a < y_{n+1} + t - 1$.

[Definition eq:rhoK of arXiv:2411.04116, 'Poisson genericity in numeration systems with exponentially mixing probabilities'] Let $\mu$ be an invariant exponentially $\psi$-mixing  measure on $\Omega^\mathbb N$. 
The measure  $\mu$  has a contraction ratio $\rho\in (0,1)$ 
if there is constant $K > 0$ such that 
    for every $k\in \mathbb N$, for every $ w\in\Omega^k$,
\begin{equation}

        \mu_k(w) \leq K {\rho}^k.
\end{equation}

[Proposition eq:bounded_advection of arXiv:2604.23981, 'Accelerating sampling via asymptotic relaxation enhancing flows'] Let $v$ be a relaxation enhancing flow, i.e., $\dot{\mathcal{I}}=\emptyset$. Suppose that $\{v_n\}$ is a sequence of flows with finite energies that converges to $v$ weakly in $L^2(\pi)$ and that
\begin{equation}
\|v_n\cdot\nabla\phi\|_{L^2(\pi)}\le C\|\phi\|_{H^1(\pi)}
\end{equation}
Then,
\[
\lim_{n\to\infty}r(v_n)=\infty.
\]

[Lemma lem:y_SI-ER of arXiv:2411.12076, 'Explicit solutions of the SI and Bass models on sparse Erd\H{o}s-R\'enyi and regular netwo'] Let  
		$y_{\rm SI}(t)$ be the solution of~(equation eq:y-ER-SI of the paper). Then 
		\begin{subequations}
			\begin{equation}

				\frac{dy_{\rm SI}}{dt}(t)<0, \qquad t>0. 
			\end{equation}
			Let $ y_{\rm SI}^{\infty}:=\lim\limits_{t \to \infty} y_{\rm SI}$. Then $0< y_{\rm SI}^{\infty}<1$. Moreover, 
			$y_{\rm SI}^{\infty}$  
			is the unique root in~$(0, 1)$ of the equation
			\begin{equation}

				y_{\rm SI}^{\infty} = (1-I^0)e^{-\lambda(1-y_{\rm SI}^{\infty})}.
			\end{equation}
		\end{subequations}

