[Lemma 10 (Exact orthogonal replica identities) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Let $E$ and $H$ be real Hilbert spaces, let
$J_1,\ldots,J_N:E\to H$ be isometries with mutually orthogonal ranges,
and let $q\ge1$.  For $a\in E^{\odot q}$ define
\begin{equation}
 R_N^{(q)}a
 =\frac1{\sqrt N}\sum_{j=1}^NJ_j^{\odot q}a.

\end{equation}
Then, for $a,b\in E^{\odot q}$ and $1\le r<q$,
\begin{align}
 \ip{R_N^{(q)}a}{R_N^{(q)}b}
 &=\ip{a}{b},
 \\
 \norm{R_N^{(q)}a\otimes_rR_N^{(q)}b}
 &=\frac1{\sqrt N}\norm{a\otimes_rb},
 \\
 \norm{L_{R_N^{(q)}a,r}}_{\op}
 &=\frac1{\sqrt N}\norm{L_{a,r}}_{\op}.

\end{align}

