body:
[Lemma 9 of arXiv:2607.25986, 'Asymptotics of a two-species particle system associated to the doubly parabolic Keller-Seg'] Let $F: \R_+ \times \R^2 \to \R$ be of class $C^{2}_b(\R_+ \times \R^2)$. For all $u\geq 0$,
\begin{align*}
\E \Big[ \int_0^u F(u-s, R^{1,2}_{u,s}) \dd s \Big ] =& \E \Big[ \int_0^u F(0, R^{1,2}_{s,s})
\dd s \Big ] + \E \Big[\int_0^u \int_0^t (\partial_t F + \Delta F) (t-s,R^{1,2}_{t,s})  \dd s \dd t \Big]\\
&+ \chi \E \Big[\int_0^u \Big(\int_0^t \nabla F (t-s, R_{t,s}^{1,2})  \dd s \Big) \cdot D^{1}_t \dd t \Big].
\end{align*}

[Lem 41 of arXiv:2608.26068, 'All once-extended 3D TQFTs are Reshetikhin--Turaev theories'] Let $K,\ol{K}$ be ribbon-colourings that extend $\mathbf{K}$, so we have an inclusion $\iota: \mathcal{V}_{K}(\Gamma) \otimes \mathcal{V}_{\ol{K}}(-\Gamma) \rightarrow \mathcal{V}_\mathbf{K}(\Gamma) \otimes \mathcal{V}_\mathbf{K}(-\Gamma)$ of vector spaces.
    \begin{enumerate}
        \item If $K=\ol{K}$, the following diagram commutes:
        \begin{equation}
            \begin{tikzcd}
                {\mathcal{V}_{K}(\Gamma) \otimes \mathcal{V}_{K}(-\Gamma)} && {k}\\
                \\
                {\mathcal{V}_{\mathbf{K}_{/T}}(\Gamma/T) \otimes \mathcal{V}_{\mathbf{K}_{/T}}(-\Gamma/T)} && {k}
                \arrow["{\langle\cdot,\cdot\rangle_\Gamma\circ\iota}", from=1-1, to=1-3]
                \arrow["{(\bigcirc\otimes\bigcirc)\circ\iota}", from=1-1, to=3-1]
                \arrow["{\langle\cdot,\cdot\rangle_{\Gamma/T}}", from=3-1, to=3-3]
                \arrow["{\cdot\dim(K|_T)^{-1}}", from=1-3, to=3-3]
            \end{tikzcd}
        \end{equation}
        \item If $K\ne\ol{K}$, then we instead have $$\langle\cdot,\cdot\rangle_{\Gamma/T} \circ (\bigcirc\otimes\bigcirc) \circ \iota = \langle\cdot,\cdot\rangle_\Gamma\circ\iota = 0.$$
    \end{enumerate}

[Lemma mix line and cycles of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $C_{1},\cdots,C_{K}$ be test-graphs whose underlying graphs are cycles of length $c_{1},\cdots,c_{K}$ respectively. Let $L_{1},\cdots,L_{M}$ be test-graphs whose underlying graphs are lines of length $l_{1},\cdots,l_{M}$ respectively. We have the following equality,
        \begin{multline}
            \mathbb{E}\left[\prod_{k=1}^{K}\mathrm{Tr}^{0}(C_{k}(V_{N}))\prod_{m=1}^{M}\mathrm{Tr}^{0}(L_{m}(V_{N}))\right]=\\mathbb{N}^{K+M}\mathbb{E}\left[\prod_{k=1}^{K}\frac{c_{k}\eta_{c_{k}}}{N}\prod_{m=1}^{M}\left(1-\frac{\sum_{j=1}^{l_{m}-1}j\eta_{j}}{N}\right)\right]
        \end{multline}
        where $L:=\mathrm{max}\{c_{1},\cdots,c_{K},l_{1},\cdots,l_{M}\}$ and for all $1\leq j\leq L$, let $\eta_{j}$ is the number of cycles of length $j$ of $V_{N}$

[Lemma doublestep of arXiv:2412.04284, 'Approximately jumping towards the Origin'] Let $k \equiv -1$ modulo 4. Then if $z_k$ exists and $|z_k|<\sqrt{2}$, we have at least one of the following:
    \begin{itemize}
        \item[1.] $z_k=z_{k+2}$
        \item[2.] $z_{k+2}=z_{k+4}$.
    \end{itemize}

[Lemma 12 of arXiv:2607.09246, 'Scaling limit of 1+1 dimensional directed polymer with power-law tail and spatial correlat'] Assume that conditions \textbf{(A)} and \textbf{(B)} hold.
Assume moreover that \(\alpha>2\). Choose and fix
$q\in(2,\min\{\alpha,3\})$ such that \(\mathbb E_{\mathbb Q}[|\xi|^q]<\infty\).
We also use the parameter choices for \(\beta_N\) in \eqref{beta_N}
and \(k_N\) in \eqref{k_N}. Then, for every fixed \(m\ge1\),
the truncated chaos expansions \(\mathfrak Z_N^{\le m}(\beta_N;\overline\omega)\)
and \(\mathfrak Z_N^{\le m}(\beta_N;\mu)\) possess the same limiting
distribution as \(N\to\infty\). That is, for any test function
\(f\in C_b^{(3)}(\mathbb R)\),
\begin{equation}
\lim_{N\to\infty}
\left|
\mathbb E_{\mathbb Q}
\left[f\left(\mathfrak Z_N^{\le m}(\beta_N;\overline\omega)\right)\right]
-
\mathbb E_{\mathbb Q}
\left[f\left(\mathfrak Z_N^{\le m}(\beta_N;\mu)\right)\right]
\right|=0 .

\end{equation}

[Proposition 8 of arXiv:2605.28801, 'Microscopic Weak Selection Principle for the Logistic Branching Brownian Motion with selec'] The process $(\boldsymbol{Z}^c(t))_{t\geq 0}$ has an unique stationary distribution $\boldsymbol{\nu}^c$ on $\mathbb{E}$, such that 
	\[\boldsymbol{\nu}^c(dx_1,\cdots,dx_n,n) = \boldsymbol{\nu}^{c,n}(dx_1,\cdots,dx_n)\pi(n),\]
	such that $\int_{\mathbb{R}^n}  \boldsymbol{\nu}^{c,n}(dx_1,\cdots,dx_n)=1$ for each $n\in \mathbb{N}$. In addition, for any initial distribution $\boldsymbol{\psi}_{\pi}$,
	\begin{equation}
		\lim_{t \rightarrow\infty} \| P_{\boldsymbol{\psi}_{\pi}} \left(\boldsymbol{Z}^c(t) \in \cdot\right) - \boldsymbol{\nu}^c(\cdot)\|_{TV} =0.
	\end{equation}

[Lemma 6 of arXiv:2606.11142, 'Strong invariance principles for diffusions, Markov chains and their perturbations.'] The following estimate holds for the densities on the grid:
\begin{equation*}
\int_{\mathbb{R}^{m \times d}} |P^m_x(z) - P^m_{\epsilon,x}(z)| dz \le C m \Delta_{\epsilon,\gamma,q},
\end{equation*}
where $z = (z_1, \dots, z_m)$ and $dz = dz_1 \dots dz_m$.

