[Lemma lem:g(k)-cauchy-schwarz of arXiv:2602.14998, 'Random geometric graphs with smooth kernels: sharp detection threshold and a spectral conj'] Let $g(k)$ and $a_{\boldsymbol{\ell}}$ be defined in ~((eq:def-g(k) of the paper)) and ~((eq:def-a-ell of the paper)) respectively. 
Also recall the notation $\ell_i \triangleq \sum_{j\neq i} \ell_{ij}$ for $\boldsymbol{\ell} = (\ell_{ij})_{i \ne j}$ where $0 \le \ell_{ij} \le L$.  
We have 
$$
g(k) \le \Big( \frac{e}{e-1} \Big)^k  \cdot 
\sum_{\boldsymbol \ell }
\beta_{\boldsymbol{\ell}} a^2_{\boldsymbol \ell} M_{\boldsymbol{\ell}} ,
$$
where
$$
\beta_{\boldsymbol \ell} \triangleq 
e^{\sum_{i=1}^k \ell_i} \cdot \left(\sum_{i=1}^k \ell_i -1\right)!! \cdot \frac{\prod_{i<j} \ell_{ij}!}{\prod_{i=1}^k \ell_i! } 
$$
and 
\begin{equation}
M_{\boldsymbol{\ell}}
\triangleq \mathbb{E}_{A}
\pth{\mathbb{E}_{x_1,\ldots,x_k|A}
\qth{ \prod_{1 \le i<j \le k} 
\iprod{x_i}{x_j}^{\ell_{ij}}}
}^2 .

\end{equation}

