body:
[Definition Dynamic Programming Principle in the case of infinite horizon of arXiv:2608.08299, 'Non-linear optimal stopping with Bermudan strategies: the infinite horizon case'] We say that an admissible non-negative family $\phi$ satisfies the Dynamic Programming Principle (abridged DPP) in the case of infinite horizon, if the following property holds true: \\
For all $k \in \mathbb{N}$, 
\begin{equation}
    \phi(\theta_k)=\max\left(\xi(\theta_k), \rho_{\theta_k,\theta_{k+1}}[\phi(\theta_{k+1})]\right).
\end{equation}

[Theorem main_theorem of arXiv:2609.00973, 'The Vlasov-Maxwell point charge system : study of the spherically symmetric case'] Let $\mathcal{W}$ be a set of spherically symmetric functions defined by 
    \begin{equation}
        \mathcal{W}:=\{f\in L^1(\R^*_+\times\R\times \R_+)\,|\, \partial_rf\in L^1,\,\partial_u f\in L^1\}.
    \end{equation}
    There exists $\varepsilon^* > 0$ such that for any $0 < \varepsilon_0 < \varepsilon^*$ and any $f_0 \in \mathcal{W}$ satisfying
    \begin{equation}
        \|(r^{-65}+r^{35}+|u|^{35}+\ell^{45})(f_0+|\partial_r f_0|+|\partial_uf_0|)\|_{L^1}\leq \varepsilon_0,
    \end{equation}
    there exists a global solution $f \in C^1_t L^1 \cap C^0_t \mathcal{W}$ to (equation equation_VM_pc_radial_case of the paper), arising from the initial data $f(t=0,\cdot)=f_0$. Moreover, this solution exhibits a modified scattering dynamic. Namely, there exist $\mathcal{R}, \mathcal{U}$ and $f_\infty \in L^1$ such that
    \begin{equation*}
    f(t,\mathcal{R}(t,r,u,\ell),\mathcal{U}(t,r,u,\ell),\ell) \xrightarrow[t \to +\infty]{L^1(\R^*_+\times\R\times \R_+)} f_\infty(r,u,\ell).
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm meso-main of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Assume that the edge weights satisfy Assumption~(ass:weight of the paper). Fix $\mathsf{u}\in(0,1/2)$ and let $T_n^{(\ell)}(0,\mathsf{u}_n)$ be the first-passage time defined in~(equation eq:fixed-target-Tn of the paper). The following holds.
\begin{enumeratea}
 \item  When $1\ll \ell\log\ell \ll n$, we have
 \begin{align} 
 \frac{\mathfrak{a}_\ell\ell}{\mathsf{u}_n} \cdot T_n^{(\ell)}(0,\mathsf{u}_n)
 \stackrel{\pr}{\to}
 \frac1{\mathsf{v}^\star}
 \text{ and }
 \frac{\mathfrak{a}_\ell\ell}{\mathsf{u}_n} \cdot\E T_n^{(\ell)}(0,\mathsf{u}_n)
 \to \frac{1}{\mathsf{v}^\star} \text{ as }n\to\infty,
\end{align}
where $\mathsf{v}^\star\in (0,\infty)$ is the constant defined in~(equation def:vstar of the paper).

 \item  When $1\ll\ell\ll n$, there is a constant $C=C(\theta,\mathsf{u})\in (0,\infty)$ such that, for all large $n$,
\begin{align} 
 C^{-1}\cdot \left( \frac n{\ell^{2+2/\theta}} \vee\frac1{\ell^{2/\theta}} \right)
 \leqslant \var\bigl(T_n^{(\ell)}(0,\mathsf{u}_n)\bigr)
 \leqslant C\cdot \frac{n}{\ell^{1+2/\theta}}\cdot (\log\ell)^{2\gth}.
\end{align}

 \item  When $\ell\ll n^{1/4}(\log n)^{-3\gth/2}$, we have
 \begin{align}
 \frac{T_n^{(\ell)}(0,\mathsf{u}_n)-\E T_n^{(\ell)}(0,\mathsf{u}_n)}{\sqrt{\var\bigl(T_n^{(\ell)}(0,\mathsf{u}_n)\bigr)}}
 \Rightarrow\N(0,1)\text{ as } n\to\infty.
\end{align}
\end{enumeratea} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 12 of arXiv:2506.08910, 'Critical points of random polynomials and finite free cumulants'] Let $\tilde{p}_{\ell,N}$ be as in \eqref{eq:shifted der}. Then, for any $\ell\in\N$ \begin{equation}
		\sqrt{N}\left[\boldsymbol{\kappa}^{\ell}\left(\tilde{p}_{\ell,N}\right)-(0,\ell,0,\dots,0)^{\mathrm{T}}\right]\Rightarrow \mathcal{N}(0,\Sigma^{(\ell)}),
	\end{equation} where the only non-zero entry of $\Sigma^{(\ell)}$ is the $(2,2)$-entry $\ell^2(m_{4}(\mu)-1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] For  $K>1$
and $t_0, t_1$ given by \eqref{trt}
the $K$-variate extreme-value processes
\begin{equation}
((\widehat{M}_{n,n-i+1}(t))_{i=1}^K,~ t\in[t_0,t_1]) ~~~{\rm and~~~}   ((\widehat{M}_{n,i}(t))_{i=1}^K,~ t\in[t_0,t_1])
\end{equation}
are asymptotically independent.

[Theorem 1 of arXiv:2608.29298, 'On Hypersurfaces of Space Forms that are Gradient Yamabe Solitons'] Let $\left(M^{n-1}, g, f, \rho\right)$ be a complete, oriented, nontrivial Yamabe gradient soliton isometrically immersed into a space form $\left(\overline{M}^n(C), \overline{g}\right), n\ge 6$, with constant scalar curvature. If $f$ has no critical point and a regular level set $\Sigma^{n-2}$ of $f$ has the scalar curvature $R^{\Sigma}>max\left\{(n-2)(n-3)C, 0\right\}$ with
         \begin{equation}
             \Tr\left(\left(\Phi^{\Sigma}_{\overline{M}}\right)^3\right)\ge -\frac{n-2(k+1)}{\sqrt{(n-2)k(n-k-2)}} \left|\Phi^{\Sigma}_{\overline{M}}\right|^3, \hspace{2mm}\text{for some integer}\hspace{2mm} 1\le k\le n-4,
         \end{equation}
         where $\Phi^{\Sigma}_{\overline{M}}$ defined in \eqref{FE27} is the traceless part of the second fundamental form of the isometric immersion $\Sigma^{n-2} \hookrightarrow \overline{M}^n(C)$.
         Then,
             \begin{enumerate}
                 \item either $\sup\limits_{\Sigma}  \left|\Phi^{\Sigma}_{\overline{M}}\right|^2=0$ and $(M^{n-1}, g)$ is isometric to a Riemannian product of $\mathbb{R}$ and a totally umbilical submanifold of $\overline{M}^n(C)$; 
                 \item or, there exists a unique $\alpha \left(R^{\Sigma}, n-2, k, C\right)>0$ such that
                 \begin{equation*}
                     \sup_{\Sigma}\left|\Phi^{\Sigma}_{\overline{M}}\right|^2\ge \alpha \left(R^{\Sigma}, n-2, k, C\right).
                 \end{equation*}
                  Moreover, the equality $\sup\limits_{\Sigma}\left|\Phi^{\Sigma}_{\overline{M}}\right|^2= \alpha \left(R^{\Sigma}, n-2, k, C\right)$ holds and is attained at some point of $\Sigma^{n-2}$ if, and only if, $\left(M^{n-1}, g\right)$ is isometric to a Riemannian product of $\mathbb{R}$ and a parallel submanifold of $\overline{M}^n(C)$.


             \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem omega of arXiv:2504.19942, 'The edge-averaging process on graphs \\ with random initial opinions'] Let $G=(V,E)$ be either the $n$-cycle or the infinite path $\mathbb Z$ and let $o\in V$. Suppose that $t_*=\min(t,n^2)\ge 120$ and let $J$ be the set of vertices in $V$ whose distance from $o$ is less than $4\sqrt{t}$. Define the event 
\begin{equation}
    \Omega := \big\{ m_t(J) \ge 1/2,  \  Q_t \le 6t_*^{-1/2} \big\},
\end{equation}
where $m_t(J):=\sum _{v\in J} m_t(v)$. Then $\mathbb P (\Omega ) \ge 4/5$.

