body:
[Lemma lemmadepthprobabilitycolumns of arXiv:2607.06952, 'Universality for cokernels of partially random integral matrices'] Let $X$ be $(\varepsilon,\tau,A)$-balanced. Let $F \in \Sur(V,G)$ have depth $D > 1$ for $X$. Then, \[\mathbb{P}(FX=0) \leq (D|G|^{-1} + \exp(-\varepsilon\log(n)^{\lambda}/a^2)) \cdot \begin{cases}
        (1-\varepsilon) &\text{if $F$ has proper robust image for $X$.} \\
        1 &\text{otherwise.} 
    \end{cases}\]

[Corollary 3 (Terminal-spine bias) of arXiv:2607.16833, 'Dynamical Equations for Poisson Galton--Watson Trees and Component Densities of Sparse Inh'] If $0\leq u<1$ and $u\rho<1$, then $G_{x,u}^{*}$ and $G_u$ are finite almost surely and
\begin{equation}
 \frac{\dd\bP_{x,u}^{*}}{\dd\bP_{x,u}}(t)
 =H_{x,u}^{*}(t)
 :=\frac{1-u}{\varphi(x)}
   \sum_{z\in t}\rho^{-|z|}\varphi(x_z).
\end{equation}
When $\rho=1$, the bias is $(1-u)\ip{\Lambda_t}{\varphi}/\varphi(x)$.

[Definition 4 of arXiv:2608.04937, '2608.04937'] We say that a triple $(Y,Z,R)$ of $\mathbb{F}$-adapted processes is a solution to the mean-field reflected backward stochastic differential equation on $[0,T]$ with generator $f$, coefficient $X$, terminal function $h$, lower barrier $L$, and upper barrier $U$ (MF-RBSDE$^T(h,f,X,L,U)$ for short) if
\begin{enumerate}
\item[(a)] $Y$ is a regulated process and $Z\in\mathcal{H}_{\mathbb{F}}(0,T)$,
\item[(b)] $R\in\mathcal{V}_{0,\mathbb{F}}(0,T)$, $L_t\le Y_t\le U_t$, $t\in[0,T]$, and
\begin{equation*}
\begin{split}
&\int^T_0(Y_{r-}-\overrightarrow{L}_r)\,dR^{+,*}_r+\sum_{0\le r<T}(Y_r-L_r)\Delta^+R^+_r\\&
=\int^T_0(\underrightarrow{U}_r-Y_{r-})\,dR^{-,*}_r+\sum_{0\le r<T}(U_r-Y_r)\Delta^+R^-_r=0,
\end{split}
\end{equation*}
where $R=R^+-R^-$ is the Jordan decomposition of $R$,
\item[(c)] $\int^T_0|f(r,X_r,Y_r,Z_r,\mathcal{L}(X_r,Y_r,Z_r))|\,dr<\infty$,
\item[(d)]
\begin{equation*}
\begin{split}
Y_t&=h(X_T,\mathcal{L}(X_T))+\int^{T}_t f(r,X_r,Y_r,Z_r,\mathcal{L}(X_r,Y_r,Z_r))\,dr+R_T-R_t\\
&\quad-\int^{T}_t Z_r\,dW_r,\,t\in[0,T].
\end{split}
\end{equation*}
\end{enumerate}

[Lemma lem: hitting time the fruit bounded in expectation of arXiv:2509.23069, 'Every cutoff profile is possible'] Let $(k, \boldsymbol{\ell},\boldsymbol{\rho}) \in {\ensuremath{\mathcal P}} $. Let $\varepsilon\in (0,1/3)$. Let $(X_t)_{t\geq 0} = (X_t^{(\varepsilon)})_{t\geq 0} $ be the FIT Markov chain with parameters $(k, \boldsymbol{\ell},\boldsymbol{\rho}, \varepsilon)$. There exists a constant $C_0 = C_0(\ell_0)$ such that 
\begin{equation}
    \max_{x\in S} {\ensuremath{\mathbb E}} _x \left[ T_z \right] \leq C_0.
\end{equation}

[Theorem thm:sineb_corr of arXiv:2509.15446, 'On the pair correlation function of the $\Sineb$ process'] Let $\beta>0$, $\lambda>0$, and consider the unique strong solution $\alpha_{\lambda}(u)$ of the following stochastic differential equation on $(-\infty,0]$:
    \begin{align}

	d\alpha_\lambda = \lambda\tfrac{\beta}{4}e^{\frac{\beta}{4}u} du -\frac{\beta}{2} \sin(\alpha_\lambda(u)) du+ \Re[(e^{-i\alpha_\lambda(u)}-1)dZ], \qquad \lim_{u\to -\infty} \alpha_\lambda(u)=0. 
\end{align}
    The  pair correlation function of the $\operatorname{Sine}_{\beta}$ process is given by
\begin{align}
        \rho_\beta^{(2)}(0,\lambda)=\frac{1}{4\pi^2}+\frac{1}{2\pi^2}\sum_{k=1}^\infty  \frac{(-\beta/2)^{\uparrow k}}{(1+\beta/2)^{\uparrow k}} E[\cos(k \alpha_\lambda(0)].
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Coro 9 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Let $h\in Z\hat C(\Delta_T^3;B_\alpha)$ and define
\begin{equation}

h^\tau := \Theta_\tau h, \quad  \forall\tau\in[0,T].
\end{equation}
Then $h^\tau \in ZC_3(\Delta_\tau;B_\alpha)$. Moreover, for every $\tau\in[0,T]$ there exists $b^\tau\in C(\Delta_\tau^2; B_\alpha)$ such that $\delta b^\tau = h^\tau$.

[Lemma 15 of arXiv:2608.29143, 'Least Variability in a Polynomial-Square Class\\ of Rational Kernels'] Define
\begin{equation}
 w_n(s)=\exp\left(-\frac{\e^s}{2}\right)\Lag_n(\e^s),
 \qquad s\in\R.
\end{equation}
Then, the zeros of $w_n$ are $z_{1,n},\ldots,z_{n,n}$ and
\begin{equation}
 w_n''(s)+W_n(s)w_n(s)=0,
 \qquad
 W_n(s)=\left(n+\frac12\right)\e^s-\frac{\e^{2s}}4.
\end{equation}
Moreover,
\begin{equation}
 W_n(s)\leq\left(n+\frac12\right)^2,
\end{equation}
with equality only when $\e^s=2n+1$.

