[Lem 14 of arXiv:2608.21312, 'Interface between competing random walks on a cycle'] For $n\ge0$ and $d\ge1$, let $Y_{U,n}$ be the shifted ATD walk as in \eqref{eq:shifted ATD walk} with $U=\tau^{(2)}_{0}$.
Suppose that $m\ge1$ and $2m<N-d.$ Then
\begin{align*}
&\pr\left(\exists n\in\{m+1,\ldots,2m\}:(n-1,n)\in\cI_{\cA_{\rm long}}\right)\\
&\qquad\ge\pr\left(\exists n\in\{m+1,\ldots,2m\}:Y_{U,n-1}Y_{U,n}<0\right)-\frac{4m+d}{N}.
\end{align*}

[Lemma lem_b of arXiv:2609.01250, 'Global regularity for 2D gravity water waves with two retreating point vortices'] We have
    \begin{equation}
        \left\lVertb\right\rVert_{L^2}\lesssim\frac{\epsilon^2}{t^{\frac{1}{2}}}+\frac{\lambda}{H^{\frac{3}{2}}},
    \end{equation}
    \begin{equation}
        \left\lVertb\right\rVert_{L^\infty}\lesssim\frac{\epsilon^2}{t^{\frac{3}{4}}}\ln (2+t)+\frac{\lambda}{H^2},
    \end{equation}
    \begin{equation}
        \left\lVert\partial_\alpha b\right\rVert_{H^{s-1}}\lesssim\frac{\epsilon^2}{t^{\frac{2}{3}-\delta_0}}\ln (2+t)+\frac{\lambda}{H^{\frac{3}{2}}},
    \end{equation}
    \begin{equation}
        \left\lVert\partial_\alpha b\right\rVert_{W^{s-3,\infty}}\lesssim\frac{\epsilon^2}{t^{\frac{3}{2}-\delta_0}}(\ln (2+t))^2+\frac{\lambda}{H^3},
    \end{equation}
    \begin{equation}
        \left\lVert\partial_\alpha b\right\rVert_{\dot W^{s-2,\infty}}\lesssim\frac{\epsilon^2}{t^{\frac{7}{6}-\delta_0}}(\ln (2+t))^2+\frac{\lambda}{H^3},
    \end{equation}
\begin{equation}
        \left\lVertD_tb\right\rVert_{H^{s}}\lesssim\frac{\epsilon^2}{t^{\frac{2}{3}-\delta_0}}\ln (2+t)+\frac{\lambda(\epsilon+\lambda)}{H^{\frac{5}{2}}},
    \end{equation}
\begin{equation}
        \left\lVertD_t b\right\rVert_{W^{s-2,\infty}}\lesssim\frac{\epsilon^2}{t^{\frac{5}{4}-\delta_0}}(\ln (2+t))^2+\frac{\lambda(\epsilon+\lambda)}{H^3}
    \end{equation}
and
\begin{equation}
        \left\lVertD_t b\right\rVert_{\dot W^{s-1,\infty}}\lesssim\frac{\epsilon^2}{t^{\frac{7}{6}-\delta_0}}(\ln (2+t))^2+\frac{\lambda(\epsilon+\lambda)}{H^3}.
    \end{equation}

