body:
[Lemma 30 of arXiv:2605.16868, '\ttl'] With definitions \eqref{eq:infliftqueue}--\eqref{eq:infliftlm}, 
the lifted system $\widetilde{Q}_u^N(t)$ can be written as: for $u \in [0,1]$ and $t \ge 0$, 
\begin{equation*}
\widetilde{Q}_u^N(t) = \bar{Q}_u^N(0) + \lambda_u^Nt + \Big(\int_0^1 G^N(v,u)\mu^N_v dv - \mu^N_u \Big) t -  \int_0^1 G^N(v,u)  \mu^N_v \widetilde{I}^N_v  dv  +  \mu^N_u  \widetilde{I}_u^N(t).
\end{equation*}
Equivalently, we write
\begin{equation} \

\widetilde{Q}^N (t) = \widetilde{X}^N (t) + (\mathbf{1}-(\boldsymbol{G}^N)^T) \widetilde{Y}^N (t), 
\end{equation}
where
\begin{align}

\widetilde{X}^N(t)  & = \bar{Q}^N(0) + \lambda^N t - (\mathbf{1}-(\boldsymbol{G}^N)^T)\mu^Nt, \\ \widetilde{Y}^N (t) &= {\operatorname{diag}}(\mu^N)\widetilde{I}^N(t).
\end{align}

[Prop 36 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $(C_v)_{v\mid \infty}$ be a collection of fixed real numbers satisfying $C_v\geq 1$ and $\q$, $x$, and $\pi_0\ni\phi_0$ be as in \S\ref{sec:choices}. Then there exists a spectral weight function $\H$ defined on the generic automorphic representations for $\bar{G}_n(F)$, factorizing as
	\begin{equation*}
		\H(\sigma)=\prod_{v<\infty}H_v(\sigma_v)\prod_{v\mid\infty}h_v(\sigma_v),\quad \sigma=\otimes'_v\sigma_v,
	\end{equation*}
	such that we have the spectral expansion of the period
	\begin{multline*}
		\mathrm{vol}^{-1}(K_0(\q))\frac{\zeta_\q(1)\zeta_\q(\frac{n}{2})^2}{\zeta_\q(n)}\int_{[\bar{G}_{n}]}|\phi_0\cdot R(x)\Eis(f)|^2 = \\ \Delta^{-\mu_1}\sum_{P}n_P^{-1}\sum_{\pi\in\Pi_{\mathrm{c}}(\bar{M})}\intop_{i\a^\ast_P/i\a^\ast_G}\frac{|L\left(\frac{1}{2},\mathcal{I}(\pi,\lambda)\otimes\tilde{\pi}_0\right)|^2}{\ell(\mathcal{I}(\pi,\lambda))}\mathcal{H}\left(\mathcal{I}(\pi,\lambda)\right)\, d\lambda,
	\end{multline*}
	where $\mu_1$ is a constant depending only on $n$ and $\H$ satisfies the following properties:
	\begin{itemize}
		\item If $v<\infty$ and $c(\sigma_v)>r_v$ then $H_v(\sigma_v)=0$;
		\item If $v<\infty$ and $c(\sigma_v)\le r_v$ then $H_v(\sigma_v)\geq 1$, with equality when $r_v=0$; 
		\item If $v\mid\infty$ and $C(\sigma_v)\leq C_v$ then $h_v(\sigma_v) \gg_{C_v} 1$;
		\item $\int_{\widehat{\bar{G}_n(F_v)}}H_v(\sigma_v)\, d\mu_{\loc}\sigma_v\asymp \mathrm{vol}^{-1}\left(K_0\left(\p_v^{r_v}\right)\right)$;
	\end{itemize}
	as $N(\q)\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2606.06859, 'The rectangular finite free heat flow'] For $A \in \R^{d \times m}$ with singular values $r_1 > \cdots > r_d > 0$, the Riemannian volume of $\mathcal{O}_A$ satisfies
\begin{equation} 
\log \mathrm{vol}(\mathcal{O}_A)
  = \sum_{1 \le i < j \le d}
      \log(r_i^2 - r_j^2)
    + (m - d) \sum_{i=1}^d \log r_i
    + C,
\end{equation}
where $C$ is a constant that does not depend on the singular values.

[Lem 3 of arXiv:2608.29703, 'A Sharp Small-Coefficient Variant of Khintchine's Inequality and the Sharp $\pi/2$ Theorem'] There exists a universal constant $C_{1}>0$
such that for all $y,u\in\mathbb{R}$, 
\begin{equation}
\abs{f'(y+u)-f'(y)-u\,d(y)}\leq C_{1}\left(u^{2}+\abs{u}\ind{\abs{y}\leq\abs{u}}\right).
\end{equation}

