body:
[Proposition 49 of arXiv:2604.01685, 'Probability with Measure\footnote{Lecture notes. University of Ljubljana.}'] Suppose $a\leq b$ are real numbers and $f:[a,b]\to \mathbb{R}$. If $f$ is continuous, then $f\mathbbm{1}_{[a,b]}$ is $\leb$-integrable and \begin{equation}
	\int_{[a,b]}f\dd \leb=\int_a^bf(x)\dd x,
	\end{equation}
	where the integral on the right-hand side is in the Riemann-Darboux sense.


	Moreover, $f$ is Riemann-Darboux integrable iff it is continuous $\overline{\leb}$-a.e. and bounded, in which case $f$ is $\overline{\leb}$-integrable and  $
	\int_{[a,b]}f\dd\overline{ \leb}=\int_a^bf(x)\dd x$.

[Definition 2 of arXiv:2604.10244, 'Ergodicity for regime-switching neutral stochastic functional differential equations with '] A $C_r$-valued stochastic process ${(X_t)_{ t\geq 0}}$ is called a solution map to the RNSFDE if
		\begin{enumerate}[(1)]
			\item $X_t$ is continuous and ${\mathcal{F}_{t}}$-adapted;
			\item ${\int_{{0}}^{\infty}\|X_t\|_r^{2} \d t<\infty}$, almost surely;
			\item ${X_0=\xi}$ and with probability 1,
			\begin{equation}
				X(t)-G\left(X_{t},\Lambda(t)\right)=\xi(0)-G\left(\xi,i\right)+\int_{{0}}^{t} b\left(X_{s},\Lambda(s)\right) \d s+\int_{{0}}^{t} \sigma\left(X_{s},\Lambda(s)\right) \d W(s),
			\end{equation}
		\end{enumerate}
		for any  $t \geq 0$. A solution map ${(X_t)}$ is said to be unique if any other solution map $(Y_t)$ is indistinguishable from it, that is,
		\[
		\mbb P\left\{\|X_t-Y_t\|_r=0, \text{ for all }t \geq 0\right\}=1 .
		\]
		Moreover, the corresponding $\mbb R^n$-valued stochastic process ${(X(t))_{ t\geq 0}}$ is called a solution of the RNSFDE.

[Lem 8 of arXiv:2609.02327, 'On the counting function of square-full numbers'] For $|t| \ge t_0$ where $t_0$ is sufficiently large, we have (with $\kappa \ge \frac {13}{84}+\epsilon$ unconditionally)
			\begin{equation}
				\zeta(\sigma+it)\ll |t|^{2 \kappa (1-\sigma)} \log |t|
			\end{equation}
			uniformly for $\quad \frac{1}{2}\leqslant \sigma\leqslant 1+\frac{1}{\log t}$.

