[Proposition 13 (Capacity asymptotic through the saddle) of arXiv:2607.20882, 'An Eyring--Kramers Law for the Hypoelliptic Third-Order\\ Langevin Diffusion'] As $\eps\downarrow0$,
\begin{equation}

\Cap_\eps(A_\eps,S_\eps)
=
[1+o_\eps(1)]
\frac{1}{Z_\eps}
\frac{(2\pi\eps)^{3d/2}}{L^d}
\frac{\mu_\sigma}{2\pi\sqrt{-\det H_\sigma}}
e^{-U(\sigma)/\eps}.
\end{equation}

[Lemma 62 (Schatten continuity of a pulled-back dyadic block) of arXiv:2607.10813, '2607.10813'] Fix a principal shell tuple $(N,Q,M)$, one of its finitely many cutoff states,
and $2\le r_0<\infty$.  Let $F_\varkappa^\sharp(t,s)$ be the four
flattenings of the pulled-back form on $\Delta_T$.  For every
$0<\theta\le1/2$,
\begin{equation}
 \sum_{\varkappa=1}^4
 \|F_\varkappa^\sharp(t,s)-F_\varkappa^\sharp(t',s')\|_{\Sch_{r_0}}
 \lesssim_{r_0,\theta}
 d_\Delta^\theta N^\theta\,\mathfrak P_{N,Q,M}(r_0),
\end{equation}
where
\begin{align}
 \mathfrak P_{N,Q,M}(r_0):={}&
 N^{-3/2+\beta_{b,c}}
 \bigl(Q^{3/2}M^{3/r_0}+M^{3/2}Q^{3/r_0}\bigr)\notag\\
 &+N^{-3+\beta_{b,c}}Q^{3/2}M^{3/2}N^{3/r_0}.
\end{align}
The same statement holds for differences of cutoff states.  On the transfer
tail, the right-hand side is replaced by the majorant in
\eqref{eq:inner-transfer-tail-time-increment}.  Consequently, for every fixed
shell tuple, $(t,s)\mapsto F_\varkappa^\sharp(t,s)$ is continuous in
$\Sch_{r_0}$, its image is compact, and simultaneous finite-rank compression
converges uniformly on $\Delta_T$ in all four Schatten norms.

[Theorem fobw of arXiv:2509.20657, 'Scaling limit for Brownian motions \\ on the $l$-level Sierpinski gaskets: \\ The fractal '] {\rm ([HK])}
For each $d\geq 2$, the following hold as $l\to\infty$.
\begin{equation}
d_w(l)=\left\{
           \begin{array}{ll}
             2+\frac{\log\log l}{\log l}+\frac{O(1)}{\log l}, & \hbox{if $d=2$;} \\
              d+\frac{O(1)}{\log l}, & \hbox{if $d\geq 3$.}
           \end{array}
         \right.\end{equation}
\begin{equation}
d_s(l)=\left\{
           \begin{array}{ll}
             2-\frac{\log\log l}{\log l}+\frac{O(1)}{\log l}, & \hbox{if $d=2$;} \\
              2-\frac{O(1)}{\log l}, & \hbox{if $d\geq 3$.}
           \end{array}
         \right.\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 18 (Proposition \ref{prop:margin Z} in the main text) of arXiv:2608.28991, 'Jigsaw-CRL: Recovering Global Latent Causal Order from Fragmented Multi-Client Interventio'] For $Z$ generated by Eq.~\eqref{eq:gloabl latent}, let $Z_k=(Z_{(i)})_{i\in O_k}$. Then
\begin{equation}
Z_k = \bA_k Z_k + E_k,
\end{equation}
where
\begin{align}

    \bA_k
    &=
    [\bA]_{O_k,O_k}
    +
    [\bA]_{O_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-1}
    [\bA]_{M_k,O_k}, \\
    E_k
    &=
    E_{O_k}
    +
    [\bA]_{O_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-1}
    E_{M_k}.
\end{align}
Moreover, $E_k$ has mean zero and covariance
\begin{equation}

    \bSigma_k
    =
    [\bSigma]_{O_k,O_k}
    +
    [\bA]_{O_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-1}
    [\bSigma]_{M_k,M_k}
    (\bI-[\bA]_{M_k,M_k})^{-T}
    [\bA]_{O_k,M_k}^{T}.
\end{equation}

Furthermore $\prec_k$, which is induced by $\bA_k$, is exactly the restriction of the $\prec$, which is induced by $\bA$,  to $\cV_k = O_k$.

