	\lim_{L\to\infty}\frac{1}{\tP}
	\sum_{n=1}^\infty\frac{\mathcal M_n}{(n!)^2} =\sum_{n=1}^\infty\frac{(-1)^{n+1}}{(n!)^2}\frac{1}{(2\pi\ii)^{2n}}
	\int_{>\ww}\dd\bu\int \dd\bv
	\prod_{i=1}^n\frac{e^{-u_i^3/3+(\rr+\ww^2)u_i}(v_i-\ww)}{e^{-v_i^3/3+(\rr+\ww^2)v_i}(u_i-\ww)}
	\K_n(\bu\mid\bv)^2.
