[Defn def:stochastic-airy-op of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] We define \textit{Ornstein--Uhlenbeck space-time white noise} as a one parameter family of random continuous functions of time into space distributions $\xi_{a}:[0,\infty)\to \mathcal{D}'((0,\infty))$, such that for any test functions $f_1,\dots,f_k \in C_c^{\infty}((0,\infty))$, $(\langle \xi_{a}(t_1),f_1 \rangle,\dots,\langle \xi_{a}(t_k), f_k \rangle)$ is a centered Gaussian process, and
    \begin{equation}
        \mathbb{E}[\langle \xi_{a}(t), f_i\rangle \langle \xi_{a}(s), f_j\rangle] = \int_{0}^{\infty} e^{-a|t-s|x} f_i(x)f_j(x) dx.
    \end{equation}

[Proposition prop_estimatecarreduchamp_0thderivative of arXiv:2509.18045, 'Density convergence on Markov diffusion chaos via Stein's method'] Let $\mathcal{Z}$ be the Pearson  distribution  assosiated with (equation sde_pearson of the paper) with mean $m$. Suppose that $X\in \mathcal{A}$  is an eigenfunction of the generator $L$ corresponding to the eigenvalue $-q$. Set   $F=X+m$ and recall the definitions of $S_n,Q_n$ at (equation def_SnandQ_n of the paper). Assume that  $S_1^{-1}\in L^{4}(E,\mu)$ and that 
\begin{align*}
\E{\mathcal{U}_1(0,x,F)^2}+\E{\mathcal{U}_2(0,x,F)^2}+\sum_{3\leq i\leq 6}\E{\mathcal{U}_i(0,F)^2}<\infty\,,  
\end{align*}
where $U_i(0),1\leq i\leq 6$ are from in Lemmas (lemma_xinlandu of the paper), (lemma_steinmethod_xlessthanl of the paper) and (lemma_steinmethod_xmorethanu of the paper). \
Then $F$ admits a density and we have the following estimate at every $x\in \mathbb{R}$:   
\begin{align*}
     &\abs{p_F(x)-p_\mathcal{Z}(x)}\\
     &\leq \E{\frac{1}{S_1^3}}^{1/2}\E{\autobracket*{LQ_1}^2}^{1/4}\mathbb{E}{\left[ Q_1^2\right]}^{1/4}+\E{ \brac{\frac{2b_2F+b_1+F-m}{S_1b(F)}}^2}^{1/2}\mathbb{E}{\left[ Q_1^2\right]}^{1/2}\\
&+\brac{\E{\mathcal{U}_2(0,x,F)^2}^{1/2}+\E{\mathcal{U}_4(0,F)^2}^{1/2}+\E{\mathcal{U}_6(0,F)^2}^{1/2} }\frac{1}{q^2}\mathbb{E}{\left[ Q_1^2 \right]}^{1/2}. 
\end{align*}

