	\begin{align*}
		[\Psi(D\tau)]^{\mcZ}_i - \delta [\Psi(\tau)]^{\mcZ}_i =&  \sum_{\sigma\prec D\tau}\Delta_{<i-1}\big(\lambda^\mcZ((D\tau)/\sigma)\big)\, [\Psi(\sigma)]^\mcZ_i 
		\\
		&- \sum_{\mu\prec\tau} {\sf Q}^\mcZ(\Psi(\tau/\mu))_i \big([\Psi(D\mu)]^\mcZ_i - \delta[\Psi(\mu)]^\mcZ_i\big).
	\end{align*}

	We have 
	\begin{align*}
