[Proposition 18 of arXiv:2607.10725, 'From the Airy line ensemble to the Gaussian free field'] Fix $m \geq 2$,  $\e \in (0,1)$,  $\delta \in \left(0,\tfrac{1}{2m}\right)$, and $A > 0$. Let $H_T$ be as in (\ref{Eq.HeightFunction}) and assume the same notation as in Definition \ref{Def.ITs}. Then, as $T \to \infty$,
\begin{equation*}
\E\bigl[H_T(t_1,x_1)\cdots H_T(t_m,x_m)\bigr] \longrightarrow P(t_1, x_1; \ldots; t_m, x_m)
\end{equation*}
uniformly for
\begin{equation*}
    (t_1,x_1;\ldots;t_m,x_m)
    \in
    \bigl([-A,A]^2\cap\{(t,x):x\le -T^{-\e}\}\bigr)^m
    \cap
    \Bigl\{
        \min_{i\neq j}|t_i-t_j|>T^{-\delta}
    \Bigr\}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 of arXiv:2607.16017, 'On large networks of integrate-and-fire neurons with short-term synaptic plasticity'] Grant Assumptions~\ref{ass:fmin}-- \ref{ass:minf} and assume moreover that there exists $0 < \lambda_\alpha'   \le \lambda_\alpha $ such that
	\[ \forall z \in \C, \quad \Re(z) > -\lambda' _\alpha \implies \hat{\Theta}_\alpha(z) \neq 1. \] 
	Then, $\mu_\infty$ is (locally) stable. More precisely, there exist $ C, \varepsilon  > 0 $ and $ 0 < \lambda < \lambda_\alpha' , $ such that for any  $ \mu_0 \in \cP  ( \R \times [0, 1 ] ) $ with $ d_{BL} ( \mu_0, \mu_\infty ) \le \varepsilon,  $ we have 
    \begin{equation}
        d_{BL} ( \mu_t , \mu_\infty ) \le C e^{ - \lambda t } d_{BL} ( \mu_0, \mu_\infty ) , \end{equation}
        for all $ t \geq 0, $  where $ \mu_t = \cL  (V_t, X_t)  $ with initial law $ \mu_0 = \cL  (V_0, X_0). $ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 40 of arXiv:2608.18075, '2608.18075'] Let $b>2$.  For $-1\le r\le b$, in the distributional sense at the
lower endpoint,
\begin{align*}
 \norm{\cS(w,u)}_{H^{r-1}}
 \le C_{b,r}\norm{w}_{H^b}\norm{u}_{H^r}.
\end{align*}

[Corollary cor:ProcDecomp of arXiv:2606.11951, 'On Skorokhod Problems for Reflected and Singular Stochastic Heat Equations'] There is an $\mathcal{E}^{a}$-exceptional set $S^a \subset L$ s.th.\ for all $z \in L\setminus S^a$ under $P_z^a$ there exists an $\mathcal{M}_t^a$-cylindrical Wiener process $W^{z,a}$, s.th.\ the sample paths of the associated distorted Ornstein-Uhlenbeck process $M^{a}$ on $L$ satisfy for all $l \in D(A) \cap H_0^1$ that
    \begin{multline}
        \langle l, X_{t}^a-X_0^a\rangle = \int_0^{t} \langle l, dW_s^{z,a}\rangle + \frac{1}{2} \int_0^{t} \langle l, n_{\sigma^{(a)}} (X_s^a) \rangle dL_{s}^{\var{\sigma^{(a)}}} - \int_0^{t} \langle l'', X_s^a \rangle ds \\ \forall \, t \geq 0 \, \text{$P_z^a$-a.s.}
    \end{multline}
    In this equation, $L_{t}^{\var{\sigma^{(a)}}}$ denotes the real valued PCAF associated with $\var{\sigma^{(a)}}$ by the Revuz correspondence.

    The analogous statement holds for $\rho$.

[Lemma lem:IPS:entropy-diffusion of arXiv:2605.16904, 'Positive-rate PCA and IPS with stationary Bernoulli measures are rapidly forgetful \footno'] Let $\widehat{\Psi}=(\widehat{\Psi}_J)_{J\Subset\mathbb{Z}^d}$ be the family of asynchronous updating kernels associated with a local transition rule $\psi\colon\Sigma^N\times\Sigma\to[0,1]$, and suppose that $\widehat{\Psi}_J$ preserves a Bernoulli measure~$\lambda=\lambda_q$.
	Then,
	\begin{equation}
		D_J(\mu\widehat{\Psi}_J\relto\lambda) \leq
			D_J(\mu\relto\lambda) + \abs{N}\log(\sfrac{1}{q_\mathsf{min}})\cdot\frac{\abs{\partial^- N(J)}}{\abs{J}}
	\end{equation}
	for every probability measure~$\mu$ and every finite set $J\subseteq\mathbb{Z}^d$,
	where $q_\mathsf{min}\coloneqq\min\{q(a): a\in\Sigma\}$ and
	$\partial^-N(J)\coloneqq\{k\in J: N(k)\not\subseteq J\}$.

