[Definition eq:Jintegrals of arXiv:2411.06827, 'The Exponential Lie Series and a Chen--Strichartz Formula for L{\'e}vy Processes'] \begin{equation}

	J_w:=\mu(w^0) 
	\quad\ \text{and} \quad\
	V_w:=\bar\mu(\overline w^0),
\end{equation}
so that the flowmap expansion rewrites as
\begin{equation}
	\varphi_t=\sum_{w} J_w(t) V_w.
\end{equation}
We call this expansion the renormalised expansion of the flowmap.

[Definition 23 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $\sigma \in \Sym_n$, and $X \subseteq \Der \sigma$. Define
    \begin{equation}
        E^{(X, \sigma)} \defeq E[X \leftrightarrow (X \cup \Fix \sigma)] = \{e \in E \text{ with one endpoint in } X \text{ and the other in } X \cup \Fix \sigma \}.
    \end{equation}
    Then, if $e = \{u, v\} \in E^{(X, \sigma)}$, exactly one of the following holds.

    \begin{enumerate}
        \item For some $k \in \N$, $\sigma^k(e) \notin E^{(X, \sigma)}$. If this is the case, there exist maximal $i,j \geq 0$ such that $\{\sigma^{-i}(e), \sigma^{-(i-1)}(e) \ldots, e, \ldots, \sigma^j(e) \} \subseteq E^{(X, \sigma)}$; such a maximal subset is called a chain. \\
        \item The $\sigma$-orbit $\mc{O}$ of $e$ is contained within $E^{(X, \sigma)}$, i.e. the $\sigma$-orbits $\mc{O}_u$ (resp. $\mc{O}_v$) of $u$ (resp. $v$) are contained within $X \cup \Fix \sigma$. In this case:

        \begin{enumerate}
            \item either $|\mc{O}| = \mathrm{lcm}(|\mc{O}_u|, |\mc{O}_v|)$;
            \item or $\mc{O}$ is a so-called "special" orbit. 
        \end{enumerate}
        There are at most $n$ edges inside special orbits.
    \end{enumerate}

[Lemma lem_zbieznosc_K_1 of arXiv:2411.08220, 'Nonlocal operators with Neumann conditions'] Let $\alpha\in (0,2)$. Assume that $f:\mathbb{R}_*\to [0,\infty)$ is a function such that for some $x\neq 0$ we have $\widehat{\nu}f(x) <\infty$. Then 
\begin{align*}
    \lim_{t\to 0^+}  \frac{1}{t} K_{t,1} f(x) = \widehat{\nu}f(x).
\end{align*}

