	\begin{align}

		 & |(I\backslash I \cap J)^{\gamma}|= |\bullet_I| + |\reflectbox{\sf L}| + |{\sf Z}_{0}|+ |-_0|, \hspace{0.1cm} {\rm and}                                                                                                               \\

