[Theorem 20 (Residual-augmented representation and response-aware resolvent) of arXiv:2608.26877, 'When Is the Sharp Covariance Envelope Tight? Feature-Only Geometry for Volume-Sampled Leas'] Suppose $\lossstar>0$ and $d<s<m$.  If $X$ is in row general position, then
the ordinary law and the auxiliary law $P_B$ are related by the exact
change of measure below; sampling and fitting remain under $P_X$.
\begin{equation}
  P_X(S)L_S=\beta\lossstar P_B(S),
  \qquad
  \frac{\overline M_s}{\lossstar}=I_d-\beta\E_B[K_S^{-1}],
  \qquad
  \E_BK_S=I_d-\gamma R.

\end{equation}
Classical operator Jensen for matrix inversion, with the minus sign in the
middle identity reversing the order, gives the interior resolvent bound
\begin{equation}
  \boxed{\overline M_s\preceq
  \lossstar\left[I_d-\beta(I_d-\gamma R)^{-1}\right]}

\end{equation}
and its linear consequence
\begin{equation}
  \overline M_s\preceq
  \alpha\lossstar I_d-\beta\gamma\lossstar R.

\end{equation}
For an arbitrary full-column-rank boundary design, as defined before
Theorem~\ref{thm:main-envelope}, only the congruent
one-sided inequality is asserted.  With
$Q=\sum_i(1-h_i)x_ix_i^\top$,
\begin{equation}
  M_s\preceq\lossstar\left[G^{-1}-\beta(G-\gamma Q)^{-1}\right].

\end{equation}
The exact inverse-moment covariance identity in~\eqref{eq:augmented-transform-main}
does not extend through a rank-changing boundary. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 (Root moments, void events and basins) of arXiv:2607.13210, 'Punctured Wilson--Evolving Sets and Root Identities for Massive Kirchhoff Forests'] For every $k\geq1$, we find:
\begin{equation*}
  \Ee[(N_q)_k]
  =\sum_{\substack{x_1,\ldots,x_k\in V\\\mathrm{distinct}}}
  \prod_{i=1}^k
  \Pp^{V\setminus A_{i-1}}_{\{x_i\}}
  \bigl(x_i\in S_{T_q}^{V\setminus A_{i-1}}\bigr).
\end{equation*}
More generally, for any $U\subset V$, it follows:
\begin{equation*}
  \Ee[(N_q(U))_k]
  =\sum_{\substack{x_1,\ldots,x_k\in U\\\mathrm{distinct}}}
  \prod_{i=1}^k
  \Pp^{V\setminus A_{i-1}}_{\{x_i\}}
  \bigl(x_i\in S_{T_q}^{V\setminus A_{i-1}}\bigr).
\end{equation*}
Furthermore, one finds for any $U\subset V$,
\begin{equation}
  \Pp(\Root\cap U=\emptyset)
  =\sum_{A\subset U}(-1)^{|A|}\Pp(A\subset\Root).
\end{equation}
For every $x\in V$ and $U\subset V$, we find:
\begin{equation}
  \Pp(\rho_q(x)\in U)
  =\frac{1}{\pi(x)}\Ee_{\{x\}}[\pi(S_{T_q}\cap U)].
\end{equation}
If $B_q(U):=\{x\in V:\rho_q(x)\in U\},$ then it follows:
\begin{equation}
  \Ee[\pi(B_q(U))]=\pi(U).
\end{equation}
Finally, we find:
\begin{equation*}
  \Ee[|E(F_q)|]=|V|-\Ee[N_q].
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 of arXiv:2604.15753, 'The truncation property and continuity for \\ the long-range contact process on $\mathbb{Z'] Let $\lambda \in \Lambda$ be symmetric and irreducible, and let $\delta>0$. Then there exists $N=N(\lambda)\geq 1$ such that, for all $n\geq N$, 
\begin{equation}
\bP_{\lambda,\delta}\left( \leftidx{_{[0,n]^d}}A_1^o \supset [0,n]^d\right) >0.
\end{equation}

[Lemma 29 of arXiv:2604.04823, '2604.04823'] For all sufficiently small~$h$ and all~$x\in \Omega_h$, $\xi(x)$ is well-defined as in Lemma~\ref{l:facts-on-boundaries}, and
\begin{gather}
    \E\brak{\zeta_{t,i} \one_E} = O(h)\,, \quad 
    \E\brak{\zeta_n \zeta_{t,i}\one_E} = O(h)\,,\quad 
    \E\brak*{\zeta_{t,i}\zeta_{t,j} \one_E} = O(h)\,,\quad \forall i\neq j\,,
\end{gather}
where the implicit constants in the~$O(\cdot)$ notation depend only on the dimension.

Moreover, if we let~$a\geq 1$ and suppose~$a\sqrt{\epsilon}$ is sufficiently small and~$h\leq \epsilon^2$, then for any~$x\in \Omega_h$, $\xi(x)$ is well-defined. If, in addition,
\begin{equation}
    \abs{D\hat U(x)_t} \geq ca\sqrt{\epsilon}\,,
\end{equation}
for some constant~$c>0$ independent of~$a,\epsilon,h$, then
\begin{gather}
    \E\brak*{\zeta_{t,i}\zeta_{t,j} \one_{E\cap \set{D>0}}} = O(h^{0.75})\,,\quad \forall i\neq j\,,\\

    \E\brak*{\zeta_{t,i}^2 \one_{E\cap \set{D>0}}} = \frac{1}{4}\sigma^2 + O(h^{0.75})\,,\\

    \E\brak*{\zeta_n^2\one_{E\cap \set{D>0}}} = \frac{1}{4}\sigma^2 + O(h^{0.75})\,.
\end{gather}
Here, $D\hat U(x)_t$ is the component of~$D\hat U(x)$ on the tangent space spanned by the orthonormal vectors~$(t_i(\xi(x)))_{i=1}^{d-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lm 37 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $N>0$ be a fixed integer and let $w=(w_1,\dots,w_N)$ be a fixed alphabet. The function \eqref{eq:F initial coord function} indexed by the half-space configuration $y=(1)$ is explicitly given by:
	\begin{equation}

		\mathcal{F}_{(1)}(w_1,\dots,w_N) = \alpha^{N-1} \sum_{k=1}^N \frac{(1-q)^2w_k}{(1-w_k)(1-qw_k)}.
	\end{equation}

