[Lemma lem:error_bounds1 of arXiv:2411.17827, 'Ordered random walks and the Airy line ensemble'] Let $a < 1/2$, $\beta > 0$ and $\theta > \max(1, \beta/2)$.
\begin{enumerate}
    \item Suppose $\varepsilon \in (0, 1/2)$ and $2a < 1/2 - \varepsilon$.
There exists $t_0 > 0$ and $C > 0$ such that uniformly in $d(t) \leq t^a$ and $t > t_0$, 
for all $x \in W_{t,\varepsilon}$ with $\lvert x_j \rvert \leq t^{\theta}/\log(t)$,
\begin{align*}
\mathbf E_x[V(S(t)); \tau > t, \mathcal C_t^c] & \leq CV(x) e^{\theta t^{a} \log(2t)-t^{\beta/2}}.
\end{align*}
\item
There exists $t_0 > 0$ and $C > 0$ such that uniformly in $d(t) \leq t^a$ and $t > t_0$,
 for all $x \in W^d$ with $\lvert x_j \rvert \leq t^{\theta}/\log(t)$ and $x_j - x_{j-1} \geq 1$ for all $j = 2, \ldots, d,$
\begin{align*}
\mathbf E_{x}[\Delta(B(t)); \tau^{\mathrm{bm}} > t, \mathcal C_t^c] & \leq C\Delta(x) e^{\theta t^a \log(2t)-t^{\beta/2}}.
\end{align*}
\end{enumerate}

