\begin{equation}

 \frac1{\mathbb P(A)}\,\mathbb E\left[\exp\!\left(\frac{\beta |f-f_A|}{\|f\|_{\mathrm{BMO}}}\right)\mathbf1_A\right]
 \le 1+\frac{e^2\beta}{\alpha-e\beta}.
