body:
[Theorem Theorem Convergence Empirical Measure Autonomous of arXiv:2411.09260, 'The Hydrodynamic Limit of Hawkes Processes on Adaptive Stochastic Networks'] Suppose that Hypothesis (Hypothesis Additional Autonomous of the paper) holds in addition to the other hypotheses. Then for any continuous function $\mathcal{H}: \mathcal{E}\times\mathcal{E}\times \Gamma\times\Gamma_E \mapsto \mathbb{R}$ and any $T > 0$, $\mathbb{P}$-almost-surely,
  \begin{multline}
  \lim_{n\to\infty} \sup_{\alpha \in \Gamma}\sup_{a\in\Gamma_E} \sup_{t\leq T}\bigg| \int_{\mathcal{E}} \int_{\mathcal{E}} \mathcal{H}(x,y,\alpha,a) p_{xy}(\alpha,a)d\mu_{\mathcal{E}}(x) d\mu_{\mathcal{E}}(y) \\- n^{-2}\sum_{j,k\in I_n} \mathcal{H}(\theta^j_n,\theta^k_n , \alpha,a) \mathbf{1}\lbrace \sigma^k_t = \alpha , J^{jk}_t = a \rbrace \bigg| =0.
  \end{multline}

Here $p_{\theta\eta,t}$ is the unique solution of the following system of PDEs. For $\theta,\eta \in \mathcal{E}$, and $\alpha \in \Gamma$, $a\in \Gamma_E$,  
  \begin{align} 
  p_{\theta\eta,0}(\alpha,a) =  \sum_{\beta\in\Gamma} v_{\theta\eta}(\beta,\alpha,a) 
  \end{align}
  and for $t> 0$,
  \begin{multline} 
  \frac{d}{dt}p_{\theta\eta,t}(\alpha,a) = \sum_{\zeta\in\Gamma : \zeta \neq \beta}\big( f_{\zeta \mapsto \alpha}(G_{\eta,t})p_{\theta\eta,t}(\zeta,a) -  f_{\alpha \mapsto \zeta}(G_{\eta,t})p_{\theta\eta,t}(\alpha,a)  \big) \\
  + \sum_{b\in \Gamma_E \; : b\neq a} \big( \tilde{l}_{b\mapsto a}(\alpha) p_{\theta\eta,t}(\alpha,b)  -  \tilde{l}_{a\mapsto b}(\alpha) p_{\theta\eta,t}(\alpha,a)  \big)
  \end{multline}
  where $G_{\theta,t} \in \mathcal{P}(\Gamma\times\Gamma_E)$ is such that for $\alpha\in\Gamma$, $a\in \Gamma_E$,
  \begin{align}
  G_{\theta,t}(\alpha,a) =  \int_{\mathcal{E}}  p_{\theta\eta,t}(\alpha,a) d\mu_{\mathcal{E}}(\eta)
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conj 7 (Partial homogenization) of arXiv:2506.13587, 'Non-exchangeable mean-field theory for adaptive weights: propagation of dissociatedness an'] Adopt the setting of Theorem~\ref{thm:empirical_data_stability}, but for $k \in \mathbb{N}$, assume the $N_k$-particle system $\bm{\mathcal{Y}}^{(k)}(t) = ((\bm{X}^{(k)}_{i}(t))_{i \in [N_k]}, (\bm{W}^{(k)}_{i,j}(t))_{i,j \in [N_k]})$ evolves according to the SDE system \eqref{eqn:decay_SDEs} with $\epsilon = 1$. 
Let $\overline{\mathcal{Y}}(t) = (\overline{\mathsf{X}}(t), \overline{\mathsf{W}}(t))$ denote the structural limit solution to the McKean-Vlasov SDEs \eqref{eqn:main_McKean_Vlasov} in the sense of Proposition~\ref{prop:well_posedness_McKean_Vlasov} (corresponding to the particular dynamics \eqref{eqn:decay_SDEs}).
Moreover, assume
\begin{equation*}
\begin{aligned}
& \lim_{k \to \infty} \mathbb{E} \Big[ \gamma_{W_1,\square}\big( \bm{\mathcal{Y}}^{(k)}(0), \overline{\mathcal{Y}}(0) \big) \Big] = 0.
\end{aligned}
\end{equation*}
Then, ``the convergence at $t \to \infty$ takes place in the stronger sense'', namely,
\begin{equation*}
\begin{aligned}
& \lim_{t \to \infty}
\limsup_{k \to \infty}
\E \Big[ \delta_{W_1,\square}\big( \bm{\mathcal{Y}}^{(k)}(t), \overline{\mathcal{Y}}(t) \big) \Big]= 0.
\end{aligned}
\end{equation*} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

