[Lemma 7 of arXiv:2607.16017, 'On large networks of integrate-and-fire neurons with short-term synaptic plasticity'] Let $g : \R \times [0, 1] \to \R$ be measurable and bounded. 
For all $ s \le t, $ we have that 
\begin{multline} 
\E \left[ g  (V_{s, t}^{ a, \mu } , X_{s, t }^{a, \mu } )\right]  = \int_{ \R \times [0, 1] }  g ( \varphi_{s, t }^a (v), \psi_{ t-s } (x) ) H_a^v ( s , t )\mu ( \d v, \d x)   \\
+ \int_{\R \times  [ 0, 1]} \int_s^t K_a^v (s, u)  \E \left[ g   (V_{u , t}^{ a, \delta_{(0, (1- U) \psi_{ u-s} ( x)) } }  , X_{u, t }^{a, \delta_{(0, (1- U) \psi_{u-s} ( x))} } )\right]  \d u  \mu ( \d v,  \d x ) . 
\end{multline}

[Proposition 58 (Hille-Yosida Theorem) of arXiv:2608.20252, '2608.20252'] For a Markov semigroup $T_t$ on $L^2(Q)$, define
\begin{eqnarray*}
{\rm Dom} &=& \big\{f\in L^2(Q):  \lim_{t\downarrow 0} \frac{T_tf - f}{t} \ {\rm exists}\big\}\\
Lf&=& \lim_{t\downarrow 0} \frac{T_tf - f}{t} \ {\rm for \ }f\in {\rm Dom}
\end{eqnarray*}

Then, if $f\in {\rm Dom}$, we have $T_tf\in {\rm Dom}$ and $\frac{d}{dt} T_tf = LT_tf = T_tLf$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop cor:incor of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] For every $\mathsf{q} \in \mathsf{R}_1\cup \cdots \cup \mathsf{R}_7$,  there exist constants $C, c, L_0>0$ such that for every $L\ge L_0$ and $\mathbf{n}\in {\mathbb N}^3$, 
and for every ${\boldsymbol \sigma}, {\boldsymbol \tau}\in \mathcal S_{\mb{n}}$ of the forms 
\begin{enumerate} [(a)]
\item ${\boldsymbol \sigma} =2^{a_2} (23)^{a_{23}}3^{a_3}(123)^{a_{123}}(12)^{a_{12}}1^{a_1}$ and ${\boldsymbol \tau} = 3^{b_3'}2^{b_2'}1^{b_{1}}2^{b_2''}3^{b_3''}$ if $\mathsf{q} \in \mathsf{R}_1\cup \mathsf{R}_2$; 

\item ${\boldsymbol \sigma} = 3^{a_3}(23)^{a_{23}}2^{a_2}(123)^{a_{123}}(12)^{a_{12}}1^{a_1}$  and ${\boldsymbol \tau} = 3^{b_3'}2^{b_2'}1^{b_{1}}2^{b_2''}3^{b_3''}$ if $\mathsf{q} \in \mathsf{R}_3\cup \mathsf{R}_4$;

\item ${\boldsymbol \sigma} =3^{a_3}(23)^{a_{23}}(123)^{a_{123}}1^{a_1} (12)^{a_{12}} 2^{a_2}$ and ${\boldsymbol \tau} = 3^{b_3'}2^{b_2'}1^{b_{1}}2^{b_2''}3^{b_3''}$ if $\mathsf{q} \in \mathsf{R}_5$; 

\item ${\boldsymbol \sigma} = 3^{a_3}(23)^{a_{23}}(123)^{a_{123}}1^{a_1} (12)^{a_{12}} 2^{a_2}$ and ${\boldsymbol \tau} = 2^{b_2}(23)^{b_{23}}3^{b_{3}'}(12)^{b_{12}}1^{b_1}3^{b_{3}''}$ if $\mathsf{q} \in \mathsf{R}_6\cup \mathsf{R}_7$;
\end{enumerate} 
satisfying 
\begin{itemize}
\item $(a_{123}, a_{12}, a_{23}, a_1, a_2, a_3) \neq (1,0,0,0,0,0)$ when $\mathsf{q} \in \mathsf{R}_1\cup \cdots\cup \mathsf{R}_5$, 
\item $a_{123}+a_1\ge 1$  when $\mathsf{q} \in \mathsf{R}_5\cup \mathsf{R}_6\cup \mathsf{R}_7$, 
\item $(a_{123}, a_{12}, a_{23}, a_1, b_2, a_3)\neq (1,0,0,0,0,0)$ when $\mathsf{q} \in \mathsf{R}_6\cup \mathsf{R}_7$, 
\end{itemize}
we have 
\begin{equation} 
    |\mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}}| 
    \le C^{|\mathbf{n}|} \sqrt{n_1! (n_2-n_1+a_1+b_1)! (n_2-n_3+a_3+b_3)!n_3!} e^{-cL} \mathsf{Z}_L, 
\end{equation}
where $b_3=b_3'+b_3''$. (Proof in the paper; no proof environment follows the statement in the TeX.)

