[Lemma ExpoStability of arXiv:2601.15223, 'Large time behaviour for a class of 2D and 3D stochastic non-Newtonian fluids of different'] Assume that \emph{$\boldsymbol{\mathfrak{K}}=\textbf{0}$}. Then, there exists $T(\omega)>0$ such that the solution of the system (equation STGF of the paper) satisfies the following exponential estimate:
	\begin{align}
		\|\boldsymbol{\mathcal{Y}}_1(t)-\boldsymbol{\mathcal{Y}}_2(t)\|^2_{2}\leq e^{-\frac{\sigma^2}{4}t}\|\boldsymbol{\mathcal{Y}}_{1,0}-\boldsymbol{\mathcal{Y}}_{2,0}\|^2_{2},  \ \  \text{ for all }\  t\geq T(\omega),
	\end{align}
	where $\boldsymbol{\mathcal{Y}}_1(t):=\boldsymbol{\mathcal{Y}}_{1}(t;0,\omega,\boldsymbol{\mathcal{Y}}_{1,0})$ and $\boldsymbol{\mathcal{Y}}_{2}(t):=\boldsymbol{\mathcal{Y}}_{2}(t;0,\omega,\boldsymbol{\mathcal{Y}}_{2,0})$ be two solutions of the system (equation STGF of the paper) with respect to the initial data $\boldsymbol{\mathcal{Y}}_{1,0}$ and $\boldsymbol{\mathcal{Y}}_{2,0}$ at $0$, respectively.

[Defn Empirical 2-point conditional homomorphism density of arXiv:2606.02340, 'Transitivity in Inhomogeneous Random Tournaments'] Suppose $T_n$ is a tournament with vertex set $[n]:=\{1, 2, \ldots, n\}$ and adjacency matrix $A_{T_n} = ((a_{uv}))_{1 \leq u, v \leq n}$. Fix $1 \leq u, v \leq n$. Then empirical 2-point conditional homomorphism density for $\cc$ is defined as: 
\begin{align*}
    \hat{t}_{T_n}(\cc, u, v) & = \frac{a_{uv}}{n} \sum_{w=1}^n a_{vw} a_{wu} .
\end{align*}  
Similarly, the empirical 2-point conditional homomorphism density for $\cac$ is defined as
\begin{align*}
   \hat{t}_{T_n}(\cac, u, v) & = \frac{a_{vu}}{n} \sum_{w=1}^n a_{uw} a_{wv} = \hat{t}_{T_n}(\cc, v, u) .
\end{align*}  
Finally, define {\it symmetrized empirical $2$-point conditional homomorphism density} as: 
\begin{align*}
    \hat \triangle_{T_n}(u, v) :=\frac{ a_{uv} \sum_{w=1}^n a_{vw} a_{wu} + a_{vu} \sum_{w=1}^n a_{uw} a_{wv} }{2 n } . 

\end{align*}

[Prop 2 of arXiv:2607.06745, 'Regularization and asymptotic behaviour of Ornstein-Uhlenbeck evolution operators in infin'] i) Let $s<t$ and $\overrightarrow{P_{s,t}}$
be defined by $\text{\eqref{eq: def O-U vett formula}}$. Then $P_{s,t}\left(C_{b}\left(X\right)\right)\subseteq C_{b}\left(X\right)$,
$\overrightarrow{P_{s,t}}\left(C_{b}\left(X;X\right)\right)\subseteq C_{b}\left(X;X\right)$,
and the operators:
\begin{align*}
P_{s,t} & :C_{b}\left(X\right)\to C_{b}\left(X\right)\\
\overrightarrow{P_{s,t}} & :C_{b}\left(X;X\right)\to C_{b}\left(X;X\right)
\end{align*}
are bounded and indeed contractions.

Further, the family $\left\{ P_{s,t}\mid-\infty<s\leq t<+\infty\right\} $
forms a backward evolution operator in $C_{b}\left(X\right)$, meaning
that
\begin{equation}
P_{s,t}f=P_{s,\tau}P_{\tau,t}f\quad\forall s<\tau<t,\ f\in C_{b}\left(X\right).
\end{equation}

ii) For every $s<t$, $P_{s,t}\left(C_{b}^{1}\left(X\right)\right)\subseteq C_{b}^{1}\left(X\right)$
and the following formula holds:
\begin{equation}
\left[\nabla\left(P_{s,t}\varphi\right)\right]\left(x\right)=U\left(t,s\right)^{*}\left[\overrightarrow{P_{s,t}}\left(\nabla\varphi\right)\right]\left(x\right)\quad\forall\varphi\in C_{b}^{1}\left(X\right),\ x\in X.
\end{equation}

iii) For each $f\in C_{b}\left(X\right)$ and $x\in X$:
\begin{equation}
\lim_{s\to-\infty}\left[P_{s,t}f\right]\left(x\right)=\int_{X}f\left(y\right)\mathcal{N}\left(0,Q\left(t,-\infty\right)\right)\left(dy\right)\quad\forall t\in\mathbb{R},
\end{equation}
and
\begin{equation}
\lim_{t\to+\infty}\left\{ \left[P_{s,t}f\right]\left(x\right)-\int_{X}f\left(y\right)\mathcal{N}\left(0,Q\left(t,-\infty\right)\right)\left(dy\right)\right\} =0\quad\forall s\in\mathbb{R}
\end{equation}
if $f\in C_{b}^{\alpha}\left(X\right)$ for some $\alpha\in\left(0,1\right)$.

[Corollary 10 (Log-concave approximation) of arXiv:2608.27657, '\bfseries Stein Kernels and Normal Approximation\\ for Log-Concave Bilinear Forms'] Assume the estimates in \cref{thm:letwin}.  Every isotropic log-concave
law \(\mu\) on \(\R^n\) admits a symmetric positive-semidefinite Stein
kernel \(\tau\) satisfying, simultaneously for every
\(A\in\mathsf S_n\),
\begin{align}
  \E\tau&=I_n,
  \tag{4.12}\\
  \E\Tr(A\tau A\tau)
  &\leq2\Tr(A^2),
  \tag{4.13}\\
  \Var\!\left(\Tr(A\tau)\right)
  &\leq4\Tr(A^2).
  \tag{4.14}
\end{align}
It also satisfies
\begin{equation}
  \Var_\mu g
  \leq
  \E\langle\tau(Y)\nabla g(Y),\nabla g(Y)\rangle
  \qquad(g\in C_c^\infty(\R^n)).
  \tag{4.15}
\end{equation}
In particular,
\begin{equation}
  \E\Tr(\tau^2)\leq2n,
  \qquad
  \Var(\Tr\tau)\leq4n.
  \tag{4.16}
\end{equation}

[Theorem 7 of arXiv:2608.30736, 'Stability results for distribution-dependent stochastic Volterra equations'] Suppose that
  \begin{itemize}
    \item Assumption~\ref{ass:volatility} holds,
    \item all pairs of kernels $(K_{b,n}, K_{\sigma,n})$ $n \in \bN$ and $(K_b,K_{\sigma})$ satisfy Assumption~\ref{ass:kernel} using the same constants $\gamma, \epsilon, L$,
    \item $\mu_{0,n} \in \mathcal{P}_{p}(\R^d)$ for all $n \in \bN$ holds for some $p > \max\{\frac{2 \eta + 1}{\gamma},2+\frac{4}{\varepsilon}\}$ with uniformly bounded $p$-moments, meaning $\sup_{n \in \bN} \int_{\bR^d} |x|^p \mu_{0,n}(\d x) < \infty$,
	\item $\mu_{0,n}$ converges to $\mu$ as $n \to \infty$,
	\item for any compact subsets $K \subset \bR^d$ and $\mathcal K \subset \mathcal P_\eta(\bR^d)$,
	\begin{equation*}
	  \lim_{n \to \infty} \sup_{t \in [0,T]} \sup_{x \in K} \sup_{\mu \in \mathcal K} |\sigma_n(t,x,\mu)-\sigma(t,x,\mu)|+|b_n(t,x,\mu)-b(t,x,\mu)|=0
	\end{equation*}
	Additionally
	\begin{equation*}
	  \sup_{t \in [0,T]} \int_0^t |K_{b,n}(s,t)-K_b(s,t)|^{1+\epsilon} \dd s \to 0 \text{ as } n \to \infty
	\end{equation*}
	and
	\begin{equation*}
	  \sup_{t \in [0,T]} \int_0^t |K_{\sigma,n}(s,t)-K_\sigma(s,t)|^{2+\epsilon} \dd s \to 0 \text{ as } n \to \infty.
	\end{equation*}
  \end{itemize}
  Furthermore, suppose that the distribution-dependent Volterra local martingale problem given $(\mu_{0,n},K_{b,n}, K_{\sigma,n}, b_n, \sigma_n)$, $n \in \bN$, has a solution $P_n \in \mathcal{P}_p(C([0,T];  \bR^d))$ for each $n \in \bN$ and that the distribution-dependent Volterra local martingale problem given $(\mu, K_{b}, K_{\sigma}, b, \sigma)$ has a unique (in law) solution $P$. Then, $P_n$ converges weakly to $P$ as $n \to \infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma gNasymp of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let ${\sf b}$ and $g_{\infty}$ be as in Lemma~(lemma:gjasympcritd of the paper).  Then under the assumptions of Proposition~(prop:theRGthm of the paper),
\begin{align}
	g_N^{(\emptyset)} =
		\begin{cases} 
			(\textbf{b} N)^{-1} (1 + O(N^{-2} \log N)) & (d= d_{c,u} ,  \;  N < j_{\textbf{a}}) \\
			g_{\infty} + O_L ( 2^{- (N - j_\textbf{a})_+ } g_{\infty}^2) & (d = d_{c,u} ,  \;  N \ge j_{\textbf{a}}) \\
			g_{\infty} + O_L ( r_N g^2  ) & (d > d_{c,u})
		\end{cases}	
\end{align}

