[Theorem thm-gmc of arXiv:2603.01823, 'on a fractional stochastic heat equation arising from the disordered pinning model'] Assume $\rho\in(\frac1{2H-1},2]$. Then, we have the following Feynman--Kac formula for the solution $u(t,x)$ to (equation e:she of the paper)
\begin{equation}
\begin{aligned}
u(t,x)&=\lim_{n\to\infty }\mathbf E_{(t,x)}\left[ \exp\left\{\sum_{k=1}^n\left( m_k(t)\xi_k-\frac12 m_k^2(t)\right) \right\}\right]\\
&=\mathbf E_{(t,x)}\left[ \exp\left\{\sum_{k=1}^\infty \left(m_k(t)\xi_k-\frac12 m_k^2(t) \right)\right\}\right].
\end{aligned}
\end{equation}

[Theorem ASXXZA of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume the same hypotheses as in Theorem (SSS of the paper). Then in case $A\neq 0$ (and therefore $G\in C^{4}_{b}$), there exists a polynomial $Q_2$ such that
			\begin{align*}
				&\Vert \Vert D_{\xi}\phi_{\mathbf{X}}[\zeta]- D_{\tilde\xi}\phi_{\mathbf{X}}[\zeta]\Vert_{\mathscr{D}_{\mathbf{X}}^{\gamma}([0,r]}\leq \\ &\quad\Vert \xi-\tilde{\xi}\Vert_{\mathscr{D}_{\mathbf{X}}^{\gamma}([-r,0]}\Vert\zeta\Vert_{\mathscr{D}_{\mathbf{X}}^{\gamma}([-r,0]}\exp\big(Q_{2}(\Vert\xi\Vert_{\mathscr{D}_{\mathbf{X}}^{\gamma}([-r,0])},\Vert\tilde{\xi}\Vert_{\mathscr{D}_{\mathbf{X}}^{\gamma}([-r,0]},\Vert\mathbf{X}\Vert_{\gamma,[0,r]})\big),
			\end{align*}
			for every \( \xi, \tilde{\xi}, \zeta \in \mathscr{D}_{\mathbf{X}}^{\gamma}([-r,0]) \).
			In case \( A=0 \), and additionally, if for some \( 0 < \vartheta \leq 1 \), \( G \in C^{3+\vartheta}_{b} \), then there exists a polynomial \( Q_3 \) such that
			\begin{align*}
				&\Vert \Vert D_{\xi}\phi_{\mathbf{X}}[\zeta]- D_{\tilde\xi}\phi_{\mathbf{X}}[\zeta]\Vert_{\mathscr{D}_{\mathbf{X}}^{\gamma}([0,r]}\leq \\ &\quad\Vert \xi-\tilde{\xi}\Vert_{\mathscr{D}_{\mathbf{X}}^{\gamma}([-r,0]}^{\vartheta}\Vert\zeta\Vert_{\mathscr{D}_{\mathbf{X}}^{\gamma}([-r,0]}\exp\big(Q_{3}(\Vert\xi\Vert_{\mathscr{D}_{\mathbf{X}}^{\gamma}([-r,0])},\Vert\tilde{\xi}\Vert_{\mathscr{D}_{\mathbf{X}}^{\gamma}([-r,0])},\Vert\mathbf{X}\Vert_{\gamma,[0,r]})\big),
			\end{align*}
			for every \( \xi, \tilde{\xi}, \zeta \in \mathscr{D}_{\mathbf{X}}^{\gamma}([-r,0]) \).

[Definition Well-behaved Backtracking Intersections for SC Polynomials of arXiv:2608.12415, 'Sharp Phase Transition for Ellipsoid Fitting'] Given $\tau \in \mathcal{B}(K)$ that are backbone-dangling shapes, we say the composition $\tau\cdot \tau'$ forms a backtracking intersection if \begin{enumerate}
		\item $U_{\tau} \equiv V_{\tau'} $: the left-boundary vertex of $U_\tau$ matches with the right-boundary vertex of $V_{\tau'}$ ;
		\item $E(\tau) \equiv E(\tau')$: the underlying edge-set of the two sets receive the same labels.  
	\end{enumerate}
	We denote the corresponding backtracking intersection pattern as $\mathsf{BacktrackingInt}(\tau)$.

[Lemma 56 of arXiv:2608.27307, '2608.27307'] Along the interpolation \eqref{eq:cov_interp}, the estimates of Theorems~\ref{thm:rand_sc_eq} and~\ref{thm:opt_ll} hold uniformly for $0\leq s\leq t$ with the same deterministic solution $\Pi$. With $z_j=E_j+\ii\eta_{\rr{sm}}$ as in the proof of Proposition~\ref{prop:short_comp}, uniformly for deterministic unit vectors $\bbv,\bbw\in\C^L$,
        \begin{align}
                \abs{\scalar{\bbv}{(G(s,z_j)-\Pi(z_j))\bbw}} &\prec N^{-1/3+C_{\rr{cmp}}\chi},\qquad \abs{\scalar{\bbv}{G(s,z_j)\bbw}}\prec1, \nonumber\\
                \abs{\scalar{\bbv}{(G(s,z_2)-G(s,z_1))\bbw}} &\prec N^{-1/3+C_{\rr{cmp}}\chi}. \nonumber
        \end{align}

[Lem 6 of arXiv:2607.24166, 'Strong rate of convergence for the Euler--Maruyama scheme of additive fractional SDEs with'] Let $q \geq 1$, $\tau \in (0,1]$, $\Gamma, \ell \geq 0$ and $M > 0$. Let $f$ be a measurable function $\Omega \times [0,1] \to \mathbb{R}^d$.
    Suppose that $f_0 = 0$ and for every $(s,t) \in \Delta_{[0,1]}$ with $t - s \leq \ell$, we have
    \begin{equation}
        [f]_{C^\tau L^q([s,t])} \leq M \|f_s\|_{L^q} + \Gamma. 
    \end{equation}
    Then there exists a constant $C = C(\tau, \ell, M) > 0$ independent of $\Gamma$ such that
    \begin{equation}
        [f]_{C^\tau L^q([0,1])} \leq C\Gamma.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

