[Lemma lem:two-dim-sys of arXiv:2607.13748, 'Load Balancing with Individually Heterogeneous Servers'] Consider the following integral equations
\begin{align}
x_1(t) &=h_1 +y_1(t) - \int_0^t(\mu_{\max} x_1(s) - \mu_{\min} x_2(s))ds -u_1(t), \\
x_2(t) &=h_2 +y_2(t) - \int_0^t\mu_{\min} x_2(s)ds +u_1(t)-u_2(t),\\
x_1(t)&\leq0, \ 0\leq x_2(t) \leq B, \ t\geq0, 
\end{align}
where $u_1$ and $u_2$ are non-decreasing and non-negative functions satisfying
\begin{align}
\int_0^t\mathbb{I}{x_1(s)<0}du_1(s)&=0,\\
\int_0^t\mathbb{I}{x_2(s)<B}du_2(s)&=0.
\end{align}
Then for given $B\in \bar{\mathbb{R}}_+$, $\mathbf{h}\in \mathbb{R}^2$, and $\mathbf{y}\in \mathbb{D}_{\mathbb{R}^2}[0,\infty)$~(equation eqn:ref_1 of the paper)-(equation eqn:ref_3 of the paper) has a unique solution $(\mathbf{x},\mathbf{u}) \in \mathbb{D}_{\mathbb{R}^2}[0,\infty) \times \mathbb{D}_{\mathbb{R}^2}[0,\infty)$. Moreover, there exists a well-defined  function $(f,  g): \bar{\mathbb{R}}_+ \times \mathbb{R}^2 \times \mathbb{D}_{\mathbb{R}^2}[0,\infty) \to \mathbb{D}_{\mathbb{R}^2}[0,\infty) \times \mathbb{D}_{\mathbb{R}^2}[0,\infty)$ which maps $(B,\mathbf{h},\mathbf{y})$ to $\mathbf{x} =f(B,\mathbf{h},\mathbf{y})$ and $\mathbf{u}=g(B,\mathbf{h},\mathbf{y})$. Furthermore, the function $(f,g)$ is continuous on $\bar{\mathbb{R}}_+ \times \mathbb{R}^2 \times \mathbb{D}_{\mathbb{R}^2}[0,\infty)$. Finally, $\mathbf{y}$ continuous implies that $\mathbf{x}$ and $\mathbf{u}$ are also continuous. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 24 of arXiv:2604.19738, 'Phase Transitions in the Fluctuations of Functionals of Random Neural Networks \\'] With the same assumptions and notations of \Cref{fixed-point-sparse}, for fixed $q\in \mathbb N$ with $q\geq 2$, the following asymptotics hold.

 If $q< d/(2\nu)$, as $L\to \infty$ we have
 	\begin{equation}
\int_{-1}^1 \beta_L^q(u)\di \mu(u)=\,\int_{-1}^1  \beta^q(u)\di \mu(u)\,(1+o(1))\,\,
 	\end{equation}

If $q\ge d/(2\nu)$,
 	\begin{align}
\int_{-1}^1 \beta_L^q(u)\di \mu(u)\,\asymp \,
 		\begin{cases}
 			\log L\,\, &\textnormal{if } q=d/(2\nu) \\
 			L^{q -d/(2\nu) }\,\, &\textnormal{if }q>d/(2\nu)
 		\end{cases}
 		\qquad\,.
 	\end{align}

Moreover, we have
\begin{equation} \int_{-1}^1|\beta_L^q(u)|^q \di \mu(u) \,\asymp \,
 		\begin{cases}
        1 \,\, &\textnormal{if } q<d/(2\nu) \\
 			\log L\,\, &\textnormal{if } q=d/(2\nu) \\
 			L^{q -d/(2\nu) }\,\, &\textnormal{if }q>d/(2\nu)
 		\end{cases}
 		\qquad\,.
        \end{equation}

[Lemma lem:est for iid of arXiv:2411.03512, 'Ergodicity and Mixing of Sublinear Expectation System and Applications'] Let $\{X_k\}_{k\geq 1}$ be a d-dimensional i.i.d. sequence such that $\hat{\mathbb{E}}[|X_1|^{1+\beta}]<\infty$ for some $\beta\in (0,1]$ and $v\in C_b^{1,1+\beta}(\mathbb{R}_+\times \mathbb{R}^d)$ be the solution to equation (equation PDE of the paper) with $p(a)=\hat{\mathbb{E}}[\langle a, X_1\rangle]$. Set $S_n=\frac{1}{n}\sum_{i=1}^nX_i$. Then we have
        \begin{equation}
           \begin{split}
				v(1,0)-\hat{\mathbb{E}}[\phi(S_n)]&\geq -4n^{-\beta}\int_0^1|\nabla_xv(s,\cdot)|_{\beta}ds\times \hat{\mathbb{E}}[|X_1|^{1+\beta}]+\underline{f},
			\end{split}
        \end{equation}
        where 
		$
			\underline{f}=\inf_{\{0\leq t\leq 1,x\in \mathbb{R}^d\}}f(t,x)
	$ with $f$ defined as in (equation PDE of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm jointr1r2 of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Fix integers $2 \le r_1 < r_2$. Let $\bm H_n = (H_n^{(1)}, H_n^{(2)})$ be a sequence of 2-hypermultiplexes on the same set of vertices $V_n$, such that 
$H_n^{(1)}$ is $r_1$-uniform, $H_n^{(2)}$ is $r_2$-uniform, $|E(H_n^{(1)})| \to \infty,$ and $|E(H_n^{(2)})| \to \infty$. Suppose $V_n$ is colored uniformly at random with $c_n$ colors as in (equation eq:cn of the paper), such that the following hold: 
      \begin{itemize}
      \item  There exist constants $\lambda_1, \lambda_2 \ge 0$ such that 
            \begin{align}
            \frac{|E(H_n^{(1)})|}{c_n^{r_1-1}} \to \lambda_1,~\frac{|E(H_n^{(2)})|}{c_n^{r_2-1}} \to \lambda_2 . 
            \end{align}

      \item  For all $t_1 \in [2, r_1 - 1]$ and $t_2 \in [2, r_2 - 1]$, 
      \begin{align}
      \frac{|\cK(t_1, H_n^{(1)})|}{c_n^{2r_1-t_1-1}} \to 0 \text{ and } \frac{|\cK(t_2, H_n^{(2)})|}{c_n^{2r_2-t_2-1}} \to 0 , 
      \end{align} 
     where $\cK(\cdot, \cdot)$ is defined in (equation defn:K of the paper). 
  \end{itemize} 
Then 
  $$\bm T(\bm H_n)= \left(\begin{array}{l}
    T(H_n^{(1)}) \\
    T(H_n^{(2)})
    \end{array}\right) \dto \left(\begin{array}{l}
      Z_1\\
      Z_2
      \end{array}\right) , $$
    where $Z_1 \sim \Pois(\lambda_1), Z_2 \sim \Pois(\lambda_2)$ are independent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Mainresultd 3 (Exact profile formulas) of arXiv:2609.04143, 'The Geometry of Real Anisotropic Bohnenblust--Hille Constants'] Let $m\ge2$.
\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.35em]
\item For every $0\le s\le1$,
\begin{equation}
 \max_{\substack{\mathbf q\in\mathcal B_m\\ \sigma(\mathbf q)=s}}
 C_{\mathbf q}^{(m)}
 =2^{(m-1)s/2}.
\end{equation}
The maximum is attained by every permutation of
\[
 \mathbf q_s=\left(\frac{2}{1+s},2,\ldots,2\right).
\]

\item For every Bohnenblust--Hille exponent $\mathbf q$ with $\sigma(\mathbf q)>0$ and $Y_1(\mathbf q)\ge1/2$,
\begin{equation}
 C_{\mathbf q}^{(m)}
 =2^{\frac{\sigma(\mathbf q)}{2}\left(1+(m-2)Y_1(\mathbf q)\right)}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 3 of arXiv:2606.00648, 'Asymptotic estimates for multiple point ranges of transient random walks on graphs'] For every $\epsilon > 0$, there exists $\theta(\epsilon) > 0$ such that 
for every random variable $Y$ on a probability space satisfying $|Y| \le 1$, 
\begin{equation}
E\left[\exp(\theta(\epsilon) Y) \right] \le 1 + \theta(\epsilon) (E[Y] + \epsilon) \le \exp\left(  \theta(\epsilon) (E[Y] + \epsilon) \right). 
\end{equation}

[Lemma 20 of arXiv:2506.18132, 'Throughput in inhomogeneous planar drainage networks'] Let \(\alpha \in (1/2, 2/3)\). Then, for all \(1 \leq a-b \leq \ell^{\alpha}\) (uniformly in \(a, b, j\)), we have that
    \begin{align*}
        \P\big(\boldsymbol{\mathsf \tau}_{(a, b, j, \ell)} \neq \tau_{(a, b, j, \ell)}\big) 
       \rightarrow
        0, \qquad\text{ as } \ell\to\infty.
    \end{align*}

