[Theorem 1 of arXiv:2609.01128, 'Nonabelian Chabauty for the Thrice-punctured Line over Cyclotomic Fields'] Let $K=\bQ(\zeta_8)$, $S=\left\{(1-\zeta_8)\right\}$, and let $p$ be a rational prime which splits completely in $K$. Let \(\sigma_+\) denote complex conjugation and let \(\sigma_i\) denote the automorphism \(\zeta_8\mapsto -\zeta_8\). Label the primes of~$K$ above~$p$ as $\fp_1,\ldots,\fp_4$ with $\fp_2=\sigma_+^*\fp_1$, $\fp_3=\sigma_i^*\fp_1$, and $\fp_4=(\sigma_+\sigma_i)^*\fp_1$.
For $(z_1,z_2,z_3,z_4)\in X(\cO_K\otimes\bZ_p) = \prod_{i=1}^4 X(\cO_{\fp_i})$ write $X_i=\log(z_i)$, $Y_i=L_1(z_i)$, $Z_i=L_2(z_i)$, $W_i=L_3(z_i)$, $V_i=L_4(z_i)$ for $i=1,2,3,4$.
Assume that $L_2(1+ \zeta_8 + \zeta_8^{-1}) \neq 0$ and $L_n(\zeta_8) \pm L_n(-\zeta_8) \neq 0$ for $n=2,3,4$. Then, for each $1\leq N\leq 4$, the depth-$N$ polylogarithmic Chabauty--Kim locus
$X(\cO_K\otimes \bZ_p)_{S,\PL,N}$ is the common solution set of the first $N$ systems of equations below:
\begin{equation}
\tag{E1}
X_1=X_2,\quad X_3=X_4,\quad Y_1=Y_2,\quad Y_3=Y_4;
\end{equation}

\begin{empheq}[left=\empheqlbrace]{equation}
\tag{E2}
\begin{gathered}
    Z_1+Z_2=-Z_3-Z_4,\\
    Z_1+Z_2=c_2\left(-X_3Y_1+X_1Y_3\right).
\end{gathered}
\end{empheq}

\begin{empheq}[left=\empheqlbrace]{equation}
\tag{E3}
\begin{aligned}
    W_1-W_2+W_3-W_4 &= c_{3,1}(X_1+X_3)(Z_1+Z_3) +c_{3,2}(X_1-X_3)(Z_1+Z_4),\\ W_1-W_2-W_3+W_4 &= c_{3,3}(X_1-X_3)(Z_1+Z_3) +c_{3,4}(X_1+X_3)(Z_1+Z_4);
\end{aligned}
\end{empheq}

\begin{empheq}[left=\empheqlbrace]{equation}
\tag{E4}
\begin{aligned}
    V_1+V_2+V_3+V_4 &= c_{4,1}(X_1+X_3)(W_1+W_2+W_3+W_4)\\ &\quad +c_{4,2}(X_1-X_3)(W_1+W_2-W_3-W_4)\\ &\quad +c_{4,3}(X_1-X_3)(X_1+X_3)(Z_1+Z_2),\\ V_1+V_2-V_3-V_4 &= c_{4,4}(X_1-X_3)(W_1+W_2+W_3+W_4)\\ &\quad+c_{4,5}(X_1+X_3)(W_1+W_2-W_3-W_4)\\ &\quad +c_{4,6}(X_1-X_3)^2(Z_1+Z_2)\\ &\quad +c_{4,7}(X_1+X_3)^2(Z_1+Z_2).
\end{aligned}
\end{empheq}
The $p$-adic coefficients $c_2$, $c_{3,1},\ldots,c_{3,4}$ and $c_{4,1},\ldots,c_{4,7}$ can be computed by plugging known $S$-integral points into the equations and using linear algebra, see \Cref{thm:depth2-equations,thm:depth3-equations,thm:depth4-equations}. 
The non-vanishing assumptions are implied by the $p$-adic period conjecture \cite[Conjecture~2.2.11]{ishaidancohen_2020_mixed} and checked numerically for $p < 200$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm main_finite of arXiv:2603.27144, 'On the critical fugacity of the hard-core model on regular bipartite graphs'] There exist $C,c>0$ such that the following
holds for every $\lambda,C_{\mathrm{LE}},M_{\mathrm{LE}}>0$ and integer $\delta\ge2$.
Let $G=(V,E)$ denote a finite simple $\delta$-regular bipartite
graph, with bipartition $(\mathcal{E},\mathcal{O})$. Suppose that $G$ satisfies
the local expansion property with parameters $C_{\mathrm{LE}},M_{\mathrm{LE}}$. Then,
first,
\begin{equation}
\frac{1}{|V|}\log Z^{G}\le\frac{1}{2}\log(1+\lambda)+\frac{CC_{\mathrm{LE}}}{\delta}\left((1+\lambda)^{-\frac{\delta}{CC_{\mathrm{LE}}}}+\frac{1}{M_{\mathrm{LE}}}\right).
\end{equation}
Second, for $r>0$, if
\begin{equation}
\log(1+\lambda)>\frac{CC_{\mathrm{LE}}}{\delta}\max\left\{ \log\left(\frac{C\delta}{h(G)}\cdot\frac{|V|}{r}\right),\frac{\delta}{h(G)}\cdot\frac{|V|}{r}\cdot\frac{1}{M_{\mathrm{LE}}}\right\} 
\end{equation}
then
\begin{equation}
\mu^{G}(\min\{|\sigma_{\mathcal{E}}|,|\sigma_{\mathcal{O}}|\}>r)\le\frac{\zeta^{G}(\min\{|\sigma_{\mathcal{E}}|,|\sigma_{\mathcal{O}}|\}>r)}{(1+\lambda)^{|V|/2}}\le(1+\lambda)^{-c\frac{h(G)}{\delta}r}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

