[Theorem 22 of arXiv:2506.15044, '2506.15044'] Let $M\in (\mathcal{M}_{\mathrm{loc}})^\mathbb{B}$.
\begin{itemize}
  \item [$(1)$] $M$ admits a unique decomposition
\begin{equation}
M=M_0\mathfrak{I}_\mathbb{B}+M^c+M^d,
\end{equation}
where $M^c\in (\mathcal{M}^c_{\mathrm{loc},0})^\mathbb{B}$ and $M^d\in (\mathcal{M}^d_{\mathrm{loc}})^\mathbb{B}$. $M^c$ is called the {\bf continuous martingale part} of $M$, and $M^d$ is called the {\bf purely discontinuous martingale part} of $M$.
  \item [$(2)$] If $(T_n,M^{(n)})$ is an FCS for $M\in (\mathcal{M}_{\mathrm{loc}})^\mathbb{B}$, then $(T_n,(M^{(n)})^c)$ and $(T_n,(M^{(n)})^d)$ are FCSs for $M^c\in(\mathcal{M}^c_{\mathrm{loc},0})^\mathbb{B}$ and $M^d\in(\mathcal{M}^d_{\mathrm{loc}})^\mathbb{B}$, respectively.
  \item [$(3)$] If $\tau$ is a $\mathbb{B}$-inner stopping time, then we have
  \begin{equation}
  (M^c)^\tau=(M^\tau)^c,\quad (M^d)^\tau=(M^\tau)^d
  \end{equation}
  and
  \begin{equation}
  (M^c)^\tau\mathfrak{I}_\mathbb{B}=(M^\tau)^c\mathfrak{I}_\mathbb{B}=(M^\tau\mathfrak{I}_\mathbb{B})^c,\quad (M^d)^\tau\mathfrak{I}_\mathbb{B}=(M^\tau)^d\mathfrak{I}_\mathbb{B}=(M^\tau\mathfrak{I}_\mathbb{B})^d.
  \end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

