[Definition def:cycles of arXiv:2607.02367, 'Flux solutions for stochastic chemical systems with sources and sinks'] The space of the cycles of a chemical system  $(\Omega, \mathcal R, \mathcal R_s,  \mathcal K, \mathcal K_s )$ is defined as
\begin{equation*}
\mathcal W := \left\{  w \in \mathbb R^{r + |\Omega_c|} : \sum_{\rho=1}^{r } w(\rho) S_\rho + \sum_{ k \in \Omega_c } w(k ) =0 \right\}. 
\end{equation*}

[Proposition 12 of arXiv:2605.30055, 'The Wasserstein cost of importance sampling'] Let $\varphi$ be a bounded measurable function. We suppose that $W\varphi(X)$ is bounded by a constant $m_\varphi:=|W\varphi(X)|_\infty$. Then, noting $\sigma^2_\varphi = \mathrm{Var}(W \varphi(X))$, we have 
    \begin{equation}
        \mathbb{P}\left(\sum_{i=1}^n W_i \varphi(X_i) > (1+\delta) n\int g(x)\varphi(x)\,dx\right) \leqslant \exp\left(-n \frac{\sigma^2_\varphi}{m_\varphi^2} h\left(\frac{\delta m_\varphi }{ \sigma^2_\varphi} \int g(x)\varphi(x)\,dx\right)\right).
    \end{equation}
    where $h(x) = (1+x)\ln(1+x) - x$.
    The same inequality holds for the lower deviation.

[Lemma 13 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] $2\leq h\leq n$. Let $C_1,\dots,C_h$ be a partition of $\hat V$ and $T^h=T^h(C_1,\dots,C_n)$ defined as after \eqref{peRk}. Then:
\begin{equation}
	\sum_{(y_2,\dots ,y_h)\in T^h}r(s,y_2)\cdots r(s,y_h) 	\,=\, 
\left(r^\textup{out}(s)\right)^{h-2}\;\sum_{y\in C_1}r(s,y)
\end{equation}

[Definition Def_ModuliSpaceOfRamifiedEuclideanLineBundles of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] {Doan2024}}]

  The \defined{moduli space of ramified Euclidean line bundles} over $X$ is constructed as follows:
  \begin{enumerate}
  \item

    Denote by $\mathbf{Sub}$ the \emph{set} of closed codimension-two submanifolds $Z \subseteq X$.
    Equip $\mathbf{Sub}$ with the following tame Fréchet manifold structure described in [Hamilton1982:NashMoser].

    Given $Z \in \mathbf{Sub}$ and a tubular neighbourhood $\jmath \mskip0.5mu\colon\thinspace NZ \supseteq U \to X$ of $Z$,
    define the map $\phi_\jmath^{-1} \mskip0.5mu\colon\thinspace \Gamma\paren{Z,NZ} \supseteq \Gamma\paren{Z,U} \to \mathbf{Sub}$ by
    \begin{equation*}
      \phi_\jmath^{-1}(v) \coloneq \im \paren{\jmath \circ v}.
    \end{equation*}
    Denote by $\phi_\jmath$ the inverse of $\phi_\jmath^{-1} \mskip0.5mu\colon\thinspace \Gamma\paren{Z,U} \to \im \phi_\jmath^{-1}$.
    Equip $\Gamma\paren{Z,NZ}$ with the usual structure of a tame Fréchet space;
    see [Hamilton1982:NashMoser].
    The charts constructed in [Hamilton1982:NashMoser] are of the form $\phi_\jmath$. 
  \item

    Denote by $\mathbf{Ram}$ the \emph{set} of isometry classes of ramified Euclidean line bundles $(Z,{\mathfrak l})$ over $X$ with smooth $Z$.
    Consider the map
    \begin{equation*}
      \mathrm{Br} \mskip0.5mu\colon\thinspace \mathbf{Ram} \to \mathbf{Sub}
    \end{equation*}
    assigning to $(Z,[{\mathfrak l}])$ the branching locus $Z$.
  \item

    For every open subset $U \subseteq X$ denote by $\mathbf{Sub}_U \subseteq \mathbf{Sub}$ the open subset of those $Z \in \mathbf{Sub}$ for which:
    \begin{enumerate}
    \item
      $Z \subseteq U$, and
    \item
      the restriction ${\rm H}^1\paren{X{\backslash} Z,\set{\pm 1}} \to {\rm H}^1\paren{X{\backslash} U,\set{\pm 1}}$ is an isomorphism.
    \end{enumerate}
    The subset $\mathbf{Sub}_U$ is open and the monodromy representations assemble into an injection
    \begin{equation*}
      \tau_U \mskip0.5mu\colon\thinspace \mathrm{Br}^{-1}(\mathbf{Sub}_U) \to \mathbf{Sub}_U \times {\rm H}^1\paren{X{\backslash} U,\set{\pm 1}}.
    \end{equation*}
    Equip $\mathbf{Ram}$ with the coarsest \emph{topology} with respect to which the maps $\tau_U$ are continuous.
  \item

    With respect to the above topology $\mathrm{Br} \mskip0.5mu\colon\thinspace \mathbf{Ram} \to \mathbf{Sub}$ is a locally finite covering map; cf.~[tomDieck2008:AlgebraicTopology].
    In particular, $\mathbf{Ram}$ inherits the structure of a tame Fréchet manifold from $\mathbf{Sub}$.
    Moreover, for every $(Z,[{\mathfrak l}]) \in \mathbf{Ram}$,
    \begin{equation*}
      T_{(Z,[{\mathfrak l}])}\mathbf{Ram} = T_Z\mathbf{Sub} = \Gamma\paren{Z,NZ}.
    \end{equation*}
  \end{enumerate}
  In the following $(Z,[{\mathfrak l}])$ is frequently abbreviated to $[{\mathfrak l}]$.
  This is harmless, because $Z$ can be recovered as $\mathrm{Br}({\mathfrak l})$.
  \qedhere

[Proposition bound_separating_multicurve of arXiv:2506.02611, '\textbf{The tight length spectrum of large-genus random hyperbolic surfaces with many cusp'] For any $\mu_g \underset{g \to +\infty}{\rightarrow}\mu_c$ such that $\mu_c- \mu_g = o(g^{-2})$, any $r >0$ and $1 < q \le r+1$, we have for $g$ large enough
    \begin{align*}
       \frac{1}{M_0(\mu_g)^{r} T_{g}(\mu_g)}\cdot \somme{(g_1,n_1),\ldots,(g_q,n_q)}{}{}\displaystyle \prod_{i=1}^{q}T_{g_i,n_i}(\mu_g) \le  \frac{C_r}{g^{q-1}},
    \end{align*}
    where the sum is taken over all sequences $(g_1,n_1),\ldots,(g_q,n_q)$ such that $2g_i+n_i\ge 3$ and $\somme{i=1}{q}{g_i} = g + q -r -1 $ and $\somme{i=1}{q}{n_i} = 2r$. The constant $C_r > 0$ only depends on $r$ and the sequence $(\mu_g)$.

