[Proposition prop:diffusion_limit_FSL_SSL of arXiv:2607.13748, 'Load Balancing with Individually Heterogeneous Servers'] For $\pi \in \{ \mathrm{FSL}, \mathrm{SSL}\}$, $\tilde{\mathbf{X}}_b^{\pi,n} \Rightarrow \tilde{\mathbf{X}}^\pi$, where $\tilde{\mathbf{X}}^\pi$ is the unique solution of
        \begin{align}
             X_1^\pi(t) & = X_1(0) - (\varsigma + \nu)t + \sqrt{2} W(t) - \mu_{1}^{\pi} \int_0^t X_1^\pi(s) \, ds + \mu_{2}^\pi \int_0^t X_2^\pi(s) \, ds - U_1^{\pi}(t), \\
            X_2^\pi(t) & = X_2(0) + U_1^{\pi}(t) - \mu_{2}^\pi \int_0^t X_2^\pi(s) ds + \mu_{2}^\pi \int_0^t X_3^\pi(s) \, ds, \\
        X_i^\pi(t) & = X_i(0) - \mu_{2}^\pi \int_0^t X_i^\pi(s) ds + \mu_{2}^\pi \int_0^t X_{i+1}^\pi(s) \, ds, \quad \text{for all } 3\leq i\leq b,
    \end{align}
    where $\mu_1^{\mathrm{FSL}}=\mu_2^{\mathrm{SSL}} = \mu_{\min}$, $\mu_2^{\mathrm{FSL}}=\mu_1^{\mathrm{SSL}} = \mu_{\max}$ and $U_1^{\pi}(t)\in \mathbb{D}_{\mathbb{R}_+}[0,\infty)$ is a non-decreasing function and satisfies
    \begin{align*}
        \int_0^\infty \mathbb{I}(X_1^{\pi}(s)<0)dU_1^{\pi}(s) = 0.
        \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2506.11707, 'Fluctuations of two-dimensional determinantal processes associated with Berezin--Toeplitz '] Let $f: \C \to \R$, with $|f|\le C(1+|\cdot|)$ for some $C\ge 0$,  be $C^\infty$ in a neighborhood of $\mathcal{D}=\{V<\mu\}$.
Under Assumptions~\ref{ass:V}, define the Fourier coefficients of
$f$ along the curve $\{V=\mu\}$ as
\begin{equation} 
\widehat{f}_k = \int_{[0,2\pi]} f(z_\theta) e^{-ik\theta}  \frac{\d\theta}{2\pi} ,\qquad k\in \N,
\end{equation}
and define
\begin{equation} 
\Sigma^1_{\mathcal{D}}(f) := \tfrac12 \|f\|_{\dot{H}^{\frac12}(\partial\mathcal D)}^2  = \sum_{k\ge 1} k |\widehat{f}_k|^2 \, , \qquad 
\Sigma^2_{\mathcal{D}}(f) :=  \tfrac 12 \|f\|_{\dot{H}^{1}(\mathcal{D})}^2 =
\frac 12 \int_{\mathcal{D}}  |\nabla f|^2 \d\bgamma \,.
\end{equation}
Then, one has the following two-term asymptotics as $N\to\infty$:
\begin{equation} 
\E_{\Pi_N}[e^{\X(f)}]= \exp( \E_{\Pi_N}\X(f)+ \tfrac12 \Sigma(f) + o(1) )
\end{equation}
where $\Sigma(f) = \Sigma^1_{\mathcal{D}}(f)+\Sigma^2_{\mathcal{D}}(f)$.
In particular,
\begin{equation} 
\X(f) - \E \X(f) \,\Longrightarrow\, \sqrt{\Sigma(f)}\, \mathcal{G}
\qquad \text{as }N\to +\infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

