[Lemma SCE3 of arXiv:2607.21862, '\bf Uniform Large Deviations of Mckean-Vlasov Stochastic Fractional $(\alpha,p)$-Laplacian'] Let conditions  {\bf A} and {\bf B1}
be satisfied. Then for every $T>0$, $\delta>0$, $R>0$ and $N>0$, we have
\begin{align*}
&\lim_{\epsilon\rightarrow0}\sup_{\psi_{0}\in \overline{B}_{R}(\mathbb{H})}
\sup_{u\in \mathfrak{A}_N}\mathbf{P}\Big\{ \|\psi^\epsilon_u-\psi_u\|_{C([0,T],\mathbb{H}) \bigcap L^p([0,T], \mathbb{V}_1)\bigcap L^q([0,T], \mathbb{V}_2)}>\delta\Big\}=0,
\end{align*}
where $\psi^\epsilon_u=
\mathfrak{M}_{\psi_0,\mathcal{L}_{
\psi^\epsilon}}^\epsilon
\big(\mathcal{W}+\frac{1}{\sqrt{\epsilon}}
\int_0^\cdot u(t)dt\big)$ and $\psi_u=
\mathfrak{M}_{\psi_0}^0
\big(
\int_0^\cdot u(t)dt\big)$ are solutions of (equation Int1--- of the paper) and (equation Int1--++ of the paper), respectively.

[Lem lemma:estimates_bar_V_for_existence of arXiv:2605.29073, 'Volterra clocks and their pure-jump limits: \\hitting times of curved boundaries'] Let $(Y\,, X)$ be as in Lemma (lemma:existence_Volterra_V of the paper). Then, there exists a constant $C > 0$ depending on $g_0\,$, $\nu\,$, $T$ and $f$ such that 
    \begin{equation}

        \mathbb E \left[\sup_{t \leq T}\,(X_t)^2 \right] \leq C\,\left(1 + \int_0^T\,\left|R_{-C\bar K(T) K}(s) \right|\,ds \right)\,,
    \end{equation}
    where $\bar K := \int_0^{\cdot}\,K(s)\,ds\,$, and $R_{-c\bar K(T) K}$ is the resolvent of the second kind of $t \mapsto -C\bar K(T)\,K(t)$ (see Appendix (app:resolvents of the paper)).

    Moreover, for $s \leq t \leq T\,$, we have 
    \begin{equation}

    X_t - X_s \leq G_0(t) - G_0(s) + 2\nu\,\|M\|_{\infty}\, \bar K(t-s)\,.
    \end{equation}

[Cor of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] The partition function for the walk bridges  from $(0,H)$ to $(L,0)$, with weights given in Definition (def:walkbridge of the paper), is 
\begin{equation}
  \frac{H+1}{L+1} \frac{1}{2\pi i} \oint\; \left(\frac{z}{z_c(N)}\right)^H V_{N}(z)^{L+1} \; dz
\end{equation}
where the contour only encloses the pole at $0$.

[Prop P: consistency condition of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Assume that $\mathbf{P} \{ f_{+},f_{-} \in \mathcal{S} \} = 1$ and (equation E: decay one of the paper) holds, and fix $\theta \in \mathbb{R}$.  Define $p^{(N)} = 1/2 + \theta N^{-1}$.  Consider the operator $\mathscr{L}^{(N)}$ given by (equation E: definition of L of the paper) with $p = p^{(N)}$.  If $G : \mathbb{R} \to [0,1]$ is a nondecreasing function with bounded, uniformly continuous first and second derivatives, rescaled according to the rule $G_{\delta}(y) = G(\delta y)$, and if $R_{G}^{(N)} : \mathbb{R} \to \mathbb{R}$ is the remainder defined so that
		\begin{align*}
			( \mathscr{L}^{(N)} G_{N^{-\frac{1}{2}}} )( N^{\frac{1}{2}} x ) = N^{-1} \sigma | \partial_{x} G ( x ) |^{2} + N^{-1} R_{G}^{(N)}(x),
		\end{align*}
	then $R^{(N)}_{G} \to 0$ uniformly in $\mathbb{R}$ as $N \to +\infty$.

	Further, if the stronger assumption (equation E: decay two of the paper) holds,  and if $R^{(N)}_{G}$ is instead defined by
		\begin{align*}
			( \mathscr{L}^{(N)} G_{N^{-\frac{1}{3}}} )( N^{\frac{1}{3}} x ) = N^{- \frac{2}{3} } \sigma | \partial_{x} G ( x ) |^{2} + N^{ -1 } a | \partial_{x} G ( x ) | \partial_{x}^{2} G ( x ) + N^{ -1 } R_{G}^{(N)}(x),
		\end{align*}
	then, as before, $R^{(N)}_{G} \to 0$ uniformly as $N \to +\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2605.13727, 'Stochastic evolution equations\\ driven by arbitrary cylindrical Lévy processes'] Let $U,H$ and $V$ be separable Hilbert spaces, and $L$ be a cylindrical L\'evy process in $U$. For each $C \in L_2(U,H)$ and $D \in L(H,V)$ with $\norm{D}\leq r$ for some $r>0$, the following assertions hold:
    \begin{enumerate}
        \item [{\rm (1)}] $\zeta_L(DC)\leq \max\{r,1\}\, \zeta_L(C)$;
        \item [{\rm (2)}] $\eta_L(DC)\leq d_r\left(\eta_L(C)+ \zeta_L(C)\right)$ for some constant $d_r>0$ depending only on $r$.
    \end{enumerate}

