[Definition def:F-DDSDE of arXiv:2607.00800, 'Brownian motion in Minkowski normed spaces'] \ 
\begin{enumerate}[(i)]
    \item A (\emph{probabilistically weak}) \emph{solution} to (equation eq:DDSDE of the paper) is a quadruple consisting of a stochastic basis $(\Omega, \mathcal F, (\mathcal F_t)_{t\geq 0}, \mathbb{P})$, an $(\mathcal F_t)$-standard Brownian motion $W = (W_t)_{t\geq 0}$, a family of probability densities $u(t) \in \mathfrak{C}$, $t>0$,  and an $(\mathcal F_t)$-adapted stochastic process $X = (X_t)_{t\geq 0}$ on $\Omega$ such that $\mathcal{L}(X_t)  = u(t,x) \,\mathrm d x$ for all $t>0$,
    \begin{equation*}
        \mathbb{E}\bigg[ \int_0^T \Bigl( \bigl|b\bigl(X_t,\mathcal{L}(X_t)\bigr)\bigr| + \bigl|a\bigl(X_t,\mathcal{L}(X_t)\bigr) \bigr| \Bigr) \,\mathrm d t \bigg] < \infty, \quad \forall T>0
    \end{equation*}
    (where $\mathbb{E}$ denotes the expectation with respect to $\mathbb{P}$),
    and, $\mathbb{P}$-a.s.,
    \begin{equation*}
        X_t -X_0 = \int_0^t b\bigl( X_r,\mathcal{L}(X_r) \bigr) \,\mathrm d r + \int_0^t \sqrt{2a\bigl(X_r,\mathcal{L}(X_r)\bigr)} \,\mathrm d W_r,\quad \forall t\geq 0.
    \end{equation*}
Below, we usually simply refer to $X$ instead of the entire quadruple as a solution.
\item For each solution $X$, we call its path law $P = \mathcal{L}(X)$ (a probability measure on $C([0,\infty);\mathbb{R}^d)$) a \emph{solution path law} to (equation eq:DDSDE of the paper).
\item We say that solutions to (equation eq:DDSDE of the paper) with initial datum $\zeta \in \mathcal P$ are \emph{weakly unique} if $\mathcal{L}(X) = \mathcal{L}(Y)$ for any two solutions $X,Y$ with $\mathcal{L}(X_0) = \mathcal{L}(Y_0) = \zeta$. 
\end{enumerate}

[Proposition prop:partial-stability of arXiv:2509.08430, 'One-dimensional particle clouds with elastic collisions'] Suppose that $\ell, r \in [N]$, $\ell < r$, 
    and it holds that
    \begin{equation}

 \frac{U_{\ell,k}}{M_{\ell,k}} < \frac{U_{\ell,r}}{M_{\ell,r}} \text{ for all } k \in [ \ell ; r-1]. 
     \end{equation}
    Then there exist constants $C \in {\mathbb R}_+$ and $\delta > 0$ (depending on the $a_i, b_i$, and $m_i$)
    such that 
    \begin{equation}

\sup_{t \in {\mathbb R}_+} \Pr \left[ \Delta_{[\ell+1;r]} (t) \geq s \right] \leq C \left[ 1 + {\mathrm{e}}^{C \Delta_{[\ell+1;r]} (0) } \right] {\mathrm{e}}^{-\delta s} , \text{ for all } s \in {\mathbb R}_+,     \end{equation} 
and, moreover,
    \begin{equation}

    \limsup_{t \to \infty} \frac{\Delta_{[\ell+1;r]} (t)}{\log t} < \infty, \ \text{a.s.} \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma priori-combine-2026-6-5 of arXiv:2609.01488, 'Stabilization by a background magnetic field: global well-posedness of the full compressib'] Let $M, N\geq3$. Assume $(\rho,\mathbf u,p,\mathbf h)$ is a smooth solution to   the system (equation no-heat-mhd3 of the paper) on $\mathbb T^3\times[0,T]$ for some $T>0$ satisfying (equation suppose-1 of the paper) and (equation rhoH-M of the paper). Then there is a positive constant $A_8$ satisfying $A_8\sim\|\rho_0\|^{2(N-1)}_{M}+1$ such that
\begin{align}
\frac{d}{dt}&\widetilde{\mathcal E}(t)+\frac{2}{3}\underline\rho\|\mathbf u_t\|^2_{N-1}+\frac{4}{3}\|\mathbf u\|_{N+1}^2\nonumber\\
&\lesssim\|\rho\|^2_{N-1}\|\mathbf u_t\|^2_{2}+(\|\rho_0\|_M\|\mathbf u\|_3\|\mathbf u\|_{N}+\|\rho\|_N\|\mathbf u\|^2_{3})\|\mathbf u\|_N+\|\rho\|^2_{N-1}\|\mathbf u\|^4_3\nonumber\\
&\quad+\|(\mathbf u,p,\mathbf h)\|^2_{3}\|(\mathbf u,p,\mathbf h)\|^2_{N}+(\|\rho_0\|^{2(N-1)}_{M}+1)(1+\|(\mathbf u,p,\mathbf h)\|_2)\|(\mathbf u,p,\mathbf h)\|_2^3\nonumber\\
&\quad+\|(\mathbf u,p,\mathbf h)\|_{3}\|(\mathbf u,p,\mathbf h)\|^2_{N},
\end{align}
and
\begin{equation}
\|(\mathbf u,p,\mathbf h)\|^2_N\leq \widetilde{\mathcal E}(t)\leq B_5\big(\|\rho_0\|^{2(N-1)}_{M}+1\big)\|(\mathbf u,p,\mathbf h)\|^2_N
\end{equation}
with $\widetilde{\mathcal E}(t):=A_8\mathcal A(t)+E_{N}(t)$. Here $B_5>0$ is a constant depending only on $\mathbb T^3$, $|\mathbf n|$, $N$, $\mu$, $\lambda$, $\gamma$, $\bar P$, $\underline{\rho}^{-1}$, $\bar\rho$, $M_0$, $r$ and $c$.

