    \leq
    \left( \frac{n}{t v} \right)^2 \right) \geq c \frac{\log t}{t^2}.
    \end{equation}
    Moreover, there exists a constant $c^\prime>0$ so that for any $n\geq 3$, $v\in [n/4]$ and $t\in\big(1, \frac{1}{\sqrt{3}} (n/v) \big)$,
    \begin{equation}
        \mathbb{P} \left( \phi_n^{{\scriptscriptstyle{({2}})}}(v)
    \leq
    \left( \frac{n}{t v} \right)^2 \right) \geq c \frac{1}{t^2}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2608.19576, 'Convex order preservation for graphon mean-field systems'] Let $\varphi \in \mathbb{C}_{cv}(\mathbb{R}^d, \mathbb{R})$ with linear growth. Then, for every $m \in \mathbb{N}^*$ and $u \in I$:

    \textup{(i)} the function $(x, e) \mapsto (Q^u_m \varphi) (x,e)$ is (finite and) convex; 

    \vspace{1mm}

    \textup{(ii)} for any fixed $x \in \mathbb{R}^d$, the function $e \mapsto (Q^u_m \varphi)(x, e)$ attains its minimum at $\mathbf{0}^{d \times q}$, where $\mathbf{0}^{d \times q}$ is the zero-matrix of size $d \times q$; 

    \vspace{1mm}

    \textup{(iii)} for any fixed $x \in \mathbb{R}^d$, the function $e \mapsto (Q^u_m \varphi)(x,e)$ is nondecreasing with respect to the partial order of $d \times q$ matrix, defined in \eqref{A:eqn:7};

    \vspace{1mm}

    \textup{(iv)} for any $\boldsymbol{\mu} \in \mathcal{H}(\mathbb{R}^d)$, the function $x \mapsto \mathbb{E}\big[\varphi\big(b_m(x)+\sigma^u_m(x, \boldsymbol{\mu}) Z^u_{m+1}\big)\big]$ is convex with linear growth.

[Theorem 13 (McLeish, 1974) of arXiv:2609.00292, 'Extinction, Survival and Fluctuations for the Spatial Maki--Thompson Model on Infinite Gra'] Let $\{Z_{n,j}:n\ge1,\ 1\le j\le b_{n}\}$ be a martingale-difference
    array with respect to filtrations $(\mathcal{H}_{n,j})_{0\le j\le b_n}$.
    Assume that
    \begin{enumerate}
        \item $\sup_{n\ge1}\mathbb{E}\left[ \max_{1\le j\le b_n}|Z_{n,j}|^{2}
                      \right ] <\infty;$

        \item $\max_{1\le j\le b_n}|Z_{n,j}| \xrightarrow[n\to\infty]{\mathbb{P}}
                  0;$

        \item $\sum_{j=1}^{b_n}Z_{n,j}^{2}\xrightarrow[n\to\infty]{\mathbb{P}}
                  1.$
    \end{enumerate}
    Then
    \[
        \sum_{j=1}^{b_n}Z_{n,j}\xrightarrow[n\to\infty]{d}\mathcal{N}(0,1).
    \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary thm:Jacobi-inverse of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] For any $\gamma\in(\mu,1-\mu)$ and $k\ge0$,
\begin{equation}
 J_\Gamma:
 C^{k+2,\alpha}_\gamma
 \longrightarrow
 C^{k,\alpha}_{\gamma+2}
\end{equation}
is an isomorphism on axis-smooth invariant functions, and
\begin{equation}
 \|f\|_{C^{k+2,\alpha}_\gamma}
 \le C_k\|J_\Gamma f\|_{C^{k,\alpha}_{\gamma+2}}.
\end{equation}

