[Lemma 24 of arXiv:2608.15616, '\textbf{Compact Support Property of Super-Brownian Motion with Irregular Drift}'] Let $\eta \in (0,1/2)$ and $b_1>0$ and  let $c_\eta >0$ be such that 
        \begin{equation}
			\frac{1}{\Gamma(\mu)}\int_{c_\eta}^\infty u^{\mu-1}\ee^{-u}du \geq \frac{3}{4},
		\end{equation}
        for $\mu = 1-2\eta$.
        Assume that $f\in \mcC_c^+$ with $f\neq 0$, $m_f = \langle f,1\rangle$ and $K_f = \mathrm{diam}(\supp(f))/2$ is such that the following is satisfied
		\begin{enumerate}




			\item It holds that 
		\begin{equation*}
			m_f  = \langle f, 1\rangle < \frac{c_\eta}{2}.
		\end{equation*}
		\item For $\gamma(1,K_f, m_f) := A(1)(K_f+\sqrt{K_f} +\beta(1,m_f))$ with $A$ and $\beta$ from \eqref{eq:expectation_RT_est}, it holds that 
		\begin{equation}
			\frac{b_1}{\eta}\gamma(1, K_f, m_f) \leq 10^{-2}.
		\end{equation}





		\end{enumerate}
		Then it holds for all $t\geq \frac{2m_f}{c_\eta}$ that 
		\begin{equation*}
			\mathbbm{P}(\langle X_t ,1\rangle = 0) > \frac{1}{2},
		\end{equation*}
		where $X$ is the solution to \eqref{eq:SPDE1_sup} with $b_1>0$ and $f\in \mcC_c^+$ as above.

