[Lemma lem-Upsilon of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] \begin{enumerate}
\item There is a unique $\sigma$-finite measure $\Upsilon$ on ${\mathcal T }^*$ such that
\begin{equation}
\1_{{\mathcal T }_W^*}\,\Upsilon = \pi^*\circ Q_W,\qquad W\subset\mathbb{R}^d\mbox{ a box}.
\end{equation}

\item $\Upsilon$ is invariant under time-reversal and spatial shifts.

\item For any $W\Subset \mathbb{R}^d$ and any ${\mathbf x}=(x_n)_{n\in\{0,\dots,N\}}\in{\mathcal T }_{W\to W}$,
\begin{equation}
\begin{aligned}
Q_W\big((X_{-n})_{n\in\mathbb{N}_0}\in A, &(X_n)_{n\in\{0,\dots,L_W\}}\in {\rm d} {\mathbf x},(X_{L_W+n})_{n\in\mathbb{N}_0}\in B\big)\\
&=\mathbb{P}_{x_0}^{{{\scriptscriptstyle{({W}})}}}(A){\operatorname e }_W(x_0)\mathbb{P}_{x_0}((X_n)_{n\in\{0,\dots,N\}}\in {\rm d}{\mathbf x}) \mathbb{P}_{x_N}^{{{\scriptscriptstyle{({W}})}}}(B),\qquad  A,B\subset {\mathcal T }_+\mbox{ mb.}
\end{aligned}
\end{equation}
\end{enumerate}

[Lemma lemma-sup  S_k -001 of arXiv:2412.08932, 'Gaussian heat kernel asymptotics for conditioned random walks'] There exists a constant $c > 0$ such that, 
for any $M \geqslant 1$ and $n\geqslant 1$, 
\begin{align*} 
 \sup_{x \in \bb R}
\bb P\left( \sup_{1\leqslant k \leqslant n}  | x + S_k | \leqslant M   \right) \leqslant c e^{-  \frac{n}{2 M^2}}.
\end{align*}

