body:
[Lem 18 (Useful bounds for $\mathfrak{b}_h$) of arXiv:2604.20323, '2604.20323'] There exists $C\geq 1$ s.t. for all $h>0$ and all $(s,z)\in [0,T] \times \R^d$, $s\neq \tau_s^h $,
	\begin{itemize}
		\item Pointwise control (uniform in $z$)
		\begin{equation}
			|\mathfrak b_h(s,z)|\le C (s-\tau_s^h)^{-\frac d{\alpha p}+\frac\beta\alpha}\|b(s,\cdot)\|_{B_{p,q}^\beta}.
		\end{equation}
		\item Time-integrated pointwise control (uniform in $z$)
		\begin{equation}
			\left|\int_{\tau_s^h}^s\mathfrak b_h(u,z)d u \right|\le C (s-\tau_s^h)^{\frac{\gamma}{\alpha}+\frac{1-\beta}{\alpha}}\|b\|_{L^\vartheta-B_{p,q}^\beta}.

		\end{equation} 
		\item Spatial H\"older modulus of the integrated drift\\
		For all $(z,z')\in (\R^d)^2 $, $\zeta\in [-\beta,\gamma -\beta) $,
		\begin{equation} 
			\left|\int_{\tau_s^h}^s\Big(\mathfrak b_h(u,z)-\mathfrak b_h(u,z')\Big)d u \right|\le  C|z-z'|^\zeta (s-\tau_s^h)^{\frac{\gamma}{\alpha}+\frac{1-\beta-\zeta}{\alpha}}\|b\|_{L^\vartheta-B_{p,q}^\beta}.

		\end{equation}
		\item Besov norm of the mollified drift
		\begin{equation}

			\|\mathfrak b_h(s,\cdot)\|_{B_{p,q}^\beta}\le \|b(s,\cdot)\|_{B_{p,q}^\beta}.
		\end{equation}
		\item Approximation in Besov norm. {For $\tilde \gamma\in [0,\gamma] $},
		\begin{equation}
		\|b(s,\cdot)-\mathfrak b_h(s,\cdot)\|_{\B_{p,q}^{\beta-{\tilde \gamma}}}\lesssim h^{\frac{{\tilde \gamma}}{\alpha}}\|b(s,\cdot)\|_{\B_{p,q}^{\beta}}.
		\end{equation}
		\item Besov norm of the conditioned scheme. 
		For all $\varphi\in B_{p,q}^\beta $, $\rho\in (-\beta,-\beta+\gamma) $, {$0\le s<t\le T$},
		\begin{align}

				\|\Gamma^h(0,x,\tau_s^h,\cdot)\nabla P^\alpha_{t-\tau_s^h}\varphi(\cdot+\int_{\tau_s^h}^s \mathfrak b_h(r,\cdot)dr )\|_{B_{p',q'}^{-\beta}}\lesssim& \Big[t^{\frac{\beta+\rho}{\alpha}}\Big(s^{-(\frac \rho\alpha+\frac{d}{p\alpha})}(t-s)^{-\frac 1\alpha+\frac \beta\alpha-\frac d{p\alpha}}\notag\\
				&+s^{-\frac d{\alpha p}}(t-s)^{-\frac 1\alpha+\frac{\beta}{\alpha}-\frac \rho\alpha-\frac d{p\alpha}}\Big)\Big]\|\varphi\|_{B_{p,q}^\beta}.
		\end{align}
		\item Time sensitivity for the scheme.
				For {$\varepsilon \in (0,\gamma)$}, all $\varphi\in B_{p,q}^\beta $, {$\rho\in(-\beta,-\beta+\gamma)$}, $s\in [h,\tau_t^h-h] $,
		\begin{align}

				&\left\|\Gamma^h(0,x,\tau_s^h,\cdot)\Big[\nabla P^\alpha_{t-\tau_s^h}\varphi(\cdot+\int_{\tau_s^h}^s \mathfrak b_h(r,\cdot)dr )-\nabla P^\alpha_{t-s}\varphi(\cdot )\Big]\right\|_{B_{p',q'}^{-\beta}}\notag\\
                  \lesssim& h^\frac{\gamma-\varepsilon}{\alpha}\Big[t^{\frac{\beta+\rho}{\alpha}}\Big(s^{-(\frac \rho\alpha+\frac{d}{p\alpha})}(t-s)^{{-\frac\gamma\alpha+\frac\varepsilon\alpha}-\frac 1\alpha+\frac \beta\alpha-\frac d{p\alpha}}

				+s^{-\frac d{\alpha p}}(t-s)^{{-\frac\gamma\alpha+\frac\varepsilon\alpha}-\frac 1\alpha+\frac{\beta}{\alpha}-\frac \rho\alpha-\frac d{p\alpha}}\Big)\Big]\|\varphi\|_{B_{p,q}^\beta}.
		\end{align}

	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

