[Lemma repl_lemma_ave of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] For every $H \in C([0,T])$, for any $t \in [0,T]$ and $z=\epsilon_N$, it holds
\begin{equation} 
\lim_{\epsilon\to 0}\lim_{N\to+\infty}\mathbb{E}_{\nu_N} \left[\Big | \int_0^t [\eta_{sN^2}(z) - \overrightarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}(z)] H(s)ds\Big| \right] =0,
\end{equation}
where, for every $L\in\mathbb N$ and $\eta \in \Omega_N$,
\begin{equation} 
\overrightarrow{\eta}^L(z) :=\frac{1}{L\epsilon_N}\sum_{y= z+\epsilon_N}^{z+L\epsilon_N}\eta(y).
\end{equation}
The same result holds for $z = \tau_N$ by replacing the average to the right, i.e. $\overrightarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}$, by an average to the left, i.e. $\overleftarrow{\eta}^{\lfloor \epsilon N\rfloor}_{sN^2}$, which is defined, for every $L\in\mathbb N$ and $\eta \in \Omega_N$, as
\begin{equation}
 \overleftarrow{\eta}^L(z) :=\frac{1}{L\epsilon_N}\sum_{y=z-L\epsilon_N}^{z-\epsilon_N}\eta(y).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (Uniform moments of the overdamped solution) of arXiv:2608.08177, 'Uniform-in-Time Smoluchowski--Kramers Approximation\\ in Total Variation for Fractional SD'] Under \Cref{ass:dissipative}, for every $p\ge1$ and
$\gamma\in(1/2,H)$,
\begin{align}
 \sup_{t\ge0}\E|Z_t|^p&<\infty,
 \\
 \sup_{k\in\mathbb N_0}
 \E\bigl([Z]_{\gamma;[k,k+1]}^p\bigr)&<\infty.

\end{align}

[Lemma 15 (Localization trick) of arXiv:2607.14361, 'NeuralChaos: Optimal Adapted Approximation of Square Integrable Predictable Processes'] Let $q_{\mathrm{in}},q_{\mathrm{out}}\in\mathbb N_{+}$, $\beta>0$, and $f\,:\,\mathbb{R}^{q_{\mathrm{in}}}\to\mathbb{R}^{q_{\mathrm{out}}}$ be realized by a $\operatorname{ReLU-MLP}$ $\Phi$ with $\operatorname{depth}(\Phi) \leq L$, $\operatorname{width}(\Phi) \leq W$, and $\operatorname{size}(\Phi) \leq S$. Let $S_{\rm in}(\Phi) \leq q_{\mathrm{in}} B$ denote the number of non-zero weights in the first weight matrix of $\Phi$. Then, there exists a $\operatorname{ReLU-MLP}$ $\bar{\Phi}_{\beta}$ realizing a map $\bar{f}\,:\,\mathbb{R}^{q_{\mathrm{in}}}\to\mathbb{R}^{q_{\mathrm{out}}}$ satisfying:
\begin{itemize}
    \item \textbf{\emph{Extension:}} $\bar{f}(x)=f(x)$ for every $x \in [-1,1]^{q_{\mathrm{in}}}$;
    \item \textbf{\emph{Cutoff:}} $\bar{f}(x)=0$ for every $x \in \mathbb{R}^{q_{\mathrm{in}}}$ with $\|x\|_{\infty} \geq 1+\frac{1}{\beta}$.
\end{itemize}
Moreover, with $\ell_{q_{\mathrm{in}}}\eqdef\left\lceil
\log_2(q_{\mathrm{in}}\vee2)\right\rceil$, the network $\bar{\Phi}_{\beta}$ may be chosen so that $\operatorname{width}(\bar{\Phi}_{\beta}) \leq W + D q_{\rm in } + 2 q_{\rm out} + 2$, $\operatorname{depth}(\bar{\Phi}_{\beta}) \leq \max\{L + 2,\ell_{q_{\mathrm{in}}}+2\}+1$, and $\operatorname{size}(\bar{\Phi}_{\beta}) \leq S + C (S_{\rm in}(\Phi) + q_{\rm in } + q_{\rm out} \ell_{q_{\rm in }} + L + q_{\rm out})$, where $C$ is a strictly positive universal constant.

