[Mydef Level sets of CLCD of arXiv:2604.11761, 'The smallest singular value of signed random combinatorial matrices'] Let $H \ge H_0/2$. We define the level set $S_H \subseteq \mathbb{S}^{n-1}$ associated with the parameter $H$ as
\begin{align*}
S_H := \left\{ v \in \mathcal{N}(\delta, \rho) : H \le \operatorname{CLCD}_{\mu n, \gamma}(v) \le 2H \right\}.
\end{align*}

[Proposition prop:common-spectral-localization of arXiv:2608.22910, 'A Commutator Framework for Selective Spectral Alignment in Deep Neural Networks'] Let \(A_\ell\) be symmetric on \(\mathbb R^{m_{\ell+1}}\). Then
\begin{equation}
\|[A_\ell,P_\ell]\|_F^2
=
\sum_{i,j=1}^{m_{\ell+1}}
(\lambda_{\ell,i}-\lambda_{\ell,j})^2
|u_{\ell,i}^\top A_\ell u_{\ell,j}|^2
=
2\sum_{i<j}
(\lambda_{\ell,i}-\lambda_{\ell,j})^2
|u_{\ell,i}^\top A_\ell u_{\ell,j}|^2.
\end{equation}
If \(I_{\mathsf a},I_{\mathsf b}\) are disjoint spectral index sets,
\(
\Pi_{\ell,\mathsf a}=\sum_{i\in I_{\mathsf a}}
u_{\ell,i}u_{\ell,i}^\top
\),
\(
\Pi_{\ell,\mathsf b}=\sum_{j\in I_{\mathsf b}}
u_{\ell,j}u_{\ell,j}^\top
\), and
\begin{equation}
\delta_\ell(\mathsf a,\mathsf b)
:=
\min_{i\in I_{\mathsf a},\,j\in I_{\mathsf b}}
|\lambda_{\ell,i}-\lambda_{\ell,j}|,
\end{equation}
then
\begin{equation}
\|[A_\ell,P_\ell]\|_F^2
\geq
2\delta_\ell(\mathsf a,\mathsf b)^2
\|\Pi_{\ell,\mathsf a}A_\ell\Pi_{\ell,\mathsf b}\|_F^2.
\end{equation}

[Lemma 10 of arXiv:2609.03243, 'Weighted Ces\`aro type operators on the weighted Bergman spaces in the unit ball'] Let $\lambda\in\mathbb{R}$, $\theta>0$ and $\mu$ be a finite positive Borel measure on $[0,1)$. Then
\begin{equation}
\int_{0}^1\Big(\frac{\hat{\mu}(r)}{(1-r)^{\lambda}}\Big)^{\theta}\frac{{\rm d}r}{1-r}<\infty
\end{equation}
if and only if 
\begin{equation}
\sum_{k=1}^{\infty}\Big(\frac{\hat{\mu}(r_k)}{\delta_k^{\lambda}}\Big)^{\theta}<\infty.
\end{equation}

[Lemma 32 of arXiv:2607.02777, 'Hypocoercivity for Hamiltonian Diffusions \\ with Singular Drift'] Let $d_1 \leq d_2$ and $Q\in \mathbb{R}^{d_1\times d_2}$ be of full rank. Assume \textup{($\Phi_1$1)}. Then 
        $\textup{(eT)}$ holds
        if \textup{($\Phi_1$5)} or the following condition is satisfied:
    	\begin{itemize}[leftmargin = 1.1cm]
    		\item[\textup{(eT)$'$}] It holds $\vert\nabla\phi_1\vert \in L^2(\mu_1)$, $\vert\nabla\phi_1\vert^2 +\vert\nabla^2\phi_1\vert \in L_\textup{loc}^2(\mathbb{R}^{d_1},\mu_1)$, $\vert \nabla\phi_1\vert^2 e^{-\phi_1}\in L_\textup{loc}^\infty(\mathbb{R}^{d_1},\mu_1)$ and $d_1\geq 2$.
    	\end{itemize}

