body:
[Theorem kappa-p of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Suppose that the hypotheses (equation VL4 of the paper)--(equation VL5' of the paper) are in force. Suppose moreover that Assumption (ass:Boltz of the paper) is satisfied with $p'\geq 4$ and that
		for every $p=2,\ldots,p'$, $p$ even,
		\begin{equation}

			\bar{b}>\kappa_{p},\quad \mbox{where}\quad \kappa_{p}=2^{{p}-3}(p-1)(2Q_2+2^{p-1}Q_{p}).
		\end{equation}	

		Let $\gamma _{k}=\frac{1}{(1+k)^{\beta }}$  with $
		1\geq\beta >\frac{2}{3 }$.
		Then, for every  
		\begin{equation*}
			\zeta \in \Big(0,1-\frac{Q{ _2  }}{\bar{b}}\Big)\cap \Big(0,\frac{p^{\prime }-2}{
				(d+5/2)(p^{\prime }-2)+2(d+2)}\Big],
		\end{equation*}
		one has 
		\begin{align*}
			\mbox{if $\beta=1$:}&\quad \mathbb{E}[W_{2}^{2}(\rho _{k}(Y),\mu _{\ast
			})]\leq \frac{C}{(\ln k)^\zeta}, \\
			\mbox{if $1>\beta>\frac 2{3}$:} &\quad \mathbb{E}[W_{2}^{2}(\rho
			_{k}(Y),\mu _{\ast })]\leq \frac{C}{k^{(1-\beta)\zeta}}, \end{align*}
		$\mu_*$ denoting the invariant measure associated with the stochastic equation (equation EX1.SDE of the paper).

