body:
[Lemma 33 (rigidity lemma) of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, there exist constants $\Cl,\cl>0$ such that for any distinct $v,v',w\in \widetilde{\mathbb{Z}}^d$ with $|v-w|\ge d$, and any events $\mathsf{A}$ and $\mathsf{A}'$ increasing with respect to $\mathcal{C}_{v}$ and $\mathcal{C}_{v'}$ respectively, 
  	\begin{equation}
  		\begin{split}
  		 	\mathbb{P}\big(\mathsf{A} \mid  \big\{v\xleftrightarrow{} w \Vert \mathsf{A}' \big\}\big) 
  			\le   & \Cref{const_app_switch1} \Big[  \mathbb{P}\big(\mathsf{A}  \mid  v\xleftrightarrow{} w  \big) + \mathrm{exp}\big( -\cref{const_app_switch2}|v -w |^{\frac{d}{2}-1}\big)\Big]. 
  		\end{split}
  	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2609.02175, '2609.02175'] Let $V_j(x)=v_j(|x|)$, $j=1,2$, satisfy the short-range condition
	\eqref{eq:short-range} and assumptions
	\eqref{eq:radial-assumptions-intro}--\eqref{eq:radial-monotonicity-intro}.
	Fix an incoming direction $\omega\in\mathbb S^{n-1}$ and assume that
	\begin{equation}
		\frac{d\sigma_{1,h}}{d\Omega}
		(\omega,\theta;\lambda)
		-
		\frac{d\sigma_{2,h}}{d\Omega}
		(\omega,\theta;\lambda)
		\longrightarrow0,
		\qquad h\longrightarrow0,
	\end{equation}
	for every $\theta\in\mathbb S^{n-1}\setminus\{\omega,-\omega\}$.
	Then
	\begin{equation}
		r_{1,\lambda}=r_{2,\lambda}=:r_\lambda,
	\end{equation}
	and
	\begin{equation}
		V_1(x)=V_2(x),
		\qquad |x|\geq r_\lambda.
	\end{equation}
	In particular, the semiclassical differential cross section at the
	single energy $\lambda$, for one fixed incoming direction, determines
	the potential throughout the classically accessible region. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2609.03755, 'The Scramble Number of Outerplanar Graphs'] Let $W_m$ be the wheel graph on $m+1$ vertices. If $m = k^2+c$ for some $k\in {\mathbb Z}_{>0}$ with $0\leq c \leq 2k$, then
    $$\operatorname{sn}(W_m) = \begin{cases}
        \lfloor\sqrt{m}\rfloor+1 & \text{ if }c=0\\
        \lfloor\sqrt{m}\rfloor+2 & \text{ otherwise }
    \end{cases}.$$

[Theorem Neumann_problem of arXiv:2411.08220, 'Nonlocal operators with Neumann conditions'] Let $\alpha \in (0,1)\cup (1,2)$ and $f\in C_c(\mathbb{R}\setminus\{0\})$. Then, $G|f|<\infty$ on $\mathbb{R}\setminus\{0\}$ and $u = G f$ is the solution of the following Neumann problem for the fractional Laplacian
    \begin{align*}
        \begin{cases}
            (-\Delta)^{\alpha/2} u &= f, \quad \mathrm{in } ~D, \\
            \phantom{\,\,\,\,\,\,\,\,\,} \mathcal{N}_{\alpha/2} u &= f, \quad \mathrm{in } ~\overline{D}^c.
        \end{cases}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 27 of arXiv:2506.15044, '2506.15044'] \normalfont
If there exists a $\mathbb{B}$-process $L\in(\mathcal{M}_{\mathrm{loc}})^{i,\mathbb{B}}$ such that
\begin{equation}
[L,N]=H_{\bullet}[M,N]
\end{equation}
holds for every process $N\in(\mathcal{M}_{\mathrm{loc}})^\mathbb{B}$ (this naturally implies $H\in\mathcal{L}_s^\mathbb{B}([M,N])$), then we say that $H$ is $\mathbb{B}$-integrable w.r.t. $M$. In this case, the $\mathbb{B}$-process $L$, denoted by $H_{\bullet}M$, is called the stochastic integral of $H$ w.r.t. $M$, and the collection of all $\mathbb{B}$-predictable processes which are $\mathbb{B}$-integrable w.r.t. $M$ is denoted by $\mathcal{L}_m^\mathbb{B}(M)$.

[Definition def:weak_sol_MKV of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let \textcolor{black}{$\nu\in \mathcal{P}(\mathbb{R}^d)$}. A (weak) solution to MKV$({\bf b},{\boldsymbol\sigma};\textcolor{black}{\nu})$ 
is a 
(general) solution to MKV$({\bf b},{\boldsymbol\sigma})$ such that
\begin{equation}
[X_0] =  \nu. \vspace{-10pt}
\end{equation}

[Lem 9 of arXiv:2608.11695, 'Generalised stochastic curvature flow in $d \geq 2$, and sharp interface limit for the sto'] Let \(e\in\RR^d\setminus\{0\}\) and \(G(\cdot,e)\in\lL^\infty(\RR)\). Consider
\begin{align*}
-\aA_e\varphi = G(\cdot,e)\quad\text{in }\RR\;,
\quad
\varphi\in\lL^\infty(\RR)\;,
\quad
\varphi(0)=0\;.
\end{align*}
Then there exists a unique solution $\varphi$ if and only if $\bracket{G,Y}=0$. 

Let \(\gamma_\pm(e)\) be as in Lemma~\ref{lem:profile_refined_asymptotics}. Assume in addition that there exist constants \(G(\pm \infty, e)\) and \(\lambda\in 
\left(0, \min\left\{\gamma_+(e),\gamma_-(e)\right\}\right) \) such that
\begin{align}
|G(\pm z,e)-G(\pm \infty, e)|\lesssim e^{-\lambda z}\;,\quad z\ge 0\;.
\end{align}
Then \(\varphi(z,e)\) admits limits \(\varphi(\pm \infty, e)\) as \(z\to\pm\infty\), and we have
\begin{equation*}
|\varphi( \pm z,e)-\varphi(\pm \infty, e)| + |\varphi_{zz}(\pm z,e)| \lesssim e^{-\lambda z}\;, \quad z\ge 0\;.
\end{equation*}

