body:
[Theorem thm-approximation of arXiv:2512.17727, 'Stochastic transport equation with L\'evy noise'] Suppose that  the assumptions of Theorem (reg of the paper)  are satisfied. Assume that $(b^{n})_{n=0}^\infty$ and $(f^{n})_{n=0}^\infty$ are two  $ C_{\mathrm{b}}^{\beta}(\mathbb R^d,\mathbb R^d)$-valued
sequences of vector fields such that
\begin{equation}
b^{n}\to b^0  \mbox{ and } f^{n}\to f^0 \mbox{ in } C_{\mathrm{b}}^{\beta}(\mathbb R^d,\mathbb R^d).
\end{equation}
Let, for all  $n\geq 0$ and $\lambda\geq 1$,   $ u^n_{\lambda}\in C_{\mathrm{b}}^{\alpha+\beta}(\mathbb R^d,\mathbb R^d) $  be  the unique solution to equation (equation eqn-wee of the paper) with the vector field $b$ replaced by the vector field  $b^n$
and $f$ replaced by $f^n$, i.e.,
\begin{align}
\lambda u^n_{\lambda} -  {
\mathscr A} u^n_{\lambda}  - b^n \cdot Du^n_{\lambda} = f^n \;\;  \mbox{ on }\mathbb R^d.
\end{align}
 Then, there exists $\lambda_0\geq1$ and $R>0$  such that
\begin{equation}
\sup_{\lambda\geq \lambda_0}\sup_{n\geq0}\Vert u^n_{\lambda}\Vert_{\alpha+\beta} \leq R \quad \mbox{ and }\quad \sup_{\lambda\geq \lambda_0} \sup_{n\geq0}\Vert Du^n_{\lambda}\Vert_0\leq \frac{1}{3},
\end{equation}
\begin{equation}
 \lim_{n\to \infty}\Vert u^n_{\lambda}-u^0_{\lambda}\Vert_{0}=0,
\end{equation}
and the following results hold: 
for any compact set $K \subset \mathbb R^d$ and $0< \beta' <\beta$,
\begin{equation}
 \lim_{n\to \infty}\Vert u^n_{\lambda}-u^0_{\lambda}\Vert_{\alpha+\beta',K}=0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 (Weighted complex soft-thresholding) of arXiv:2608.21551, '\bf Sparse Separable Factor Analysis in the Complex Domain with an Application to Local Fi'] Let $\Ab=(a_{rc})\in\CC^{p\times k}$ and $\Psib = \diag\left(\psi_{11},\ldots,\psi_{pp} \right)$, where the diagonal entries of $\Psib$ are positive. The optimization problem
\begin{align}

  \min_{\Lambdab\in\CC^{p\times k}}
  \left\{
    \tr\left[
      (\Lambdab-\Ab)^\star
      \Psib^{-1}
      (\Lambdab-\Ab)
    \right]
    +
    \rho\|\Lambdab\|_{1,\CC}
  \right\}
\end{align}
has a unique minimizer $\widehat{\Lambdab}=(\widehat{\lambda}_{rc})$ with entries $\widehat{\lambda}_{rc}
  = \mathcal{T}_{\rho\psi_{rr}/2}(a_{rc})$, where
\begin{align}

  \mathcal{T}_{\tau}(z)
  =
  \begin{cases}
    \displaystyle
    \left(
      1-\frac{\tau}{|z|}
    \right)z,
    & |z|>\tau,\\[2mm]
    0,
    & |z|\leq\tau.
  \end{cases}
\end{align}
The operator $\mathcal{T}_{\tau}$ is the complex soft-thresholding operator. It preserves the phase of each entry that remains nonzero while reducing its modulus by $\tau$.

[Proposition 6 of arXiv:2607.09575, 'Probabilistic estimates for a system of\\noisy integrate-and-fire neurons'] Fix $i \in \{1,\ldots,\,N\}$ and define the stochastic exponential to be
	\begin{equation*}
		\mathcal{E}_t \coloneqq \exp\left\{-\int_0^t \hat{b}_s^i \ind_{\{\Upsilon_s\left(X_s^i\right) < 0\}} \diff{}B_s^i - \frac{1}{2} \int_0^t \left(\hat{b}_s^i\right)^2 \ind_{\{\Upsilon_s\left(X_s^i\right) < 0\}} \diff{}s\right\},
	\end{equation*}
	where $\hat{b}_t^i \ind_{\{\Upsilon_t\left(X_t^i\right) < 0\}}$ is the drift of $\Upsilon_t\left(X_t^i\right)$ defined as in \cref{prop: SCALE TRANSFORM LEMMA }. Then $\int_0^t\hat{b}_s^i \ind_{\{\Upsilon_s\left(X_s^i\right) < 0\}}\diff{s} + {B_t^i}$ is a standard Brownian motion under the probability measure $\mathbbm{Q}$ given by the Radon-Nikodym derivative
	\begin{equation}
		\left.\frac{\diff{}\mathbbm{Q}}{\diff{}\prob}\right|_{\mathcal{F}_t} = \mathcal{E}_t.
	\end{equation}

[Proposition 38 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Under the preceding assumptions, the state projection is Markov for all initial age laws if and only if there exist a measurable function $a:\X\to[0,1)$ and a Markov kernel $K$ on $\X$ such that $K(x,\{x\})=0$ and

\begin{equation*}
q_{u+1}(x,A)=a^u(x)\bigl(1-a(x)\bigr)K(x,A),
\qquad u\in\N,
\quad A\in\calX.
\end{equation*}

In that case

\begin{equation*}
\overline H_{u}(x)=a^u(x)
\end{equation*}

and the projected one-step kernel is

\begin{equation*}
P_1^Z(x,A)=a(x)\one_A(x)+\bigl(1-a(x)\bigr)K(x,A).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2607.13401, 'Total variation cutoff for Kac's walk on the sphere'] Let
\begin{equation*}
        \rho_n:=1-\frac{n+2}{2n(n-1)} .
\end{equation*}
Then
\begin{equation}
        \mb E W_t=\rho_n^t\left(1-\frac1n\right).
\end{equation}
The process \(R_t\) is a martingale, converges in \(L^2\) to a limit
\(R_\infty\), and satisfies
\begin{equation*}
        \mb E[(R_\infty-R_t)^2]\le2\rho_n^t .
\end{equation*}
Moreover, for every sequence \(t_n\) with \(t_n/n\to\infty\), there is a
universal constant \(C<\infty\) such that
\begin{equation}
        \limsup_{n\to\infty}\mb P(R_{t_n}\le r)
        \le C\sqrt r,
        \qquad 0<r\le1 .
\end{equation}

[Proposition prop:general-grav of arXiv:2510.18392, 'Hyperuniformity of random measures, transport and rigidity'] Let $ \mathsf{P} = \sum_{i}\delta _{ x_{ i}}$ a simple stationary point process of $ \mathbb{R}^{ d}$ with unit intensity for which some stationary $   \mathscr  C^{ 1}$ field $ F_{ \mathsf{P}}$ satisfies a.s.  (equation eq:fixed-repr-FP of the paper). Call $ B_{ i}$ the  {\it attraction basin} of $ x_{ i}$, i.e. the set of points attracted to $ x_{ i}$
\begin{align*}
 B_{ i} = \{Y (s),s\geqslant 0:Y\text{\rm{\color{black}  satisfies  (equation eq:coulomb-pde of the paper) and }}\lim_{ t\to \infty }Y(t) = x_{ i}\}.
\end{align*}
 Then a.s. the $ B_{ i}$ all have volume $ 1$ and form an equivariant fair partition. (Proof in the paper; no proof environment follows the statement in the TeX.)

