[Theorem 14 (Theorem 3.6 of \cite{ding2020spikedseparablecovariancematrices}) of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] Suppose that Assumptions \ref{assm_big1'}, \ref{ass:unper}, and \ref{ass:spike} hold, except that the high-moment condition \eqref{eq_highmoment} is replaced by the slightly more general bounded support condition \eqref{eq_support}, with $ n^{-{1}/{2}} \leq q \leq n^{- c_q} $ for some constant $c_q>0$. Then
\begin{equation}
\left|\wt\lambda_{\alpha(i)}-\theta_1(\wt\sigma_i^a)\right| \prec n^{-1/2}\Delta_1(\widetilde{\sigma}_i^a)  + q\Delta_1^2(\widetilde{\sigma}_i^a), \quad 1 \leq i \leq r,
\end{equation}
\begin{equation}
\left|\wt\lambda_{\beta(\mu)}-\theta_2(\wt\sigma_\mu^b)\right| \prec n^{-1/2} \Delta_2(\widetilde{\sigma}_\mu^b) + q\Delta_2^2(\widetilde{\sigma}_\mu^b), \quad 1 \leq \mu \leq s .
\end{equation}
Moreover, for any fixed integer $k>r+s$,
\begin{equation}
\left|\wt\lambda_{k}-\lambda_+\right| \prec n^{-2/3} + q^2.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 50 of arXiv:2601.16377, '2601.16377'] Under the assumptions of Lemma~\ref{Lemma_I_quadratic_Fourier}, for any $\varkappa > 0$ and $M >1$ we have
\begin{equation}

\max_{h\in[H]} \frac{\pi}{2} \cdot [\boldsymbol{\Theta}^{1/2}]_{h,h} \cdot \big|\nu([\hat{a}'_{h},\hat{b}'_{h}])\big| \leq \Bigg(-\bigg(\log M + \max_{h\in[H]} \frac{(\hat b'_h-\hat a'_h)^2}{8}\bigg) \cdot \mathcal{I}^{(2)}[\boldsymbol{\nu}]\Bigg)^{\frac{1}{2}} + \bigg(\frac{\mathcal{J}_{\varkappa}[\boldsymbol{\nu}]}{\varkappa M^{\varkappa}}\bigg)^{\frac{1}{2}},
\end{equation}
where
\begin{equation}

\mathcal J_{\varkappa}[\boldsymbol{\nu}] :=\int_{0}^{+\infty} \frac{\dd s}{s^{1-\varkappa}} \bigg( \sum_{g,h =1}^H
 \theta_{g,h} \widehat \nu_g(s) \widehat \nu_{h}^*(s) \bigg).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma EthV12 of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] [FSmap] 
If $V$ is a local monomial of degree $\le k$, 
then for $\kh \ge \kc_{j+1}$,
\begin{align}

		\norm{\E_{j+1} (\theta V - V ) (b)}_{\kh,  T_j(0)}
		& \lesssim \Big( \frac{\kc_+}{\mathfrak{h}} \Big) \norm{V (b)}_{\kh,  T_j (0)}
		, \\

		\norm{\operatorname{Cov}_{j+1} [ V (b) ; V(b') ] }_{\kh,  T_j(0)}
		& \lesssim  \Big( \frac{\kc_+}{\mathfrak{h}} \Big)^{2} \norm{V (b)}_{\kh,  T_j (0)}^2
\end{align}
with the constants only depending on $k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm moment of arXiv:2503.22334, 'Probabilistic analysis of optimal multi-pivot QuickSort'] Let $K\in {\mathbb N}$. For the number $X_n$ of key comparisons using optimal $K$-pivot QuickSort we have 
  \begin{equation}
    {\mathbb E}\left[X_n\right] = \alpha_K n\ln n + \beta_K n + o(n) \quad (n\to\infty),
  \end{equation}
with a constant $\beta_K \in \mathbb{R}$ and $\alpha_K= \gamma_K/(H_{K+1}-1)$, where $H_n := \sum_{i=1}^n \frac1i$ are the harmonic numbers. In the case of $K≤4$, the error term $o(n)$ can be replaced by $\mathrm{O}(\log n)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma LM21 of arXiv:2412.08886, 'On domination for (non-symmetric) Dirichlet forms'] Let $({\mathscr E},{\mathscr F})$ and $({\mathscr E}',{\mathscr F}')$ be two Dirichlet forms on $L^2(E,m)$,  whose associated semigroups (as described in [MR92]) are denoted by $(T_t)_{t\geq 0}$ and $(T'_t)_{t\geq 0}$,  respectively.  The following assertions are equivalent:
\begin{itemize}
\item[(1)] $T'_t f\leq T_tf$ for all $t\geq 0$ and all non-negative $f\in L^2(E,m)$. 
\item[(2)] ${\mathscr F}'\subset {\mathscr F}$,  $\mathrm{b}{\mathscr F}':={\mathscr F}'\cap L^\infty(E,m)$ is an algebraic ideal in $\mathrm{b}{\mathscr F}$,  and 
\begin{equation}
	{\mathscr E}'(f,g)\geq {\mathscr E}(f,g)
\end{equation}
for all non-negative $f,g\in {\mathscr F}'$.  
\item[(3)] ${\mathscr F}'\subset {\mathscr F}$,  ${\mathscr F}'$ is an order ideal in ${\mathscr F}$,  and (equation eq:21 of the paper) holds for all non-negative $f,g\in {\mathscr F}'$.
\end{itemize}

[Prop x(s) of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] The parabola~$\mathcal{P}$ (see~(equation paraboleP of the paper)) admits the following parameterisation:
\begin{equation}
  \left\{
    \begin{array}{ll}
        x(s) &=   -\frac{1}{2}s(s - 2\mu_2)\\
      y(s) &= - \frac{1}{2}s\left(s + 2\mu_1\right)
    \end{array}
\right. , \quad s \in {\mathbb R}.  
\end{equation}
This means that $\{(x,y) \in {\mathbb R}^2, \ \gamma(x,y) = 0\} = \{(x(s),y(s)), \ s \in {\mathbb R}\}$.

