[Lemma 10 of arXiv:2604.26898, '\bf Stochastic Scaling Limits and Synchronization \\by Noise in Deep Transformer Models'] Under Assumptions \ref{ass:att_reg} and \ref{ass1}, for every $N\in \mathbb{N}$, there exists a constant $\cN > 0$ such that for every $m, L \in \mathbb N$ and $T>0$:
    \begin{equ}
        \E\left[\sup_{0\leq k\leq L} \frac{1}{N}\sum_{i=1}^N |{X}_k^i-\hat{{X}}^i_k|^2\right] \leq \cN \left(\frac{1}{L}+\frac{1}{m}\right) e^{\cN T}.
    \end{equ}
Assuming further that $\act \in C^\infty(\R)$ there exists a $m, L, N$-independent constant $\mathsf c$ such that 
        \begin{equ}
       \E\left[\sup_{0\leq k\leq L} \frac{1}{N}\sum_{i=1}^N |{X}_k^i-\hat{{X}}^i_k|^2\right] \leq \mathsf c \left(\frac{1}{L}+\frac{1}{m^{1/4}}\right) e^{\mathsf c T}.
    \end{equ} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 32 of arXiv:2608.31070, 'Sub-Laplacians on Compact Lie Groups: Heat Kernels, Distance, and Zeta Determinants'] For the pair \eqref{eq:examples-hermitian-pair},
		\begin{equation}
			\mathfrak F_{G,K}(H_M)=\Phi_n(M).
		\end{equation}
		An exact minimizing loop uses only frequencies $|k|\le n$, and, uniformly for $\Phi_n(M)\le R$,
		\begin{equation*}
			d_{\sr}(e,\exp(\varepsilon H_M))^2
			=\varepsilon\Phi_n(M)+O_R(\varepsilon^{3/2}),
		\end{equation*}
		with lower error $O_R(\varepsilon^2)$.

