[Thm thm-I of arXiv:2609.02552, 'Resolvent Estimates for the Stokes Operator \\ in a Three-Dimensional Lipschitz Domain'] Let $\Omega$ be a bounded Lipschitz domain in $\mathbb{R}^d, d\ge 2$.
Let $T$ be a bounded linear operator from $L^2_\sigma(\Omega)$ to $L^2(\Omega; \mathbb{C}^d)$.
Suppose that 
\begin{equation}
\aligned
\| Tu \|_{L^2(\Omega)} &  \le M_2 \| u \|_{L^2(\Omega)}  & \quad & \text{ for } u \in L^2_\sigma(\Omega),\\
\| Tu \|_{L^\infty(\Omega)} & \le M_\infty  \| u \|_{L^\infty(\Omega)}  & \quad & \text{ for   } u \in C^\infty_{0, \sigma}(\Omega).
\endaligned
\end{equation}
Then $T$ is bounded from $L^p_\sigma(\Omega)$ to $L^p(\Omega; \mathbb{R}^d)$ for  any $2< p\le  \infty$, and 
\begin{equation}
\| Tu \|_{L^p(\Omega)} \le C_p M_2^\theta M_\infty^{1-\theta}  \| u \|_{L^p(\Omega)}
\end{equation}
for any $u\in L^p_\sigma (\Omega)$, 
where $\theta=\frac{2}{p}$ and $C_p$ depends only on $p$ and $\Omega$.

[Lemma 15 of arXiv:2608.26816, '\textbf{On the existence of maximal foliations in general relativity}'] For  any $W^{2,2}$-tensor field $F$ on $M_{t}$, we have      \begin{equation}
    \|F\|_{L^{\infty}(M_{t})}\leqslant C\|\Delta F\|^{\frac{1}{2}}_{L^{2}(M_{t})} \|\nabla F\|^{\frac{1}{2}}_{L^{2}(M_{t})},
    \end{equation}
    where  $C=C(\alpha_0, \alpha_1)$.

