[Theo 28 of arXiv:2609.01932, 'Essential dimension and faithful rank of finite $p$-gerbes'] Let $\cA/k$ be a finite gerbe whose geometric inertia groups have order
invertible in $k$, let $\fC\simeq(\mu_p)^c$ be a split central subband,
and assume $\operatorname{char}(k)\ne p$.  Then
\begin{equation}
\ed_k(\cA;p)\ge
\min_{\mathcal B\text{ basis of }\fC^*}
\sum_{\chi\in\mathcal B}d_\chi(\cA).
\end{equation}
No $p$-group hypothesis is imposed on the full inertia.

[Lemma 23 of arXiv:2512.04807, 'Existence and uniqueness of the canonical Brownian motion in non-simple conformal loop ens'] Let $F_1,F_2$ be two sets such that $F_1 \cap F_2$ is a non-empty finite set. For $i=1,2$, let $(\CE_i,\CF_i)$ be a resistance form on $F_i$, and let $(\CE,\CF)$ be the resistance form on $F_1 \cup F_2$ defined by
 \begin{align*}\begin{split}
  \CF &= \{ f : f|_{F_1} \in \CF_1,\, f|_{F_2} \in \CF_2 \} ,\\
  \CE(f,f) &= \CE_1(f|_{F_1},f|_{F_1})+\CE_2(f|_{F_2},f|_{F_2}) .
 \end{split}\end{align*}
 Then the following holds. Let $A \subseteq F_1 \cup F_2$ be a finite set containing $F_1 \cap F_2$, let $A_i = A \cap F_i$ for $i=1,2$, and let $w_A, w_{A,i}$ be the weight functions associated with $\CE|_A, \CE_i|_{A_i}$, respectively.
 Then
 \[
  w_A(x,y) =
  \begin{cases}
   w_{A,1}(x,y)+w_{A,2}(x,y) ,& x,y \in F_1 \cap F_2 ,\\
   w_{A,1}(x,y) ,& x,y \in F_1 ,\, \{x,y\} \nsubseteq F_1 \cap F_2 ,\\
   w_{A,2}(x,y) ,& x,y \in F_2 ,\, \{x,y\} \nsubseteq F_1 \cap F_2 ,\\
   0 ,& \text{otherwise.}
  \end{cases}
 \]

[Definition 30 of arXiv:2605.02430, '\textbf{Scaling limit of the range of tree-valued branching random walks in random environ'] \textbf{(Brownian snakes)} 
A $q$-dimensional Brownian snake is a r.v. $(H, W)\! :\!  \Omega\!  \rightarrow \! \fSigma_q(\bbR_+)$ that is measurable with respect to $\mathscr F$ and to the Borel $\sigma$-field of $\fSigma_q(\bbR_+)$, such that for all $p\ino \bbN^*$, and all real numbers 
$0\leqo s_1\leko \ldots \leko s_p$, 
\begin{equation}

\big(W_0,W_{\! s_1}, \ldots , W_{\! s_p} \big) \; \overset{\textrm{(law)}}{=} \;  F_p \big( H ; (B^{(j)}) _{0\leq j\leq p}  ;  (s_j)_{1\leq j\leq p} \big)\; , 
\end{equation}
where $B^{(0)}\eqo W_0$, where $(B^{(j)})_{1\leq j\leq p}$ are independent standard $q$-dimensional Brownian motions that are moreover independent from $W_0$ and $H$. \cq

