body:
[Thm HessenbergP of arXiv:2504.14036, 'Darwinian evolution in Malthusian population growth model and Markov chains'] Let $n > 3$ be a natural number and let the transition matrix $P$ be a Hessenberg matrix with $p_{i+1,i} = \delta\varepsilon$ for $i=1,\ldots,n-2$ and $p_{i,i+1} = (1-\delta)\varepsilon$ for $i=2,\ldots,n-1$, i.e.,
\begin{gather}
P(\delta) = \left(\begin{array}{ccccccc}
1-\varepsilon & \varepsilon & 0 & \ldots & \ldots & \ldots & 0\\
\delta\varepsilon & 1-\varepsilon & (1-\delta)\varepsilon & 0 &  &  & \vdots\\
0 & \delta\varepsilon & 1-\varepsilon & (1-\delta)\varepsilon & 0 &  & \vdots \\
\vdots & \ddots & \ddots & \ddots & \ddots & \ddots & \vdots\\
\vdots &  & 0 & \delta\varepsilon & 1-\varepsilon & (1-\delta)\varepsilon & 0\\
\vdots & & & 0 & \delta\varepsilon & 1-\varepsilon & (1-\delta)\varepsilon\\
0 & \ldots & \ldots & \ldots & 0 & \varepsilon & 1-\varepsilon
\end{array}\right).

\end{gather}

\noindent 
Then 
\begin{gather}
E_{\pi^*}(\delta) = \frac{\delta^{n-2} (2\delta - 1)}{2\delta^{n-1} - 2(1-\delta)^{n-1}} + \frac{\delta^{n-1}(2\delta - 1)}{2(1-\delta)^2 (\delta^{n-1} - (1-\delta)^{n-1})} \cdot \sum_{k=2}^{n-1} k\left(\frac{1-\delta}{\delta}\right)^k + n\frac{(1-\delta)^{n-2} (2\delta - 1)}{2\delta^{n-1} - 2(1-\delta)^{n-1}}

\end{gather}

\noindent
and, consequently, we have
\begin{gather}
\lim_{\delta \rightarrow 0^+}\ E_{\pi^*}(\delta) = \frac{2n-1}{2}.

\end{gather}

