[Definition 4 of arXiv:2609.03647, 'Extension Problems for the Vladimirov--Taibleson Operator and the Hierarchical Laplacian'] Let $\alpha>0$. The Vladimirov--Taibleson operator $D^\alpha$ is the nonnegative self-adjoint operator on $L^2(\mathbb{Q}_p^n)$ defined by
    \begin{align*}
        \widehat{D^\alpha f}(\boldsymbol{\xi})
        =\|\boldsymbol{\xi}\|_p^{\alpha}\hat{f}(\boldsymbol{\xi}),
    \end{align*}
    with operator domain
    \begin{align*}
        \mathcal{D}(D^\alpha)
        =\left\{f\in L^2(\mathbb{Q}_p^n)\ \middle|\
        \|\boldsymbol{\xi}\|_p^\alpha\hat f(\boldsymbol{\xi})
        \in L^2(\mathbb{Q}_p^n)\right\}.
    \end{align*}

[Lemma 10 (Theorem 2.2 of \cite{AHP2024}) of arXiv:2604.22159, 'Adapted optimal transport between filtered Gaussian processes'] Let $\bG^{a, L}, \bG^{b, M} \in \cFG$ and $\pi \in \Cpl_{\mathrm{bc}}(\bG^{a, L}, \bG^{b, M})$. The following are equivalent:
\begin{enumerate}
\item[(i)] $\pi \in \cP(\bR^{Nd} \times \bR^{Nd}) \cong  \cP(\bR^{2Nd})$ is jointly Gaussian. (Here and below, we identify $(x, y) \in \bR^{Nd} \times \R^{Nd}$ with the column vector $\begin{bmatrix} x^{\intercal} & y^{\intercal} \end{bmatrix}^{\intercal} \in \bR^{2Nd}$.)
\item[(ii)] There exists a block diagonal matrix $P =\textup{diag}(P_1,\dots,P_N)$, where each diagonal block $P_t \in \bR^{d \times d}$ satisfies $\|P_t\|_{2\rightarrow 2}\le 1$ (that is, each $P_t$ is a contraction and hence is a correlation matrix), such that
\begin{equation} 
\pi = \pi^P := \cN_{2Nd} \left( \begin{bmatrix} 0 \\ 0 \end{bmatrix}, \begin{bmatrix} I & P \\ P^{\intercal} & I \end{bmatrix} \right).
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 5 Hodge n point formula of arXiv:2609.02409, 'Membranes and Maps'] Suppose that $\sum_{i=1}^5 \epsilon_i = 0$. (conj:GW:vertex of the paper) holds if and only if, for all $n\in\{1,\ldots,5\}$, we have
    \begin{equation}

        \mathsf{H}(\epsilon_1^{-1},\ldots, \epsilon_n^{-1} ; \epsilon_1,\ldots, \epsilon_5 ; u)
        =
        \mathsf{V}(\epsilon_1,\ldots,\epsilon_n;u)
        \prod_{j=1}^n \frac{1}{u^2}
        \prod_{i\neq j} \frac{\gamfct{-\epsilon_j^{-1}\epsilon_i}{u\epsilon_j}}{\epsilon_i} \,,
    \end{equation}
    where
    \begin{equation}

        \mathsf{V}(\epsilon_1,\ldots,\epsilon_n;u)
        \coloneqq
        \begin{cases}
            1
            & n=1 \,, \\[0.75em]
            \dfrac{\varsigma(u \epsilon_3)\varsigma(u \epsilon_4)\varsigma(u \epsilon_5)}{\varsigma(u (\epsilon_1+\epsilon_2))}
            & n=2 \,, \\[0.95em]
            \varsigma(u \epsilon_4)^2 \varsigma(u \epsilon_5)^2
            & n=3 \,, \\[0.75em]
            \Big(\prod_{i=1}^5 \varsigma(u\epsilon_i) \Big) \, \varsigma(u\epsilon_5)^2 \sum_{i=1}^4 \kappa(u\epsilon_i)
            & n=4 \,, \\[0.75em]
            \Big(\prod_{i=1}^5 \varsigma(u \epsilon_i) \Big)^2 \Big(\big(\sum_{i=1}^5 \kappa(u \epsilon_i)\big)^2 -\frac{1}{4} \Big)
            & n=5 \,,
        \end{cases}
    \end{equation}
    and $\varsigma(x) = 2 \sinh \tfrac{x}{2}$, $\kappa(x) = \frac{d}{dx} \log{\varsigma(x)} = \tfrac{1}{2} \coth \tfrac{x}{2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

