body:
[Thm 5 of arXiv:2607.27932, '2607.27932'] Let $\underline{H}_0$ be the minimum of 
\begin{equation}
	H_0:\lambda\in \mathbb R^d\rightarrow H_0(\lambda)=\inf_{-\infty<T_1\leq T_2<\infty}\inf_{\phi}\left\{I(T_1,T_2,\phi)\,:\,\phi\in \mathcal A^{(\lambda_1,\lambda_2),(\lambda,\lambda)}([T_1,T_2])\right\}\,,	
\end{equation}
where $I$ is the action functional:
\begin{align}
	I(T_1,T_2,\phi)=\frac 1{4}\int_{T_1}^{T_2}\left(\Big\|\dot{\phi}^1_t+\W_{\lambda_1}(\phi^1_t)\Big\|^2_{A^{-1}(\phi^1_t)}+\Big\|\dot{\phi}^2_t+\W_{\lambda_2}(\phi^2_t)\Big\|^2_{A^{-1}(\phi^2_t)}\right)
	\,\ddt,	
\end{align}
and $\mathcal A^{(\lambda_1,\lambda_2),(\lambda,\lambda)}([T_1,T_2])$ is the set of all $\mathbb R^{2d}$-valued $\mathcal C^1$-paths $\phi=\{(\phi^1_t,\phi^2_t)\}_{t\in[0,T]}$ starting at $(\lambda_1,\lambda_2)$ at time $T_1$ and ending at the common point $(\lambda,\lambda)$ at time $T_2$.

\medskip 
\noindent
Then, for any $\delta>0$, 
\begin{equation*}
\lim_{\varepsilon\to0}\lim_{\sigma\to0}\PP
\left(\exp\left[\frac{2}{\sigma^2}\left(\underline{H}_0-\delta\right)\right]
<{C}_\varepsilon(\sigma)
<\exp\left[\frac{2}{\sigma^2}\left(\underline{H}_0+\delta\right)\right]\right)=1.
\end{equation*}
Moreover, $L_\varepsilon(\sigma)=(X_{C_{\varepsilon}(\sigma)},Y_{C_\varepsilon(\sigma)})$ persists asymptotically in the vicinity of the minimizers set of $H_0$:
\begin{equation}
\mathcal M_0=\argmin H_0:=\{\lambda_0\in\mathbb R^d\,:\,H_0(\lambda_0)=\underline H_0\},
\end{equation}
with, for any $\delta>0$,  
\begin{align*}
&\lim_{\varepsilon\to0}\lim_{\sigma\to0}\PP\left(\dist\bigg( L_{{C}_\varepsilon(\sigma)},\mathcal M_0\times\mathcal M_0\bigg)\leq\delta\right)\\
&=\lim_{\varepsilon\to0}\lim_{\sigma\to0}\PP\left(\max\bigg(\dist( X_{{C}_\varepsilon(\sigma)},\mathcal M_0),\dist(
	Y_{{C}_\varepsilon(\sigma)},\mathcal M_0)\bigg)\leq\delta\right)=1.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:rainbow of arXiv:2507.16188, 'The noisy voter model with general initial conditions'] Let $G = \mathbb{Z}_n$. There exists $c>0$ such that, for every $q\geq 3$, every $\theta\in(0,1]$ and every initial state $\mathsf{x}_0$,
\begin{equation}
\mathcal{A}^{(2)}_t(\mathsf{x}_0) \geq 

\frac{c_0}{q^2}\, \mathcal{A}^{(2)}_t(\mathsf{x}_\mathrm{rbw})\,.
\end{equation}
Consequently, $T_{\mathsf{x}_0} \geq T_{\mathsf{x}_\mathrm{rbw}}+O(1)$, and thus $\mathsf{x}_\mathrm{rbw}$ is the asymptotically fastest initial condition. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:path-coupling of arXiv:2601.07045, 'From Continuous to Discrete: \\ a No-U-Turn Sampler for Permutations'] Let $G=(\mathcal{X},E)$ be a finite, connected, undirected graph whose edges
$\{u,v\}\in E$ are assigned lengths $l(u,v)\ge 1$, and let $d$ denote the
resulting shortest-path metric on $\mathcal{X}$. Let $K$ be a Markov kernel on
$\mathcal{X}$ with stationary distribution $\pi$. Suppose that for every edge
$\{u,v\}\in E$ there exists a coupling $(U,V)$ of $K(u,\cdot)$ and $K(v,\cdot)$
such that
\begin{equation}
\EE_{u,v}\!\left[d(U,V)\right]
\;\le\;
d(u,v)\,e^{-\alpha},
\qquad \text{for some }\alpha>0.
\end{equation}
Then, for all $t\ge 0$,
\[
\max_{x\in\mathcal{X}}
\bigl\|K^t(x,\cdot)-\pi\bigr\|_{\TV}
\;\le\;
e^{-\alpha t}\,\diam(\mathcal{X},d),
\]
where $\diam(\mathcal{X},d):=\max_{x,y\in\mathcal{X}} d(x,y)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 10 of arXiv:2608.21255, 'Laws of the iterated logarithm for random Dirichlet series with general weights'] Assume that $\eta$ has a standard normal distribution. Then
\begin{equation}
\liminf_{n\to\infty}\frac{\log|\hat{Z}_n|}{\log n}=-1~~\text{{\rm a.s}}.
\end{equation}

