[Lemma lemZhaoBound of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] For $0 \le \eta< \eta_\ell $, 
   \begin{equation}
       \lim_{c \to \infty} \frac{\Phi_{n,c/\sqrt{n}}(\eta)}{c n^{3/2}} < -\frac{1}{2} h \left ( \eta^{1/3} \right)  \,, 
   \end{equation}
   where $\eta_\ell \approx .0091$ is given explicitly in~[zhao2017lower] as the maximum of a single variable function on the unit interval. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2604.04823, '2604.04823'] For any~$a\geq1$, there exists~$\hat\epsilon (a) >0$ such that for any~$\epsilon$ and~$h$ with~$\epsilon < \hat\epsilon$ and~$h \leq \epsilon^2$, the following holds.
    For any~$x\in \Omega_h$ such that $\dist(x,\partial\Omega) = \delta h$ for some~$\delta \in (0,1]$, $\xi(x)$ is well-defined as in Lemma~\ref{l:facts-on-boundaries} and
    \begin{equation}
        \E\brak{D \one_E} = -h^2 \delta L + \frac{1}{2}h^2 Q + O(h^2\abs{D\hat U(x)}) + O(h^{2.75}) \,,
    \end{equation}
    where
        \begin{align}
            L &= n(\xi(x))^T H(\xi(x)) n(\xi(x)) \E\brak{\zeta_n \one_E}\,,\\
            Q &= n^T \hat H(x) n \E\brak*{\zeta_n^2 \one_E} + \sum_i t_i^T \hat H(x) t_i \E\brak*{\zeta_{t,i}^2 \one_E}\,.
        \end{align}
    Here, $H=D^2U$ and $\hat H = D^2 \hat U$ respectively, and~$\zeta_n = \zeta \cdot n(\xi(x))$ and~$\zeta_{t,i} = \zeta \cdot t_i(\xi(x))$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Tightness of arXiv:2607.08187, 'Asymptotic behaviours of critical branching random walk in $\mathbb{R}^d$'] For any $A>0$, it holds that 
	\begin{equation}
		\begin{aligned}
			& \sup_{x>1} \sup_{\mathbf{y}\in \overline{D}_1} \frac{1}{x^2}\mathbb{P}_{x\mathbf{y}}\left(\|\mathbf{S}_{\tau_{x}}\|>x+A\right)
			\le 4C_\tau \mathbb{P}( \|\mathbf{X}\|>A ). 
		\end{aligned}
	\end{equation}

[Theorem 4 of arXiv:2608.12070, 'Central limit theorems for a heavy-tailed subcritical Galton-Watson process with state-dep'] Suppose   the process $\mathbf{X}=\{X_n:n\geq0\}$  is defined by \eqref{111} and satisfies {\bf (A)}. Then as $n\to \infty$,  
\begin{align*}
\frac{S_n-  n\beta\pi_0/(1-m)}{a_n}\stackrel{d}{\rightarrow} \pi_0^{-1/\kappa}\zeta_\kappa,
\end{align*}
where  $\{a_n\}$  and $\zeta_\kappa$ are the same as in Theorem \ref{th1}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:asymptotic-dynamical-selection of arXiv:2608.21561, '\textbf{Loss-Parameterized Fisher Width Along Learning Trajectories}'] Let $\theta(t)$ be any population gradient-flow trajectory. Then
\begin{equation}
    \alpha(t)\longrightarrow\infty,
    \qquad
    \beta(t)\longrightarrow0.

\end{equation}
Consequently,
\begin{equation}
    \frac{\alpha(t)}{\|\theta(t)\|_2}
    \longrightarrow1.

\end{equation}
More precisely,
\begin{equation}
    \frac{\alpha(t)^3}{t}
    \longrightarrow
    \frac{\pi^2}{2\sqrt{2\pi}}.

\end{equation}
If $\beta(0)\neq0$, then
\begin{equation}
    \frac{\log|\beta(t)|}{\alpha(t)^2}
    \longrightarrow
    -\frac{3}{\pi^2}.

\end{equation}
In particular,
\[
    \alpha(t)\asymp t^{1/3},
\]
while $|\beta(t)|$ decays on a stretched-exponential $t^{2/3}$
scale when $\beta(0)\neq0$.

