[Coro 6 of arXiv:2510.21595, 'One-arm exponents of high-dimensional percolation revisited'] Let $d>6$ and $L\geq L_0$. There exist $c,C>0$ such that, for every $p\leq p_c$, and every $n\geq 0$, 
\begin{align}
	 p \psi_p(\Lambda_n) & \leq   \varphi_p(\Lambda_n)  \leq C \exp\left( - c (p_c-p)^{1/2} n\right), \\
	 p \psi_p(\H_n) & \leq   \varphi_p(\H_n)  \leq C \exp\left( - c (p_c-p)^{1/2} n\right)\,
\end{align}
and
\begin{equation}
	c\leq \psi_{p_c}(\mathbb H_n)\leq C.
\end{equation}

[Theorem growth of ES_n^2 of arXiv:2505.05921, 'Limit Theorems for step reinforced random walks\\ with regularly varying memory'] {}
    Let $\{S_n\}_{n\geq 0}$ be the SRRW-RVM with $\mathbb E(\xi_1^2)=1$. Then:
    \begin{enumerate}
        \item For unbounded $\{v_n\}$, we have 
        \begin{equation}             \mathbb{E}S_n^2 \sim \begin{cases}
                \frac{(2\gamma+1-p)}{(1-p)(2(1-p)(\gamma+1)-1)}n, &\text{if } p\in[0,p_c),\\
                (2\gamma+1)^2\sigma_n^2, & \text{if } p=p_c.
            \end{cases}
        \end{equation}
        \item For bounded $\{v_n\}$, $\left\{a_n\mu_nS_n\right\}_{n\geq 1}$ is $L^2$-bounded.
    \end{enumerate}

