[Lemma eq:v-decay of arXiv:2604.20094, 'Persistence and local extinction for superprocesses in random environments'] Let $\rho, T>0$ and $p\in {\mathbb N}$.
  If $0\leqslant f\leqslant N \phi_{\rho}$  for some constant $N>0$, then there is a constant $C=C(d, p, \rho, T, N, \|{\mathcal C}\|_\infty)$ such that
  	\begin{equation}
  		{\mathbf E}  \left[ \left( \sup_{x\in {\mathbb R}^d}  |v(t,x)  \phi^{-1}_{\rho/2}(x)|\right)^{2p} \right] \leqslant C(d, p,\rho,T, N, \|{\mathcal C}\|_\infty)<\infty,  \quad  \forall  t\in [0, T].
  	\end{equation}

[Lemma le:psi-asymp of arXiv:2411.16913, 'Entropies of the Poisson distribution as functions of intensity: ``normal'' and ``anomalou'] For any $\alpha>0$,
\begin{equation*}
    \psi(\alpha,\lambda)\sim \frac{1}{ \sqrt{\alpha}}(2\pi\lambda)^{\frac{1-\alpha}{2}}, \qquad\lambda\to\infty.
\end{equation*}

[Lem 30 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Let $\alpha\in \R $. For any $v\in L^2([0,\infty),\dot{H}^\alpha)$ we have
  \begin{align*}
      \sup_{0\leq t\leq T} \Vert \nabla Z_t(v)\Vert_{H^{\alpha+1}}^2\leq \int_0^T\Vert v_s \Vert_{H^\alpha}^2\ ds.
  \end{align*}

