body:
[Definition 12 of arXiv:2606.14443, 'SEMICLASSICAL LIMIT OF POLYAKOV-LIOUVILLE MEASURE and Q-Curvature Uniformization ON EVEN-D'] For $0<\gamma<\sqrt{2n}$ and the Gaussian field $h$, the Liouville Quantum measure $\mu^{\gamma h}$ is a measurable map
	\begin{equation*}
		\mu^{\gamma\bullet} \colon H^{-\varepsilon} \to \mathcal{M}_{b}(M), \qquad f \mapsto \mu^{\gamma f}\comma
	\end{equation*}
	satisfying

	\begin{enumerate}[$(i)$]
		\item
		for $\P$-a.e.~$h$ and every $\varphi \in \mathring H^{n/2}$,
		\begin{equation}
			\mu^{\gamma(h+ \varphi)} = e^{\gamma\varphi}\, \mu^{\gamma h} \fstop
		\end{equation}

		\item
		for all Borel measurable $f \colon H^{-\varepsilon} \times M \to [0,\infty]$, we have that
		\begin{equation}
			\E \int f(h, x) d\mu^{\gamma h}(x) = \E \int f\tparen{h + \gamma k(x,\emparg), x} \, d\vol(x) \fstop
		\end{equation}
	\end{enumerate}

