[Lemma 1 of arXiv:2609.01770, 'Support of Dyson Brownian Motion'] Let $m(z)=m_\mu(z)$ be the Stieltjes transform of a finite measure $\mu$ with $A=\mu(\bR)$. For any integer $p\geq 1$, we denote its $p$-th derivative by $m^{(p)}(z)$. Then, 
\begin{align}
|m(z)|\leq \frac{A}{\dist(z,\supp(\mu))},\quad
\quad |m'(z)|\leq \frac{\Im[m(z)]}{\Im[z]}, 
\quad |m^{(p)}(z)|\leq \frac{p!A}{\dist(z,\supp(\mu))^{p+1}}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 14 (Transformation of conditional laws under rerooting) of arXiv:2510.22533, 'Marginal dynamics of probabilistic cellular automata on trees'] Suppose Condition \ref{cond:UGW} holds.
Let $k \in \N_0$ and let $h \colon (\PolishX^{k+1})^2 \times \SQ(\PolishX^{k+1}) \to \Rmb$ be bounded and measurable.
Define $\Xi_k \colon (\{0,1\} \times \PolishX^{k+1})^2 \rightarrow \Rmb$ by 
\begin{equation*}
\Xi_k(X_{\myroot}[k], X_1[k]) := 1_{\{N_{\myroot}(\tree)\ne\emptyset\}} \frac{\Emb\left[\frac{|N_{\myroot}(\tree)|}{|N_1(\tree)|} h(X_{\myroot}[k],X_1[k],\lan X_{N_{\myroot}(\tree)}[k]\ran) \,\big|\, X_{\myroot}[k],X_1[k]\right]}{\Emb\left[\frac{|N_{\myroot}(\tree)|}{|N_1(\tree)|} \,\big|\, X_{\myroot}[k],X_1[k]\right]}.
\end{equation*}
Then, for each $v \in \N$, 
\begin{equation} 
\Xi_k(X_v[k], X_{\myroot}[k]) = \Emb\left[ h(X_v[k],X_{\myroot}[k],\lan X_{N_v(\tree)}[k]\ran) \,|\, X_{\myroot}[k],X_v[k] \right], \mbox{ on } \{v \in \tree\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:BKKprob of arXiv:2411.11345, 'Real Gaussian exponential sums via a real moment map'] For all $U\subset \mathbb{C}^n$, we have 
  \begin{equation}
    \mathbb{E}\mathbb{S}\left\{\mathcal{E}^\mathbb{C};U\right\}=\frac{n!}{\pi^n}\int_U \det\left(\partial_z\bar{\partial}_z\Phi^\mathbb{C}\right)\, \mathrm{d} z.
  \end{equation}
  In particular, if $A\subset \mathbb{Z}^n$, then for all $V\subset\mathbb{R}^n$, we have 
  \begin{equation}
    \mathbb{E}\mathbb{S}\left\{\mathcal{E}^\mathbb{C};V\times i (-\pi,\pi)\right\}=n!\vol_n\left(\mu^\mathbb{C}(V)\right).
  \end{equation}
  Which gives in the case $V=\mathbb{R}^n$: 
  \begin{equation}
    \mathbb{E}\mathbb{S}\left\{\mathcal{E}^\mathbb{C};\mathbb{R}^n\times i (-\pi,\pi)\right\}=n!\vol_n(P).
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition Prop:PropertiesGamma of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] Fix $\alpha \in (0,1)$ and let the effective branching rate $R\in C^{0,\alpha}_p(\mathbb{R}^d)$ defined in (equation eq:Intro:EffectiveBranching of the paper) be such that $R \ge 0$ and $R\not\equiv 0$. Then $\gamma(\zeta)=\gamma(\zeta;b,\sigma,R)$ satisfies the following properties.
    \begin{enumerate}[(i)]
        \item The function $\gamma$ belongs to $C^2(\mathbb{R}^d)$, is strictly convex, and for $\zeta\in \mathbb{R}^d$,
        \begin{equation}
             \gamma(\zeta) \in \left[\Big(\min_{x\in \mathbb{R}^d}R(x)\Big) + \frac{\theta^{-1} |\zeta|^2}{2} - |\zeta| \| b\|_\infty ,  \Big(\max_{x\in \mathbb{R}^d}R(x)\Big) + \frac{\theta |\zeta|^2}{2} + |\zeta| \| b\|_\infty  \right],
        \end{equation}
        where we recall that $\theta$ is a positive constant such that $0<\theta^{-1} \mathrm{Id}<\sigma \sigma^T<\theta \mathrm{Id}$ (see \textbf{(AssumptionA:SigmaEllipticity of the paper)}).
        \item Let $\nu(\cdot;0):\mathbb{T}^d\to \mathbb{R}$ be the density on the torus of the invariant measure of a periodic diffusion with generator $\mathcal{L}^0$ as defined in (equation eq:Intro:GeneratorExponential of the paper). Recall that $\nu(R;0)$ denotes the integral $\int_{\mathbb{T}^d}R(x)\nu(x;0)dx$. We have that $\gamma(0)\geq \nu(R;0)>0$, and for $e\in S^{d-1}$,
        \begin{equation}
            \begin{split}
                &\lim_{\lambda \rightarrow 0^+ }\frac{\gamma(\lambda e)}{\lambda}=\lim_{\lambda \rightarrow + \infty }\frac{\gamma(\lambda e)}{\lambda}=+\infty, \ \mathrm{ and } \ \lim_{\lambda \rightarrow 0^- }\frac{\gamma(\lambda e)}{\lambda}= \lim_{\lambda \rightarrow - \infty }\frac{\gamma(\lambda e)}{\lambda}=-\infty.
            \end{split}
        \end{equation}
        \item For all $e\in S^{d-1}$, there exists a unique $\lambda_e\in (0,\infty)$ such that 
        \begin{equation*}
            \inf_{\lambda>0} \frac{\gamma(\lambda e)}{\lambda}=\frac{\gamma(\lambda_e e)}{\lambda_e}.
        \end{equation*}
        \item At every $\zeta\in \mathbb{R}^d$, the Hessian $\nabla^2 \gamma (\zeta)$ is invertible.
    \end{enumerate}

[Proposition 54 of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] Under the event where the bounds in Propositions \ref{prop:pbar_square_root_G} and \ref{prop:u_ratio_concentration_G} hold true, we have
    \begin{align}
        F_1(i)\lesssim \begin{cases}
        \frac{1}{\sqrt{i}}+\frac{\log n}{\sqrt{n}}\quad &\mbox{if $n_0\le i\le n/2$}\\
        \frac{\log n}{\sqrt{n-i}}\quad &\mbox{if $i>n/2$}
            \end{cases},\qquad 
        F_2(i)\lesssim \begin{cases}
       \sqrt{\frac{n}{i}}\log T \quad &\mbox{if $n_0\le i\le n/2$}\\
        \sqrt{\frac{n}{i}}\quad &\mbox{if $i>n/2$}
        \end{cases}.
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 (Krylov type estimate) of arXiv:2604.12317, 'Weak solution for distribution dependent SDEs driven by L\'{e}vy noise'] Suppose that \( \alpha \in(1,2]\), \( p>\frac{d}{\alpha-1} \) and \( q>\frac{p \alpha}{p(\alpha-1)-d} \). Then, for any \( T_{0}>0 \), there exist a constant \( C= \) \( C\left(T_{0}, d, \alpha, p, q\right)>0 \) such that for any \( \left(\mathcal{F}_{t}\right) \)-stopping time \( \tau \), and \( 0 \leq S \leq T \leq T_{0} \), and all \( f \in L^{q}([S, T] ; L^{p}(\mathbb{R}^{d})) \),
\begin{equation}
	\mathbb{E}\left(\int_{S \wedge \tau}^{T \wedge \tau} f_{S}\left(X_{S}\right) \mathrm{d} s \bigg| \mathcal{F}_{S}\right) \leq C\left[1+\mathbb{E}\left(\int_{S \wedge \tau}^{T \wedge \tau}\left|\xi_{s}\right| \mathrm{d} s \bigg| \mathcal{F}_{S}\right)\right]\|f\|_{L^{q}([S, T] ; L^{p}(\mathbb{R}^{d}))} .
\end{equation}

