body:
[Prop 6 of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Given $\eps>0$, let $(Q_t,P_t)$ be the solution to~\eqref{eq:abc-slow},\eqref{eq:intro-InfMass} with corresponding initial data $(Q^i_0,P^i_0)$ for $i=1,2$. Recall the definition of the potential $V$ from~\eqref{eq:Valpha} for some parameter value $\alpha\geq 0$. Furthermore, let $T\geq 1$ be fixed. 
    \begin{enumerate}[label=(\roman*)]
        \item
       We have for any$ t\geq 0$
       \begin{align}
           \E\Bigl[\bigl|Q_t^{1}-Q^{1}_0\bigr|^2\Bigr]
            \leq \begin{dcases}  \eps^2 C_1 t^2 \Bigl( t^2+|P_0^{1}|^2\Bigr) \ \  &\text{if $\alpha=0$}, \\

             \eps C_2 \Bigl( t+ \eps t^4 |Q^1_0| +  |P^1_0|^2  \Bigr) &\text{if $\alpha>0$},
            \end{dcases}
        \end{align}
     where the constants $C_1,C_2>0$, are independent of $\eps$ and $t$.   
        \item Let $(q_t,p_t)\in \R^{2(d-k)}$ with initial data $(q_0,p_0)=(Q_0^2,P_0^2)$ evolve according to~\eqref{eq:limit-gen} with $\hat q=Q^1_0 \in \R^k$. 
         Then
        \begin{align} &\E\biggl[\sup_{t\in [0,T]}\biggl|\begin{pmatrix}q_t - Q^{2}_t \\ p_t - P^{2}_t\end{pmatrix}\biggr|^2\biggr] \leq \begin{dcases}
         \eps^2 C_4 T^4    e^{C_5 T}\Bigl(T^2+|P_0^{1}|^2  \Bigr) & \text{if } \alpha=0\\
            \eps C_6  T  \left(T+ \eps T^4 |Q^1_0|^2 +  |P^1_0|^2 \right) & \text{if } \alpha>0
            \end{dcases}
        \end{align}
        where the constants  $C_4, C_5, C_6>0$ are independent of $\eps$ and $T$. 
        \item  Let $p^1_t\in\R^k$ with initial condition $p^1_0=P^1_0$ evolve according to~\eqref{eq:InfMass-p1}. We have  for any $t\geq 1$
        \begin{align}
        \E\biggl[\bigl|p^{1}_t - P_t^{1}\bigr|^2\biggr] \leq  \begin{dcases}
\eps C_7  t^2 \left( e^{C_8 t} \left(t^2+\eps t^2 |P^1_0|^2  \right) + |P^1_0|^2 \ \right) & \text{ if } \alpha=0 \\
C_9 \left( (t^2 + \eps^2  t^7)  |Q_0^1|^2 + \eps^2 t^4  |P^1_0|^2 +   \eps t^4\right) &\text{ if } \alpha>0,
        \end{dcases}
        \end{align}
        where $C_7,C_8,C_9>0$ are independent of $\eps$ and $t$.
    \end{enumerate}

