body:
[Theorem 20 (Finite length of the classwise and all-lattice coefficient modules) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] For every $\Lambda\in\mathfrak{L}_{\bm{\beta},\bm{w}}^{\mathrm{adm}}$, the module $M_{\Lambda,\bm{w}}^{\mathrm{dir}}$ has finite length.
Moreover, the all-lattice module $M_{\bm{\beta},\bm{w}}^{\mathrm{dir,all}}$ has finite length, and
\begin{equation}

\length_{S}M_{\bm{\beta},\bm{w}}^{\mathrm{dir,all}}=\sum_{\Lambda\in\mathfrak{L}_{\bm{\beta},\bm{w}}^{\mathrm{adm}}}\length_{S}M_{\Lambda,\bm{w}}^{\mathrm{dir}}.
\end{equation}

[Def property-a of arXiv:2411.18155, 'Besov regularity of random wavelet series'] Let $d\in\mathds{N}$, $s\in\mathds{R}$, $p,q\in (0,\infty]$, $\alpha,\beta,\gamma,\theta\in\mathds{R}$, $\mu,\nu\in (-\infty,0]$, and $r\in (0,\infty)$.
We say that \emph{Property A is satisfied} if
 \begin{equation*}
\gamma <-\frac{d}{p},\qquad \beta<-\frac{d}{p},\qquad s+\frac{d}{2}+\alpha<0
\end{equation*}
or 
 \begin{equation*}
\gamma <-\frac{d}{p},\qquad \beta<-\frac{d}{p},\qquad s+\frac{d}{2}+\alpha=0,\qquad \theta  <-\frac{1}{q}.
\end{equation*}
When $p=\infty$, the conditions  $\gamma <-\frac{d}{p}$, $\beta<-\frac{d}{p}$ have to be replaced by  $\gamma\leq 0$, $\beta\leq 0$.
When $q=\infty$, the condition $\theta  <-\frac{1}{q}$ has to be replaced by $\theta\leq 0$.

We say that \emph{Property A' is satisfied} if one of the following sets of conditions is satisfied
\begin{enumerate}[label={(\alph*)},leftmargin=*,align=left,noitemsep]
\item{$p\neq\infty$, $q\neq \infty$, $\gamma +\frac{d+\nu}{p}<0$, $\beta +\frac{d+\nu}{p}< 0$, $s+\frac{d}{2}+\alpha+\frac{\mu}{p}< 0$;}
\item{$p\neq\infty$, $q= \infty$, $\gamma +\frac{d+\nu}{p}<0$, $\beta +\frac{d+\nu}{p}< 0$, $s+\frac{d}{2}+\alpha+\frac{\mu}{p}\leq 0$;}
\item{$p=\infty$, $q\neq \infty$, $\gamma\leq 0$, $\beta\leq 0$, $s+\frac{d}{2}+\alpha< 0$;}
\item{$p=\infty$, $q= \infty$, $\gamma\leq 0$, $\beta\leq 0$, $s+\frac{d}{2}+\alpha\leq 0$.}
\end{enumerate}
We say that \emph{Property A'' is satisfied} if one of the following sets of conditions is satisfied
\begin{enumerate}[label={(\alph*)},leftmargin=*,align=left,noitemsep]
\item{$p\neq\infty$, $\gamma +\frac{d}{p} +\frac{\nu }{\max\left\{r,p\right\}}< 0$, $\beta  +\frac{d}{p}+\frac{\nu}{\max\left\{r,p\right\}}< 0$, $s+\frac{d}{2}+\alpha+\frac{\mu}{\max\left\{r,p\right\}}< 0$;}
\item{$p=\infty$, $\gamma\leq 0$, $\beta\leq 0$, $s+\frac{d}{2}+\alpha\leq 0$.}
\end{enumerate}

[Lemma 31 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $Y : [0,T] \to W$ be measurable and bounded. We define the path $Z : [0,T] \to W$ as
\begin{align*}
Z_t := \int_0^t Y_s \, ds, \quad t \in [0,T].
\end{align*}
Then we have
\begin{align*}
|Z_{s,t}| \leq \| Y \|_{\infty} |t-s| \quad \text{for all $s,t \in [0,T]$.}
\end{align*}

