body:
[Theorem of arXiv:2606.01683, 'Singular-value gap of nonreversible Markov processes'] Assume $\gamma > 0$.
    For $n \geq 1$, we have the following upper and lower bounds on $\Delta_n$:
    \begin{align*}
        &\text{(i)}  \qquad  \Delta_n \leq \frac{2}{\sqrt{\gamma n}}\\
        &\text{(ii)} \max_{n \leq k \leq 2n} \Delta_k \geq \frac{1}{2\gamma n +3}.
    \end{align*}

[Theorem 5 of arXiv:2609.03647, 'Extension Problems for the Vladimirov--Taibleson Operator and the Hierarchical Laplacian'] The functions
    \begin{align*}
        \Psi_{\gamma,\boldsymbol{a},\boldsymbol{j}}(\boldsymbol{x})
        =p^{\frac{n(\gamma-1)}{2}}
        \chi_p\!\left(p^{-\gamma}\boldsymbol{j}\cdot
        (\boldsymbol{x}-\boldsymbol{a})\right)
        \boldsymbol{1}_{\boldsymbol{a}
        +p^{\gamma-1}\mathbb{Z}_p^n}(\boldsymbol{x}),
    \end{align*}
    where $\gamma\in\mathbb{Z}$, $\boldsymbol{a}$ ranges over a fixed set of representatives of $\mathbb{Q}_p^n/p^{\gamma-1}\mathbb{Z}_p^n$, and $\boldsymbol{j}\in\mathbb{F}_p^n\setminus\{\boldsymbol{0}\}$, form a complete orthonormal basis of $L^2(\mathbb{Q}_p^n)$ and satisfy
    \begin{align*}
        D^\alpha\Psi_{\gamma,\boldsymbol{a},\boldsymbol{j}}
        =p^{\gamma\alpha}
        \Psi_{\gamma,\boldsymbol{a},\boldsymbol{j}}.
    \end{align*}
    Consequently,
    \begin{align*}
        \operatorname{Spec}(D^\alpha)
        =\{0\}\cup\{p^{\gamma\alpha}\mid\gamma\in\mathbb{Z}\}.
    \end{align*}
    Every positive eigenvalue has infinite multiplicity. The point $0$ belongs to the spectrum as an accumulation point, but it is not an $L^2$-eigenvalue.

[Prop prop-fixation of arXiv:2504.04943, 'Emergence of \bl microbial \bl host dormancy \\ \bl during \bl a persistent virus epidemic'] Assume $r\kappa\mu_1 \neq v \sigma$.
\begin{enumerate}
\item  Assume that~(equation viruscoexcondq=0 of the paper) holds. Then the equilibrium $(n_{1a}^*,n_{1i}^*,0,0,0,n_3^*)$ of~(equation 6dimvirus of the paper) is 
\begin{itemize}
    \item {\em  unstable} under the condition
    \[ 
\lambda_1-\lambda_2 < \frac{qDn_3^* (v\sigma-r\kappa\mu_1)}{(r+v)(\kappa\mu_1+\sigma)}, 
\qquad \mbox{$(\rm{Inv}_{2 \rightarrow 1,3})$\color{black}}
\addtocounter{equation}{1}\tag{\thesection.\arabic{equation}} 
\] 
\item {\em asymptotically stable} under the condition
\[ 
\lambda_1-\lambda_2 > \frac{qDn_3^* (v\sigma-r\kappa\mu_1)}{(r+v)(\kappa\mu_1+\sigma)}, \qquad \mbox{$(\rm{Inv}_{2 \nrightarrow 1,3})$\color{black}}
\addtocounter{equation}{1}\tag{\thesection.\arabic{equation}} 
\] 
if additionally $(n_{1a}^*,n_{1i}^*,n_3^*)$ is an asymptotically stable equilibrium of~(equation 3dimvirus of the paper).\\
\end{itemize}

\item  Assume that~(equation viruscoexcond2 of the paper) holds. Then, the equilibrium $(0,0,\widetilde n_{2a}, \widetilde n_{2d}, \widetilde n_{2i}, \widetilde n_3)$  of~(equation 6dimvirus of the paper) is 
\begin{itemize}
    \item {\em unstable} under the condition
     \[ 
    \lambda_1-\lambda_2 > \frac{qD \widetilde n_3 (v\sigma-r\kappa\mu_1)}{(r+v)(\kappa\mu_1+\sigma)}, \addtocounter{equation}{1}\tag{\thesection.\arabic{equation}}  \qquad \mbox{$(\rm{Inv}_{1 \rightarrow 2,3})$\color{black}}
    \] 
    \item {\em asymptotically stable} under the condition
     \[ 
    \lambda_1-\lambda_2 < \frac{qD \widetilde n_3 (v\sigma-r\kappa\mu_1)}{(r+v)(\kappa\mu_1+\sigma)}, \qquad \mbox{$(\rm{Inv}_{1 \nrightarrow 2,3})$\color{black}}\addtocounter{equation}{1}\tag{\thesection.\arabic{equation}} 
    \] 
    if additionally $(\widetilde n_{2a},\widetilde n_{2d}, \widetilde n_{2i}, \widetilde n_3)$ is an asymptotically stable equilibrium of~(equation 4dimvirus of the paper).
\end{itemize}

\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 68 of arXiv:2609.02850, 'Canonical-row Chern flow on Bott--Samelson towers:\\ realizable-volume models for Schubert'] For every $0\le k\le r_w$,
\begin{equation}
 \Nrm(A_{w,k})
 =\left.\partial_z^{L-k}\Nrm(F_w)\right|_{z=0}
 \in\RV.
\end{equation}
Equivalently,
$(-1)^k\Nrm(G_w^{(\length(w)+k)})$ is a realizable-volume polynomial.

