body:
[Definition 2 (Height function) of arXiv:2605.28473, 'The BKT transition and surface tension differentiability'] Consider a finite simple graph $G=(V,E)$ with edge weights
    $J=(J_{uv})_{uv\in E}\subset[0,\infty)$.
    Let $\emptyset\neq\partial G\subset V$ be a distinguished subset of vertices,
    called the \emph{boundary}, and let $\zeta\in\Z^{\partial G}$ be a
    \emph{boundary height function}.
    The \emph{height function} on $G$ with coupling constants $J$ and boundary conditions
    $\zeta$ is the Gibbs measure $\mu_{G,J}^\zeta$ on $\Z^V$ defined by the formula
    \begin{multline}

        \mu_{G,J}^\zeta[\{h\}] := \frac1{Z_{G,J}^\zeta}
        \true{h|_{\partial G}=\zeta} \prod_{uv\in E} w_{J_{uv}}(h_u-h_v);
        \\
        w_{J_{uv}}(k) := \sum_{i,j\in\Z_{\geq 0},\,i-j=k} \frac{(J_{uv}/2)^i}{i!}
        \frac{(J_{uv}/2)^j}{j!}.
    \end{multline}
    Here $Z_{G,J}^\zeta$ is the \emph{partition function}.
    We write $\mu_{G,\beta}^\zeta$ when $J\equiv\beta\in[0,\infty)$ is constant.

[Lemma 22 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exists a constant $C_{13}>0$, which depends on $\delta$, $T^*$ and $\|v_0\|_{H^1(\Omega)}$, such that the following uniform boundedness holds 
for all $\nu \in (0,1)$:

\begin{align*}
&\sup_{\varepsilon \in (0,1)} \left\{ \int_0^{T^*} \|v_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}'(t)\|_{L^2 (\Omega)}^2dt
+\sup_{0 \le t \le T^*} \Phi_\nu (v_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}(t)) \right.\\
&\hspace*{4cm}\left.+\nu^2 \int_0^{T^*} \|v_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}(t)\|_{H^2(\Omega)}^2dt \right\} \le C_{13}.
\end{align*}

In particular, the following uniform boundedness holds:

\begin{equation*}
\sup_{\varepsilon \in (0,1),\,\nu \in (0,1)} \left\{ \int_0^{T^*} \|v_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}'(t)\|_{L^2 (\Omega)}^2dt+
\frac{1}{2} \left( \max_{0 \le t \le T^*} \|v_{\text{{\tiny $\delta,\!\varepsilon,\!\nu$}}}(t)\|_{L^2(\Omega)}\right)^2 \right\} \le C_{13}.
\end{equation*}

