[Corollary 10 of arXiv:2604.19738, 'Phase Transitions in the Fluctuations of Functionals of Random Neural Networks \\'] Let $F_L[q]$ be the $q$th chaotic component of $F_L$ (cf.~\eqref{deco Y}). Under the same assumptions of \Cref{cor:boun-hatK-iper}, we have the following asymptotics for fixed $q\in \N$, $q\geq 2$.

\smallskip
\noindent
If $q<d/(2\nu)$, setting $\gimel_q = \beth_q \omega_d^2 q! \varphi_q^2$, as $L\rightarrow\infty$ we have
	\begin{equation*}
		\Var(F_L[q])= v_L^{q} \Big( \gimel_q +o(1) \Big)\,\,\,.
	\end{equation*}

\smallskip
\noindent
If $q\ge d/(2\nu)$, $\varphi_q\neq 0$ and $q$ is even whenever $\kappa$ is odd, we have
\begin{align*}
		\Var(F_L[q])\,\asymp \,
		\begin{cases}
			v_L^q \log(v_L^{-1})\, &\textnormal{if } q=d/(2\nu) \\
			v_L^{d/(2\nu)}\,\, &\textnormal{if }q>d/(2\nu)
		\end{cases}
		\qquad\,.
	\end{align*}

[Lemma 57 (Step A in theorem~\ref{SWLOG}) of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] This lemma proceeds from the assumptions in theorem~\ref{Smainresult}. Define
\begin{equation} 
   {G^1}' := \Big\{t \in \mathbb{R} \ \big| \ h_1(t) \geq h_1(-t) \Big\}\\
\end{equation}
where, as usual, $h_1(t) = P\{(t,X_2,...,X_n) \in V\}, \ \forall t \in \mathbb{R}$. Define
\begin{equation} 
\phi_1(t) := 
\begin{cases} 
|t| & \text{if }|t| \in {G^1}' \\ 
-|t| & \text{otherwise} 
\end{cases} 
\end{equation} 
Then 
$$
P(X \in V) \leq P\big((\phi \circ X_1,X_2,...,X_n) \in V \big)
$$
\begin{proof} 
Notice, $\forall t \in \mathbb{R}$, $t$ or $-t \in {G^1}'$. Thus
\begin{equation}
({G^1}')_{|\cdot|} = [0,\infty).
\end{equation} 
${G^1}'$ is measurable because ${G^1}' = H_1^{-1}([0,\infty))$, where $H^1(t) = h_1(t) - h_1(-t), \ \forall t \in \mathbb{R}$, which is measurable. 

It is elementary to show $\phi_1$ is Borel measurable. Indeed, $\forall U \subset \mathbb{R}$ measurable, one may verify
\begin{align*} 
\phi_1^{-1}(U) =& \Big[\big( U_{\geq 0} \cap {G^1}'\big) \cup \Big(\big\{-x \ \big| \ x \in U \cap (-\infty,0)   \big\} \backslash {G^1}'\Big) \Big] \\
               &\cup \Big[\big(U_{\geq 0} \cap {G^1}'\big) \cup \Big(\big\{-x \ \big| \ x \in U \cap (-\infty,0) \big\}\backslash {G^1}'\Big) \Big]_{-}
\end{align*}
which is a finite combination of unions, intersections, compliments, and reflections of measurable sets (sections~\ref{abbreviationschapter4} notations)). By theorem~\ref{Fubini'stheorem} applied to the indicator function of $V$, integrating $P(X \in V)$ over the $1$st component, 
$$
P(X \in V) = \int_{\mathbb{R}} h_1 {dX_1}_\#(m) 
$$
where $X_1\#(m)$ is the pushforward \eqref{pushforwarddef} of the Lebesgue measure on $(0,1)$. Similarly, 
$$
P\big((\phi_1 \circ X_1,X_2,...,X_n) \in V \big) = \int_\mathbb{R} h_1 \ d(\phi_1 \circ X_1)_\#(m).
$$
By change of variables for Lebesgue integration, 
\begin{align*} 
&P(X \in V) = \int_{(0,1)} h_1 \circ X_1 \ dm\\
P\big((\phi_1 \circ X_1,&X_2,...,X_n) \in V \big) = \int_{(0,1)} h_1 \circ \phi_1 \circ X_1 \ dm.
\end{align*} 
By definition of $\phi_1$ and ${G^1}'$ \eqref{G1'def}, notice $\forall t \in \mathbb{R}$, $\phi_1$ sends $t$ to $t$ or $-t$, depending which makes $h_1$ larger (with the nuance if $h_1(t) = h_1(-t)$, then $\phi$ sends 
$t$ to $|t|$). That is, $\forall t \in \mathbb{R}, h_1(t) \leq h_1(\phi_1(t))$. Since $X_1:(0,1) \rightarrow \mathbb{R}$ it follows $\forall s \in (0,1), \ h_1(X_1(s)) \leq h_1 \circ \phi(X_1(s))$. The lemma follows 
by monotonicity of Lebesgue integration.  
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Phi-returnshift of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Fix $i\in \{1,2\}$ and $0<\delta <\eta <1$. There
exist integers $q_{1}<q_{2}<\cdots $, a shift $m=q_{1}$, an FS-set 
\begin{equation}
I=\mathrm{FS}(q_{1},q_{2},\dots ),\qquad I^{\prime }=\mathrm{FS}
(q_{2},q_{3},\dots ),  
\end{equation}
and a continuous function $G_{i}\in C([\delta ,\eta ])$ such that: 
\begin{equation}
\sup_{x\in \lbrack \delta ,\eta ]}|\Phi _{n}^{i}(x)-G_{i}(x)|\rightarrow
0\qquad \text{as }n\rightarrow \infty ,\ n\in I,  
\end{equation}
and 
\begin{equation}
\sup_{x\in \lbrack \delta ,\eta ]}|\Phi _{n+m}^{i}(x)-G_{i}(x)|\rightarrow
0\qquad \text{as }n\rightarrow \infty ,\ n\in I^{\prime }.  
\end{equation}
Moreover, for every $n\in I^{\prime }$, we have $(n,n+m)\in I\times I$.

