[Lem 52 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $A,K,D$ satisfy \eqref{eq:costanti}. Also let $k \ge 1$ be an integer and $q \in [2^k N^{K \delta-1}, \varepsilon_0]$ be a real number. Further let $q' \ge 0$ satisfy
		\begin{flalign}

			\begin{aligned} 
				& q' \in [q - 2^k N^{(D+1)\delta-1}, q - 2^k N^{(D-1)\delta - 1}]; \qquad 	\mathsf{t}:=q^{-1} k 2^{k+3} N^{1+11K\delta}.
			\end{aligned} 
		\end{flalign}

		\noindent  Consider the Glauber dynamics $(H_t)_{t \ge 0}$ starting from an initial condition $\mu \in \mathcal P^+$ (recall Definition \ref{def:P+}) and assume that, w.o.p. under $\mu$, 
		\begin{flalign}

			\begin{aligned}
				H_0 (w) \le \mathcal{H}_{q} (w) + N^{\delta-1}, \qquad  \text{for each $w \in \mathfrak{X}$}.
			\end{aligned} 
		\end{flalign}

		\noindent Then,  w.o.p., we have
		\begin{flalign}

			H_t (z) \le \mathcal{H}_{q'} (z), \qquad \text{for each $z \in \bigcup_{j=1}^{k+1} \mathcal{A}_j^{q'} (N^{A\delta})$ and $t \in [ \mathsf{t}, N^5]$.}
		\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop ravenel-4.4 of arXiv:2608.26876, 'Local Bousfield classes via homological support'] Let $X$ be a $p$-local bounded below spectrum such that
	\begin{enumerate}
		\item $\pi_iX$ is finitely generated over $\bbZ_{(p)}$ for each $i$, and 
		\item the homological dimension of $BP_*(X)$ as a $BP_*$-module is finite.
	\end{enumerate}
	Then $X \otimes BP \in \Coloco{BP}$.

[Thm 1 (Scaling limit for the length of the longest increasing subsequence of the Brownian separable permutons) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] For all $p\in(0,1)$, let $\sigma_n=\Perm[\bm{\mu}_p,n]$ be a random permutation of size $n$ sampled from the Brownian separable permuton $\bm{\mu}_p$ of parameter $p$, as introduced in \eqref{eq:finite_perm_brownian}. Recall that the permutations $\sigma_n$ are naturally coupled for different values of $n$. We have the almost sure convergence
    \begin{equation}
        \frac{\lis(\sigma_n)}{n^{\alpha}} \xlongrightarrow[n\rightarrow \infty]{a.s.} X,
    \end{equation}  
    where $\alpha=\alpha(p)$ is the unique solution in the interval $(1/2,1)$ to the equation	
        \begin{equation}
            \frac{1}{4^{\frac{1}{2\alpha}}\sqrt{\pi}}\,\frac{\Gamma\big(\tfrac{1}{2}-\tfrac{1}{2\alpha}\big)}{\Gamma\big(1-\tfrac{1}{2\alpha}\big)}=\frac{p}{p-1},
        \end{equation}
    and the limiting random variable $X=X(p)$ is non-deterministic and almost surely positive and finite.
    Moreover, $X$ is a deterministic measurable function of the Brownian separable permuton $\bm{\mu}_p$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 5 of arXiv:2609.02040, '\Large Quantum Landau Damping with Coulomb Repulsion in the Whole Space'] We consider the linearized Hartree equation~\eqref{eq:Hartree_linear} around the homogeneous state $\opmu=\mu_P(\opp)$. Then if $\rho_\h$ is the associated spatial density, its spatial Fourier transform satisfies
		\begin{equation}
			\widehat\rho_\h(t,k) = \widehat{\rho_\h^\circ}(t,k)- 2\pi\CK \int_0^t e^{-\n{k}(t-s)} \, \frac{\sin\!\lt(2\pi\Omega_k\lt(t-s\rt)\rt)}{\Omega_k} \, \widehat{\rho_\h^\circ}(s,k) \d s \, ,
		\end{equation}
		where
		\begin{equation*}
			\Omega_k=\sqrt{\CK+\tfrac{h^2\n{k}^4}{4}}
		\end{equation*}
		and
		\begin{equation*}
			\rho_\h^\circ(t,x) =\intd \Wigner{\op^\init}(x-tv,v) \d v
		\end{equation*}
		is the free-transport density. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop basis of arXiv:2609.00672, 'Deciding superellipticity and computing the Weierstrass normal form'] The differential $\omega_{a,b}$ is holomorphic on $C$ if and only if $(a,b)\in A$, where

\begin{equation}
A=\Bigl\{(a,b): a\ge 0,\ 0\le b<n,\ a+\sum_{j}\Bigl\lfloor\frac{b\,l_j}{n}\Bigr\rfloor\le\frac{bm}{n}-1-\frac{1}{e_\infty}\Bigr\}.
\end{equation}

The set $\{\omega_{a,b}\}_{(a,b)\in A}$ is a basis of $H^0(C,\Omega^1)$, and

\begin{equation}
\ord_P(\omega_{a,b})=na+n-1-\bigl(b\,l_i \bmod n\bigr),
\end{equation}

where $b\,l_i\bmod n$ denotes the least non-negative residue.

