body:
[Lemma 3 of arXiv:2608.13358, 'Extreme points of sets of probability measures and $\phi$-divergences'] Let $p,p',q\in\cP$ with $p\ll q$ and $p'\ll q$, and let $\varphi\colon[0,\infty)\to\R$ be a convex function satisfying
    \begin{equation}
        \varphi(1)=0,\quad \Div{\varphi}{p}{q}<\infty,\quad\text{and}\quad \Div{\varphi}{p'}{q}<\infty.
    \end{equation}
    Then, the following statements hold.
    \begin{enumerate}
        \item The functions $\varphi\big(\frac{\d p}{\d q}\big)$ and $\varphi\big(\frac{\d p'}{\d q}\big)$ are $q$-integrable on every $A\in\cF$.
        \item Define
        \begin{equation} 
        g:=\begin{cases}
        \varphi'_+\big(\tfrac{\d p}{\d q}\big)\big(\tfrac{\d p'}{\d q}-\tfrac{\d p}{\d q}\big) & \text{if } \tfrac{\d p'}{\d q}\geq \tfrac{\d p}{\d q},\\[0.5em]
        \varphi'_-\big(\tfrac{\d p}{\d q}\big)\big(\tfrac{\d p'}{\d q}-\tfrac{\d p}{\d q}\big) & \text{otherwise,}
        \end{cases}
        \end{equation}
        with the convention $(-\infty)\cdot 0:=0$.\ Then, $g$ is $q$-a.s.\ well-defined with values in $[-\infty,\infty)$ and, for every $A\in\cF$,
        \begin{equation}
        \lim_{\lambda\uparrow 1}\int_A  \frac{\varphi\big(\lambda \frac{\d p}{\d q} + ( 1- \lambda) \frac{\d p'}{\d q}\big)-\varphi\big(\frac{\d p}{\d q}\big)}{1-\lambda}\,\d q=\int_A g\,\d q\in[-\infty,\infty).
        \end{equation}
        In particular, choosing $A=\Omega$,
        \[
       \lim_{\lambda\uparrow 1}\frac{\Div{\varphi}{\lambda p+(1-\lambda)p'}{q}-\Div{\varphi}{p}{q}}{1-\lambda}=\int_\Omega g\,\d q.
        \]
    \end{enumerate}

[Proposition prop:generator of arXiv:2606.04859, 'Stein's method for the Wishart distribution'] For any $f\in C^2(\mathcal{S}_{++}^d)$, the extended generator of $(\mathfrak{W}_t)_{t\geq 0}$ is given by
\begin{equation}
\mathcal{A}^{\mathcal{W}}f(S) = 2 \, \mathrm{tr}\{(\alpha \Sigma - S) \nabla f(S)\} + 4 \, \mathrm{tr}\{S \nabla \Sigma \nabla f(S)\}, \qquad S\in \mathcal{S}_{++}^d,
\end{equation}
where $\nabla \vcentcolon= (\frac{1}{2} (1 + \delta_{ij}) \partial / \partial S_{ij})_{1\leq i,j \leq d}$ denotes the $d\times d$ symmetric gradient, and $\delta_{ij}$ denotes the Kronecker delta. (Proof in the paper; no proof environment follows the statement in the TeX.)

