[Lemma 8 of arXiv:2608.30155, 'Gradient Estimates Near the Natural Exponent for Very Weak Solutions to $A_p$-Weighted Qua'] Assume \eqref{struc} and \eqref{unidegen}. If  $\omega \in A_{p}$ for some $p>1$, then there exists a small constant   $\delta_{1}=\delta_{1}(n,p,	\nu, L, \Lambda, [\omega]_{A_{p}})$ such that the following holds: For any $\delta \in (0,
		\delta_{1}]$, if $w \in	W^{1,p-\delta}_{\omega}( B_{\rho})$ is a very weak solution to \eqref{apreq} with $w_{0}
		\in W^{1,p-\delta}_{\omega}( B_{\rho})$ and $ \mathbf{f} \in
		L^{p-\delta}_{\omega}( B_{\rho})$, then there holds
		\begin{equation}
			\int_{B_{\rho}} |Dw|^{p-\delta} \omega \, dx   \leq c \left[  \int_{B_{\rho}} |Dw_{0}|^{p-\delta} \omega  \, dx +\int_{B_{\rho}} |\mathbf{f}|^{p-\delta} \omega  \, dx \right] ,
		\end{equation}
		where $c>0$ depends on  $ n,p, \nu,L, \Lambda$ and $[\omega]_{A_{p}}$.

[Cor 46 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] Let $v_{0} \in L^{1}(\R^{d}) \cap L^{\infty}(\R^{d})$ with $v_{0} \geq 0$. Let $v$ be the unique nonnegative entropy solution to \eqref{e.pmev} and let $v_{N}$ be generated by $\mathcal{S}_{N}$ with initial condition $v_{0}$. Then
	\begin{equation*}
		v_{N} \xrightarrow{L^{1}_{\text{loc}}(Q_{T})} v \text{ and }v_{N}(\cdot,t) \xrightarrow{L^{1}_{\text{loc}}(\R^{d})} v(\cdot,t)\text{ for all }t \in [0,T].
	\end{equation*}

