[Lemma lemma3 of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] Let $p \geq 1$ and $(\mathcal{F}_p,\Gamma_p,\Psi)$ be a $p$-energy structure.
    Let $\tau \geq 1$, $x,y \in X$ and $r,s > 0$ such that
    $B(x,r) \cap B(y,s) \neq \emptyset$ and $\tau^{-1}s \leq r \leq \tau s$.
    There are constants $C = C,\sigma \geq 1$ depending only on $\tau$, $p$, the constants in (eq:PI of the paper), the constants associated to $\Psi$ in (equation eq:Psi of the paper), the constants in (equation eq:muDoubling of the paper) and (equation eq:RadDiam of the paper) such that for all $f \in \mathcal{F}_p$,
    \begin{equation}
        \abs{f_{B(x,r)} - f_{B(y,s)}} \leq C \left(\frac{\Psi(x,r)}{\mu(B(x,r))}
        \int_{B(x,\sigma r)} \, d\Gamma_p\Span{f} \right)^{\frac{1}{p}}.
    \end{equation}

[Lem 17 of arXiv:2609.00743, '$L_p$ Brunn-Minkowski inequality for the eigenvalue of generalized Monge-Ampère equation'] For $\Omega_0,\Omega_1\in \mathcal{U}_s$ and $\alpha\in[0,1]$, we have
    \begin{equation*}
    \lambda(\Omega_\alpha)\le (1-\alpha)\lambda(\Omega_0)+\alpha\lambda(\Omega_1).
    \end{equation*}

[Theorem 39 of arXiv:2606.17501, 'Critical spectral behavior and large deviations for geometric $\alpha$-stable processes'] For any $x \in \mathbb{R}^{d}$ and $\theta \in \mathbb{R}$,
  the logarithmic moment generating function $\Lambda(\theta)$ exists
  and coincides with the spectral function $C(\theta)$:
  \begin{align*}
    \Lambda(\theta) = C(\theta).
  \end{align*}

[Lemma lem:Buse_from_geod of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Let $\gamma$ be any semi-infinite geodesic rooted at $\gamma(0) = (m,n) \in \mathbb{Z}^2_{\mathrm{HS}}$ and such  that $\gamma(-k)\cdot \mathbf e_1 \to -\infty$ as $k \to \infty$. Then, for every $\mathbf x \le \mathbf \gamma(0)$ in $\mathbb{Z}^2_{\mathrm{HS}}$, the limit
	\begin{equation} 
	b(\mathbf x) := \lim_{k \to \infty} G(\gamma(-k),\mathbf x) - G(\gamma(-k),\gamma(0))
	\end{equation}
	exists. Furthermore, for any $j \in \mathbb{Z}_{\le n}$,
	\begin{equation} 
	\begin{aligned}
		&b(\gamma(0)) = 0  = \max_{i \in \llbracket j,m \rrbracket} [b(i,j-1) + G\bigl((i,j),(m,n)\bigr)],  \quad\text{and}\\
		&i_j^\star := \max\{i \in \mathbb{Z}: \gamma(-k) = (i,j-1) \text{ for some } k \in \mathbb{N} \} \in \argmax_{i \in \llbracket j,m \rrbracket}[b(i,j-1) + G\bigl((i,j),(m,n)\bigr)].
	\end{aligned}
	\end{equation}

