body:
[Definition of arXiv:2507.09421, 'Stability of randomly switching stochastic reaction networks with asymptotically linear tr'] Let $X$ be a CTMC on $\mathbb S\subseteq \mathbb Z^d$. We say that $X$ \emph{converges exponentially fast} if
 \begin{enumerate}
     \item $X$ restricted to any closed communicating class is exponentially ergodic;
     \item there exists $\gamma\in\mathbb R_{>0}$ such that for every $x\in S$ we have $\mathbb E_x[e^{\gamma \tau}]<\infty$, where $\tau=\inf\{t\in\mathbb R_{>0}\,:\,X(t)$ is in a closed communicating class$\}$.
 \end{enumerate}

[Prop prop1 of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Let $(\Omega,\mathcal{F},P,T)$  be a measure preserving system. Then the following three statements are equivalent:
	\begin{longlist}
		\item $P$ is weakly mixing;
		\medskip
		\item for any $r>0$, $\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P^{r}(B\cap T^{-i}C)=P^{r}(B)P^{r}(C)$ for any $B,C\in\mathcal{F}$;
		\medskip
		\item    for any $B,C\in\mathcal{F}$, $
		\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P(B\cap T^{-i}C)=P(B)P(C),$	 and there exists $r=r_{B,C}\in(0,1/2]$ such that $\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P^{r}(B\cap T^{-i}C)=P^{r}(B)P^{r}(C)$.
	\end{longlist}
	In particular, $P$ is weakly mixing  if and only if $P$ is ergodic and $\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P^{1/2}(B\cap T^{-i}C)=P^{1/2}(B)P^{1/2}(C)$ for any $B,C\in\mathcal{F}$.

[Proposition 6 (Comparison with the centered fan) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] For the exponentially localized choice \eqref{eq:w0-tails},
\begin{equation}
 \sup_{x_1\in\R}
 \abs{(\Nr,\Vr)(t,x_1)-(N^c,V^c)(x_1/t)}
 \le C\frac{\Delta w}{1+t\Delta w}
 \log(2+t\Delta w),\qquad t>0. 
\end{equation}
In particular, the smooth reference converges uniformly to the centered
Euler rarefaction as $t\to\infty$.

[Lemma 36 of arXiv:2511.20322, 'Dissertation'] Let $b, \si \in G_1([0,\infty)\times \R^d) \cap G^\infty([0,\infty)\times \R^d)$, such that $b$ is $\R^d$-valued and $\si$ is $\R^{d\times d}$-valued.
	Let $h\in (0,1), s\geq 0$ and consider the \tSDE{}
	\[dX_t^h = b_t(X_t^h)\,dt + \sqrt{h}\si_t(X_t^h)\,dW_t, \quad X_s = x,\]
	with $t\in [s, s+h]$. Then there exists a function $C\in G(\R^d)$, such that
	\begin{align}
		\E[\Delt X_s^h] = h b_s + h^2 C, && \E[(\Delt X_s^h)^{\otimes 2}] = h^2 C,
	\end{align}
	for all $h\in (0,1)$, where $\Delt X_s^h := X_{s+h}^h - X_s^h$.

[Proposition 31 of arXiv:2608.09700, 'A general paracontrolled ansatz for singular SPDEs'] For any tree $\tau\in T\sqcup T^+$ and $|n|>|\tau|$, we have 
	\begin{align*}
		\sum_{\substack{k\geq 0 \\ k=k_1+k_2}} \sum_{\substack{q\geq 0 \\ \sigma_q\prec\dots\prec\sigma_1\prec \tau }} \frac{1}{k_2!} \binom{n}{k_1}  \partial^{n-k_1}_*\P_{k_2}\left(  Z_{\downarrow^k\tau/\sigma_1},\dots, Z_{\sigma_q}   \right) = \partial^n_y\Big(\Pi_x^\mcZ(\Psi(\tau))(y)\Big)_{|y=x}
	\end{align*}

