body:
[Theorem 12 (Local well-posedness in the weakened setting) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Suppose that Assumption~\ref{assumption_weakened_setting} holds. Then for all $u_0\in L^0_{\F_0}(\Omega;H^1(\sO))$, there exists a (unique) maximal solution $(u,\sigma)$ to \eqref{eq:AVP} such that a.s.\ $u\in C([0,\sigma);H^1(\sO))\cap L^2_{\loc}([0,\sigma);\nH^3(\sO))$. Moreover, the following blow-up criterion holds
\begin{equation}

    \P \bigg(\sigma < \infty ,\sup\limits_{t\in [0,\sigma)} \| u(t) \|_{H^1(\sO)} + \int_0^\sigma \|u(t) \|^2_{H^3(\sO)} \dt<\infty  \bigg) =0.
\end{equation}

In the noncritical case $d=3$ the blow-up criterion can be relaxed to 
\begin{equation}

    \P \bigg(\sigma < \infty ,\sup\limits_{t\in [0,\sigma)} \| u(t) \|_{H^1(\sO)} <\infty  \bigg) =0.
\end{equation}

[Theorem t.main of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] Under Assumption~(a.environment of the paper) with $d\ge 2$, $\mathbb{Q}$-almost surely,
	\begin{equation}
		\Bigl|\frac{\ell_X(\lambda)}{\lambda}-\Sigma_X e_1\Bigr|
		\le \lambda^{\beta^*}
		\qquad\text{for every }0<\lambda\le\lambda_0(\omega)\, ,
	\end{equation}
	where $\beta^*=\beta^*(d)\in(0,1/4)$ is a deterministic exponent and $\lambda_0\colon\Omega\to(0,1]$ is a random scale satisfying the tail bound
	\begin{equation}
		\mathbb{Q}\bigl(\lambda_0\le\lambda\bigr)\le C\exp\bigl(-c (\log(1/\lambda))^\sigma\bigr)\qquad\text{for every }\lambda\in(0,1]\, ,
	\end{equation}
	with $C=C(d,\Lambda,r_0)<\infty$, $c=c(d,\Lambda,r_0)>0$, and an exponent $\sigma=\sigma(d,\Lambda,r_0)\in(0,1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 19 of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] For every $\delta_0 >0$ there exist $\delta \leq \delta_0$ and $c>0$ such that the following holds for every $x_0\in D$.
	Suppose that one is given $T,C,\gamma>0$ such that for every $\varepsilon \leq \gamma r_\delta$,
	\begin{align}
		\bbP(X_T \in \sB(y,\varepsilon) \mid X_0 = x_0)\geq C \Area(\sB(y,\varepsilon))  \text{ for every } y \in \cD(\delta). 
	\end{align}
	Then, for $T' \de T + c \min\{1/\kappa^2, 1/\lambda_{\max}^2, \rho^2 \}$ and every measurable $E\subseteq D$,
	\begin{align}
		\bbP(X_{T'} \in E \mid X_0 = x_0)\geq (C/2)\Area(E).
	\end{align}

[Lemma S-lem of arXiv:2604.24914, 'SPDEs with time-independent\\ L\'evy colored noise'] Let $S \in \mathcal{O}_{C}'(\mathbb{R}^d)$ be such that $\int_{\mathbb{R}^d}|\mathcal{F} S(\xi)|^2 \mu(d\xi)<\infty$. Then $S \in \overline{\mathcal{P}}_{d}(\mathbb{R}^d)$, $S * \kappa \in L^2(\mathbb{R}^d)$ and 
\begin{equation}

\int_{\mathbb{R}^d}S(x)X(dx)=\int_{\mathbb{R}^d}(S*\kappa)(x)L(dx) \quad \mbox{in $L^2(\Omega)$.}
\end{equation}

[Proposition c3.11 of arXiv:2603.14447, '\Large \bf Backward doubly stochastic differential equations with and without reflection u'] \sl
			For \(i=1,2\), assume that the parameters \((\xi^i,f^i,g^i)\) satisfy
		\textbf{(A1)}, \textbf{(F1)}, \textbf{(G1)}  and \textbf{(G3)}  with common structural constants, and that \(f^i\) is Lipschitz continuous in \(z\). Assume additionally that \(S^i\) satisfies 
		\textbf{(S1)} and \(S_T^i\leqslant \xi^i\), \(i=1,2\).
		 Let $(Y^i,Z^i,K^i)\in S^2_{\mathbb{F}}([0,T];\mathbb{R})\times L^2_{\mathbb{F}}([0,T];\mathbb{R}^d)\times A^2_{\mathbb{F}}([0,T];\mathbb{R}_+)$  be the unique solution of the following reflected BDSDE:
		\begin{equation*}
			\left\{
			\begin{aligned}
				&	Y^i_t=\xi^i+\int_{t}^{T}f^i(s,Y^i_s,Z^i_s)ds+\int_{t}^{T}g^i(s,Y^i_s,Z^i_s)dB_s+K^i_T-K^i_t-\int_t^TZ^i_sdW_s,\quad\ 0\leqslant t\leqslant T,\\
				&	Y_t^i\geqslant S_t^i\quad\ \hbox{and} \quad\ \int_0^T (Y_s^i-S_s^i)dK_s^i=0.
			\end{aligned}\right.
		\end{equation*}
		If, for any \(t\in [0,T]\),
		\begin{align*}
			\xi^1\leqslant \xi^2,\quad\ S^1_t\leqslant S_t^2,\quad\ f^1(t,Y^2_t,Z_t^2)\leqslant f^2(t,Y^2_t,Z_t^2), \quad\ g^1(t,Y^2_t,Z_t^2)= g^2(t,Y^2_t,Z_t^2),  \quad \hbox{a.s.}, 
		\end{align*}
		\begin{align*}
			\Big( \hbox{alternatively,}\quad~ 
			f^1(t,Y^1_t,Z_t^1)\leqslant f^2(t,Y^1_t,Z_t^1), \quad~ g^1(t,Y^1_t,Z_t^1)= g^2(t,Y^1_t,Z_t^1), \quad \hbox{a.s.}, \Big)
		\end{align*}
		then we have $Y_t^1\leqslant Y_t^2$, \(\forall t\in [0,T]\),  $ \mathbb{P} $-a.s.

[Theorem order_statistic_concentration of arXiv:2606.17425, 'Order statistics for edge eigenvectors of Wigner matrices'] Let $\epsilon > 0$ and choose $J$ to be $\{(\alpha, i, i), 1 \leq i \leq N\}$ for some $\alpha = \alpha(N) < N^{\epsilon/10}$. Let $\mathfrak{c} \in (0, 1]$ be a constant, and denote the cdf of the $\chi^2(1)$-distribution by $F_{\chi^2(1)} : {\mathbb R}_{\geq 0} \to [0, 1]$. The $\mathfrak{c}$-quantile is given by,
	\begin{equation*}
		u^{\star}_{\mathfrak{c}} := F_{\chi^2(1)}^{-1}(1 - \mathfrak{c}). 
	\end{equation*}	
	Then there exists a $\delta > 0$ such that for $\epsilon < \delta$ and sufficiently large $N$, with probability $\geq 1 - N^{-\epsilon/2}$, 
	\begin{equation}
		(N \abs{\inner{u_{\alpha},q_i}}^2)_{(\ceil{ \mathfrak{c}N})} = u^{\star}_{\mathfrak{c}} + O(N^{-\epsilon/4}).

	\end{equation}
	A direct consequence of (equation order_statistic_concentration of the paper) is the following quantitative convergence: With probability $\geq 1 - N^{-\epsilon/4}$, 
	\begin{equation}
		\inf_{\substack{I \subset [[1, N]] \\ \#_{I} = \floor{(1-\mathfrak{c})N}}} \sum_{i \in I} \abs{\inner{u_{\alpha}, q_i}}^2 = \int_{\mathfrak{c}}^1 u^{\star}_{c} \mathop{}\!{d} c + O(N^{-\epsilon/4}).

	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm: main of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] There exists a probability measure $\nu^0$ on $S'(\mathbb T^2)$ and a family of amplitudes corresponding to measurable maps 
\begin{equation}
\mathcal A^\sigma({\Large \boldsymbol{\cdot} }\,\mid {\Large \boldsymbol{\cdot} }\,,{\Large \boldsymbol{\cdot} }\,): C^\infty(M^\sigma) \times S'(\mathbb T^2)\times S'(\mathbb T^2)\rightarrow \mathbb R
\end{equation}
such that the following are satisifed.
\begin{enumerate}
\item[(i)] The boundary measure $\nu^0$	is an admissible boundary law.
\item[(ii)] Let $\varphi_-,\varphi_+$ be i.i.d. sampled according to $\nu^0$. For every $f \in C^\infty(M^\sigma)$, $\mathcal A^\sigma(f \mid \varphi_-,\varphi_+)$ is, up to a multiplicative constant, the limit of unnormalized Laplace transforms $\mathcal Z_T(f \mid \varphi_-\ast \rho_T,\varphi_+\ast \rho_T)$ of the prelimiting $\varphi^4_3$ measures as $T \rightarrow \infty$. 
\item[(iii)] The amplitudes satisfy the gluing property. Almost surely for every $\varphi_-,\varphi_+$ independently sampled according to any admissible boundary law, and for every $f \in C^\infty(M)$,
\begin{equation}
\mathcal A(f\mid \varphi_-,\varphi_+) =  \mathbb E_{\nu^0} \left[ \mathcal A^{-}(f|_{M_-} \mid \varphi_-,\varphi^0) \,  \mathcal A^{+}(f|_{ M_+} \mid \varphi^0,\varphi_+) \right],
\end{equation}
where the field $\varphi^0\sim \nu^0$ is independent from $\varphi_-$ and $\varphi_+$, and $f|_{M_\pm}$ is the restriction of $f$ to $M_\pm$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition {\cite[Proposition 6.2 of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] {EK11Quantum}}]
    \begin{equation}
        U_{n}\big(\frac{H}{2}\big)=\sum_{k\ge 0}\sum_{{{a}}\in \{2,3\}^k}\sum_{l_0+\cdots +l_k=n}V_{l_0}\underline{\Phi_{a_1}V_{l_1}}\cdots\underline{\Phi_{a_k}V_{l_k}},
    \end{equation}
    where the sum ranges over $l_i\ge 0$ for $i=0,\ldots, k$, and 
    $a=(a_1,\ldots ,a_k)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:R_N_derivative_bounds_general of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] For all $z \in F$ and $k\ge k_0$, a.s.\ the conditional law given $\mathcal{F}_{z,k}$ of $\Psi - \lfloor \Psi_{2^{-k}}(z)/(2\lambda) \rfloor 2 \lambda$ restricted to $B_{15 \cdot 2^{-k} / 16}(z)$ is mutually absolutely continuous with respect to the law of $\Psi_{z,k}^0$ restricted to $B_{15 \cdot 2^{-k} / 16}(z)$.  Moreover let $\mathcal{Z}_{z,k}$ (resp.\ $\mathcal{W}_{z,k}$) be the Radon--Nikodym derivative of the former with respect to the latter (resp.\ latter with respect to former).  Then,  for all $p \in \BR$,  there exists a constant $C_{p,M} \in (0,\infty)$ depending only on $p$ and $M$ such that,  a.s.\ on the event $E_{z,k}^M$,  we have that
	\begin{align*}
		&\BE\!\left[ \mathcal{Z}_{z,k}(\Psi_{z,k}^0|_{B_{15 \cdot 2^{-k} / 16}(z)})^p \mid \mathcal{F}_{z,k} \right] \leq C_{p,M}\\
		&\BE\!\left[  \mathcal{W}_{z,k}( (\Psi  - \lfloor \Psi_{2^{-k}}(z)/(2\lambda) \rfloor 2 \lambda) |_{B_{15 \cdot 2^{-k} / 16}(z)})^p \mid \mathcal{F}_{z,k} \right] \leq C_{p,M}.
	\end{align*}

[Thm LLN of arXiv:2508.07099, 'The Maki-Thompson model with random awareness'] Suppose the MT--RA model with initial condition $x^0$ such that $\sum_{l=1}^{\infty}(1+q_l)x_l^0>1$. Then $\lim_{n\to\infty}\tau_n=\tau_\infty\in(0,\infty)$ almost surely. Moreover,
        \begin{equation*}
          \frac{1}{n}(Y^n(\tau_n),X_1^n(\tau_n),X_2^n(\tau_n),\dots)\to(0,x_{1,\infty},x_{2,\infty},\dots),  
        \end{equation*}
        as $n$ goes to infinity, where 
        \begin{eqnarray*}
            x_{1,\infty}&=&x_1^0\exp(-\zeta_\infty),
        \end{eqnarray*}
        and, for $\ell\geq2$,
        \begin{equation}
        \begin{array}{rcl}

            x_{\ell,\infty}&=&\exp(-\zeta_\infty)\bigg[x_1^0\frac{(\zeta_\infty)^{\ell-1}}{(\ell-1)!}\Big(1-\sum_{i=0}^{\ell-1}p_i\Big)\\
        &&+\displaystyle\sum_{k=2}^{\ell}\frac{x_k^0}{(\ell-k)!}(\zeta_\infty)^{\ell-k}\prod_{i=k}^{\ell-1}(1-q_i)\bigg],

        \end{array}
        \end{equation}
        where $\zeta_\infty$ is the unique positive solution to
        \begin{equation}
            \begin{array}{c}
            \zeta_\infty=\displaystyle(1+q_1)x_1^0\gamma(1,\zeta_\infty)+\sum_{\ell=2}^{\infty}(1+q_\ell)\bigg[x_1^0\frac{\gamma(\ell,\zeta_\infty)}{\Gamma(\ell)}\Big(1-\sum_{i=0}^{\ell-1}p_i\Big)\\
            +\displaystyle\sum_{k=2}^{\ell}x_k^0\frac{\gamma(\ell-k+1,\zeta_\infty)}{\Gamma(\ell-k+1)}\prod_{i=k}^{\ell-1}(1-q_i)\bigg].
            \end{array}
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 16 of arXiv:2607.11283, 'Markov Properties of $k$-Record Processes via Order Statistics'] Assume that $F$ is continuous. Then the process $(R_n^{(k)})_{n\ge1}$ is a time-homogeneous Markov chain. Its transition kernel $K_k$ is given by
\begin{equation}

K_k(x,A)
=
\int_{A\cap(x,\infty)}
\frac{k\,(1-F(y))^{k-1}}{(1-F(x))^k}\, dF(y),
\qquad A\in\mathcal{B}(\mathbb{R}).
\end{equation}

