[Lemma lem:AFEbds_S of arXiv:2412.05491, 'Near-critical and finite-size scaling for \\ high-dimensional lattice trees and animals'] Let $d>2$ and $L \ge L_2$.
There is a $\delta_2 = \delta_2(L) > 0$ such that
for all $z \in [1 - \delta_2, 1)$,
for all $m \in [0, \frac{1}{2} m_S(z) \wedge \frac{1}{2} m_0({\mu_z}) ]$,
for all multi-indices $\gamma$ with $\abs \gamma \le d-2$,
and for all $q_1, q_2$ with
\begin{equation}
    \frac{ \abs \gamma } d < q_1^{-1} < 1,
    \qquad
    \frac{ 1 + \abs \gamma } d < q_2^{-1} < 1,
\end{equation}
the norm inequalities
\begin{equation}  
\biggnorm{ \frac{ \nabla^\gamma \hat B_{\mu_z} ^{(m)} }{ \hat B_{\mu_z} ^{(m)} } }_{q_1}, \;
\biggnorm{ \frac{ \nabla^\gamma \hat A_z ^{(m)} }{ \hat A_z ^{(m)} } }_{q_1}, \;
\biggnorm{ \frac{ \nabla^\gamma \hat E_z ^{(m)} }{ \hat B_{\mu_z} ^{(m)} \hat A_z ^{(m)} } }_{q_2}
\lesssim 1
\end{equation}
hold, with constants independent of $z,m,L$.

[Theorem thm:mr of arXiv:2605.26048, 'Classification of the eternal solutions and multiple coalescing shocks in the KPZ fixed po'] For almost-every $\omega$, the mapping $\mathcal{H}_\omega[\varphi] := W\star \varphi$ is a homeomorphism $(\Phi_\omega,\mathcal T_{\Phi_\omega}) \to (\mathcal{B}_\omega,\mathcal T_{\mathcal{B}_\omega})$ that satisfies
    \begin{equation} 
    \mathcal{H}[\varphi_1] \vee \mathcal{H}[\varphi_2] = \mathcal{H}[\varphi_1 \vee \varphi_2],\quad \forall \varphi_1,\varphi_2 \in \Phi,
    \end{equation}
    and whose inverse is given by
    \begin{equation} 
    \mathcal{H}^{-1}[b](\xi) = \inf_{(x,t)\in\mathbb{R}^2}\{b(x,t)-W^\xi(0,0;x,t)\},\quad \forall\; b \in \mathcal{B}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:s-hol of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] A function $F$ defined on a subset of $\diamondsuit(G)$ is called $s$-holomorphic if, for each pair of adjacent quads $z, z’ \in \diamondsuit(G)$ separated by the edge $[\mathcal{S}(v^\circ(c)); \mathcal{S}(v^\bullet(c))]$ of $\mathcal{S}$ attached to the corner $c$, we have
\begin{equation}

\textrm{Pr}[F(z), \eta_c \mathbb{R}] = \textrm{Pr}[F(z’), \eta_c \mathbb{R}].
\end{equation}

[Lemma lem:gyration_derivative of arXiv:2508.18807, '{\bf Critical long-range percolation I: High effective dimension}'] Suppose that at least one of the four hypotheses of (equation HD+ of the paper) holds. For each $u\in \mathbb R^d$ we have that
\begin{equation*}

 \frac{d}{dr} \mathbb E_{\beta_c,r} \left[\sum_{x\in K} \langle x,u\rangle^2 \right]
\sim  \frac{2 \alpha}{r} \mathbb E_{\beta_c,r} \left[\sum_{x\in K} \langle x,u\rangle^2 \right] + \frac{\alpha^2}{\beta_c} r^{2+\alpha-1} \int_{B} \langle y,u\rangle^2 \dif y
\end{equation*}

as $r\to \infty$. Moreover, in Cases 1, 2, and 3 all relevant errors are logarithmically integrable. (Proof in the paper; no proof environment follows the statement in the TeX.)

