body:
[Lemma 6 of arXiv:2607.23585, 'The one-period Kyle model has one equilibrium'] Under the hypothesis of Lemma~\ref{lem:foc}, for every $y\in\R$, the
	functions $\id$ and $\phi$ lie in $L^2(\pi_y)$. The function $P$ is
	continuously differentiable, with
	\begin{equation}
		P'(y)=\Cov_{\pi_y}(\id,\phi)>0,\qquad\text{for every }y\in\R\,.

	\end{equation}
	Consequently,
	\begin{equation}
		F'(x)>0,\qquad\text{for every }x\in\R\,.

	\end{equation}
	Thus, $P$ and $F$ are strictly increasing. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 32 of arXiv:2606.12670, 'The censored stochastic six-vertex model and parabolic Kazhdan--Lusztig $R$-polynomials'] Consider the same setup as in Theorem~\ref{thm:labeling}, except there are only $N$ second-class particles.
    Let $\dots<Z_t(N-1)<Z_t(N)$ be the ordered positions of the second- and third-class particles and consider the labeling process
    \begin{equation}
    \xi_t(k) = 
    \begin{cases} 
    1 & \text{if $k\leq N$ and ${Z}_t(k)$ contains a second-class particle} \\ 
    0 & \text{if $k\leq N$ and ${Z}_t(k)$ contains a third-class particle, } \\
    1 &\text{if $k> N$}.\end{cases}
    \end{equation}
    Then for any time $t$, the law of $\xi_t$ is dominated by $\pi^N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:ConvBd of arXiv:2506.06559, 'Bi-infinite incipient cluster in high dimensions'] {HaraHofstSlade03}}}]
Suppose $a\ge b>0$ and $f,g\colon \mathbb Z^d\to\mathbb R$ satisfy $f(x)\le c_1|x|^{-a}$ and $g(x)\le c_2|x|^{-b}$ for constants $c_1,c_2>0$. 
Then there exists $c_3>0$ such that 
\begin{equation}
	(f\ast g)(x)\le c_3
	\begin{cases}
		|x|^{-b}\quad&\text{ if }a>d,\\
		|x|^{d-(a+b)}\quad&\text{ if }a<d, a+b>d.
	\end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfntn 5 of arXiv:2608.31054, 'Revisiting Picard's proof of the Picard--Weber--Weck selection theorem'] A set $\Omega \subseteq \R^d$ is a \textbf{weak Lipschitz domain} if the boundary $\Gamma = \partial \Omega$ is a Lipschitz submanifold. That is, there exists a finite open cover $U_1, \ldots, U_K \subseteq \R^d$ of $\Gamma$ and maps $\varphi_k : U_k \rightarrow (0,1)^{d-1}\times (-1,1)$ such that for $k \in \{ 1,\ldots, K\}$, $\varphi_k$ is bi-Lipschitz, bounded, regular, and satisfies
    \begin{align*}
        \varphi_k(U_k \cap \Omega ) = (0,1)^{d} =: Q.
    \end{align*}
    That is, $\varphi_k \in C^{0,1}_{b}(\overline{U_k}, [0,1]^{d-1}\times [-1,1])$, $\varphi_k^{-1} \in C^{0,1}_{b}([0,1]^{d-1}\times [-1,1], \overline{U_k})$, and there exists $c>0$ such that the Jacobian $J_{\varphi_k} := \Grad(\varphi_k)$ of $\varphi_k$ satisfies
    \begin{align*}
        \det{J_{\varphi_k}(x)} \geq c \quad \text{for $a.e.$ $x \in U_k$.}
    \end{align*}

[Proposition prop:boundedness of arXiv:2609.02710, 'Asymptotic Mean Value Laplacian\\ on equiregular sub-Riemannian manifolds'] For every $K\Subset O$, there are constants $C,h_K>0$ such that
\begin{equation}
  \widehat B_x(1-Ch)\subset B_{x,h}
  \subset\widehat B_x(1+Ch),
  \qquad x\in K,\quad 0<h<h_K,
\end{equation}
and
\begin{equation}
  \left|\int_{B_{x,h}}\xi_i\,\,d\xi\right|\le Ch,
  \qquad 1\le i\le k.
\end{equation}

[Lemma 8 (Barrier is not crossed a second time) of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] Adopt the notion and assumptions of Lemma \ref{lem: W_si_nice} and assume that the event from \eqref{eq:SlowIce} occurs.
	Additionally, assume that
	\begin{align}
		\alpha + \beta < 1/5 - \gamma\ \text{ and }\ (1-2\delta)\beta -2\gamma - 12 \delta \geq 4\delta.
	\end{align}
	Then, it holds with $T\de \inf\{t \geq 0: s_i(\Lc{i}_t) \neq s_i(0) \}$ that
	$
		\Lc{i}_{ r_\delta^2} \leq \Lc{i}_{T} +  \beta r_\delta.
	$
	In particular,
	\begin{align}
		s_i(\Lc{i}_t) = s_i(\Lc{i}_{T}) \text{ for every } t\in [T,  r_\delta^2].
	\end{align}

[Defi combs of arXiv:2609.02346, 'Regularised double shuffle relations for planar \AZVs{}'] With these notations, we notice that all trees $t$ admit respectively a \emph{right comb representation} and a \emph{left comb representation}:
	\begin{align}
		t&=\decombright{F_1}{F_2}{F_k}{\omega_1}{\omega_2}{\omega_{k}}{\omega_{k+1}}
		& \text{ and } &&  t=\decombleft{F_{k+2}}{F_{k+3}}{F_{k+l+1}}{\omega_{k+2}}{\omega_{k+3}}{\omega_{k+l+1}}{\omega_{k+l+2}},
	\end{align}

	where $F_1,\dots,F_k$ and $F_{k+2},\dots, F_{k+l+1}$ are forests, possibly empty . In the following, we will consider that there exist two further forests $F_{k+1}$ and $F_{k+l+2}$, both empty and respectively grafted to the nodes decorated by $\omega_{k+1}$ and $\omega_{k+l+2}$.

