[Definition c-opt-gen of arXiv:2509.23086, 'On Optimal Markovian Couplings of L\'evy Processes'] Let $\Pi$ be a state space, $c:\Pi^2\to[0,\infty)$ be a cost function, 
and let \( \mathcal{A}, \mathcal{B} \in \mathcal{G}(\Pi) \) be two Feller generators on \( \Pi \). The \emph{Markovian transport derivative} is the function \( \theta_c(\cdot, \cdot; \mathcal{A}, \mathcal{B}) : \Pi^2 \to [-\infty, \infty] \) defined by
\begin{align}
    \theta_c(x, y; \mathcal{A}, \mathcal{B}) := \inf_{\mathcal{J} \in \Gamma(\mathcal{A}, \mathcal{B})} (\mathcal{J}^- c)(x, y),
\end{align}
where $\mathcal{J}^-$ is the lower generator given in Definition (def:lower-gen of the paper). We say that \( \mathcal{J}_* \in \Gamma(\mathcal{A}, \mathcal{B}) \) is a \emph{\( c \)-optimal coupling} of \( \mathcal{A} \) and \( \mathcal{B} \) if $c\in \bar D(\mathcal{J}_*)$ and it holds for all $(x,y)\in\mathbb R^{2d}$:
\begin{align}
    (\mathcal{J}_* c)(x, y) = \theta_c(x, y; \mathcal{A}, \mathcal{B}).
\end{align}

[Lemma le:projection-geometry of arXiv:2608.19358, 'An optimal Poincaré inequality\\for the complex Ginibre log-gas'] The following properties hold.
  \begin{enumerate}
  \item
    $\mathcal{H}_n^{\mathrm{div},0}$ and
    $\overline{\mathcal{H}_n^{\mathrm{div},0}}$ are orthogonal.
  \item For every symmetric $f\in L^2(\mu_n)$,
    \begin{equation}
      \|Pf\|_{L^2(\mu_n)}^2+\|Qf\|_{L^2(\mu_n)}^2
      \leq
      \|f\|_{L^2(\mu_n)}^2+\|P_0f\|_{L^2(\mu_n)}^2.
    \end{equation}
  \item If $f\in L^2(\mu_n)$ is real-valued, symmetric, and centered, then
    $h=Pf$, its pointwise complex conjugate $\overline h$, and
    $r=f-h-\overline h$, are three pairwise orthogonal functions in $L^2(\mu_n)$, and
    \begin{align}
      \|f\|_{L^2(\mu_n)}^2
      &=2\|h\|_{L^2(\mu_n)}^2+\|r\|_{L^2(\mu_n)}^2,
      \\
      \operatorname{dist}_{L^2(\mu_n)}
      \bigl(f,\mathcal{H}_n^{\mathrm{div}}\bigr)^2
      &=\frac{1}{2}\|f\|_{L^2(\mu_n)}^2
        +\frac{1}{2}\|r\|_{L^2(\mu_n)}^2.

    \end{align}
    In particular, we have the half-distance estimate 
    \begin{equation}
      \operatorname{dist}_{L^2(\mu_n)}
      \bigl(f,\mathcal{H}_n^{\mathrm{div}}\bigr)^2
      \geq\frac{1}{2}\|f\|_{L^2(\mu_n)}^2.
    \end{equation}
  \end{enumerate}

[Corollary LemmaCondExpII of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Let $(u_{n})_{n \in \mathbb{N}}$ be any admissible ordering of $\mathcal{I}$ and let $\varphi$ be an $h$-dependent descendant characteristic, for some $h \in \mathbb{N}_{0}$, satisfying (C1 of the paper)-(C2 of the paper). Then, for $t \in \mathbb{R}$ and $k=0, \dots, h+1$, 
\begin{align}  
\mathbb{E}[\varphi_{u_{1}}(t-S(u_{1})) \mid \mathcal{G}^{(k)}_{0}] \stackrel{a.s.}{=}  \varphi^{(0)}_{u_{1}}(t-S(u_{1})),
\end{align} 
\noindent while for $i \geq 2$,
\begin{align} 
\mathbb{E}[\varphi_{u_{i}}(t-S(u_{i})) \mid \mathcal{G}^{(k)}_{i-1}] \stackrel{a.s.}{=}  \varphi^{(k)}_{u_{i}}(t-S(u_{i})).
\end{align}

[Lemma 11 (Uniform bounds for the unweighted partial traces) of arXiv:2606.24090, 'Sparsity-adaptive concentration inequalities for random polynomials'] Let $I\subseteq[d]$, $|I|=l$, let $\varepsilon\in\{0,1\}^l$, and let
$T_{I,\varepsilon}A$ be defined by \eqref{eq:B_T_I_epsilon_A}. Let
$I_2\subseteq[2l]$, set $q:=|I_2|$, and let
$\mathcal J\in\Pi([2l]\setminus I_2)$ with
$\kappa:=|\mathcal J|$. Then, uniformly in the fixed coordinates $j_{I_2}$,
\begin{equation}
    \bigl\|
    (T_{I,\varepsilon}A)_{j_{I_{2}^{c}}}
    \bigr\|_{\mathcal J}
    \le
    n^{d-(\kappa+q)/2}\|A\|_{\mathsf L,\mathsf R}.
\end{equation}
Moreover, when $I_2=\varnothing$,
\begin{equation}
    \|T_{I,\varepsilon}A\|_{\mathcal J}
    \le
    n^{(d-l)/2}\|A\|_{[2d]}.
\end{equation}

