[Lemma 25 of arXiv:2605.09706, 'A dyadic construction of a three-dimensional attractive point interaction Markov family'] For the function $P_t(r)$ defined in~\eqref{DefFreeHeat3d}, the following hold.
\begin{enumerate}[(i)]
    \item For every \(s,t>0\) and every \(a,b\in\R\),
\begin{align} 
\int_{\R}
P_s(a-r)\,P_t(r-b)\,dr
=
\frac{s+t}{4\pi st}\,P_{s+t}(a-b).
\end{align}

    \item Let $s>0$, $x\in\R^3\setminus\{0\}$, and let $F:(0,\infty)\to\R$ be measurable such that all integrals below are finite. Then
\begin{align} 
\int_{\R^3}
P_s(x,y)\,\frac{F(|y|)}{|y|}\,dy
&=
\frac{4\pi s}{|x|}
\int_0^\infty
\Bigl(
P_s(r-|x|)-P_s(r+|x|)
\Bigr)\,F(r)\,dr.
\end{align}
\end{enumerate}

